INSERT INTO `games` (`id`, `text`, `date`, `userID`, `views`, `author`, `title`, `description`, `private`, `allowDownload`, `tags`) VALUES
(2, '<br><div style=\"color:#0ff;font-family: play;font-size: 24px;line-height: 1em;background:linear-gradient(#0246,#0000);border-radius: 30px;padding: 20px;\">\n<center>\n  <span style=\"font-size: 1.5em;\">Tetris - The Next Generation</span><br>\n  Multiplayer-online, or single player<br>play with up to 4 players at a time<br>\n  Two themes to choose from<br><br>\n  <a style=\"background: #284;color: #4f8; padding: 5px;text-shadow: 2px 2px 2px #000;padding-left: 20px;padding-right: 20px; border-radius: 10px;\" href=\"http://whr.rf.gd/b/games/tetris\" target=\"_blank\">play now</a><br><br>\n</center>\n<img style=\"width:70%;max-width: 800px\" onclick=\"window.open(\'http://whr.rf.gd/b/games/tetris\',\'_blank\')\" src=\"https://srmcgann.github.io/assets/1r6PnM.jpg\">\n</div>', '2022-04-09 14:26:42', 145, 224, 'whitehot robot', 'Tetris - The Next Generation', 'single player / multiplayer online', 0, 0, '#multiplayer'),
(4, '<br><div style=\"color:#0ff;font-family: play;font-size: 24px;line-height: 1em;background:linear-gradient(#0246,#0000);border-radius: 30px;padding: 20px;\">\n<center>\n  <span style=\"font-size: 1.5em;\">Sudoku</span><br>just sudoku - it works!<br><br>\n  <a style=\"background: #284;color: #4f8; padding: 5px;text-shadow: 2px 2px 2px #000;padding-left: 20px;padding-right: 20px; border-radius: 10px;\" href=\"http://whr.rf.gd/b/games/sudoku\" target=\"_blank\">play now</a><br><br>\n</center>\n<img style=\"width:50%;max-width: 500px;\" onclick=\"window.open(\'http://whr.rf.gd/b/games/sudoku\',\'_blank\')\" src=\"https://srmcgann.github.io/assets/1MBaK6.jpg\">\n</div>', '2022-04-09 14:26:42', 145, 223, 'whitehot robot', 'Sudoku', 'classic sudoku - works on mobile / laptop / desktop', 0, 0, '#sudoku'),
(5, '<br><div style=\"color:#0ff;font-family: play;font-size: 24px;line-height: 1em;background:#0246;border-radius: 30px;padding: 20px;\">\n<center>\n  <span style=\"font-size: 1.5em;\">Rufus Game</span><br>chase the skunk!</center><center>keep it away from the flowers</center><center>before it eats them all!<br><br>\n  <a style=\"background: #284;color: #4f8; padding: 5px;text-shadow: 2px 2px 2px #000;padding-left: 20px;padding-right: 20px; border-radius: 10px;\" href=\"http://whr.rf.gd/b/games/rufus_game\" target=\"_blank\">play now</a><br><br>\n</center>\n<img style=\"width:50%;max-width: 800px;\" onclick=\"window.open(\'http://whr.rf.gd/b/games/rufus_game\',\'_blank\')\" src=\"https://gummier-fish.000webhostapp.com/uploads/12M6Lx.jpg\">\n</div>', '2022-04-09 14:26:42', 145, 19, 'whitehot robot', 'Rufus Game', 'chase the skunk!', 0, 0, '#mouse #touch #mobile'),
