INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600000, 'https://srmcgann.github.io/assets/1tgfHk.mp4', 'song = \'https://twilightparadox.com/reflecting%20pool.mp3\'\nvid = \'https://twilightparadox.com/base%20videos/awakening%20base.mp4\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\n\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(!t){\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    Rn=Math.random\n  }\n\n  if(vidplaying){\n    x.globalAlpha=.5\n    x.drawImage(bgvid,0,0,w=c.width,1080)\n    x.globalAlpha=1\n    x.fillStyle=\'#0003\'\n    x.fillRect(0,0,w=c.width,w)\n  }else{\n    x.fillStyle=\'#0004\'\n    x.fillRect(0,0,w=c.width,w)\n  }\n\n  Rl=t/6,Pt=S(t/2)/2,Yw=S(t/1.5)/1.5\n  oX=0,oY=0,oZ=4+S(t/1.5)/1.75\n  mt=S(t/4)\n  \n  if(!t){\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    x.lineJoin=x.lineCap=\'round\'\n    sd=6\n    iBr=2,iPv=.006,iPsv=.025,iPc=8,iPs=150,iRm=iPv*65,iRsm=iPsv*2.75,iPbv=.02\n    B=Array(sd).fill().map((v,i)=>{\n      return [S(p=Math.PI*2/sd*i)*iBr,C(p)*iBr,0]\n    })\n    P=Array(iPc).fill().map(v=>{return {X:0,Y:0,Z:0,vx:S(p=Rn()*Math.PI*2)*iPv,vy:C(p)*iPv,vz:0,theta:0,P:[]}})\n  }\n\n  P.map((v,j)=>{\n    x3_=v.X+=v.vx\n    y3_=v.Y+=v.vy\n    z3_=v.Z+=v.vz\n    d=Math.hypot(v.vx,v.vy,v.vz)\n    vxd=v.vx/d*iRm\n    vyd=v.vy/d*iRm\n    vzd=v.vz/d*iRm\n    x4_=x3_+vxd\n    y4_=y3_+vyd\n    z4_=z3_+vzd\n    B.map((q,i)=>{\n      if(i){\n        X=B[i-1][0]\n        Y=B[i-1][1]\n        Z=0\n      }else{\n        X=B[l=B.length-1][0]\n        Y=B[l][1]\n        Z=0\n      }\n      R(mt,0,0,0)\n      x2_=X,y2_=Y\n      X=q[0],Y=q[1],Z=0\n      R(mt,0,0,0)\n      x1_=X,y1_=Y\n      if(a=I(x1_,y1_,x2_,y2_,x3_,y3_,x4_,y4_)){\n        u=((x3_-x1_)*(x2_-x1_)+(y3_-y1_)*(y2_-y1_))/Math.hypot(x2_-x1_,y2_-y1_)\n        mx=u*(x2_-x1_)\n        my=u*(y2_-y1_)\n        v.vx+=S(p=Math.atan2(mx-v.X,my-v.Y)-Math.PI/2)/80\n        v.vy+=C(p)/80\n      }\n    })\n    d=Math.hypot(v.vx,v.vy)\n    v.vx/=d\n    v.vy/=d\n    v.vx*=iPv\n    v.vy*=iPv\n    for(m=2;m--;)v.P.push([v.X,v.Y,v.Z,S(p=v.theta+=Math.PI/sd*(1+j==3?5:1+j)+S(t/1.5)/16)*iPsv,C(p)*iPsv,0,iPs])\n    v.P.map(v=>{\n\n      x3_=v[0]\n      y3_=v[1]\n      z3_=v[2]\n      d=Math.hypot(v[3],v[4],v[5])\n      vxd=v[3]/d*iRsm\n      vyd=v[4]/d*iRsm\n      vzd=v[5]/d*iRsm\n      x4_=x3_+vxd\n      y4_=y3_+vyd\n      z4_=z3_+vzd\n      bnc=0\n      B.map((q,i)=>{\n        if(i){\n          X=B[i-1][0]\n          Y=B[i-1][1]\n          Z=0\n        }else{\n          X=B[l=B.length-1][0]\n          Y=B[l][1]\n          Z=0\n        }\n        R(mt,0,0,0)\n        x2_=X,y2_=Y\n        X=q[0],Y=q[1],Z=0\n        R(mt,0,0,0)\n        x1_=X,y1_=Y\n        if(!bnc&&(a=I(x1_,y1_,x2_,y2_,x3_,y3_,x4_,y4_))){\n          bnc=0\n          u=((x3_-x1_)*(x2_-x1_)+(y3_-y1_)*(y2_-y1_))/Math.hypot(x2_-x1_,y2_-y1_)\n          mx=u*(x2_-x1_)\n          my=u*(y2_-y1_)\n          v[3]+=S(p=Math.atan2(mx-v[0],my-v[1])-.8)/80*(d=.25+Math.hypot(v[3],v[4])*100)\n          v[4]+=C(p)/100*d\n        }\n      })\n      d=Math.hypot(v[3],v[4])\n      v[3]/=d\n      v[4]/=d\n      v[3]*=iPsv\n      v[4]*=iPsv\n\n      X=v[0]+=v[3]\n      Y=v[1]+=v[4]\n      Z=v[2]+=v[5]\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        x.beginPath()\n        x.arc(...Q(),Math.min(99,(v[6]-=1.5)/Z/Z),0,7)\n        x.fillStyle=\'#1f84\'\n        x.fill()\n      }\n    })\n    v.P=v.P.filter(v=>v[6]>10)\n  })\n\n  B.map((v,i)=>{\n    x.beginPath()\n    if(i){\n      X=B[i-1][0]\n      Y=B[i-1][1]\n      Z=B[i-1][2]\n    }else{\n      X=B[l=B.length-1][0]\n      Y=B[l][1]\n      Z=B[l][2]\n    }\n    R(mt,0,0,0)\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R(mt,0,0,0)\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    x.strokeStyle=\'#84f6\'\n    x.lineWidth=50/Z\n    x.stroke()\n  })  \n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  x.lineCap=x.lineJoin=\'round\'\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'html,body{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg,#000,#024);\n}\n\n#c{\n  width:100%;\n  height:100%;\n}', '<canvas id=c></canvas>\n\n', 'Reflecting Pool', 1, 'cantelope', '2022-04-09 14:26:46', '', 23, 'https://code.dweet.net/thumbs/1e455650fe4ca82c5511d363efcd2607.jpg', 16, 0),
(600001, 'https://srmcgann.github.io/assets/HHWuJ.mp4', 'song = \'https://twilightparadox.com/march%20of%20the%20cloud%20people.mp3\'\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    t=playing=go=0\n    window.onclick=()=>{if(!playing)mp3.play()}\n    rsz()\n    Draw=()=>{\n\n      if(!t){\n        focal=900\n        mp3 = new Audio()\n        mp3.loop=true\n        mp3.onplaying=()=>{playing=true}\n        mp3.oncanplay=()=>{go=true;if(!playing)mp3.play()}\n        mp3.src=\'https://twilightparadox.com/march of the cloud people.mp3\'\n        R=($1,$2,$3,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=ogx+S(p=A(ogx-X,ogz-Z)+Yw)*(d=H(ogx-X,ogz-Z))\n          Z=ogz+C(p)*d\n          Y=ogy+S(p=A(ogy-Y,ogz-Z)+Pt)*(d=H(ogy-Y,ogz-Z))\n          Z=ogz+C(p)*d\n          X=ogx+S(p=A(ogx-X,ogy-Y)+Rl)*(d=H(ogx-X,ogy-Y))\n          Y=ogy+C(p)*d\n          if(m)X+=oX,Y+=oY,Z+=oZ\n        }\n        Q=()=>[c.width/2+X/Z*focal,c.height/2+Y/Z*focal]\n  }\n    x.fillStyle=\'#0004\'\n    x.fillRect(0,0,w=c.width,w)\n\n  if(!t && typeof firstRun == \'undefined\'){\n    firstRun=0,w=c.width,Rn=Math.random\n    imgs=[\"https://twilightparadox.com/flowers/IMG_0461.JPG\",\"https://twilightparadox.com/flowers/IMG_0462.JPG\",\"https://twilightparadox.com/flowers/IMG_0463.JPG\",\"https://twilightparadox.com/flowers/IMG_0464.JPG\",\"https://twilightparadox.com/flowers/IMG_0465.JPG\",\"https://twilightparadox.com/flowers/IMG_0466.JPG\",\"https://twilightparadox.com/flowers/IMG_0467.JPG\",\"https://twilightparadox.com/flowers/IMG_0468.JPG\",\"https://twilightparadox.com/flowers/IMG_0469.JPG\",\"https://twilightparadox.com/flowers/IMG_0470.JPG\",\"https://twilightparadox.com/flowers/IMG_0471.JPG\",\"https://twilightparadox.com/flowers/IMG_0472.JPG\",\"https://twilightparadox.com/flowers/IMG_0474.JPG\",\"https://twilightparadox.com/flowers/IMG_0475.JPG\",\"https://twilightparadox.com/flowers/IMG_0477.JPG\",\"https://twilightparadox.com/flowers/IMG_0478.JPG\",\"https://twilightparadox.com/flowers/IMG_0479.JPG\",\"https://twilightparadox.com/flowers/IMG_0480.JPG\",\"https://twilightparadox.com/flowers/IMG_0481.JPG\",\"https://twilightparadox.com/flowers/IMG_0482.JPG\",\"https://twilightparadox.com/flowers/IMG_0483.JPG\"]\n\n    imgs=imgs.map((v,i)=>{\n      img = new Image()\n      img.src = v\n      img.addEventListener(\'load\', ()=>imgs[i].state=1)\n      return {img,state:0}\n    })\n    P=[]\n  }\n  \n  freq=60*.05\n  \n  if(!(imgs.filter(v=>!v.state).length) &&\n     !((t*60|0)%freq)){\n    if(typeof ci == \'undefined\') ci=0\n    if(typeof simg !== \'undefined\'){\n      bsimg=simg\n      simg=imgs[ci%imgs.length].img\n    }else{\n      bsimg=simg=imgs[ci%imgs.length].img\n    }\n    ia=w/simg.width\n    ib=1080/simg.height\n    if(ia>ib){\n      X=c.width/2-simg.width*ia/2\n      Y=c.height/2-simg.height*ia/2\n      a=ia\n    }else{\n      X=c.width/2-simg.width*ib/2\n      Y=c.height/2-simg.height*ib/2\n      a=ib\n    }\n    ci++\n  }\n  \n  if(typeof simg !== \'undefined\'){\n    x.globalAlpha=1\n    x.drawImage(simg,X,Y,simg.width*a,simg.height*a)\n    \n    iR=c.width/1.5,iV=7,sql=.15,iS=20\n    for(m=8;m--;)P=[...P,[c.width/2+S(p=Math.PI*2*Rn())*iR,c.height/2+C(p)*iR*(c.height/c.width),-S(p)*iV,-C(p)*iV,iS]]\n    \n    x.globalAlpha=Math.max(0,S(Math.PI/2+Math.PI*2/freq*(t*60|0)))\n    if(typeof bsimg !== \'undefined\'){\n      if((t*60|0)%freq<freq/2){\n        x.drawImage(bsimg,X,Y,bsimg.width*a,bsimg.height*a)\n      }else{\n        x.drawImage(simg,X,Y,simg.width*a,simg.height*a)\n      }\n    }else{\n      x.fillRect(0,0,w,w)\n    }\n    x.globalAlpha=1\n    P.map((v,i)=>{\n      aX=v[0]+=v[2]=S(p=Math.atan2(v[2],v[3])+(Rn()-.5)*sql)*iV\n      aY=v[1]+=v[3]=C(p)*iV\n      x.beginPath()\n      x.arc(aX,aY,Math.min(180,((v[4]/=1.01)+1)**2.65/26),0,7)\n      x.fillStyle=`hsla(${360/P.length*i+t*200},99%,${52+Math.hypot(c.width/2-aX,c.height/2-aY)/iR*60}%,${Math.hypot(c.width/2-aX,c.height/2-aY)/iR/3}`\n      x.fill()\n    })\n    P=P.filter(v=>v[4]>2)\n  }\n\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'March of the Cloud People', 1, 'cantelope', '2022-04-09 14:26:46', '', 31, 'https://code.dweet.net/thumbs/5b4ee49bb4ef97ad8696c45813a6ee18.jpg', 22, 0),
(600002, 'https://srmcgann.github.io/assets/1ohLFf.mp4', 'song = \'https://twilightparadox.com/seraphim.mp3\'\nvid = \'\'//\'https://twilightparadox.com/base%20videos/awakening%20base.mp4\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w),h=700\n  R=(Rl,Pt,Yw)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d}\n  Q=q=>[c.width/2+X/Z*h,c.height/2+Y/Z*h]\n  Rn=Math.random\n\n  Rl=0,Pt=C(t/2.5)/60,Yw=S(t)/50\n  oX=0,oY=0,oZ=10\n  cl=8/4,rw=32/4\n  iR=1,mSr=2,iTc=12,iTl=.25,sd=8\n\n  if(!t){\n    x.lineCap=x.lineJoin=\'round\'\n    P=[...Array(cl|0).fill().map((v,j)=>{\n      b=[]\n      for(m=0;m<iTc;m++){\n        s=iR-(iR/(iTc-1)*m)\n        a=[]\n        scl=rw-(rw/cl*j)\n        for(k=scl|0;k--;){\n          a = [...a, Array(sd).fill().map((v,i)=>{\n            X=S(p=Math.PI*2/sd*i)*s\n            Y=C(p)*s\n            Z=mSr+((m*iTl)**.65)*2\n            R(0,p2=Math.PI/2/cl*j,p1=Math.PI*2/scl*k)\n            return [X,Y,Z,0,0]\n          })\n              ]\n        }\n        b=[...b, a]\n      }\n      return b\n    }),\n       ...Array((cl-1)|0).fill().map((v,j)=>{\n         b=[]\n         for(m=0;m<iTc;m++){\n           s=iR-(iR/(iTc-1)*m)\n           a=[]\n           scl=rw-(rw/cl*(j+1))\n           for(k=scl|0;k--;){\n             a = [...a, Array(sd).fill().map((v,i)=>{\n               X=S(p=Math.PI*2/sd*i)*s\n               Y=C(p)*s\n               Z=mSr+((m*iTl)**.65)*2\n               R(0,p2=-Math.PI/2/cl*(j+1),p1=Math.PI*2/scl*k)\n               return [X,Y,Z,0,0]\n             })\n                 ]\n           }\n           b=[...b, a]\n         }\n         return b\n       })]\n  }\n\n  x.strokeStyle=\'#4f84\'\n  P.map(v=>{\n    v.map((v,n,b)=>{\n      v.map((v,i,a)=>{\n        x.beginPath()\n        v.map((v,j)=>{\n          X=v[0]\n          Y=v[1]\n          Z=v[2]\n          if(n){\n            if(Math.abs(v[3]-b[n-1][i][j][3])>=Math.PI){\n              if(v[3]<b[n-1][i][j][3]){\n                v[3]+=Math.PI*2\n              }else{\n                v[3]-=Math.PI*2\n              }\n            }\n            if(Math.abs(v[4]-b[n-1][i][j][4])>=Math.PI){\n              if(v[4]<b[n-1][i][j][4]){\n                v[4]+=Math.PI*2\n              }else{\n                v[4]-=Math.PI*2\n              }\n            }\n            p1=v[3]+=(b[n-1][i][j][3]-v[3])/(1+n/3)\n            p2=v[4]+=(b[n-1][i][j][4]-v[4])/(1+n/3)\n          }else{\n            p1=v[3]=S(t*2)/40\n            p2=v[4]=-C(t)/40\n          }\n          R(0,p2,p1)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n          X+=oX,Y+=oY,Z+=oZ\n          x.lineTo(...Q())\n          return v\n        })\n        x.lineWidth=599/Z/Z\n        x.closePath()\n        x.stroke()\n      })\n    })\n    v.map((v,n,b)=>{\n      v.map((v,i)=>{\n        if(n){\n          v.map((v,j)=>{\n            x.beginPath()\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            R(0,v[3],v[4])\n            X+=oX,Y+=oY,Z+=oZ\n            x.lineTo(...Q())\n            X=b[n-1][i][j][0]\n            Y=b[n-1][i][j][1]\n            Z=b[n-1][i][j][2]\n            R(0,b[n-1][i][j][3],b[n-1][i][j][4])\n            X+=oX,Y+=oY,Z+=oZ\n            x.lineTo(...Q())                \n            x.lineWidth=599/Z/Z\n            x.stroke()\n          })\n        }\n      })\n    })\n  })\n\n\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  x.lineCap=x.lineJoin=\'round\'\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'html,body{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg,#000,#024);\n}\n\n#c{\n  width:100%;\n  height:100%;\n}', '<canvas id=c>', 'seraphim', 1, 'cantelope', '2022-04-09 14:26:46', '', 28, 'https://code.dweet.net/thumbs/8ab8dd3d5f9e408c1cd41f1fa0778cfc.jpg', 35, 0),
