 if(v[6]){\n        x.beginPath()\n        x.arc(...Q(),iBs/Z*1.5,0,7)\n        x.fillStyle=`hsla(${col=t*300+360/B.length*j},99%,50%,.2`\n        x.fill()\n        x.beginPath()\n        x.arc(...Q(),iBs/Z,0,7)\n        x.fillStyle=`hsla(${col},99%,85%,.3`\n        x.fill()\n        x.beginPath()\n        x.arc(...Q(),iBs/Z/1.6,0,7)\n        x.fillStyle=`hsla(${col},99%,99%,.5`\n        x.fill()\n      }else{\n        x.beginPath()\n        x.arc(...Q(),iBs/Z,0,7)\n        x.fillStyle=`hsla(${180},99%,50%,${v[7]/1.5}`\n        x.fill()\n      }\n    }\n    v[7]=Math.min(.5,v[7]+.02)\n  })\n  \n  B=B.filter(v=>v[1]<G*3)\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nmp3 = new Audio()\nmp3.src = song\nmp3.loop = true\nmp3.play()\n\nDraw()', 'html,body{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg,#000,#024);\n}\n\n#c{\n  width:100%;\n  height:100%;\n}', '<canvas id=c>', 'sorting hat', 1, 'cantelope', '2022-04-09 14:26:46', '', 76, 'https://code.dweet.net/thumbs/25ea53bc06ed38dd3a0d5c64c1a78802.jpg', 61, 0),
(600017, 'https://srmcgann.github.io/assets/J91bd.mp4', 'song = \'https://twilightparadox.com/breaking%20the%20ice.mp3\'\nvid = \'https://twilightparadox.com/base%20videos/1Zidrk.mp4\'\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\nS=Math.sin\nC=Math.cos\nt=0,vidplaying=playing=false\n\nDraw=()=>{\n\n  if(!t){\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    Rn=Math.random\n  }\n  \n  if(typeof bgvid !== \'undefined\'){\n    x.globalAlpha=.4\n    x.drawImage(bgvid,0,0,w=c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0006\'\n    x.fillRect(0,0,w=c.width,w)\n  }else{\n    x.fillStyle=\'#0006\'\n    x.fillRect(0,0,w=c.width,w)\n  }\n\n  oX=0,oY=0,oZ=14+S(t*3)*4\n  Rl=t/4,Pt=0,Yw=t\n  iBCsc=3\n  G=6\n\n  //x.lineJoin=\'round\'\n  if(!t){\n    BC=[(-G/2|0)+.5,(G/2|0)+.5,0,[],1,0]\n    for(i=6;i--;){\n      for(j=4;j--;){\n        BC[3]=[...BC[3],[\n          (a=[S(p=Math.PI*2/4*j+Math.PI/4)*(d=(2**.5)/2),C(p)*d,.5])[i%3]*(l=i<3?1:-1),\n          a[(i+1)%3]*l,\n          a[(i+2)%3]*l]\n        ]\n      }\n    }\n    BCs=Array(iBCsc).fill().map(v=>[JSON.parse(JSON.stringify(BC))])\n  }\n\n  if(1){\n    BCs.map((q,j)=>{\n      for(m=1;m--;){\n        a=JSON.parse(JSON.stringify(q[q.length-1]))\n        n=a[5]\n        if(!(((t*60+j*(20/BCs.length))|0)%3)) n=a[5]=Rn()*6|0\n        tx=a[0]\n        ty=a[1]\n        tz=a[2]\n        tx+=(n==0?1:0)\n        ty+=(n==1?1:0)\n        tz+=(n==2?1:0)\n        tx+=(n==3?-1:0)\n        ty+=(n==4?-1:0)\n        tz+=(n==5?-1:0)\n        tx=Math.max(-G,tx)\n        ty=Math.max(-G,ty)\n        tz=Math.max(-G,tz)\n        tx=Math.min(G,tx)\n        ty=Math.min(G,ty)\n        tz=Math.min(G,tz)\n        a[0]=tx,a[1]=ty,a[2]=tz\n        a[4]=1\n        q.push(a)\n      }\n    })\n  }\n\n  BCs=BCs.map((v,j)=>{\n    v.map(v=>{\n      a=v[4]/=1.3\n      x.strokeStyle=`hsla(${0},99%,${115-(1-a)*75}%,${a/4}`\n      x.fillStyle=`hsla(${0},99%,${115-(1-a)*75}%,${a/8}`\n      for(m=8;m--;){\n        switch(m){\n          case 0:\n            tx=v[0]\n            ty=v[1]\n            tz=v[2]\n            break\n          case 1:\n            tx=v[0]*-1\n            ty=v[1]\n            tz=v[2]\n            break\n          case 2:\n            tx=v[0]*-1\n            ty=v[1]*-1\n            tz=v[2]\n            break\n          case 3:\n            tx=v[0]*-1\n            ty=v[1]*-1\n            tz=v[2]*-1\n            break\n          case 4:\n            tx=v[0]\n            ty=v[1]*-1\n            tz=v[2]*-1\n            break\n          case 5:\n            tx=v[0]\n            ty=v[1]\n            tz=v[2]*-1\n            break\n          case 6:\n            tx=v[0]*-1\n            ty=v[1]\n            tz=v[2]*-1\n            break\n          case 7:\n            tx=v[0]\n            ty=v[1]*-1\n            tz=v[2]\n            break\n        }\n        v[3].map((v,i)=>{\n          if(i%4==0)x.beginPath()\n          X=v[0]+tx\n          Y=v[1]+ty\n          Z=v[2]+tz\n          R(Rl,Pt,Yw,1)\n          if(Z>0){\n            x.lineTo(...Q())\n            if(i%4==3){\n              x.closePath()\n              x.lineWidth=Math.min(50,1+599/Z/Z)\n              x.stroke()\n              x.fill()\n            }\n          }\n        })\n      }\n    })\n    return v.filter(v=>v[4]>.08)\n  })\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\n\nmp3 = new Audio()\nmp3.src = song\nif(!mp3)loaded=1\nmp3.addEventListener(\'canplay\',()=>{\n  if(!playing){\n    loaded=playing=1\n    mp3.loop = true\n    mp3.play()\n    if(vid){\n      bgvid = document.createElement(\'video\')\n      bgvid.src = vid\n      bgvid.addEventListener(\'canplay\',()=>{\n        if(!vidplaying){\n          vidplaying=1\n          bgvid.loop=true\n          bgvid.play()\n        }\n      })\n    }\n  }\n})\n\n\nDraw()', 'html,body{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(135deg, #012, #123)\n}\n#c{\n  width: 100%;\n  height: 100%;\n}', '<canvas id=c>', 'breaking the ice', 1, 'cantelope', '2022-04-09 14:26:46', '', 68, 'https://code.dweet.net/thumbs/c2f957c5fa582ded8205f47599a69e16.jpg', 45, 0),
(600018, 'https://srmcgann.github.io/assets/1pfk3E.mp4', 'song = \'https://twilightparadox.com/anthropology.mp3\'\nvid = \'https://twilightparadox.com/base%20videos/anthropology_compressed.mp4\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  Rn=Math.random\n\n  if(typeof bgvid !== \'undefined\'){\n    x.globalAlpha=.4\n    x.drawImage(bgvid,0,0,w=c.width,c.height);\n    x.globalAlpha=1\n  }else{\n    x.fillStyle=\'#0001\'\n    x.fillRect(0,0,w=c.width,w)\n  }\n  if(!t){\n    iR=c.width/1.5,iV=7,sql=.15,iS=24\n    P=[]\n  }\n\n  for(m=10;m--;)P=[...P,[c.width/2+S(p=Math.PI*2*Rn())*iR*.95,c.height/2+C(p)*iR*(c.height/c.width),-S(p)*iV,-C(p)*iV,iS,Rn()*80]]\n  P.map((v,i)=>{\n    aX=v[0]+=v[2]=S(p=Math.atan2(v[2],v[3])+(Rn()-.5)*sql)*iV\n    aY=v[1]+=v[3]=C(p)*iV\n    x.beginPath()\n    x.arc(aX,aY,Math.min(120,((v[4]/=1.01)+1)**2.65/26),0,7)\n    x.fillStyle=`hsla(${140+v[5]},99%,${4+Math.hypot(c.width/2-aX,c.height/2-aY)/iR*20}%,${.08*Math.hypot(c.width/2-aX,c.height/2-aY)/iR}`\n    x.fill()\n  })\n  P=P.filter(v=>v[4]>5)\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  x.lineCap=x.lineJoin=\'round\'\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'html,body{\n  height: 100vh;\n  margin: 0;\n  background: #000;\n}\n\n#c{\n  width:100%;\n  height:100%;\n}', '<canvas id=c>', 'anthropology', 1, 'cantelope', '2022-04-09 14:26:46', '', 80, 'https://code.dweet.net/thumbs/6c919f30c6368dda60c92531777a1b21.jpg', 57, 0),
(600020, 'https://srmcgann.github.io/assets/1BJDQH.mp4', 'song = \'https://twilightparadox.com/giant%20oaks.mp3\'\nvid = \'https://twilightparadox.com/base%20videos/giant%20oaks%20base%20downgraded.mp4\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(typeof bgvid !== \'undefined\'){\n    x.globalAlpha=.8\n    x.drawImage(bgvid,0,0,w=c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0004\'\n    x.fillRect(0,0,w=c.width,w)\n  }else{\n    x.fillStyle=\'#0006\'\n    x.fillRect(0,0,w=c.width,w)\n  }\n\n  if(!t){\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    Q=q=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n    Rn=Math.random\n    x.lineJoin=x.lineCap=\'round\'\n    cl=3,rw=16*3,s=6\n  }\n\n  Rl=t/4,Pt=-t,Yw=t/2\n  oX=0,oY=0,oZ=60+S(t*2)*16\n  \n  P=Array(cl).fill().map((v,j)=>{\n    return Array(rw).fill().map((v,i)=>{\n      l2=1\n      l1=rw*l2/16\n      d=s+S(Math.PI*2/rw*l1*i)*(.15+C(Math.PI*8/rw*l1*i))**3*2\n      X=S(p=Math.PI*2/(rw)*l2*i)*d\n      Y=C(p)*d\n      Z=0\n      R(0,0,Math.PI*2/cl*j,0)\n      return [X,Y,Z]\n    })\n  })\n  \n  for(k=3**3;k--;){\n    tx=((k%3)-1.5+.5)*s*4\n    ty=(((k/3|0)%3)-1.5+.5)*s*4\n    tz=((k/3/3|0)-1.5+.5)*s*4\n    d3=Math.hypot(tx,ty,tz)/16+t*2\n    P.map((v,j)=>{\n      v.map((q,i)=>{\n        x.beginPath()\n        X=q[0]\n        Y=q[1]\n        Z=q[2]\n        R(t+d3,-t/2+d3,t/3+d3,0)\n        X+=tx,Y+=ty,Z+=tz\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n        if(i<v.length-1){\n          X=v[i+1][0]\n          Y=v[i+1][1]\n          Z=v[i+1][2]\n        }else{\n          X=v[0][0]\n          Y=v[0][1]\n          Z=v[0][2]\n        }\n        R(t+d3,-t/2+d3,t/3+d3,0)\n        X+=tx,Y+=ty,Z+=tz\n        R(Rl,Pt,Yw,1)\n        if(Z>5){\n          x.lineTo(...Q())\n          x.strokeStyle=\'#8fb3\'\n          x.lineWidth=Math.min(32,1+30000/Z/Z)\n          x.stroke()\n          x.strokeStyle=\'#eef8\'\n          x.lineWidth=Math.min(12,1+5000/Z/Z)\n          x.stroke()\n        }\n      })\n    })\n  }\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  x.lineCap=x.lineJoin=\'round\'\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n            Draw()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'html,body{\n  height: 100vh;\n  margin: 0;\n  background: #000;\n}\n\n#c{\n  width:100%;\n  height:100%;\n}', '<canvas id=c>', 'giant oaks', 1, 'cantelope', '2022-04-09 14:26:46', '', 88, 'https://code.dweet.net/thumbs/791cd4a5cdf0a3021a94df6a6b3dbe90.jpg', 69, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600021, 'https://srmcgann.github.io/assets/1f7iJb.mp4', 'song = \'https://twilightparadox.com/the%20long%20path.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(!t){\n    iPv=.2,lk=1.55,lk2=.22,bx=75\n    bgimg=new Image()\n    bgimg.src=\'https://srmcgann.github.io/assets/rw8b4.jpg\'\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    Q=q=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n    Rn=Math.random\n    x.lineJoin=x.lineCap=\'round\'\n    G=10,gh=G/16\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    B=[\n      [-G/2,-G/2+gh*2,0,G/2-gh*3,-G/2+gh*3,0],\n      [G/2,-G/2,0,tx=G/2,ty=-G/2+gh*4,tz=0]\n    ]\n    r=.2\n    for(i=0;i<6;++i) B=[...B,[tx,ty,tz,tx-=S(p=Math.PI/15*(i+1))*r,ty+=C(p)*r,tz]]\n    B=[...B, [tx,ty,tz,tx=-G/2+gh*3,ty=ty+gh,tz]]\n    B=[...B, [tx=-G/2,ty-=gh*4.2,tz,tx,ty+=gh*5.5,tz]]\n    for(i=0;i<6;++i) B=[...B,[tx,ty,tz,tx+=S(p=Math.PI/15*(i+1))*r,ty+=C(p)*r,tz]]\n    B=[...B, [tx,ty,tz,tx=G/2-gh*3,ty=ty+gh,tz]]\n    for(m=8;m--;){\n      B=[...B, [tx=G/2,ty-=gh*5.5,tz,tx,ty+=gh*6.5,tz]]\n      for(i=0;i<6;++i) B=[...B,[tx,ty,tz,tx-=S(p=Math.PI/15*(i+1))*r,ty+=C(p)*r,tz]]\n      B=[...B, [tx,ty,tz,tx=-G/2+gh*3,ty+=gh,tz]]\n      B=[...B, [tx=-G/2,ty-=gh*5.5,tz,tx,ty+=gh*6.5,tz]]\n      for(i=0;i<6;++i) B=[...B,[tx,ty,tz,tx+=S(p=Math.PI/15*(i+1))*r,ty+=C(p)*r,tz]]\n      B=[...B, [tx,ty,tz,tx=G/2-gh*3,ty+=gh,tz]]\n    }\n    B.map(v=>{v[0]*=4,v[3]*=4,v[1]-=14.5,v[4]-=14.5,v[1]*=2.75,v[4]*=2.75})\n    P=[]\n  }\n  \n  x.globalAlpha=.08\n  x.drawImage(bgimg,0,0,w=c.width,c.height)\n  x.globalAlpha=1\n  x.fillStyle=`hsla(${t*75},80%,10%,.25`,x.fillRect(0,0,w,w)\n\n  if(!((t*60|0)%10)){\n    P=[...P,[(Rn()-.5)*G*2.5+4,-G*6.25,0,S(p=Math.PI*2*(Rn()-.5)/9)*iPv,C(p)*iPv,0]]\n  }\n\n  oX=0,oY=0\n  Rl=S(t)/16\n  Rl2=S(t/1.5+Math.PI/4)/16\n  Pt=-S(t/2)/6\n  Yw=t\n  Yw1=S(t+Math.PI/4)/3\n  Yw2=S(t*1.5+Math.PI/2)/3\n  \n  fcol1=`hsla(${t*100+360/3*1},99%,40%,.25`\n  fcol2=`hsla(${t*100+360/3*2},99%,40%,.25`\n  fcol3=`hsla(${t*100+360/3*3},99%,40%,.25`\n  col1=`hsla(${t*100+360/3*2},99%,50%,.2`\n  col2=`hsla(${t*100+360/3*3},99%,50%,.2`\n  col3=`hsla(${t*100+360/3*1},99%,50%,.2`\n\n  oZ=G*11-S(t/2)*20\n  P.map(v=>{\n    X=(v[0]+=v[3])\n    Y=v[1]+=v[4]\n    Z=v[2]+=v[5]\n    R(0,0,Yw1,0)\n    R(Rl2,-Pt,0,1)\n    X-=bx\n    x.beginPath()\n    x.arc(...Q(),700/Z,0,7)\n    x.fillStyle=col1\n    x.fill()\n    x.beginPath()\n    x.arc(...Q(),350/Z,0,7)\n    x.fillStyle=\'#fff6\'\n    x.fill()\n  })\n\n  B.map((v,i)=>{\n    x.beginPath()\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R(0,0,Yw1,0)\n    R(Rl2,-Pt,0,1)\n    X-=bx\n    x.lineTo(...Q())\n    X=v[3]\n    Y=v[4]\n    Z=v[5]\n    R(0,0,Yw1,0)\n    R(Rl2,-Pt,0,1)\n    X-=bx\n    x.lineTo(...Q())\n    x.lineWidth=100000/Z/Z\n    x.strokeStyle=fcol1\n    x.stroke()\n    x.lineWidth=40000/Z/Z\n    x.strokeStyle=\'#fff8\'\n    x.stroke()\n  })\n\n  oZ=G*11-S(t/2+Math.PI*2/3*1)*20\n  P.map(v=>{\n    X=(v[0]+=v[3])\n    Y=v[1]+=v[4]\n    Z=v[2]+=v[5]\n    R(0,0,Y/15*S(t/4))\n    R(0,0,Yw,0)\n    R(Rl,-Pt,0,1)\n    //X-=bx\n    x.beginPath()\n    x.arc(...Q(),700/Z,0,7)\n    x.fillStyle=col2\n    x.fill()\n    x.beginPath()\n    x.arc(...Q(),350/Z,0,7)\n    x.fillStyle=\'#fff6\'\n    x.fill()\n  })\n\n  B.map((v,i)=>{\n    x.beginPath()\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R(0,0,Y/15*S(t/4))\n    R(0,0,Yw,0)\n    R(Rl,-Pt,0,1)\n    x.lineTo(...Q())\n    X=v[3]\n    Y=v[4]\n    Z=v[5]\n    R(0,0,Y/15*S(t/4))\n    R(0,0,Yw,0)\n    R(Rl,-Pt,0,1)\n    x.lineTo(...Q())\n    x.lineWidth=100000/Z/Z\n    x.strokeStyle=fcol2\n    x.stroke()\n    x.lineWidth=40000/Z/Z\n    x.strokeStyle=\'#fff8\'\n    x.stroke()\n  })\n\n  oZ=G*11-S(t/2+Math.PI*2/3*2)*20\n  P.map(v=>{\n    X3=v[0]\n    Y3=v[1]\n    d=Math.hypot(v[3],v[4],v[5])\n    X4=X3+v[3]/d*lk*(1+d*2)\n    Y4=Y3+v[4]/d*lk*(1+d*2)\n    B.map(q=>{\n      X1=q[0]\n      Y1=q[1]\n      X2=q[3]\n      Y2=q[4]\n      if(m=I(X1,Y1,X2,Y2,X3,Y3,X4,Y4)){\n        v[3]/=1.02\n        v[4]/=1.08\n        v[3]+=S(p=Math.atan2(X2-X1,Y2-Y1)+Math.PI/2)*lk2*(X2<=X1&&X1>0?-1:1)\n        v[4]+=C(p)*lk2*(X2<=X1?-1:1)\n      }\n    })\n    X=(v[0]+=v[3])\n    Y=v[1]+=v[4]+=.025\n    Z=v[2]+=v[5]\n    R(0,0,Yw2,0)\n    R(Rl,Pt,0,1)\n    X+=bx\n    x.beginPath()\n    x.arc(...Q(),700/Z,0,7)\n    x.fillStyle=col3\n    x.fill()\n    x.beginPath()\n    x.arc(...Q(),350/Z,0,7)\n    x.fillStyle=\'#fff6\'\n    x.fill()\n  })\n\n  B.map((v,i)=>{\n    x.beginPath()\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R(0,0,Yw2,0)\n    R(Rl,Pt,0,1)\n    X+=bx\n    x.lineTo(...Q())\n    X=v[3]\n    Y=v[4]\n    Z=v[5]\n    R(0,0,Yw2,0)\n    R(Rl,Pt,0,1)\n    X+=bx\n    x.lineTo(...Q())\n    x.lineWidth=100000/Z/Z\n    x.strokeStyle=fcol3\n    x.stroke()\n    x.lineWidth=40000/Z/Z\n    x.strokeStyle=\'#fff8\'\n    x.stroke()\n  })\n\n  P=P.filter(v=>v[1]<G*9)\n\n \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  x.lineCap=x.lineJoin=\'round\'\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'html,body{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg,#000,#024);\n}\n\n#c{\n  width:100%;\n  height:100%;\n}', '<canvas id=c>', 'the long path', 1, 'cantelope', '2022-04-09 14:26:46', '', 109, 'https://code.dweet.net/thumbs/6f175c0e5dd266a02a3cb702b22d6574.jpg', 77, 0),
(600022, '', 'names=[\"astra\", \"Aztec03\", \"blazin\", \"bozoslive\", \"bysin\", \"ByteLawd\", \"cantelope\", \"chopchop1\", \"comrade\", \"djsubz\", \"fauna\", \"god\", \"med\", \"mptank\", \"mur\", \"ningy\", \"notK\", \"pu-nx\", \"punx\", \"punx-\", \"QAnon\", \"sig\", \"stybla\", \"TiK\", \"tvitale\", \"vprowl\", \"xc\", \"xcalibur\", \"xeno\", \"darthbane\", \"sandwitch\"]\nspawnCol = () => {\n  let checks = i = 0\n  let occupied = false\n  do{\n    occupied = false\n    i = R() * cols.length | 0\n    for(j = 0; !occupied && j < cols[i].length; ++j) {\n      if(cols[i][j].id !== null) occupied = true\n    }\n    checks++\n  } while (occupied && checks < 2);\n  if (!occupied) {\n    cols[i][0] = {id: R() * 8 | 0, alpha: 1.15, life: 0}\n  }\n}\n\nDraw = () => {\n  if(!t){\n    R1=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    Rn=Math.random\n    curNameIdx=0\n  }\n  \n  x.fillStyle = \'#000b\'\n  x.fillRect(0, 0, c.width, c.height)\n  if (R()<Math.min(t/40,.1)) spawnCol()\n  let sym = \'\'\n  x.font = size * 1.5 + \'px courier\'\n  for(let i = 0; i < cols.length; ++i) {\n    let bottomChar = -1\n    for( let j = cols[i].length - 1; j--; ) {\n      if (cols[i][j].id !== null) {\n        let X = cx + i * size * spacing - size / 2 - size * spacing * cols.length / 2\n        let Y = j * size * spacing - size / 2\n        x.fillStyle = `hsl(116, 80%, ${Math.pow(cols[i][j].alpha-.2, 3)*100}%)`\n        if(cols[i][j].id === 0) {\n          x.globalAlpha = cols[i][j].alpha\n          x.drawImage(logo[cols[i][j].id].img, X, Y, size, size)\n          x.globalAlpha = 1\n          x.globalCompositeOperation = \"multiply\";\n          x.fillRect(X, Y, size, size)\n          x.globalCompositeOperation = \"source-over\";\n        } else {\n          switch (cols[i][j].id) {\n            case 1: sym = \'t\'; break;\n            case 2: sym = \'c\'; break;\n            case 3: sym = \'e\'; break;\n            case 4: sym = \'S\'; break;\n            case 5: sym = \'n\'; break;\n            case 6: sym = \'y\'; break;\n            case 7: sym = \'S\'; break;\n          }\n          x.globalAlpha = 1\n          x.fillText(sym, X, Y + size)\n        }\n        if (bottomChar === -1 && j < cols[i].length - 2) {\n          bottomChar = j\n          cols[i][j].life++\n          if(cols[i][j].life > speed) {\n            cols[i][j + 1].id = (cols[i][j].id + 1) % 8\n            cols[i][j + 1].alpha = 1.15\n            cols[i][j + 1].life = 0\n          }\n        }\n        if (cols[i][j].alpha < .6) {\n          cols[i][j].id = null\n          cols[i][j].alpha = 0\n          cols[i][j].life = 0\n        } else {\n          cols[i][j].alpha -= .01\n        }\n      }\n    }\n  }\n\n  Rl=-C(t/2.1)/8,Pt=S(t/1.5)/6,Yw=t\n  oX=0,oY=0,oZ=7\n  \n  names.map((curName,j)=>{\n    if(curName.length){\n      n=names[(j+(t*4|0))%names.length]\n      n.split(\'\').map((v,i)=>{\n        X=S(p=Math.PI*2/50/1.15*i+(10+n.charCodeAt(0)*n.length**2.51/16+(j+(t*4|0))**2.8))*3.5\n        Y=-names.length/5+(j-(t*4%1))/2\n        Z=C(p)*3.5\n        R1(Rl,Pt,Yw,1)\n        x.font=(600/(Z**1.25))+\'px courier\'\n        x.fillStyle=\'#3fa8\'\n        while(p>Math.PI*2)p-=Math.PI*2\n        if(p<Math.PI/4+1.25||p>Math.PI*1.5-.5){\n          x.fillText(v,...Q())\n        }else{\n          x.fillText(n.split(\'\')[n.length-1-i],...Q())\n        }\n      })\n    }\n  })\n  \n\n  t+=1/60\n  requestAnimationFrame(Draw);\n}\nlet R = Math.random\nlet c=document.getElementById(\"canvas\")\nlet x=c.getContext(\"2d\")\nc.width = 1920\nc.height = 1080\nlet S = Math.sin\nlet C = Math.cos\nlet t = 0\nlet oldG = gg = 0\nlet cx = c.width / 2\nlet cy = c.height / 2\nlet circles = []\nlet speed = 2\nlet size = 16\nlet spacing = 1.25\nlet rowNo = c.height * 1.1 / (size * spacing) | 0\nle