https://srmcgann.github.io/assets/1mnB22.jpg\"\n    angel.map(faces=>{\n      faces.map(v=>{\n        i++\n        tx+=v[0]\n        ty+=v[1]\n        tz+=v[2]\n      })\n    })\n    tx/=i\n    ty/=i\n    tz/=i\n    tx+=iMx\n    ty+=iMy\n    tz+=iMz\n    angel.map(faces=>{\n      faces.map(v=>{\n        v[0]-=tx\n        v[1]-=ty\n        v[2]-=tz\n        X=v[0]*.2\n        Y=v[1]*.2\n        Z=v[2]*.2\n        R(0,Math.PI/2,Math.PI,0)\n        v[0]=X\n        v[1]=Y\n        v[2]=Z\n      })\n    })\n    aBat=Array(16).fill().map((v,j)=>{\n      a=JSON.parse(JSON.stringify(angel))\n      return a.map(faces=>{\n        return faces.map(v=>{\n          X=v[0]\n          Y=v[1]-(Math.abs(X))**2*(.3+S(Math.PI*2/16*j))/23\n          Z=v[2]\n          return [X,Y,Z]\n        })\n      })\n    })\n    angels=Array(iBc).fill().map(v=>{\n      d=10+iBdr*3*Rn()**.5\n      return[S(p1=Math.PI*2*Rn())*S(p2=Math.PI/2*(Rn()**.5))*d,(Rn()<.5?-1:1)*C(p2)*d,C(p1)*S(p2)*d,0,(Rn()-.5)*Math.PI/4,Rn()*Math.PI*2]\n    })\n  }\n  \n  Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n  x.globalAlpha=.4, x.drawImage(bgimg,0,0,w=c.width,1080)\n  x.globalAlpha=1\n  x.fillStyle=\'#00000020\',x.fillRect(0,0,w,w)\n  oX=0,oY=0,oZ=G*1.1\n  Rl=0,Pt=0,Yw=0\n  \n  drawBat=(bx,by,bz,rl,pt,yw,ph)=>{\n    x.fillStyle=\'#88eeff20\'\n    X=bx\n    Y=by\n    Z=bz\n    R(Rl,Pt,Yw,1)\n    if(Z>0&&(d=Math.hypot(X,Y,Z))>G*1.55){\n      x.fillStyle=\'#44ffaa40\'\n      x.globalAlpha=1/((.45+Z)**14/6e43)\n      \n      x.beginPath()\n      x.arc(...Q(),6e8/(1+d**2.5),0,7)\n      x.fill()\n      x.globalAlpha=1\n    }else{\n      X=bx,Y=by,Z=bz,R(Rl,Pt,Yw,1)\n      x.lineWidth=1+2e5/(1+Z**2)\n      x.strokeStyle=x.fillStyle=\'#44ffaa66\'\n      FN=(ph+t*60|0)%aBat.length\n      aBat[FN].map((faces,i)=>{\n        x.beginPath()\n        faces.map(v=>{\n          X=v[0]\n          Y=v[1]\n          Z=v[2]\n          R(rl,pt,yw,0)\n          X+=bx\n          Y+=by\n          Z+=bz\n          R(Rl,Pt,Yw,1)\n          l=Q()\n          x.lineTo(...Q())\n        })\n        if(Z>.1){\n          x.closePath()\n          //x.fill()\n          x.stroke()\n        }\n      })\n    }\n  }\n\n  angels.map((v,j)=>{\n    tx=ty=tz=0\n    angels.map((q,i)=>{\n      if(i!==j){\n        d=(1+Math.hypot(q[0]-v[0],q[1]-v[1],q[2]-v[2]))**2\n        tx-=(v[0]-q[0])/d\n        ty-=(v[1]-q[1])/d\n        tz-=(v[2]-q[2])/d\n      }\n    })\n    p1=Math.atan2(tx,tz)\n    p2=Math.acos(ty)/Math.hypot(tx,ty,tz)\n    v[4]/=1.004\n    //v[5]+=(v[5]-p1)/10\n    v[4]+=(Rn()-.5)/6\n    v[5]+=(Rn()-.5)/4\n    v[0]-=S(p1=-v[5])*S(p2=v[4]+Math.PI/2)*iBv\n    v[1]-=C(p2)*iBv\n    v[2]+=C(p1)*S(p2)*iBv\n    drawBat(...v,j)\n    if(v[0]>G*2)v[0]-=G*4\n    if(v[1]>G)v[1]-=G*2\n    if(v[2]>G)v[2]-=G*2\n    if(v[0]<-G*2)v[0]+=G*4\n    if(v[1]<-G)v[1]+=G*2\n    if(v[2]<-G)v[2]+=G*2\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  x.lineCap=x.lineJoin=\'round\'\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'html,body{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(135deg, #000, #123);\n}\n\n#c{\n  width: 100%;\n  height: 100%;\n}', '<canvas id=c>', '', 13, 'WWWWWWWWWWWWWWWW', '2022-04-09 14:26:46', '[600023]', 10, '', 4, 0),
(600063, 'https://srmcgann.github.io/assets/1aGixh.mp4', 'song = \'https://twilightparadox.com/when the moon was made.mp3\'\nvid = \'\'\n\nfunction initVars() {\n\n  pi = Math.PI;\n  canvas = c//document.querySelector(\"#c\");\n  cx = canvas.width / 2;\n  cy = canvas.height / 2;\n  frames = seed = 0;\n  res = 20;\n  points = 10;\n  cols = parseInt(1920 / res);\n  rows = parseInt(1080 / res);\n}\n\nfunction rand() {\n  seed += .1234;\n  return parseFloat(\'0.\' + Math.sin(seed).toString().substr(6));\n}\n\nfunction loadControlPoints() {\n\n  controls = new Array(points);\n  for (i = 0; i < points; ++i) {\n    controls[i] = new Object();\n    controls[i].x = cols / 2;\n    controls[i].y = rows / 2;\n    controls[i].vx = 3 - rand() * 6;\n    controls[i].vy = 3 - rand() * 6;\n  }\n}\n\nfunction loadTerrain() {\n\n  terrain = new Array(cols);\n  max = 0;\n  for (i = 0; i < cols; ++i) {\n    terrain[i] = new Array(rows);\n    for (j = 0; j < rows; ++j) {\n      terrain[i][j] = new Object();\n      d1 = d2 = 0;\n      for (k = 0; k < points; ++k) {\n        d1 += Math.sqrt((i - controls[k].x) * (i - controls[k].x) + \n        								(j - controls[k].y) * (j - controls[k].y));\n      }\n      c_ = 1;\n      for (k = 0; k < points; ++k) {\n        d2 = Math.sqrt((i - controls[k].x) * (i - controls[k].x) + \n        							 (j - controls[k].y) * (j - controls[k].y));\n        c_ *= 1 - (1 - (d2 / d1));\n      }\n      if (c_ > max) max = c_;\n      terrain[i][j].color = c_;\n    }\n  }\n  for (i = 0; i < cols; ++i) {\n    for (j = 0; j < rows; ++j) {\n      terrain[i][j].color /= max;\n    }\n  }\n}\n\nfunction interpolate(x, y, degree) {\n\n  return degree * x + (1 - degree) * y;\n}\n\nfunction doLogic() {\n\n  frames++;\n  t = .5 - Math.cos(frames / 100) / 2;\n  for (i = 0; i < controls.length; ++i) {\n    if (controls[i].x + controls[i].vx >= cols || \n    		controls[i].x + controls[i].vx < 0) controls[i].vx *= -1;\n    if (controls[i].y + controls[i].vy >= rows ||\n    		controls[i].y + controls[i].vy < 0) controls[i].vy *= -1;\n    p = pi * 2 / controls.length * i + frames / 10 + \n    		(i % 2 ? 1 : -1) * Math.sin(frames / 16) * 2;\n    ls = rows / 2 * (1 + (i % 2));\n    x_ = cols / 2 + Math.sin(p) * ls;\n    y_ = rows / 2 + Math.cos(p) * ls;\n    vx = (x_ - controls[i].x) / 25;\n    vy = (y_ - controls[i].y) / 25;\n    controls[i].x += interpolate(controls[i].vx, vx, t);\n    controls[i].y += interpolate(controls[i].vy, vy, t);\n  }\n  loadTerrain();\n}\n\nfunction colorString(col){\n  var r = Math.round(col[0]*255);\n  var g = Math.round(col[1]*255);\n  var b = Math.round(col[2]*255);\n  return \"#\"+(\"0\" + r.toString(16) ).slice (-2)+(\"0\" + g.toString(16) ).slice (-2)+(\"0\" + b.toString(16) ).slice (-2);\n}\n\nfunction interpolateColors(RGB1, RGB2, degree) {\n\n  w1 = degree;\n  w2 = 1 - w1;\n  return colorString([w1 * RGB1[0] + w2 * RGB2[0], \n  										w1 * RGB1[1] + w2 * RGB2[1], \n                      w1 * RGB1[2] + w2 * RGB2[2]]);\n}\n\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\n\nDraw=()=>{\n\n  if(!t){\n    initVars()\n    loadControlPoints()\n    loadTerrain()\n  }\n\n  x.clearRect(0, 0, cx * 2, cy * 2);\n\n  width = cx * 2 / cols;\n  height = cy * 2 / rows;\n  for (i = 0; i < cols; ++i) {\n    for (j = 0; j < rows; ++j) {\n      x_ = i * width;\n      y_ = j * height;\n      x.globalAlpha = 1;\n      col1 = [terrain[i][j].color,\n              terrain[i][j].color,\n              terrain[i][j].color];\n      p = terrain[i][j].color * pi * \n          (5.65 - Math.cos(frames / 22) * 5) + frames / 14;\n      col2 = [.5 + Math.sin(p) / 2,\n              .5 + Math.cos(p) / 2,\n              .5 - Math.sin(p) / 2];\n      x.fillStyle = interpolateColors(col2, col1, \n                      .5 - Math.cos(frames / 42) / 2);\n      x.fillRect(x_, y_, width + 1, height + 1);\n    }\n  }\n\n  doLogic();\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  x.lineCap=x.lineJoin=\'round\'\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}', '<canvas id=c>', 'when the moon was made', 1, 'cantelope', '2022-04-09 14:26:46', '', 889, 'https://code.dweet.net/thumbs/9ca3597b73dab1bb32e4ea5c2f0adc02.jpg', 217, 0),
(600066, 'https://srmcgann.github.io/assets/15svCP.mp4', 'song = \'https://twilightparadox.com/symbols from beyond.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n x.lineCap=\'round\',R=q=>{X=S(p=(A=(M=Math).atan2)(X,Z)+Yw)*(d=(H=Math.hypot)(X,Z)),Z=C(p)*d;Z+=oZ};Q=q=>[960+X/Z*700,540+Y/Z*700];x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w),Yw=t/2,oZ=10,CR=(tx,ty,tz,pz)=>{x.beginPath();for(i=16;i--;){X=tx+S(p=i/2.546);Y=ty+C(p),Z=tz,R(),x.lineTo(...Q())};x.strokeStyle=`hsla(${11*(pz+t*4|0)},99%,${75+S(pz/8-t*8)*25}%,${Math.min(.3,((pz+16)**3/8e3)*((16-pz)**3/4e3))}`;x.lineWidth=600/Z/Z;x.closePath();x.stroke()};B=[];for(k=8;k--;){px=S(p=Math.PI*4/8*(k+(t*6|0)))*(d=S(t));py=C(p)*d;pz=(k*4)-(t*6%1)*4-10;P=[a=[px,py,pz/2]],CR(...a,pz);for(m=1;m<3;++m){for(j=6;j--;){P=[...P,[tx=px+S(p=j+.52+t)*m*2,ty=py+C(p)*m*2,tz=pz/2,pz]];CR(tx,ty,tz,pz)}};B=[...B,P]}B.map(v=>{v.map((m,i)=>{v.map((q,j)=>{if(j>i){X=m[0];Y=m[1];Z=m[2];R();x.beginPath();x.lineTo(...Q());X=q[0];Y=q[1];Z=q[2];R();x.lineTo(...Q());x.lineWidth=600/Z/Z;x.strokeStyle=`hsla(${11*(q[3]+t*4|0)},99%,${75+S(q[3]/8-t*8)*25}%,${Math.min(.2,((q[3]+16)**3/1e4)*((16-q[3])**3/1e4))}`;x.stroke()}})})})\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  x.lineCap=x.lineJoin=\'round\'\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}', '<canvas id=c>', 'symbols from beyond', 1, 'cantelope', '2022-04-09 14:26:46', '[600063]', 859, 'https://code.dweet.net/thumbs/0d68626990760673f1877ecff358f4e1.jpg', 185, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600068, 'https://srmcgann.github.io/assets/13U73y.mp4', 'song = \'https://twilightparadox.com/sierpenski.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n   x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w)\n  \n  if(!t){\n    Q=q=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    loopCount=0\n    transitionFreq=16\n  }\n  \n  switch(loopCount%4){\n    case 1:\n      Rl=-Math.PI/2+S(t/2.5)/2,Pt=-.2+S(t/2)/2,Yw=-t/2.5\n      break\n    case 2:\n      Rl=-Math.PI/2+S(t/2.5)/2,Pt=-.3-S(t/2)/3,Yw=t/2.5\n      break\n    case 3:\n      Rl=-Math.PI/2+S(t/2.5)/2,Pt=-.2-S(t*1.5)/4,Yw=-t/2.5\n      break\n    case 0:\n      Rl=-Math.PI/2+S(t/2.5)/2,Pt=-.3-S(t/2)/3,Yw=t/2.5\n      break\n  }        \n\n  init = () => {\n    t=1/60\n    switch(loopCount%4){\n      case 0:\n        oX=0,oY=-2,oZ=14\n        lw=16e6\n        cl=3\n        grav=.01\n        floor=6\n        ls=.7\n        iSr=4\n        iBv=.1\n        lsrd=1.85\n        tiSrd=2\n        tOx=-5.25\n        depth=4\n        curveres=4\n        break\n      case 1:\n        oX=0,oY=-2.5,oZ=15\n        lw=16e6\n        cl=4\n        grav=.01\n        floor=5.5\n        ls=.7\n        iSr=5\n        iBv=.1\n        lsrd=1.85\n        tiSrd=2\n        tOx=-5\n        depth=3\n        curveres=5\n        break\n      case 2:\n        oX=0,oY=-2.25,oZ=14\n        lw=16e6\n        cl=5\n        grav=.01\n        floor=6\n        ls=.75\n        iSr=5\n        iBv=.06\n        lsrd=1.95\n        tiSrd=2.5\n        tOx=-5\n        depth=2\n        curveres=5\n        break\n      case 3:\n        oX=0,oY=-2.25,oZ=14\n        lw=16e6\n        cl=6\n        grav=.01\n        floor=5\n        ls=.75\n        iSr=5\n        iBv=.06\n        lsrd=1.95\n        tiSrd=3.5\n        tOx=-5\n        depth=2\n        curveres=4\n        break\n    }\n\n    a=[],tk=0\n    SG=(tx,ty,tz,r,idx,idx2,ls)=>{\n      for(let i=0;i<cl;++i){\n        X1=tx\n        Y1=ty+S(p=Math.PI*2/cl*i)*r\n        Z1=tz+C(p)*r\n        X2=tx+ls\n        Y2=ty+S(p=Math.PI*2/cl*i)*r\n        Z2=tz+C(p)*r\n        G=[...G,[[X1,Y1,Z1],[X2,Y2,Z2]]]\n        a=[...a,[idx,idx2+i]]\n      }\n    }\n    x.lineJoin=x.lineCap=\'round\'\n\n    G=[[[tOx,0,0],[tOx+ls*2,0,0]]]\n    tsidx=0\n    tl=G.length\n    SG(G[0][1][0]+ls*4,G[0][1][1],G[0][1][2],iSr,0,tl,ls)\n    tiSr=iSr\n    for(m=depth;m--;){\n      tiSr/=tiSrd\n      ls/=lsrd\n      tsidx=(G.length/cl|0)-1\n      G.map((v,i)=>{\n        if(i>tsidx){\n          tl=G.length\n          SG(v[1][0]+ls*4,v[1][1],v[1][2],tiSr,i,tl,ls)\n        }\n      })\n    }\n\n    B=[],FB=[]\n\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n\n    strokeCol=`hsl(${130},99%,50%`\n    RCB=q=>{\n      x.globalAlpha=.2*strokeAlpha\n      x.strokeStyle=strokeCol\n      tx_=q[0],ty_=q[1],tz_=q[2]\n      for(j=0;j<curveres-1;j++){\n        tx1=X=q[0]+(q[3]-q[0])/curveres*j\n        ty1=Y=q[1]+(q[4]-q[1])/curveres*j\n        tz1=Z=q[2]+(q[5]-q[2])/curveres*j\n        R(Rl,Pt,Yw,1)\n        x.beginPath()\n        x.lineTo(...Q())\n        tx2=X=q[3]+(q[6]-q[3])/curveres*j\n        ty2=Y=q[4]+(q[7]-q[4])/curveres*j\n        tz2=Z=q[5]+(q[8]-q[5])/curveres*j\n        x.beginPath()\n        X=tx_,Y=ty_,Z=tz_\n        R(Rl,Pt,Yw,1)\n        tct=[X,Y,Z]\n        x.lineTo(...Q())\n        tx3=X=q[0]+(q[3]-q[0])/curveres*(j+1)\n        ty3=Y=q[1]+(q[4]-q[1])/curveres*(j+1)\n        tz3=Z=q[2]+(q[5]-q[2])/curveres*(j+1)\n        tx4=X=q[3]+(q[6]-q[3])/curveres*(j+1)\n        ty4=Y=q[4]+(q[7]-q[4])/curveres*(j+1)\n        tz4=Z=q[5]+(q[8]-q[5])/curveres*(j+1)\n        l=I(tx1,ty1,tx2,ty2,tx3,ty3,tx4,ty4)\n        tx_=X=l[0],ty_=Y=l[1],tz_=Z=q[2]+(q[8]-q[2])/curveres*(j+.5)\n        R(Rl,Pt,Yw,1)\n        tc=[...tc,[[...tct],[X,Y,Z]]]\n        x.lineTo(...Q())\n        x.lineWidth=Math.min(30,1+lw/((Z+1)**1.2+1+(1+Math.abs(tOx)+tx1)*10)**3.25)\n        x.stroke()\n      }\n      x.beginPath()\n      tct=[X,Y,Z]\n      x.lineTo(...Q())\n      X=q[6],Y=q[7],Z=q[8]\n      R(Rl,Pt,Yw,1)\n      tc=[...tc,[[...tct],[X,Y,Z]]]\n      x.lineTo(...Q())\n      x.lineWidth=Math.min(30,1+lw/((Z+1)**1.2+1+(1+Math.abs(tOx)+q[3])*10)**3.25)\n      x.stroke()\n      x.globalAlpha=1\n    }\n    loopCount++\n  }\n  \n  strokeAlpha=Math.max(0,.1+S(t)*.75)\n  bcol=\'#10f6\'\n    \n  if(!((t*60|0)%(60*transitionFreq))) init()\n    \n  if(!((t*60|0)%1)){\n    g=(g=a.filter(v=>v[0]==0))[g.length*Math.random()|0]\n    B=[...B,[g[0],g[1],0,0,S(t*8)*Math.PI]]\n    tk++\n  }\n   \n  x.globalAlpha=.4*strokeAlpha\n  G.map((v,i)=>{\n    x.beginPath()\n    X=v[0][0]\n    Y=v[0][1]\n    Z=v[0][2]\n    if(i) R(0,.00001,0,0)\n    v[0][0]=X,v[0][1]=Y,v[0][2]=Z\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    X=v[1][0]\n    Y=v[1][1]\n    Z=v[1][2]\n    if(i) R(0,.00001,0,0)\n    v[1][0]=X,v[1][1]=Y,v[1][2]=Z\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    x.strokeStyle=strokeCol\n    x.lineWidth=Math.min(30,1+lw/((Z+1)**1.2+(1+Math.abs(tOx)+v[1][0])*9)**3.25)\n    x.stroke()\n  })\n  x.globalAlpha=1\n\n  a.map(v=>{\n    X1=G[v[1]][0][0]\n    Y1=G[v[1]][0][1]\n    Z1=G[v[1]][0][2]\n    X2=G[v[0]][1][0]\n    Y2=G[v[0]][1][1]\n    Z2=G[v[0]][1][2]\n    \n    xa=X=X1,ya=Y=Y1,za=Z=Z1,xb=X=X2,yb=Y=Y2,zb=Z=Z2\n    xc=X=(X1+X2)/2,yc=Y=(Y1+Y2)/2,zc=Z=(Z1+Z2)/2\n    xd=X=xc,yd=Y=ya,zd=Z=(za+zc)/2,xe=X=xc,ye=Y=yb,ze=Z=(zb+zc)/2\n    tc=[]\n    RCB([xa,ya,za,xd,yd,zd,xc,yc,zc,v[0]])\n    RCB([xb,yb,zb,xe,ye,ze,xc,yc,zc,v[0]])\n\n    /*\n    tc.map((v,i)=>{\n      x.beginPath()\n      X1=X=v[0][0]\n      Y1=Y=v[0][1]\n      Z1=Z=v[0][2]\n      x.lineTo(...Q())\n      X2=X=v[1][0]\n      Y2=Y=v[1][1]\n      Z2=Z=v[1][2]\n      x.lineTo(...Q())\n      x.strokeStyle=\'#0ff8\'\n      x.lineWidth=1+lw/10/(Z+(1+Math.abs(tOx)+tx1)*10)**3.25\n      x.stroke()\n    })\n    */\n\n    B=B.map((q,k)=>{\n      if(q[3]==1 && q[1]==v[1]){\n        q[2]+=iBv/2\n        seg=(q[2]*tc.length)|0\n        tc.map((n,j)=>{\n          let i\n          if(j<tc.length/2){\n            i=(tc.length/2+j)|0\n            l1=0,l2=1\n          } else{\n            i=(tc.length/2-(j-tc.length/2+.5))|0\n            l1=1,l2=0\n          }\n          m=tc[i]\n          if(j==seg){\n            X1=X=m[l1][0]\n            Y1=Y=m[l1][1]\n            Z1=Z=m[l1][2]\n            X2=X=m[l2][0]\n            Y2=Y=m[l2][1]\n            Z2=Z=m[l2][2]\n            l=(q[2]*tc.length)-j\n            X=X1+(X2-X1)*l\n            Y=Y1+(Y2-Y1)*l\n            Z=Z1+(Z2-Z1)*l\n            x.globalAlpha=1\n            s=Math.min(12,1+lw/(l1?150:150)/((Z+1)**1.2+(1+Math.abs(tOx)+tx1)*250)**1.25)\n            x.beginPath()\n            x.fillStyle=bcol\n            x.arc(...Q(),s,0,7)\n            x.fill()\n            x.beginPath()\n            s/=2\n            x.fillStyle=\'#fff8\'\n            x.arc(...Q(),s,0,7)\n            x.fill()\n          }\n          if(q[2]>=1){\n            g=(g=a.filter(v=>v[0]==q[1]))[g.length*Math.random()|0]\n            if(typeof g === \'undefined\'){\n              q=[q[1],0,.6,2]\n            } else {\n              q=[g[0],g[1],0,0]\n            }\n          }\n        })\n      }\n      return q\n    })\n  })\n  \n  B=B.map((q,k)=>{\n    if(!q[3]||q[3]==2){\n      v1=G[q[0]][0]\n      v2=G[q[0]][1]\n      tx=X=v1[0]+(v2[0]-v1[0])*q[2]\n      ty=Y=v1[1]+(v2[1]-v1[1])*q[2]\n      tz=Z=v1[2]+(v2[2]-v1[2])*q[2]\n      q[2]+=iBv\n      R(Rl,Pt,Yw,1)\n      x.beginPath()\n      s=Math.min(12,1+lw/150/((Z+1)**1.2+(1+Math.abs(tOx)+tx)*250)**1.25)\n      x.arc(...Q(),s,0,7)\n      x.globalAlpha=1\n      x.fillStyle=bcol\n      x.fill()\n      x.beginPath()\n      s/=2\n      x.fillStyle=\'#fff8\'\n      x.arc(...Q(),s,0,7)\n      x.fill()\n      if(q[2]>=1){\n        if(q[3]==2){\n          p=A(ty,tz)+Math.PI/2\n          d=H(ty,tz)/99\n          FB=[...FB,[tx,ty,tz,grav*4,0,0,1,q[4]]]\n          q[3]=-1\n        } else {\n          q[2]=0,q[3]=1\n        }\n      }\n    }\n    return q\n  }).filter(q=>q[3]!==-1)\n\n  FB=FB.map((v,k)=>{\n    if(v[6]>0){\n      v[0]+=v[3]+=grav/4\n      v[1]+=v[4]\n      v[2]+=v[5]\n    }\n    if(v[0]>=floor){\n      v[0]=floor\n      v[6]=-1\n    }\n    tx=X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R(Rl,Pt,Yw,1)\n    x.beginPath()\n    x.globalAlpha=1\n    if(v[6]==-1){\n      s=Math.min(12,1+lw/300/((Z+1)**1.2+(1+Math.abs(tOx)+tx)*250)**1.25)\n      x.fillStyle=\'#fffa\'\n    } else {\n      s=Math.min(12,1+lw/150/((Z+1)**1.2+(1+Math.abs(tOx)+tx)*250)**1.25)\n      x.fillStyle=bcol\n    }\n    x.arc(...Q(),s,0,7)\n    x.fill()\n    x.beginPath()\n    s/=2\n    x.fillStyle=\'#fff8\'\n    x.arc(...Q(),s,0,7)\n    x.fill()\n    return v\n  })\n  \n  for(i=0;i<FB.length;++i){\n    if(FB[i][0]==floor){\n      for(j=i+1;j<FB.length;++j){\n        if(FB[j][0]==floor && H(FB[j][1]-FB[i][1],FB[j][2]-FB[i][2])<.01){\n          FB[j][6]=0\n          FB[i][6]=-1\n        }\n      }\n    }\n  }\n\n  FB=FB.filter(v=>v[6])\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  x.lineCap=x.lineJoin=\'round\'\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=f