(600091, 'https://srmcgann.github.io/assets/mWhqb.mp4', 'song = \'https://twilightparadox.com/nebula.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  ls=.5,cl=20\n  oX=0,oY=0,oZ=14+S(t*2)*6\n  Rl=0,Pt=-t,Yw=t*2\n\n  if(!t){\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    Q=q=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n    Rn=Math.random\n    B=Array(6).fill().map((v,j)=>{\n      return Array(cl**2).fill().map((v,i)=>{\n        a=[((i%cl)-cl/2+.5)*ls,((i/cl|0)-cl/2+.5)*ls,ls*cl/2]\n        return [a[(0+j)%3]*(l=j<3?-1:1),a[(1+j)%3]*l,a[(2+j)%3]*l,0]\n      })\n    })\n    bg = new Image()\n    loaded = 0\n    bg.addEventListener(\'load\', ()=>{\n      loaded = 1\n    })\n    bg.src = \'https://srmcgann.github.io/assets/Uskuz.jpg\'\n    ST=Array(1920*1).fill().map(v=>{\n      X=(Rn()-.5)*1e3\n      Y=(Rn()-.5)*1e3\n      Z=Rn()*500\n      return [X,Y,Z]\n    })\n  }\n  \n  if(loaded){\n    x.globalAlpha=.3\n    x.drawImage(bg,0,0,w=c.width,1080)\n    x.fillStyle=\'#000c\',x.fillRect(0,0,w=c.width,w)\n    x.globalAlpha=1\n  } else {\n    x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w)\n  }\n  \n  x.fillStyle=\'#fff\'\n  ST.map(v=>{\n    X=v[0]\n    Y=v[1]\n    Z=v[2]-=2\n    if(v[2]<-50) v[2]=450\n    tx=X,ty=Y,tz=Z\n    R(0,0,0,1)\n    if(Z>0){\n      h=H(X,Y,Z)\n      h2=H(tx,ty,tz)\n      x.globalAlpha=(4/(1+h**3/5e5))*(h/3099)*40*Math.min(1,h2**4/9e8)\n      x.fillRect(...Q(),s=3+Math.min(50,9e4/Z/Z),s)\n    }\n    return v\n  })\n  x.globalAlpha=1\n\n  for(m=1;m--;){\n    a=JSON.parse(JSON.stringify(B))\n    a.map((v,i)=>{\n      v.map((q,j)=>{\n        if(!(j%cl)){\n          q[3]+=B[i][j+cl-1][3]\n        } else {\n          q[3]+=B[i][j-1][3]\n        }\n        if(j%cl==cl-1) {\n          q[3]+=B[i][j-cl+1][3]\n        } else {\n          q[3]+=B[i][j+1][3]\n        }\n        if(j<cl) {\n          q[3]+=B[i][j+(cl**2)-cl*2][3]\n        } else {\n          q[3]+=B[i][j-cl][3]\n        }\n        if(j>cl**2-cl-1){\n          q[3]+=B[i][j%cl][3]\n        } else {\n          q[3]+=B[i][j+cl][3]\n        }\n        q[3]/=5.25\n      })\n    })\n\n    B=a\n  }\n\n  B.map((v,j)=>{\n    v.map(v=>{\n\n      if(Rn()<.00007) v[3]=500+Rn()*4000\n      \n      tx=v[0]\n      ty=v[1]\n      tz=v[2]\n      x.beginPath()\n      for(let i=5;--i;){\n        a=[S(p=Math.PI*2/4*i+Math.PI/4)*(d=ls/2**.5),C(p)*d,0]\n        X=tx+a[(0+j)%3]*(l=j<3?-1.02:1.02)\n        Y=ty+a[(1+j)%3]*l\n        Z=tz+a[(2+j)%3]*l\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n      }\n      x.closePath()\n      x.fillStyle=`hsla(${Math.min(110,v[3]*10)-55},99%,${v[3]**.3*35}%,${Math.min(1,v[3]/12)})`\n      x.fill()\n      //x.strokeStyle=\'#f004\'\n      //x.lineWidth=9/Z/Z\n      //x.stroke()\n    })\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  x.lineCap=x.lineJoin=\'round\'\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}', '<canvas id=c>', 'nebula', 1, 'cantelope', '2022-04-09 14:26:46', '[600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 581, 'https://code.dweet.net/thumbs/2f4f39bab0b6efc0dc722ee5d906af43.jpg', 29, 0),
