(600095, '', 'c=document.querySelector(\'#c\')\nc.width=1920\nc.height=1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\nDraw=()=>{\n      x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w)\n\n      if(!t){\n				Rn=Math.random\n				Q=q=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n			  R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m){X+=oX,Y+=oY,Z+=oZ}}\n			  \n				B=Array(17).fill().map(v=>{\n					a=[]\n					ls=1\n					tx1=(Rn()-.5)*12\n					ty1=(Rn()-.5)*16\n					tz1=(Rn()-.5)*16\n					for(j=3;j--;){\n						tx=tx1+S(p=Math.PI*2/3*j+Math.PI/3)*ls\n						ty=ty1+C(p)*ls\n					  for(i=42;i-->8;){\n              X=S(p=Math.PI*2/50*i)*ls\n						  Y=C(p)*ls\n						  Z=tz1\n							R(Math.PI*2/3*j+1.05+Math.PI,0,0)\n							X1=tx+X,Y1=ty+Y,Z1=Z\n						  X=S(p=Math.PI*2/50*(i+1))*ls\n						  Y=C(p)*ls\n						  Z=tz1\n							R(Math.PI*2/3*j+1.05+Math.PI,0,0)\n              X2=tx+X,Y2=ty+Y,Z2=Z\n						  a=[...a,[X1,Y1,Z1,X2,Y2,Z2,tx1,ty1+1,tz1]]\n					  }\n					}\n					return a\n			  })\n      }\n\n      oX=0,oY=0,oZ=10\n			Rl=0,Pt=0,Yw=t\n      B.map(v=>{\n        x.beginPath()\n				X=v[0][6]\n				Y=v[0][7]\n        Z=v[0][8]\n				R(Rl,Pt,Yw,1)\n				x.lineTo(...Q())\n				Y+=3\n				x.lineTo(...Q())\n				x.strokeStyle=\'#4f86\'\n				x.lineWidth=1500/Z/Z\n				x.stroke()\n				x.beginPath()\n			  v.map(q=>{\n				  X=q[0]\n					Y=q[1]\n					Z=q[2]\n					R(Rl,Pt,Yw,1)\n					//x.beginPath()\n					x.lineTo(...Q())\n					/*\n					X=q[3]\n					Y=q[4]\n					Z=q[5]\n					R(Rl,Pt,Yw,1)\n					x.lineTo(...Q())\n				  */\n				})\n			  x.fillStyle=\'#4f86\'\n			  //x.lineWidth=800/Z/Z\n				x.fill()\n			})\nt+=1/60\nrequestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  margin:0;\n  height:100vh;\n}\n#c{\n  width:100%;\n  height:100%;\n}', '<canvas id=c>', 'clovers', 1, 'cantelope', '2022-04-09 14:26:46', '[600094]', 50, '', 0, 0),
(600096, '', 'c=document.querySelector(\'#c\')\nc.width=1920\nc.height=1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\nDraw=()=>{\n      x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w)\n      x.lineJoin=x.lineCap=\'round\'\n\n      if(!t){\n				Rn=Math.random\n				Q=q=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n			  R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m){X+=oX,Y+=oY,Z+=oZ}}\n			  cl=2,sp=4,sd=3\nfor(cb=[],j=6;j--;)for(i=4;i--;)cb=[...cb,[(a=[S(p=Math.PI*2/4*i+Math.PI/4)*(d=(2**.5)),C(p)*d,1])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n\n      oX=0,oY=0,oZ=12\n			Rl=0,Pt=-t/2,Yw=t\n      sp=4+S(t*2)*4\n			for(m=sd;m--;){\n				Array(cl**3).fill().map((v,k)=>{\n				  tx=((k%cl)-cl/2+.5)*sp\n				  ty=((Math.floor(k/cl)%cl)-cl/2+.5)*sp\n			    tz=((Math.floor(k/cl/cl)%cl)-cl/2+.5)*sp\n				  cb.map((q,i)=>{\n				    X=tx+q[0]*(d1=1/sd*(m+(t*3)%1)*2)\n					  Y=ty+q[1]*d1\n					  Z=tz+q[2]*d1\n					  R(Rl,Pt,Yw,1)\n            if(!(i%4)) x.beginPath()\n					  x.lineTo(...Q())\n            if(i%4==3){\n					    x.closePath()\n						  x.lineWidth=700/Z/Z\n						  x.strokeStyle=`hsla(${d1*300+t*200},99%,${100-(1+d1**5)*2}%,${1-(1+d1**4)/10})`\n						  x.stroke()\n					  }\n				  })\n			  })\n			}\nt+=1/60\nrequestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  margin:0;\n  height:100vh;\n}\n#c{\n  width:100%;\n  height:100%;\n}', '<canvas id=c>', 'cube dance', 1, 'cantelope', '2022-04-09 14:26:46', '[600095,600094]', 34, '', 0, 1),
(600097, '', 'c=document.querySelector(\'#c\')\nc.width=1920\nc.height=1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\nDraw=()=>{\n      x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w)\n\n      if(!t){\n				Rn=Math.random\n				Q=q=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n			  R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m){X+=oX,Y+=oY,Z+=oZ}}\n			  x.lineJoin=x.lineCap=\'round\'\n		    for(cb=[],j=6;j--;)for(i=4;i--;)cb=[...cb,[(a=[S(p=Math.PI*2/4*i+Math.PI/4)*(d=(2**.5)),C(p)*d,1])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n			  iBPc=1,iBPv=1,iBPr=3\n			}\n\n      cl=4\n			rw=10\n\n      if(!(Math.floor(t*60)%(60*2))){\n			  B=Array(cl*rw).fill().map((v,i)=>{\n					X=i%cl\n					Y=Math.floor(i/cl)-rw/2+.5\n					Z=0\n				  return [X,Y,Z,0,0,0,1]\n				})\n				BP=Array(iBPc).fill().map(v=>{\n				  X=-20\n					Y=0\n					Z=0\n					return [X,Y,Z,S(p=Math.PI/2+(Rn()-.5)*.5)*iBPv,C(p)*iBPv,0,iBPr]\n				})\n			}\n\n			oX=0,oY=0,oZ=12\n			Rl=0,Pt=0,Yw=0\n\n      B.map((v,i)=>{\n			  X=v[0]+=v[3]\n				Y=v[1]+=v[4]\n				Z=v[2]+=v[5]\n				B.map((q,j)=>{\n				  if(i!=j){\n						X2=q[0]\n						Y2=q[1]\n						Z2=q[2]\n						d=Math.hypot(X-X2,Y-Y2)\n						if(d<(l=(q[6]+v[6])/2)){\n						  n=Math.abs(l-d)/9\n							p=Math.atan2(X-X2,Y-Y2)\n							v[0]=q[0]+S(p)*l\n							v[1]=q[1]+C(p)*l\n							v[3]+=S(p)*n*(1+q[6]/3)\n							v[4]+=C(p)*n*(1+q[6]/3)\n							q[3]-=S(p)*n*(1+v[6]/3)\n							q[4]-=C(p)*n*(1+v[6]/3)\n						}\n					}\n				})\n				BP.map(q=>{\n				  X2=q[0]\n					Y2=q[1]\n					Z2=q[2]\n					d=Math.hypot(X-X2,Y-Y2)\n          if(d<(l=(q[6]+v[6])/2)){\n					  n=Math.abs(l-d)/9\n						p=Math.atan2(X-X2,Y-Y2)\n						v[0]=q[0]+S(p)*l\n						v[1]=q[1]+C(p)*l\n						v[3]+=S(p)*n*(1+q[6]/3)\n						v[4]+=C(p)*n*(1+q[6]/3)\n						q[3]-=S(p)*n*(1+v[6]/3)\n						q[4]-=C(p)*n*(1+v[6]/3)\n					}\n				})\n				R(Rl,Pt,Yw,1)\n				x.beginPath()\n				x.arc(...Q(),350/Z*v[6],0,7)\n				x.fillStyle=\'#4f86\'\n				x.fill()\n			})\n			BP.map(v=>{\n			  X=v[0]+=v[3]\n				Y=v[1]+=v[4]\n				Z=v[2]+=v[5]\n				R(Rl,Pt,Yw,1)\n				x.beginPath()\n				x.arc(...Q(),350/Z*v[6],0,7)\n				x.fillStyle=\'#84f6\'\n				x.fill()\n			})\nt+=1/60\nrequestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  margin:0;\n  height:100vh;\n}\n#c{\n  width:100%;\n  height:100%;\n}', '<canvas id=c>', 'collisons', 1, 'cantelope', '2022-04-09 14:26:46', '[600096,600095,600094]', 44, '', 0, 0),
(600098, '', 'c=document.querySelector(\'#c\')\nc.width=1920\nc.height=1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\nDraw=()=>{      x.fillStyle=\'#0004\',x.fillRect(0,0,w=c.width,w)\n\n      if(!t){\n				Rn=Math.random\n				Q=q=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n			  R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m){X+=oX,Y+=oY,Z+=oZ}}\n			  x.lineJoin=x.lineCap=\'round\'\n		    for(cb=[],j=6;j--;)for(i=4;i--;)cb=[...cb,[(a=[S(p=Math.PI*2/4*i+Math.PI/4)*(d=(2**.5)),C(p)*d,1])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n			  ls=.25,Ys=2\n			  B=Array(w/6).fill().map(v=>{\n					Y=-(Ys*(Rn()**.5-.5))-Ys/2\n				  X=S(p=Math.PI*2*(Rn()-.5))*(d=((2-(Y/Ys+1)*2)**2*ls)*Rn()**.5)\n					Z=C(p)*d\n					return [X,Y,Z]\n				})\n			}\n\n      oX=0,oY=0,oZ=4+S(t*3)*2\n			Rl=t/4,Pt=-t/1.5,Yw=t\n\n      B.map(v=>{\n 		    tx=X=v[0]\n 			  ty=Y=v[1]\n 			  tz=Z=v[2]\n				d=(1+Math.hypot(tx,tz))**5*20\n				R(0,0,20/d)\n				v[0]=X,v[1]=Y,v[2]=Z\n        for(m=6;m--;){\n					X=tx,Y=ty,Z=tz\n				  switch(m){\n						case 0: R(0,Math.PI,0); break\n						case 1: R(Math.PI/2,0,0); break\n						case 2: R(-Math.PI/2,0,0); break\n						case 3: R(-Math.PI/2,0,Math.PI/2); break\n						case 4: R(-Math.PI/2,0,-Math.PI/2); break\n					}\n					R(Rl,Pt,Yw,1)\n					s=Math.min(50,3+70/Z/Z)\n					x.fillStyle=\'#fff8\'\n					l=Q()\n					x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n				}\n		  })\n\nt+=1/60\nrequestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  margin:0;\n  height:100vh;\n}\n#c{\n  width:100%;\n  height:100%;\n}', '<canvas id=c>', 'vortices', 1, 'cantelope', '2022-04-09 14:26:46', '[600097,600096,600095,600094]', 42, '', 0, 0),
(600099, 'https://srmcgann.github.io/assets/ynvL7.mp4', 'song = \'https://twilightparadox.com/wells.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(!t){\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    Q=q=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n    Rn=Math.random\n    loaded=false\n    bgimg=new Image()\n    bgimg.addEventListener(\'load\',()=>{\n      loaded=true\n    })\n    bgimg.src=\'/proxy.php?url=https://srmcgann.github.io/assets/2abaGf.jpg\'\n    Rn=Math.random\n    Q=q=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m){X+=oX,Y+=oY,Z+=oZ}}\n    x.lineJoin=x.lineCap=\'round\'\n    for(cb=[],j=6;j--;)for(i=4;i--;)cb=[...cb,[(a=[S(p=Math.PI*2/4*i+Math.PI/4)*(d=(2**.5)),C(p)*d,1])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n    ls=.25,Ys=2\n    B=Array(1920/2).fill().map(v=>{\n      Y=-(Ys*(Rn()**.5-.6))-Ys/2\n      X=S(p=Math.PI*2*(Rn()-.5))*(d=((2-(Y/Ys+1)*2)**3*ls)*Rn()**.5)\n      Z=C(p)*d\n      return [X,Y*1.5,Z]\n    })\n  }\n\n  oX=0,oY=0,oZ=3+S(t/2)*2.5\n  Rl=t/6,Pt=-t/2,Yw=t/2.5\n\n  if(loaded){\n    x.globalAlpha=.2\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0001\',x.fillRect(0,0,w=c.width,w)\n  } else {\n    x.fillStyle=\'#0002\',x.fillRect(0,0,w=c.width,w)\n  }\n  \n  B.map(v=>{\n    tx=X=v[0]\n    ty=Y=v[1]\n    tz=Z=v[2]\n    d1=(1+Math.hypot(tx,tz))**6*40\n    R(0,0,50/d1)\n    v[0]=X,v[1]=Y,v[2]=Z\n    for(m=6;m--;){\n      X=tx,Y=ty,Z=tz\n      switch(m){\n        case 0: R(0,Math.PI,0); break\n        case 1: R(Math.PI/2,0,0); break\n        case 2: R(-Math.PI/2,0,0); break\n        case 3: R(-Math.PI/2,0,Math.PI/2); break\n        case 4: R(-Math.PI/2,0,-Math.PI/2); break\n      }\n      R(Rl,Pt,Yw,1)\n      s=Math.min(150,1+100/Z/Z)\n      x.fillStyle=`hsla(${d1/30-t*600},99%,${Math.max(55,98-d1/200*(2+S(t*2)*2))}%,${.085+Math.min(.15,d1/20000)}`\n      l=Q()\n      if(Z>0)x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n    }\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  x.lineCap=x.lineJoin=\'round\'\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}', '<canvas id=c>', 'wells', 1, 'cantelope', '2022-04-09 14:26:46', '[600092,600091,600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 541, 'https://code.dweet.net/thumbs/d09a859a99d79a34e81fff9b44a60d09.jpg', 35, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600100, 'https://srmcgann.github.io/assets/1Bs2u.mp4', 'song = \'https://twilightparadox.com/streets.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(!t){\n    bgimg = new Image()\n    loaded=false\n    bgimg.addEventListener(\'load\',()=>{\n      loaded=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/24xfD1.jpg\'\n    x.lineJoin=x.lineCap=\'round\'\n  }\n  if(loaded){\n    x.globalAlpha=.2,x.drawImage(bgimg,0,0,w=1920,h=1080)\n    x.globalAlpha=1\n  }else{\n    x.fillStyle=\'#0006\',x.fillRect(0,0,w=1920,h=1080)\n  }\n  P=t?P:[[[[960,540,0]]],[[[960,540,0]]],[[[960,540,0]]],[[[960,540,0]]],[[[960,540,0]]]]\n  for(k=4;k--;){\n    for(j=3;j--;){\n      x.lineWidth=2+(6*(((1+j*1.5)*2+(.01+k*1.5))+.1))**2.5/400\n      x.strokeStyle=`hsl(${(j*2+k)*30+t*300},99%,${110-50*((j*2+(.1+k)/4)/(7+S(t)*3))}%,${.005+5000/((j*250+(k+1)*400)**2.5/150)}`\n      P[k]=P[k].map(q=>{\n        x.beginPath()\n        q.map((v,j)=>{\n          x.lineTo(...v)\n        })\n        x.stroke()\n        X=q[0][0],Y=q[0][1],g=q[0][2]\n        if((r=Math.random)()<.2+S(t*2+Math.PI*2/3*k)/5)g=r()*4|0\n        X+=S(p=Math.PI*2/4*g)*14,Y+=C(p)*14\n        q=[[X<0?0:X>w?w:X,Y<0?0:Y>h?h:Y,g],...q].filter((v,i)=>i<50)\n        return q\n      })\n      if(P[k].length<20)P[k]=[[[X,Y,g]],...P[k]]\n    }\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  x.lineCap=x.lineJoin=\'round\'\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}', '<canvas id=c>', 'streets', 1, 'cantelope', '2022-04-09 14:26:47', '[600099,600092,600091,600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 509, 'https://code.dweet.net/thumbs/12d7157531075a6371ec8586e3d5e3fb.jpg', 26, 0),
