(600108, 'https://srmcgann.github.io/assets/1pGAcI.mp4', 'song = \'https://twilightparadox.com/flux.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(!t){\n    Rn = Math.random\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    Q=q=>[c.width/2+X/Z*600,c.height/2+Y/Z*600]\n  }\n\n  if(!t){\n    bgimg = new Image()\n    go = false\n    bgimg.addEventListener(\'load\', ()=>{\n      go = true\n    })\n    bgimg.src = \'https://srmcgann.github.io/assets/1FIjlE.jpg\'\n    iPv = 1, iPc = 2e3, iBr = .2, iBc = 6, iBv = 1, brsp = 30\n    cl = 180/2\n    rw = 120/2\n    br = 3\n    G=Array(br).fill().map((v, j)=>{\n      P=Array(iPc).fill().map(v=>{\n        X = (Rn() - .5) * cl\n        Y = (Rn() - .5) * rw \n        Z = ((-br / 2 + .5)+ j) * brsp\n        VX = iPv\n        VY = 0\n        VZ = 0\n        return [X, Y, Z, VX, VY, VZ, X, Y, Z, VX, VY, VZ]\n      })\n      B=Array(iBc).fill().map(v=>{\n        X = iBr + (Rn() - .5) * (cl - iBr * 4)\n        Y = iBr + (Rn() - .5) * (rw - iBr * 4)\n        Z = ((-br / 2 + .5) + j) * brsp\n        VX = S(p=Math.PI*2*Rn())*iBv\n        VY = C(p)*iBv\n        VZ = 0\n        return [X, Y, Z, VX, VY, VZ]\n      })\n      return [P, B]\n    })\n  }\n\n  if(go){\n    x.globalAlpha = .6\n    x.drawImage(bgimg, 0, 0, c.width, c.height)\n    x.fillStyle=\'#0002\',x.fillRect(0,0,w=c.width,w)\n    x.globalAlpha = 1\n  } else {\n    x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w)\n  }\n\n  oX = 0, oY = 0, oZ = (120 - S(t) * 40) / 2\n  Rl = 0, Pt = -t/2, Yw = t\n  \n  G.map((q,k)=>{\n    q[1].map(v=>{\n      X = v[0] += v[3]\n      Y = v[1