(600111, 'https://srmcgann.github.io/assets/1f3xIM.mp4', 'song = \'https://twilightparadox.com/geoflux.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(!t){\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    Rn=Math.random\n    Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n  }\n\n    if(!t){\n      mode=0\n      ST=Array(1920*4).fill().map(v=>{\n        X=(Rn()-.5)*1e3\n        Y=(Rn()-.5)*1e3\n        Z=Rn()*500\n        return [X,Y,Z]\n      })\n      x.lineJoin=x.lineCap=\'round\'\n    }\n\n    if(!((t*60|0)%(60*6))){\n      switch(mode){\n        case 0: iBd=30,iBc=6,iPc=3,iBv=0,imsv=32,G=0; break\n        case 1: iBd=12,iBc=3,iPc=16,iBv=5,imsv=12,G=14; break\n        case 2: iBd=20,iBc=6,iPc=4,iBv=6,imsv=10,G=50; break\n        case 3: iBd=12,iBc=12,iPc=3,iBv=5,imsv=8,G=150; break\n        case 4: iBd=24,iBc=5,iPc=6,iBv=8,imsv=12,G=50; break\n        case 5: iBd=20,iBc=3,iPc=12,iBv=6,imsv=8,G=20; break\n        case 6: iBd=12,iBc=2,iPc=32,iBv=8,imsv=3,G=30; break\n        case 7: iBd=12,iBc=3,iPc=12,iBv=0,imsv=4,G=0; break\n      }\n      mode=(mode+1)%8\n      B=Array(iBc).fill().map(v=>{\n        X=(Rn()-.5)*G\n        Y=(Rn()-.5)*G\n        Z=(Rn()-.5)*G\n        vx=(Rn()-.5)*iBv\n        vy=(Rn()-.5)*iBv\n        vz=(Rn()-.5)*iBv\n        return [X,Y,Z,[],vx,vy,vz]\n      })\n      for(i=iPc;i--;){\n        B=B.map(v=>{\n          X=Rn()-.5\n          Y=Rn()-.5\n          Z=Rn()-.5\n          d=Math.hypot(X,Y,Z)\n          X=X/d*iBd\n          Y=Y/d*iBd\n          Z=Z/d*iBd\n          v[3].push([X,Y,Z,0,[]])\n          return v\n        })\n      }\n      ms=[]\n    }\n    \n    if(!((t*60|0)%1)){\n      B=B.map(v=>{\n        tx=v[0]\n        ty=v[1]\n        tz=v[2]\n        v[3]=v[3].map(q=>{\n          X=tx+q[0]\n          Y=ty+q[1]\n          Z=tz+q[2]\n          d=Math.hypot(q[0],q[1],q[2])\n          vx=q[0]/d*imsv\n          vy=q[1]/d*imsv\n          vz=q[2]/d*imsv\n          q[4].push([X,Y,Z,vx,vy,vz,1])\n          return q\n        })\n        return v\n      })\n    }\n    \n    oX=0, oY=0, oZ=375+S(t)*150\n    Rl=t/8, Pt=-t/3, Yw=S(t/6)*8\n    \n    g=x.createLinearGradient(0,0,0,1080)\n    g.addColorStop(0,\'#0004\')\n    g.addColorStop(1,\'#2064\')\n    x.fillStyle=g\n    x.fillRect(0,0,w=c.width,1080)\n\n    x.fillStyle=\'#fff\'\n    x.globalAlpha=1\n    ST.map(v=>{\n      X=v[0]\n      Y=v[1]\n      Z=v[2]-=2\n      R(.01*S(t/2),0,0,0)\n      v[0]=X\n      v[1]=Y\n      v[2]=Z\n      if(v[2]<-50) v[2]=450\n      tx=X,ty=Y,tz=Z\n      if(Z>0){\n        h=Math.hypot(X,Y,Z)\n        h2=Math.hypot(tx,ty,tz)\n        x.globalAlpha=(15/(1+h**3.2/2e5))*(h/3099)*40*Math.min(1,h2**4/9e8)\n        x.fillRect(...Q(),s=3+Math.min(50,6e4/Z/Z),s)\n      }\n      return v\n    })\n    x.globalAlpha=1\n\n    B=B.map(v=>{\n      B.map(q=>{\n        d=(1+Math.hypot(q[0]-v[0],q[1]-v[1],q[2]-v[2]))**2\n        v[4]+=(q[0]-v[0])/40/d\n        v[5]+=(q[1]-v[1])/40/d\n        v[6]+=(q[2]-v[2])/40/d\n      })\n      tx=v[0]+=v[4]-=v[0]/4e3\n      ty=v[1]+=v[5]-=v[1]/4e3\n      tz=v[2]+=v[6]-=v[2]/4e3\n      v[3]=v[3].map(q=>{\n        X=q[0]\n        Y=q[1]\n        Z=q[2]\n        mind=6e6\n        v[3].map((n, j)=>{\n          d=Math.hypot(q[0]-n[0],q[1]-n[1],q[2]-n[2])\n          if(d&&d<mind)mind=d\n          d=(1+d)**2\n          X+=(q[0]-n[0])*1e16/d\n          Y+=(q[1]-n[1])*1e16/d\n          Z+=(q[2]-n[2])*1e16/d\n        })\n        q[3]=mind\n        \n        d=Math.hypot(X,Y,Z)\n        X=X/d*iBd\n        Y=Y/d*iBd\n        Z=Z/d*iBd\n        q[0]=X\n        q[1]=Y\n        q[2]=Z\n        \n        X+=tx\n        Y+=ty\n        Z+=tz\n        R(Rl,Pt,Yw,1)\n        x.fillStyle=\'#0ffa\'\n        s=2000/Z\n        l=Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        return q\n      })\n      return v\n    })\n\n\n    x.strokeStyle=\'#affc\'\n    B.map((v,m)=>{\n      tx=v[0]\n      ty=v[1]\n      tz=v[2]\n      v[3].map((q,i)=>{\n        q[4]=q[4].map((v,j)=>{\n            B.map((q,j)=>{\n              if(m!=j){\n                d=(1+Math.hypot(q[0]-v[0],q[1]-v[1],q[2]-v[2]))**2.5\n                v[3]+=(q[0]-v[0])*100/d\n                v[4]+=(q[1]-v[1])*100/d\n                v[5]+=(q[2]-v[2])*100/d\n              }\n            })\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            R(Rl,Pt,Yw,1)\n            s=(1+200/Z*(v[6]-.3))**2\n            v[6]/=1.05\n          if(j){\n            x.beginPath()\n            if(Z>0)x.lineTo(...Q())\n            X=q[4][j-1][0]\n            Y=q[4][j-1][1]\n            Z=q[4][j-1][2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0)x.lineTo(...Q())\n            x.strokeStyle=`hsla(${360/2/q[4].length*j-t*100},99%,${50+50/q[4].length*j**2/16}%,.05)`\n            x.lineWidth=Math.min(20, 1800/Z*s)\n            x.stroke()\n          }\n          v[0]+=v[3]\n          v[1]+=v[4]\n          v[2]+=v[5]\n          return v\n        }).filter(v=>{\n          return v[6]>.3\n        })\n        x.beginPath()\n        v[3].map((n,j)=>{\n          if(j>i){\n            d=Math.hypot(q[0]-n[0],q[1]-n[1],q[2]-n[2])\n            if(d<q[3]*1.25){\n              X=tx+q[0]\n              Y=ty+q[1]\n              Z=tz+q[2]\n              R(Rl,Pt,Yw,1)\n              if(Z>0)x.moveTo(...Q())\n              X=tx+n[0]\n              Y=ty+n[1]\n              Z=tz+n[2]\n              R(Rl,Pt,Yw,1)\n              if(Z>0)x.lineTo(...Q())\n            }\n          }\n        })\n        X=tx,Y=ty,Z=tz\n        R(Rl,Pt,Yw,1)\n        x.strokeStyle=\'#0f42\'\n        x.lineWidth=3000/Z\n        x.stroke()\n        x.strokeStyle=\'#fff8\'\n        x.lineWidth=1+200/Z\n        x.stroke()\n      })\n    })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}', '<canvas id=c>', 'geoflux', 1, 'cantelope', '2022-04-09 14:26:47', '[600110,600109,600108,600104,600103,600102,600101,600100,600099,600092,600091,600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 338, 'https://code.dweet.net/thumbs/101b310689f6a72c6060ddf689f4edf8.jpg', 8, 0),
(600112, 'https://srmcgann.github.io/assets/103LTL.mp4', '  song = \'https://twilightparadox.com/synthesis.mp3\'\n  vid = \'\'\n  recordingStarted=playing=vidplaying=analyzerSetup=0\n\n  fftSize = 64\n\n  c=document.querySelector(\'#c\')\n  x=c.getContext(\'2d\')\n  c.width=c.clientWidth\n  c.height=c.clientHeight\n  canvas2=c.cloneNode()\n  x2=canvas2.getContext(\'2d\')\n  S=Math.sin\n  C=Math.cos\n  t=0\n\n  Draw=()=>{\n\n    if(!t){\n      R=(Rl,Pt,Yw,o)=>{\n        X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n        if(o)X+=oX,Y+=oY,Z+=oZ\n      }\n      Rn=Math.random\n      Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    }\n\n    if(!t){\n      go=false\n      pulses=[\n        {\n          src: \'https://srmcgann.github.io/assets/AOOmI.png\'\n        ,\n          img: new Image()\n        },\n        {\n          src: \'https://srmcgann.github.io/assets/1M85UA.png\'\n        ,\n          img: new Image()\n        },\n        {\n          src: \'https://srmcgann.github.io/assets/s8xSI.png\'\n        ,\n          img: new Image()\n        }\n      ]\n      \n      pulses.map((v, i)=>{\n        v.img.src = v.src\n        v.idx = i\n      })\n        \n      bgimg = new Image()\n      go=false\n      bgimg.addEventListener(\'load\',()=>{\n        go=true\n      })\n      bgimg.src = \'https://srmcgann.github.io/assets/OR2SY.jpg\'\n      B=[], G=150\n    }\n    \n    if(go){\n      x.globalAlpha=.1\n      x.drawImage(bgimg,c.width/2-bgimg.width/2,0,bgimg.width,1080)\n      x.globalAlpha=1\n      x.fillStyle=\'#0011\',x.fillRect(0,0,w=c.width,w)\n      for(m=2;m--;)B=[...B, [(Rn()-.5)*G*3,(Rn()-.5)*G*2,Rn()*G*5,0,Rn()*pulses.length|0]]\n\n      oX=0,oY=0,oZ=0\n      Rl=0,Pt=0,Yw=0\n\n      B.map(v=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R(Rl,Pt,Yw,1)\n        s=((v[3]+=.001))*22**4\n        x.globalAlpha=1/((1+s)**4/9999999999999999)\n        s/=Z\n        l=Q()\n        x.drawImage(pulses[v[4]].img,l[0]-s/2,l[1]-s/2,s,s)\n        x.globalAlpha=1\n        v[2]-=1\n      })\n      B=B.filter(v=>v[3]<.16&&v[2]>0)\n    } else {\n      x.fillStyle=\'#0014\',x.fillRect(0,0,w=c.width,w)\n    }\n\n    t+=1/60\n    requestAnimationFrame(Draw)\n  }\n\n  setupAnalyzerAndContent = () => {\n    analyzerSetup=1\n    loaded=0\n    mp3 = new Audio()\n    mp3.crossOrigin = \"anonymous\"\n    mp3.src = song\n    mp3.loop = true\n    if(!mp3)loaded=1\n    mp3.addEventListener(\'canplay\',()=>{\n      if(!playing){\n        loaded=playing=1\n        audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n        analyser = audioCtx.createAnalyser()\n        source = audioCtx.createMediaElementSource(mp3)\n        source.connect(analyser)\n        analyser.connect(audioCtx.destination)\n        analyser.fftSize=fftSize\n        trim=analyser.fftSize*.25\n        bufferLength = analyser.frequencyBinCount\n        mp3.loop=true      \n        mp3.play()\n        Draw()\n        if(vid){\n          bgvid = document.createElement(\'video\')\n          bgvid.src = vid\n          bgvid.addEventListener(\'canplay\',()=>{\n            if(!vidplaying){\n              vidplaying=1\n              bgvid.loop=true\n              bgvid.muted=true\n              bgvid.play()\n            }\n          })\n        }\n      }\n    })\n  }\n\n  setupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}', '<canvas id=c>', 'synthesis', 1, 'cantelope', '2022-04-09 14:26:47', '[600111,600110,600109,600108,600104,600103,600102,600101,600100,600099,600092,600091,600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 316, 'https://code.dweet.net/thumbs/89a6eab44361418c825d9d82b4700612.jpg', 19, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600113, 'https://srmcgann.github.io/assets/CQ8rn.mp4', '  song = \'https://twilightparadox.com/heavenly conduit.mp3\'\n  vid = \'\'\n  recordingStarted=playing=vidplaying=analyzerSetup=0\n\n  fftSize = 64\n\n  c=document.querySelector(\'#c\')\n  x=c.getContext(\'2d\')\n  c.width=c.clientWidth\n  c.height=c.clientHeight\n  canvas2=c.cloneNode()\n  x2=canvas2.getContext(\'2d\')\n  S=Math.sin\n  C=Math.cos\n  t=0\n\n  Draw=()=>{\n\n    if(!t){\n      R=(Rl,Pt,Yw,o)=>{\n        X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n        if(o)X+=oX,Y+=oY,Z+=oZ\n      }\n      Rn=Math.random\n      Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    }\n\n   if(!t){\n    rw=14,col=80\n    x.lineJoin=x.lineCap=\'round\'\n    bgimg = new Image()\n    go=false\n    bgimg.addEventListener(\'load\',()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/ma2ha.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.3\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0004\',x.fillRect(0,0,w=c.width,w)\n  } else {\n    x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w)\n  }\n  B=[]\n  for(i=rw*col;i--;){\n    j=i/rw|0\n    ls=4+(8+S(Math.PI*2/col*4*j-t*6)*8)**2.5/120\n    X=S(p=Math.PI*2/rw*i)*ls*(l=S(q=Math.PI*2/col*j))+l*50\n    Y=C(p)*ls\n    Z=C(q)*50+S(p)*C(q)*ls\n    B = [...B, [X,Y,Z]]\n  }\n  \n  Rl=Math.PI/2,Pt=t/8,Yw=t/3\n  oX=0,oY=-51,oZ=20-C(t/1.5)*20\n  \n  tt=-t/2\n  \n  B.map((v,i)=>{\n    //if(!(i%rw)) x.beginPath()\n    x.beginPath()\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R(0,0,tt)\n    R(Rl,Pt,Yw,1)\n    lz=Z\n    if(Y>-45&&Z>0){\n      x.lineTo(...Q())\n      if((i+1)%rw){\n        X=B[i+1][0]\n        Y=B[i+1][1]\n        Z=B[i+1][2]\n        R(0,0,tt)\n        R(Rl,Pt,Yw,1)\n        if(Y>-45&&Z>0)x.lineTo(...Q())\n      } else {\n        X=B[i-rw+1][0]\n        Y=B[i-rw+1][1]\n        Z=B[i-rw+1][2]\n        R(0,0,tt)\n        R(Rl,Pt,Yw,1)\n        if(Y>-45&&Z>0)x.lineTo(...Q())\n      }\n      if(1&&i<B.length-rw-1){\n        if((i+1)%(rw*2)){\n          X=B[i+rw+1][0]\n          Y=B[i+rw+1][1]\n          Z=B[i+rw+1][2]\n          R(0,0,tt)\n          R(Rl,Pt,Yw,1)\n          if(Y>-45&&Z>0)x.lineTo(...Q())\n        }\n      } else {\n        X=B[(i+rw+1)%rw][0]\n        Y=B[(i+rw+1)%rw][1]\n        Z=B[(i+rw+1)%rw][2]\n        R(0,0,tt)\n        R(Rl,Pt,Yw,1)\n        if(Y>-45&&Z>.15)x.lineTo(...Q())\n      }\n    }\n    //if(i%rw==rw-1){\n      x.strokeStyle=`hsla(${200},99%,99%,${.35-((1+Math.min(0,Y/2+8))**2/200)})`\n      x.lineWidth=Math.min(50, 1+150/lz)\n      x.stroke()\n      x.strokeStyle=`hsla(${180+t*200},99%,65%,${.07-((1+Math.min(0,Y/2+8))**2/200)})`\n      x.lineWidth=Math.min(100, 1+1000/lz)\n      x.stroke()\n   // }\n  })\n\n    t+=1/60\n    requestAnimationFrame(Draw)\n  }\n\n  setupAnalyzerAndContent = () => {\n    analyzerSetup=1\n    loaded=0\n    mp3 = new Audio()\n    mp3.crossOrigin = \"anonymous\"\n    mp3.src = song\n    mp3.loop = true\n    if(!mp3)loaded=1\n    mp3.addEventListener(\'canplay\',()=>{\n      if(!playing){\n        loaded=playing=1\n        audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n        analyser = audioCtx.createAnalyser()\n        source = audioCtx.createMediaElementSource(mp3)\n        source.connect(analyser)\n        analyser.connect(audioCtx.destination)\n        analyser.fftSize=fftSize\n        trim=analyser.fftSize*.25\n        bufferLength = analyser.frequencyBinCount\n        mp3.loop=true      \n        mp3.play()\n        Draw()\n        if(vid){\n          bgvid = document.createElement(\'video\')\n          bgvid.src = vid\n          bgvid.addEventListener(\'canplay\',()=>{\n            if(!vidplaying){\n              vidplaying=1\n              bgvid.loop=true\n              bgvid.muted=true\n              bgvid.play()\n            }\n          })\n        }\n      }\n    })\n  }\n\n  setupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}', '<canvas id=c>', 'heavenly conduit', 1, 'cantelope', '2022-04-09 14:26:47', '[600112,600111,600110,600109,600108,600104,600103,600102,600101,600100,600099,600092,600091,600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 302, 'https://code.dweet.net/thumbs/ad08b9c28539e5023d398868536ec334.jpg', 40, 0),
