  v[5]+=e/((1+d)**4)*grav\n      })\n      v[0]+=v[3]\n      v[1]+=v[4]\n      v[2]+=v[5]\n      v[3]/=1.025\n      v[4]/=1.025\n      v[5]/=1.025\n      X=v[0],Y=v[1],Z=v[2]\n      R(Rl,0,Yw)\n      R(Rl,Pt,0)\n      X+=oX,Y+=oY,Z+=oZ\n      x.fillStyle=`#2f85`\n      s=v[6]*20/Z/Z\n      v[6]-=decay\n      l=[...Q()]\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n    })\n\n    P=P.filter(v=>v[6]>10)\n\n    B.map(v=>{\n      X=v[0],Y=v[1],Z=v[2]\n      Y+=C(t)/40\n      R(0,0,iBtheta)\n      v[0]=X,v[1]=Y,v[2]=Z\n      R(Rl,0,Yw)\n      R(Rl,Pt,0)\n      X+=oX,Y+=oY,Z+=oZ\n      if(Z>0){\n        x.beginPath()\n        x.fillStyle=\'#24f8\'\n        x.arc(...Q(),5000/Z/Z,0,7)\n        x.fill()\n      }\n    })\n  \n    t+=1/60\n    requestAnimationFrame(Draw)\n  }\n\n  setupAnalyzerAndContent = () => {\n    analyzerSetup=1\n    loaded=0\n    mp3 = new Audio()\n    mp3.crossOrigin = \"anonymous\"\n    mp3.src = song\n    mp3.loop = true\n    if(!mp3)loaded=1\n    mp3.addEventListener(\'canplay\',()=>{\n      if(!playing){\n        loaded=playing=1\n        audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n        analyser = audioCtx.createAnalyser()\n        source = audioCtx.createMediaElementSource(mp3)\n        source.connect(analyser)\n        analyser.connect(audioCtx.destination)\n        analyser.fftSize=fftSize\n        trim=analyser.fftSize*.25\n        bufferLength = analyser.frequencyBinCount\n        mp3.loop=true      \n        mp3.play()\n        Draw()\n        if(vid){\n          bgvid = document.createElement(\'video\')\n          bgvid.src = vid\n          bgvid.addEventListener(\'canplay\',()=>{\n            if(!vidplaying){\n              vidplaying=1\n              bgvid.loop=true\n              bgvid.muted=true\n              bgvid.play()\n            }\n          })\n        }\n      }\n    })\n  }\n\n  setupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\nca