(600117, 'https://srmcgann.github.io/assets/1Ui51x.mp4', '  song = \'https://twilightparadox.com/sweet spot.mp3\'\n  vid = \'\'\n  recordingStarted=playing=vidplaying=analyzerSetup=0\n\n  fftSize = 64\n\n  c=document.querySelector(\'#c\')\n  x=c.getContext(\'2d\')\n  c.width=1920\n  c.height=1080\n  canvas2=c.cloneNode()\n  x2=canvas2.getContext(\'2d\')\n  S=Math.sin\n  C=Math.cos\n  t=0\n\n  Draw=()=>{\n\n    if(!t){\n      bg = new Image()\n      go=false\n      bg.addEventListener(\'load\',()=>{\n        go=true\n      })\n      bg.src = \'https://srmcgann.github.io/assets/D8R8C.jpg\'\n    }\n    \n    if(go){\n      x.globalAlpha = .15\n      s=1.2\n      x.drawImage(bg, c.width/2-bg.width/4*s,c.height/2-bg.height/4*s,bg.width/2*s,bg.height/2*s)\n      x.globalAlpha = 1\n      x.fillStyle=\'#0004\',x.fillRect(0,0,w=c.width,w)\n    } else {\n      x.fillStyle=\'#000\', x.fillRect(0,0,w=c.width,w)\n    }\n    \n    iTs=80,iTv=2.5,iTr=8,iTt=100,iTa=1\n    iFc=200,iFs=16,iFv=20\n    \n    Qf=q=>{\n      F=[...F,[Rn()*w,Rn()*1080,1]]\n    }\n\n    if(!t){\n      F=[]\n      Rn=Math.random\n      P=[[960,540,iTs,Math.PI,0,100]]\n      for(i=iFc;i--;)Qf()\n    }\n\n    if(!((t*60|0)%2))Qf()\n    \n    F=F.map(v=>{\n      x.fillStyle=\'#4f4f\'\n      s=iFs\n      x.fillRect(v[0]-s/2,v[1]-s/2,s,s)\n      return v\n    }).filter(v=>v[2])\n\n    Q=q=>{\n      for(m=q[5]/12|0;m--;){\n        P=[...P,[q[0],q[1],10+(q[2]/2-10)*Rn(),q[3],0,100]]\n      }\n    }\n\n    P.map((v, j)=>{\n      v[5]-=iTa\n      mind=6e6\n      F.map(q=>{\n        d=Math.hypot(a=v[0]-q[0],b=v[1]-q[1])\n        if(d<mind)mind=d,p1=Math.atan2(a,b)\n        if(q[2]&&mind<iTs/2){\n          q[2]=0,mind=6e6\n          v[2]+=3\n          v[5]+=iFv\n          v[5]=Math.min(100,v[5])\n        }\n      })\n      p2=v[3]\n      if(Math.abs(p1-p2)>=Math.PI){\n        if(p1<p2){\n          p1+=Math.PI*2\n        }else{\n          p2+=Math.PI*2\n        }\n      }\n      v[4]/=1.15\n      v[3]/=1.03\n      v[4]+=(p1-p2<0?iTr:-iTr)/80\n      v[3]+=v[4]/4\n      v[0]+=S(p=v[3])*(d=v[2]/20*iTv)\n      v[1]+=C(p)*d\n      if(v[0]<0)v[0]+=w\n      if(v[0]>w)v[0]-=w\n      if(v[1]<0)v[1]+=1080\n      if(v[1]>1080)v[1]-=1080\n      x.beginPath()\n      for(i=3;i--;){\n        X=v[0]+S(p=Math.PI*2/3*i+v[3])*(d=v[2]*(i?.5:1))\n        Y=v[1]+C(p)*d\n        x.lineTo(X,Y)\n      }\n      x.closePath()\n      x.lineCap=x.lineJoin=\'round\'\n      x.lineWidth=v[2]/8\n      x.fillStyle=x.strokeStyle=`hsla(${t*50+290-v[5]*.5},99%,${75+S(t*2+v[3])*25}%,.4`\n      x.stroke()\n      x.fill()\n      if(v[2]>=iTt){\n        Q(v)\n        v[5]=0\n      }\n      if(v[5]<=0){\n        for(i=4;i--;){\n          if(i){\n            X1=v[0]+S(p=Math.PI*2/3*i+v[3])*(d=v[2]*(i==3?1:.5))\n            Y1=v[1]+C(p)*d\n            X2=v[0]+S(p=Math.PI*2/3*(i+1)+v[3])*(d=v[2]*((i+1)==3?1:.5))\n            Y2=v[1]+C(p)*d\n            for(j=3;j--;){\n              X=X1+(X2-X1)/3*j\n              Y=Y1+(Y2-Y1)/3*j\n              F=[...F,[X,Y,1]]\n            }\n          }\n        }\n      }\n      return v\n    })\n    P=P.filter((v,i)=>i<500&&v[5]>0)\n  \n    t+=1/60\n    requestAnimationFrame(Draw)\n  }\n\n  setupAnalyzerAndContent = () => {\n    analyzerSetup=1\n    loaded=0\n    mp3 = new Audio()\n    mp3.crossOrigin = \"anonymous\"\n    mp3.src = song\n    mp3.loop = true\n    if(!mp3)loaded=1\n    mp3.addEventListener(\'canplay\',()=>{\n      if(!playing){\n        loaded=playing=1\n        audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n        analyser = audioCtx.createAnalyser()\n        source = audioCtx.createMediaElementSource(mp3)\n        source.connect(analyser)\n        analyser.connect(audioCtx.destination)\n        analyser.fftSize=fftSize\n        trim=analyser.fftSize*.25\n        bufferLength = analyser.frequencyBinCount\n        mp3.loop=true      \n        mp3.play()\n        Draw()\n        if(vid){\n          bgvid = document.createElement(\'video\')\n          bgvid.src = vid\n          bgvid.addEventListener(\'canplay\',()=>{\n            if(!vidplaying){\n              vidplaying=1\n              bgvid.loop=true\n              bgvid.muted=true\n              bgvid.play()\n            }\n          })\n        }\n      }\n    })\n  }\n\n  setupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'sweet spot', 1, 'cantelope', '2022-04-09 14:26:47', '[600116,600115,600114,600113,600112,600111,600110,600109,600108,600104,600103,600102,600101,600100,600099,600092,600091,600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 246, 'https://code.dweet.net/thumbs/bc3f2dfbee103931735ec427997ff12b.jpg', 22, 0),
(600119, 'https://srmcgann.github.io/assets/1eAn7C.mp4', 'song = \'https://twilightparadox.com/tachyon.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=1920\nc.height=1080\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w),h=700\n  R=q=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d,X+=oX,Y+=oY,Z+=oZ}\n  Q=q=>[960+X/Z*h,540+Y/Z*h]\n  Rn=Math.random\n\n  Rl=0,Pt=-t/2,Yw=t\n  oX=0,oY=0,oZ=9\n  iPc=1900/5,iPbr=5\n  iBv=.2,iBc=3,iBs=2\n  G=5\n\n  if(!t){\n    go=false\n    bgimg=new Image()\n    bgimg.addEventListener(\'load\', ()=>{\n      go = true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/2clPtA.jpg\'\n    Rv=q=>[S(p=Math.PI*2*Rn())*S(q=Math.PI*Rn())*iBv,C(q)*iBv,C(p)*S(q)*iBv]\n    x.lineCap=x.lineJoin=\'round\'\n    B=Array(iBc).fill().map(v=>[Rn(),Rn(),Rn(),...Rv()])\n    P=Array(iPbr).fill().map((v,j)=>Array(iPc).fill().map((v,i)=>[a=S(p=Math.PI*2/50*i)/4+(i/iPc-.5)*10,b=C(p/2)*3*S(Math.PI/2+Math.PI*(i/iPc-.5)),f=(j-iPbr/2+.5)*1.5,0,0,0,a,b,f]))\n  }\n  \n  if(go){\n    x.globalAlpha=.4\n    x.drawImage(bgimg, 0, 0, c.width, c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0121\',x.fillRect(0,0,w=c.width,w),h=700\n  } else {\n    x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w),h=700\n  }\n\n  B.map(v=>{\n    v[0]+=v[3]\n    v[1]+=v[4]\n    v[2]+=v[5]\n    if(v[0]<-G||v[0]>G)v[3]*=-1\n    if(v[1]<-G||v[1]>G)v[4]*=-1\n    if(v[2]<-G||v[2]>G)v[5]*=-1\n    x.beginPath()\n    x.fillStyle=\'#4af4\'\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R()\n    x.arc(...Q(),Math.max(1,iBs*600/Z),0,7)\n    x.fill()\n  })\n\n  P.map(v=>{\n    v.map((v,i,ar)=>{\n      v[3]+=(v[6]-v[0])/9\n      v[4]+=(v[7]-v[1])/9\n      v[5]+=(v[8]-v[2])/9\n      v[0]+=v[3]/=1.15\n      v[1]+=v[4]/=1.15\n      v[2]+=v[5]/=1.15\n      B.map(q=>{\n      d=H(a=q[0]-v[0],b=q[1]-v[1],e=q[2]-v[2])\n      if(d<iBs){\n        p1=A(a,e),p2=M.acos(b/d)\n        v[0]=q[0]-S(p1)*S(p2)*iBs\n        v[1]=q[1]-C(p2)*iBs\n        v[2]=q[2]-C(p1)*S(p2)*iBs\n        v[3]-=S(p1)*S(p2)/1000\n        v[4]-=C(p2)/1000\n        v[5]-=C(p1)*S(p2)/1000\n      }\n      })\n      if(i<ar.length-2){\n      x.beginPath()\n      X=ar[i][0]\n      Y=ar[i][1]\n      Z=ar[i][2]\n      R(Rl,Pt,Yw)\n      x.lineTo(...Q())\n      X=ar[i+1][0]\n      Y=ar[i+1][1]\n      Z=ar[i+1][2]\n      R(Rl,Pt,Yw)\n      x.lineTo(...Q())\n      x.strokeStyle=\'#2fa3\'\n      x.lineWidth=iBs*800/Z/Z\n      x.stroke()\n      }\n    })\n  })\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'tachyon', 1, 'cantelope