    analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'wings actual', 1, 'cantelope', '2022-04-09 14:26:47', '[600119,600117,600116,600115,600114,600113,600112,600111,600110,600109,600108,600104,600103,600102,600101,600100,600099,600092,600091,600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 216, 'https://code.dweet.net/thumbs/f8c46b07188b73efe4d7685f5961c536.jpg', 23, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600121, 'https://srmcgann.github.io/assets/1bpGeD.mp4', 'song = \'https://twilightparadox.com/Miami Nights.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=1920\nc.height=1080\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  R=(Rl,Pt,Yw,o)=>{\n    X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n    if(o)X+=oX,Y+=oY,Z+=oZ\n  }\n  Q=q=>[960+X/Z*800,540+Y/Z*800]\n  Rn=Math.random\n\n  if(!t){\n    \n    chk=()=>{\n      if(cp1&&cp2&&cp3&&cp4){\n        bgvid1.play()\n        bgvid3.currentTime = bgvid3.duration/2\n        bgvid3.play()\n        mp3.play()\n        go=true\n      }\n    }\n    bgvid1 = document.createElement(\'video\')\n    bgvid2 = document.createElement(\'video\')\n    bgvid3 = document.createElement(\'video\')\n    bgvid4 = document.createElement(\'video\')\n    cp1=cp2=cp3=cp4=false\n    go=false\n    bgvid1.addEventListener(\'canplay\',()=>{\n      cp1=true\n      if(!go)chk()\n    })\n    bgvid2.addEventListener(\'canplay\',()=>{\n      cp2=true\n      if(!go)chk()\n    })\n    bgvid3.addEventListener(\'canplay\',()=>{\n      cp3=true\n      if(!go)chk()\n    })\n    bgvid4.addEventListener(\'canplay\',()=>{\n      cp4=true\n      if(!go)chk()\n    })\n    bgvid1.src = \'https://srmcgann.github.io/assets/20uyb5.mp4\'\n    bgvid2.src = \'https://srmcgann.github.io/assets/20uyb5.mp4\'\n    bgvid3.src = \'https://srmcgann.github.io/assets/20uyb5.mp4\'\n    bgvid4.src = \'https://srmcgann.github.io/assets/20uyb5.mp4\'\n    for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4)*(d=2**.5),C(p)*d,1])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n  }\n  rw=2, cl=7, br=8, sp = 8+S(t)*6\n  B=Array(rw*cl*br).fill().map((v,i)=>{\n    X=(i%rw-rw/2+.5)*sp\n    Y=(((i/rw|0)%cl)-cl/2+.5)*sp\n    Z=((i/rw/cl|0)-br/2+.5)*(l=(4+S(t))*4)-((t*10)%1)*l\n    return [X, Y, Z]\n  })\n\n  if(go){\n    delay = 5\n    if(bgvid1.ended && bgvid2.currentTime >= bgvid2.duration-bgvid2.duration/delay){\n      bgvid1.play()\n    }\n    if((bgvid2.paused || bgvid2.ended) && bgvid1.currentTime >= bgvid1.duration-bgvid1.duration/delay){\n      bgvid2.play()\n    }\n    x.globalCompositeOperation = \'source-over\'\n    c.width|=0\n    x.lineCap=x.lineJoin=\'butt\'\n    x.fillStyle=`hsla(${t*200},99%,50%,1)`, x.fillRect(0,0,c.width,c.height)\n    alpha1 = Math.min(1, bgvid1.currentTime/bgvid1.duration*delay * Math.min(1, (bgvid1.duration-bgvid1.currentTime)/bgvid1.duration))\n    if(alpha1>.01){\n      x.globalAlpha=alpha1\n      x.drawImage(bgvid1, 0, 0, c.width, c.height)\n    }\n    alpha2 = Math.min(1, bgvid2.currentTime/bgvid2.duration*delay * Math.min(1, (bgvid2.duration-bgvid2.currentTime)/bgvid2.duration))\n    if(alpha2>.01){\n      x.globalAlpha=alpha2\n      x.drawImage(bgvid2, 0, 0, c.width, c.height)\n    }\n    \n    if(bgvid3.ended && bgvid4.currentTime >= bgvid4.duration-bgvid4.duration/delay){\n      bgvid3.play()\n    }\n    if((bgvid4.paused || bgvid4.ended) && bgvid3.currentTime >= bgvid3.duration-bgvid3.duration/delay){\n      bgvid4.play()\n    }\n    x.globalCompositeOperation = \'difference\'\n    alpha3 = Math.min(1, bgvid3.currentTime/bgvid3.duration*delay * Math.min(1, (bgvid3.duration-bgvid3.currentTime)/bgvid3.duration))\n    if(alpha3>.01){\n      x.globalAlpha=alpha3\n      x.drawImage(bgvid3, 0, 0, c.width, c.height)\n    }\n    alpha4 = Math.min(1, bgvid4.currentTime/bgvid4.duration*delay * Math.min(1, (bgvid4.duration-bgvid4.currentTime)/bgvid4.duration))\n    if(alpha4>.01){\n      x.globalAlpha=alpha4\n      x.drawImage(bgvid4, 0, 0, c.width, c.height)\n    }\n  } else {\n    x.fillStyle=\'#0008\',x.fillRect(0,0,c.width,c.height)\n  }\n\n  x.globalCompositeOperation=\'source-over\'\n  x.globalAlpha = 1\n\n  oX=0, oY=0, oZ=20\n  Rl=C(t)*3, Pt=S(t/4)/4, Yw=t/2\n  B.map(v=>{\n    tx=v[0]\n    ty=v[1]\n    tz=v[2]\n    CB.map((q, j)=>{\n      if(!(j%4)) x.beginPath()\n      X = tx + q[0]\n      Y = ty + q[1]\n      Z = tz + q[2]\n      R(Rl,Pt,Yw,1)\n      if(Z>0)x.lineTo(...Q())\n      if(j%4==3){\n        x.closePath()\n        x.lineWidth = Math.min(40, 1+1600/Z/Z)\n        x.strokeStyle=`hsla(${170+t*200},99%,85%,${Math.max(0,.2-Math.abs(tz**2)/19999)})`\n        x.stroke()\n        x.fillStyle=`hsla(${170+t*200},99%,40%,${Math.max(0,.2-Math.abs(tz**2)/19999)})`\n        x.fill()\n      }\n    })\n  })\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'miami nights', 1, 'cantelope', '2022-04-09 14:26:47', '[600120,600119,600117,600116,600115,600114,600113,600112,600111,600110,600109,600108,600104,600103,600102,600101,600100,600099,600092,600091,600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 194, 'https://code.dweet.net/thumbs/6860b2efc80e279ba8cc1247d9b18ce3.jpg', 8, 0),
(600122, 'https://srmcgann.github.io/assets/1hnWRV.mp4', 'song = \'https://twilightparadox.com/breaking formation.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=1920\nc.height=1080\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  R=(Rl,Pt,Yw,o)=>{\n    X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n    if(o)X+=oX,Y+=oY,Z+=oZ\n  }\n  Q=q=>[960+X/Z*800,540+Y/Z*800]\n  Rn=Math.random\n\n  if(!t){\n    bgimg = new Image()\n    go=false\n    bgimg.addEventListener(\'load\', ()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/uJDKE.jpg\'\n    x.lineCap=x.lineJoin=\'butt\'\n    init=()=>{\n      B=[0,0,0,0,0,0]\n      for(i=6;i--;){\n        p=Math.PI*2/6*i\n        d=1\n        X=S(p)*d\n        Y=C(p)*d\n        Z=0\n        B=[...B,[X,Y,Z,0,0,0]]\n      }\n      for(i=3;i--;){\n        p=Math.PI*2/3*i+Math.PI/6\n        d=.58\n        X=S(p)*d\n        Y=C(p)*d\n        Z=.8\n        B=[...B,[X,Y,Z,0,0,0]]\n      }\n      for(i=3;i--;){\n        p=Math.PI*2/3*i+Math.PI/6\n        d=.58\n        X=S(p)*d\n        Y=C(p)*d\n        Z=-.8\n        B=[...B,[X,Y,Z,0,0,0]]\n      }\n      B=[...B,\n        ...JSON.parse(JSON.stringify(B)).map(v=>{\n          v[2]-=6\n          v[0]+=10\n          return v\n        }),\n        ...JSON.parse(JSON.stringify(B)).map(v=>{\n          v[2]+=6\n          v[0]+=10\n          return v\n        }),\n      /*\n        ...JSON.parse(JSON.stringify(B)).map(v=>{\n          v[0]-=6\n          return v\n        }),\n        ...JSON.parse(JSON.stringify(B)).map(v=>{\n          v[0]+=6\n          return v\n        }),\n        */\n        ...JSON.parse(JSON.stringify(B)).map(v=>{\n          v[1]+=6\n          v[0]+=10\n          return v\n        }),\n        ...JSON.parse(JSON.stringify(B)).map(v=>{\n          v[1]-=6\n          v[0]+=10\n          return v\n        }),\n      ]\n      P=Array(1).fill().map((v,j)=>{\n        return [-50,S(p=Math.PI*2/3*j)*.35,C(p)*.35,2,(Rn()-.5)/20,(Rn()-.5)/20]\n      })\n    }\n  }\n\n  if(!((t*60|0)%120)){\n    init()\n    Rl=0,Pt=t/2,Yw=Math.PI/6+Math.PI/1.5*Rn()\n    Rl=-.25+(Rn()-.5)*.5\n  }\n\n  if(go){\n    x.globalAlpha=.25\n    x.drawImage(bgimg,c.width/2-(s=bgimg.width*(c.height/bgimg.height))/2,0,s,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0003\',x.fillRect(0,0,c.width,c.height)\n  }else{\n    x.fillStyle=\'#000a\',x.fillRect(0,0,c.width,c.height)\n  }\n  iPr=2, iBr=.5\n  Pt-=.02\n  oX=0,oY=0,oZ=28+S(t*2)*12\n  \n  DC=(tx,ty,tz,r,rl,pt,yw)=>{\n    cx=X,cy=Y,cz=Z\n    for(m=18;m--;){\n      x.beginPath()\n      for(let i=8;i--;){\n        X=S(p=Math.PI*2/8*i)*r\n        Y=C(p)*r\n        Z=0\n        if(m<6){\n          R(0,0,Math.PI*2/12*m,0)\n        }else if(m<12){\n          R(0,Math.PI*2/12*m,0,0)\n        }else{\n          R(0,Math.PI*2/12*m,Math.PI/2,0)\n        }\n        R(rl,pt,yw,0)\n        X+=tx\n        Y+=ty\n        Z+=tz\n        R(Rl,Pt,Yw,1)\n        if(Z>.1)x.lineTo(...Q())\n      }\n      x.closePath()\n      x.lineWidth=1+Math.min(60, 100/Z/Z)\n      x.stroke()\n    }\n    X=cx,Y=cy,Z=cz\n  }\n\n\n  P.map(v=>{\n    X=v[0]+=v[3]\n    Y=v[1]+=v[4]\n    Z=v[2]+=v[5]\n    //R(Rl,Pt,Yw,1)\n    x.strokeStyle=\'#2cd8\'\n    DC(X,Y,Z,iPr,0,0,0)\n  })\n  B.map((v,i)=>{\n    P.map(q=>{\n      d=Math.hypot(mx=v[0]-q[0],my=v[1]-q[1],mz=v[2]-q[2])\n      if(d<iBr+iPr){\n        q[3]+=v[3]/4/iPr\n        q[4]+=v[4]/4/iPr\n        q[5]+=v[5]/4/iPr\n        q[3]-=mx/4/iPr\n        q[4]-=my/4/iPr\n        q[5]-=mz/4/iPr\n        v[3]+=q[3]/8/iBr\n        v[4]+=q[4]/8/iBr\n        v[5]+=q[5]/8/iBr\n        v[3]+=mx/8/iBr\n        v[4]+=my/8/iBr\n        v[5]+=mz/8/iBr\n      }\n    })\n    B.map((q,j)=>{\n      if(i!=j){\n        d=Math.hypot(mx=v[0]-q[0],my=v[1]-q[1],mz=v[2]-q[2])\n        if(d<iBr*1.95){\n          q[3]+=v[3]/6/iBr\n          q[4]+=v[4]/6/iBr\n          q[5]+=v[5]/6/iBr\n          q[3]-=mx/8/iBr\n          q[4]-=my/8/iBr\n          q[5]-=mz/8/iBr\n          v[3]+=mx/8/iBr\n          v[4]+=my/8/iBr\n          v[5]+=mz/8/iBr\n        }\n      }\n    })\n    X=v[0]+=v[3]\n    Y=v[1]+=v[4]\n    Z=v[2]+=v[5]\n    x.strokeStyle=\'#1f83\'\n    DC(X,Y,Z,iBr,0,0,0)\n  })\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'breaking formation', 1, 'cantelope', '2022-04-09 14:26:47', '[600121,600120,600119,600117,600116,600115,600114,600113,600112,600111,600110,600109,600108,600104,600103,600102,600101,600100,600099,600092,600091,600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 171, 'https://code.dweet.net/thumbs/dd659427657179e38a6aa1661ff3a631.jpg', 7, 0),
(600123, 'https://youtu.be/UNu23nOKObQ', 'song = \'https://twilightparadox.com/rufus.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=1920\nc.height=1080\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  R=(Rl,Pt,Yw,o)=>{\n    X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n    if(o)X+=oX,Y+=oY,Z+=oZ\n  }\n  Q=q=>[960+X/Z*800,540+Y/Z*800]\n  Rn=Math.random\n\n  if(!t){\n    w=1920\n    rufus = new Image()\n    loaded=false\n    rufus.addEventListener(\'load\',()=>{\n      loaded=true\n    })\n    rufus.src = \'https://srmcgann.github.io/assets/e5Jhv.png\'\n    bgimg = new Image()\n    bgloaded=false\n    bgimg.addEventListener(\'load\',()=>{\n      bgloaded=true\n    })\n    bgimg.src = \'https://srmcgann.github.io/assets/1Hyqt6.jpg\'\n    drawRotatedImage=(img,X,Y,w,h,a)=>{\n      x.save()\n      x.translate(X,Y)\n      x.rotate(a)\n      x.drawImage(img,-w/2,-h/2,w,h)\n      x.restore()\n    }\n    G=20\n    B=Array(w).fill().map((v,j)=>{\n      X = (Rn()-.5)*G\n      Y = (Rn()-.5)*G/1.77777778\n      Z = Rn()*G\n      return [X,Y,Z,j]\n    })\n  }\n  \n  Rl=0,Pt=0,Yw=0\n  oX=0,oY=0,oZ=.01\n  \n  if(bgloaded){\n    x.globalAlpha=.3\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0002\',x.fillRect(0,0,c.width,c.height)\n  }else{\n    x.fillStyle=\'#0008\',x.fillRect(0,0,c.width,c.height)\n  }\n  if(loaded){\n    B=B.map(v=>{\n      Z=v[2]-=.05\n      if(v[2]<0)v[2]+=G\n      return v\n    })\n    let tmp = JSON.parse(JSON.stringify(B)).sort((a,b)=>b[2]-a[2])\n    tmp.map(v=>{\n      X=v[0]\n      Y=v[1]\n      Z=v[2]\n      R(Rl,Pt,Yw,1)\n      s=.5/Z\n      x.globalAlpha = 1/(1+Z**4/2000)\n      drawRotatedImage(rufus,...Q(),rufus.width*s,rufus.height*s,(t+v[3])*S(v[3])*(v[3]%2?-1:1))\n    })\n  }\n  x.globalAlpha=1\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'rufus inception (10 hrs)', 1, 'cantelope', '2022-04-09 14:26:47', '[600122,600121,600120,600119,600117,600116,600115,600114,600113,600112,600111,600110,600109,600108,600104,600103,600102,600101,600100,600099,600092,600091,600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 164, 'http://img.youtube.com/vi/UNu23nOKObQ/0.jpg', 2, 0),
