n=x.lineCap=\'round\'\n    ST=Array(5e3).fill().map(v=>{\n      X=(Rn()-.5)*G\n      Y=(Rn()-.5)*G/1.7777778\n      Z=Rn()*G\n      return [X,Y,Z]\n    })\n  }\n\n  if(go){\n    x.globalAlpha=.4\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0006\', x.fillRect(0,0,c.width,c.height)\n  }else{\n    x.fillStyle=\'#0006\', x.fillRect(0,0,c.width,c.height)\n  }\n\n  if(!((t*60|0)%120))spawn()\n    \n  mn=6e6\n  \n  x.fillStyle=\'#fff8\'\n  ST.map(v=>{\n    X=v[0]\n    Y=v[1]\n    Z=v[2]-=.06\n    if(Z<.1)v[2]+=G\n    x.globalAlpha=1/(1+Z**5/999999)\n    x.fillRect(...Q(),s=Math.min(50,1+25/Z),s)\n  })\n  x.globalAlpha=1\n  B.map(v=>{\n    B.map(q=>{\n      d=Math.hypot(q[0]-v[0],q[1]-v[1],q[2]-v[2])\n      if(d&&d<mn)mn=d\n    })\n  })\n  P.map(v=>{\n    mx=v[0]\n    my=v[1]\n    mz=v[2]\n    B.map((v,i)=>{\n      tx=v[0],ty=v[1],tz=v[2]\n      B.map((q,j)=>{\n        if(j>i){\n          d=Math.hypot(q[0]-v[0],q[1]-v[1],q[2]-v[2])\n          if(d<mn*ls){\n            x.beginPath()\n            X=mx+tx,Y=my+ty,Z=mz+tz\n            R(Rl,Pt,Yw,1)\n            if(Z>0)x.lineTo(...Q())\n            X=mx+q[0],Y=my+q[1],Z=mz+q[2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0)x.lineTo(...Q())\n            x.strokeStyle=`hsla(${t*199},99%,50%,.2`\n            x.lineWidth=Math.min(30, 100/Z)\n            x.stroke()\n            x.strokeStyle=\'#fff8\'\n            x.lineWidth=Math.min(30, 30/Z)\n            x.stroke()\n          }\n        }\n      })\n    })\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)