[2]=0)\n    //if(v[2]+v[6][0][2]>br/2*sp)v[2]=-br/2*sp,v[6][0][2]=0\n    tx=X=v[0]\n    ty=Y=v[1]\n    tz=Z=v[2]-=.1\n    for(let j=v[6].length;j--;){\n      q=v[6][j]\n      if(j){\n        d=Math.hypot(q[0]-v[6][j-1][0],q[1]-v[6][j-1][1],q[2]-v[6][j-1][2])\n        q[0]=v[6][j-1][0]+(q[0]-v[6][j-1][0])/d*v[6][v[6].length-j][3]/2\n        q[1]=v[6][j-1][1]+(q[1]-v[6][j-1][1])/d*v[6][v[6].length-j][3]/2\n        q[2]=v[6][j-1][2]+(q[2]-v[6][j-1][2])/d*v[6][v[6].length-j][3]/2\n      }\n    }\n  })\n  B.map(v=>{\n    tx=X=v[0]\n    ty=Y=v[1]\n    tz=Z=v[2]-=.3\n    v[6].map((q,j)=>{\n      if(j){\n        x.beginPath()\n        X=tx+q[0]\n        Y=ty+q[1]\n        Z=tz+q[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        X=tx+v[6][j-1][0]\n        Y=ty+v[6][j-1][1]\n        Z=tz+v[6][j-1][2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        x.globalAlpha=.4/(1+H(tx+q[0],ty+q[1],tz+q[2])**6/5e10)\n        x.strokeStyle=\'#4fb\'\n        x.lineWidth=Math.min(200, 400/(1+(v[6].length-j)**3/50)/Z)\n        x.stroke()\n      }\n    })\n    v[3]+=(Rn()-.5)/5\n    v[4]+=(Rn()-.5)/5\n    v[5]+=(Rn()-.5)/5\n    d=Math.hypot(v[3],v[4],v[5])\n    v[3]/=1.3\n    v[4]/=1.3\n    v[5]/=1.3\n    v[3]=v[3]/d*iBv\n    v[4]=v[4]/d*iBv\n    v[5]=v[5]/d*iBv\n    v[6][0][0]+=v[3]\n    v[6][0][1]+=v[4]\n    v[6][0][2]+=v[5]\n  })\n  x.globalAlpha=1\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.ff