setupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'Taylor Swift - Epiphany (unicorn mix)', 1, 'cantelope', '2022-04-09 14:26:47', '[600127,600126,600125,600124,600123,600122,600121,600120,600119,600117,600116,600115,600114,600113,600112,600111,600110,600109,600108,600104,600103,600102,600101,600100,600099,600092,600091,600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 109, 'https://code.dweet.net/thumbs/86d53e90b872c29c2061dcdddbf318de.jpg', 35, 0),
(600129, 'https://srmcgann.github.io/assets/j3Zbz.mp4', 'song = \'https://twilightparadox.com/awakening.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  x.fillStyle=\'#000a\',x.fillRect(0,0,w=c.width,w),h=650\n  R=(Rl,Pt,Yw)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d}\n  Q=q=>[c.width/2+X/Z*h,c.height/2+Y/Z*700]\n  Rn=Math.random\n\n  Rl=0,Pt=0,Yw=0\n  cl=6,sp=10\n  s=cl*sp/2\n\n  if(!t){\n  \n    x.lineJoin=x.lineCap=\'round\'\n    sql=0\n    PX=PY=PZ=0\n    PRl=PPt=PYw=0\n    oX=0\n    oY=0\n    oZ=0\n    \n    sd=10\n    iBv=.2\n    iPv=.5\n    iFex=.04\n    iFfreq=3\n    iFms=1.75\n    \n    P=Array(200).fill().map((v,i)=>{\n      X=0,Y=-iBv,Z=0\n      R(0,Rn()*Math.PI,Rn()*Math.PI*2)\n      //R(0,-Math.PI/2,-Math.PI/4)\n      vx=X,vy=Y,vz=Z\n      X=((i%cl)-cl/2+.5)*sp\n      Y=(((i/cl|0)%cl)-cl/2+.5)*sp\n      Z=((i/cl/cl|0)%cl-cl/2+.5)*sp          \n      return [X,Y,Z,vx,vy,vz]\n    })\n    \n    MR=q=>{\n      R(0,0,-PYw)\n      R(0,-PPt,0)\n      R(-PRl,0,0)\n      R(Rl,Pt,Yw)\n    }\n\n    FQ=v=>{\n      a=[]\n      for(let i=sd;i--;){\n        X=S(p=Math.PI*2/sd*i+t*2)\n        Y=C(p)\n        Z=0\n        p1=A(v[3],v[5])\n        p2=Math.acos(v[4]/(H(v[3],v[4],v[5])))\n        R(0,-p2-Math.PI/2,0)\n        R(0,0,p1)\n        a=[...a,[X,Y,Z,v[0],v[1],v[2],p1,p2,.2]]\n      }\n      return a\n    }\n\n    F=[]\n  }\n\n  X=0,Y=0,Z=iPv\n  PRl=C(t)/2\n  PPt=S(t*2)/4\n  PYw=S(t)\n  R(PRl,PPt,PYw)\n  PX+=X,PY+=Y,PZ+=Z\n  \n  P.map(v=>{\n    X=v[3],Y=v[4],Z=v[5]\n    R(0,(Rn()-.5)*Math.PI*sql,(Rn()-.5)*Math.PI*2*sql)\n    v[3]=X,v[4]=Y,v[5]=Z\n    v[0]+=v[3]\n    v[1]+=v[4]\n    v[2]+=v[5]\n    X=v[0]-PX\n    Y=v[1]-PY\n    Z=v[2]-PZ\n    while(X<-s)X+=s*2\n    while(X>s)X-=s*2\n    while(Y<-s)Y+=s*2\n    while(Y>s)Y-=s*2\n    while(Z<-s)Z+=s*2\n    while(Z>s)Z-=s*2\n    MR()\n    X+=oX,Y+=oY,Z+=oZ\n    alpha=1/(1+((1+Z)**6)/5e7)\n    if(Z>0){\n      x.beginPath()\n      x.arc(...Q(),Math.min(100,100/Z),0,7)\n      x.fillStyle=`hsla(${150},99%,50%,${alpha}`\n      x.fill()\n    }\n    \n    if(!((t*60|0)%iFfreq)){\n      F=[...F,FQ(v)]\n    }\n    \n  })\n\n  F.map(v=>{\n    x.beginPath()\n    X=v[0][3]-PX\n    Y=v[0][4]-PY\n    Z=v[0][5]-PZ\n    while(X<-s)X+=s*2\n    while(X>s)X-=s*2\n    while(Y<-s)Y+=s*2\n    while(Y>s)Y-=s*2\n    while(Z<-s)Z+=s*2\n    while(Z>s)Z-=s*2\n    tx=X,ty=Y,tz=Z\n    v.map(v=>{\n      X=tx+(v[0]*v[8])\n      Y=ty+(v[1]*v[8])\n      Z=tz+(v[2]*v[8])\n      MR()\n      X+=oX,Y+=oY,Z+=oZ\n      if(Z>0)x.lineTo(...Q())\n      v[8]*=1.05\n      v[8]+=iFex\n    })\n    \n    X=tx,Y=ty,Z=tz\n    MR()\n    if(Z>1){\n      x.closePath()\n      alpha=1/(1+((1+Z)**6)/7e8)\n      x.strokeStyle=`hsla(${360*(iFms/8)*v[0][8]+t*400},99%,${100-v[0][8]/iFms*50}%,${1/((1+iFms*v[0][8])**1.8)*alpha})`\n      x.lineWidth=Math.min(50,1+300/Z/Z)\n      x.stroke()\n    }\n  })\n\n  F=F.filter(v=>v[0][8]<iFms)\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'awakening', 1, 'cantelope', '2022-04-09 14:26:47', '[600128,600127,600126,600125,600124,600123,600122,600121,600120,600119,600117,600116,600115,600114,600113,600112,600111,600110,600109,600108,600104,600103,600102,600101,600100,600099,600092,600091,600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 91, 'https://code.dweet.net/thumbs/594a55ac2567495f20d29a011d297a70.jpg', 20, 0),
(600131, 'https://srmcgann.github.io/assets/SacyH.mp4', 'song = \'https://twilightparadox.com/rosemary.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w)\n  \n  initV=10,initR=60,squirreliness=.1\n  \n  P=t?P:Array(12).fill().map(v=>[960,540,initR,S(p=Math.random()*Math.PI*2)*initV,C(p)*initV,[],0])\n  \n  x.globalAlpha=.6\n  R=P=>{\n    P=P.filter(v=>v[2]>10).map(v=>{\n      if(v[2]<initR)v[2]/=1.08\n      d=Math.hypot(v[3],v[4])\n      p=Math.atan2(v[3],v[4])+((v[6]+=Math.random()-.5)*squirreliness)\n      v[6]=Math.min(1,Math.max(-1,v[6]))\n      v[3]=S(p)*d\n      v[4]=C(p)*d\n      v[0]+=v[3]\n      v[1]+=v[4]\n      if(v[0]>w)v[0]-=w\n      if(v[0]<0)v[0]+=w\n      if(v[1]>1080)v[1]-=1080\n      if(v[1]<0)v[1]+=1080\n      x.beginPath()\n      x.fillStyle=`hsla(${v[2]*1.5-15},99%,${30+v[2]}%,${(v[2]**2/500)}`\n      x.arc(v[0],v[1],v[2],0,7)\n      x.fill()\n      if(!((v[2]|0)%10)){\n        for(m=2;m--;)v[5].push([v[0],v[1],v[2]/2+Math.random()*v[2]/2,S(p=Math.atan2(v[3],v[4])-Math.PI+(Math.random()-.5)/10)/2*initV,C(p)/2*initV,[],0])\n      }\n      v[5]=R(v[5])\n      return v\n    })\n    return P\n  }\n  P=R(P)\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'rosemary', 1, 'cantelope', '2022-04-09 14:26:47', '[600129,600128,600127,600126,600125,600124,600123,600122,600121,600120,600119,600117,600116,600115,600114,600113,600112,600111,600110,600109,600108,600104,600103,600102,600101,600100,600099,600092,600091,600090,600089,600088,600086,600085,600084,600080,600079,600078,600075,600071,600070,600069,600068,600066,600063]', 88, 'https://code.dweet.net/thumbs/f594e7faf7beb06731e67371ddbc83fc.jpg', 16, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600132, 'https://srmcgann.github.io/assets/Zr30T.mp4', 'song = \'https://twilightparadox.com/Billie Eilish - Party Favor (unicorn mix).mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  R=q=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d,X+=oX,Y+=oY,Z+=oZ}\n  Q=q=>[960+X/Z*h,540+Y/Z*h]\n  Rn=Math.random\n\n  iBs=.35,iBc=6,iBv=.15\n  oX=0,oY=0,oZ=8\n  Rl=0,Pt=-t/1.5,Yw=t*2\n  iGs=8\n\n  if(!t){\n    B=[]\n    for(i=iBc;i--;){\n      B=[...B,[Rn()-.5,Rn()-.5,Rn()-.5,S(p=Math.PI*2*Rn())*S(q=Math.PI*Rn())*iBv,C(q)*iBv,C(p)*S(q)*iBv]]\n    }\n    bgimg = new Image()\n    go=false\n    songplaying=false\n    bgimg.addEventListener(\'load\',()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/1y1ji7.jpg\'\n  }\n\n  if(go){\n    if(!songplaying){\n      songplaying=true\n      mp3.play()\n    }\n    x.globalAlpha = .2\n    x.drawImage(bgimg, 0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0003\',x.fillRect(0,0,w=c.width,w),h=800\n    x.lineJoin=\'round\'\n    x.lineCap=\'round\'\n\n    Sk=[]\n    B.map((v,i)=>{\n      B.map((q,j)=>{\n        if(j!=i){\n          e=Math.hypot(X=q[0]-v[0],Y=q[1]-v[1],Z=q[2]-v[2])\n          o=p1=Math.atan2(X,Z)\n          m=p2=Math.acos(Y/e)\n          tx=v[0]\n          ty=v[1]\n          tz=v[2]\n          l=e\n          vx=S(o)*S(m)\n          vy=C(m)\n          vz=C(o)*S(m)\n          tx1=tx\n          ty1=ty\n          tz1=tz\n          tx2=tx+vx*l\n          ty2=ty+vy*l\n          tz2=tz+vz*l\n          Sk=[...Sk,[tx1,ty1,tz1,tx2,ty2,tz2,e,q[0],q[1],q[2]]]\n          if(e<iBs*2){\n            vx=S(p1)*S(p2)\n            vy=C(p2)\n            vz=C(p1)*S(p2)\n            v[0]=q[0]-vx*iBs*2\n            v[1]=q[1]-vy*iBs*2\n            v[2]=q[2]-vz*iBs*2\n            v[3]-=vx/5\n            v[4]-=vy/5\n            v[5]-=vz/5\n            q[0]=v[0]+vx*iBs*2\n            q[1]=v[1]+vy*iBs*2\n            q[2]=v[2]+vz*iBs*2\n            q[3]+=vx/5\n            q[4]+=vy/5\n            q[5]+=vz/5\n          }\n        }\n      })\n      d=Math.hypot(v[3],v[4],v[5])\n      v[3]=v[3]/d*iBv\n      v[4]=v[4]/d*iBv\n      v[5]=v[5]/d*iBv\n      v[0]+=v[3]\n      v[1]+=v[4]\n      v[2]+=v[5]\n      if(v[0]>iGs/2-iBs)v[0]=iGs/2-iBs,v[3]*=-1\n      if(v[0]<-iGs/2+iBs)v[0]=-iGs/2+iBs,v[3]*=-1\n      if(v[1]>iGs/2-iBs)v[1]=iGs/2-iBs,v[4]*=-1\n      if(v[1]<-iGs/2+iBs)v[1]=-iGs/2+iBs,v[4]*=-1\n      if(v[2]>iGs/2-iBs)v[2]=iGs/2-iBs,v[5]*=-1\n      if(v[2]<-iGs/2+iBs)v[2]=-iGs/2+iBs,v[5]*=-1\n      x.beginPath()\n      X=v[0],Y=v[1],Z=v[2]\n      R()\n      x.arc(...Q(),iBs*1e3/Z,0,7)\n      x.fillStyle=\'#0ff3\'\n      x.fill()\n    })\n\n    sd=2\n\n    Sk=Sk.map(v=>{\n      d=1/12\n      lx1=v[0]\n      ly1=v[1]\n      lz1=v[2]\n      lx2=v[0]+(v[3]-v[0])*d\n      ly2=v[1]+(v[4]-v[1])*d\n      lz2=v[2]+(v[5]-v[2])*d\n      v=[lx1,ly1,lz1,lx2,ly2,lz2,Math.hypot(lx1-lx2,ly1-ly2,lz1-lz2),v[7],v[8],v[9]]\n      return v\n    })\n    \n    \n    for(j=16;j--;){\n      tSk=[]\n      for(m=2;m--;){\n        Sk=Sk.map(v=>{\n          d=v[6]\n          lx1=v[3]\n          ly1=v[4]\n          lz1=v[5]\n          n=(1/(1+(L=Math.hypot(v[7]-v[3],v[8]-v[4],v[9]-v[5]))))\n          a=((v[0]-v[3])+(v[3]-v[7])*n)/2\n          b=((v[2]-v[5])+(v[5]-v[9])*n)/2\n          e=((v[1]-v[4])+(v[4]-v[8])*n)/2\n          U=Math.min(1.5,L**3/100)\n          p1=Math.atan2(a,b)+(Rn()-.5)*U\n          p2=Math.acos(e/Math.hypot(a,b,e))+(Rn()-.5)*U\n          lx2=v[3]-S(p1)*S(p2)*d\n          ly2=v[4]-C(p2)*d\n          lz2=v[5]-C(p1)*S(p2)*d\n          if(Rn()<.12)tSk=[...tSk,[lx1,ly1,lz1,lx2,ly2,lz2,v[6],v[7],v[8],v[9]]]\n          return v\n        })\n      }\n      Sk=[...Sk,...tSk]\n\n      tSk2=[]\n      for(m=2;m--;){\n        tSk=tSk.map(v=>{\n          e=v[6]\n          lx1=v[3]\n          ly1=v[4]\n          lz1=v[5]\n\n          n=(1/(L=1+(Math.hypot(v[7]-v[3],v[8]-v[4],v[9]-v[5]))))\n          a=((v[0]-v[3])+(v[3]-v[7])*n)/2\n          b=((v[2]-v[5])+(v[5]-v[9])*n)/2\n          e=((v[1]-v[4])+(v[4]-v[8])*n)/2\n          U=Math.min(1.5,L**3/100)\n          p1=Math.atan2(a,b)+(Rn()-.5)*U\n          p2=Math.acos(e/Math.hypot(a,b,e))+(Rn()-.5)*U\n          lx2=v[3]-S(p1)*S(p2)*e\n          ly2=v[4]-C(p2)*e\n          lz2=v[5]-C(p1)*S(p2)*e\n          if(Rn()<.12)tSk2=[...tSk2,[lx1,ly1,lz1,lx2,ly2,lz2,v[6],v[7],v[8],v[9]]]\n          return v\n        })\n      }\n      Sk=[...Sk,...tSk2]\n    }\n    \n    x.lineJoin=x.lineCap=\'round\'\n    Sk.map((v,i)=>{\n      x.beginPath()\n      x.strokeStyle=\'#aef2\'\n      d=1\n      lx=(v[3]-v[0])*d\n      ly=(v[4]-v[1])*d\n      lz=(v[5]-v[2])*d\n      X=v[0],Y=v[1],Z=v[2]\n      R()\n      x.lineTo(...Q())\n      X=v[0]+lx,Y=v[1]+ly,Z=v[2]+lz\n      R()\n      x.lineTo(...Q())\n      x.lineWidth=1+300/(1+i/100)/Z\n      x.stroke()\n      \n      X=v[7]\n      Y=v[8]\n      Z=v[9]\n      R()\n    })\n  }else{\n    x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w),h=800\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(