PI/10\n  }\n\n  m=0\n  l=2**.5/2\n  for(j=cl*rw*br;j--;){\n    tx=((j%cl)-cl/2+.5)*l*sp\n    ty=((j/rw|0)%cl-rw/2+.5)*l*sp\n    tz=((j/cl/rw|0)-br/2+.5)*l*sp\n    x.beginPath()\n    for(i=4;i--;){\n      a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),0]\n      X=a[m%3]*(d=j<3?-1:1)\n      Y=a[(m+1)%3]*d\n      Z=a[(m+2)%3]*d\n      if((j/4|0)%2){\n        R(mRl,mPt,mYw)\n      }else{\n        R(mRl2,mPt2,mYw2)\n      }\n      X+=tx\n      Y+=ty\n      Z+=tz\n      R(Rl,Pt,Yw)\n      X+=oX,Y+=oY,Z+=oZ\n      x.lineTo(...Q())\n    }\n    x.closePath()\n    x.fillStyle=\'#88ffff0c\'\n    x.fill()\n    x.lineWidth=1+1e3/Z/Z\n    x.strokeStyle=\'#88ffff18\'\n    x.stroke()\n  }\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'Ariana Grande and Nicki Minaj - Side to Side (unicorn mix)', 145, 'whitehot robot', '2022