(600141, 'https://srmcgann.github.io/assets/2eMsc5.mp4', 'song = \'https://audiocloud.rotoblaster.com/audio/124fa4cbd06cfcd9a1678f50dc84e21c.MP3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(!t){\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    Rn=Math.random\n    playing=go=false\n    bgimg = new Image()\n    bgimg.addEventListener(\'load\',()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/1OFK3N.jpg\'\n    img=new Image()\n    img.src=\'https://srmcgann.github.io/assets/11ScI8.png\'\n    G=16\n    B=Array(2e3).fill().map((v,i)=>{\n      return [(Rn()-.5)*G,(Rn()-.5)*G/1.77777778,Rn()*G/2,Rn(),i]\n    })\n    drawRotatedImage=(img, X, Y, W, H, a)=>{\n      x.save()\n      x.translate(X,Y)\n      x.rotate(a)\n      x.drawImage(img, -W/2, -H/2, W, H)\n      x.translate(-X,-Y)\n      x.restore()\n    }\n  }\n  if(go){\n    if(!playing){\n      playing=true\n      mp3.play()\n    }\n    let idx=[]\n    B.map((v,i)=>{\n      idx=[...idx,[v[2], i]]\n    })\n    idx.sort((a,b)=>b[0]-a[0])\n    Rl=0,Pt=0,Yw=0\n    oX=0,oY=0,oZ=0\n    x.globalAlpha = .1\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha = .7\n    x.fillStyle=\'#4002\',x.fillRect(0,0,c.width,c.height)\n    B.map((v,i)=>{\n      X=B[idx[i][1]][0]\n      Y=B[idx[i][1]][1]\n      Z=B[idx[i][1]][2]-=.02\n      if(Z<0)B[idx[i][1]][2]+=G/2\n      R(Rl,Pt,Yw,1)\n      l=Q()\n      s=Math.max(.1,Z**1.2)*1.5*(2+S(B[idx[i][1]][3])*1.01)\n      iw = img.width/s/2\n      ih = img.height/s/2\n      x.globalAlpha = (1 / (1+Z**5/2e3))*Math.min(1,Z/3)\n      drawRotatedImage(img, ...l, iw, ih, S(B[idx[i][1]][3])*Math.PI*2+t*(S(B[idx[i][1]][3])+.5)*4*(idx[i][1]%2?-1:1))\n    })\n  }else{\n    x.fillStyle=\'#400\',x.fillRect(0,0,c.width,c.height)\n  }\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'Taylor Swift - Lover (unicorn mix)', 145, 'whitehot robot', '2022-04-09 14:26:47', '[600140,600139,600138,600137,600136,600135]', 551, 'https://code.dweet.net/thumbs/0ff103d74ffcd32e7e7dc4ece73c49db.jpg', 59, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600142, 'https://srmcgann.github.io/assets/rTFOU.mp4', 'song = \'https://audiocloud.rotoblaster.com/audio/f7e80b4fd0f27ed2a43c0a8c2560d5a0.MP3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(!t){\n    bgimg = new Image()\n    playing=go=false\n    bgimg.addEventListener(\'load\',()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/18AaFq.jpg\'\n  }\n  \n  if(go){\n    if(!playing) playing=true, mp3.play()\n    x.globalAlpha=.3\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0004\',x.fillRect(0,0,w=c.width,w),h=540\n  }else{\n    x.fillStyle=\'#1048\',x.fillRect(0,0,w=c.width,w),h=540\n  }\n  \n  M=Math,A=M.atan2,H=M.hypot\n  \n  cl=10,initV=.35,l=.35\n  oX=oY=0,oZ=cl/1/2\n  Rl=t/4,Pt=-t/3,Yw=t/1.5\n  \n  Rn=q=>(Math.random()-.5)*initV\n  P=t?P:Array(4).fill().map(v=>[0,0,0,Rn(),Rn(),Rn()])\n  \n  Q=q=>[960+X/Z*700,h+Y/Z*700]\n  R=q=>{X=S(p=A(X,Y)+Rl)*(d=H(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d}\n  x.lineCap=\'round\'\n  for(i=cl**3;i--;){\n    X=(i%cl)-cl/2+.5\n    Y=((i/cl|0)%cl)-cl/2+.5\n    Z=((i/cl/cl|0)%cl)-cl/2+.5\n    pX=pY=pZ=d1=0\n    P.map(v=>{\n      d=H(X-v[0],Y-v[1],Z-v[2])**2\n      d1+=500/(d**.8)\n      p1=A(X-v[0],Z-v[2])\n      p2=M.acos((Y-v[1])/H(X-v[0],Y-v[1],Z-v[2]))\n      pX+=X+S(p1)*S(p2)*200/d\n      pY+=Y+C(p2)*200/d\n      pZ+=Z+C(p1)*S(p2)*200/d\n    })\n    pX/=P.length\n    pY/=P.length\n    pZ/=P.length\n    d=H(X-pX,Y-pY,Z-pZ)\n    p1=A(X-pX,Z-pZ)\n    p2=M.acos((Y-pY)/d)\n    R()\n    X+=oX\n    Y+=oY\n    Z+=oZ\n    if(Z>1){\n      x.beginPath()\n      x.fillStyle=\'#fff4\'\n      x.arc(...Q(),10/Z,0,7)\n      x.fill()\n      x.beginPath()\n      x.lineTo(...Q())\n      X=(i%cl)-cl/2+.5\n      Y=((i/cl|0)%cl)-cl/2+.5\n      Z=((i/cl/cl|0)%cl)-cl/2+.5\n      X+=S(p1)*S(p2)*l\n      Y+=C(p2)*l\n      Z+=C(p1)*S(p2)*l\n      R()\n      X+=oX\n      Y+=oY\n      Z+=oZ\n      x.lineTo(...Q())\n      x.lineWidth=100/Z\n      x.strokeStyle=`hsla(${d1/2-140},99%,${20+(d1**2.5)/6e4}%,${.05+(d1**1.5)/8e4}`\n      x.stroke()\n      x.lineWidth=25/Z\n      x.strokeStyle=`hsla(${d1/2-140},99%,${20+(d1**2.5)/6e4}%,${.05+(d1**1.5)/8e4*4}`\n      x.stroke()\n    }\n  }\n  P.map(v=>{\n    X=v[0]+=v[3]\n    Y=v[1]+=v[4]\n    Z=v[2]+=v[5]\n    v[3]*=X>cl/2-1||X<-cl/2+1?-1:1\n    v[4]*=Y>cl/2-1||Y<-cl/2+1?-1:1\n    v[5]*=Z>cl/2-1||Z<-cl/2+1?-1:1\n    R()\n    X+=oX\n    Y+=oY\n    Z+=oZ\n    if(Z>1){\n      x.beginPath()\n      x.fillStyle=\'#0f88\'\n      x.arc(...Q(),99/Z,0,7)\n      x.fill()\n    }\n  })\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'above ground', 145, 'whitehot robot', '2022-04-09 14:26:48', '[600141,600140,600139,600138,600137,600136,600135]', 531, 'https://code.dweet.net/thumbs/28a393c48709f0014e06de60557e8356.jpg', 13, 0),
(600143, 'https://srmcgann.github.io/assets/1B8upE.mp4', 'song = \'https://audiocloud.rotoblaster.com/audio/d627692a855ff82b87d42b102961f94f.MP3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(!t){\n    vid1 = document.createElement(\'video\')\n    vid2 = document.createElement(\'video\')\n    tc = c.cloneNode()\n    tx = tc.getContext(\'2d\')\n    vid1.loop = true\n    vid2.loop = true\n    canplay1=canplay2=false\n    vid1.addEventListener(\'canplay\',()=>{\n      canplay1=true\n      vid1.play()\n    })\n    vid2.addEventListener(\'canplay\',()=>{\n      canplay2=true\n      vid2.play()\n    })\n    vid1.src = \'/video/tunnel_downgraded.mp4\'\n    vid2.src = \'/video/goZBf.mp4\'\n    playing=false\n  }\n  \n  if(canplay1 && canplay2){\n    if(!playing){\n      playing=true\n      mp3.play()\n    }\n    tx.drawImage(vid2,0,0,tc.width,tc.height)\n    data=tx.getImageData(0,0,tc.width,tc.height)\n    d=data.data\n    l=t*8\n    r=255\n    g=255\n    b=255\n    for(i=0;i<d.length;i+=4){\n      if((d[i+0]+d[i+1]+d[i+2])/3>128){\n        d[i+0]=r\n        d[i+1]=g\n        d[i+2]=b\n        d[i+3]=255\n      }else{\n        d[i+0]=d[i+1]=d[i+2]=d[i+3]=0\n      }\n    }\n    tc.width|=0\n    tx.putImageData(data,0,0)\n    x.globalAlpha=.7\n    x.drawImage(vid1,0,0,c.width,c.height)\n    for(m=9;m---1;){\n      x.globalAlpha=Math.min(.4,.4/(1+(m+2)**3/90))\n      x.drawImage(tc,0,0,c.width,c.height)\n      s=S(t)*200*m\n      x.drawImage(tc,-s,-s/1.77778,c.width+s*2,c.height+s*2/1.77778)\n    }\n    x.globalAlpha=1\n    x.fillStyle=`hsla(${t*199},99%,30%,.2)`\n    x.fillRect(0,0,c.width,c.height)\n  }else{\n    x.fillStyle=\'#0008\',x.fillRect(0,0,c.width,c.height)\n  }\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'Daya - Hide Away (unicorn mix)', 145, 'whitehot robot', '2022-04-09 14:26:48', '[600142,600141,600140,600139,600138,600137,600136,600135]', 552, 'https://code.dweet.net/thumbs/2563ef7d03835296c5bb2a3f8c04fd38.jpg', 4, 0),
(600144, 'https://srmcgann.github.io/assets/2icbO0.mp4', 'song = \'https://audiocloud.rotoblaster.com/audio/d09439f60a64d0bc100336b7dbf4aadc.MP3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w),h=700\n  R=(Rl,Pt,Yw)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d}\n  Q=q=>[960+X/Z*h,540+Y/Z*h]\n  Rn=Math.random\n\n  Rl=0,Pt=C(t/2.5)/60,Yw=S(t)/50\n  oX=0,oY=0,oZ=10\n  cl=8/4,rw=32/4\n  iR=1,mSr=2,iTc=12,iTl=.25,sd=8\n  \n  if(!t){\n    playing=go=false\n    bgimg=new Image()\n    bgimg.addEventListener(\'load\',()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/1rTRjf.jpg\'\n    x.lineCap=x.lineJoin=\'round\'\n    P=[...Array(cl|0).fill().map((v,j)=>{\n      b=[]\n      for(m=0;m<iTc;m++){\n        s=iR-(iR/(iTc-1)*m)\n        a=[]\n        scl=rw-(rw/cl*j)\n        for(k=scl|0;k--;){\n          a = [...a, Array(sd).fill().map((v,i)=>{\n              X=S(p=Math.PI*2/sd*i)*s\n              Y=C(p)*s\n              Z=mSr+((m*iTl)**.65)*2\n              R(0,p2=Math.PI/2/cl*j,p1=Math.PI*2/scl*k)\n              return [X,Y,Z,0,0]\n            })\n          ]\n        }\n        b=[...b, a]\n      }\n      return b\n    }),\n    ...Array((cl-1)|0).fill().map((v,j)=>{\n      b=[]\n      for(m=0;m<iTc;m++){\n        s=iR-(iR/(iTc-1)*m)\n        a=[]\n        scl=rw-(rw/cl*(j+1))\n        for(k=scl|0;k--;){\n          a = [...a, Array(sd).fill().map((v,i)=>{\n              X=S(p=Math.PI*2/sd*i)*s\n              Y=C(p)*s\n              Z=mSr+((m*iTl)**.65)*2\n              R(0,p2=-Math.PI/2/cl*(j+1),p1=Math.PI*2/scl*k)\n              return [X,Y,Z,0,0]\n            })\n          ]\n        }\n        b=[...b, a]\n      }\n      return b\n    })]\n  }\n\n  if(go){\n    if(!playing) mp3.play(),playing-true\n    x.globalAlpha=.2\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#2063\',x.fillRect(0,0,c.width,c.height)\n    x.strokeStyle=\'#4f84\'\n    P.map(v=>{\n      v.map((v,n,b)=>{\n        v.map((v,i,a)=>{\n          x.beginPath()\n          v.map((v,j)=>{\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            if(n){\n              if(Math.abs(v[3]-b[n-1][i][j][3])>=Math.PI){\n                if(v[3]<b[n-1][i][j][3]){\n                  v[3]+=Math.PI*2\n                }else{\n                  v[3]-=Math.PI*2\n                }\n              }\n              if(Math.abs(v[4]-b[n-1][i][j][4])>=Math.PI){\n                if(v[4]<b[n-1][i][j][4]){\n                  v[4]+=Math.PI*2\n                }else{\n                  v[4]-=Math.PI*2\n                }\n              }\n              p1=v[3]+=(b[n-1][i][j][3]-v[3])/(1+n/3)\n              p2=v[4]+=(b[n-1][i][j][4]-v[4])/(1+n/3)\n            }else{\n              p1=v[3]=S(t*2)/40\n              p2=v[4]=-C(t)/40\n            }\n            R(0,p2,p1)\n            v[0]=X\n            v[1]=Y\n            v[2]=Z\n            X+=oX,Y+=oY,Z+=oZ\n            x.lineTo(...Q())\n            return v\n          })\n          x.lineWidth=599/Z/Z\n          x.closePath()\n          x.stroke()\n        })\n      })\n      v.map((v,n,b)=>{\n        v.map((v,i)=>{\n          if(n){\n            v.map((v,j)=>{\n              x.beginPath()\n              X=v[0]\n              Y=v[1]\n              Z=v[2]\n              R(0,v[3],v[4])\n              X+=oX,Y+=oY,Z+=oZ\n              x.lineTo(...Q())\n              X=b[n-1][i][j][0]\n              Y=b[n-1][i][j][1]\n              Z=b[n-1][i][j][2]\n              R(0,b[n-1][i][j][3],b[n-1][i][j][4])\n              X+=oX,Y+=oY,Z+=oZ\n              x.lineTo(...Q())                \n              