(600151, 'https://srmcgann.github.io/assets/1JW9kP.mp4', 'song = \'https://audiocloud.rotoblaster.com/audio/dfc974333a99250b2bc81d0276683612.MP3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(!t){\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    Rn=Math.random\n    iBc=7,G=16,iBr=50,iBv=.8,iPv=.1\n    P=[]\n    B=Array(iBc).fill().map(v=>{\n      X=(Rn()-.5)*G\n      Y=(Rn()-.5)*G\n      Z=(Rn()-.5)*G\n      rn=Rn()\n      return [X,Y,Z,(Rn()-.5)*iBv*rn,(Rn()-.5)*iBv*rn,(Rn()-.5)*iBv*rn]\n    })\n    bgimg=new Image()\n    go=playing=false\n    bgimg.addEventListener(\'load\',()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/EXR42.jpg\'\n  }\n  \n  if(go){\n    if(!playing)mp3.play(),playing=true\n    x.globalAlpha=.3\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0001\',x.fillRect(0,0,c.width,c.height)\n\n    Rl=0,Pt=S(t),Yw=S(t/2)*6\n    oX=0,oY=0,oZ=G/1.5\n    \n    \n    P=P.map(v=>{\n      X=v[0]+=v[3]*=1.1\n      Y=v[1]+=v[4]*=1.1\n      Z=v[2]+=v[5]*=1.1\n      d1=Math.hypot(v[3],v[4],v[5])\n      if(v[0]>G||v[0]<-G)v[6]=1\n      if(v[1]>G||v[1]<-G)v[6]=1\n      if(v[2]>G||v[2]<-G)v[6]=1\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s=1+Math.min(50,250/Z)\n        x.fillStyle=`hsla(${(d1*1e3)+t*299-50+360/iBc*v[7]},99%,${Math.max(50, 130-d1*600)}%,${.075-d1/16}`\n        l=Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n      return v\n    }).filter(v=>!v[6])\n    B.map((v,i)=>{\n      tx=X=v[0]+=v[3]\n      ty=Y=v[1]+=v[4]\n      tz=Z=v[2]+=v[5]\n      if(v[0]>G/2||v[0]<-G/2)v[3]*=-1\n      if(v[1]>G/2||v[1]<-G/2)v[4]*=-1\n      if(v[2]>G/2||v[2]<-G/2)v[5]*=-1\n      R(Rl,Pt,Yw,1)\n      x.beginPath()\n      if(Z>0){\n        x.arc(...Q(),Math.min(99,7*iBr/Z),0,7)\n        x.fillStyle=\'#f2f2\'\n        x.fill()\n        x.beginPath()\n        x.arc(...Q(),Math.min(99,3*iBr/Z),0,7)\n        x.fillStyle=`#2886`\n        x.fill()\n      }\n      for(m=25;m--;){\n        X=S(p=Math.PI*2*Rn())*iBr/99\n        Y=C(p)*iBr/99\n        Z=0\n        R(0,0,Rn()*Math.PI*2)\n        P=[...P,[tx+X,ty+Y,tz+Z,X*iPv,Y*iPv,Z*iPv,0,i]]\n      }\n    })\n  }else{\n    x.fillStyle=\'#08f8\',x.fillRect(0,0,c.width,c.height)\n  }\n        \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'Cyndi Lauper - Time After Time (unicorn mix)', 145, 'whitehot robot', '2022-04-09 14:26:48', '[600150,600149,600148,600147,600146,600145,600144,600143,600142,600141,600140,600139,600138,600137,600136,600135]', 379, 'https://code.dweet.net/thumbs/75c5f5bb6330882646da1bf24c6d7145.jpg', 42, 0),
(600152, '', 'recordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  Rl=-t/8,Pt=S(t/1.5)*4,Yw=t/2\n  oX=0,oY=0,oZ=3\n  iBc=300,iBv=.1,iBs=.25\n  G=1\n  if(!t){\n    go=false\n    bgimg = new Image()\n    bgimg.addEventListener(\'load\',()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/1kvs6g.jpg\'\n    R=(Rl,Pt,Yw)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d}\n    Q=q=>[960+X/Z*h,540+Y/Z*h]\n    Rn=Math.random\n    x.lineJoin=x.lineCap=\'round\'\n    CB=(X,Y,Z)=>{b=[],l=(2**.5)/2;for(let i=6;i--;){for(let j=4;j--;){a=[S(p=Math.PI*2/4*j+Math.PI/4)*l,C(p)*l,.5],b=[...b,[a[i%3]*(e=i<3?-1:1)+X,a[(i+1)%3]*e+Y,a[(i+2)%3]*e+Z]]}};return b}\n    P=[\n      CB(-1,0,0),\n      CB(1,0,0),\n      CB(0,-1,0),\n      CB(0,1,0),\n      CB(0,0,-1),\n      CB(0,0,1)\n    ]\n    B=Array(iBc).fill().map(v=>{\n      return [\n        (Rn()-.5)*G,\n        (Rn()-.5)*G,\n        (Rn()-.5)*G,\n        (Rn()-.5)*iBv,\n        (Rn()-.5)*iBv,\n        (Rn()-.5)*iBv\n      ]\n    })\n  }\n  \n  if(go){\n    x.globalAlpha = .3\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha = 1\n    x.fillStyle=\'#0003\',x.fillRect(0,0,w=c.width,w),h=700\n\n\n    B.map((v,i)=>{\n\n      gv=[0,1,0]\n      X=gv[0],Y=gv[1],Z=gv[2]\n      R(0,0,-Yw)\n      R(0,-Pt,0)\n      R(-Rl,0,0)\n      gvx=X,gvy=Y,gvz=Z\n\n      X=v[0]\n      Y=v[1]\n      Z=v[2]\n      R(Rl,Pt,Yw)\n      X+=oX,Y+=oY,Z+=oZ\n      s=.5\n\n      v[3]+=gvx/100\n      v[4]+=gvy/100\n      v[5]+=gvz/100\n      \n      v[3]/=1.05\n      v[4]/=1.05\n      v[5]/=1.05\n      \n      B.map((q,j)=>{\n        if(j!=i){\n          d=H(a=q[0]-v[0],b=q[1]-v[1],e=q[2]-v[2])\n          if(d<iBs){\n            v[3]/=1.1\n            v[4]/=1.1\n            v[5]/=1.1\n            v[3]-=a/d/50\n            v[4]-=b/d/50\n            v[5]-=e/d/50\n            q[3]/=1.1\n            q[4]/=1.1\n            q[5]/=1.1\n            q[3]+=a/d/50\n            q[4]+=b/d/50\n            q[5]+=e/d/50\n          }\n        }\n      })\n\n      tx=v[0]+v[3]\n      ty=v[1]+v[4]\n      tz=v[2]+v[5]\n      \n      if(\n        (tx>s*3 || tx<-s*3) ||\n        (!(v[1]>-s && v[1]<s && v[2]>-s && v[2]<s) &&\n        (v[0]>-s && v[0]<s && (tx>s || tx<-s)))\n      ) v[3]*=-.9\n      \n      if(\n        (ty>s*3 || ty<-s*3) ||\n        (!(v[2]>-s && v[2]<s && v[0]>-s && v[0]<s) &&\n        (v[1]>-s && v[1]<s && (ty>s || ty<-s)))\n      ) v[4]*=-.9\n      \n      if(\n        (tz>s*3 || tz<-s*3) ||\n        (!(v[0]>-s && v[0]<s && v[1]>-s && v[1]<s) &&\n        (v[2]>-s && v[2]<s && (tz>s || tz<-s)))\n      ) v[5]*=-.9\n      \n      \n      v[0]+=v[3]\n      v[1]+=v[4]\n      v[2]+=v[5]\n\n      if(\n        (v[0]>s||v[0]<-s)&&(v[2]>s||v[2]<-s) ||\n        (v[1]>s||v[1]<-s)&&(v[0]>s||v[0]<-s) ||\n        (v[2]>s||v[2]<-s)&&(v[1]>s||v[1]<-s)\n      ) v[0]=v[1]=v[2]=0\n\n      x.beginPath()\n      x.arc(...Q(),300*iBs/Z,0,7)\n      x.fillStyle=\'#48f6\'\n      x.fill()\n      x.beginPath()\n      x.arc(...Q(),150*iBs/Z,0,7)\n      x.fillStyle=\'#60f6\'\n      x.fill()\n    })\n\n    P.map((v,i)=>{\n      v.map((v,i)=>{\n        X=v[0],Y=v[1],Z=v[2]\n        \n        if(!(i%4)) x.beginPath()\n        R(Rl,Pt,Yw)\n        X+=oX,Y+=oY,Z+=oZ\n        x.lineTo(...Q())\n        if(i%4==3){\n          x.lineWidth=99/Z/Z\n          x.strokeStyle=\'#4fc2\'\n          x.closePath()\n          x.stroke()\n        }\n      })\n    })\n  }else{\n    \n    x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w),h=700\n  }\n\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin