r.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'madonna - borderline (unicorn mix)', 145, 'whitehot robot', '2022-04-09 14:26:48', '[600151,600150,600149,600148,600147,600146,600145,600144,600143,600142,600141,600140,600139,600138,600137,600136,600135]', 381, 'https://code.dweet.net/thumbs/ff25bc3784480353fbcbf5ae707316a2.jpg', 31, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600154, 'https://srmcgann.github.io/assets/LgbJo.mp4', 'song = \'https://audiocloud.rotoblaster.com/audio/ece8a579479ffe00bda3490465905652.MP3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  isd=4\n\n  if(!t){\n    Rn=Math.random\n    bgimg = new Image()\n    go=playing=false\n    bgimg.addEventListener(\'load\',()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/12ddK3.jpg\'\n    R=(Rl,Pt,Yw,o)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=H(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(o)X+=oX,Y+=oY,Z+=oZ}\n    Q=q=>[c.width/2+X/Z*1e3,c.height/2+Y/Z*1e3]\n    iPc=16,G=16,iPTv=8,iPs=800\n    PT=[]\n    P=Array(iPc).fill().map(v=>{\n      switch(Rn()*4|0){\n        case 0: sd = 4; break\n        case 1: sd = 6; break\n        case 2: sd = 12; break\n        case 3: sd = 14; break\n      }\n      B=Array(sd).fill().map(v=>[(O=Math.random)(),O(),O()])\n      L=q=>q*99**3/d,n=0\n      for(m=500/(1+sd/9)|0;m--;){\n        B.map((v,i)=>{\n          f=g=h=0,B.map(q=>{d=(1+(H=Math.hypot)(a=v[0]-q[0],b=v[1]-q[1],e=v[2]-q[2])*9)**3,f+=L(a),g+=L(b),h+=L(e)}),d=H(v[0]+=f,v[1]+=g,v[2]+=h),v[0]*=1/d,v[1]*=1/d,v[2]*=1/d\n        })\n      }\n      n=6e6\n      B.map(v=>{\n        B.map(q=>{\n          if((d=H(q[0]-v[0],q[1]-v[1],q[2]-v[2]))&&d<n) n=d\n        })\n      })\n      X=(Rn()-.5)*G\n      Y=(Rn()-.5)*G\n      Z=(Rn()-.5)*G\n      return [ X, Y, Z, B, 0, n, sd]\n    })\n  }\n  if(go){\n    if(!playing)mp3.play(),playing=true\n    x.globalAlpha=.3\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0012\',x.fillRect(0,0,c.width,c.height)\n    Rl=t/16,Pt=-t/8,Yw=S(t/12)*2\n    oX=0,oY=0,oZ=G/1.2\n    x.lineCap=\'round\'\n    P.map((e,o)=>{\n      Rl1=t/3,Pt1=-C(t/2+o/3)*3,Yw1=S(t+o)*2\n      tx=e[0]\n      ty=e[1]\n      tz=e[2]\n      B=e[3]\n      B.map((v,i)=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R(Rl1,Pt1,Yw1)\n        X+=tx\n        Y+=ty\n        Z+=tz\n        PT=[...PT, [X,Y,Z,(X-tx)/99*iPTv,(Y-ty)/99*iPTv,(Z-tz)/99*iPTv,1,o,0]]\n        B.map((q,j)=>{\n          if(j>i){\n            d=H(q[0]-v[0],q[1]-v[1],q[2]-v[2])\n            if(d<e[5]*1.22+e[6]**2/2e5){\n              x.beginPath()\n              X=v[0]\n              Y=v[1]\n              Z=v[2]\n              R(Rl1,Pt1,Yw1)\n              X+=tx\n              Y+=ty\n              Z+=tz\n              R(Rl,Pt,Yw,1)\n              if(Z>0) x.lineTo(...Q())\n              k=Z+4\n              X=q[0]\n              Y=q[1]\n              Z=q[2]\n              R(Rl1,Pt1,Yw1)\n              X+=tx\n              Y+=ty\n              Z+=tz\n              R(Rl,Pt,Yw,1)\n              if(Z>0) x.lineTo(...Q())\n              x.globalAlpha=99/Z\n              x.strokeStyle=\'#fffa\'\n              x.lineWidth=1+Math.min(30,40/Z)\n              x.stroke()\n              x.strokeStyle=`hsla(${t*199+360/P.length*o},99%,50%,.1)`\n              x.lineWidth=Math.min(30,500/Z)\n              x.stroke()\n            }\n          }\n        })\n      })\n    })\n\n    PT=PT.map(v=>{\n      X=v[0]+=v[3]\n      Y=v[1]+=v[4]\n      Z=v[2]+=v[5]\n      R(Rl,Pt,Yw,1)\n      v[6]/=1.1\n      v[8]++\n      if(Z>0){\n        l=Q()\n        s=iPs*v[6]/Z/1\n        x.fillStyle=`hsla(${t*199+360/P.length*v[7]-v[8]*10},99%,${Math.max(50,100-v[8]*6)}%,.1)`\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s=iPs*v[6]/Z/3\n        x.fillStyle=`#fff8`\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n      return v\n    }).filter(v=>v[6]>.15)\n  }else{\n    x.fillStyle=\'1031\',x.fillRect(0,0,c.width,c.height)\n  }\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'cherubim', 145, 'whitehot robot', '2022-04-09 14:26:48', '[600153,600151,600150,600149,600148,600147,600146,600145,600144,600143,600142,600141,600140,600139,600138,600137,600136,600135]', 367, 'https://code.dweet.net/thumbs/2f9b847bac6054ed263602649e1c39d0.jpg', 38, 0),
(600155, 'https://srmcgann.github.io/assets/GaOXc.mp4', 'song = \'https://audiocloud.rotoblaster.com/audio/21bd7d4a7dbdd56b95ce0325d24c2ebe.MP3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  oX=0,oY=0,oZ=12+S(t*1.5)*3\n  Rn=Math.random\n  Rl=t/2,Pt=S(t)/2.5,Yw=S(t)/2\n  cellSize=.25\n  iCs=1,iMv=.5,sql=.2,MR=6\n  if(!t){\n    genPath=start=>{\n      P=[]\n      recurse=q=>{\n        B[q][5]=1\n        tc=0\n        while(tc<20&&B[tq=B[q][4][B[q][4].length*Rn()|0]][5])tc++;\n        n=5\n        if(!B[tq][5]){\n          p=(Math.atan2(B[tq][2][0]-B[q][2][0]+.00001,B[q][2][1]-B[tq][2][1])+Math.PI)/(Math.PI*2+.001)*6|0\n          switch(p){\n            case 0:\n              B[q][1][0]=0\n              B[tq][1][3]=0\n              break\n            case 1:\n              B[q][1][1]=0\n              B[tq][1][4]=0\n              break\n            case 2:\n              B[q][1][2]=0\n              B[tq][1][5]=0\n              break\n            case 3:\n              B[q][1][3]=0\n              B[tq][1][0]=0\n              break\n            case 4:\n              B[q][1][4]=0\n              B[tq][1][1]=0\n              break\n            case 5:\n              B[q][1][5]=0\n              B[tq][1][2]=0\n              break;\n          }\n          P.push([q,tq])\n          B[q][6].push(tq)\n          B[tq][6].push(q)\n          recurse(tq)\n        }else{\n          if(B.filter(v=>!v[5]).length)recurse(P[P.length*Rn()|0][0])\n        }\n      }\n      recurse(start)\n    }\n    \n    solve=(a,b)=>{\n      if(found||memo[b])return\n      if(a==b) return true\n      memo[b]=1\n      let test=0\n      B[b][6].map(v=>{if(solve(a,v))found=1,sP.push(v),test=1})\n      if(test) return true\n    }\n    RQa=(tx,ty,m)=>{\n      a=[]\n      for(let i=6;i--;){\n        a=[...a,[tx+S(p=Math.PI*2/6*i+Math.PI/6)*cellSize*iCs,ty+C(p)*cellSize*iCs,0]]\n      }\n      b=[...b,[a,[1,1,1,1,1,1],[tx,ty,0],1,[],0,[],0]]\n      a=[]\n      for(let j=6;j--;){\n        a=[]\n        X=tx+S(p=Math.PI*2/6*j)*d\n        Y=ty+C(p)*d\n        for(i=6;i--;){\n          a=[...a,[X+S(p=Math.PI*2/6*i+Math.PI/6)*cellSize*iCs,Y+C(p)*cellSize*iCs,0]]\n        }\n        b=[...b,[a,[1,1,1,1,1,1],[X,Y,0],1,[],0,[],0]]\n      }\n      if(m){\n        for(let j=6;j--;){\n          a=[]\n          X=tx+S(p=Math.PI/3*j+Math.PI/6)*.75\n          Y=ty+C(p)*.75\n          for(i=6;i--;){\n            a=[...a,[X+S(p=Math.PI*2/6*i+Math.PI/6)*cellSize*iCs,Y+C(p)*cellSize*iCs,0]]\n          }\n          b=[...b,[a,[1,1,1,1,1,1],[X,Y,0],1,[],0,[],0]]\n        }\n      }\n    }\n    RQb=(tx1,ty1)=>{\n      RQa(tx1,ty1,0)\n      for(j=6;j--;){\n        RQa(tx1+S(p=l*j)*d*3,ty1+C(p)*d*3,1)\n        RQa(tx1+S(p=l*j+Math.PI/6)*d*6*d*2,ty1+C(p)*d*6*d*2,0)\n        RQa(tx1+S(p=l*j)*d*6,ty1+C(p)*d*6,1)\n      }\n    }\n\n    RQc=(tx2,ty2)=>{\n     RQb(tx2,ty2)\n     for(let j=6;j--;){\n        d1=5.25\n        RQb(tx2+S(p=Math.PI*2/6*j+Math.PI/6)*d1,ty2+C(p)*d1)\n      }\n    }\n    bgimg = new Image()\n    go=playing=false\n    bgimg.addEventListener(\'load\',()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/1DE0V.jpg\'\n    l=Math.PI*2/6    \n    x.lineJoin=x.lineCap=\'round\'\n    genMaze=()=>{\n      o=d=0.8660254037844386*cellSize*2\n      b=[],a=[]\n      for(i=6;i--;)a=[...a,[S(p=l*i+Math.PI/6)*cellSize*iCs,C(p)*cellSize*iCs,0]]\n      b=[...b,[a,[1,1,1,1,1,1],[0,0,0],1,[],0,[],0]]\n      RQc(0,0)\n      for(let j=6;j--;){\n        d1=10.5\n        RQc(S(p=Math.PI*2/6*j+Math.PI/6)*d1,C(p)*d1)\n      }\n      M1=[0,0,0,S(p=Math.PI*2*Rn())*iMv,C(p)*iMv,0]\n      M2=[0,0,0,S(p=Math.PI*2*Rn())*iMv,C(p)*iMv,0]\n      b=b.filter(v=>Math.hypot(...v[2])<=MR)\n      \n      for(let i=0;i<b.length;++i){\n        for(let j=i+1;j<b.length;++j){\n          if(b[j][3]&&((d=Math.hypot(b[i][2][0]-b[j][2][0],b[i][2][1]-b[j][2][1]))<.01))b[j][3]=0\n        }\n      }\n      b = b.filter(v=>v[3])\n      for(let i=0;i<b.length;++i){\n        for(let j=0;j<b.length;++j){\n          if(i!=j && (d=Math.hypot(b[i][2][0]-b[j][2][0],b[i][2][1]-b[j][2][1]))-o<.1){\n            b[i][4].push(j)\n          }\n        }\n      }\n      B = b\n      genPath(0)\n    }\n    genMaze()\n  }\n  if(go){\n    if(!playing)mp3.play(),playing=true\n    x.globalAlpha=.3\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0023\',x.fillRect(0,0,w=c.width,w)\n    h=800\n    R=(Rl,Pt,Yw)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d,X+=oX,Y+=oY,Z+=oZ}\n    Q=q=>[c.width/2+X/Z*h,c.height/2+Y/Z*h]\n    Rn=Math.random\n\n\n    M1[3]+=(Rn()-.5)*sql\n    M1[4]+=(Rn()-.5)*sql\n    d=(H=Math.hypot)(M1[3],M1[4])\n    M1[3]-=(M1[3]-M1[3]/d*iMv)/5\n    M1[4]-=(M1[4]-M1[4]/d*iMv)/5\n    X=M1[0]+=M1[3]\n    Y=M1[1]+=M1[4]\n    Z=M1[2]+=M1[5]\n    if(H(...M1)>MR)M1[3]-=S(p=A(M1[0],M1[1]))/4,M1[4]-=C(p)/4\n    R(Rl,Pt,Yw)\n    x.beginPath()\n    x.arc(...Q(),1999/Z/Z,0,7)\n    x.fillStyle=\'#6af9\'\n    x.fill()\n    M2[3]+=(Rn()-.5)*sql\n    M2[4]+=(Rn()-.5)*sql\n    d=H(M2[3],M2[4])\n    M2[3]-=(M2[3]-M2[3]/d*iMv)/5\n    M2[4]-=(M2[4]-M2[4]/d*iMv)/5\n    X=M2[0]+=M2[3]\n    Y=M2[1]+=M2[4]\n    Z=M2[2]+=M2[5]\n    if(H(...M2)>MR)M2[3]-=S(p=A(M2[0],M2[1]))/4,M2[4]-=C(p)/4\n    R(Rl,Pt,Yw)\n    x.beginPath()\n    x.arc(...Q(),1999/Z/Z,0,7)\n    x.fillStyle=\'#6af9\'\n    x.fill()\n\n\n    sP=[],found=0,memo=Array(5e5).fill(0)\n\n    mindA=mindB=6e6\n    B.map((v,i)=>{\n      v[7]=0\n      if((d1=H(v[2][0]-M1[0],v[2][1]-M1[1]))<mindA)ptA=i,mindA=d1\n      if((d2=H(v[2][0]-M2[0],v[2][1]-M2[1]))<mindB)ptB=i,mindB=d2\n    })\n    B[ptA][7]=B[ptB][7]=1\n\n    solve(ptA,ptB)\n    sP.push(ptB)\n\n    sP.map((v,j)=>{\n      if(j<sP.length-1){\n      x.beginPath()\n        X=B[v][2][0]\n        Y=B[v][2][1]\n        Z=B[v][2][2]\n        R(Rl,Pt,Yw)\n        x.lineTo(...Q())\n        X=B[sP[j+1]][2][0]\n        Y=B[sP[j+1]][2][1]\n        Z=B[sP[j+1]][2][2]\n        R(Rl,Pt,Yw)\n        x.lineTo(...Q())          \n        x.strokeStyle=\'#3f66\'\n        x.lineWidth=1+Math.min(15,1500/Z/Z)\n        x.stroke()\n      }\n    })\n\n    P.map((v,j)=>{\n      X=B[v[0]][2][0]\n      Y=B[v[0]][2][1]\n      Z=B[v[0]][2][2]\n      R(Rl,Pt,Yw)\n      tq=Q()\n      for(let i=1;i<v.length;++i){\n        x.beginPath()\n        x.lineTo(...tq)\n        X=B[v[1]][2][0]\n        Y=B[v[1]][2][1]\n        Z=B[v[1]][2][2]\n        R(Rl,Pt,Yw)\n        x.lineTo(...Q())\n      }\n      x.strokeStyle=`hsla(${t*400},99%,60%,.3`\n      x.lineWidth=1+Math.min(15,600/Z/Z)\n      x.stroke()\n    })\n\n    B.map((v,j)=>{\n      if(v[7]){\n        v[0].map((q,i)=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(Rl,Pt,Yw)\n          if(!i)x.beginPath()\n          x.lineTo(...Q())\n          if(i==v[0].length-1){\n            x.closePath()\n            x.fillStyle=\'#f084\'\n            x.closePath()\n            x.fill()\n          }\n        })\n      }\n      v[0].map((q,i)=>{\n        if(v[1][i]){\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(Rl,Pt,Yw)\n          x.beginPath()\n          x.lineTo(...Q())\n          if(i<5){\n            X=v[0][i+1][0]\n            Y=v[0][i+1][1]\n            Z=v[0][i+1][2]\n          }else{\n            X=v[0][0][0]\n            Y=v[0][0][1]\n            Z=v[0][0][2]\n          }\n          R(Rl,Pt,Yw)\n          x.lineTo(...Q())\n          x.strokeStyle=\'#28fc\'\n          x.lineWidth=1+Math.min(15,200/Z/Z)\n          x.stroke()\n        }\n      })\n    })\n  }else{\n    x.fillStyle=\'#2044\',x.fillRect(0,0,c.width,c.height)\n  }\n\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'Elizabeth Cotten - In the Sweet By and By (unicorn mix)', 145, 'whitehot robot', '2022-04-09 14:26:48', '[600154,600153,600151,600150,600149,600148,600147,600146,600145,600144,600143,600142,600141,600140,600139,600138,600137,600136,600135]', 338, 'https://code.dweet.net/thumbs/76a34b1dc637688deab3267a7f9f0b4d.jpg', 31, 0),
