      x.drawImage(dr2,l[0]+iw/4,l[1]+ih/4,iw/2,ih/2)\n        }\n      }\n      return v\n    }).filter(v=>v[1]<G)\n    x.globalAlpha=1\n  }\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'mazzy star - fade into you (unicorn mix)', 145, 'whitehot robot', '2022-04-09 14:26:48', '[600166,600165,600164,600163,600161,600157,600155,600154,600153,600151,600150,600149,600148,600147,600146,600145,600144,600143,600142,600141,600140,600139,600138,600137,600136,600135]', 213, 'https://code.dweet.net/thumbs/10f15e8cf48bb6949f94cdc4826c8527.jpg', 28, 0),
(600168, 'https://srmcgann.github.io/assets/dWqCY.mp4', 'song = \'https://audiocloud.rotoblaster.com/audio/5e2d8b2bc59d08ab711e94c8e0b152a6.MP3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(!t){\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    Rn=Math.random\n    bgimg = new Image()\n    go=playing=false\n    bgimg.addEventListener(\'load\',()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/1BHoLL.jpg\'\n    iBc=5,iBv=.16,iBs=99,G=10\n    iPc=20,iPv=.07,iOBc=3,iOBr=.013\n    iPs=8,iPr=20\n    B=Array(iBc).fill().map(v=>{\n      X=(Rn()-.5)*G\n      Y=(Rn()-.5)*G\n      Z=0\n      return [X,Y,Z,S(p=Math.PI*2*Rn())*iBv,C(p)*iBv,0]\n    })\n    P=[]\n    for(cb=[],j=6;j--;)for(i=4;i--;)cb=[...cb,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n    OB=Array(iOBc).fill().map((v,j)=>{\n      X=S(p=Math.PI*2/iOBc*j)*G/3\n      Y=C(p)*G/3\n      Z=0\n      a=[]\n      d=G/7+Rn()*G/7\n      for(i=sd=3+j;i--;){\n        a=[...a,[S(p=Math.PI*2/sd*i)*d,C(p)*d,0]]\n      }\n      return [X,Y,Z,a,sd]\n    })\n    x.lineCap=x.lineJoin=\'round\'\n  }\n  if(go){\n    if(!playing)mp3.play(),playing=true\n    oX=0,oY=0,oZ=G*1.2+S(t/2)*4\n    Rl=S(t/3)/4\n    Pt=C(-t)/3\n    Yw=S(t/2)/2\n    x.globalAlpha=.2\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0013\',x.fillRect(0,0,c.width,c.height)\n    \n    OB.map((v,i)=>{\n      tx=v[0]\n      ty=v[1]\n      tz=v[2]\n      v[3].map((q,j)=>{\n        X=q[0]\n        Y=q[1]\n        Z=q[2]\n        q[0]=S(p=Math.atan2(X,Y)+iOBr*(i%2?-1:1))*(d=Math.hypot(X,Y))\n        q[1]=C(p)*d\n        if(!(j%v[4])) x.beginPath()\n        X+=tx\n        Y+=ty\n        Z+=tz\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n        if(j%v[4]==v[4]-1){\n          x.closePath()\n          x.lineWidth=160/Z\n          x.strokeStyle=`hsla(${t*200},99%,40%,.2`\n          x.stroke()\n          x.fillStyle=`hsla(${t*200},99%,10%,.1`\n          x.fill()\n          x.lineWidth=50/Z\n          x.strokeStyle=\'#fff6\'\n          x.stroke()\n        }\n      })\n    })\n\n    cb.map((v,i)=>{\n      if(!(i%4))x.beginPath()\n      X=v[0]*(d=G/(2**.5/2)/2)\n      Y=v[1]*d\n      Z=v[2]*d\n      R(Rl,Pt,Yw,1)\n      x.lineTo(...Q())\n      if(i%4==3){\n        x.closePath()\n          x.lineWidth=6\n          x.strokeStyle=`hsla(${t*200},50%,20%,.1`\n          x.stroke()\n          //x.fillStyle=`hsla(${t*200},99%,20%,.06`\n          //x.fill()\n          x.lineWidth=2\n          x.strokeStyle=\'#fff2\'\n          x.stroke()\n      }\n    })\n    B.map(n=>{\n      d=Math.hypot(n[3],n[4],n[5])\n      n[3]/=d\n      n[4]/=d\n      n[5]/=d\n      n[3]*=iBv\n      n[4]*=iBv\n      n[5]*=iBv\n      X=n[0]+=n[3]\n      Y=n[1]+=n[4]\n      Z=n[2]+=n[5]\n\n      OB.map(v=>{\n        v[3].map((q,j)=>{\n          X1=X,Y1=Y,X2=X+n[3]*2,Y2=Y+n[4]*2,X3=v[0]+q[0],Y3=v[1]+q[1],X4=v[0]+v[3][(j+1)%v[4]][0],Y4=v[1]+v[3][(j+1)%v[4]][1]\n          if(a=I(X1,Y1,X2,Y2,X3,Y3,X4,Y4)){\n            nx=Y3-Y4\n            ny=X4-X3\n            d=Math.hypot(nx,ny)\n            nx/=d\n            ny/=d\n            ax=X2-X1\n            ay=Y2-Y1\n            p1=Math.atan2(ax,ay)\n            p2=Math.atan2(nx,ny)\n            if(Math.abs(p1-p2)>Math.PI){\n              if(p1<p2){\n                p1+=Math.PI*2\n              }else{\n                p2+=Math.PI*2\n              }\n            }\n            n[3]/=2\n            n[4]/=2\n            n[3]-=nx/8\n            n[4]-=ny/8\n          }\n        })\n      })\n\n\n      for(m=iPc;m--;)P=[...P,[X,Y,Z,S(p=Math.PI*2*Rn())*iPv,C(p)*iPv,0,iPs]]\n      for(m=3;m--;)if(n[m]>G/2||n[m]<-G/2)n[3+m]*=-1\n      R(Rl,Pt,Yw,1)\n      x.beginPath()\n      x.arc(...Q(),iBs/Z,0,7)\n      x.fillStyle=\'#afa8\'\n      x.fill()\n    })\n    \n    P=P.map(n=>{\n      d=Math.hypot(n[3],n[4],n[5])\n      n[3]/=d\n      n[4]/=d\n      n[5]/=d\n      n[3]*=iPv\n      n[4]*=iPv\n      n[5]*=iPv\n      X=n[0]+=n[3]\n      Y=n[1]+=n[4]\n      Z=n[2]+=n[5]\n      \n      OB.map(v=>{\n        v[3].map((q,j)=>{\n          X1=X,Y1=Y,X2=X+n[3]*3,Y2=Y+n[4]*3,X3=v[0]+q[0],Y3=v[1]+q[1],X4=v[0]+v[3][(j+1)%v[4]][0],Y4=v[1]+v[3][(j+1)%v[4]][1]\n          if(a=I(X1,Y1,X2,Y2,X3,Y3,X4,Y4)){\n            nx=Y3-Y4\n            ny=X4-X3\n            d=Math.hypot(nx,ny)\n            nx/=d\n            ny/=d\n            ax=X2-X1\n            ay=Y2-Y1\n            p1=Math.atan2(ax,ay)\n            p2=Math.atan2(nx,ny)\n            if(Math.abs(p1-p2)>Math.PI){\n              if(p1<p2){\n                p1+=Math.PI*2\n              }else{\n                p2+=Math.PI*2\n              }\n            }\n            n[3]/=1.5\n            n[4]/=1.5\n            n[3]-=nx/20\n            n[4]-=ny/20\n          }\n        })\n      })\n      \n      R(Rl,Pt,Yw,1)\n      x.fillStyle=\'#22ccff18\'\n      x.fillStyle=`hsla(${n[6]*199+t*200},99%,${50+(1+n[6])**6/8000}%,.05`\n      l=Q()\n      s=(n[6]/=1.025)*iPr/Z\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      return n\n    }).filter(v=>Math.abs(v[0])<G/2&&Math.abs(v[1])<G/2&&Math.abs(v[2])<G/2&&v[6]>2)\n  }\n        \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'ocean', 145, 'whitehot robot', '2022-04-09 14:26:48', '[600167,600166,600165,600164,600163,600161,600157,600155,600154,600153,600151,600150,600149,600148,600147,600146,600145,600144,600143,600142,600141,600140,600139,600138,600137,600136,600135]', 210, 'https://code.dweet.net/thumbs/2f280f45d2d7586eebdc2c7d34eeb6d5.jpg', 14, 0);
