se\n    bgimg.addEventListener(\'load\',()=>{\n      go = true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/1OFK3N.jpg\'\n    img=new Image()\n    img.src=\'https://srmcgann.github.io/assets/11ScI8.png\'\n    iBc=16\n    G=16\n    Bh=Array(1e3).fill().map((v,i)=>{\n      return [(Rn()-.5)*G,(Rn()-.5)*G/1.77777778,Rn()*G/2,Rn(),i]\n    })\n    drawRotatedImage=(img, X, Y, W, H, a)=>{\n      x.save()\n      x.translate(X,Y)\n      x.rotate(a)\n      x.drawImage(img, -W/2, -H/2, W, H)\n      x.translate(-X,-Y)\n      x.restore()\n    }\n  }\n  if(go&&go1){\n    let idx=[]\n    Bh.map((v,i)=>{\n      idx=[...idx,[v[2], i]]\n    })\n    idx.sort((a,b)=>b[0]-a[0])\n    Rl=0,Pt=0,Yw=0\n    oX=0,oY=0,oZ=0\n    x.globalAlpha = .4\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha = 1\n    x.fillStyle=\'#4002\',x.fillRect(0,0,c.width,c.height)\n    Bh.map((v,i)=>{\n      X=Bh[idx[i][1]][0]\n      Y=Bh[idx[i][1]][1]\n      Z=Bh[idx[i][1]][2]-=.04\n      if(Z<0)Bh[idx[i][1]][2]+=G/2\n      R(Rl,Pt,Yw,1)\n      l=Q()\n      s=Math.max(.1,Z**1.2)*1.5*(2+S(Bh[idx[i][1]][3])*1.01)\n      iw = img.width/s/2\n      ih = img.height/s/2\n      x.globalAlpha = (1 / (1+Z**5/2e3))*Math.min(1,Z/3)\n      drawRotatedImage(img, ...l, iw, ih, S(Bh[idx[i][1]][3])*Math.PI*2+t*(S(Bh[idx[i][1]][3])+.5)*4*(idx[i][1]%2?-1:1))\n    })\n    \n    if(!playing)mp3.play(),playing=true\n    \n    x.globalAlpha=1\n    oX=0,oY=0,oZ=2\n    Rl=S(t)/2,Pt=-Math.PI,Yw=S(t/4)*3\n    \n    B.map(v=>{\n\n      ax=ay=az=0\n      x.beginPath()\n      for(i=v.length;i--;){\n        ax+=X=v[i][0]\n        ay+=Y=v[i][1]\n        az+=Z=v[i][2]\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n      }\n      //x.closePath()\n      //x.strokeStyle=\'#ffffff18\'\n      //x.lineWidth=3/Z\n      //x.stroke()\n      x.strokeStyle=\'#fae2\'\n      x.lineWidth=12/Z|0\n      x.stroke()\n      //x.fillStyle=\'#ff448810\'\n      //x.fill()\n      ax/=v.length\n      ay/=v.length\n      az/=v.length\n      X1=v[0][0]-ax\n      Y1=v[0][1]-ay\n      Z1=v[0][2]-az\n      X2=v[1][0]-ax\n      Y2=v[1][1]-ay\n      Z2=v[1][2]-az\n      nx=Y1*Z2-Z1*Y2\n      ny=Z1*X2-X1*Z2\n      nz=X1*Y2-Y1*X2\n      p1=Math.atan2(nx,nz)\n      p2=Math.PI/2-Math.acos(ny/Math.hypot(nx,ny,nz))\n      for(i=v.length;i--;){\n        if(Rn()<.04){\n          for(m=1;m--;){\n            X=v[i][0]-ax\n            Y=v[i][1]-ay\n            Z=v[i][2]-az\n            R(0,0,-p1)\n            R(0,-p2,0)\n            Z=0\n            X1=0\n            Y1=0\n            X2=S(p=Math.PI*2*Rn())*G\n            Y2=C(p)*G\n            X3=X\n            Y3=Y\n            X=v[l=(i+1)%v.length][0]-ax\n            Y=v[l][1]-ay\n            Z=v[l][2]-az\n            R(0,0,-p1)\n            R(0,-p2,0)\n            X4=X\n            Y4=Y\n            pt=I(X1,Y1,X2,Y2,X3,Y3,X4,Y4)\n            X=pt[0]*(d=Rn()**.5)\n            Y=pt[1]*d\n            Z=0\n            R(0,p2,p1)\n            X+=ax,Y+=ay,Z+=az\n            P=[...P,[X,Y,Z,1]]\n          }\n        }\n      }\n    })\n   \n    P=P.map(v=>{\n      X=v[0]\n      Y=v[1]\n      Z=v[2]\n      R(Rl,Pt,Yw,1)\n      s=16/Z*(v[3]/=1.1)\n      l=Q()\n      x.fillStyle=`hsla(${0},99%,${50+((2+v[3])**5)/4}%,.7`\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      return v\n    }).filter(v=>v[3]>.2)\n    x.globalAlpha=Math.max(0, S(t*2)/1.5)\n    x.fillStyle=\'#f04\'\n    x.strokeStyle=\'#fac8\'\n    x.font=\"500px \'alice\'\"\n    x.fillText(\'happy\', c.width/2-400,c.height/2-200)\n    x.strokeText(\'happy\', c.width/2-400,c.height/2-200)\n\n    x.font=\"450px \'alice\'\"\n    x.fillText(\'valentine\\\'s\', c.width/2-750,c.height/2+100)\n    x.strokeText(\'valentine\\\'s\', c.width/2-750,c.height/2+100)\n   \n    x.font=\"600px \'alice\'\"\n    x.fillText(\'day!\', c.width/2-380,c.height/2+480)\n    x.strokeText(\'day!\', c.width/2-380,c.height/2+480)\n    x.globalAlpha=1\n  }\n  \n\n  t+=1/60\n  \n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', '    @font-face {\n      font-family: \'alice\';\n      src:  url(\'https://twilightparadox.com/Alice_in_Wonderland_3.woff2\') format(\'woff2\'),\n            url(\'https://twilightparadox.com/Alice_in_Wonderland_3.woff\') format(\'woff\');\n    }\n\nbody,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}\nbody,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: #fff;\n  transform: translate(-50%, -50%);\n}', '<div style=\"font-family: alice;position:absolute; z-index:-100\">a</div>\n<canvas id=c>', 'For Jenifer - pogues - love you till the end (performed by birds of a feather) (unicorn mix)', 145, 'whitehot robot', '2022-04-09 14:26:48', '[600179,600178,600177,600174,600173,600171,600170,600168,600167,600166,600165,600164,600163,600161,600157,600155,600154,600153,600151,600150,600149,600148,600147,600146,600145,600144,600143,600142,600141,600140,600139,600138,600137,600136,600135]', 167, 'https://code.dweet.net/thumbs/900297dccad1c9858e0a9d57175874fe.jpg', 15, 0);
