(600181, 'https://srmcgann.github.io/assets/6aoc4.mp4', 'song = \'https://audiocloud.rotoblaster.com/audio/c6cbe194a8cc6da1b896a350ded06c76.MP3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(!t){\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    Rn=Math.random\n    x.lineJoin=x.lineCap=\'round\'\n    sd=10\n    shp=[]\n    G=2.75\n    iBc=7\n    lsi=.2\n    for(i=sd;i--;){\n      ls=lsi*(i%2?.5:1.25)\n      X1=S(p=Math.PI*2/sd*i)*ls\n      Y1=0\n      Z1=C(p)*ls\n      ls=lsi*((i+1)%2?.5:1.25)\n      X2=S(p=Math.PI*2/sd*(i+1))*ls\n      Y2=0\n      Z2=C(p)*ls\n      X3=0\n      Y3=lsi/3\n      Z3=0\n      shp=[...shp, [[X1,Y1,Z1],[X2,Y2,Z2],[X3,Y3,Z3]]]\n    }\n    \n    B=Array(iBc).fill().map(v=>{\n      ls=2//+Rn()*3\n      tx=(Rn()-.5)*G\n      ty=(Rn()-.5)*G\n      tz=(Rn()-.5)*G\n      P=[]\n      trl=Math.PI*Rn()*2\n      tpt=Math.PI*Rn()*2\n      tyw=Math.PI*Rn()*2\n      for(j=2;j--;){\n        shp.map(q=>{\n          a=[]\n          for(m=3;m--;){\n            X=q[m][0]*ls\n            Y=q[m][1]*ls*(j%2?1:-1)\n            Z=q[m][2]*ls\n            R(trl,tpt,tyw)\n            a=[...a,[X,Y,Z]]\n          }\n          P=[...P, a]\n        })\n      }\n      return JSON.parse(JSON.stringify([tx,ty,tz,P]))\n    })\n    P=[]\n    bgimg = new Image()\n    go=playing=false\n    bgimg.addEventListener(\'load\',()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/26a7bw.jpg\'\n  }\n\n  if(go){\n    if(!playing)mp3.play(),playing=true\n    x.globalAlpha=.35\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#1021\',x.fillRect(0,0,c.width,c.height)\n    oX=0,oY=0,oZ=2.5\n    Rl=-t/10,Pt=-t/6,Yw=S(t/8)*6\n    \n\n    RP=q=>{\n      R(0,-t,S(t/2+q)*6)\n    }\n\n    B.map((q,j)=>{\n      tx=q[0]\n      ty=q[1]\n      tz=q[2]\n      q[3].map(v=>{\n        ax=ay=az=0\n        x.beginPath()\n        for(i=v.length;i--;){\n          ax+=X=v[i][0]\n          ay+=Y=v[i][1]\n          az+=Z=v[i][2]\n          RP(j)\n          X+=tx\n          Y+=ty\n          Z+=tz\n          R(Rl,Pt,Yw,1)\n          x.lineTo(...Q())\n        }\n        x.closePath()\n        x.strokeStyle=\'#ffffff20\'\n        x.lineWidth=10/Z\n        x.stroke()\n        x.strokeStyle=\'#2fc1\'\n        x.lineWidth=30/Z\n        x.stroke()\n        x.fillStyle=\'#00ffee0a\'\n        x.fill()\n        ax/=v.length\n        ay/=v.length\n        az/=v.length\n        X1=v[0][0]-ax\n        Y1=v[0][1]-ay\n        Z1=v[0][2]-az\n        X2=v[1][0]-ax\n        Y2=v[1][1]-ay\n        Z2=v[1][2]-az\n        nx=Y1*Z2-Z1*Y2\n        ny=Z1*X2-X1*Z2\n        nz=X1*Y2-Y1*X2\n        p1=Math.atan2(nx,nz)\n        p2=Math.PI/2-Math.acos(ny/Math.hypot(nx,ny,nz))\n        for(i=v.length;i--;){\n          if(Rn()<.4){\n            for(m=1;m--;){\n              X=v[i][0]-ax\n              Y=v[i][1]-ay\n              Z=v[i][2]-az\n              R(0,0,-p1)\n              R(0,-p2,0)\n              Z=0\n              X1=0\n              Y1=0\n              X2=S(p=Math.PI*2*Rn())*G\n              Y2=C(p)*G\n              X3=X\n              Y3=Y\n              X=v[l=(i+1)%v.length][0]-ax\n              Y=v[l][1]-ay\n              Z=v[l][2]-az\n              R(0,0,-p1)\n              R(0,-p2,0)\n              X4=X\n              Y4=Y\n              pt=I(X1,Y1,X2,Y2,X3,Y3,X4,Y4)\n              X=pt[0]*(d=Rn()**.5)\n              Y=pt[1]*d\n              Z=0\n              R(0,p2,p1)\n              X+=ax,Y+=ay,Z+=az\n              P=[...P,[tx,ty,tz,X,Y,Z,1,j]]\n            }\n          }\n        }\n      })\n    })\n   \n    P=P.map(v=>{\n      X=v[3]\n      Y=v[4]\n      Z=v[5]\n      RP(v[7])\n      X+=v[0]\n      Y+=v[1]\n      Z+=v[2]\n      R(Rl,Pt,Yw,1)\n      s=20/Z*(v[6]/=1.05)\n      l=Q()\n      x.fillStyle=`hsla(${180},99%,${50+((2+v[6])**5)/4}%,.4`\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      return v\n    }).filter(v=>v[6]>.2)\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'madonna - lucky star (unicorn mix)', 145, 'whitehot robot', '2022-04-09 14:26:48', '[600180,600179,600178,600177,600174,600173,600171,600170,600168,600167,600166,600165,600164,600163,600161,600157,600155,600154,600153,600151,600150,6