(600182, 'https://srmcgann.github.io/assets/Q8WN6.mp4', 'song = \'https://audiocloud.rotoblaster.com/audio/a9e4200d05376f6325e271ca5f4384a5.MP3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\nif(!t){var E=q=>{c.width=1920/1.5,c.height=1080/1.5|0};E();bg=new Image();bg.addEventListener(\'load\',()=>{go=true});bg.src=\'https://srmcgann.github.io/assets/1ai8yE.jpg\';go=playing=false;};if(go){if(!playing)mp3.play(),playing=true;for(o=(k=32)*25,x[g=\'globalAlpha\']=.4,x.drawImage(bg,0,0,w=c.width,c.height),x[g]=1,x.fillStyle=\'#0005\',x.fillRect(0,0,w,w),x.fillStyle=\'#0663\',x.strokeStyle=\'#4cf8\',j=6,b=[];j--;b=[...b,T])for(i=4,T=[];i--;T=[...T,[a[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]])a=[S(p=1.57*i+.79),C(p),.71];for(j=100,h=152;j--;){l=j**3.2,p1=7*l+t*4,p2=7*l/2-t*2,b.map(v=>{x.beginPath(),v.map(v=>{X=S(p1+(p=(M=Math).atan2(a=v[0],e=v[2])))*(d=(H=M.hypot)(a,e)),Z=C(p1+p)*d,d=H(Z,e=v[1]),Y=S(p2+(p=M.atan2(Z,e)))*d,Z=C(p2+p)*d,X+=l%k-k/2,Y+=l/9%k-k/2,d=H(X,Y),X=S(p=M.atan2(X,Y)+S(t/4)*6)*d,Y=C(p)*d,x.lineTo(w/2+X/(Z=Z+h*2-(l*l+t*h*1.5+(S(t*1.5)*150))%(h*2-2))*o,c.height/2+Y/Z*o)}),x[g]=1/(1+(99+Z)**6/1e14)*Math.min(1,Z**2/2e3),x.lineWidth=1+1e3/Z/Z|0,x.stroke(),x.fill()})}}\n\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.desti