      }\n      }\n    })\n    B.map(v=>{\n      X=v[0]+=v[3]\n      Y=v[1]+=v[4]\n      Z=v[2]+=v[5]\n      if(X<-G/2 || X>G/2) v[3]*=-1\n      if(Y<-G/2 || Y>G/2) v[4]*=-1\n      if(Z<-G/2 || Z>G/2) v[5]*=-1\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        x.beginPath()\n        x.arc(...Q(),Math.min(80,iBr/Z/Z),0,7)\n        x.fillStyle=\'#f168\'\n        x.fill()\n        x.beginPath()\n        x.arc(...Q(),Math.min(40,iBr/Z/Z/2),0,7)\n        x.fillStyle=\'#fff8\'\n        x.fill()\n      }\n    })\n    P2=P2.map(v=>{\n      X=v[0]+=v[3]\n      Y=v[1]+=v[4]\n      Z=v[2]+=v[5]\n      R(Rl,Pt,Yw,1)\n      v[6]+=1\n      l=Q()\n      x.fillStyle=`hsla(${80-v[6]},99%,${130-v[6]*1.1}%,.5)`\n      s=Math.min(40,2+(99-v[6]/2)/Z/Z)\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      return v\n    }).filter(v=>v[6]<99)\n    P=P.map((v,i)=>{\n      v[7]=v[7].map((q,j)=>{\n        X=q[0]\n        Y=q[1]\n        Z=q[2]\n        R(Rl,Pt,Yw,1)\n        if(j&&Z>0&&j<v[7].length-1){\n          x.beginPath()\n          x.lineTo(...Q())\n          X=v[7][j+1][0]\n          Y=v[7][j+1][1]\n          Z=v[7][j+1][2]\n          R(Rl,Pt,Yw,1)\n          if(Z>0){\n            x.lineTo(...Q())\n            x.lineWidth=Math.min(40,4*j/Z)\n            x.strokeStyle=`#6fc3`\n            x.stroke()\n          }\n        }\n        return q\n      }).filter((q,j)=>!(!j&&v[7].length>20))\n      X=v[0]+=v[3]\n      Y=v[1]+=v[4]\n      Z=v[2]+=v[5]\n      mind=6e6\n      B.map((q,j)=>{\n        bx=q[0]\n        by=q[1]\n        bz=q[2]\n        d=H(X-bx,Y-by,Z-bz)\n        if(d<mind){\n          mind=d\n          tj=j\n        }\n      })\n      B.map((q,j)=>{\n        if(tj==j){\n          bx=q[0]\n          by=q[1]\n          bz=q[2]\n          d=1+H(bx-X,by-Y,bz-Z)\n          v[3]+=(bx-X)/1.5/(d**3.85)\n          v[4]+=(by-Y)/1.5/(d**3.85)\n          v[5]+=(bz-Z)/1.5/(d**3.85)\n          d2=H(v[3],v[4],v[5])\n          v[3]/=d2\n          v[4]/=d2\n          v[5]/=d2\n          v[3]*=iPv\n          v[4]*=iPv\n          v[5]*=iPv\n          if(d<1.1){\n            v[6]=6e6\n            for(n=99;n--;){\n              vel=.5+(Rn()-.5)/3\n              P2 = [...P2,[v[0],v[1],v[2],v[3]*vel+(Rn()-.5)/50,v[4]*vel+(Rn()-.5)/50,v[5]*vel+(Rn()-.5)/50,0]]\n            }\n          }\n        }\n      })\n      R(Rl,Pt,Yw,1)\n      v[6]+=.1\n      v[7]=[...v[7],[...v]]\n      if(Z>0){\n        x.beginPath()\n        x.arc(...Q(),Math.min(99,iPr/Z),0,7)\n        x.fillStyle=\'#fffc\'\n        x.fill()\n        x.arc(...Q(),Math.min(99,iPr/Z/2),0,7)\n        x.fillStyle=\'#fff7\'\n        x.fill()\n      }\n      return v\n    }).filter(v=>v[6]<100)\n  }\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'natural fun', 145, 'whitehot robot', '2022-04-09 14:26:48', '[600191,600189,600182,600181,600180,600179,600