(600194, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\nrsz=window.onresize=()=>{\n  c.width=c.clientWidth\n  c.height=c.clientHeight\n}\nrsz()\n\nDraw=()=>{\n\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    Rn=Math.random\n    G=100\n    B=Array(100).fill().map((v,i)=>{\n      X=(Rn()-.5)*2\n      Y=(Rn()-.5)*2\n      Z=(Rn()-.5)*2\n      d=Math.hypot(X,Y,Z)\n      X=X/d*G*3.5\n      Y=Y/d*G*3.5\n      Z=Z/d*G*3.5\n      return [X,Y,Z]\n    })\n    cl=6,rw=4\n  }\n  eyerad=50//-S(t*2)*5\n  G2=G*2+S(t*1)*G/1.5\n  P=Array(cl*(rw-1)).fill().map((v,i)=>{\n    j=(i/cl|0)+1\n    p1=Math.PI*2/cl*i\n    p2=Math.PI/rw*j\n    X=S(p1)*S(p2)*G2\n    Y=C(p2)*G2\n    Z=C(p1)*S(p2)*G2\n    return [X,Y,Z]\n  })\n  P=[...P,[0,0,0]]\n\n  oX=oY=0,oZ=350-S(t/2.5-1.4)*200\n  Rl=0,Pt=S(t/14)*20,Yw=-C(t/3)*16\n  Rl2=0,Pt2=-S(t/7)*5,Yw2=-C(t/4)*2\n  x.fillStyle=\'#0004\'\n  x.fillRect(0,0,c.width,c.height)\n  col=\'#44ff8818\'\n  col2=\'#4f84\'\n\n  B.map(v=>{\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    //R(Rl2,Pt2,Yw2,0)\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      x.beginPath()\n      l=Q()\n      s=Math.min(1400,25000/(Z**1))\n      x.arc(...l,s,0,7)\n      x.fillStyle=col\n      x.fill()\n      x.beginPath()\n      s/=2\n      //x.fillStyle=\'#ffec\'\n      x.fillStyle=col2\n      x.arc(...l,s,0,7)\n      x.fill()\n      x.beginPath()\n      s/=2\n      x.fillStyle=\'#fff\'\n      x.arc(...l,s,0,7)\n      x.fill()\n    }\n  })\n  P.map(v=>{\n    tx=v[0]\n    ty=v[1]\n    tz=v[2]\n    X=tx,Y=ty,Z=tz\n    R(Rl2,Pt2,Yw2,0)\n    R(0,0,0,1)\n    if(Z>0){\n      x.beginPath()\n      x.arc(...Q(),eyerad*900/(Z),0,7)\n      x.fillStyle=\'#22ffdd18\'\n      x.fill()\n    }\n })\n  P.map(v=>{\n    tx=v[0]\n    ty=v[1]\n    tz=v[2]\n    B.map(q=>{\n      X=q[0]\n      Y=q[1]\n      Z=q[2]\n      R(Rl,Pt,Yw,0)\n      R(0,0,-Yw2,0)\n      R(0,-Pt2,0,0)\n      R(-Rl2,0,0,0)\n      X+=tx,Y+=ty,Z+=tz\n      d1=H(X,Y,Z)\n      X/=d1\n      Y/=d1\n      Z/=d1\n      //d1=H(X-tx,Y-ty,Z-tz)\n      X*=eyerad\n      Y*=eyerad\n      Z*=eyerad\n      X-=tx\n      Y-=ty\n      Z-=tz\n      R(Rl2,Pt2,Yw2,0)\n      R(0,0,0,1)\n      if(Z>0){\n        l=Q()\n        s=Math.min(600, 15000000/(((d1+Z)**2)**1))\n        x.fillStyle=col\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=4\n        x.fillStyle=\'#fff\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n    })\n  })\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nDraw()', 'html, body{\n  margin: 0;\n  overflow: hidden;\n  backgroung: linear-gradient(45deg, #000, #123);\n  height: 100vh;\n}\n#c{\n  width: 100%;\n  height: 100%;\n}', '<canvas id=c>', 'faux reflectivity', 145, 'whitehot robot', '2022-04-09 22:28:21', '', 61, '', 0, 1),
(600195, '', '      //---- do not edit the following code (you can indent as you wish)\n      let alphabet = \"123456789abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ\"\n      var fxhash = \"oo\" + Array(49).fill(0).map(_=>alphabet[(Math.random()*alphabet.length)|0]).join(\'\')\n      let b58dec = (str) => str.split(\'\').reduce((p,c,i) => p + alphabet.indexOf(c) * (Math.pow(alphabet.length, str.length-i-1)), 0)\n      let fxhashTrunc = fxhash.slice(2)\n      let regex = new RegExp(\".{\" + ((fxhashTrunc.length/4)|0) + \"}\", \'g\')\n      let hashes = fxhashTrunc.match(regex).map(h => b58dec(h))\n      let sfc32 = (a, b, c, d) => {\n        return () => {\n          a |= 0; b |= 0; c |= 0; d |= 0\n          var t = (a + b | 0) + d | 0\n          d = d + 1 | 0\n          a = b ^ b >>> 9\n          b = c + (c << 3) | 0\n          c = c << 21 | c >>> 11\n          c = c + t | 0\n          return (t >>> 0) / 4294967296\n        }\n      }\n      var fxrand = sfc32(...hashes)\n      //---- /do not edit the following code\n\n      c=document.querySelector(\'#c\')\n      x=c.getContext(\'2d\')\n      S=Math.sin\n      C=Math.cos\n      t=playing=0\n      window.onclick=()=>{if(!playing)mp3.play()}\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n      Draw=()=>{\n    if(!t){\n      R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n      Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n      mp3 = new Audio()\n      mp3.loop=true\n      mp3.onplaying=()=>{playing=true}\n      mp3.oncanplay=()=>{if(!playing)mp3.play()}\n      mp3.src=\'89f23a462e4beb6ee2aa6abb58e3c465.MP3\'\n      Rn=fxrand\n      go=false\n      c2=c.cloneNode()\n      c2.width=960/4\n      c2.height=540/4\n      x_=c2.getContext(\'2d\')\n      imgs = Array(2).fill().map((v, i)=>{\n        v = {img: new Image(), loaded: false, data: [], originalDataArray: []}\n        v.img.onload=()=>{\n          v.loaded = true\n          x_.drawImage(v.img, 0, 0, c2.width, c2.height)\n          v.data = x_.getImageData(0, 0, c2.width, c2.height)\n          //v.originalData = JSON.parse(JSON.stringify(v.data.data))\n          if(!imgs.filter(v=>!v.loaded).length) go = true\n        }\n        s=\'/video/\'\n        v.img.src = s+(i?\'2etjMJ.jpg\':\'1ydph8.jpg\')\n        return v\n      })\n      tx=Array(imgs.length).fill(0)\n      ty=Array(imgs.length).fill(0)\n      bg=new Image()\n      bg.src=s+\'2h9kBr.jpg\'\n    }\n\n    x.globalAlpha=.5\n    x.drawImage(bg, 0,0,c.width,c.height)\n    x.globalAlpha=1\n\n    if(go){\n      imgs.map((v,i)=>{\n        tx[i]-=S(t/4+i*9)*1.5\n        ty[i]+=S(t+i*3)*1\n        if(1||i){\n          for(j=0; j<v.data.data.length; j+=4){\n            X=(j/4|0)%c2.width\n            Y=(j/4)/c2.width|0\n            X+=tx[i]\n            Y+=ty[i]\n            while(X<0)X+=c2.width\n            while(Y<0)Y+=c2.height\n            X=X%c2.width\n            Y=Y%c2.height\n            //v.data.data[j+0]=v.data.data[j+0]\n            //v.data.data[j+1]=v.data.data[j+1]\n            //v.data.data[j+2]=v.data.data[j+2]\n            d=Math.hypot(e=c2.width/2-X, f=c2.height/2-Y)*1.65\n            v.data.data[j+3]=Math.max(0, Math.min(255, ((1+S(S(-t*8+i*9+d/16)*3+Math.atan2(e,f)*3+t*13+i*9)*5/(1+d**6/4e11)+S(-t*8+i*9+d/(20+S(t+i*Math.PI/2)*16))/(1+d**5/8e10)*6))**2*6))|0\n          }\n        }\n        //v.data.data = JSON.parse(JSON.stringify(v.originalDataArray))\n        //x.clearRect(0,0,c.width,c.height)\n        x_.putImageData(v.data, 0, 0)\n        x.drawImage(c2,0,0,c.width,c.height)\n      })\n    }\n\n    t+=1/60\n    requestAnimationFrame(Draw)\n      }\n      Draw()\n', 'html, body{\n  height: 100vh;\n  background: linear-gradient(45deg,#000,#123);\n  overflow: hidden;\n  margin: 0;\n}\n#c{\n  width: 100%;\n  height: 100%\n}', '<canvas id=c>', 'alpha interpolation', 145, 'whitehot robot', '2022-04-12 16:44:25', '', 23, '', 0, 1),
(600196, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\nrsz=window.onresize=()=>{\n  c.width=c.clientWidth\n  c.height=c.clientHeight\n}\nrsz()\n\nDraw=()=>{\n\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    Rn=Math.random\n    G=200,g = 1400\n    B=Array(8).fill().map(v=>{\n      X=(Rn()-.5)*G\n      Y=(Rn()-.5)*G\n      Z=(Rn()-.5)*G\n      return [X, Y, Z, Math.PI*Rn()*2, Math.PI*Rn()*2,(Rn()-.5)/g,(Rn()-.5)/g, Rn()*99]\n    })\n    \n  }\n\n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin=x.lineCap=\'round\'\n\n  oX=oY=0, oZ=G/1.5+S(t)*G/3\n  Rl=0,Pt=-S(t/10)*6,Yw=S(t/6)*2\n  B.map(v=>{\n    tx=v[0]\n    ty=v[1]\n    tz=v[2]\n    v[3]+=v[5]\n    v[4]+=v[6]\n    v[7]+=.5\n    sd=12\n    for(j=15;j--;){\n      ls1=v[7]+j*2\n      ls1=ls1%60\n      ls2=ls1+2\n      for(i=sd;i--;){\n        x.beginPath()\n        X=S(p=Math.PI*2/sd*i)*ls1\n        Y=C(p)*ls1\n        Z=0\n        R(0,v[3],v[4],0)\n        X+=tx,Y+=ty,Z+=tz\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        X=S(p=Math.PI*2/sd*i)*ls2\n        Y=C(p)*ls2\n        Z=0\n        R(0,v[3],v[4],0)\n        X+=tx,Y+=ty,Z+=tz\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        X=S(p=Math.PI*2/sd*(i+1))*ls2\n        Y=C(p)*ls2\n        Z=0\n        R(0,v[3],v[4],0)\n        X+=tx,Y+=ty,Z+=tz\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        X=S(p=Math.PI*2/sd*(i+1))*ls1\n        Y=C(p)*ls1\n        Z=0\n        R(0,v[3],v[4],0)\n        X+=tx,Y+=ty,Z+=tz\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        x.closePath()\n        x.lineWidth=Math.min(200, 3000/(Z**1.5))\n        x.fillStyle=`hsla(${360/15*i*2+t*300+2*(a=1/(1+(5+S(Math.PI*2/15*(j+1)+Math.PI/2-.15)*5)*20**3/1e4)/(1+ls2**4/1999999))*99+t*200},99%,${20+a*150}%,1)`\n        x.globalAlpha=a\n        x.fill()\n      }\n    }\n    x.globalAlpha=1\n  })\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nDraw()', 'html, body{\n  margin: 0;\n  overflow: hidden;\n  backgroung: linear-gradient(45deg, #000, #123);\n  height: 100vh;\n}\n#c{\n  width: 100%;\n  height: 100%;\n}', '<canvas id=c>', 'haloes', 145, 'whitehot robot', '2022-04-14 22:30:52', '[600194]', 44, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600197, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin      \nC=Math.cos\nt=playing=0\nwindow.onclick=()=>{if(!playing)mp3.play()}\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    mp3 = new Audio()\n    mp3.loop=true\n    mp3.onplaying=()=>{playing=true}\n    mp3.oncanplay=()=>{go=true;if(!playing)mp3.play()}\n    mp3.src=\'https://audiocloud.rotoblaster.com/audio/54862b4e4a45424f48098207dd8c8605.MP3\'\n    Rn=Math.random\n\n    DrawSolid=(dod, sx, sy, sz, strokeStyle, fillStyle, useFill, globalAlpha) => {\n      dod.map(v=>{\n        x.beginPath()\n        v.map((q,j)=>{\n          X=q[0]+sx\n          Y=q[1]+sy\n          Z=q[2]+sz\n          R(Rl,0,Yw,0)\n          R(0,Pt,0,1)\n          if(Z>0)x.lineTo(...Q())\n        })\n        x.closePath()\n        x.lineWidth=Math.min(200,3e5/(Z**1.25))\n        x.globalAlpha=.3*globalAlpha\n        x.strokeStyle=strokeStyle\n        x.stroke()\n        x.lineWidth/=7\n        x.lineWidth=Math.max(x.lineWidth, 1)\n        x.globalAlpha=1*globalAlpha\n        x.strokeStyle=\'#fff8\'\n        x.stroke()\n      })\n\n      if(useFill){\n        dod.map(v=>{\n          x.beginPath()\n          v.map((q,j)=>{\n            X=q[0]+sx\n            Y=q[1]+sy\n            Z=q[2]+sz\n            R(Rl,0,Yw,0)\n            R(0,Pt,0,1)\n            if(Z>0)x.lineTo(...Q())\n          })\n          x.globalAlpha=.6*globalAlpha\n          x.fillStyle=fillStyle\n          x.fill()\n        })\n      }\n    }\n\n    Tetrahedron=ls=>{\n      let ret=[]\n      let a = []\n      let theta=1.2217304763960306\n      for(let i=3;i--;){\n        X=S(p=Math.PI*2/3*i)\n        Y=C(p)+.5\n        Z=0\n        R(0,-theta/2,0)\n        a=[...a, [X,Y,Z]]\n      }\n      ret=[...ret, a]\n      b=JSON.parse(JSON.stringify(a))\n      ax=ay=az=0\n      b.map(v=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R(0,theta,0)\n        v[0]=X\n        v[1]=Y\n        v[2]=Z\n      })\n      ret=[...ret, b]\n      ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax*1.5\n          q[1]-=ay*1.5\n          q[2]-=az*1.5\n        })\n      })\n\n      b=JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(0,Math.PI,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n      })\n      ret=[...ret, ...b]\n      \n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(0,.96,0)\n          R(0,0,t*5)\n          R(0,Math.PI,0)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n    \n    Octahedron=ls=>{\n      ret = []\n      a=[]\n      for(i=4;i--;){\n        X1=S(p=Math.PI*2/4*i+Math.PI/4)\n        Y1=C(p)\n        Z1=0\n        X2=S(p=Math.PI*2/4*(i+1)+Math.PI/4)\n        Y2=C(p)\n        Z2=0\n        X3=0\n        Y3=0\n        Z3=1\n        a=[\n          [X1,Y1,Z1],\n          [X2,Y2,Z2],\n          [X3,Y3,Z3]\n        ]\n        ret=[...ret, a]\n        a=[\n          [X1,Y1,-Z1],\n          [X2,Y2,-Z2],\n          [X3,Y3,-Z3]\n        ]\n        ret=[...ret, a]\n      }\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n    \n    Cube=ls=>{\n      let ret=[]\n      for(j=6;j--;ret=[...ret,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-ls:ls),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n    \n    Icosahedron=ls=>{\n      let a=[1,1],ret=[]\n      let b\n      for(i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]];\n      let phi=a[l]/a[l-1]\n      a=[[[-phi,-1,0],[phi,-1,0],[phi,1,0],[-phi,1,0]],[[0,-phi,-1],[0,phi,-1],[0,phi,1],[0,-phi,1]],[[-1,0,-phi],[-1,0,phi],[1,0,phi],[1,0,-phi]]]\n      let ico=[[[0,1],[1,0],[1,3]],[[0,1],[2,3],[1,0]],[[2,0],[2,3],[1,0]],[[0,1],[2,3],[0,2]],[[1,1],[2,3],[0,2]],[[1,1],[2,3],[2,0]],[[1,1],[1,2],[0,2]],[[0,1],[2,2],[0,2]],[[0,0],[1,0],[2,0]],[[2,0],[0,3],[0,0]],[[1,1],[1,2],[0,3]],[[1,1],[2,0],[0,3]],[[0,1],[1,3],[2,2]],[[1,3],[2,1],[2,2]],[[2,1],[0,3],[1,2]],[[2,1],[0,0],[1,3]],[[1,2],[2,2],[2,1]],[[2,2],[1,2],[0,2]],[[0,3],[2,1],[0,0]],[[1,3],[1,0],[0,0]]]\n      ico.map((v,i)=>{\n        b=[]\n        v.map(q=>{\n          t1=q[0],t2=q[1]\n          X=a[t1][t2][0],Y=a[t1][t2][1],Z=a[t1][t2][2]\n          b=[...b, [X,Y,Z]]\n        })\n        ret=[...ret, b]\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Dodecahedron=ls=>{\n      let ret=[]\n      let sd=5\n      let a=[], b=[]\n      mind=6e6\n      for(let i=sd;i--;){\n        X=S(p=Math.PI*2/sd*i)\n        Y=C(p)\n        Z=0\n        if(Y<mind)mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a=a.map(v=>{\n        X=v[0]\n        Y=v[1]-=mind\n        Z=v[2]\n        R(0,.5535735,0)\n        return [X,Y,Z]\n      })\n      \n      ret = [...ret, a]\n      b=JSON.parse(JSON.stringify(a)).map(v=>{\n        d=Math.hypot(v[0],v[1])\n        v[0]=S(p=Math.atan2(v[0],v[1])+Math.PI)*d\n        v[1]=C(p)*d\n        return v\n      })\n      ret = [...ret, b]\n      \n      ret.map(v=>{\n        v.map(q=>{\n          if(q[2]<mind)mind=q[2]\n        })\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]+=ang=1.538840639715\n        })\n      })\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(Math.PI,0,Math.PI)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n      \n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      b=JSON.parse(JSON.stringify(e)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(Math.PI/2,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n      \n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    /*\n    Dodecahedron=ls=>{\n      let ret=[]\n      let sd=5\n      let a=[], b=[]\n      mind=6e6\n      for(let i=sd;i--;){\n        X=S(p=Math.PI*2/sd*i)\n        Y=C(p)\n        Z=0\n        if(Y<mind)mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a=a.map(v=>{\n        X=v[0]\n        Y=v[1]-=mind\n        Z=v[2]\n        R(0,.5535735,0)\n        return [X,Y,Z]\n      })\n      \n      ret = [...ret, a]\n      b=JSON.parse(JSON.stringify(a)).map(v=>{\n        d=Math.hypot(v[0],v[1])\n        v[0]=S(p=Math.atan2(v[0],v[1])+Math.PI)*d\n        v[1]=C(p)*d\n        return v\n      })\n      ret = [...ret, b]\n      \n      ret.map(v=>{\n        v.map(q=>{\n          if(q[2]<mind)mind=q[2]\n        })\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]+=ang=1.538840639715\n        })\n      })\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(Math.PI,0,Math.PI)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n      \n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      b=JSON.parse(JSON.stringify(e)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(Math.PI/2,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n      \n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n    */\n\n    rw=20,cl=20,sp=70\n    B=Array(cl*rw).fill().map((v,i)=>{\n      X=((i%cl)-cl/2+.5)*sp\n      Y=0\n      Z=((i/cl|0)-rw/2+.5)*sp\n      return [X,Y,Z]\n    })\n    GG=()=>{\n      return 0-Math.min(0,S(t*8-1.8)*420)/(1+Math.hypot(X,Z)**3/20000000)\n    }\n    switch(Rn()*5|0){\n      case 0: chosenShape = Tetrahedron; break\n      case 1: chosenShape = Octahedron; break\n      case 2: chosenShape = Cube; break\n      case 3: chosenShape = Dodecahedron; break\n      case 4: chosenShape = Icosahedron; break\n    }\n  }\n\n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin=x.lineCap=\'round\'\n\n  oX=0, oY=0, oZ=800+S(t*2)*300\n  Rl=t/3,Pt=-1+S(t)/1.0,Yw=S(t/4)*3\n\n  B.map(v=>{\n    x.beginPath()\n    X=v[0],Z=v[2],Y=v[1]+GG(),R(Rl,0,Yw,0),R(0,Pt,0,1);if(Z>0)x.lineTo(...Q())\n    X=v[0]+sp,Z=v[2],Y=v[1]+GG(),R(Rl,0,Yw,0),R(0,Pt,0,1);if(Z>0)x.lineTo(...Q())\n    X=v[0]+sp,Z=v[2]+sp,Y=v[1]+GG()\n    a=H(X,Z)\n    R(Rl,0,Yw,0),R(0,Pt,0,1);if(Z>0)x.lineTo(...Q())\n    x.globalAlpha=1/(1+a**9/599999999999999999999999)\n    x.lineWidth=Math.min(200, 4e5/(Z**1.5))\n    \n    x.strokeStyle=\'#60f4\'\n    x.stroke()\n    x.lineWidth/=4\n    x.strokeStyle=\'#fffc\'\n    x.stroke()\n  })\n  B.map(v=>{\n    X=v[0]\n    Z=v[2]\n    Y=v[1]+GG()\n    a=H(X,Z)\n    x.globalAlpha=1/(1+a**9/599999999999999999999999)\n    R(Rl,0,Yw,0)\n    R(0,Pt,0,1)\n    l=Q()\n    s=Math.min(500,2e5/(Z**1.25))\n    x.fillStyle=\'#0fc3\'\n    x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n    s/=3\n    x.fillStyle=\'#fff\'\n    x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n  })\n\n  dodec=chosenShape(220+Math.abs(S(t*4))*50**2/20)\n  DrawSolid(dodec, -2, 260-Math.abs(S(t*4))*900, 0, `hsla(${t*20},99%,50%,.8)`, `hsla(${t*20},99%,50%,.1)`, \'#fff\', 1, .2)\n  x.globalAlpha=1\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'html, body{\n  margin: 0;\n  background: #000;\n  height: 100vh;\n  text-align: center;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  display: inline-block;\n}', '<canvas id=c>', 'the physical world', 145, 'whitehot robot', '2022-04-15 20:02:42', '', 60, '', 0, 0),
(600198, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\nrsz=window.onresize=()=>{\n  c.width=c.clientWidth, c.height=c.clientHeight\n}\nrsz()\nDraw=()=>{\n\n  if(!t){\n    Rn=Math.random\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    cl=64,rw=64,sp=2\n    cells=Array(cl*rw).fill().map((v,i)=>{\n      X=((i%cl)-cl/2+.5)*sp\n      Z=((i/cl|0)-rw/2+.5)*sp\n      Y=0\n      v1=1//Rn()<.1?1:0\n      v2=0//+(Rn()*3|0)\n      return [X,Y,Z,v1,v2]\n    })\n\n    fix=val=>{\n      while(val<0)val+=cl*rw\n      while(val>cl*rw-1)val-=cl*rw\n      return val\n    }\n\n    recurse=()=>{\n      let a=JSON.parse(JSON.stringify(cells))\n      cells.map((v,i)=>{\n        if(v[3]){\n          j=fix(i-cl)\n          if(cells[j][4]==(0+((v[4]+1)%3))){\n            a[j][4]=(Rn()*3|0)%3\n          } else {\n            a[j][4]=v[4]\n          }\n          j=fix(i+cl)\n          if(cells[j][4]==(0+((v[4]+1)%3))){\n            a[j][4]=(Rn()*3|0)%3\n          } else {\n            a[j][4]=v[4]\n          }\n          j=fix(i%cl?i-1:i+cl-1)\n          if(cells[j][4]!=(0+((v[4]+1)%3))){\n            a[j][4]=(Rn()*3|0)%3\n          } else {\n            a[j][4]=v[3]\n          }\n          j=fix((i+1)%cl?i+1:i-cl+1)\n          if(cells[j][4]!=(0+((v[4]+1)%3))){\n            a[j][4]=(Rn()*3|0)%3\n          } else {\n            a[j][4]=v[4]\n          }\n        }\n      })\n      cells=a\n    }\n    recurse()\n  }\n\n\n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n\n  oX=0, oY=0, oZ=100\n  Rl=0, Pt=Math.PI/2, Yw=0\n\n  //if(!((t*60|0)%0)){\n  //  recurse()\n  //}\n\n  p1=()=>0//S(Math.hypot(X,Z)/2.5/(6+S(t*2)*4)-t*6)*(25+S(t*2)*20)\n\n  cells.map(v=>{\n    x.beginPath()\n    X=v[0]\n    Z=v[2]\n    Y=v[1]+p1()\n    R(Rl,Pt,Yw,1)\n    if(Z>0)x.lineTo(...Q())\n    \n    X=v[0]+sp\n    Z=v[2]\n    Y=v[1]+p1()\n    R(Rl,Pt,Yw,1)\n    if(Z>0)x.lineTo(...Q())\n    \n    X=v[0]+sp\n    Z=v[2]+sp\n    Y=v[1]+p1()\n    R(Rl,Pt,Yw,1)\n    if(Z>0)x.lineTo(...Q())\n    \n    X=v[0]\n    Z=v[2]+sp\n    Y=v[1]+p1()\n    R(Rl,Pt,Yw,1)\n    if(Z>0)x.lineTo(...Q())\n    \n    //x.lineWidth=Math.min(200, 2e3/(Z**1.5))\n    //x.strokeStyle=\'#4f83\'\n    //x.stroke()\n    //x.closePath()\n    //x.lineWidth/=5\n    //x.strokeStyle=\'#fffc\'\n    //x.stroke()\n\n    if(v[3]){\n      switch(v[4]){\n        case 0: x.fillStyle=`hsla(${t*20},99%,50%,.2)`; break\n        case 1: x.fillStyle=`hsla(${t*20},99%,50%,.7)`; break\n        case 2: x.fillStyle=`hsla(${t*20},99%,50%,.c)`; break\n      }\n      x.fill()\n    }\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()\n', 'html, body{\n  margin: 0;\n  height: 100vh;\n  background: linear-gradient(45deg, #123, #000);\n}\n#c{\n  width: 100%;\n  height: 100%;\n}', '<canvas id=c>', '', 145, 'whitehot robot', '2022-04-16 21:49:57', '', 22, '', 0, 1),
(600199, '', '//---- do not edit the following code (you can indent as you wish)\nlet alphabet = \"123456789abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ\"\nvar fxhash = \"oo\" + Array(49).fill(0).map(_=>alphabet[(Math.random()*alphabet.length)|0]).join(\'\')\nlet b58dec = (str) => str.split(\'\').reduce((p,c,i) => p + alphabet.indexOf(c) * (Math.pow(alphabet.length, str.length-i-1)), 0)\nlet fxhashTrunc = fxhash.slice(2)\nlet regex = new RegExp(\".{\" + ((fxhashTrunc.length/4)|0) + \"}\", \'g\')\nlet hashes = fxhashTrunc.match(regex).map(h => b58dec(h))\nlet sfc32 = (a, b, c, d) => {\n  return () => {\n    a |= 0; b |= 0; c |= 0; d |= 0\n    var t = (a + b | 0) + d | 0\n    d = d + 1 | 0\n    a = b ^ b >>> 9\n    b = c + (c << 3) | 0\n    c = c << 21 | c >>> 11\n    c = c + t | 0\n    return (t >>> 0) / 4294967296\n  }\n}\nvar fxrand = sfc32(...hashes)\n//---- /do not edit the following code\n\n      c=document.querySelector(\'#c\')\n      x=c.getContext(\'2d\')\n      S=Math.sin\n      C=Math.cos\n      t=playing=0\n      window.onclick=()=>{if(!playing)mp3.play()}\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n      Draw=()=>{\n        if(!t){\n          R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n          Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n          mp3 = new Audio()\n          mp3.loop=true\n          mp3.onplaying=()=>{playing=true}\n          mp3.oncanplay=()=>{go=true;if(!playing)mp3.play()}\n          mp3.src=\'colossus.mp3\'\n          Rn=fxrand\n    for(cube=[],j=6;j--;cube=[...cube,e])for(e=[],i=4;i--;)e=[...e, [(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n                        G=50\n    B=Array(99).fill().map(v=>{\n      X=(Rn()-.5)*G\n      Y=(Rn()-.5)*G\n      Z=(Rn())*G\n      return [X,Y,Z]\n    })\n          bg=new Image()\n          go=false\n          bg.onload=()=>{\n            go=true\n          }\n          bg.src=\"https://srmcgann.github.io/assets/qgCWt.jpg\"\n        }\n\n        if(go){\n          x.globalAlpha=.2\n          x.drawImage(bg, 0, 0, c.width, c.height)\n          x.globalAlpha=1\n          x.fillStyle=\'#0001\'\n          x.fillRect(0, 0, c.width, c.height)\n        } else {\n          x.fillStyle=\'#0008\'\n          x.fillRect(0,0,c.width,c.height)\n        }\n\n        x.lineJoin=x.lineCap=\'round\'\n\n  oX=oY=0, oZ=8\n  Rl=S(t)/4, Pt=0, Yw=0\n  B.map((n, m)=>{\n    tx=n[0]\n    ty=n[1]\n    tz=n[2]\n    if(tz<0)n[2]+=G\n    n[2]-=1\n    cube.map((v, i)=>{\n      x.beginPath()\n      v.map(q=>{\n        X=q[0]\n        Y=q[1]\n        Z=q[2]\n        R(-t/2,m-S(t*2+m)*4,t*2,0)\n        X+=tx\n        Y+=ty\n        Z+=tz\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n      })\n      x.globalAlpha=1/(1+Z**9/1e14)*Math.min(1,((Z-3)/10)**3/4)\n      x.lineWidth=Math.min(200, 10000/(Z**1.5))\n      x.strokeStyle=\'#aaffcc06\'\n      x.stroke()\n      x.lineWidth/=16\n      x.strokeStyle=\'#0f88\'\n      x.stroke()\n      x.fillStyle=\'#40f2\'\n      x.fill()\n    })\n  })\n  x.globalAlpha=1\n\n        t+=1/60\n        requestAnimationFrame(Draw)\n      }\n      Draw()\n', '      body, html{\n        margin: 0;\n        width: 100%;\n        height: 100vh;\n        overflow: hidden;\n        background: #000;\n      }\n      #c{\n        position: absolute;\n        top: 50%;\n        left: 50%;\n        width: 100%;\n    