(600204, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\nrsz=window.onresize=()=>{\n  c.width=c.clientWidth,c.height=c.clientHeight\n}\n\nrsz()\n\nDraw=()=>{\n\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    Rn=Math.random\n\n    plotSquare=(sx,sy,sz,size)=>{\n      a=[]\n      for(i=4;i--;){\n        X=S(p=Math.PI*2/4*i+Math.PI/4)*size+sx\n        Y=sy\n        Z=C(p)*size+sz\n        a=[...a,[X,Y,Z]]\n      }\n      return a\n    }\n    squares=[]\n    rw=cl=23,sp=2**.5*2\n    for(j=cl*rw;--j;){\n      X=((j%cl)-cl/2+.5)*sp\n      Z=(((j/cl|0)%rw)-rw/2+.5)*sp\n      Y=0\n      squares=[...squares, plotSquare(X,Y,Z,1)]\n    }\n\n    ct=stx=sty=stz=0\n    do{\n      cl=12,rw=60,sp=40,vt=0,tj=-1,vtv=0,twt=Rn()*Math.PI*2\n      maxY=-6e6,minY=606\n      B=Array(cl*rw).fill().map((v,i)=>{  \n        j=i/cl|0\n        if(j!=tj)vt/=2.5,vt+=(.001+Rn()**16)*800,tj=j,vtv+=vt\n        X=((i%cl)-cl/2+.5)*sp*3\n        Y=vtv-(1+C(Math.PI*2/cl*(i-C(j/6)*cl/8)+Rn()/2-S(j/2)/1.5))**.4*300\n        if(Y>maxY)maxY=Y\n        if(Y<minY)minY=Y\n        Z=(j-rw/2+.5)*sp*3\n        R(0,0,-C(j/12+twt)*Math.min(1,j/20)/3-.2)\n        if(i==cl/2|0)stx=X,sty=Y,stz=Z\n        return [X,Y,Z]\n      })\n      ct++\n    }while(ct < 300 && (maxY < 2600 || maxY > 3000));\n    console.log(maxY)\n    B.map(v=>{\n      v[1]-=maxY/2-100\n    })\n    stx-=10\n    stz+=50\n    sty=minY-maxY/2-200\n    stz+=0\n    P=[]\n  }\n\n  x.fillStyle=\'#0004\'\n  x.fillRect(0,0,c.width,c.height)\n\n  oX=0, oY=200, oZ=4000+C(t/3)*400\n  Rl=0, Pt=-.5+C(t/2)/2, Yw=-S(t/4)+t/4+Math.PI/2\n\n  if(!((t*60|0)%2)){\n    for(m=1;m--;){\n      X=stx+(Rn()-.5)*cl/1.5*sp+30\n      Y=sty-500\n      Z=stz+Rn()*300\n      P=[...P, [X,Y,Z,0,0,0,0,0]]\n    } \n  }\n  if(0&&!((t*60|0)%10)){\n    for(m=1;m--;){\n      X=(Rn()-.5)*rw*sp*4\n      Y=-maxY-1200\n      Z=(Rn()-.5)*rw*sp*4\n      P=[...P, [X,Y,Z,0,0,0,0,1]]\n    }\n  }\n\n  tx=ty=tz=0,mind=0\n  squares.map((v,i)=>{\n    x.beginPath()\n    v.map(q=>{\n      sx=X=q[0]*1500/2\n      Y=q[1]*1500+maxY/2\n      sz=Z=q[2]*1500/2\n      R(0,0,Yw,0)\n      R(Rl,Pt,0,1)\n      if(Z>0){\n        x.lineTo(...Q())\n        X=(v[0][0]+v[1][0]+v[2][0]+v[3][0])/4\n        Y=(v[0][1]+v[1][1]+v[2][1]+v[3][1])/4\n        Z=(v[0][2]+v[1][2]+v[2][2]+v[3][2])/4\n        R(0,0,Yw,0)\n        R(Rl,Pt,0,1)\n        tx=X\n        ty=Y\n        tz=Z\n      }\n    })\n    x.closePath()\n    \n    x.globalAlpha=Math.max(0, 1/(1+(H(sx,sz)/55500*100)**4/99999))\n    if(H(tx,tz)>mind)mind=H(tx,tz)\n    x.fillStyle=x.strokeStyle=\'#00ccff08\'\n    x.lineWidth=Math.min(500, 150000/(1+tz**1))\n    x.stroke()\n    x.lineWidth/=4\n    x.strokeStyle=\'#0cf1\'\n    x.stroke()\n    x.fill()\n  })\n  x.globalAlpha=1\n  B.map(v=>{\n    X=v[0]\n    Y=v[1]-300\n    Z=v[2]\n    R(0,0,Yw,0)\n    R(Rl,Pt,0,1)\n    if(Z>0){\n      s=Math.min(200, 6000000/(Z**1.5))\n      l=Q()\n      x.fillStyle=\'#6600ff10\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      s/=5\n      x.fillStyle=\'#8ff6\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n    }\n  })\n\n  P=P.filter(v=>v[1]<maxY*2&&v[6]<300)\n\n  P.map(v=>{\n    v[3]/=1.01\n    v[4]/=1.02\n    v[5]/=1.02\n    X=v[0]+=v[3]+=(Rn()-.5)*2\n    Y=v[1]+=v[4]+=10\n    Z=v[2]+=v[5]+=v[7]?0:.3\n    v[6]+=.2\n\n    B.map(q=>{\n      tx=q[0]\n      ty=q[1]\n      tz=q[2]\n      if(d=H(tx-X,ty-Y,tz-Z)<sp*8.1){\n        v[7]=0\n        vx=tx-X\n        vy=ty-Y\n        vz=tz-Z\n        vx/=(d2=H(vx,vy,vz))\n        vy/=d2\n        vz/=d2\n        v[0]=tx-vx*sp*8\n        v[1]=ty-vy*sp*8\n        v[2]=tz-vz*sp*8 \n        v[3]/=1.01\n        v[4]/=1.05\n        v[5]/=1.02\n        v[3]-=vx*2\n        v[4]-=vy*4\n        v[5]-=vz/20-.5\n      }\n    })\n\n    R(0,0,Yw,0)\n    R(Rl,Pt,0,1)\n    if(Z>0){\n      x.globalAlpha=Math.max(0, 1-Math.max(Y/maxY/2,0))\n      l=Q()\n      x.fillStyle=\'#28e1\'\n      s=Math.min(200, 18000000/(1+v[6]/99)/(Z**1.5))\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      s/=2.5\n      x.fillStyle=\'#0ff2\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      s/=3\n      x.fillStyle=\'#afff\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n    }\n  })\n  x.globalAlpha=1\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body, html{\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123);\n  height: 100vh;\n}\n#c{\n  width: 100%;\n  height: 100%;\n}', '<canvas id=c>', 'waterfall', 145, 'whitehot robot', '2022-04-25 21:21:54', '', 28, '', 0, 0),
(600205, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\nrsz=window.onresize=()=>{\n  c.width=c.clientWidth,c.height=c.clientHeight\n}\n\nrsz()\n\nDraw=()=>{\n\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    Rn=Math.random\n  }\n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n  for(i=20;i--;){\n    x.fillStyle=\'#fff\'\n    x.fillRect((c.width/20*i)/(20-i),0,(c.width/60)/(5-i/4),c.height)\n  }\n  x.globalAlpha=1\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body, html{\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123);\n  height: 100vh;\n}\n#c{\n  width: 100%;\n  height: 100%;\n}', '<canvas id=c>', '', 145, 'whitehot robot', '2022-04-27 01:53:47', '[600204]', 11, '', 0, 1),
(600206, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=playing=0\nwindow.onclick=()=>{if(!playing)mp3.play()}\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\nDraw=()=>{\n  \n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    mp3 = new Audio()\n    mp3.loop=true\n    go=playing=false\n    mp3.onplaying=()=>{playing=true}\n    mp3.oncanplay=()=>{go=true;if(!playing)mp3.play()}\n    mp3.src=\'https://audiocloud.rotoblaster.com/audio/9f7b12499f8a4d5f97e5f7cda8639e3c.MP3\'\n    Rn=Math.random\n    bg=new Image()\n    bgloaded=false\n    bg.onload=()=>{\n      bgloaded=true\n    }\n    bg.src=\'https://srmcgann.github.io/assets/3HMCW.jpg\'\n    hist = [], histlen = 103*70\n    play = () => {\n    \n      if(bgloaded){\n        x.globalAlpha=.1\n        x.drawImage(bg,0,0,c.width,c.height)\n        x.globalAlpha=1\n        x.fillStyle=\'#0002\'\n        x.fillRect(0, 0, c.width, c.height)\n      }else{\n        x.fillStyle=\'#0006\'\n        x.fillRect(0, 0, c.width, c.height)\n      }\n      \n      let newlines=0\n      if(hist.length > histlen){\n        newlines=hist.length-histlen\n        x.lineJoin=x.lineCap=\'butt\'\n        x.globalAlpha=1\n        x.globalAlpha=(1.00-((1.00/(histlen-0)*i)**.1))**1\n        hist.filter((v, i)=>i<=histlen+newlines-300).map((v, i) => {\n          switch(v[0]){\n            case \'lineWidth\': x.lineWidth = v[1]; break\n            case \'strokeStyle\': x.strokeStyle = v[1]; break\n            case \'fillStyle\': x.fillStyle = v[1]; break\n            case \'globalAlpha\': x.globalAlpha = x.globalAlpha=(1.0-((1.0/(histlen-0)*i)**.1))*v[1]; break\n            case \'lineJoin\': x.lineJoin = v[1]; break\n            case \'lineCap\': x.lineCap = v[1]; break\n            default :\n              x[v[0]](...v[1])\n            break\n          }\n        })\n      }\n      x.globalAlpha=1\n      hist = hist.filter((v, i) => i > newlines)\n    }\n    x_ = {\n      fillStyle: (col) => {\n        hist=[...hist, [\'fillStyle\', [col]]]\n      },\n      strokeStyle: (col) => {\n        hist=[...hist, [\'strokeStyle\', [col]]]\n      },\n      lineTo: (X, Y) => {\n        hist=[...hist, [\'lineTo\', [X, Y]]]\n      },\n      fillRect: (X, Y, W, H) => {\n        hist=[...hist, [\'fillRect\', [X, Y, W, H]]]\n      },\n      beginPath: () => {\n        hist=[...hist, [\'beginPath\', []]]\n      },\n      closePath: () => {\n        hist=[...hist, [\'closePath\', []]]\n      },\n      arc: (X, Y, RAD, START, STOP) => {\n        hist=[...hist, [\'arc\', [X, Y, RAD, START, STOP]]]\n      },\n      fill: () => {\n        hist=[...hist, [\'fill\', []]]\n      },\n      globalAlpha: (alpha) => {\n        hist=[...hist, [\'globalAlpha\', [alpha]]]\n      },\n      lineWidth: (width) => {\n        hist=[...hist, [\'lineWidth\', [width]]]\n      },\n      lineJoin: (mode) => {\n        hist=[...hist, [\'lineJoin\', [mode]]]\n      },\n      lineCap: (mode) => {\n        hist=[...hist, [\'lineCap\', [mode]]]\n      },\n      stroke: () => {\n        hist=[...hist, [\'stroke\', []]]\n      }\n    }\n    \n    for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(1+j)%3]*l,a[(2+j)%3]*l]]\n    tRl=tPt=tYw=0\n  }\n  \n  oX=oY=0, oZ=2.75+S(t)*1.25\n  Rl=0,Pt=0,Yw=0\n\n  tRl+=.0015/2\n  tPt+=-S(t/3)*.05/2\n  tYw+=S(t/1.5)*.075/2\n  \n  for(n=2;n--;){\n    CB.map((v,i)=>{\n      if(!(i%4)) x_.beginPath()\n      X=v[0]*(l=(n+(1+S(t/4))*12)/2%1)\n      Y=v[1]*l\n      Z=v[2]*l\n      R(tRl,tPt,tYw)\n      X+=Math.min(1.25, Math.max(-1.25, S(t/1.5)*5))\n      R(Rl,Pt,Yw,1)\n      if(Z>0) x_.lineTo(...Q())\n      if(i%4==3){\n        x_.globalAlpha((1-l)**2.2)\n        x_.strokeStyle(`hsla(${-190+l*10-(t%10)**4/2},99%,${150-(l**.3*100)}%,.45)`)\n        x_.fillStyle(`hsla(${-190+l*10-(t%10)**5/10},99%,${100-(l**.3*50)}%,.05)`)\n        x_.lineWidth(Math.min(200, 100/(Z**2)))\n        x_.stroke()\n        x_.strokeStyle(\'#fffd\')\n        x_.globalAlpha((1-l)**4*8)\n        x_.lineWidth(Math.min(200, 200/(Z**2)/20))\n        x_.stroke()\n        x_.fill()\n      }\n    })\n  }\n  \n  play()\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()\n', 'body, html{\n  margin: 0;\n  width: 100%;\n  height: 100vh;\n  overflow: hidden;\n  background: #000;\n}\n#c{\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 100%;\n  height: 100%;\n  background: url(3HMCW.jpg);\n  background-position: center center;\n  background-size: fill;\n  transform: translate(-50%, -50%);\n}\n', '<canvas id=c>', 'history', 145, 'whitehot robot', '2022-04-27 17:35:32', '[600205,600204]', 25, '', 0, 0),
