(600212, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\nDraw=()=>{\n\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    vidWidth=vidHeight=ar=0\n    Rn=Math.random\n    go=false\n    vid=document.createElement(\'video\')\n    vid.loop=true\n    vid.muted=true\n    vid.style.display=\'none\'\n    vid.style.position=\'absolute\'\n    document.body.appendChild(vid)\n    vid.oncanplay=()=>{\n      setTimeout(()=>vid.play(),0)\n      vidWidth=vid.videoWidth\n      vidHeight=vid.videoHeight\n      ar=vidHeight/c.height\n      go=true\n    }\n    vid.src=\'/video/1BxV4f.mp4\'\n    G=500\n    B=Array(2e3).fill().map(v=>{\n      X=(Rn()-.5)*G\n      Y=(Rn()-.5)*G\n      Z=Rn()*G\n      return [X,Y,Z]\n    })\n  }\n  if(go){\n    x.globalAlpha=.25\n    x.fillStyle=\'#0041\'\n    //x.fillRect(0,0,c.width,c.height)\n    s=vidWidth/ar\n    for(m=2;m--;){\n      tx=(m-.5)*s\n      x.drawImage(vid,c.width/2-s/2+tx,0,s,vidHeight/ar)\n    }\n    x.globalAlpha=1\n  }else{\n    x.fillStyle=\'#0008\'\n    x.fillRect(0,0,c.width,c.height)\n  }\n\n  oX=oY=0, oZ=0\n  Rl=S(t/8)*4,Pt=0,Yw=0\n\n  B.map(v=>{\n    X=v[0]\n    Y=v[1]\n    Z=v[2]-=S(t/3)*4\n    if(Z<0)v[2]=G\n    if(Z>G)v[2]=0\n    R(Rl,Pt,Yw,1)\n    s=Math.min(500,5000/(Z**1.25))\n    l=Q()\n    x.globalAlpha=1/(1+(Z)**6/1e15)\n    x.fillStyle=\'#fff2\'\n    x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n    s/=5\n    x.fillStyle=\'#fff\'\n    x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n  })\n  x.globalAlpha=1\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nwindow.onclick=()=>{Draw()}', '      body, html{\n        margin: 0;\n        width: 100%;\n        height: 100vh;\n        overflow: hidden;\n        background: #000;\n        font-family: courier;\n        color: #fff;\n        font-size: 24px;\n        text-align: center;\n      }\n      #startMsg{\n        position: absolute;\n        left: 50%;\n        top: 50%;\n        transform: translate(-50%, -50%);\n      }\n      #c{\n        position: absolute;\n        top: 50%;\n        left: 50%;\n        width: 100%;\n        height: 100%;\n        background: url(3HMCW.jpg);\n        background-position: center center;\n        background-size: fill;\n        transform: translate(-50%, -50%);\n        z-index: 100;\n      }', '<canvas id=\"c\"></canvas>\n<div id=\"startMsg\">click/touch</div>', 'med core', 145, 'whitehot robot', '2022-04-29 19:35:37', '', 25, '', 0, 1);
