(600213, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n\n  if(!t){\n    mp3=new Audio()\n    mp3.oncanplay=()=>{\n      mp3.play()\n    }\n    mp3.loop=true\n    mp3.src=\'https://play.rotoblaster.com/whr//tracks/acoustic.mp3\'\n    mp3.onplaying=()=>{\n      playing=true\n    }\n    window.onclick=()=>{\n      if(!playing)mp3.play(),playing=true\n    }\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    vid1 = document.createElement(\'video\')\n    vid1.loop = true\n    vid1.muted = true\n    canplay1=false\n    vid1.addEventListener(\'canplay\',()=>{\n      vidWidth=vid1.videoWidth\n      vidHeight=vid1.videoHeight\n      ar=vidHeight/c.height\n      go=true\n      canplay1=true\n      vid1.play()\n    })\n    vid1.src = \'https://srmcgann.github.io/assets/1D4hwI.mp4\'\n    G=500\n    Rn=Math.random\n    B=Array(3e3).fill().map(v=>{\n      X=(Rn()-.5)*G\n      Y=(Rn()-.5)*G\n      Z=Rn()*G\n      return [X,Y,Z]\n    })\n    playing=false\n  }\n  \n  if(canplay1){\n\n    x.globalAlpha=1\n    x.fillStyle=\'#0041\'\n    s=vidWidth/ar\n    for(m=2;m--;){\n      tx=(m-.5)*s\n      x.drawImage(vid1,c.width/2-s/2+tx,0,s,vidHeight/ar)\n    }\n    x.globalAlpha=1\n  oX=oY=0, oZ=0\n  Rl=S(t/8)*4,Pt=0,Yw=0\n\n  B.map(v=>{\n    X=v[0]\n    Y=v[1]\n    Z=v[2]-=S(t/3)*4\n    if(Z<0)v[2]=G\n    if(Z>G)v[2]=0\n    R(Rl,Pt,Yw,1)\n    s=Math.min(500,5000/(Z**1.25))\n    l=Q()\n    x.globalAlpha=1/(1+(Z)**6/5e15)\n    x.fillStyle=\'#fff2\'\n    x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n    s/=5\n    x.fillStyle=\'#fff\'\n    x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n  })\n  }else{\n    x.fillStyle=\'#0008\',x.fillRect(0,0,c.width,c.height)\n  }\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', '      body, html{\n        margin: 0;\n        width: 100%;\n        height: 100vh;\n        overflow: hidden;\n        background: #000;\n        font-family: courier;\n        color: #fff;\n        font-size: 24px;\n        text-align: center;\n      }\n      #startMsg{\n        position: absolute;\n        left: 50%;\n        top: 50%;\n        transform: translate(-50%, -50%);\n      }\n      #c{\n        position: absolute;\n        top: 50%;\n        left: 50%;\n        width: 100%;\n        height: 100%;\n        background: url(3HMCW.jpg);\n        background-position: center center;\n        background-size: fill;\n        transform: translate(-50%, -50%);\n        z-index: 100;\n      }\n', '<canvas id=c>', 'med core', 145, 'whitehot robot', '2022-04-29 21:31:14', '[600143,600142,600141,600140,600139,600138,600137,600136,600135]', 38, '', 0, 0),
(600214, 'https://youtu.be/vzoJ_FnIXwE', '', 'body,html{\n  background: #000;\n  margin: 0;\n  text-align: center;\n}', '<iframe style=\"transform:scale(.75);width:640px;height:290px;border:none;vertical-align:top;\" src=\"https://audioplayer.rotoblaster.com/https://play.rotoblaster.com/whr//tracks/ethnicities.mp3\"></iframe>\n', 'ethnicities - whitehot robot', 145, 'whitehot robot', '2022-05-02 18:53:42', '[600207]', 30, 'http://img.youtube.com/vi/vzoJ_FnIXwE/0.jpg', 0, 0),
(600215, '', '//---- do not edit the following code (you can indent as you wish)\nlet alphabet = \"123456789abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ\"\nvar fxhash = \"oo\" + Array(49).fill(0).map(_=>alphabet[(Math.random()*alphabet.length)|0]).join(\'\')\nlet b58dec = (str) => str.split(\'\').reduce((p,c,i) => p + alphabet.indexOf(c) * (Math.pow(alphabet.length, str.length-i-1)), 0)\nlet fxhashTrunc = fxhash.slice(2)\nlet regex = new RegExp(\".{\" + ((fxhashTrunc.length/4)|0) + \"}\", \'g\')\nlet hashes = fxhashTrunc.match(regex).map(h => b58dec(h))\nlet sfc32 = (a, b, c, d) => {\n  return () => {\n    a |= 0; b |= 0; c |= 0; d |= 0\n    var t = (a + b | 0) + d | 0\n    d = d + 1 | 0\n    a = b ^ b >>> 9\n    b = c + (c << 3) | 0\n    c = c << 21 | c >>> 11\n    c = c + t | 0\n    return (t >>> 0) / 4294967296\n  }\n}\nvar fxrand = sfc32(...hashes)\n//---- /do not edit the following code\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=playing=0\nmp3=new Audio()\nmp3.loop\nmp3.oncanplay=()=>{\n  if(!playing)mp3.play()\n}\nmp3.onplaying=()=>{\n  playing=true\n}\nmp3.src=\'https://audiocloud.rotoblaster.com/audio/734b86de412cfbbd26354c73ae25fa4c.MP3\'\nwindow.onclick=()=>{if(!playing)mp3.play()}\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    Rn=fxrand\n    B=[]\n    x.lineCap=\'round\'\n    x.linejoin=\'round\'\n    B=[]\n    w=c.width\n    cl=99,sc=w/cl\n    rw=cl*.5625|0\n    iBc=3,iBs=12,iBv=.5\n    iPc=5,iPs=4,iPv=.5\n    bnc=12\n    for(i=iBc+1;--i;){\n      dn=0\n      while(!dn){\n        dn=1\n        X=Rn()*cl|0\n        Y=Rn()*rw|0\n        if(X<iBs*1.5||X>cl-iBs*1.5||Y>rw-iBs*1.5||Y<iBs*1.5)dn=0\n        B.map(v=>{if(Math.hypot(v[0]-X,v[1]-Y)<iBs)dn=0})\n      }\n      B=[...B,[X,Y,S(p=Rn()*Math.PI*2)*iBv,C(p)*iBv]]\n    }\n    P=[]\n    for(i=iPc+1;--i;){\n      dn=0\n      while(!dn){\n        dn=1\n        X=Rn()*cl|0\n        Y=Rn()*rw|0\n        if(X<iPs*2||X>cl-iPs*2||Y>rw-iPs*2||Y<iPs*2)dn=0\n        P.map(v=>{if(Math.hypot(v[0]-X,v[1]-Y)<iBs)dn=0})\n        B.map(v=>{if(Math.hypot(v[0]-X,v[1]-Y)<(iBs+iPs)/2)dn=0})\n      }\n      P=[...P,[X,Y,S(p=Rn()*Math.PI*2)*iPv,C(p)*iPv]]\n    }\n    h=800\n  }\n\n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n\n  g=x.createLinearGradient(0,0,w,1080)\n  g.addColorStop(0,\'#0006\')\n  g.addColorStop(1,\'#0086\')\n  x.fillStyle=g,x.fillRect(0,0,w,1080)\n\n  Q=q=>{x.fillRect((X-q/2)*sc,(Y-q/2)*sc,q*sc,q*sc)}\n  Q2=(v,s)=>{\n    l=iPv-Math.hypot(v[2],v[3])\n    v[2]*=1+l/50\n    v[3]*=1+l/50\n    X=v[0]\n    Y=v[1]\n    if(X<s/2||X>cl-s/2)v[2]*=-1\n    if(Y<s/2||Y>rw-s/2)v[3]*=-1\n    v[0]+=v[2]\n    v[1]+=v[3]\n  }\n  \n  B.map((v,j)=>{\n    Q2(v,iBs)\n    x.fillStyle=\'#26f8\'\n\n    X=v[0]\n    Y=v[1]\n    P.map((q,k)=>{\n      if(Math.hypot(a=q[0]-X,b=q[1]-Y)<(d=(iBs+iPs)/2)){\n        v[0]=q[0]-S(p=Math.atan2(a,b))*d\n        v[1]=q[1]-C(p)*d\n        v[2]-=S(p)/bnc\n        v[3]-=C(p)/bnc\n        q[0]=v[0]+S(p=Math.atan2(a,b))*d\n        q[1]=v[1]+C(p)*d\n        q[2]+=S(p)/bnc\n        q[3]+=C(p)/bnc\n      }\n    })\n    B.map((q,k)=>{\n      if(j!=k&&Math.hypot(a=q[0]-X,b=q[1]-Y)<(d=iBs)){\n        v[0]=q[0]-S(p=Math.atan2(a,b))*d\n        v[1]=q[1]-C(p)*d\n        v[2]-=S(p)/bnc\n        v[3]-=C(p)/bnc\n        q[0]=v[0]+S(p=Math.atan2(a,b))*d\n        q[1]=v[1]+C(p)*d\n        q[2]+=S(p)/bnc\n        q[3]+=C(p)/bnc\n      }\n    })\n    \n    for(i=iBs*4+1;i--;){\n      X=v[0]+S(p=Math.PI/iBs/2*i)*iBs/2\n      Y=v[1]+C(p)*iBs/2\n      Q(1)\n    }\n  })\n\n  x.strokeStyle=\'#fff2\'\n  P.map((v,j)=>{\n    Q2(v,iPs)\n    X=v[0]\n    Y=v[1]\n    P.map((q,k)=>{\n      if(k!=j){\n        d=Math.hypot(a=q[0]-X,b=q[1]-Y)\n        if(k<j){\n          x.beginPath()\n          for(k=0;k<(d*2+1)|0;k++){\n            aX=X+a/d/2*k\n            aY=Y+b/d/2*k\n            E=1\n            B.map(n=>{\n              E=50+Math.hypot(e=aX-n[0],f=aY-n[1])**2\n              p=Math.atan2(e,f)\n              aX+=S(p)*400/E\n              aY+=C(p)*400/E\n            })\n            \n            x.lineTo(aX*sc,aY*sc)\n          }\n          x.lineWidth=sc\n          x.stroke()\n        }\n        if(d<(d=iPs)){\n          v[0]=q[0]-S(p=Math.atan2(a,b))*d\n          v[1]=q[1]-C(p)*d\n          v[2]-=S(p)/bnc\n          v[3]-=C(p)/bnc\n          q[0]=v[0]+S(p=Math.atan2(a,b))*d\n          q[1]=v[1]+C(p)*d\n          q[2]+=S(p)/bnc\n          q[3]+=C(p)/bnc\n        }\n      }\n    })\n\n    l=P.length\n    ar=Array(cl*rw*2).fill(0)\n    x.fillStyle=\'#fff8\'\n\n    x.fillStyle=\'#2f68\'\n    for(i=iPs*4+1;i--;){\n      X=v[0]+S(p=Math.PI/iPs/2*i)*iPs/2\n      Y=v[1]+C(p)*iPs/2\n      Q(1)\n    }\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()\n', 'body, html{\n  margin: 0;\n  width: 100%;\n  height: 100vh;\n  overflow: hidden;\n  background: #000;\n}\n#c{\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 100%;\n  height: 100%;\n  background: url(VoZVF.jpg);\n  background-position: center center;\n  backgroun-size: fill;\n  transform: translate(-50%, -50%);\n}\n', '<canvas id=\"c\" width=\"1920\" height=\"1079\" style=\"width: 100vw;\"></canvas>', 'the mission', 145, 'whitehot robot', '2022-05-02 21:04:16', '', 39, '', 0, 0),
