(600218, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nt=mx=my=0\nS=Math.sin\nC=Math.cos\nrsz=window.onresize=()=>{\n  c.width=c.clientWidth,c.height=c.clientHeight\n}\nrsz()\nDraw=()=>{\n  if(!t){\n    window.onmousemove=e=>{\n      mx=e.pageX/c.clientWidth*c.width\n      my=e.pageY/c.clientHeight*c.height\n    }\n    scale = 64\n    columns = 16\n    rows = 16\n    tiles=Array(columns * rows).fill().map((v, i)=>{\n      X = ((i%columns) - columns / 2 + .5) * scale\n      Y = (((i/columns|0)%rows) - rows / 2 + .5) * scale\n      return [X, Y]\n    })\n  }\n\n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n\n  tiles.map(v=>{\n    X=v[0]\n    Y=v[1]\n    x.strokeStyle=\'#fff\'\n    x.lineWidth=5\n    s=scale\n    tx=c.width/2 + X-s/2\n    ty=c.height/2 + Y-s/2\n    x.strokeRect(tx, ty, s, s)\n    if(mx > tx && mx < tx + s && my > ty && my < ty+s){\n      x.fillStyle=\'#4f8\'\n      x.fillRect(tx, ty, s, s)\n    }\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'html, body{\n  margin: 0;\n  height: 100vh;\n  background: linear-gradient(45deg, #000, #123);\n}\n#c{\n  width: 100%;\n  height: 100%;\n}', '<canvas id=c>', 'grid formula', 145, 'whitehot robot', '2022-05-03 18:58:28', '', 51, '', 0, 0),
