(600220, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\nrsz=window.onresize=()=>{\n  c.width=c.clientWidth*4\n  c.height=c.clientHeight*4\n}\nrsz()\nDraw=()=>{\n  if(!t){\n    bg=new Image()\n    bg.src=\'https://srmcgann.github.io/assets/2h9kBr.jpg\'\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    Rn=Math.random\n    G=2000\n    B=[]\n    tgt=150\n    rd=1.5\n    rd2=1\n    for(i=tgt;i--;){\n      ct=0\n      do{\n        ols=ls=50\n        tx=(Rn()-.5)*G\n        ty=(Rn()-.5)*G/(16/9)\n        good = true,trn=Rn()*9\n        for(a=[],s=m=4+Rn()*8|0;m--;){\n          ls+=(Rn()-.5)*1000\n          ls/=4\n          ls=Math.min(200,Math.max(50, ls))\n          X=S(p=Math.PI*2/s*m+trn)*ls\n          Y=C(p)*ls\n          Z=0\n          X2=S(p)*ls/rd\n          Y2=C(p)*ls/rd\n          Z2=0\n          p=Math.atan2(X2-X,Y2-Y)\n          d=Math.hypot(X2-X,Y2-Y)\n          vx=(X2-X)/d*16\n          vy=(Y2-Y)/d*16\n          X3=X2-vx\n          Y3=Y2-vy\n          Z3=0\n          a=[...a, [X+tx,Y+ty,Z,X2+tx,Y2+ty,Z2,X3+tx,Y3+ty,Z3]]\n        }\n        ntx=nty=0\n          a.map(v=>{\n            ntx+=v[0]\n            nty+=v[1]\n          })\n          ntx/=a.length\n          nty/=a.length\n        B.map(q=>{\n          btx=bty=0\n          q[0].map(n=>{\n            btx+=n[0]\n            bty+=n[1]\n          })\n          btx/=q[0].length\n          bty/=q[0].length\n          d=Math.hypot(ntx-btx,nty-bty)\n          if(d<ols*1.5) good=false\n        })\n        B.map((v,i)=>{\n            if(good){\n              v[0].map((q,j)=>{\n                X1=q[0]\n                Y1=q[1]\n                X2=v[0][(j+1)%v[0].length][0]\n                Y2=v[0][(j+1)%v[0].length][1]\n                a.map((o,p)=>{\n                  X3=o[0]\n                  Y3=o[1]\n                  X4=a[(p+1)%a.length][0]\n                  Y4=a[(p+1)%a.length][1]\n                  if(good) good = !I(X1,Y1,X2,Y2,X3,Y3,X4,Y4)\n                })\n              })\n            }\n        })\n        ct++\n      }while(!good && ct<500);\n      if(good) B=[...B, [a,Rn()-.5,Rn()-.5,0,tx,ty,0]]\n    }\n    iPc=6, iPv=100, iPs=6e6\n    P=Array(iPc).fill().map(v=>{\n      X=(Rn()-.5)*G\n      Y=(Rn()-.5)*G\n      Z=0\n      return [X,Y,Z,(Rn()-.5)*iPv,(Rn()-.5)*iPv,0]\n    })\n  }\n  x.globalAlpha=.4\n  x.drawImage(bg,0,0,c.width,c.height)\n  x.globalAlpha=1\n  x.fillStyle=\'#0003\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin=x.lineCap=\'round\'\n  oX=oY=0, oZ=2000+S(t)*1e3\n  Rl=0, Pt=C(t)/2, Yw=S(t)/2\n  Bv=.01\n  bnc=.01\n  P.map(v=>{\n    v[3]-=v[0]/3999\n    v[4]-=v[1]/3999\n    v[5]-=v[2]/3999\n    X=v[0]+=v[3]\n    Y=v[1]+=v[4]\n    Z=v[2]+=v[5]\n    R(Rl,Pt,Yw,1)\n    x.beginPath()\n    if(Z>0){\n      x.arc(...Q(),Math.min(1e3,iPs/(Z**1.5)),0,7)\n      x.fillStyle=\'#4f86\'\n      x.fill()\n      x.beginPath()\n      x.arc(...Q(),Math.min(1e3, iPs/(Z**1.5))/1.5,0,7)\n      x.fillStyle=\'#afca\'\n      x.fill()\n    }\n  })\n  B.map((v,i)=>{\n    v[1]-=v[4]/1600\n    v[2]-=v[5]/1600\n    d=Math.hypot(v[1],v[2],v[3])\n    v[1]/=d\n    v[2]/=d\n    v[3]/=d\n    d2=(d-(d-Bv)/40)\n    v[1]*=d2\n    v[2]*=d2\n    v[3]*=d2\n      B.map((q,j)=>{\n        if(j!=i){\n          if(d=Math.hypot(v[4]-q[4],v[5]-q[5])<ls*3.05){\n            p=Math.atan2(v[4]-q[4],v[5]-q[5])\n            v[1]+=S(p)/(l=((2+d)**3)/bnc)*15000\n            v[2]+=C(p)/l*15000\n            q[1]-=S(p)/l*15000\n            q[2]-=C(p)/l*15000\n            v[1]/=1.01\n            v[2]/=1.01\n            q[1]/=1.01\n            q[2]/=1.01\n          }\n        }\n      })\n      P.map(q=>{\n        if(d=Math.hypot(v[4]-q[0],v[5]-q[1])<ls*7.5){\n          p=Math.atan2(v[4]-q[0],v[5]-q[1])\n          v[1]+=S(p)/(l=((.5+d)**3*1)/bnc)*5000\n          v[2]+=C(p)/l*5000\n        }\n      })\n      v[4]+=v[1]\n      v[5]+=v[2]\n      v[6]+=v[3]\n    for(m=3;m--;){\n      l=m*3\n      if(m)x.beginPath()\n      v[0].map(q=>{\n        X=q[0+l]+=v[1]\n        Y=q[1+l]+=v[2]\n        Z=q[2+l]+=v[3]\n        if(m){\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n        }\n      })\n      if(m){\n        x.closePath()\n        x.lineWidth = Math.min(500, 5e5 / (Z**1.4))\n        x.strokeStyle = \'#0f83\'\n        x.stroke()\n        x.lineWidth/=6\n        x.strokeStyle = \'#fff8\'\n        x.stroke()\n        if(m>1){\n          x.fillStyle=\'#40f5\'\n          x.fill()\n        }\n      }\n    }\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123);\n  height: 100vh;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n}\niframe{\nposition: absolute;\n  width: 100%;\n  height: 100%;\n}', '<canvas id=c></canvas>\n', 'polygon packing', 145, 'whitehot robot', '2022-05-05 16:15:50', '', 162, '', 0, 0),
