2,X3,Y3,X4,Y4)) good = false\n                        })\n                      }\n                    })\n                  }\n                })\n              }\n              ct++\n            }while(!good && ct<4);\n            if(good) {\n              P=[...P, a]\n            \n            }\n          }\n        }\n\n        x.fillStyle=\'#000c\'\n        x.fillRect(0,0,c.width,c.height)\n        //P.filter((v,i)=>i==P.length-1).map(v=>{\n        P.map(v=>{\n          x.beginPath()\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0) x.lineTo(...Q())\n          })\n          //x.closePath()\n          //x.lineWidth = 1\n          //x.strokeStyle=\'#88ffdd30\'\n          x.fillStyle=\'#99ffdd20\'\n          //x.stroke()\n          x.fill()\n        })\n        \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123);\n  height: 100vh;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n}\niframe{\nposition: absolute;\n  width: 100%;\n  height: 100%;\n}', '<canvas id=c></canvas>\n', 'polygon packing 2.0', 145, 'whitehot robot', '2022-05-07 21:35:44', '[600220]', 54, '', 0, 0),
(600224, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\nrsz=window.onresize=()=>{\n  c.width=1920*4\n  c.height=1080*4\n}\nrsz()\nDraw=()=>{\n  if(!t){\n    sd=16\n    rd1=1.1\n    e=9\n    n=(sd/2|0)%2?1:0\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*1200,c.height/2+Y/Z*1200]\n    RC=(tx,ty,s,j,k,q)=>{\n      rd=2.5/(1+k/300)\n      if(s<0.1)return\n      for(let m=0;m<e;m++){\n        x.beginPath()\n        for(let i=sd;i--;){\n          ls=i%2?s:s/2.5\n          ls-=ls/(e-1)*m\n          X=S(p=Math.PI*2/sd*i+Math.PI*2/sd*j*k*n)*ls\n          Y=C(p)*ls\n          Z=0\n          X+=tx\n          Y+=ty\n          R(Rl,Pt,Yw,1)\n          x.lineTo(...Q())\n        }\n        x.fillStyle=`hsla(${280/e*m-100},99%,${50+3/e*m**4}%,.5`\n        x.fill()\n      }\n      for(let i=sd;i--;){\n        if(i%2){\n          ls=i%2?s:s/2.5\n          X=S(p=Math.PI*2/sd*i+Math.PI*2/sd*j*k*n)*(l=ls*(1+1/rd))\n          Y=C(p)*l\n          while(p<0)p+=Math.PI*2\n          while(q>Math.PI*2)q-=Math.PI*2\n          while(q<0)q+=Math.PI*2\n          while(p>Math.PI*2)p-=Math.PI*2\n          if(!k||Math.abs(Math.abs(p-q)-Math.PI)>.01)RC(tx+X,ty+Y,s/rd,i,k+1,p)\n        }\n      }\n    }\n\n    x.fillStyle=\'#000\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=0\n    oY=1.5\n    oZ=8\n    t=0\n    Rl=-2, Pt=C(t)/2, Yw=S(t)/2\n    Rl=0, Pt=0, Yw=0\n    RC(0,0,5,0,0,0)\n    c2=c.cloneNode()\n    c2.width=c.width\n    c2.height=c.height\n    x_2=c2.getContext(\'2d\')\n    x_2.drawImage(c,0,0,c2.width,c2.height)\n  }\n  x.drawImage(c2,0,0,c.width,c.height)\n        \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123);\n  height: 100vh;\n}\n#c{\n  width: 100%;\n  height: 100%;\n}\n', '<canvas id=c></canvas>\