n  genstrt=genend\n  genend=genstrt+gendur\n  building=!!((t<1)||BB.length-BB.filter(v=>v[7]).length>cl*4)\n  if(building){\n    BB.map((v,i)=>{\n      if(v[7]<1){\n        tx=v[3]\n        ty=v[4]\n        keep=1,mct=0\n        dc=[0,0,0,0]\n        for(j=4;j--;){\n          switch(j){\n            case 0:\n              tx2=tx+G/cl\n              ty2=ty\n            break\n            case 1:\n              tx2=tx-G/cl\n              ty2=ty\n            break\n            case 2:\n              tx2=tx\n              ty2=ty+G/cl\n            break\n            case 3:\n              tx2=tx\n              ty2=ty-G/cl\n            break\n          }\n          BB.map((q,k)=>{\n            mind=Math.min(Math.hypot(tx2-q[0],ty2-q[1]),Math.hypot(tx2-q[3],ty2-q[4]))\n            if(mind<.001)dc[j]=1\n          })\n        }\n        v[7]+=(dc.indexOf(0)===-1?1:0)\n      }\n    })\n    nn=t?[]:[...BB]\n    B=BB\n    B2=B.filter(v=>v[7]<1)\n    for(i=genstrt;i<genend;i++){\n      l=Rn()*B2.length|0\n      X1=B2[l][0]\n      Y1=B2[l][1]\n      X2=B2[l][3]\n      Y2=B2[l][4]\n      B[l][6]++\n      tx=X2\n      ty=Y2\n      n=ct=0\n      do{\n        switch(Rn()*4|0){\n          case 0:\n            tx2=tx+G/cl\n            ty2=ty\n          break\n          case 1:\n            tx2=tx-G/cl\n            ty2=ty\n          break\n          case 2:\n            tx2=tx\n            ty2=ty+G/cl\n          break\n          case 3:\n            tx2=tx\n            ty2=ty-G/cl\n          break\n        }\n        B.map(v=>{\n          d1=Math.hypot(tx2-v[0],ty2-v[1])\n          d2=Math.hypot(tx2-v[3],ty2-v[4])\n          if(d1 < .01 || d2 < .01 || tx2 < -G/2 || tx2 > G/2 || ty2 < -G/2 || ty2 > G/2) n=1\n        })\n        ct++\n      }while(ct<4 && n);\n      if(!n){\n        m=[tx,ty,0,tx2,ty2,0,0,0]\n        nn.push(m)\n        BB.push(m)\n      }\n    }\n    B=nn\n\n    B.map(v=>{\n      v[2]+=G/2\n      v[5]+=G/2\n    })\n    b=JSON.parse(JSON.stringify(B))\n    b.map(v=>{\n      v[2]*=-1\n      v[5]*=-1\n    })\n    B=[...B,...b]\n    b=JSON.parse(JSON.stringify(B))\n    a=JSON.parse(JSON.stringify(B))\n    a.map(v=>{\n      X=v[0],Y=v[1],Z=v[2]\n      R(0,0,Math.PI/2)\n      v[0]=X,v[1]=Y,v[2]=Z\n      X=v[3],Y=v[4],Z=v[5]\n      R(0,0,Math.PI/2)\n      v[3]=X,v[4]=Y,v[5]=Z\n    })\n    B=[...B,...a]\n    b.map(v=>{\n      X=v[0],Y=v[1],Z=v[2]\n      R(0,Math.PI/2,0)\n      v[0]=X,v[1]=Y,v[2]=Z\n      X=v[3],Y=v[4],Z=v[5]\n      R(0,Math.PI/2,0)\n      v[3]=X,v[4]=Y,v[5]=Z\n    })\n    B=JSON.parse(JSON.stringify([...B,...b]))\n    oX=oY=0,oZ=-G/5,tt=0\n    l1=1\n    l2=(1-l1)\n  } else {\n    Rlv+=S(t/6)/300\n    Ptv+=S(t/8)/300\n    Ywv+=C(t/10)/300\n    Rlv/=1.3\n    Ptv/=1.3\n    Ywv/=1.3\n    Rl+=Rlv\n    Pt+=Ptv\n    Yw+=Ywv\n    oX=oY=0,oZ=Math.max(0,Math.min(G*.8,S(tt/1.5)*G*2))\n    tt+=1/120\n    l1=Math.min(1,2+S(tt*3)*2)\n    l2=(1-l1)\n  }\n  g=x.createLinearGradient(0,0,0,c.height)\n  g[l=\'addColorStop\'](0, \'#000\')\n  g[l](1, \'#023\')\n  x.fillStyle=g\n  x.fillRect(0,0,c.width,c.height)\n\n  ll=[...ll,...B]\n  //x.lineJoin=x.lineCap=\'round\'\n  ll.map(v=>{\n    x.beginPath()\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    if(!building){\n      d=Math.hypot(X,Y,Z)/(G/4)**2*G/25\n      px=X*d\n      py=Y*d\n      pz=Z*d\n      d=H(X,Y,Z)\n      tx=X/d,ty=Y/d,tz=Z/d\n      tx*=G/2,ty*=G/2,tz*=G/2\n      X=tx*l1+px*l2\n      Y=ty*l1+py*l2\n      Z=tz*l1+pz*l2\n    }\n    R(Rl,Pt,Yw,1)\n    if(Z>0)x.lineTo(...Q())\n    X=v[3]\n    Y=v[4]\n    Z=v[5]\n    if(!building){\n      d=Math.hypot(X,Y,Z)/(G/4)**2*G/25\n      px=X*d\n      py=Y*d\n      pz=Z*d\n      d=H(X,Y,Z)\n      tx=X/d,ty=Y/d,tz=Z/d\n      tx*=G/2,ty*=G/2,tz*=G/2\n      X=tx*l1+px*l2\n      Y=ty*l1+py*l2\n      Z=tz*l1+pz*l2\n    }\n    R(Rl,Pt,Yw,1)\n    if(Z>0)x.lineTo(...Q())\n    x.lineWidth=Math.min(100,G*40/mscl1/(H(X,Y,Z)**1.35))\n    x.strokeStyle=\'#0f83\'\n    x.stroke()\n    x.lineWidth/=5\n    x.lineWidth=Math.max(1,x.lineWidth)\n    x.strokeStyle=\'#fffc\'\n    x.stroke()\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()\n', 'body, html{\n  margin: 0;\n  width: 100%;\n  height: 100vh;\n  overflow: hidden;\n  background: #000;\n}\n#c{\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 100%;\n  height: 100%;\n  background: url(https://srmcgann.github.io/assets/138BkZ.jpg);\n  background-position: center center;\n  background-size: fill;\n  transform: translate(-50%, -50%);\n}\n', '<canvas id=c>', 'maze cube', 145, 'whitehot robot', '2022-05-16 18:56:39', '[600233]', 67, '', 0, 0),
(600235, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=playing=0\nwindow.onclick=()=>{if(!playing)mp3.play()}\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\nDraw=()=>{\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()\n', 'body, html{\n  margin: 0;\n  width: 100%;\n  height: 100vh;\n  overflow: hidden;\n  background: #000;\n}\n#c{\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 100%;\n  height: 100%;\n  background: url(https://srmcgann.github.io/assets/138BkZ.jpg);\n  background-position: center center;\n  background-size: fill;\n  transform: translate(-50%, -50%);\n}\n', '<canvas id=c>', 'basic template', 145, 'whitehot robot', '2022-05-17 18:04:17', '[600234,600233]', 69, '', 0, 1);
