(600236, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=playing=0\nwindow.onclick=()=>{if(!playing)mp3.play()}\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\nDraw=()=>{\n  if(!t){\n    Rn=Math.random\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*600,c.height/2+Y/Z*600]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    cl=9, G=60, sp=G/15, spd=1.25\n    B=Array(cl).fill().map((v,i)=>{\n      X=0\n      Y=(i-cl/2)*sp\n      Z=G\n      return [[X,Y,Z]]\n    })\n    bgimg=new Image()\n    bgimg.src=\'https://srmcgann.github.io/assets/1EfTuQ.jpg\'\n  }\n  x.lineJoin=x.lineCap=\'round\'\n\n  B=B.map((v,i)=>{\n    X=v[l=v.length-1][0]\n    Y=v[l][1]\n    Z=G\n    v.map(q=>{\n      q[2]-=spd\n    })\n    X+=S((Rn()-.5)*4+(i+99+t/16)**2)*2\n    //Y+=S(t/14)/20\n    if(X<-G/2)X=-G/2\n    if(X>G/2)X=G/2\n    if(Y<-G/2)v[l][1]=G/2\n    if(Y>G/2)v[l][1]=-G/2\n    v.push([X,Y,Z])\n    return v\n  })\n\n  x.globalAlpha=.3\n  x.drawImage(bgimg,0,0,c.width,c.height)\n  x.globalAlpha=1\n  x.fillStyle=\'#0005\'\n  x.fillRect(0,0,c.width,c.height)\n\n  Rl=S(t/6)*6;Pt=0;Yw=0\n  oX=0,oY=0,oZ=0\n  \n  B=B.map((v,i)=>{\n    v.map((q,j)=>{\n      if(j){\n        x.beginPath()\n        X=v[j][0]\n        Y=v[j][1]\n        Z=v[j][2]\n        R(Rl,Pt,Yw,1)\n        if(Z>-10)x.lineTo(...Q())\n        X=v[j-1][0]\n        Y=v[j-1][1]\n        Z=v[j-1][2]\n        R(Rl,Pt,Yw,1)\n        if(Z>-10)x.lineTo(...Q())\n        x.lineWidth = Math.min(500,2e3/(1+Z**1.4))\n        x.strokeStyle = `hsla(${Z*2-t*300+i/cl*360},99%,${100+S(Z/10+i*4+t*10)*70}%,.3)`\n        x.stroke()\n        x.lineWidth /= 8\n        x.strokeStyle=\'#fff\'\n        x.stroke()\n      }\n    })\n    v=v.filter(q=>{\n      return q[2]>0\n    })\n    return v\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()\n', 'body, html{\n  margin: 0;\n  width: 100%;\n  height: 100vh;\n  overflow: hidden;\n  background: #000;\n}\n#c{\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 100%;\n  height: 100%;\n  background: url(https://srmcgann.github.io/assets/138BkZ.jpg);\n  background-position: center center;\n  background-size: fill;\n  transform: translate(-50%, -50%);\n}\n', '<canvas id=c>', 'paths 2.0', 145, 'whitehot robot', '2022-05-18 17:26:18', '[600235,600234,600233]', 98, '', 0, 0),
(600237, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=playing=0\nwindow.onclick=()=>{if(!playing)mp3.play()}\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\nDraw=()=>{\n  if(!t){\n    Rn=Math.random\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*600,c.height/2+Y/Z*600]\n    segs=6\n    P=Array(60).fill().map(q=>{\n      return Array(segs).fill().map((v,i)=>{\n        X=0\n        Y=-(1.5*i)/(2+i**2.5/80)/1+1\n        Z=0\n        d=i?Math.hypot(X-a[0],Y-a[1],Z-a[2]):0\n        a=[X,Y,Z]\n        return [...a,0,0,0,d]\n      })\n    })\n    bgimg=new Image()\n    bgimg.src=\'https://twilightparadox.com/network.jpg\'\n  }\n\n  Rl=t/4,Pt=C(t/2)*3,Yw=S(t/4)*4\n  oX=oY=0,oZ=4+S(t)\n\n  x.globalAlpha=.2\n  x.drawImage(bgimg,0,0,c.width,c.height)\n  x.fillStyle=\'#0004\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin=x.lineCap=\'round\'\n\n  P.map(B=>{\n    B[B.length-1][3]/=1.3\n    B[B.length-1][4]/=1.3\n    B[B.length-1][5]/=1.3\n    B[B.length-1][0]+=B[B.length-1][3]+=(Rn()-.5)/10\n    B[B.length-1][1]+=B[B.length-1][4]+=(Rn()-.5)/10\n    B[B.length-1][2]+=B[B.length-1][5]+=(Rn()-.5)/10\n\n    B.map((v,i)=>{\n      j=B.length-i-1\n      if(i){\n        X=B[j][0]\n        Y=B[j][1]\n        Z=B[j][2]\n        d=Math.hypot(px=X-B[j+1][0],py=Y-B[j+1][1],pz=Z-B[j+1][2])\n        tx=px/d*B[j+1][6]\n        ty=py/d*B[j+1][6]\n        tz=pz/d*B[j+1][6]\n        B[j][0]=B[j+1][0]+tx\n        B[j][1]=B[j+1][1]+ty\n        B[j][2]=B[j+1][2]+tz\n      }\n    })\n    B[0][0]=0\n    B[0][1]=0\n    B[0][2]=0\n    B.map((v,i)=>{\n      if(i){\n        X=B[i][0]\n        Y=B[i][1]\n        Z=B[i][2]\n        d=Math.hypot(px=X-B[i-1][0],py=Y-B[i-1][1],pz=Z-B[i-1][2])\n        tx=px/d*v[6]\n        ty=py/d*v[6]\n        tz=pz/d*v[6]\n        v[0]=B[i-1][0]+tx\n        v[1]=B[i-1][1]+ty\n        v[2]=B[i-1][2]+tz\n      }\n    })\n    B.map((v,i)=>{\n      if(i){\n        x.beginPath()\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n        X=B[i-1][0]\n        Y=B[i-1][1]\n        Z=B[i-1][2]\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n        x.lineWidth=Math.min(400,5000/(Z**1.5)/(5+i**3/2))\n        x.globalAlpha=Math.max(0,(i-2)/6)\n        x.strokeStyle=`hsla(${i*10-t*60},99%,${(60+C(t)*40)-(50/segs*i)**2/50}%,1`\n        x.stroke()\n        x.globalAlpha=1\n        x.strokeStyle=`hsla(${i*10-t*60},99%,${(90+C(t*1.5)*20)-(20/segs*i)**2/50}%,.5`\n        x.lineWidth/=5\n        x.stroke()\n      }\n    })\n  })\n  x.globalAlpha=1\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  margin: 0;\n  overflow: hidden;\n  background: #000;\n  width: 100%;\n  height: 100vh;\n  text-align: center;\n}\n#c{\n  width: 100%;\n  height: 100%;\n}', '<canvas id=c>', 'bones', 145, 'whitehot robot', '2022-05-18 22:28:04', '', 72, '', 0, 0),
(600238, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=playing=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\nDraw=()=>{\n  if(!t){\n    Rn=Math.random\n    bgimg=new Image()\n    bgimg.src=\'/video/network.jpg\'\n    catface = new Image()\n    catface.src = \'/video/cat-face.gif\'\n    mx=my=moves=0\n    winnerLine = []\n    inplay=true\n    sqid=-1\n    window.onclick=e=>{\n      if(inplay && B[sqid]==-1) play()\n    }\n    window.ontouchend=e=>{\n      setTimeout(()=>{\n        if(inplay && B[sqid]==-1) play()\n      },500)\n    }\n    window.ontouchstart=e=>{\n      r=c.getBoundingClientRect()\n      mx=(e.pageX-r.left)/c.clientWidth*c.width\n      my=(e.pageY-r.top)/c.clientHeight*c.height\n    }\n    window.ontouchmove=e=>{\n      r=c.getBoundingClientRect()\n      mx=(e.pageX-r.left)/c.clientWidth*c.width\n      my=(e.pageY-r.top)/c.clientHeight*c.height\n    }\n    window.onmousemove=e=>{\n      r=c.getBoundingClientRect()\n      mx=(e.pageX-r.left)/c.clientWidth*c.width\n      my=(e.pageY-r.top)/c.clientHeight*c.height\n    }\n    turn=false\n    B=Array(9).fill(-1)\n\n    idx=(X,Y)=>{\n      return Y*3+X\n    }\n\n    idx2=val=>{\n      return [val%3, val/3|0]\n    }\n\n    fill=(idx, col)=>{\n      l=idx2(idx)\n      X=(l[0]-1.5)*s*2\n      Y=(l[1]-1.5)*s*2\n      x1=c.width/2+X\n      y1=c.height/2+Y\n      x.fillStyle=col\n      x.fillRect(x1,y1,s*2,s*2)\n    }\n\n    restart=()=>{\n      document.querySelectorAll(\'.replay\')[0].style.display=\'none\'\n      setTimeout(()=>{\n        turn=false\n        B=Array(9).fill(-1)\n        inplay=true\n        winnerLine = []\n        sqid=-1\n        moves=0\n      },500)\n    }\n\n    doEnding=()=>{\n      inplay=false\n      let el = document.querySelectorAll(\'.replay\')[0]\n      el.style.display=\'block\'\n      el.innerHTML = winnerLine.length>1?\'play again\':\'\"cat\\\'s game!\"<br><div style=\"display: inline-block;width:100px;height:50px;background-size: 100px 50px;background-image: url(/video/cat-face.gif)\"></div><br>play again\'\n    }\n\n    victor=(O,n,q)=>{\n      a=[]\n      for(let m=3;m--;){\n        switch(q){\n         case 0: //ROW\n           a=[...a, [n, m]]\n         break\n         case 1: //COLUMN\n           a=[...a, [m, n]]\n         break\n         case 2: //DIAGONAL\n           l=[[0,4,8],[2,4,6]]\n           a=[...a, [...idx2(l[n][m])]]\n         break\n        }\n      }\n      winnerLine=a\n    }\n\n    check=()=>{\n      let inplay=true\n      for(O=2;O--;){\n        tgval=O?true: false\n        for(n=3;n--;){\n          for(ct=0, m=3; m--;) ct+=B[id=idx(n, m)]==tgval?1:0\n          if(inplay && ct==3) inplay=false, victor(O,n,0)\n          for(ct=0, m=3; m--;) ct+=B[id=idx(m, n)]===tgval?1:0\n          if(inplay && ct==3) inplay=false, victor(O,n,1)\n        }\n        l=[[0,4,8],[2,4,6]]\n        for(m=3;m--;)for(n=2;n--;){\n          if(inplay && B[l[n][m]]===tgval&&B[l[n][(m+1)%3]]===tgval&&B[l[n][(m+2)%3]]==tgval) inplay=false,victor(O,n,2)\n        }\n      }\n      return inplay\n    }\n\n    play=()=>{\n      moved=false\n      B[sqid]=turn\n      if(!moves){\n        if(sqid==1||sqid==3||sqid==5||sqid==7){\n          l=[4]\n          for(i=4;i--;){\n            if(!moved){\n              id = l[(i)%l.length]\n              if(B[id]==-1){B[id]=true,moves++;return}\n            }\n          }\n        }\n        if(sqid==0||sqid==2||sqid==6||sqid==8){\n          if(B[4]==-1){B[4]=true,moves++;return}\n          l=[1,3,5,7]\n          for(i=4;i--;){\n            if(!moved){\n              id = l[(i)%l.length]\n              if(B[id]==-1){B[id]=true,moves++;return}\n            }\n          }\n        }\n        if(B[4]===false){\n          l=[0,2,6,8]\n          for(i=4;i--;){\n            if(!moved){\n              id = l[(i)%l.length]\n              if(B[id]==-1){B[id]=true,moves++;moved=true;return}\n            }\n          }\n        }\n      }\n      moves++\n      for(O=2;O--;){\n        if(!moved){\n          tgval=O?true: false\n          for(n=3;n--;){\n            for(ct=cs=0, m=3; m--;){\n              if(B[id=idx(m, n)]==-1) bk=id, cs++\n              ct+=B[id]===tgval?1:0\n            }\n            if(!moved && cs && ct==2) B[bk]=true, moved=true\n            for(ct=cs=0, m=3; m--;){\n              if(B[id=idx(n, m)]==-1) bk=id, cs++\n              ct+=B[id]===tgval?1:0\n            }\n            if(!moved && cs && ct==2) B[bk]=true, moved=true\n          }\n          l=[[0,4,8],[2,4,6]]\n          for(m=3;m--;)for(n=2;n--;){\n            if(!moved&&B[l[n][m]]===tgval&&B[l[n][(m+1)%3]]===tgval&&B[l[n][(m+2)%3]]==-1)B[l[n][(m+2)%3]]=true,moved=true\n          }\n        }\n      }\n\n      inplay=false\n      B.map((v,i)=>{\n        if(v==-1){\n          inplay=true\n        }\n      })\n      if(!check() || !inplay){\n        doEnding()\n      } else if(!moved) {\n        a=[]\n        B.map((v,i)=>{\n          if(v==-1) a=[...a, i]\n        })\n        if(moves==2){\n          if(sqid==0||sqid==2||sqid==6||sqid==8){\n            if(B[4]==-1){B[4]=true,moves++;return}\n            l=B[4]==false?[0,2,6,8]:[1,3,5,7]\n            for(i=4;i--;){\n              if(!moved){\n                id = l[(i)%l.length]\n                if(B[id]==-1){B[id]=true,moves++;return}\n              }\n            }\n          }\n        }\n        if(B[4]==-1){B[4]=true,moves++;return}      \n        B[a[Math.random()*a.length|0]]=true\n      }\n    }\n\n    drawBoard=()=>{\n      x.globalAlpha=.2\n      x.drawImage(bgimg,0,0,c.width,c.height)\n      x.fillStyle=\'#0004\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      x.beginPath()\n      x.lineTo(c.width/2-s,c.height/2-s2)\n      x.lineTo(c.width/2-s,c.height/2+s2)\n      x.lineWidth=50\n      x.strokeStyle=\'#fff3\'\n      x.stroke()\n      x.lineWidth/=3\n      x.strokeStyle=\'#fff\'\n      x.stroke()\n      x.beginPath()\n      x.lineTo(c.width/2+s,c.height/2-s2)\n      x.lineTo(c.width/2+s,c.height/2+s2)\n      x.lineWidth=50\n      x.strokeStyle=\'#fff3\'\n      x.stroke()\n      x.lineWidth/=3\n      x.strokeStyle=\'#fff\'\n      x.stroke()\n      x.beginPath()\n      x.lineTo(c.width/2-s2,c.height/2-s)\n      x.lineTo(c.width/2+s2,c.height/2-s)\n      x.lineWidth=50\n      x.strokeStyle=\'#fff3\'\n      x.stroke()\n      x.lineWidth/=3\n      x.strokeStyle=\'#fff\'\n      x.stroke()\n      x.beginPath()\n      x.lineTo(c.width/2-s2,c.height/2+s)\n      x.lineTo(c.width/2+s2,c.height/2+s)\n      x.lineWidth=50\n      x.strokeStyle=\'#fff3\'\n      x.stroke()\n      x.lineWidth/=3\n      x.strokeStyle=\'#fff\'\n      x.stroke()\n      x.globalAlpha=1\n    }\n\n    xpic=new Image()\n    xpicloaded=false\n    xpic.onload=()=>{xpicloaded=true}\n    xpic.src = \'/video/o.png\'\n    opic=new Image()\n    opicloaded=false\n    opic.onload=()=>{opicloaded=true}\n    opic.src = \'/video/x.png\'\n  }\n\n  if(xpicloaded && opicloaded){\n\n    s=c.width>c.height?c.width/12:c.height/12\n    s2=s*3\n    drawBoard()\n \n    x.fillStyle=\'#4f8\'\n    x.fillRect(mx-s/8,my-s/8,s/4,s/4)\n\n    B.map((v,i)=>{\n      if(v!=-1){\n        l=idx2(i)\n        X=(l[0]-1.5)*s*2\n        Y=(l[1]-1.5)*s*2\n        x1=c.width/2+X\n        y1=c.height/2+Y\n        x.drawImage(v?xpic:opic,x1,y1,s*2,s*2)\n      }\n    })\n\n    if(inplay){\n      sqid=-1\n      for(i=9;i--;){\n        l=idx2(i)\n        X=(l[0]-1.5)*s*2\n        Y=(l[1]-1.5)*s*2\n        x1=c.width/2+X\n        y1=c.height/2+Y\n        x2=x1+s*2\n        y2=y1+s*2\n        if(mx>x1&&mx<x2&&my>y1&&my<y2){\n          sqid=i\n          fill(i, B[i]==-1?\'#4f82\':\'#f442\')\n        }\n      }\n    }\n    if(winnerLine.length){\n      x.beginPath()\n      winnerLine.map(v=>{\n        X=c.width/2+(v[0]-1)*s*2\n        Y=c.height/2+(v[1]-1)*s*2\n        x.lineTo(X,Y)\n      })\n      x.strokeStyle=\'#f00\'\n      x.lineWidth=40\n      x.stroke()\n      x.lineWidth/=3\n      x.strokeStyle=\'#faa\'\n      x.stroke()\n    }\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  margin: 0;\n  overflow: hidden;\n  background: #000;\n  width: 100%;\n  height: 100vh;\n  text-align: center;\n}\n#c{\n  position: absolute;\n  width: 100%;\n  height: 100%;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n}\n.replay{\n  z-index: 100;\n  display: none;\n  border: none;\n  background: #284c;\n  font-family: courier;\n  color: #fff;\n  text-shadow: 1px 1px 1px #000;\n  position: absolute;\n  left: 50%;\n  font-size: 24px;\n  top: 50%;\n  cursor: pointer;\n  border-radius: 10px;\n  padding: 5px;\n  min-width: 200px;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>\n<button onclick=\"restart()\" class=\"replay\">play again</button>', 'unbeatable tic tac toe', 145, 'whitehot robot', '2022-05-19 14:37:53', '[600237]', 100, '', 0, 0),
