     //printLn(\'  ^\', posx, posy+20)\n      //printLn(\'  |\', posx, posy+=fs-15)\n      //printLn(\' val\', posx, posy+=fs)\n\n      x.beginPath()\n      for(i=10;i--;){\n        X=i*73,Y=-(a=1/((10-i)/10))*130\n        x.lineTo(c.width/2+170+X,c.height/2+30+Y)\n        x.font=(fs=30)+\'px courier\'\n        if(i<8){\n          posx=c.width/2+35,posy=c.height/2-120-c.height/3/w*i\n          printLn(Math.round(a*100)/100, posx, posy+20)\n        }\n      }\n      x.stroke()\n\n      x.font=(fs=42)+\'px courier\'\n      posx=60,posy=c.height/2+60\n      printLn(\'observe\', posx, posy)\n      printLn(\'\', posx, posy+=fs)\n      printLn(\'  the curve resembles an\', posx, posy+=fs)\n      printLn(\'  exponential increase,\', posx, posy+=fs)\n      printLn(\'  approaching astronomically\', posx, posy+=fs)\n      printLn(\'  large values as the\', posx, posy+=fs)\n      printLn(\'  denominator approaches zero.\', posx, posy+=fs)\n      printLn(\'\', posx, posy+=fs)\n      printLn(\'  The obvious conclusion is that\', posx, posy+=fs)\n      printLn(\'  upon reaching zero, the value\', posx, posy+=fs)\n      printLn(\'  returned, is infinite.\', posx, posy+=fs)\n\n      tlc=x.lineCap\n      x.lineCap=x.lineJoin=\'round\'\n      for(i=99;i--;){\n        x.beginPath()\n        X=S(p=Math.PI*2/99*i)*1.5\n        Y=S(p*2)*1.5/2\n        Z=0\n        R(0,C(t)/4,S(t/3)*Math.PI*2)\n        R(Rl,Pt,Yw,1)\n        l=Q()\n        x.lineTo(l[0]+c.width/4,l[1]+c.height/4)\n        X=S(p=Math.PI*2/99*(i+1))*1.5\n        Y=S(p*2)*1.5/2\n        Z=0\n        R(0,C(t)/4,S(t/3)*Math.PI*2)\n        R(Rl,Pt,Yw,1)\n        l=Q()\n        x.lineTo(l[0]+c.width/4,l[1]+c.height/4)\n        x.lineWidth=500/(Z**1.5)\n        x.strokeStyle=\'#0001\'\n        x.stroke()\n        x.lineWidth/=4\n        x.strokeStyle=\'#0008\'\n        x.stroke()\n      }\n      x.lineCap=x.lineJoin=tlc\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n  overflow: hidden;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  border: 1px solid #0ff8;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'div by zero graphs', 145, 'whitehot robot', '2022-06-30 17:12:52', '[600253,600252,600251,600248,600247]', 107, 'https://code.dweet.net/thumbs/18161247b5c48083d0d878f2bf20bb1a.jpg', 0, 0),
