h/=3\n          x.strokeStyle=\'#fff8\'\n          x.stroke()\n          x.fillStyle=\'#0f48\'\n          s=100/Z\n          ax/=v.length\n          ay/=v.length\n          az/=v.length\n          X=ax\n          Y=ay\n          Z=az\n          R(Rl,Pt,Yw,1)\n          l=Q()\n          x.fillRect(l[0]-s/2+Gx,l[1]-s/2+Gy,s,s)\n          x.beginPath()\n          X=ax\n          Y=ay\n          Z=az\n          R(Rl,Pt,Yw,1)\n          l=Q()\n          x.lineTo(l[0]+Gx,l[1]+Gy)\n          p1=Math.atan2(ax,az)\n          p2=Math.acos(ay/Math.hypot(ax,ay,az))\n          X=ax+S(p1)*S(p2)/2\n          Y=ay+C(p2)/2\n          Z=az+C(p1)*S(p2)/2\n          R(Rl,Pt,Yw,1)\n          l=Q()\n          x.lineTo(l[0]+Gx,l[1]+Gy)\n          x.strokeStyle=\'#f008\'\n          x.stroke()\n          v.map((q,j)=>{\n              X=(q[0]+v[l=(j+1)%v.length][0])/2\n              Y=(q[1]+v[l][1])/2\n              Z=(q[2]+v[l][2])/2\n              hexes[j]=[...hexes[j],[X,Y,Z]]\n          })\n          R(Rl,Pt,Yw,1)\n          s=100/Z\n          l=Q()\n          x.fillStyle=\'#ff08\'\n          x.fillRect(l[0]-s/2+Gx,l[1]-s/2+Gy,s,s)\n        })\n        hexes.map((hex,f)=>{\n          hex.map((n,i)=>{\n            x.beginPath()\n            switch(i%6){\n              case 0:\n                j=0,l=4\n              break\n              case 1:\n                j=4,l=2\n              break\n              case 2:\n                j=2,l=3\n              break\n              case 3:\n                j=3,l=1\n              break\n              case 4:\n                j=1,l=5\n              break\n              case 5:\n               j=5,l=0\n              break\n            }\n            v=hex[j]\n            q=hex[l]\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0){\n              l=Q()\n              x.lineTo(l[0]+Gx,l[1]+Gy)\n            }\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0){\n              l=Q()\n              x.lineTo(l[0]+Gx,l[1]+Gy)\n            }\n            x.lineWidth=120/(Z**1.5)\n            x.strokeStyle=\'#40f5\'\n            if(f==0)x.stroke()\n            x.lineWidth/=4\n            x.strokeStyle=\'#0f8a\'\n            x.closePath()\n            if(f==0)x.stroke()\n            //x.font=\'125px courier\'\n            //x.fillStyle=\'#fff\'\n          })\n        })\n      }\n\n\n/*  (golfed)\nif(!t){M=Math;R=(Rl,Pt,Yw,m)=>{X=S(p=(A=M.atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ};Q=()=>[c.width/2+X/Z*400,c.height/2+Y/Z*400];for(CB=[],j=6;j--;CB=[...CB,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=M.PI*2/4*i+M.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]};x.fillStyle=\'#0008\';x.fillRect(0,0,c.width,c.height);x.lineJoin=x.lineCap=\'round\';oX=0,oY=0,oZ=7;cl=5,rw=3,sp=350;for(G_=cl*rw;G_--;){oZ=5+S(G_**2+t*4)*2;Gx=((G_%cl)-cl/2+.5)*sp;Gy=((G_/cl|0)-rw/2+.5)*sp;hex=[],G=Array(6).fill([]);CB.map((v,i)=>{x.beginPath();ax=ay=az=0;v.map(q=>{ax+=X=q[0];ay+=Y=q[1];az+=Z=q[2];R(.02/cl/rw,S(t)/30/cl/rw,C(t/2)/40/cl/rw,0);q[0]=X;q[1]=Y;q[2]=Z;R(0,0,0,1);l=Q();x.lineTo(l[0]+Gx,l[1]+Gy)});x.closePath();x.lineWidth=100/Z;x.strokeStyle=\'#fff2\';x.stroke();x.lineWidth/=3;x.strokeStyle=\'#fff8\';x.stroke();x.fillStyle=\'#0f48\';s=100/Z;ax/=v.length;ay/=v.length;az/=v.length;X=ax;Y=ay;Z=az;R(0,0,0,1);l=Q();x.fillRect(l[0]-s/2+Gx,l[1]-s/2+Gy,s,s);x.beginPath();X=ax;Y=ay;Z=az;R(0,0,0,1);l=Q();x.lineTo(l[0]+Gx,l[1]+Gy);p1=M.atan2(ax,az);p2=M.acos(ay/M.hypot(ax,ay,az));X=ax+S(p1)*S(p2)/2;Y=ay+C(p2)/2;Z=az+C(p1)*S(p2)/2;R(0,0,0,1);l=Q();x.lineTo(l[0]+Gx,l[1]+Gy);x.strokeStyle=\'#f008\';x.stroke();v.map((q,j)=>{X=(q[0]+v[l=(j+1)%v.length][0])/2;Y=(q[1]+v[l][1])/2;Z=(q[2]+v[l][2])/2;G[j]=[...G[j],[X,Y,Z]]});R(0,0,0,1);s=100/Z;l=Q();x.fillStyle=\'#ff08\';x.fillRect(l[0]-s/2+Gx,l[1]-s/2+Gy,s,s)});G.map((hex,f)=>{hex.map((n,i)=>{x.beginPath();switch(i%6){case 0:;j=0,l=4;break;case 1:;j=4,l=2;break;case 2:;j=2,l=3;break;case 3:;j=3,l=1;break;case 4:;j=1,l=5;break;case 5:;j=5,l=0};v=hex[j];q=hex[l];X=v[0];Y=v[1];Z=v[2];R(0,0,0,1);if(Z>0){l=Q();x.lineTo(l[0]+Gx,l[1]+Gy)};X=q[0];Y=q[1];Z=q[2];R(0,0,0,1);if(Z>0){l=Q();x.lineTo(l[0]+Gx,l[1]+Gy)};x.lineWidth=120/(Z**1.5);x.strokeStyle=\'#40f5\';if(f==0)x.stroke();x.lineWidth/=4;x.strokeStyle=\'#0f8a\';x.closePath();if(f==0)x.stroke()})})}\n*/\n\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'normal test (grid)', 145, 'whitehot robot', '2022-07-01 00:44:23', '[600279,600278,600266,600253,600252,600251,600248,600247]', 81, 'https://code.dweet.net/thumbs/2deb57a9c816ab80140bd64161da7557.jpg', 0, 0),
