          Z=C(p)*ls1              \n              a=[...a,[X,Y,Z]]\n              b=[...b,[X,-Y,Z]]\n            }\n            shp=[...shp, a]\n            shp=[...shp, b]\n          }\n          s1=.3\n          s2=ls1/3\n          e=[\n            [-s1,0,-s1-s2],\n            [-s1,0,s1-s2],\n            [s1,0,s1-s2],\n            [s1,0,-s1-s2],\n          ]\n          f=[\n            [-s1,0,-s1+s2],\n            [-s1,0,s1+s2],\n            [s1,0,s1+s2],\n            [s1,0,-s1+s2],\n          ]\n          shp=[...shp, e, f]\n          return shp\n        }\n\n        iBc=8, iBv=.0, G=4\n        B=Array(iBc).fill().map((v,i)=>{\n          X=(Rn()-.5)\n          Y=(Rn()-.5)\n          Z=(Rn()-.5)\n          return [X,Y,Z, Cylinder(1,8,G*1.25/iBc**.4,G/iBc**.4/16,1)]\n        })\n        for(m=2;m--;){\n          B.map((v,i)=>{\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            tx=ty=tz=0\n            B.map((q,j)=>{\n              if(j!=i){\n                d=1+Math.hypot(X-q[0],Y-q[1],Z-q[2])\n                v[0]-=(q[0]-X)/(l=(d**5))\n                v[1]-=(q[1]-Y)/l\n                v[2]-=(q[2]-Z)/l\n              }\n            })\n            d=Math.hypot(v[0], v[1], v[2])\n            v[0]/=d\n            v[1]/=d\n            v[2]/=d\n          })\n        }\n        B.map(v=>{\n          d=Math.hypot(v[0],v[1],v[2])\n          v[0]/=d\n          v[1]/=d\n          v[2]/=d\n          v[0]*=G\n          v[1]*=G\n          v[2]*=G\n        })\n\n        for(m=200+(500/iBc|0);m--;){\n          B.map((v,i)=>{\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            tx=ty=tz=0\n            B.map((q,j)=>{\n              if(j!=i){\n                d=1+Math.hypot(X-q[0],Y-q[1],Z-q[2])\n                v[0]-=(q[0]-X)/(l=(d**5))\n                v[1]-=(q[1]-Y)/l\n                v[2]-=(q[2]-Z)/l\n              }\n            })\n            d=Math.hypot(v[0],v[1],v[2])\n            v[0]/=d\n            v[1]/=d\n            v[2]/=d\n          })\n        }\n        B.map(v=>{\n          p1=Math.atan2(v[0],v[2])\n          p2=-Math.acos(v[1]/Math.hypot(v[0],v[1],v[2]))\n          v[3].map(q=>{\n            q.map(n=>{\n              X=n[0]\n              Y=n[1]\n              Z=n[2]\n              R(0,p2,p1,0)\n              n[0]=X\n              n[1]=Y\n              n[2]=Z\n            })\n          })\n          d=Math.hypot(v[0],v[1],v[2])\n          v[0]/=d\n          v[1]/=d\n          v[2]/=d\n          v[0]*=G\n          v[1]*=G\n          v[2]*=G\n        })\n\n        world=[], iWc=2, G2=(G*iWc*20)**.45\n        for(i=iWc;i--;){\n          do{\n            good=true\n            X=(Rn()-.5)*G2\n            Y=(Rn()-.5)*G2\n            Z=(Rn()-.5)*G2\n            world.map(v=>{\n              tx=v[0]\n              ty=v[1]\n              tz=v[2]\n              if(Math.hypot(tx-X,ty-Y,tz-Z)<G*2.25) good=false\n            })\n          }while(!good)\n          world=[...world, [X,Y,Z,JSON.parse(JSON.stringify(B)),(Rn()-.5)*iBv,(Rn()-.5)*iBv,(Rn()-.5)*iBv]]\n        }\n\n        g=3\n      }\n      x.fillStyle=\'#0008\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=G2*1.5\n\n      world.map(m=>{\n        tx_=m[0]+=m[4]\n        ty_=m[1]+=m[5]\n        tz_=m[2]+=m[6]\n        m[3].map((v,i)=>{\n          tx=tx_+v[0]\n          ty=ty_+v[1]\n          tz=tz_+v[2]\n          v[3].map((q,j)=>{\n            x.beginPath()\n            q.map(n=>{\n              X=n[0]+tx\n              Y=n[1]+ty\n              Z=n[2]+tz\n              switch(g){\n                case 0:\n                  R(0,0,S(t/2)*Math.PI*2+Math.PI/3,0)\n                  //x.fillStyle=\'#f002\'\n                  break\n                case 1:\n                  R(0,S(t/2)*Math.PI*2+Math.PI/2,0,0)\n                  //x.fillStyle=\'#ff02\'\n                  break\n                case 2:\n                  R(S(t/2)*Math.PI*2+Math.PI/2,0,0,0)\n                  //x.fillStyle=\'#00f2\'\n                  break\n              }\n              R(Rl,Pt,Yw,1)\n              if(Z>0)x.lineTo(...Q())\n            })\n            x.fillStyle=\'#fff1\'//`hsla(${360/3*g+t*300+S(t)*500},99%,${100+C(t*2)*100}%,.1`\n            if(j==v[3].length-1) {\n              x.fillStyle=\'#f006\'\n            } else if(j==v[3].length-2) {\n              x.fillStyle=\'#06f6\'\n            }\n            x.lineWidth=Math.min(500, 300/(Z**1.5))\n            x.closePath()\n            x.strokeStyle=\'#fff1\'\n            x.stroke()\n            x.lineWidth/=6\n            x.strokeStyle=\'#fff4\'\n            x.stroke()\n            x.fill()\n          })\n        })\n      })\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'game solver', 145, 'whitehot robot', '2022-07-04 20:01:24', '[600253,600252,600251,600248,600247]', 46, 'https://code.dweet.net/thumbs/8de6c98ae082f8f7a6434f00f8e79439.jpg', 0, 1),
