(600299, '', '\n  /****** SOME BOILERPLATE TO WIRE UP THE CANVAS  ******/\n\n    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n    c.width=1920\n    c.height=1080\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    /************/\n\n\n    Draw=()=>{\n\n      x.fillStyle=\'#0008\'\n      x.fillRect(0,0,c.width,c.height)\n      \n      // first frame (t==0) is an opportunity to define some stuff\n      if(!t){\n        keys=Array(256).fill(0)\n        window.onkeydown=e=>{\n          e.preventDefault()\n          e.stopPropagation()\n          if(e.keyCode-48>=0 && e.keyCode-48<10) focus_idx=e.keyCode-48\n          keys[e.keyCode]=true\n        }\n        window.onkeyup=e=>{\n          e.preventDefault()\n          e.stopPropagation()\n          keys[e.keyCode]=false\n        }\n        Rn = Math.random\n        NPC_vel = 3\n        player_vel=NPC_vel*8\n        NPC_turn_vel=.05\n        B=Array(100).fill().map(v=>{\n          X = (Rn()-.5) * c.width\n          Y = (Rn()-.5) * c.width\n          direction = Rn()*Math.PI*2\n          return [X, Y, direction, 0]\n        })\n        P=Array(10).fill().map(v=>{\n          X = 0\n          Y = 0\n          direction = Rn()*Math.PI*2\n          return [X, Y, direction, 0]\n        })\n        \n        Q=(X,Y,r)=>{\n          let a, b\n          let p=Math.atan2(a=X-c.width/2, b=Y-c.height/2)-(r?P[focus_idx][2]:0)+Math.PI\n          let d=Math.hypot(a,b)\n          X=c.width/2+S(p)*d\n          Y=c.height/2+C(p)*d\n          return [X, Y]\n        }\n\n        focus_idx=0\n      }\n\n      P.map((v, i)=>{\n        v[3]/=i==focus_idx?1.5:1.02\n        v[2]+=v[3]\n        if(i!==focus_idx){\n          vx = S(v[2])*NPC_vel\n          vy = C(v[2])*NPC_vel\n          v[3]+=(Rn()-.5)*NPC_turn_vel\n        } else {\n          vx=0, vy=0\n          if(keys[37]){\n            v[3]+=NPC_turn_vel\n          }\n          if(keys[38]){\n            vx = S(v[2])*player_vel\n            vy = C(v[2])*player_vel\n          }\n          if(keys[39]){\n            v[3]-=NPC_turn_vel\n          }\n          if(keys[40]){\n            vx = -S(v[2])*player_vel\n            vy = -C(v[2])*player_vel\n          }\n        }\n        X = c.width/2 + (v[0] += vx)\n        Y = c.height/2 + (v[1] += vy)\n        if(v[0] > c.width/2) v[0] -= c.width\n        if(v[0] < -c.width/2) v[0] += c.width\n        if(v[1] > c.width/2) v[1] -= c.width\n        if(v[1] < -c.width/2) v[1] += c.width\n        x.fillStyle=\'#0ff3\'\n        s=50\n        if(i==focus_idx){\n          cx = X-c.width/2, cy = Y-c.height/2\n        }\n        l=Q(X-cx, Y-cy, 1)\n        x.fillRect(l[0]-s/2,l[1]-s/2, s, s)\n        x.fillStyle=\'#0ff\'\n        s/=3\n        l=Q(X-cx, Y-cy, 1)\n        x.fillRect(l[0]-s/2,l[1]-s/2, s, s)\n\n        x.fillStyle=\'#fff\'\n        x.font=\'70px courier\'\n        x.fillText(i,l[0]+20, l[1]+40)\n\n        x.beginPath()\n        X=v[0]+c.width/2\n        y=v[1]+c.height/2\n        tx=S(p=i==focus_idx?0:v[2])\n        ty=C(p)\n        x.lineTo(...Q(X-tx*50-cx,Y-ty*50-cy, i!=focus_idx))\n        x.lineTo(...Q(X+tx*100-cx,Y+ty*100-cy, i!=focus_idx))\n        x.strokeStyle=\'#0ff\'\n        x.lineWidth=10\n        x.stroke()\n      })\n\n      B.map(v=>{\n        v[3]+=(Rn()-.5)*NPC_turn_vel\n        v[3]/=1.1\n        vx = S(v[2]+=v[3])*NPC_vel\n        vy = C(v[2])*NPC_vel\n        X = c.width/2 + (v[0] += vx)\n        Y = c.height/2 + (v[1] += vy)\n        if(v[0] > c.width/2) v[0] -= c.width\n        if(v[0] < -c.width/2) v[0] += c.width\n        if(v[1] > c.width/2) v[1] -= c.width\n        if(v[1] < -c.width/2) v[1] += c.width\n        x.fillStyle=\'#fff3\'\n        s=25\n        l=Q(X-cx, Y-cy, 1)\n        x.fillRect(l[0]-s/2,l[1]-s/2, s, s)\n        x.fillStyle=\'#fff\'\n        s/=3\n        l=Q(X-cx, Y-cy, 1)\n        x.fillRect(l[0]-s/2,l[1]-s/2, s, s)\n\n        x.beginPath()\n        X=v[0]+c.width/2\n        y=v[1]+c.height/2\n        tx=S(p=v[2])\n        ty=C(p)\n        x.lineTo(...Q(X-tx*25-cx,Y-ty*25-cy, 1))\n        x.lineTo(...Q(X+tx*50-cx,Y+ty*50-cy, 1))\n        x.strokeStyle=\'#f00\'\n        x.lineWidth=3\n        x.stroke()\n      })\n\n      x.beginPath()\n      for(i=4;i--;){\n        X=S(p=Math.PI*2/4*i+Math.PI/4)*c.width\n        Y=C(p)*c.width\n        q=Math.atan2(X,Y)//-P[focus_idx][2]\n        d=Math.hypot(X,Y)\n        X=S(q)*d/2**.5\n        Y=C(q)*d/2**.5\n        x.lineTo(...Q(c.width/2+X-cx,c.height/2+Y-cy, 1))\n      }\n      x.strokeStyle=\'#f00\'\n      x.closePath()\n      x.lineWidth=20\n      x.stroke()\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #333;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'game rotation about arbitrary player or point', 145, 'whitehot robot', '2022-07-09 21:59:21', '[600253,600252,600251,600248,600247]', 140, '', 0, 0),
