            green = l[i+1]\n            blue  = l[i+2]\n            a=[...a,String.fromCharCode(48+((red+green+blue)/3/255*10)|0)]\n            r_=red/255\n            g_=green/255\n            b_=blue/255\n            cmax=Math.max(r_,g_,b_)\n            cmin=Math.min(r_,g_,b_)\n            //if(delta = cmax-cmin){\n              //if(r_ > g_ && g_ > b_) hue = 60 * ((g_-b_)/delta%6)\n              //if(g_ > b_ && b_ > r_) hue = 60 * ((b_-r_)/delta+2)\n              //if(b_ > r_ && r_ > g_) hue = 60 * ((r_-g_)/delta+4)\n              //a=[...a,(32+hue/360*64)|0]\n            //} else {\n            //  a=[...a,0]\n            //}\n          }\n          b=[]\n          nextPos=0\n          a.map((v,i)=>{\n            tc=0, good=true\n            a.map((q,j)=>{\n              if(j>i && good){\n                if(q==v&&tc<128){\n                  tc++\n                }else{\n                  good=false\n                }\n              }\n            })\n            if(tc>2&&nextPos<=i && tc<200){\n              b=[...b, String.fromCharCode(56+tc), v]\n              nextPos=i+tc\n            }else{\n              if(nextPos<i) b=[...b, v]\n              tc=0\n            }\n          })\n          a=a.join(\'\')\n          console.log(b.join(\'\').replaceAll(\"\'\", \"\\\'\").replaceAll(\' \',\'\').replace(\'\\\\\', \'\\\\\\\\\'))\n        }\n        img.src=\'/proxy.php?url=https://srmcgann.github.io/assets/4nvw0.png\'\n      }\n      \n      if(go){\na.split(\'\').map((v,i)=>{x.fillStyle=`hsl(0,0%,${v*11}%)`,x.fillRect(i%q,(i/q|0),1,1)})\n      }\n      \n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'export img to string', 145, 'whitehot robot', '2022-07-10 18:05:54', '