(600304, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n        go=false\n        bg=document.createElement(\'video\')\n        bg.oncanplay=()=>{\n          go=true\n          bg.play()\n        }\n        bg.loop=true\n        bg.muted=true\n        bg.src=\'/proxy.php?url=https://twilightparadox.com/binia2.mp4\'\n      }\n      x.fillStyle=\'#0008\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      if(go){\n        x.drawImage(bg,0,0,c.width,c.height)\n      }      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'logo psychedlic', 145, 'whitehot robot', '2022-07-12 03:25:32', '[600253,600252,600251,600248,600247]', 67, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600305, 'https://srmcgann.github.io/assets/2bohkH.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n\n        for(a=[1,1],i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]]\n        phi = a[l+1]/a[l]\n\n        rects=Array(3).fill().map((v,i)=>{\n          a=[]\n          a=[...a, [-phi/2, -.5, 0]]\n          a=[...a, [phi/2,  -.5, 0]]\n          a=[...a, [phi/2,  .5,  0]]\n          a=[...a, [-phi/2, .5,  0]]\n          a=a.map(q=>{\n            X=q[0], Y=q[1], Z=q[2]\n            switch(i){\n              case 0: R(Math.PI/2,0,0); break\n              case 1: R(Math.PI/2,Math.PI/2,Math.PI/2); break\n              case 2: R(0,0,Math.PI/2); break\n            }\n            return [X,Y,Z]\n          })\n          return a\n        })\n        facets=[[[0,0], [2,2], [0,3]],[[1,2], [2,2], [0,3]],[[1,2], [2,2], [2,1]],[[1,2], [0,2], [2,1]],[[2,1], [0,1], [1,3]],[[2,1], [2,2], [1,3]],[[2,1], [0,1], [0,2]],[[1,2], [1,1], [0,2]],[[0,2], [0,1], [2,0]],[[0,2], [2,0], [1,1]],[[2,3], [2,0], [1,1]],[[2,3], [2,0], [1,0]],[[0,1], [2,0], [1,0]],[[0,1], [1,3], [1,0]],[[0,0], [1,3], [1,0]],[[0,0], [2,3], [1,0]],[[0,0], [2,3], [0,3]],[[1,1], [2,3], [0,3]],[[1,1], [1,2], [0,3]],[[0,0], [2,2], [1,3]]]\n\n        shp=[]\n        facets.map(n=>{\n          a=[]\n          n.map(q=>{\n            v=rects[q[0]][q[1]]\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            a=[...a, [X,Y,Z]]\n          })\n          shp=[...shp, a]\n        })\n\n        subdivide = () =>{\n          subdivisions=[]\n          new_shp=[]\n          shp.map((v,i,a)=>{\n            a=[]\n            v.map((q,j)=>{\n              X1=q[0]\n              Y1=q[1]\n              Z1=q[2]\n              X2=v[l=(j+1)%3][0]\n              Y2=v[l][1]\n              Z2=v[l][2]\n              mx=(X1+X2)/2\n              my=(Y1+Y2)/2\n              mz=(Z1+Z2)/2\n              a=[...a, [mx,my,mz]]\n            })\n            subdivisions=[...subdivisions, a]\n            v.map((q,j)=>{\n              b=[]\n              for(m=1;m--;){\n                b=[...b, [...v[(j+1)%3]], [...a[(m+j)%3]], [...a[(m+j+1)%3]]]\n              }\n              subdivisions=[...subdivisions, b]\n            })\n          })\n          shp=[...new_shp, ...subdivisions]          \n        }\n\n        subdivisions=3\n        for(let m = subdivisions; m--;)subdivide()\n        base_shp=JSON.parse(JSON.stringify(shp))\n\n        expansion=10+10*S(t*2)\n        ls=.1/(20+expansion)*270\n        shps=[]\n        shps=[...shps, ((base_shp.map(v=>{\n          v=v.map(q=>{\n            X1=q[0]\n            Y1=q[1]\n            Z1=q[2]\n            d=Math.hypot(X1,Y1,Z1)\n            X2=X1/d\n            Y2=Y1/d\n            Z2=Z1/d\n            X=(X2*expansion+(X1*(1-expansion)))*ls\n            Y=(Y2*expansion+(Y1*(1-expansion)))*ls\n            Z=(Z2*expansion+(Z1*(1-expansion)))*ls\n            return [X,Y,Z]\n          })\n          return v\n        })))]\n        expansion=S(t*4)*1-2\n        ls=1.5\n        shps=[...shps, ((base_shp.map(v=>{\n          v=v.map(q=>{\n            X1=q[0]\n            Y1=q[1]\n            Z1=q[2]\n            d=Math.hypot(X1,Y1,Z1)\n            X2=X1/d\n            Y2=Y1/d\n            Z2=Z1/d\n            X=(X2*expansion+(X1*(1-expansion)))*ls\n            Y=(Y2*expansion+(Y1*(1-expansion)))*ls\n            Z=(Z2*expansion+(Z1*(1-expansion)))*ls\n            return [X,Y,Z]\n          })\n          return v\n        })))]\n\n      }\n\n\n      x.fillStyle=\'#000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'butt\'\n      Rl=0,Pt=-4,Yw=t\n      oX=0,oY=0,oZ=3.5\n\n\n      shps.map(shp=>{\n       shp.map(n=>{\n          x.beginPath()\n          ax=ay=az=0\n          n.map(q=>{\n            v=q\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            ax+=X\n            ay+=Y\n            az+=Z\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n          })\n          ax/=n.length\n          ay/=n.length\n          az/=n.length\n          x.closePath()\n          x.lineWidth=70/(Z**1.5)\n          x.strokeStyle=`hsla(${(l=H(ax,ay,az)*200)*1-t*200},99%,${100-l**3.5/80000000}%,.2)`\n          x.stroke()\n          x.lineWidth/=5\n          x.lineWidth|=0\n          x.strokeStyle=\'#fff3\'\n          //x.stroke()\n          //x.fillStyle=`hsla(${(l=H(ax,ay,az)*200)*2-t*200},99%,${100-l**3.5/100000000}%,.1)`\n          //x.fill()\n        })\n      })\n\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'icosahedron from golden rectangles', 145, 'whitehot robot', '2022-07-12 17:35:19', '[600304,600253,600252,600251,600248,600247]', 101, 'https://code.dweet.net/thumbs/7c05c842e606df27dd89201a5bec7c9a.jpg', 0, 0),
(600306, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n\n        for(a=[1,1],i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]]\n        phi = a[l+1]/a[l]\n\n        rects=Array(3).fill().map((v,i)=>{\n          a=[]\n          a=[...a, [-phi/2, -.5, 0]]\n          a=[...a, [phi/2,  -.5, 0]]\n          a=[...a, [phi/2,  .5,  0]]\n          a=[...a, [-phi/2, .5,  0]]\n          a=a.map(q=>{\n            X=q[0], Y=q[1], Z=q[2]\n            switch(i){\n              case 0: R(Math.PI/2,0,0); break\n              case 1: R(Math.PI/2,Math.PI/2,Math.PI/2); break\n              case 2: R(0,0,Math.PI/2); break\n            }\n            return [X,Y,Z]\n          })\n          return a\n        })\n        facets=[[[0,0], [2,2], [0,3]],[[1,2], [2,2], [0,3]],[[1,2], [2,2], [2,1]],[[1,2], [0,2], [2,1]],[[2,1], [0,1], [1,3]],[[2,1], [2,2], [1,3]],[[2,1], [0,1], [0,2]],[[1,2], [1,1], [0,2]],[[0,2], [0,1], [2,0]],[[0,2], [2,0], [1,1]],[[2,3], [2,0], [1,1]],[[2,3], [2,0], [1,0]],[[0,1], [2,0], [1,0]],[[0,1], [1,3], [1,0]],[[0,0], [1,3], [1,0]],[[0,0], [2,3], [1,0]],[[0,0], [2,3], [0,3]],[[1,1], [2,3], [0,3]],[[1,1], [1,2], [0,3]],[[0,0], [2,2], [1,3]]]\n\n        shp=[]\n        facets.map(n=>{\n          a=[]\n          n.map(q=>{\n            v=rects[q[0]][q[1]]\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            a=[...a, [X,Y,Z]]\n          })\n          shp=[...shp, a]\n        })\n\n        subdivide = () =>{\n          subdivisions=[]\n          new_shp=[]\n          shp.map((v,i,a)=>{\n            a=[]\n            v.map((q,j)=>{\n              X1=q[0]\n              Y1=q[1]\n              Z1=q[2]\n              X2=v[l=(j+1)%3][0]\n              Y2=v[l][1]\n              Z2=v[l][2]\n              mx=(X1+X2)/2\n              my=(Y1+Y2)/2\n              mz=(Z1+Z2)/2\n              a=[...a, [mx,my,mz]]\n            })\n            subdivisions=[...subdivisions, a]\n            v.map((q,j)=>{\n              b=[]\n              for(m=1;m--;){\n                b=[...b, [...v[(j+1)%3]], [...a[(m+j)%3]], [...a[(m+j+1)%3]]]\n              }\n              subdivisions=[...subdivisions, b]\n            })\n          })\n          shp=[...new_shp, ...subdivisions]          \n        }\n\n        subdivisions=3\n        for(let m = subdivisions; m--;)subdivide()\n        base_shp=JSON.parse(JSON.stringify(shp))\n\n        bg=new Image()\n        go=false\n        bg.onload=()=>{\n          go=true\n        }\n        bg.src=\'/proxy.php?url=https://srmcgann.github.io/assets/1Bjk.jpg\'\n      }\n      expansion=50+53*S(t*4)\n      ls=.11/(6+expansion)*200\n      shps=[]\n      shps=[...shps, ((base_shp.map(v=>{\n        v=v.map(q=>{\n          X1=q[0]\n          Y1=q[1]\n          Z1=q[2]\n          d=Math.hypot(X1,Y1,Z1)\n          X2=X1/d\n          Y2=Y1/d\n          Z2=Z1/d\n          X=(X2*expansion+(X1*(1-expansion)))*ls\n          Y=(Y2*expansion+(Y1*(1-expansion)))*ls\n          Z=(Z2*expansion+(Z1*(1-expansion)))*ls\n          return [X,Y,Z]\n        })\n        return v\n      })))]\n\n      if(go){\n        x.globalAlpha=.07\n        x.drawImage(bg,0,0,c.width,c.height)\n        x.globalAlpha=1\n        x.fillStyle=\'#0003\'\n        x.fillRect(0,0,c.width,c.height)\n      } else {\n        x.fillStyle=\'#000\'\n        x.fillRect(0,0,c.width,c.height)\n      }\n      x.lineJoin=x.lineCap=\'butt\'\n      Rl=t/3,Pt=-t,Yw=S(t)*3\n      oX=0,oY=0,oZ=10.5\n\n\n      shps.map(shp=>{\n       shp.map(n=>{\n          x.beginPath()\n          ax=ay=az=0\n          n.map(q=>{\n            v=q\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            ax+=X\n            ay+=Y\n            az+=Z\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n          })\n          ax/=n.length\n          ay/=n.length\n          az/=n.length\n          x.closePath()\n          x.lineWidth=600/(Z**1.5)\n          //x.strokeStyle=`hsla(${(l=H(ax,ay,az)*200)*3-t*200},99%,${100-l**3.5/60000000}%,.2)`\n          //x.stroke()\n          x.lineWidth/=5\n          x.lineWidth|=0\n          x.strokeStyle=\'#fff4\'\n          x.stroke()\n          x.fillStyle=`hsla(${(l=H(ax,ay,az)*200)/2-t*300},${-1000+S(t)*1100}%,${Math.max(20, 120-(l/1.5)**3/1100000)}%,.3)`\n          x.fill()\n        })\n      })\n\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'icosahedron 2', 145, 'whitehot robot', '2022-07-12 22:16:59', '[600305,600304,600253,600252,600251,600248,600247]', 60, '', 0, 1),
