(600308, '', '      c=document.querySelector(\'#c\')\n      x=c.getContext(\'2d\')\n      S=Math.sin\n      C=Math.cos\n      Rn=Math.random\n      t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n          buffer.width=c.width,\n          buffer.height=c.height\n        },0)\n      }\n      rsz()\n\n      Draw=()=>{\n\n        if(!t){\n          R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n          Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n          for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n\n          buffer = c.cloneNode()\n          buffer.width=1920\n          buffer.height=1080\n          bctx=buffer.getContext(\'2d\')\n\n          renderText = (txt, ls, resolution, br) => {\n            bctx.fillStyle=\'#000\'\n            bctx.fillRect(0, 0, buffer.width, buffer.height)\n            let rw=1\n            let fs=1200/(2+txt.length**.52/1.6)\n            let tw=0\n            bctx.font=fs+\'px courier\'\n            bctx.strokeStyle=\'#fff\'\n            bctx.fillStyle=\'#fff\'\n            let a=[], spc, ct=0, trw=0\n            spc=fs/2\n            txt.split(\' \').map((v,i,b)=>{\n              tw+=spc+bctx.measureText(v).width\n              ct+=2\n              if(tw+(i<txt.length?bctx.measureText(b[i+1]).width:0)>buffer.width/1.35){\n                trw++\n                a=[...a, [tw, ct-1]]\n                tw=ct=0\n              }\n            })\n            a=[...a, [tw, ct-1]]\n            tw=0\n            let tw2=0\n            bctx.lineWidth=20/(1+trw)\n            txt.split(\' \').map((v,i,b)=>{\n              if(rw<a.length+1){\n                bctx.fillText(v, tw2, fs*rw*(.9+1/(1+trw)))\n                bctx.strokeText(v, tw2, fs*rw*(.9+1/(1+trw)))\n                spc=(c.width*1.05-a[rw-1][0])/(a[rw-1][1]/2)\n                tw+=(fs/2)+bctx.measureText(v).width\n                tw2+=spc+bctx.measureText(v).width\n                if(tw+(i<txt.length?bctx.measureText(b[i+1]).width:0)>buffer.width/1.35) tw=tw2=0, rw++\n              }\n            })\n            let data = bctx.getImageData(0,0,buffer.width,buffer.height)\n            a=[]\n            for(i=0;i<data.data.length;i+=4){\n              j=i/4|0\n              X=j%buffer.width\n              Y=j/buffer.width|0\n              tx=X/resolution\n              ty=Y/resolution\n              if(!(tx-(tx|0)) && !(ty-(ty|0))){\n                let l     = data.data\n                let red   = l[i+0]\n                let green = l[i+1]\n                let blue  = l[i+2]\n                if((red+green+blue)/3>128) a=[...a, [X/buffer.width*ls, Y/buffer.height*ls, 0,0,0,0,X/buffer.width*ls, Y/buffer.height*ls, 0]]\n              }\n            }\n            let minx=6e6\n            let maxx=-6e6\n            let miny=6e6\n            let maxy=-6e6\n            a.map(v=>{\n              if(v[0]<minx)minx=v[0]\n              if(v[0]>maxx)maxx=v[0]\n              if(v[1]<miny)miny=v[1]\n              if(v[1]>maxy)maxy=v[1]\n            })\n            ax=-(maxx-minx)/2\n            ay=-(3/(1+txt.length/3))-(maxy-miny)/2\n            a.map(v=>{\n              v[0]+=ax\n              v[1]+=ay\n              v[6]+=ax\n              v[7]+=ay\n            })\n            let b = []\n            for(let m=br;m--;){\n              a.map(v=>{\n                b=[...b, [\n                            v[0],\n                            v[1],\n                            v[2]-br/2*sp+m*sp,\n                            v[3],\n                            v[4],\n                            v[5],\n                            v[6],\n                            v[7],\n                            v[8]-br/2*sp+m*sp\n                          ]]\n              })\n            }\n            return b\n          }\n          P=[]\n\n          text=\'a day in the life a day in the life a day in the life a day in the life a day in the life a day in the life a day in the life\'\n          console.log(text)\n\n          br=4/(1+text.length/200)|0, sp=3, iBc=3, iBv=.55, G=20, iBs=1.3\n          res=7+(20/(1+text.length/10))|0\n          setTimeout(()=>{P = renderText(text, 10, res, br)},0)\n\n          B=Array(iBc).fill().map(v=>{\n            X=(Rn()-.5)*G\n            Y=(Rn()-.5)*G\n            Z=(Rn()-.5)*G\n            vx=(Rn()-.5)*iBv\n            vy=(Rn()-.5)*iBv\n            vz=(Rn()-.5)*iBv\n            return [X,Y,Z,vx,vy,vz]\n          })\n          ball = new Image()\n          ball.src = \'/proxy.php?url=https://srmcgann.github.io/assets/SipMv.png\'\n          go=false\n          bg=new Image()\n          bg.onload=()=>{\n            go=true\n          }\n          bg.src=\'/proxy.php?url=https://srmcgann.github.io/assets/2h9kBr.jpg\'\n        }\n\n        if(go){\n          x.globalAlpha=.2\n          x.drawImage(bg,0,0,c.width,c.height)\n          x.globalAlpha=1\n          x.fillStyle=\'#0003\'\n          x.fillRect(0,0,c.width,c.height)\n        } else {\n          x.clearRect(0, 0, c.width, c.height)\n          x.fillStyle=\'#0008\'\n          x.fillRect(0,0,c.width,c.height)\n        }\n        x.lineJoin=x.lineCap=\'round\'\n        Rl=C(t/2)/4,Pt=0,Yw=S(t)/2\n        oX=0,oY=-1,oZ=14\n\n        iGa=x.globalAlpha\n        x.globalAlpha=.65\n        B.map((v,i)=>{\n          d=Math.hypot(v[0],v[1],v[2])\n          cx=v[0]/d*iBv\n          cy=v[1]/d*iBv\n          cz=v[2]/d*iBv\n          X=v[0]+=v[3]-=cx/60\n          Y=v[1]+=v[4]-=cy/60\n          Z=v[2]+=v[5]-=cz/60\n          v[3]/=1.03\n          v[4]/=1.03\n          v[5]/=1.03\n          v[3]+=(Rn()-.5)*iBv/20\n          v[4]+=(Rn()-.5)*iBv/20\n          v[5]+=(Rn()-.5)*iBv/20\n          d=Math.hypot(v[3],v[4],v[5])\n          v[3]*=1+(iBv-d)/9\n          v[4]*=1+(iBv-d)/9\n          v[5]*=1+(iBv-d)/9\n          B.map((q,j)=>{\n            tx=q[0]\n            ty=q[1]\n            tz=q[2]\n            if(j!=i && (d=Math.hypot(mx=tx-X,my=ty-Y,mz=tz-Z))<iBs*4){\n              v[0]=tx-mx/d*iBs*4\n              v[1]=ty-my/d*iBs*4\n              v[2]=tz-mz/d*iBs*4\n              q[0]=X+mx/d*iBs*4\n              q[1]=Y+my/d*iBs*4\n              q[2]=Z+mz/d*iBs*4\n              v[3]-=mx/30\n              v[4]-=my/30\n              v[5]-=mz/30\n              q[3]+=mx/30\n              q[4]+=my/30\n              q[5]+=mz/30\n            }\n          })\n          R(Rl,Pt,Yw,1)\n          if(Z>0){\n            l=Q()\n            s=iBs*3500/Z\n            x.drawImage(ball, l[0]-s/2, l[1]-s/2, s, s)\n          }\n        })\n        x.globalAlpha=iGa\n\n        P.map(v=>{\n          v[3]+=(v[6]-v[0])/300\n          v[4]+=(v[7]-v[1])/300\n          v[5]+=(v[8]-v[2])/300\n          v[3]/=1.04\n          v[4]/=1.04\n          v[5]/=1.04\n          X=v[0]+=v[3]\n          Y=v[1]+=v[4]\n          Z=v[2]+=v[5]\n          B.map(q=>{\n            tx=q[0]\n            ty=q[1]\n            tz=q[2]\n            if((d=H(mx=tx-v[0],my=ty-v[1],mz=tz-v[2]))<iBs*2){\n              v[0]=tx-mx/d*iBs*2\n              v[1]=ty-my/d*iBs*2\n              v[2]=tz-mz/d*iBs*2\n              v[3]-=mx/16\n              v[4]-=my/16\n              v[5]-=mz/16\n            }\n          })\n          R(Rl, Pt, Yw, 1)\n          x.fillStyle=\'#fff1\'\n          s=Math.min(500, 600/(Z**1.5))\n          l=Q()\n          x.fillRect(l[0]-s/2, l[1]-s/2, s, s)\n          s/=5\n          x.fillStyle=\'#fffc\'\n          x.fillRect(l[0]-s/2, l[1]-s/2, s, s)\n        })\n\n        t+=1/60\n        requestAnimationFrame(Draw)\n      }\n      Draw()\n', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'text collisions', 145, 'whitehot robot', '2022-07-13 17:20:31', '[600304,600253,600252,600251,600248,600247]', 91, '', 0, 0),
