(600311, 'https://srmcgann.github.io/assets/1Nsrqv.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    t=playing=0\n    window.onclick=()=>{if(!playing)mp3.play()}\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        focal=900\n        mp3 = new Audio()\n        mp3.loop=true\n        mp3.onplaying=()=>{playing=true}\n        mp3.oncanplay=()=>{go=true;if(!playing)mp3.play()}\n        mp3.src=\'https://audiocloud.rotoblaster.com/audio/a3c3c799a4ef5aaaa12f09152b775145.MP3\'\n        R=($1,$2,$3,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=ogx+S(p=A(ogx-X,ogz-Z)+Yw)*(d=H(ogx-X,ogz-Z))\n          Z=ogz+C(p)*d\n          Y=ogy+S(p=A(ogy-Y,ogz-Z)+Pt)*(d=H(ogy-Y,ogz-Z))\n          Z=ogz+C(p)*d\n          X=ogx+S(p=A(ogx-X,ogy-Y)+Rl)*(d=H(ogx-X,ogy-Y))\n          Y=ogy+C(p)*d\n          if(m)X+=oX,Y+=oY,Z+=oZ\n        }\n        Q=()=>[c.width/2+X/Z*focal,c.height/2+Y/Z*focal]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n        DC=(tx, ty, tz, fillColor, strokeColor, scalex, scaley, scalez)=>{\n          CB.map((v,i)=>{\n            if(!(i%4))x.beginPath()\n            X=v[0]*scalex+tx\n            Y=v[1]*scaley-(2**.5*scaley/2)+ty\n            Z=v[2]*scalez+tz\n            R(Rl,Pt,Yw,1)\n            if(Z>0)x.lineTo(...Q())\n            if(i%4==3){\n              x.closePath()\n              x.strokeStyle=strokeColor\n              x.lineWidth=1+Math.min(400, 5000/(Z))\n              x.lineWidth/=5\n              x.stroke()\n              x.fillStyle=fillColor\n              x.fill()\n            }\n          })\n        }\n        rw=1,cl=16,br=16,sp=2**.5*256, G=2000\n        B=Array(rw*cl*br).fill().map((v,i)=>{\n          X=((i%cl)-cl/2+.5)*sp\n          Y=(((i/cl|0)%rw)-rw/2+.5)*sp\n          Z=(((i/cl/rw|0)%br)-br/2+.5)*sp\n          return [X,Y,Z,0]\n        })\n        toX=0,toY=0,toZ=2000\n        moX=0,moY=0,moZ=40\n      }\n\n      toX=0,toY=0,toZ=2000+S(t)*1000\n\n      x.fillStyle=\'#0008\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'butt\'\n      Rl=0,Pt=.6+C(t/1.5-1)/1.7,Yw=-C(t/6+.1)*12\n\n      curIdx=(t*60|0)%B.length\n\n      B.map((v,i)=>{\n        X=v[0], Y=v[1], Z=v[2]\n        if(i==curIdx){\n          fx=X, fy=Y, fz=Z\n        }\n      })\n      \n      if((t|0)%8<4)fx=fy=fz=0\n\n      perspective=(l=1.5)+S(t*1.5)*(l-.25)+.25\n      focal=900*(1/perspective)\n      offsetZ=-toZ*(1-1/perspective)\n\n      oX=toX-fx\n      oY=toY-fy\n      oZ=toZ-fz+offsetZ\n      ogx=fx\n      ogy=fy\n      ogz=fz\n\n      strokeColor = \'#eee3\'\n      B.map((v,i)=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        v[3]/=1.2\n        if(i==curIdx){\n          v[3]+=100\n        }\n        fillColor = `hsla(${i+t*500},99%,${Math.max(40,v[3])}%,${.02+v[3]/100})`\n        DC(X, Y, Z, fillColor, strokeColor, 4+(i**3.1)%100, 2+(i**4.7)%256,4+(i**2.1)%100)\n      })\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'perspective warper', 145, 'whitehot robot', '2022-07-14 17:49:10', '[600304,600253,600252,600251,600248,600247]', 123, 'https://code.dweet.net/thumbs/61869f22e36e651e8c91a5ba801d1c2f.jpg', 8, 0),
(600312, 'https://srmcgann.github.io/assets/1NUWyP.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/D0lLF.gif);\n  background-size: 100% 100%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'brain blaster', 145, 'whitehot robot', '2022-07-15 01:40:46', '[600288,600253,600252,600251,600248,600247]', 86, 'https://code.dweet.net/thumbs/b5e48ad58e834186e307ec32ba1afa8b.jpg', 0, 0),
(600313, 'https://srmcgann.github.io/assets/fN2R1.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/25azdo.gif);\n  background-size: 100% 100%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'the eye', 145, 'whitehot robot', '2022-07-15 02:53:18', '[600312,600288,600253,600252,600251,600248,600247]', 95, 'https://code.dweet.net/thumbs/55e9f3646811acbe49a8144dd9f6191a.jpg', 0, 0),
(600314, 'https://srmcgann.github.io/assets/1CbyRp.mp4', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    mx=my=bx=by=0\n    designing=1\n    \n    mode=1\n    window.onmousemove=e=>{\n      mtimer=0\n      let rect = c.getBoundingClientRect()\n      mx=(e.pageX-(rect.left+2))/(c.clientWidth)*c.width\n      my=(e.pageY-(rect.top+2))/(c.clientHeight)*c.height\n    }\n    window.ontouchmove=e=>{\n      mtimer=0\n      let rect = c.getBoundingClientRect()\n      e=(l=e.originalEvent.touches[0])?l:e\n      mx=(l.pageX-(rect.left+2))/(c.clientWidth)*c.width\n      my=(l.pageY-(rect.top+2))/(c.clientHeight)*c.height\n    }\n    window.onkeypress=e=>{\n      console.log(e.keyCode)\n      if(e.keyCode==107) designing = !designing\n      if(e.keyCode==49){1\n        drawMode=0\n        B.map(v=>v[3]=false)\n      }\n      if(e.keyCode==50){\n        drawMode=1\n        B.map(v=>v[3]=false)\n      }\n    }\n    vl=0\n    button=buttonToggle=false\n    window.onmousedown=e=>{\n      if(e.button==0)button=true\n      let rect = c.getBoundingClientRect()\n      mx=(e.pageX-(rect.left+2))/(c.clientWidth)*c.width\n      my=(e.pageY-(rect.top+2))/(c.clientHeight)*c.height\n      bx=mx\n      by=my\n    }\n    window.ontouchstart=e=>{\n      button=true\n      let rect = c.getBoundingClientRect()\n      e=(l=e.originalEvent.touches[0])?l:e\n      mx=(l.pageX-(rect.left+2))/(c.clientWidth)*c.width\n      my=(l.pageY-(rect.top+2))/(c.clientHeight)*c.height\n      bx=mx\n      by=my\n    }\n    window.onmouseup=e=>{\n      if(drawMode==1){\n        B.map(v=>{\n          v[5]=v[4]=v[3]\n        })\n      }\n      setTimeout(()=>{\n        B.map(v=>v[3]=false)\n      },0)\n      buttonToggle=curCell=false\n      if(e.button==0)button=false\n    }\n    window.ontouchend=e=>{\n      buttonToggle=curCell=false\n      button=false\n    }\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n  \n    rw=80,cl=80,sp=1\n    drawMode=1\n    B=Array(rw*cl).fill().map((v,i)=>{\n      X=((i%cl)-cl/2+.5)*sp\n      Y=((i/cl|0)-rw/2+.5)*sp\n      Z=0\n      return [X, Y, Z, 0, 0, 0]\n    })\n  }\n\n  if(button){\n    c.style.cursor=\'none\'\n  } else {\n    c.style.cursor=\'crosshair\'\n  }\n  \n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n  \n  if(designing){\n  x.lineJoin=x.lineCap=\'round\'\n\n    Rl=0,Pt=0,Yw=0\n    oX=0,oY=0,oZ=30\n\n    x.fillStyle=\'#f00\'\n    s=5, brushsize=5\n    x.fillRect(mx-s/2,my-s/2,s,s)\n\n    B.map((v,i)=>{\n      X=v[0]\n      Y=v[1]\n      Z=v[2]\n      R(Rl,Pt,Yw,1)\n      s=Math.min(2000, 900/Z)\n      l=Q()\n      switch(drawMode){\n        case 0:\n          if(!button) v[3]=v[5]\n          if(mx>l[0]-s/2 && mx <l[0]+s/2 && my>l[1]-s/2 && my<l[1]+s/2){\n            v[3]=1\n            if(button && (!buttonToggle || curCell != i)){\n              if(!buttonToggle) mode = !v[5]\n              if(mode){\n                v[4]=v[5]=mode\n              } else {\n                B.map((q,j)=>{\n                  q[3]=0\n                  if((d=Math.hypot(v[0]-q[0],v[1]-q[1]))<brushsize){\n                    q[3]=1\n                    v[4]=v[5]=q[4]=q[5]=0\n                  }\n                })\n              }\n              buttonToggle=true\n              curCell=i\n            }\n          }\n          x.fillStyle=\'#0000\'\n          if(v[3]){\n            x.fillStyle=\'#6ff8\'\n          }\n          if(v[4] || v[5]){\n            x.fillStyle=\'#4f8\'\n          }\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        break\n        case 1:\n          if(button){\n            if(mx>l[0]-s/2 && mx <l[0]+s/2 && my>l[1]-s/2 && my<l[1]+s/2 && !buttonToggle){\n              mode = !v[4], buttonToggle=true\n            }\n            if(buttonToggle){\n              v[3]=v[5]\n              for(j=4;j--;){\n                switch(j){\n                  case 0:\n                    X1=l[0]-s/2\n                    Y1=l[1]-s/2\n                    X2=l[0]+s/2\n                    Y2=l[1]-s/2\n                  break\n                  case 1:\n                    X1=l[0]+s/2\n                    Y1=l[1]-s/2\n                    X2=l[0]+s/2\n                    Y2=l[1]+s/2\n                  break\n                  case 2:\n                    X1=l[0]+s/2\n                    Y1=l[1]+s/2\n                    X2=l[0]-s/2\n                    Y2=l[1]+s/2\n                  break\n                  case 3:\n                    X1=l[0]-s/2\n                    Y1=l[1]+s/2\n                    X2=l[0]-s/2\n                    Y2=l[1]-s/2\n                 break\n                }\n                X3=bx,Y3=by,X4=mx,Y4=my\n                if(I(X1,Y1,X2,Y2,X3,Y3,X4,Y4)) v[3] = mode\n              }\n            }\n          }\n          if(v[5]){\n            x.fillStyle=\'#4f8\'\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          }\n          if(v[3] || (mode && v[4])){\n            if(!v[4]){\n              x.fillStyle=mode&&v[4]?\'#000\':\'#4fc8\'\n              x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n            }\n          }\n          if(!mode){\n            if(v[3]&&v[4]){\n              x.fillStyle=\'#246\'\n              x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n            }\n          }\n        break\n      }\n      x.strokeStyle=\'#4fc2\'\n      x.lineWidth=4\n      x.strokeRect(l[0]-s/2,l[1]-s/2,s,s)\n    })\n  } else {  //preview mode\n    Rl=0,Pt=-.1,Yw=t\n    oX=0,oY=1,oZ=60\n    B.map(v=>{\n      tx=v[0]*2**.5\n      ty=v[1]*2**.5\n      tz=v[2]*2**.5\n      for(let m=4;m--;){\n        X=tx+S(p=Math.PI*2/4*m+Math.PI/4)*(d=2**.5/2)\n        Z=tx+S(p)*d\n        y=d\n      }\n      if(v[4]){\n        CB.map((q,j)=>{\n          X=q[0]+tx\n          Z=q[1]+ty\n          Y=q[2]+tz\n          if(!(j%4)) x.beginPath()\n          R(0,0,Yw,0)\n          R(Rl,Pt,0,1)\n          if(Z>0) x.lineTo(...Q())\n          if(j%4==3){\n            x.closePath()\n            x.lineWidth=Math.min(100, 100/Z)\n            x.strokeStyle=\'#fff4\'\n            x.fillStyle=\'#fff1\'\n            x.stroke()\n            x.fill()\n          }\n        })\n      }\n    })\n  }\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  cursor: crosshair;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'level designer (unfinished)', 145, 'whitehot robot', '2022-07-15 20:14:55', '[600304,600253,600252,600251,600248,600247]', 63, 'https://code.dweet.net/thumbs/2f396fae79422cd4599aa4d17bde5f80.jpg', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600316, 'https://srmcgann.github.io/assets/AI6QY.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n\n        genTexture = async (file, factor, size) => {\n          let img = new Image()\n          img.onload=()=>{\n            buffer=document.createElement(\'canvas\')\n            ctx=buffer.getContext(\'2d\')\n            buffer.width=img.width\n            buffer.height=img.height\n            ctx.drawImage(img,0,0,buffer.width,buffer.height)\n            data=ctx.getImageData(0,0,buffer.width,buffer.height)\n            B = []\n            let l = data.data\n            let w = ((8/4|0)%buffer.width)-((4/4|0)%buffer.width)\n            for(i=0;i<l.length;i+=4){\n              let X = ((i/4|0)%buffer.width)-buffer.width/2|0\n              let Y = ((i/4|0)/buffer.width|0)-buffer.height/2|0\n              if(!(X%(buffer.width/factor|0)) && !(Y%(buffer.width/factor|0))){\n                let red    = l[i+0]\n                let green  = l[i+1]\n                let blue   = l[i+2]\n                let alpha  = l[i+3]\n                if(alpha>5) B=[...B, [X/buffer.width*size, Y/buffer.width*size, 0, buffer.width/factor/buffer.width/2.5*size, red, green, blue, alpha]]\n              }\n            }\n          }\n          img.src=\'/proxy.php?url=\' + file\n          go=false\n          bg=document.createElement(\'video\')\n          bg.oncanplay=()=>{\n            bg.play()\n            go=true\n          }\n          bg.muted=true\n          bg.loop=true\n          bg.src=\'/proxy.php?url=https://srmcgann.github.io/assets/X6dja.mp4\'\n        }\n\n        B=[]\n        genTexture(\'https://srmcgann.github.io/assets/11QvzP.png\', 24, 6)\n        sphereSize=2\n        flap=j=>{\n          Z-=sphereSize\n          d=Math.hypot(X, Y, Z)\n          X/=d\n          Y/=d\n          Z/=d\n          X=X*sphereSize\n          Y=Y*sphereSize\n          Z=Z*sphereSize\n          //R(0,0,(X>0?1:-1)*S(t*24+j)*1.5)\n          R(S(j)*10+t*12,S(j)-t*6,t+j)\n        }\n        iPc=12, G=40, iPv=.6\n        P=Array(iPc).fill().map(v=>{\n          X=(Rn()-.5)*G\n          Y=(Rn()-.5)*G\n          Z=(Rn()-.0)*G\n          vx=(Rn()-.5)*iPv\n          vy=(Rn()-.5)*iPv\n          vz=(Rn()-.5)*iPv\n          return [X,Y,Z,vx,vy,vz]\n        })\n        Sphere=(ls,cl,rw)=>{\n          let X,Y,Z\n          let ret=[]\n          for(i=cl*rw;i--;){\n            a=[]\n            j=i%cl\n            k=(i/cl|0)\n            l=(j+1)%cl\n            \n            X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*k)*ls\n            Y=C(q)*ls\n            Z=C(p)*S(q)*ls\n            a=[...a,[X,Y,Z]]\n            X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*k)*ls\n            Y=C(q)*ls\n            Z=C(p)*S(q)*ls\n            a=[...a,[X,Y,Z]]\n            X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*(k+1))*ls\n            Y=C(q)*ls\n            Z=C(p)*S(q)*ls\n            a=[...a,[X,Y,Z]]\n            X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*(k+1))*ls\n            Y=C(q)*ls\n            Z=C(p)*S(q)*ls\n            a=[...a,[X,Y,Z]]\n            \n            ret = [...ret, a]\n          }\n          return ret\n        }\n\n\n        DrawSolid=(dod, sx, sy, sz, rl, pt, yw, strokeStyle, fillStyle, useFill, globalAlpha, wireframe) => {\n          if(wireframe){\n            dod.map((v,i)=>{\n              if(v.length){\n                if(wireframe) x.beginPath()\n                v.map((q,j)=>{\n                  if(q.length){\n                    X=q[0]\n                    Y=q[1]\n                    Z=q[2]\n                    //R2(rl,pt,yw,0)\n                    R(Rl,Pt,Yw,1)\n                    X+=sx\n                    Y+=sy\n                    Z+=sz\n                    let l=[...Q(), Z, j, i]\n                    if(Z>0 && wireframe) x.lineTo(...l)\n                  }\n                })\n                if(Z>0 && wireframe){\n                  x.closePath()\n                  x.lineWidth=Math.min(200,500/(Z**1.35))|0\n                  //x.globalAlpha=.3*globalAlpha\n                  //x.strokeStyle=strokeStyle\n                  //x.stroke()\n                  x.lineWidth/=7\n                  x.lineWidth=Math.max(x.lineWidth|0, 1)\n                  x.globalAlpha=1*globalAlpha\n                  x.strokeStyle=strokeStyle\n                  x.stroke()\n                }\n              }\n            })\n          }\n          \n          dod.map((v,i)=>{\n            if(v.length){\n              x.beginPath()\n              v.map((q,j)=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                //R2(rl,pt,yw,0)\n                R(Rl,Pt,Yw,1)\n                X+=sx\n                Y+=sy\n                Z+=sz\n                if(Z>0)x.lineTo(...Q())\n              })\n              x.globalAlpha=globalAlpha\n              x.fillStyle=fillStyle\n              x.fill()\n            }\n          })\n        }\n\n        sphere = Sphere(sphereSize, 10, 6)\n      }\n      x.globalAlpha=1\n      if(go){\n        x.globalAlpha=.5\n        x.drawImage(bg,0,0,c.width,c.height)\n        x.fillStyle=\'#0000\'\n        x.globalAlpha=1\n        x.fillRect(0,0,c.width,c.height)\n      }else{\n        x.fillStyle=\'#0008\'\n        x.fillRect(0,0,c.width,c.height)\n      }\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=2\n\n      if(B.length){\n        s_ar=[]\n        P.map((q,j)=>{\n          X=tx=q[0]+=q[3]\n          Y=ty=q[1]+=q[4]\n          Z=tz=q[2]+=q[5]\n          if(tx<-G/2) q[0]=G/2\n          if(tx>G/2) q[0]=-G/2\n          if(ty<-G/2) q[1]=G/2\n          if(ty>G/2) q[1]=-G/2\n          if(tz<0) q[2]=G\n          if(tz>G) q[2]=0\n          R(Rl,Pt,Yw,1)\n          s_ar=[...s_ar, [j, Math.hypot(X,Y,Z)]]\n        })\n        s_ar.sort((a,b)=>b[1]-a[1])\n        s_ar2=[]\n        B.map((q,j)=>{\n          X=tx=q[0]\n          Y=ty=q[1]\n          Z=tz=q[2]\n          R(Rl,Pt,Yw,1)\n          s_ar2=[...s_ar2, [j, Math.hypot(X,Y,Z)]]\n        })\n        s_ar2.sort((a,b)=>b[1]-a[1])\n        P.map((ln,n,ar)=>{\n          j=s_ar[n][0]\n          q=P[j]\n          X=tx=q[0]\n          Y=ty=q[1]\n          Z=tz=q[2]\n          R(Rl,Pt,Yw,1)\n          if(Z>=.5){\n            x.globalAlpha=1\n            DrawSolid(sphere, tx, ty, tz, 0, 0, 0, \'\', \'#fffc\', 1, 1/(1+tz**14/8e19)*(Z/500**.4), 0)\n            //X=tx=q[0]\n            //Y=ty=q[1]\n            //Z=tz=q[2]\n\n            B.map((m,n)=>{\n              i=s_ar2[n][0]\n              v=B[i]\n              s=v[3]*2.5\n              x.beginPath()\n              X=v[0], Y=v[1], Z=v[2]\n              flap(j)\n              R(Rl,Pt,Yw,1)\n              X+=tx,Y+=ty,Z+=tz\n              //x.globalAlpha=1/(1+tz**14/1e20)*(Z/20**.6)\n              if(Z>0)x.lineTo(...Q())\n              X=v[0]+s, Y=v[1], Z=v[2]\n              flap(j)\n              R(Rl,Pt,Yw,1)\n              X+=tx,Y+=ty,Z+=tz\n              if(Z>0)x.lineTo(...Q())\n              X=v[0]+s, Y=v[1]+s, Z=v[2]\n              flap(j)\n              R(Rl,Pt,Yw,1)\n              X+=tx,Y+=ty,Z+=tz\n              if(Z>0)x.lineTo(...Q())\n              X=v[0], Y=v[1]+s, Z=v[2]\n              flap(j)\n              R(Rl,Pt,Yw,1)\n              X+=tx,Y+=ty,Z+=tz\n              if(Z>0)x.lineTo(...Q())\n              x.closePath()\n              x.fillStyle=`RGBA(${v[4]},${v[5]},${v[6]},${v[7]/255/1.25})`\n              x.fill()\n            })\n          }\n        })\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n  overflow: hidden;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'sea cucumber breakfast', 145, 'whitehot robot', '2022-07-16 22:42:45', '[600304,600253,600252,600251,600248,600247]', 108, 'https://code.dweet.net/thumbs/91aaf9753ca10228e1179b14ce48b5c6.jpg', 0, 0),
(600317, 'https://srmcgann.github.io/assets/ep0PD.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n        img1=new Image()\n        img2=new Image()\n        go1=go2=false\n        img1.onload=()=>{\n          go1=true\n        }\n        img2.onload=()=>{\n          go2=true\n        }\n        img1.src=\'https://srmcgann.github.io/assets/1DHpNC.jpg\'\n        img2.src=\'https://srmcgann.github.io/assets/nqHR5.png\'\n      }\n\n      x.fillStyle=\'#0008\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      if(go1 && go2){\n        x.globalAlpha=1\n        x.drawImage(img1,0,0,c.width,c.height)\n        x.globalAlpha=.5+S(t*4)/2\n        x.fillStyle=\'#000\'\n        x.fillRect(0,0,c.width,c.height)\n        x.drawImage(img2,0,0,c.width,c.height-50)\n\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'ascii wood, if you askii\'d it :D', 145, 'whitehot robot', '2022-07-17 03:11:44', '[600304,600253,600252,600251,600248,600247]', 91, 'https://code.dweet.net/thumbs/9adf33aa8499a9535aec7f95606354c4.jpg', 1, 0),
(600318, 'https://srmcgann.github.io/assets/JGVYQ.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n\n        genTexture = async (file, factor, size) => {\n          let img = new Image()\n          img.onload=()=>{\n            buffer=document.createElement(\'canvas\')\n            ctx=buffer.getContext(\'2d\')\n            buffer.width=img.width\n            buffer.height=img.height\n            ctx.drawImage(img,0,0,buffer.width,buffer.height)\n            data=ctx.getImageData(0,0,buffer.width,buffer.height)\n            B = []\n            let l = data.data\n            let w = ((8/4|0)%buffer.width)-((4/4|0)%buffer.width)\n            for(i=0;i<l.length;i+=4){\n              let X = ((i/4|0)%buffer.width)-buffer.width/2|0\n              let Y = ((i/4|0)/buffer.width|0)-buffer.height/2|0\n              if(!(X%(buffer.width/factor|0)) && !(Y%(buffer.width/factor|0))){\n                let red    = l[i+0]\n                let green  = l[i+1]\n                let blue   = l[i+2]\n                let alpha  = l[i+3]\n                if(alpha>5) B=[...B, [X/buffer.width*size, Y/buffer.width*size, 0, buffer.width/factor/buffer.width/2.5*size, red, green, blue, alpha]]\n              }\n            }\n          }\n          img.src=\'/proxy.php?url=\' + file\n          go=false\n          bg=document.createElement(\'video\')\n          bg.oncanplay=()=>{\n            bg.play()\n            go=true\n          }\n          bg.muted=true\n          bg.loop=true\n          bg.src=\'https://srmcgann.github.io/assets/Vr7g8.mp4\'\n        }\n\n        B=[]\n        genTexture(\'https://srmcgann.github.io/assets/fhhZB.png\',20,10)\n        flap=j=>{\n          R(0,0,(X>0?1:-1)*S(t*24+j)*1.5)\n          R(S(j)*10+t*12,j-t*2,0)\n        }\n        iPc=16, G=60, iPv=2\n        P=Array(iPc).fill().map(v=>{\n          X=(Rn()-.5)*G\n          Y=(Rn()-.5)*G\n          Z=(Rn()-.0)*G\n          vx=(Rn()-.5)*iPv\n          vy=(Rn()-.5)*iPv\n          vz=(Rn()-.5)*iPv\n          return [X,Y,Z,vx,vy,vz]\n        })\n      }\n      if(go){\n        x.globalAlpha=.75\n        x.drawImage(bg,0,0,c.width,c.height)\n        x.fillStyle=\'#0000\'\n        x.globalAlpha=1\n        x.fillRect(0,0,c.width,c.height)\n      }else{\n        x.fillStyle=\'#0008\'\n        x.fillRect(0,0,c.width,c.height)\n      }\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=t/6,Pt=0,Yw=t\n      oX=0,oY=0,oZ=5\n\n      if(B.length){\n        s_ar=[]\n        P.map((q,j)=>{\n          X=tx=q[0]+=q[3]\n          Y=ty=q[1]+=q[4]\n          Z=tz=q[2]+=q[5]\n          if(tx<-G/2) q[0]=G/2\n          if(tx>G/2) q[0]=-G/2\n          if(ty<-G/2) q[1]=G/2\n          if(ty>G/2) q[1]=-G/2\n          if(tz<0) q[2]=G\n          if(tz>G) q[2]=0\n          R(Rl,Pt,Yw,1)\n          s_ar=[...s_ar, [j, Math.hypot(X,Y,Z)]]\n        })\n        s_ar.sort((a,b)=>b[1]-a[1])\n        P.map((ln,n,ar)=>{\n          j=s_ar[n][0]\n          q=P[j]\n          X=tx=q[0]\n          Y=ty=q[1]\n          Z=tz=q[2]\n          if(Z>0){\n            B.map(v=>{\n              s=v[3]*2.5\n              x.beginPath()\n              X=v[0], Y=v[1], Z=v[2]\n              flap(j)\n              R(Rl,Pt,Yw,1)\n              X+=tx,Y+=ty,Z+=tz\n              if(Z>0)x.lineTo(...Q())\n              X=v[0]+s, Y=v[1], Z=v[2]\n              flap(j)\n              R(Rl,Pt,Yw,1)\n              X+=tx,Y+=ty,Z+=tz\n              if(Z>0)x.lineTo(...Q())\n              X=v[0]+s, Y=v[1]+s, Z=v[2]\n              flap(j)\n              R(Rl,Pt,Yw,1)\n              X+=tx,Y+=ty,Z+=tz\n              if(Z>0)x.lineTo(...Q())\n              X=v[0], Y=v[1]+s, Z=v[2]\n              flap(j)\n              R(Rl,Pt,Yw,1)\n              X+=tx,Y+=ty,Z+=tz\n              if(Z>0)x.lineTo(...Q())\n              x.closePath()\n              x.fillStyle=`RGBA(${v[4]},${v[5]},${v[6]},${v[7]/255/1.25})`\n              x.fill()\n            })\n          }\n        })\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n  overflow: hidden;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'butterflies', 145, 'whitehot robot', '2022-07-17 23:56:01', '[600316,600304,600253,600252,600251,600248,600247]', 98, 'https://code.dweet.net/thumbs/ba17221598765f039441b2f59d4c7489.jpg', 0, 0),
