          Y+=sy\n                Z+=sz\n                if(Z>0)x.lineTo(...Q())\n              })\n              x.globalAlpha=globalAlpha\n              x.fillStyle=fillStyle\n              x.fill()\n            }\n          })\n        }\n\n        sphere = Sphere(sphereSize, 10, 6)\n        transformation = \'\'\n      }\n      iPv=-C(t*1.5)*8\n      x.globalAlpha=1\n      if(go){\n        x.globalAlpha=.5\n        x.drawImage(bg,0,0,c.width,c.height)\n        x.fillStyle=\'#0000\'\n        x.globalAlpha=1\n        x.fillRect(0,0,c.width,c.height)\n      }else{\n        x.fillStyle=\'#0008\'\n        x.fillRect(0,0,c.width,c.height)\n      }\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=0\n\n      if(B.length){\n        s_ar=[]\n        P.map((q,j)=>{\n          X=tx=q[0]//+=q[3]\n          Y=ty=q[1]//+=q[4]\n          Z=tz=q[2]+=iPv\n          if(tx<-G/2) q[0]=G/2\n          if(tx>G/2) q[0]=-G/2\n          if(ty<-G/2) q[1]=G/2\n          if(ty>G/2) q[1]=-G/2\n          if(tz<0) q[2]=G\n          if(tz>G) q[2]=0\n          R(Rl,Pt,Yw,1)\n          s_ar=[...s_ar, [j, Math.hypot(X,Y,Z)]]\n        })\n        s_ar.sort((a,b)=>b[1]-a[1])\n        s_ar2=[]\n        B.map((q,j)=>{\n          X=tx=q[0]\n          Y=ty=q[1]\n          Z=tz=q[2]\n          R(Rl,Pt,Yw,1)\n          s_ar2=[...s_ar2, [j, Math.hypot(X,Y,Z)]]\n        })\n        s_ar2.sort((a,b)=>b[1]-a[1])\n        P.map((ln,n,ar)=>{\n          j=s_ar[n][0]\n          q=P[j]\n          X=tx=q[0]\n          Y=ty=q[1]\n          Z=tz=q[2]\n          R(Rl,Pt,Yw,1)\n          if(Z>=.5){\n            x.globalAlpha=1\n            \n            //DrawSolid(sphere, tx, ty, tz, 0, 0, 0, \'\', \'#fffc\', 1, 1/(1+tz**14/8e19)*(Z/500**.4), 0)\n            x.globalAlpha=1/(1+tz**14/8e23)*(Z/500**.4)\n            B.map((m,n)=>{\n              i=s_ar2[n][0]\n              v=B[i]\n              s=v[3]*2.5\n              x.beginPath()\n              X=v[0], Y=v[1], Z=v[2]\n              tran