(600322, 'https://srmcgann.github.io/assets/bQmpK.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n        bg=new Image()\n        bg.onload=()=>{\n          go=true\n        }\n        bg.src=\'https://srmcgann.github.io/assets/1kIeEa.jpg\'\n      }\n      x.fillStyle=\'#0008\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\nc.width=1920/1,c.height=c.width/1.7778|0\nif(go){\n  x.drawImage(bg,0,0,c.width,c.height)\n}else{\n  x.clearRect(0,0,c.width,c.height)\n  x.fillStyle=\'#fff\'}\nh=99,s=c.width/99+1|0\nP=t?P.map((v,i,a)=>{v&&x.fillRect((X=i%h)*s,(Y=i/h|0)*s,s,s);return((v+(a[i>h?i-h:w-h+i]+a[i<w-h?i+h:i-w+h]+a[i?i-1:w-1]+a[i+1])/1.5)|0)%2}):Array(w=5513).fill().map((v,i)=>((i**2.5)|0)%2);\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background-size: 100% 100%;\n  background-color:#fff;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'surface of the void 2', 145, 'whitehot robot', '2022-07-18 23:12:52', '[600321,600304,600253,600252,600251,600248,600247]', 86, 'https://code.dweet.net/thumbs/a98feace6239f293e742016c4c6bafdd.jpg', 0, 0),
(600323, 'https://srmcgann.github.io/assets/bQmpK.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/lk7uL.gif);\n  background-size: 100% 100%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'surface of the void (gif)', 145, 'whitehot robot', '2022-07-18 23:30:10', '[600288,600253,600252,600251,600248,600247]', 33, 'https://code.dweet.net/thumbs/a98feace6239f293e742016c4c6bafdd.jpg', 0, 1);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600324, 'https://srmcgann.github.io/assets/1CbyRp.mp4', '      c=document.querySelector(\'#c\')\n      x=c.getContext(\'2d\')\n      S=Math.sin\n      C=Math.cos\n      Rn=Math.random\n      t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n      Draw=()=>{\n        if(!t){\n          vl=0\n          crosshair=new Image()\n          crosshair.src=\'/proxy.php?url=https://srmcgann.github.io/assets/1oI2JM.png\'\n          showCrosshair=true\n          showFloor=true\n          \n          button=buttonToggle=false\n          \n          Tetrahedron=ls=>{\n            let ret=[]\n            let a = []\n            let theta=1.2217304763960306\n            for(let i=3;i--;){\n              X=S(p=Math.PI*2/3*i)\n              Y=C(p)+.5\n              Z=0\n              R(0,-theta/2,0)\n              a=[...a, [X,Y,Z]]\n            }\n            ret=[...ret, a]\n            b=JSON.parse(JSON.stringify(a))\n            ax=ay=az=0\n            b.map(v=>{\n              X=v[0]\n              Y=v[1]\n              Z=v[2]\n              R(0,theta,0)\n              v[0]=X\n              v[1]=Y\n              v[2]=Z\n            })\n            ret=[...ret, b]\n            ct=0\n            ret.map(v=>{\n              v.map(q=>{\n                ax+=q[0]\n                ay+=q[1]\n                az+=q[2]\n                ct++\n              })\n            })\n            ax/=ct\n            ay/=ct\n            az/=ct\n            ret.map(v=>{\n              v.map(q=>{\n                q[0]-=ax*1.5\n                q[1]-=ay*1.5\n                q[2]-=az*1.5\n              })\n            })\n\n            b=JSON.parse(JSON.stringify(ret))\n            b.map(v=>{\n              v.map(q=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(0,Math.PI,Math.PI/2)\n                q[0]=X\n                q[1]=Y\n                q[2]=Z\n              })\n            })\n            ret=[...ret, ...b]\n            \n            ret.map(v=>{\n              v.map(q=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(0,.96,0)\n                R(0,Math.PI,0)\n                q[0]=X\n                q[1]=Y\n                q[2]=Z\n                d=Math.hypot(...q)\n                q[0]/=d\n                q[1]/=d\n                q[2]/=d\n                q[0]*=ls\n                q[1]*=ls\n                q[2]*=ls\n              })\n            })\n            return ret\n          }\n          \n          Octahedron=ls=>{\n            ret = []\n            a=[]\n            for(i=4;i--;){\n              X1=S(p=Math.PI*2/4*i+Math.PI/4)\n              Y1=C(p)\n              Z1=0\n              X2=S(p=Math.PI*2/4*(i+1)+Math.PI/4)\n              Y2=C(p)\n              Z2=0\n              X3=0\n              Y3=0\n              Z3=1\n              a=[\n                [X1,Y1,Z1],\n                [X2,Y2,Z2],\n                [X3,Y3,Z3]\n              ]\n              ret=[...ret, a]\n              a=[\n                [X1,Y1,-Z1],\n                [X2,Y2,-Z2],\n                [X3,Y3,-Z3]\n              ]\n              ret=[...ret, a]\n            }\n            ret.map(v=>{\n              v.map(q=>{\n                d=Math.hypot(...q)\n                q[0]/=d\n                q[1]/=d\n                q[2]/=d\n                q[0]*=ls\n                q[1]*=ls\n                q[2]*=ls\n              })\n            })\n            return ret\n          }\n          \n          Cube=ls=>{\n            let ret=[]\n            for(j=6;j--;ret=[...ret,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-ls:ls),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n            return ret\n            ret.map(v=>{\n              v.map(q=>{\n                d=Math.hypot(...q)\n                q[0]/=d\n                q[1]/=d\n                q[2]/=d\n                q[0]*=ls\n                q[1]*=ls\n                q[2]*=ls\n              })\n            })\n          }\n          \n          Icosahedron=ls=>{\n            let a=[1,1],ret=[]\n            let b\n            for(i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]];\n            let phi=a[l]/a[l-1]\n            a=[[[-phi,-1,0],[phi,-1,0],[phi,1,0],[-phi,1,0]],[[0,-phi,-1],[0,phi,-1],[0,phi,1],[0,-phi,1]],[[-1,0,-phi],[-1,0,phi],[1,0,phi],[1,0,-phi]]]\n            let ico=[[[0,1],[1,0],[1,3]],[[0,1],[2,3],[1,0]],[[2,0],[2,3],[1,0]],[[0,1],[2,3],[0,2]],[[1,1],[2,3],[0,2]],[[1,1],[2,3],[2,0]],[[1,1],[1,2],[0,2]],[[0,1],[2,2],[0,2]],[[0,0],[1,0],[2,0]],[[2,0],[0,3],[0,0]],[[1,1],[1,2],[0,3]],[[1,1],[2,0],[0,3]],[[0,1],[1,3],[2,2]],[[1,3],[2,1],[2,2]],[[2,1],[0,3],[1,2]],[[2,1],[0,0],[1,3]],[[1,2],[2,2],[2,1]],[[2,2],[1,2],[0,2]],[[0,3],[2,1],[0,0]],[[1,3],[1,0],[0,0]]]\n            ico.map((v,i)=>{\n              b=[]\n              v.map(q=>{\n                t1=q[0],t2=q[1]\n                X=a[t1][t2][0],Y=a[t1][t2][1],Z=a[t1][t2][2]\n                b=[...b, [X,Y,Z]]\n              })\n              ret=[...ret, b]\n            })\n            ret.map(v=>{\n              v.map(q=>{\n                d=Math.hypot(...q)\n                q[0]/=d\n                q[1]/=d\n                q[2]/=d\n                q[0]*=ls\n                q[1]*=ls\n                q[2]*=ls\n              })\n            })\n            return ret\n          }\n\n          Dodecahedron=ls=>{\n            let ret=[]\n            let sd=5\n            let a=[], b=[]\n            mind=6e6\n            for(let i=sd;i--;){\n              X=S(p=Math.PI*2/sd*i)\n              Y=C(p)\n              Z=0\n              if(Y<mind)mind=Y\n              a = [...a, [X,Y,Z]]\n            }\n            a=a.map(v=>{\n              X=v[0]\n              Y=v[1]-=mind\n              Z=v[2]\n              R(0,.5535735,0)\n              return [X,Y,Z]\n            })\n            \n            ret = [...ret, a]\n            b=JSON.parse(JSON.stringify(a)).map(v=>{\n              d=Math.hypot(v[0],v[1])\n              v[0]=S(p=Math.atan2(v[0],v[1])+Math.PI)*d\n              v[1]=C(p)*d\n              return v\n            })\n            ret = [...ret, b]\n            \n            ret.map(v=>{\n              v.map(q=>{\n                if(q[2]<mind)mind=q[2]\n              })\n            })\n            ret.map(v=>{\n              v.map(q=>{\n                q[2]+=ang=1.538840639715\n              })\n            })\n            b=JSON.parse(JSON.stringify(ret)).map(v=>{\n              v.map(q=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(Math.PI,0,Math.PI)\n                q[0]=X\n                q[1]=Y\n                q[2]=Z\n              })\n              return v\n            })\n            e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n            \n            b=JSON.parse(JSON.stringify(ret)).map(v=>{\n              v.map(q=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(0,Math.PI/2,Math.PI/2)\n                q[0]=X\n                q[1]=Y\n                q[2]=Z\n              })\n              return v\n            })\n            ret = [...ret, ...b]\n\n            b=JSON.parse(JSON.stringify(e)).map(v=>{\n              v.map(q=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(Math.PI/2,0,Math.PI/2)\n                q[0]=X\n                q[1]=Y\n                q[2]=Z\n              })\n              return v\n            })\n            ret = [...ret, ...b]\n            \n            ret.map(v=>{\n              v.map(q=>{\n                d=Math.hypot(...q)\n                q[0]/=d\n                q[1]/=d\n                q[2]/=d\n                q[0]*=ls\n                q[1]*=ls\n                q[2]*=ls\n              })\n            })\n            return ret\n          }\n\n          Sphere=(ls,cl,rw)=>{\n            let X,Y,Z\n            let ret=[]\n            for(i=cl*rw;i--;){\n              a=[]\n              j=i%cl\n              k=(i/cl|0)\n              l=(j+1)%cl\n              \n              X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*k)*ls\n              Y=C(q)*ls\n              Z=C(p)*S(q)*ls\n              a=[...a,[X,Y,Z]]\n              X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*k)*ls\n              Y=C(q)*ls\n              Z=C(p)*S(q)*ls\n              a=[...a,[X,Y,Z]]\n              X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*(k+1))*ls\n              Y=C(q)*ls\n              Z=C(p)*S(q)*ls\n              a=[...a,[X,Y,Z]]\n              X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*(k+1))*ls\n              Y=C(q)*ls\n              Z=C(p)*S(q)*ls\n              a=[...a,[X,Y,Z]]\n              \n              ret = [...ret, a]\n            }\n            return ret\n          }\n          \n          x.lineJoin=x.lineCap=\'butt\'\n          \n          DrawSolid=(dod, sx, sy, sz, strokeStyle, fillStyle, useFill, globalAlpha) => {\n            tj=x.lineJoin\n            x.lineJoin=x.lineCap=\'butt\'\n            dod.map(v=>{\n              x.beginPath()\n              v.map((q,j)=>{\n                X=q[0]+sx+eX\n                Y=q[1]+sy+eY\n                Z=q[2]+sz+eZ\n                R(Rl,Pt,Yw,1)\n                if(Z>0)x.lineTo(...Q())\n              })\n              x.closePath()\n              x.lineWidth=Math.min(200,2e3/(Z**1.25))\n              x.globalAlpha=.3*globalAlpha\n              x.strokeStyle=strokeStyle\n              x.stroke()\n              x.lineWidth/=7\n              x.lineWidth=Math.max(x.lineWidth, 1)\n              x.globalAlpha=1*globalAlpha\n              x.stroke()\n            })\n\n            if(useFill){\n              dod.map(v=>{\n                x.beginPath()\n                v.map((q,j)=>{\n                  X=q[0]+sx+eX\n                  Y=q[1]+sy+eY\n                  Z=q[2]+sz+eZ\n                  R(Rl,Pt,Yw,1)\n                  if(Z>0)x.lineTo(...Q())\n                })\n                x.globalAlpha=.6*globalAlpha\n                x.fillStyle=fillStyle\n                x.fill()\n              })\n            }\n            x.lineJoin=x.lineCap=tj\n          }\n          \n          setupListeners=()=>{\n            c.onclick=()=>{\n              if(!designing){\n                c.requestPointerLock()\n                c.requestFullscreen()\n              } else {\n                document.exitPointerLock()\n              }\n            }\n            keystates=Array(255).fill(0)\n            mx=my=0\n            shooting=false\n            window.onmousedown=e=>{\n              if(designing){                \n                if(e.button==0)button=true\n                let rect = c.getBoundingClientRect()\n                mx=(e.pageX-(rect.left+2))/(c.clientWidth)*c.width\n                my=(e.pageY-(rect.top+2))/(c.clientHeight)*c.height\n                bx=mx\n                by=my\n              } else {\n                if(e.which==1){\n                  shooting=true\n                }\n                if(e.button==0)button=true\n                let rect = c.getBoundingClientRect()\n                mx=(e.pageX-(rect.left+2))/(c.clientWidth)*c.width\n                my=(e.pageY-(rect.top+2))/(c.clientHeight)*c.height\n                bx=mx\n                by=my\n              }\n            }\n            window.ontouchstart=e=>{\n              button=true\n              let rect = c.getBoundingClientRect()\n              e=(l=e.originalEvent.touches[0])?l:e\n              mx=(l.pageX-(rect.left+2))/(c.clientWidth)*c.width\n              my=(l.pageY-(rect.top+2))/(c.clientHeight)*c.height\n              bx=mx\n              by=my\n            }\n            window.onmouseup=e=>{\n              if(e.which==1){\n                shooting=false\n              }\n              if(drawMode==1){\n                B.map(v=>{\n                  v[5]=v[4]=v[3]\n                })\n              }\n              setTimeout(()=>{\n                //B.map(v=>v[3]=false)\n              },0)\n              buttonToggle=curCell=false\n              if(e.button==0)button=false\n            }\n            window.onmousemove=e=>{\n              e.stopPropagation()\n              e.preventDefault()\n              if(designing){\n                let rect = c.getBoundingClientRect()\n                console.log(c.width,c.clientWidth)\n                mx=(e.pageX-(rect.left+2))/(c.clientWidth)*c.width\n                my=(e.pageY-(rect.top+2))/(c.clientHeight)*c.height\n              } else {\n                mx+=e.movementX\n                my+=e.movementY\n                Yw-=e.movementX/300\n                Pt-=e.movementY/300\n              }\n            }\n            window.ontouchend=e=>{\n              buttonToggle=curCell=false\n              button=false\n            }\n            window.ontouchmove=e=>{\n              let rect = c.getBoundingClientRect()\n              e=(l=e.originalEvent.touches[0])?l:e\n              mx=(l.pageX-(rect.left+2))/(c.clientWidth)*c.width\n              my=(l.pageY-(rect.top+2))/(c.clientHeight)*c.height\n            }\n            window.onkeydown=e=>{\n              console.log(e.keyCode) \n              e.stopPropagation()\n              e.preventDefault()\n              if(e.keyCode==71) showFloor=!showFloor\n\n              if(e.keyCode==67){\n                eXv=eYv=eZv=eX=eY=eZ=oX=oY=0,oZ=designing?30:0\n                Rl=Pt=Yw=0\n              }\n              \n              if(e.keyCode==116) window.location.reload()\n              if(e.keyCode==75) {\n        