n        }\n        \n        x.globalAlpha=1\n        x.fillStyle=\'#000c\'\n        x.fillRect(0,0,c.width,c.height)\n        //x.lineJoin=x.lineCap=\'round\'\n        \n\n        if(button){\n          c.style.cursor=\'none\'\n        } else {\n          c.style.cursor=\'crosshair\'\n        }\n        \n        //x.fillStyle=\'#0008\'\n        //x.fillRect(0,0,c.width,c.height)\n        \n        if(designing){\n          \n          x.lineJoin=x.lineCap=\'butt\'\n          Rl=0,Pt=0,Yw=0\n          oX=0,oY=0,oZ=30\n\n          x.fillStyle=\'#f00\'\n          s=5, brushsize=5\n          x.fillRect(mx-s/2,my-s/2,s,s)\n\n          B.map((v,i)=>{\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            R(Rl,Pt,Yw,1)\n            s=Math.min(2000, 900/Z)\n            l=Q()\n            switch(drawMode){\n              case 0:\n                if(!button) v[3]=v[5]\n                if(mx>l[0]-s/2 && mx <l[0]+s/2 && my>l[1]-s/2 && my<l[1]+s/2){\n                  v[3]=1\n                  if(button && (!buttonToggle || curCell != i)){\n                    if(!buttonToggle) mode = !v[5]\n                    if(mode){\n                      v[4]=v[5]=mode\n                    } else {\n                      B.map((q,j)=>{\n                        q[3]=0\n                        if((d=Math.hypot(v[0]-q[0],v[1]-q[1]))<brushsize){\n                          q[3]=1\n                          v[4]=v[5]=q[4]=q[5]=0\n                        }\n                      })\n                    }\n                    buttonToggle=true\n                    curCell=i\n                  }\n                }\n                x.fillStyle=\'#0000\'\n                if(v[3]){\n                  x.fillStyle=\'#6ff8\'\n                }\n                if(v[4] || v[5]){\n                  x.fillStyle=\'#4f8\'\n                }\n                x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n              break\n              case 1:\n                if(button){\n                  if(mx>l[0]-s/2 && mx <l[0]+s/2 && my>l[1]-s/2 && my<l[1]+s/2 && !buttonToggle){\n                    mode = !v[4], buttonToggle=true\n                  }\n                  if(buttonToggle){\n                    v[3]=v[5]\n                    for(j=4;j--;){\n                      switch(j){\n                        case 0:\n                          X1=l[0]-s/2\n                          Y1=l[1]-s/2\n                          X2=l[0]+s/2\n                          Y2=l[1]-s/2\n                        break\n                        case 1:\n                          X1=l[0]+s/2\n                          Y1=l[1]-s/2\n                          X2=l[0]+s/2\n                          Y2=l[1]+s/2\n                        break\n                        case 2:\n                          X1=l[0]+s/2\n                          Y1=l[1]+s/2\n                          X2=l[0]-s/2\n                          Y2=l[1]+s/2\n                        break\n                        case 3:\n                          X1=l[0]-s/2\n                          Y1=l[1]+s/2\n                          X2=l[0]-s/2\n                          Y2=l[1]-s/2\n                       break\n                      }\n                      X3=bx,Y3=by,X4=mx,Y4=my\n                      if(I(X1,Y1,X2,Y2,X3,Y3,X4,Y4)) v[3] = mode\n                    }\n                  }\n                }\n                if(v[5]){\n                  x.fillStyle=\'#4f8\'\n                  x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n                }\n                if(v[3] || (mode && v[4])){\n                  if(!v[4]){\n                    x.fillStyle=mode&&v[4]?\'#000\':\'#4fc8\'\n                    x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n                  }\n                }\n                if(!mode){\n                  if(v[3]&&v[4]){\n                    x.fillStyle=\'#246\'\n                    x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n                  }\n                }\n              break\n            }\n            x.strokeStyle=\'#4fc2\'\n            x.lineWidth=4\n            x.strokeRect(l[0]-s/2,l[1]-s/2,s,s)\n          })\n        } else {\n          \n          oX=0,oY=0,oZ=0\n          \n          DrawSolid(bgsphere, -eX, -eY, -eZ, `#fff2`, `#fff2`, 1, 1)\n\n          for(m=wallHeight;m--;){\n            B.map(v=>{\n              tx=iBs*v[0]*2**.5+eX\n              ty=-iBs*v[1]*2**.5+eZ\n              tz=iBs*v[2]*2**.5+eY-iBs*m*(2**.5)\n              for(let m=4;m--;){\n                X=tx+S(p=Math.PI*2/4*m+Math.PI/4)*(d=(2**.5/2)*iBs)\n                Z=tx+S(p)*d\n                y=d\n              }\n              if(v[4]){\n                CB.map((q,j)=>{\n                  X=q[0]*iBs+tx\n                  Z=q[1]*iBs+ty\n                  Y=q[2]*iBs+tz\n                  if(!(j%4)) x.beginPath()\n                  R(0,0,Yw,0)\n                  R(Rl,Pt,0,1)\n                  if(Z>0) x.lineTo(...Q())\n                  if(j%4==3){\n                    x.closePath()\n                    x.lineWidth=Math.min(100, 100/Z)\n                    x.strokeStyle=\'#fff4\'\n                    x.fillStyle=\'#fff1\'\n                    x.stroke()\n                    x.fill()\n                  }\n                })\n              }\n            })\n          }\n          \n          if(!((t*60|0)%60) && Enemies.length<maxEnemies) spawnEnemy()\n          Enemies.map(v=>{\n            DrawSolid(v[0], v[1], v[2], v[3], `hsla(1,99%,${50+v[4]/2}%,.5)`, `hsla(1,99%,${50+v[4]/2}%,.2)`, 1, 1)\n          })\n\n          P2=P2.filter(v=>v[6]<100)\n          Enemies.map(v=>{\n            if(v[4]<1) bigSparks(v[1],v[2],v[3])\n          })\n          Enemies=Enemies.filter(v=>{\n            return H(-eX-v[1],-eY-v[2],-eZ-v[3])<200 && v[4]>0\n          })\n          P2.map(v=>{\n            X=v[0]+=v[3]\n            Y=v[1]+=v[4]\n            Z=v[2]+=v[5]\n            X+=eX\n            Y+=eY\n            Z+=eZ\n            v[6]++\n            R(Rl,Pt,Yw,1)\n            x.fillStyle=`hsla(${v[6]*1},99%,50