          Z=(Z2*expansion+(Z1*(1-expansion)))*ls\n          return [X,Y,Z]\n        })\n        return v\n      })))]\n\n      if(go){\n        x.globalAlpha=.07\n        x.drawImage(bg,0,0,c.width,c.height)\n        x.globalAlpha=1\n        x.fillStyle=\'#0003\'\n        x.fillRect(0,0,c.width,c.height)\n      } else {\n        x.fillStyle=\'#000\'\n        x.fillRect(0,0,c.width,c.height)\n      }\n      x.lineJoin=x.lineCap=\'round\'\n      //Rl=t/3,Pt=-t,Yw=S(t)*3\n      Rl=0,Pt=-.57,Yw=Math.PI/3+2.25\n      oX=0,oY=0,oZ=5\n\n      shps.map(shp=>{\n       shp.map((n,m)=>{\n          x.beginPath()\n          ax=ay=az=0\n          n.map(q=>{\n            v=q\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            ax+=X\n            ay+=Y\n            az+=Z\n            R(Rl,Pt,Yw,1)\n            if(Z>2.85)x.lineTo(...Q())\n          })\n          ax/=n.length\n          ay/=n.length\n          az/=n.length\n          x.closePath()\n          x.lineWidth=200/(Z**1.5)\n          //x.strokeStyle=`hsla(${(l=H(ax,ay,az)*200)*3-t*200},99%,${100-l**3.5/60000000}%,.2)`\n          //x.stroke()\n          x.lineWidth/=5\n          x.lineWidth|=0\n          x.strokeStyle=\'#fff3\'\n          x.stroke()\n          x.fillStyle=`hsla(${(l=H(ax,ay,az)*200)/2-t*300},${99}%,${Math.max(20, 120-(l/1.5)**3/1100000)}%,.25)`\n          x.fill()\n        })\n      })\n\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'tooth', 145, 'whitehot robot', '2022-07-25 20:51:53', '[600306,600305,600304,600253,600252,600251,600248,600247]', 94, 'https://code.dweet.net/thumbs/41ef8104e1d871dc50e47f0b57ff1215.jpg', 0, 0),
