neCap=\'round\'\n      Rl=0,Pt=C(t)/2,Yw=S(t/8)*10\n      oX=0,oY=0,oZ=800+S(t*1.5)*200\n\n      CB.map((v,i)=>{\n        if(!(i%4))x.beginPath()\n        X=v[0]*200\n        Y=v[1]*200\n        Z=v[2]*200\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        if(i%4==3){\n          x.closePath()\n          x.lineWidth=Math.min(500, 200000/(Z**1.5))\n          x.strokeStyle=\'#fff1\'\n          x.stroke()\n          x.lineWidth/=6\n          x.strokeStyle=\'#fff4\'\n          x.stroke()\n        }\n      })\n\n      B.map((v,i)=>{\n        gx=v[0]\n        gy=v[1]\n        gz=v[2]\n        d=1+Math.hypot(gx,gy,gz)\n        gx/=d\n        gy/=d\n        gz/=d\n        gx*=iGv\n        gy*=iGv\n        gz*=iGv\n        m=0\n        v[3]-=gx\n        v[4]-=gy\n        v[5]-=gz\n        do{\n          if(!i){\n            v[0]=Math.min(450,Math.max(-450,S(t/2+S(t/2)*Math.PI*2)*800))\n            v[1]=0//S(t*2)*60\n            v[2]=0\n          }\n          X=v[0]+=v[3]\n          Y=v[1]+=v[4]\n          Z=v[2]+=v[5]\n          good=true\n          m++\n          B.map((g,n)=>{\n            j=m?n:(B.length-n-1)\n            q=B[j]\n            if(i!=j&&j){\n              tx=q[0]\n              ty=q[1]\n              tz=q[2]\n              d=(1+(f=Math.hypot(a=tx-X,b=ty-Y,e=tz-Z)))**2*50\n              q[3]-=a/d*4\n              q[4]-=b/d*4\n              q[5]-=e/d*4\n              if(f<(l=q[6]+v[6])){\n                good=false\n                q[0]=v[0]+a/f*l\n                q[1]=v[1]+b/f*l\n                q[2]=v[2]+e/f*l\n                q[3]/=2\n                q[4]/=2\n                q[5]/=2\n                h=i?4:150\n                q[3]+=a/f*iBv*h\n                q[4]+=b/f*iBv*h\n                q[5]+=e/f*iBv*h\n              }\n            }\n          })\n        }while((m<(i?2:4))&&!good);\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          s=v[6]*450/(Z)\n          if(i){\n            s*=3\n            x.fillStyle=\'#4f82\'\n            l=Q()\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n            x.fillStyle=\'#fff\'\n            s/=4\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          }else{\n            x.beginPath()\n            x.arc(...Q(),s,0,7)\n            x.fillStyle=i?\'#4f85\':\'#0ff3\'\n            x.fill()\n            x.strokeStyle=\'#fff4\'\n            x.lineWidth=Math.min(200, 3699/Z)\n            x.stroke()\n          }\n        }\n      })\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'collider system', 145, 'whitehot robot', '2022-07-27 00:33:16', '[600304,600253,600252,600251,600248,600247]', 97, 'https://code.dweet.net/thumbs/b8108f28f2abebfeb3ef43b52cac33f4.jpg', 0, 0),
(600330, 'https://srmcgann.github.io/assets/AkVHB.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/zrsMs.gif);\n  background-size: 100% 100%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'collision system (gif)', 145, 'whitehot robot', '2022-07-28 20:10:04', '[600288,600253,600252,600251,600248,600247]', 82, 'https://code.dweet.net/thumbs/b8108f28f2abebfeb3ef43b52cac33f4.jpg', 2, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600331, 'https://srmcgann.github.io/assets/1pAfcz.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/52uBj.gif);\n  background-size: 100% 100%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'butterflies (gif)', 145, 'whitehot robot', '2022-07-28 21:05:18', '[600288,600253,600252,600251,600248,600247]', 86, 'https://code.dweet.net/thumbs/a1216950e5e92ac31ec5a2dd73924584.jpg', 0, 0),
(600332, 'https://srmcgann.github.io/assets/2jKi4.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n        jpg=new Image()\n        go=false\n        jpg.onload=()=>{\n          buffer = document.createElement(\'canvas\')\n          buffer.width=1920\n          buffer.height=1080\n          bctx = buffer.getContext(\'2d\')\n          if(jpg.width/jpg.height>1.7777777778){\n            w=1920\n            h=1920*(jpg.width/jpg.height)\n          } else {\n            w=1080*(jpg.width/jpg.height)\n            h=1080\n          }\n          bctx.fillStyle=\'#0f0\'\n          bctx.fillRect(0,0,1920,1080)\n          bctx.drawImage(jpg,960-w/2,540-h/2,w,h)\n          data = bctx.getImageData(0,0,buffer.width,buffer.height)\n          l=data.data\n          for(i=0;i<l.length;i+=4){\n            red   = l[i+0]\n            green = l[i+1]\n            blue  = l[i+2]\n            alpha = l[i+3]\n\n            greenTolerance=100\n            alpha=green>255-greenTolerance && red<greenTolerance && blue<greenTolerance?0:255\n\n            l[i+0] = red\n            l[i+1] = green\n            l[i+2] = blue\n            l[i+3] = alpha\n          }\n          bctx.putImageData(data,0,0)\n          go=true\n        }\n        s=window.location.href.split(\'?jpg=\')[1]\n        if(typeof s !== \'undefined\' && s.length){\n          jpg.src=\'/proxy.php?url=\'+s\n        } else {\n          jpg.src=\'/proxy.php?url=https://srmcgann.github.io/assets/20lWxw.jpg\'\n        }\n        for(a=[1,1],i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]]\n        phi = a[l+1]/a[l]\n\n        rects=Array(3).fill().map((v,i)=>{\n          a=[]\n          a=[...a, [-phi/2, -.5, 0]]\n          a=[...a, [phi/2,  -.5, 0]]\n          a=[...a, [phi/2,  .5,  0]]\n          a=[...a, [-phi/2, .5,  0]]\n          a=a.map(q=>{\n            X=q[0], Y=q[1], Z=q[2]\n            switch(i){\n              case 0: R(Math.PI/2,0,0); break\n              case 1: R(Math.PI/2,Math.PI/2,Math.PI/2); break\n              case 2: R(0,0,Math.PI/2); break\n            }\n            return [X,Y,Z]\n          })\n          return a\n        })\n        facets=[[[0,0], [2,2], [0,3]],[[1,2], [2,2], [0,3]],[[1,2], [2,2], [2,1]],[[1,2], [0,2], [2,1]],[[2,1], [0,1], [1,3]],[[2,1], [2,2], [1,3]],[[2,1], [0,1], [0,2]],[[1,2], [1,1], [0,2]],[[0,2], [0,1], [2,0]],[[0,2], [2,0], [1,1]],[[2,3], [2,0], [1,1]],[[2,3], [2,0], [1,0]],[[0,1], [2,0], [1,0]],[[0,1], [1,3], [1,0]],[[0,0], [1,3], [1,0]],[[0,0], [2,3], [1,0]],[[0,0], [2,3], [0,3]],[[1,1], [2,3], [0,3]],[[1,1], [1,2], [0,3]],[[0,0], [2,2], [1,3]]]\n\n        shp=[]\n        facets.map(n=>{\n          a=[]\n          n.map(q=>{\n            v=rects[q[0]][q[1]]\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            a=[...a, [X,Y,Z]]\n          })\n          shp=[...shp, a]\n        })\n\n        subdivide = () =>{\n          subdivisions=[]\n          new_shp=[]\n          shp.map((v,i,a)=>{\n            a=[]\n            v.map((q,j)=>{\n              X1=q[0]\n              Y1=q[1]\n              Z1=q[2]\n              X2=v[l=(j+1)%3][0]\n              Y2=v[l][1]\n              Z2=v[l][2]\n              mx=(X1+X2)/2\n              my=(Y1+Y2)/2\n              mz=(Z1+Z2)/2\n              a=[...a, [mx,my,mz]]\n            })\n            subdivisions=[...subdivisions, a]\n            v.map((q,j)=>{\n              b=[]\n              for(m=1;m--;){\n                b=[...b, [...v[(j+1)%3]], [...a[(m+j)%3]], [...a[(m+j+1)%3]]]\n              }\n              subdivisions=[...subdivisions, b]\n            })\n          })\n          shp=[...new_shp, ...subdivisions]      \n      }\n\n\n        subdivisions=3\n        for(let m = subdivisions; m--;)subdivide()\n        base_shp=JSON.parse(JSON.stringify(shp))\n\n        expansion=10+10*S(t*2)\n        ls=.1/(20+expansion)*270\n        shps=[]\n        shps=[...shps, ((base_shp.map(v=>{\n          v=v.map(q=>{\n            X1=q[0]\n            Y1=q[1]\n            Z1=q[2]\n            d=Math.hypot(X1,Y1,Z1)\n            X2=X1/d\n            Y2=Y1/d\n            Z2=Z1/d\n            X=(X2*expansion+(X1*(1-expansion)))*ls\n            Y=(Y2*expansion+(Y1*(1-expansion)))*ls\n            Z=(Z2*expansion+(Z1*(1-expansion)))*ls\n            return [X,Y,Z]\n          })\n          return v\n        })))]\n        expansion=S(t*4)*1-2\n        ls=1.5\n        shps=[...shps, ((base_shp.map(v=>{\n          v=v.map(q=>{\n            X1=q[0]\n            Y1=q[1]\n            Z1=q[2]\n            d=Math.hypot(X1,Y1,Z1)\n            X2=X1/d\n            Y2=Y1/d\n            Z2=Z1/d\n            X=(X2*expansion+(X1*(1-expansion)))*ls\n            Y=(Y2*expansion+(Y1*(1-expansion)))*ls\n            Z=(Z2*expansion+(Z1*(1-expansion)))*ls\n            return [X,Y,Z]\n          })\n          return v\n        })))]\n\n      }\n\n      x.lineJoin=x.lineCap=\'butt\'\n      Rl=0,Pt=-4,Yw=t\n      oX=0,oY=0,oZ=3.5\n\n      x.globalAlpha=1\n      x.fillStyle=\'#0008\'\n      x.fillRect(0,0,c.width,c.height)\n\n      shps.map(shp=>{\n       shp.map(n=>{\n          x.beginPath()\n          ax=ay=az=0\n          n.map(q=>{\n            v=q\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            ax+=X\n            ay+=Y\n            az+=Z\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n          })\n          ax/=n.length\n          ay/=n.length\n          az/=n.length\n          x.closePath()\n          x.lineWidth=70/(Z**1.5)\n          x.strokeStyle=`hsla(${(l=H(ax,ay,az)*200)*1-t*200},99%,${100-l**3.5/80000000}%,.2)`\n          x.stroke()\n          x.lineWidth/=5\n          x.lineWidth|=0\n          x.strokeStyle=\'#fff3\'\n          //x.stroke()\n          //x.fillStyle=`hsla(${(l=H(ax,ay,az)*200)*2-t*200},99%,${100-l**3.5/100000000}%,.1)`\n          //x.fill()\n        })\n      })\n      x.globalAlpha=1\n      if(go) x.drawImage(buffer,0,0,c.width,c.height)      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'jpg transparency', 145, 'whitehot robot', '2022-07-28 21:58:34', '[600304,600253,600252,600251,600248,600247]', 110, 'https://code.dweet.net/thumbs/b25219e5709899d2c869b682eee13ed9.jpg', 0, 0),
