(600341, 'https://srmcgann.github.io/assets/W7OZS.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          if(m)X+=oX,Y+=oY,Z+=oZ\n        }\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n\n        Cylinder=(rw,cl,ls1,ls2,caps)=>{\n          let s=ls2/rw*2, q=0\n          let shp = Array(rw*cl).fill().map((v,k)=>{\n            a=[]\n            let i=k%cl\n            let j=((k/cl|0)-rw/2)*s\n            X=S(p=Math.PI*2/cl*i+q)*ls1\n            Y=j\n            Z=C(p)*ls1\n            a=[...a,[X,Y,Z]]\n            X=S(p=Math.PI*2/cl*(i+1)+q)*ls1\n            Y=j\n            Z=C(p)*ls1\n            a=[...a,[X,Y,Z]]\n            X=S(p=Math.PI*2/cl*(i+1)+q)*ls1\n            Y=j+s\n            Z=C(p)*ls1\n            a=[...a,[X,Y,Z]]\n            X=S(p=Math.PI*2/cl*i+q)*ls1\n            Y=j+s\n            Z=C(p)*ls1\n            a=[...a,[X,Y,Z]]\n            return a\n          })\n          if(caps){\n            a=[],b=[]\n            for(let k=0;k<cl;++k){\n              let i=k%cl\n              X=S(p=Math.PI*2/cl*i+q)*ls1\n              Y=ls2\n              Z=C(p)*ls1              \n              a=[...a,[X,Y,Z]]\n              b=[...b,[X,-Y,Z]]\n            }\n            shp=[...shp, a]\n            shp=[...shp, b]\n          }\n          s1=.3\n          s2=ls1/3\n          /*e=[\n            [-s1,0,-s1-s2],\n            [-s1,0,s1-s2],\n            [s1,0,s1-s2],\n            [s1,0,-s1-s2],\n          ]\n          f=[\n            [-s1,0,-s1+s2],\n            [-s1,0,s1+s2],\n            [s1,0,s1+s2],\n            [s1,0,-s1+s2],\n          ]\n          shp=[...shp, e, f]*/\n          return shp\n        }\n\n        iBc=5,sd=8\n        h=8,caps=1\n        rw=3,cl=3,sp=40\n        let f=[],g=[]\n        B=Array(iBc).fill().map((v,i)=>{\n          for(let j=rw*cl;j--;){\n            px=((j%cl)-cl/2+.5)*sp\n            py=0\n            pz=((j/cl|0)%rw-rw/2+.5)*sp\n            tx=px\n            ty=-h+(h/iBc*i)+h/iBc/2+py\n            tz=pz\n            ls=10/(1+i/iBc)**4//+.25+S(Math.PI*2/iBc*i*1+S(t*2)*Math.PI*4-Math.PI/2)/2\n            f = [...f, [tx, ty,tz,Cylinder(1,sd,ls,h/2/iBc,caps),0,j]]\n            g = [...g, [tx,-ty,tz,Cylinder(1,sd,ls,h/2/iBc,caps),0,j]]\n          }\n        })\n        B=[...g, ...f]\n        G=1e3, iSTc=4e3\n        ST=Array(iSTc).fill().map(v=>{\n          X=(Rn()-.5)*G\n          Y=(Rn()-.5)*G\n          Z=(Rn()-.5)*G\n          return [X,Y,Z]\n        })\n      }\n\n      x.fillStyle=\'#000a\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'butt\'\n      Rl=C(t/4)/2,Pt=Math.max(-.6,Math.min(.06,-.4+S(t-.25)*4)),Yw=-Math.max(-Math.PI*2,Math.min(Math.PI*2,C(t/2)*8))\n      oX=0,oY=0,oZ=Math.max(25,Math.min(100, 100+S(t/1.5)*600))\n\n      ST.map(v=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          s=8e3/Z\n          l=Q()\n          x.globalAlpha=.75/(1+Z**8/9999999999999999999999)*(Math.min(1,Z/250)**4)\n          x.fillStyle=\'#fff2\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          x.fillStyle=\'#fff\'\n          s/=4\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        }\n      })\n      x.globalAlpha=1\n\n      B.map((v,i)=>{\n        tx=v[0]\n        ty=v[1]\n        tz=v[2]\n        ip=.5+S((v[4]+=.1)+v[5])/2\n        v[3].map(q=>{\n          x.beginPath()\n          q.map(n=>{\n            X=n[0]\n            Y=n[1]\n            Z=n[2]\n            d=Math.hypot(X,Z)\n            p=Math.atan2(X,Z)\n            nx=S(p)*(h*1.4-d)*1//.5\n            ny=Y\n            nz=C(p)*(h*1.4-d)*1//.5\n            X=nx*(1-ip)+X*ip+tx\n            Y=ny*(1-ip)+Y*ip+ty\n            Z=nz*(1-ip)+Z*ip+tz\n\n            R(Rl,Pt,Yw,1)\n            if(Z>0) x.lineTo(...Q())\n          })\n          x.closePath()\n          x.lineWidth=Math.min(100,10000/(Z**1.5))|0\n          x.strokeStyle=\'#00ffdd10\'\n          x.stroke()\n          x.lineWidth/=10\n          x.lineWidth=Math.max(1,x.lineWidth)|0\n          x.strokeStyle=\'#efe6\'\n          x.stroke()\n          x.fillStyle=\'#8800ff0a\'\n          x.fill()\n        })\n      })\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'plasma column', 145, 'whitehot robot', '2022-08-02 16:03:15', '[600304,600253,600252,600251,600248,600247]', 74, 'https://code.dweet.net/thumbs/dd8b01d60240ad7cbd5717a28be6b872.jpg', 0, 0),
