(600345, 'https://srmcgann.github.io/assets/IOGVY.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/wL3wF.gif);\n  background-size: 100% 100%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'evil day', 145, 'whitehot robot', '2022-08-02 22:52:23', '[600288,600253,600252,600251,600248,600247]', 77, 'https://code.dweet.net/thumbs/e2e15d57c7110c6be877a2ed79320988.jpg', 0, 0),
(600346, 'https://srmcgann.github.io/assets/1Gv8Ys.mp4', '//some boilerplate to wire up the canvas\n    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){  // t == 0 is an opportunity to declare some stuff\n      }\n      x.fillStyle=\'#0008\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      for(i=4;i--;){\n        x.beginPath()\n        X=S(p=Math.PI*2/4*i)*300\n        Y=C(p)*300\n        x.lineTo(960+X,540+Y)\n        X=S(p=Math.PI*2/4*i)*320\n        Y=C(p)*320\n        x.lineTo(960+X,540+Y)\n        x.strokeStyle=\'#fff2\'\n        x.lineWidth=20\n        x.stroke()\n        x.lineWidth/=5\n        x.strokeStyle=\'#fff\'\n        x.stroke()\n      }\n\n      x.beginPath()\n      x.arc(960,540,540/1.75,0,7)\n      x.strokeStyle=\'#fff2\'\n      x.lineWidth=20\n      x.stroke()\n      x.lineWidth/=5\n      x.strokeStyle=\'#fff\'\n      x.stroke()\n\n      x.fillStyle=\'#fff\'\n\n      x.font=\'90px courier\'\n      x.fillText(\'Unit Circle\',5,70)\n      x.font=\'70px courier\'\n      x.fillStyle=\'#0f8\'\n      x.fillText(\'radians/degrees\',5,150)\n      x.font=\'100px courier\'\n\n      x.font=\'200px courier\'\n      x.fillText(\'π/\',750,200)\n      x.font=\'100px courier\'\n      x.fillText(\'180°\',950,190)\n      x.font=\'200px courier\'\n      x.fillText(\'0\',900,1005)\n      x.fillText(\'½π/\',1305,610)\n      x.font=\'100px courier\'\n      x.fillText(\'90°\',1620,600)\n      x.font=\'150px courier\'\n      x.fillText(\'1½π/\',20,610)\n      x.font=\'100px courier\'\n      x.fillText(\'270°\',390,600)\n      x.font=\'200px courier\'\n\n      x.fillStyle=\'#ff0\'\n      x.font=\'40px courier\'\n      x.fillText(\'θ = \'+(Math.round((t%(2*Math.PI))*1000)/1000),760,500)\n      x.fillText(\'X = SIN(θ) = \'+(Math.round(S(t)*100)/100),760,550)\n      x.fillText(\'Y = COS(θ) = \'+(Math.round(C(t)*100)/100),760,600)\n      x.font=\'200px courier\'\n\n      x.beginPath()\n      ls=300\n      X=960+S(p=t)*ls/2.5\n      Y=540+C(p)*ls/2.5\n      x.lineTo(X,Y)\n      X=960+S(p=t)*ls\n      Y=540+C(p)*ls\n      x.lineTo(X,Y)\n      x.strokeStyle=\'#fff2\'\n      x.lineWidth=20\n      x.stroke()\n      x.lineWidth/=5\n      x.strokeStyle=\'#fff\'\n      x.stroke()\n\n      x.beginPath()\n      X=960+50, Y=540+300-50\n      d=Math.hypot(960-X,540-Y)\n      p=Math.atan2(960-X,540-Y)+t+Math.PI\n      x.lineTo(960+S(p)*d,540+C(p)*d)\n      X=960, Y=540+300\n      d=Math.hypot(960-X,540-Y)\n      p=Math.atan2(960-X,540-Y)+t+Math.PI\n      x.lineTo(960+S(p)*d,540+C(p)*d)\n      X=960-50, Y=540+300-50\n      d=Math.hypot(960-X,540-Y)\n      p=Math.atan2(960-X,540-Y)+t+Math.PI\n      x.lineTo(960+S(p)*d,540+C(p)*d)\n      x.strokeStyle=\'#fff2\'\n      x.lineWidth=20\n      x.stroke()\n      x.lineWidth/=5\n      x.strokeStyle=\'#fff\'\n      x.stroke()\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'unit circle', 145, 'whitehot robot', '2022-08-03 12:28:58', '[600253,600252,600251,600248,600247]', 78, 'https://code.dweet.net/thumbs/469abc66a8ebd71f7d3e2887c2b6313e.jpg', 0, 0),
(600347, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n\nfor(G=Math.random,x.fillRect(0,0,W=8e3,W),B=t?B:[],m=40;--m;)B=[[960+S(p=2.09*m+t)*(h=540),h+C(p)*h,0,0],...B].filter((v,i)=>i<W);B.map(v=>x.clearRect(v[0]+=v[2]+=G()-.5,v[1]+=v[3]+=G()-.5,9,9))\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'basic template', 145, 'whitehot robot', '2022-08-05 22:41:03', '[600253,600252,600251,600248,600247]', 29, '', 0, 1);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600348, 'https://srmcgann.github.io/assets/2jKi4.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        hexToRGBA=q=>{\n          q=q.replace(\'#\', \'\')\n          let l=q.length\n          if(l!=3 && l!=4 && l!==6 && l!=8) return\n          let red, green, blue, alpha, red_, green_, blue_, alpha_\n          switch(l){\n            case 3:\n              red_     = q[0]+q[0]\n              green_   = q[1]+q[1]\n              blue_    = q[2]+q[2]\n              alpha    = 255\n            break\n            case 4:\n              red_     = q[0]+q[0]\n              green_   = q[1]+q[1]\n              blue_    = q[2]+q[2]\n              alpha_   = q[3]+q[3]\n              alpha    = +(\"0x\"+alpha_)\n            break\n            case 6:\n              red_     = q[0]+q[1]\n              green_   = q[2]+q[3]\n              blue_    = q[4]+q[5]\n              alpha    = 255\n            break\n            case 8:\n              red_     = q[0]+q[1]\n              green_   = q[2]+q[3]\n              blue_    = q[4]+q[5]\n              alpha_   = q[6]+q[7]\n              alpha    = +(\"0x\"+alpha_)\n            break\n          }\n          red    = +(\"0x\"+red_)\n          green  = +(\"0x\"+green_)\n          blue   = +(\"0x\"+blue_)\n          return [red, green, blue, alpha]\n        }\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n        jpg=new Image()\n        go=false\n        jpg.onload=()=>{\n          buffer = document.createElement(\'canvas\')\n          buffer.width=1920\n          buffer.height=1080\n          bctx = buffer.getContext(\'2d\')\n          if(jpg.width/jpg.height>1.7777777778){\n            w=1920\n            h=1920*(jpg.width/jpg.height)\n          } else {\n            w=1080*(jpg.width/jpg.height)\n            h=1080\n          }\n          bctx.clearRect(0,0,1920,1080)\n          bctx.drawImage(jpg,960-w/2,540-h/2,w,h)\n          data = bctx.getImageData(0,0,buffer.width,buffer.height)\n          l=data.data\n          for(i=0;i<l.length;i+=4){\n            red   = l[i+0]\n            green = l[i+1]\n            blue  = l[i+2]\n            alpha = l[i+3]\n\n            //greenTolerance=100\n            //alpha=green>255-greenTolerance && red<greenTolerance && blue<greenTolerance?0:255\n            diff=(Math.abs(red-tgtRGBA[0])+Math.abs(green-tgtRGBA[1])+Math.abs(blue-tgtRGBA[2]))/3\n            if(invert){\n              alpha = diff>tol?0:255\n            } else {\n              alpha = diff>tol?255:0\n            }\n            l[i+0] = red\n            l[i+1] = green\n            l[i+2] = blue\n            l[i+3] = alpha\n          }\n          bctx.putImageData(data,0,0)\n          go=true\n        }\n        tolerance=window.location.href.split(\'tolerance=\')[1]\n        if(typeof tolerance !== \'undefined\' && tolerance.length){\n          tolerance = tolerance.split(\'&\')[0]\n          tol=tolerance\n        } else {\n          tol=100\n        }\n        invert=window.location.href.split(\'invert=\')[1]\n        if(typeof invert !== \'undefined\'){\n          invert=invert.split(\'&\')[0]\n          invert=!!(+invert)\n        } else {\n          invert=false\n        }\n        tgtcol=window.location.href.split(\'tgtcol=\')[1]\n        if(typeof tgtcol !== \'undefined\' && tgtcol.length){\n          tgtcol=tgtcol.split(\'&\')[0]\n          tgt_col=tgtcol\n        } else {\n          tgt_col=\'#eab29c\'\n        }\n        tgtRGBA=hexToRGBA(tgt_col)\n        s=window.location.href.split(\'jpg=\')[1]\n        if(typeof s !== \'undefined\' && s.length){\n          s=s.split(\'&\')[0]\n          jpg.src=\'/proxy.php?url=\'+s\n        } else {\n          jpg.src=\'/proxy.php?url=https://srmcgann.github.io/assets/295bRf.jpg\'\n        }\n        for(a=[1,1],i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]]\n        phi = a[l+1]/a[l]\n\n        rects=Array(3).fill().map((v,i)=>{\n          a=[]\n          a=[...a, [-phi/2, -.5, 0]]\n          a=[...a, [phi/2,  -.5, 0]]\n          a=[...a, [phi/2,  .5,  0]]\n          a=[...a, [-phi/2, .5,  0]]\n          a=a.map(q=>{\n            X=q[0], Y=q[1], Z=q[2]\n            switch(i){\n              case 0: R(Math.PI/2,0,0); break\n              case 1: R(Math.PI/2,Math.PI/2,Math.PI/2); break\n              case 2: R(0,0,Math.PI/2); break\n            }\n            return [X,Y,Z]\n          })\n          return a\n        })\n        facets=[[[0,0], [2,2], [0,3]],[[1,2], [2,2], [0,3]],[[1,2], [2,2], [2,1]],[[1,2], [0,2], [2,1]],[[2,1], [0,1], [1,3]],[[2,1], [2,2], [1,3]],[[2,1], [0,1], [0,2]],[[1,2], [1,1], [0,2]],[[0,2], [0,1], [2,0]],[[0,2], [2,0], [1,1]],[[2,3], [2,0], [1,1]],[[2,3], [2,0], [1,0]],[[0,1], [2,0], [1,0]],[[0,1], [1,3], [1,0]],[[0,0], [1,3], [1,0]],[[0,0], [2,3], [1,0]],[[0,0], [2,3], [0,3]],[[1,1], [2,3], [0,3]],[[1,1], [1,2], [0,3]],[[0,0], [2,2], [1,3]]]\n\n        shp=[]\n        facets.map(n=>{\n          a=[]\n          n.map(q=>{\n            v=rects[q[0]][q[1]]\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            a=[...a, [X,Y,Z]]\n          })\n          shp=[...shp, a]\n        })\n\n        subdivide = () =>{\n          subdivisions=[]\n          new_shp=[]\n          shp.map((v,i,a)=>{\n            a=[]\n            v.map((q,j)=>{\n              X1=q[0]\n              Y1=q[1]\n              Z1=q[2]\n              X2=v[l=(j+1)%3][0]\n              Y2=v[l][1]\n              Z2=v[l][2]\n              mx=(X1+X2)/2\n              my=(Y1+Y2)/2\n              mz=(Z1+Z2)/2\n              a=[...a, [mx,my,mz]]\n            })\n            subdivisions=[...subdivisions, a]\n            v.map((q,j)=>{\n              b=[]\n              for(m=1;m--;){\n                b=[...b, [...v[(j+1)%3]], [...a[(m+j)%3]], [...a[(m+j+1)%3]]]\n              }\n              subdivisions=[...subdivisions, b]\n            })\n          })\n          shp=[...new_shp, ...subdivisions]      \n      }\n\n        subdivisions=3\n        for(let m = subdivisions; m--;)subdivide()\n        base_shp=JSON.parse(JSON.stringify(shp))\n\n        expansion=10+10*S(t*2)\n        ls=.1/(20+expansion)*270\n        shps=[]\n        shps=[...shps, ((base_shp.map(v=>{\n          v=v.map(q=>{\n            X1=q[0]\n            Y1=q[1]\n            Z1=q[2]\n            d=Math.hypot(X1,Y1,Z1)\n            X2=X1/d\n            Y2=Y1/d\n            Z2=Z1/d\n            X=(X2*expansion+(X1*(1-expansion)))*ls\n            Y=(Y2*expansion+(Y1*(1-expansion)))*ls\n            Z=(Z2*expansion+(Z1*(1-expansion)))*ls\n            return [X,Y,Z]\n          })\n          return v\n        })))]\n        expansion=S(t*4)*1-2\n        ls=1.5\n        shps=[...shps, ((base_shp.map(v=>{\n          v=v.map(q=>{\n            X1=q[0]\n            Y1=q[1]\n            Z1=q[2]\n            d=Math.hypot(X1,Y1,Z1)\n            X2=X1/d\n            Y2=Y1/d\n            Z2=Z1/d\n            X=(X2*expansion+(X1*(1-expansion)))*ls\n            Y=(Y2*expansion+(Y1*(1-expansion)))*ls\n            Z=(Z2*expansion+(Z1*(1-expansion)))*ls\n            r