    customJS.pop()\n                customJS = customJS.join(\'}\').split(\'t+=1/60\')[0]\n                console.log(customJS)\n                goCustom = true\n              }\n            }\n            let src = `function bypass_eval(){` + customJS + `}`\n            let script = document.createElement(\'script\')\n            script.innerHTML = src\n            document.body.appendChild(script)\n            bypass_eval()\n          }\n          if(goCustom && go___){\n            bypass_eval()\n          }\n        break\n      }\n      if(go___){\n        x.globalAlpha=1\n        x.drawImage(buffer___,0,0,c.width,c.height)\n      }else{\n        x.globalAlpha=1\n        x.fillStyle=\'#0008\'\n        x.fillRect(0,0,c.width,c.height)\n      }\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: #fff;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'overlay!', 145, 'whitehot robot', '2022-08-07 15:28:49', '[600348,600332,600304,600253,600252,600251,600248,600247]', 63, '', 0, 0),
(600350, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        src=`function bypass_eval(){`\n        src+=`if(!t){\n          R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n          Q=()=>[c.width/2+X/Z*600,c.height/2+Y/Z*600]\n          for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n          Rn=Math.random\n          iBc=225, iBr=4*3.5, iBir=10, iBv=.05, iGv=.4, G=80, leadS=4*50\n          B=Array(iBc).fill().map((v,i)=>{\n            X=(Rn()-.5)*G // S(p=Math.PI*2/iBc*i)*iBir\n            Y=(Rn()-.5)*G // C(p)*iBir\n            Z=(Rn()-.5)*.01\n            vx=S(p+=Math.PI/2)*iBv\n            vy=C(p)*iBv\n            vz=0\n            s=i?iBr:leadS\n            return [X,Y,Z,vx,vy,vz,s]\n          })\n          bg=new Image()\n          go=false\n          bg.onload=()=>{\n            go=true\n          }\n          bg.src=\'https://srmcgann.github.io/assets/1QnzB7.jpg\'\n        }\n        if(go){\n          x.globalAlpha=.2\n          x.drawImage(bg,0,0,c.width,c.height)\n          x.globalAlpha=1\n          x.fillStyle=\'#0002\'\n          x.fillRect(0,0,c.width,c.height)\n        } else {\n          x.fillStyle=\'#0