              }\n            })\n          }while((m<(i?2:4))&&!good);\n          R(Rl,Pt,Yw,1)\n          if(Z>0){\n            s=v[6]*450/(Z)\n            if(i){\n              s*=3\n              x.fillStyle=\'#4f82\'\n              l=Q()\n              x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n              x.fillStyle=\'#fff\'\n              s/=4\n              x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n            }else{\n              x.beginPath()\n              x.arc(...Q(),s,0,7)\n              x.fillStyle=i?\'#4f85\':\'#0ff3\'\n              x.fill()\n              x.strokeStyle=\'#fff4\'\n              x.lineWidth=Math.min(200, 3699/Z)\n              x.stroke()\n            }\n          }\n        })`\n        src+=`}`\n        let script = document.createElement(\'script\')\n        script.innerHTML = src\n        document.body.appendChild(script)\n        bypass_eval()\n      }\n\n      bypass_eval()\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'collider system (eval performance hit workaround)', 145, 'whitehot robot', '2022-08-07 19:11:28', '[600329,600304,600253,600252,600251,600248,600247]', 14, '', 0, 1),
(600351, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    updateVals=()=>{\n      iBv = +document.querySelector(\'#velocity\').value\n      iBs = +document.querySelector(\'#particleSpacing\').value\n      flockLeaders = +document.querySelector(\'#flockLeaders\').value\n      iBc = +document.querySelector(\'#flockCount\').value\n      reset()\n    }\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n        iBc=800,G=10,iBv=.08,iBs=.15,flockLeaders=5\n        reset=()=>{\n          B=Array(iBc).fill().map(v=>{\n            X=(Rn()-.5)*G\n            Y=(Rn()-.5)*G/1.88888887\n            Z=0\n            return [X,Y,Z,(Rn()-.5)*iBv,(Rn()-.5)*iBv,0]\n          })\n        }\n        reset()\n        bgimg = new Image()\n        bgimg.src = \'/proxy.php?url=https://srmcgann.github.io/assets/2h9kBr.jpg\'\n      }\n      x.globalAlpha=.3\n      x.drawImage(bgimg, 0, 0, c.width, c.height)\n      x.globalAlpha=1\n      x.fillStyle=\'#0004\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      //Rl=S(t/6)*2,Pt=C(t/2)*.25,Yw=S(t/2)*.25\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=G/2.1\n      x.globalAlpha=1\n      B.map((q,j)=>{\n        B.map((v,i)=>{\n          if(j!=i){\n            if((d=Math.hypot(e=v[0]-q[0],f=v[1]-q[1]))<iBs){\n              v[0]=q[0]+(tx=S(p=Math.atan2(e,f))*iBs)\n              v[1]=q[1]+(ty=C(p)*iBs)\n              v[3]+=tx/9\n              v[4]+=ty/9\n            }\n          }\n        })\n        if(j>flockLeaders){\n          B.map((v,i)=>{\n            if(i<=flockLeaders){\n              q[3]/=1.04\n              q[4]/=1.04\n              q[5]/=1.04\n              d=Math.hypot(e=q[0]-v[0],f=q[1]-v[1],g=q[2]-v[2])\n              p=Math.atan2(e,f)\n              q[3]-=S(p)*iBv/Math.max(300,(15+d**5))*14\n              q[4]-=C(p)*iBv/Math.max(300,(15+d**5))*14\n              q[5]+=(v[2]-q[2])/(1+d**3)\n              d=Math.hypot(q[3],q[4],q[5])\n              q[3]/=d/10\n              q[4]/=d/10\n              q[5]/=d/10\n              q[3]*=iBv/10\n              q[4]*=iBv/10\n            }\n          })\n          }else{\n            q[3]+=S(t+(n=Rn()-.5)*2)/9\n            q[4]+=C(t+n)/9\n            d=Math.hypot(q[3],q[4],q[5])\n            q[3]/=d\n            q[4]/=d\n            q[5]/=d\n            q[3]*=iBv\n            q[4]*=iBv\n        }\n      })\n      B.map((v,i)=>{\n        mind=6e6\n        X=v[0]+=v[3]\n        Y=v[1]+=v[4]\n        Z=v[2]+=v[5]\n        if(X<-G/2)X=v[0]=G/2\n        if(Y<-G/2/1.888887)Y=v[1]=G/2/1.888887\n        if(Z<-G/2)Z=v[2]=G/2\n        if(X>G/2)X=v[0]=-G/2\n        if(Y>G/2/1.888887)Y=v[1]=-G/2/1.888887\n        if(Z>G/2)Z=v[2]=-G/2\n\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n        l=Q()\n        s=Math.min(500, 300/(Z**1.25))\n        x.fillStyle=\'#8fc2\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=4\n        x.fillStyle=\'#fff\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      })\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n.inputDiv{\n  display: none;\n  position: absolute;\n  top: 0;\n  z-index: 10;\n  left: 0;\n  line-height: 1em;\n  margin: 10px;\n}\n.inputLabel{\n  color: #ff0;\n  font-size: 14px;\n}\ninput[type=text]{\n  background: #000;\n  border: #0003;\n  font-family: courier;\n  color: #0ff;\n  text-align: center;\n  margin: 0;\n  margin-bottom: 15px;\n  width: 30px;\n  border-bottom: 1px solid #4f82;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>\n<div class=\"inputDiv\">\n  <label for=\"flockLeaders\" class=\"inputLabel\">\n    leaders<br>\n    <input oninput=\"updateVals()\" id=\"flockLeaders\" type=\"text\" maxlength=\"2\" value=\"3\" placeholder=\"flock leaders\">\n  </label><br>\n\n  <label for=\"flockCount\" class=\"inputLabel\">\n    flock count<br>\n    <input oninput=\"updateVals()\" id=\"flockCount\" type=\"text\" maxlength=\"4\" value=\"400\" placeholder=\"flock count\">\n  </label><br>\n\n  <label for=\"velocity\" class=\"inputLabel\">\n    velocity<br>\n    <input oninput=\"updateVals()\" id=\"velocity\" type=\"text\" maxlength=\"3\" value=\".08\" placeholder=\"velocity\">\n  </label><br>\n\n  <label for=\"particleSpacing\" class=\"inputLabel\">\n    particle spacing<br>\n    <input oninput=\"updateVals()\" id=\"particleSpacing\" type=\"text\" maxlength=\"3\" value=\".2\" placeholder=\"particle spacing\">\n  </label><br>\n\n</div>', 'flocking algorithm (basic)', 145, 'whitehot robot', '2022-08-07 19:46:22', '[600252,600251,600248,600247]', 30, '', 0, 1),
(600352, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n\n\n//c.height=400\n\nfor(c.width|=j=n=960,x.fillStyle=\'#fff\',x.fillRect(0,0,c.width,c.height);j--;x.lineWidth=h/Z/Z,x.beginPath(x.stroke()))for(i=7;i--;x.lineTo(n+((j%50-25)/1.16+(v%2?.85:0)+S(p))/Z*n,(h=540)+(j%2-.5)/Z*n*3))Z=25+((v=j/50|0)-14-t*9%2)*1.5+C(p=1.05*i)\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'dweet reboot (#25908)', 145, 'whitehot robot', '2022-08-07 21:55:17', '[600340,600304,600253,600252,600251,600248,600247]', 22, '', 0, 1),
