(600371, '', '', '', '<!DOCTYPE html>\n<html>\n<head>\n	<meta charset=\"utf-8\">\n	<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n	<title></title>\n</head>\n<body>\n	stuff : <br>\n<input id=\'Vol\' type=\"range\" min=\"10\" max=\"100\" step= 10 orient=\"vertical\"  />VOL\n<input id=\'low\' type=\"range\" min=\"10\" max=\"100\" step= 10 orient=\"vertical\"  />Low\n<input id=\'mid\' type=\"range\" min=\"10\" max=\"100\" step= 10 orient=\"vertical\" />Mids\n<input id=\'hig\' type=\"range\" min=\"10\" max=\"100\" step= 10 orient=\"vertical\" />HIGH!<br>\n<button onclick=\"gencontext()\" >Pressy</button>\n</body>\n<script type=\"text/javascript\">\n	function playByteArray( bytes ) {\n    var buffer = new Uint8Array( bytes.length );\n    buffer.set( new Uint8Array(bytes), 0 );\n\n    context.decodeAudioData(buffer.buffer, play);\n}\n\nfunction play( audioBuffer ) {\n    var source = context.createBufferSource();\n\n    source.buffer = audioBuffer;\n    source.connect( context.destination );\n    source.start(0);\n}\n\nlet  audioCtx ; //= new (window.AudioContext || window.webkitAudioContext)();\n\n// Stereo\nvar channels = 2;\n\n function gencontext(){\naudioCtx = new AudioContext();\nconst frameCount = audioCtx.sampleRate * 2.0;\nvar myArrayBuffer = audioCtx.createBuffer(channels, frameCount, audioCtx.sampleRate);\n  \n var Vol= document.getElementById(\'Vol\').value/100 ; \n  for (let channel = 0; channel < channels; channel++) \n  {\n  \n   const nowBuffering = myArrayBuffer.getChannelData(channel);\n   for (let i = 0; i < frameCount; i++) \n   {\n   		nowBuffering[i]  = Math.sin( 440 / 44000 * i *3.141 * 2 )*Vol ; \n    	// nowBuffering[i]  = Math.random() * 0.02 - 0.01;\n   }\n  }\n\n  const source = audioCtx.createBufferSource();// set the buffer in the AudioBufferSourceNode\n  source.buffer = myArrayBuffer;// connect the AudioBufferSourceNode to the\n  source.connect(audioCtx.destination);// destination so we can hear the sound\n  source.start();// start the source playing\n  //I stole codes here : https://developer.mozilla.org/en-US/docs/Web/API/BaseAudioContext/createBufferSource , https://mdn.github.io/webaudio-examples/audio-buffer/\n }\n</script>\n</html>', 'password codez', 145, 'whitehot robot', '2022-08-08 18:37:28', '', 60, '', 0, 1),
