(600382, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        iSTc=2e3,iSTd=500\n        ST=Array(iSTc).fill().map(v=>{\n          X=(Rn()-.5)*iSTd\n          Y=(Rn()-.5)*iSTd\n          Z=(Rn()-.5)*iSTd\n          return [X,Y,Z]\n        })\n        Tetrahedron=ls=>{\n          let ret=[]\n          let a = []\n          let theta=1.2217304763960306\n          for(let i=3;i--;){\n            X=S(p=Math.PI*2/3*i)\n            Y=C(p)+.5\n            Z=0\n            R(0,-theta/2,0)\n            a=[...a, [X,Y,Z]]\n          }\n          ret=[...ret, a]\n          b=JSON.parse(JSON.stringify(a))\n          ax=ay=az=0\n          b.map(v=>{\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            R(0,theta,0)\n            v[0]=X\n            v[1]=Y\n            v[2]=Z\n          })\n          ret=[...ret, b]\n          ct=0\n          ret.map(v=>{\n            v.map(q=>{\n              ax+=q[0]\n              ay+=q[1]\n              az+=q[2]\n              ct++\n            })\n          })\n          ax/=ct\n          ay/=ct\n          az/=ct\n          ret.map(v=>{\n            v.map(q=>{\n              q[0]-=ax*1.5\n              q[1]-=ay*1.5\n              q[2]-=az*1.5\n            })\n          })\n\n          b=JSON.parse(JSON.stringify(ret))\n          b.map(v=>{\n            v.map(q=>{\n              X=q[0]\n              Y=q[1]\n              Z=q[2]\n              R(0,Math.PI,Math.PI/2)\n              q[0]=X\n              q[1]=Y\n              q[2]=Z\n            })\n          })\n          ret=[...ret, ...b]\n          \n          ret.map(v=>{\n            v.map(q=>{\n              X=q[0]\n              Y=q[1]\n              Z=q[2]\n              R(0,.96,0)\n              R(0,Math.PI,0)\n              q[0]=X\n              q[1]=Y\n              q[2]=Z\n              d=Math.hypot(...q)\n              q[0]/=d\n              q[1]/=d\n              q[2]/=d\n              q[0]*=ls\n              q[1]*=ls\n              q[2]*=ls\n            })\n          })\n          return ret\n        }\n        \n        Octahedron=ls=>{\n          ret = []\n          a=[]\n          for(i=4;i--;){\n            X1=S(p=Math.PI*2/4*i+Math.PI/4)\n            Y1=C(p)\n            Z1=0\n            X2=S(p=Math.PI*2/4*(i+1)+Math.PI/4)\n            Y2=C(p)\n            Z2=0\n            X3=0\n            Y3=0\n            Z3=1\n            a=[\n              [X1,Y1,Z1],\n              [X2,Y2,Z2],\n              [X3,Y3,Z3]\n            ]\n            ret=[...ret, a]\n            a=[\n              [X1,Y1,-Z1],\n              [X2,Y2,-Z2],\n              [X3,Y3,-Z3]\n            ]\n            ret=[...ret, a]\n          }\n          ret.map(v=>{\n            v.map(q=>{\n              d=Math.hypot(...q)\n              q[0]/=d\n              q[1]/=d\n              q[2]/=d\n              q[0]*=ls\n              q[1]*=ls\n              q[2]*=ls\n            })\n          })\n          return ret\n        }\n        \n        Cube=ls=>{\n          let ret=[]\n          for(j=6;j--;ret=[...ret,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-ls:ls),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n          return ret\n          ret.map(v=>{\n            v.map(q=>{\n              d=Math.hypot(...q)\n              q[0]/=d\n              q[1]/=d\n              q[2]/=d\n              q[0]*=ls\n              q[1]*=ls\n              q[2]*=ls\n            })\n          })\n        }\n        \n        Icosahedron=ls=>{\n          let a=[1,1],ret=[]\n          let b\n          for(i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]];\n          let phi=a[l]/a[l-1]\n          a=[[[-phi,-1,0],[phi,-1,0],[phi,1,0],[-phi,1,0]],[[0,-phi,-1],[0,phi,-1],[0,phi,1],[0,-phi,1]],[[-1,0,-phi],[-1,0,phi],[1,0,phi],[1,0,-phi]]]\n          let ico=[[[0,1],[1,0],[1,3]],[[0,1],[2,3],[1,0]],[[2,0],[2,3],[1,0]],[[0,1],[2,3],[0,2]],[[1,1],[2,3],[0,2]],[[1,1],[2,3],[2,0]],[[1,1],[1,2],[0,2]],[[0,1],[2,2],[0,2]],[[0,0],[1,0],[2,0]],[[2,0],[0,3],[0,0]],[[1,1],[1,2],[0,3]],[[1,1],[2,0],[0,3]],[[0,1],[1,3],[2,2]],[[1,3],[2,1],[2,2]],[[2,1],[0,3],[1,2]],[[2,1],[0,0],[1,3]],[[1,2],[2,2],[2,1]],[[2,2],[1,2],[0,2]],[[0,3],[2,1],[0,0]],[[1,3],[1,0],[0,0]]]\n          ico.map((v,i)=>{\n            b=[]\n            v.map(q=>{\n              t1=q[0],t2=q[1]\n              X=a[t1][t2][0],Y=a[t1][t2][1],Z=a[t1][t2][2]\n              b=[...b, [X,Y,Z]]\n            })\n            ret=[...ret, b]\n          })\n          ret.map(v=>{\n            v.map(q=>{\n              d=Math.hypot(...q)\n              q[0]/=d\n              q[1]/=d\n              q[2]/=d\n              q[0]*=ls\n              q[1]*=ls\n              q[2]*=ls\n            })\n          })\n          return ret\n        }\n\n        Dodecahedron=ls=>{\n          let ret=[]\n          let sd=5\n          let a=[], b=[]\n          mind=6e6\n          for(let i=sd;i--;){\n            X=S(p=Math.PI*2/sd*i)\n            Y=C(p)\n            Z=0\n            if(Y<mind)mind=Y\n            a = [...a, [X,Y,Z]]\n          }\n          a=a.map(v=>{\n            X=v[0]\n            Y=v[1]-=mind\n            Z=v[2]\n            R(0,.5535735,0)\n            return [X,Y,Z]\n          })\n          \n          ret = [...ret, a]\n          b=JSON.parse(JSON.stringify(a)).map(v=>{\n            d=Math.hypot(v[0],v[1])\n            v[0]=S(p=Math.atan2(v[0],v[1])+Math.PI)*d\n            v[1]=C(p)*d\n            return v\n          })\n          ret = [...ret, b]\n          \n          ret.map(v=>{\n            v.map(q=>{\n              if(q[2]<mind)mind=q[2]\n            })\n          })\n          ret.map(v=>{\n            v.map(q=>{\n              q[2]+=ang=1.538840639715\n            })\n          })\n          b=JSON.parse(JSON.stringify(ret)).map(v=>{\n            v.map(q=>{\n              X=q[0]\n              Y=q[1]\n              Z=q[2]\n              R(Math.PI,0,Math.PI)\n              q[0]=X\n              q[1]=Y\n              q[2]=Z\n            })\n            return v\n          })\n          e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n          \n          b=JSON.parse(JSON.stringify(ret)).map(v=>{\n            v.map(q=>{\n              X=q[0]\n              Y=q[1]\n              Z=q[2]\n              R(0,Math.PI/2,Math.PI/2)\n              q[0]=X\n              q[1]=Y\n              q[2]=Z\n            })\n            return v\n          })\n          ret = [...ret, ...b]\n\n          b=JSON.parse(JSON.stringify(e)).map(v=>{\n            v.map(q=>{\n              X=q[0]\n              Y=q[1]\n              Z=q[2]\n              R(Math.PI/2,0,Math.PI/2)\n              q[0]=X\n              q[1]=Y\n              q[2]=Z\n            })\n            return v\n          })\n          ret = [...ret, ...b]\n          \n          ret.map(v=>{\n            v.map(q=>{\n              d=Math.hypot(...q)\n              q[0]/=d\n              q[1]/=d\n              q[2]/=d\n              q[0]*=ls\n              q[1]*=ls\n              q[2]*=ls\n            })\n          })\n          return ret\n        }\n\n        x.lineJoin=x.lineCap=\'round\'\n        \n        DrawSolid=(dod, sx, sy, sz, strokeStyle, fillStyle, useFill, globalAlpha) => {\n          tj=x.lineJoin\n          x.lineJoin=x.lineCap=\'round\'\n          dod.map(v=>{\n            x.beginPath()\n            v.map((q,j)=>{\n              X=q[0]+sx+eX\n              Y=q[1]+sy+eY\n              Z=q[2]+sz+eZ\n              R(Rl,Pt,Yw,1)\n              if(Z>0)x.lineTo(...Q())\n            })\n            x.closePath()\n            x.lineWidth=Math.min(200,2e3/(Z**1.25))\n            x.globalAlpha=.3*globalAlpha\n            x.strokeStyle=strokeStyle\n            x.stroke()\n            x.lineWidth/=7\n            x.lineWidth=Math.max(x.lineWidth, 1)\n            x.globalAlpha=1*globalAlpha\n            x.stroke()\n          })\n\n          if(useFill){\n            dod.map(v=>{\n              x.beginPath()\n              v.map((q,j)=>{\n                X=q[0]+sx+eX\n                Y=q[1]+sy+eY\n                Z=q[2]+sz+eZ\n                R(Rl,Pt,Yw,1)\n                if(Z>0)x.lineTo(...Q())\n              })\n              x.globalAlpha=.6*globalAlpha\n              x.fillStyle=fillStyle\n              x.fill()\n            })\n          }\n          x.lineJoin=x.lineCap=tj\n        }\n        setupListeners=()=>{\n          c.onclick=()=>{\n            c.requestPointerLock()\n            c.requestFullscreen()\n          }\n          keystates=Array(255).fill(0)\n          mx=my=0\n          shooting=false\n          window.onmousedown=e=>{\n            if(e.which==1){\n              shooting=true\n            }\n          }\n          window.onmouseup=e=>{\n            if(e.which==1){\n              shooting=false\n            }\n          }\n          window.onmousemove=e=>{\n            e.stopPropagation()\n            e.preventDefault()\n            mx+=e.movementX\n            my+=e.movementY\n            Yw-=e.movementX/300\n            Pt-=e.movementY/300\n          }\n          window.onkeydown=e=>{\n            console.log(e.keyCode)\n            e.stopPropagation()\n            e.preventDefault()\n            keystates[e.keyCode]=1\n            if(e.keyCode==32 && grounded){\n              eYv+=jumpHeight\n            }\n            if(e.keyCode==70){\n              fly=!fly\n            }\n          }\n          window.onkeyup=e=>{\n            keystates[e.keyCode]=0\n            if(e.keyCode==87 || e.keyCode==38 || e.keyCode==40 || e.keyCode==65){\n              bobv=0\n            }\n          }\n        }\n        setupListeners()\n        R=(Rl,Pt,Yw,m)=>{\n          X=S(p=(A=(M=Math).atan2)(X,Z)+Yw)*(d=(H=M.hypot)(X,Z))\n          Z=C(p)*d\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m)X+=oX,Y+=oY,Z+=oZ\n        }\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[(j+2)%3]*(l=j<3?-1:1),a[(j+0)%3]*l,a[(j+1)%3]*l]]\n\n        rw=40,cl=40,sp=2**.5*1\n        fly=false,jumpHeight=2\n        runfactor=3,grounded=false\n        B=Array(rw*cl).fill().map((v,i)=>{\n          X=((i%cl)-cl/2+.5)*sp\n          Y=1\n          Z=((i/cl|0)-rw/2+.5)*sp\n          return [X,Y,Z]\n        })\n        getFloor=(tx,tz)=>{\n          return S(tx/6+t/2)*C(tz/6+2*(S(t/6)*2))*4\n        }\n        Els=4\n        mv=.05\n        rv=.015\n        bobv=0\n        floor=0\n        eXv=eYv=eZv=0\n        Rl=0,Pt=0,Yw=0\n        eX=0,eY=0,eZ=0\n        oeX=0,oeY=0,oeZ=0\n        oX=0,oY=0,oZ=0\n        Rlv=Ptv=Ywv=0\n        spv=.2\n        P=[],lb=true,bv=-2,P2=[],P3=[]\n        sparks=(tx,ty,tz)=>{\n          for(let m=20;m--;){\n            P2=[...P2,[tx,ty,tz,(Rn()-.5)*spv,(Rn()-.5)*spv,(Rn()-.5)*spv,0]]\n          }\n        }\n        bigSparks=(tx,ty,tz)=>{\n          for(let m=300;m--;){\n            P3=[...P3,[tx,ty,tz,(Rn()-.5)*spv*16,(Rn()-.5)*spv*16,(Rn()-.5)*spv*16,0]]\n          }\n        }\n        spawnBullet=()=>{\n          bxv=S(Yw)*S(Pt+Math.PI/2)*bv\n          byv=-C(Pt+Math.PI/2)*bv\n          bzv=-C(Yw)*S(Pt+Math.PI/2)*bv\n          bx=-eX+S(Yw+Math.PI/2)*(lb?1:-1)/1+bxv*.1\n          by=-eY-0-S(t*16*(keystates[16]?2:1)*(fly?0:bobv))/10+byv*.1\n          bz=-eZ-C(Yw+Math.PI/2)*(lb?1:-1)/1+bzv*.1\n          P=[...P,[bx,by,bz,bxv,byv,bzv,0]]\n          lb=!lb\n        }\n        maxEnemies=3\n        Enemies=[]\n        spawnEnemy=()=>{\n          switch(Rn()*5|0){\n            case 0: shp = Tetrahedron(Els); break\n            case 1: shp = Cube(Els); break\n            case 2: shp = Octahedron(Els); break\n            case 3: shp = Icosahedron(Els); break\n            case 4: shp = Dodecahedron(Els); break\n          }\n          tx=-eX+(Rn()-.5)*100\n          ty=-3\n          tz=-eZ+(Rn()-.5)*100\n          Enemies=[...Enemies, [shp,tx,ty,tz,100]]\n        }\n      }\n      \n      \n      if(!((t*60|0)%60) && Enemies.length<maxEnemies) spawnEnemy()\n      \n      x.globalAlpha=1\n      x.fillStyle=\'#000c\'\n      x.fillRect(0,0,c.width,c.height)\n      //x.lineJoin=x.lineCap=\'round\'\n      \n\n      ST.map(v=>{\n        X=v[0]+eX\n        Y=v[1]+eY\n        Z=v[2]+eZ\n        if(v[0]+eX>iSTd/2)v[0]-=iSTd\n        if(v[0]+eX<-iSTd/2)v[0]+=iSTd\n        if(v[1]+eY>iSTd/2)v[1]-=iSTd\n        if(v[1]+eY<-iSTd/2)v[1]+=iSTd\n        if(v[2]+eZ>iSTd/2)v[2]-=iSTd\n        if(v[2]+eZ<-iSTd/2)v[2]+=iSTd\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          x.globalAlpha=1/(1+Z**6/1e13)*Math.min(1,(Z/100)**4)\n          s=Math.min(1e3, 3e4/(Z**1.5))\n          x.fillStyle=\'#fff2\'\n          l=Q()\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          s/=4\n          x.fillStyle=\'#fff\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        }\n      })\n      x.globalAlpha=1\n\n      Enemies.map(v=>{\n        DrawSolid(v[0], v[1], v[2], v[3], `hsla(1,99%,${50+v[4]/2}%,.5)`, `hsla(1,99%,${50+v[4]/2}%,.2)`, 1, 1)\n      })\n\n\n      P2=P2.filter(v=>v[6]<100)\n      Enemies.map(v=>{\n        if(v[4]<1) bigSparks(v[1],v[2],v[3])\n      })\n      Enemies=Enemies.filter(v=>{\n        return H(-eX-v[1],-eY-v[2],-eZ-v[3])<200 && v[4]>0\n      })\n      P2.map(v=>{\n        X=v[0]+=v[3]\n        Y=v[1]+=v[4]\n        Z=v[2]+=v[5]\n        X+=eX\n        Y+=eY\n        Z+=eZ\n        v[6]++\n        R(Rl,Pt,Yw,1)\n        x.fillStyle=`hsla(${v[6]*1},99%,50%,${1/(1+v[6]**1.5/99)})`\n        s=Math.min(500,800/(Z**1.2))/(1+v[6]**1.5/299)\n        l=Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=4\n        x.fillStyle=\'#fff\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)        \n      })\n      P3.map(v=>{\n        X=v[0]+=v[3]\n        Y=v[1]+=v[4]\n        Z=v[2]+=v[5]\n        X+=eX\n        Y+=eY\n        Z+=eZ\n        v[6]++\n        R(Rl,Pt,Yw,1)\n        x.fillStyle=`hsla(${v[6]*1-20},99%,${Math.max(40,100-v[6]*2)}%,${1/(1+v[6]**1.5/199)})`\n        s=Math.min(1500,2800/(Z**1.2))/(1+v[6]**1.5/299)\n        l=Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=4\n        x.fillStyle=\'#fff\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)        \n      })\n      P=P.filter((v,i)=>v[6]<100)\n      P.map(v=>{\n        v[6]++\n        X=v[0]+=v[3]\n        Y=v[1]+=v[4]\n        Z=v[2]+=v[5]\n        X+=eX\n        Y+=eY\n        Z+=eZ\n        R(Rl,Pt,Yw,0)\n        l=Q()\n        x.fillStyle=\'#8fc2\'\n        s=Math.min(1500, 1200/(Z**1.15))\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=3\n        x.fillStyle=\'#8f86\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=3\n        x.fillStyle=\'#fff\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        Enemies.map(q=>{\n          if(v[6]<100&&(d=H(v[0]-q[1],v[1]-q[2],v[2]-q[3]))<Els){\n            v[6]=6e6\n            sparks(...v)\n            q[4]-=2\n          }\n        })\n        if(v[1]>-getFloor(v[0],v[2])+1.5){\n          v[6]=6e6\n          sparks(...v)\n        }\n      })\n      if(shooting){\n        if(!((t*60|0)%1)){\n          spawnBullet()\n        }\n      }\n      keystates.map((v,i,a)=>{\n        if((grounded || fly)&& v && (i==87 || i==38)){ // w or up-arrow\n          eXv+=S(Yw)*mv*(a[16]?runfactor:1)*(fly?S(Pt+Math.PI/2):1)\n          eYv-=(fly?C(Pt+Math.PI/2):0)*mv*(a[16]?runfactor:1)\n          eZv-=C(Yw)*mv*(a[16]?runfactor:1)*(fly?S(Pt+Math.PI/2):1)\n          bobv=1\n        }\n        if((grounded || fly) && v && (i==65 || i==37)){ // a or left-arrow\n          eXv+=S(Yw+Math.PI/2)*mv*(a[16]?runfactor:1)*(fly?S(Pt+Math.PI/2):1)\n          eYv-=(fly?C(Pt+Math.PI/2):0)*mv*(a[16]?runfactor:1)\n          eZv-=C(Yw+Math.PI/2)*mv*(a[16]?runfactor:1)*(fly?S(Pt+Math.PI/2):1)\n          //Ywv+=rv\n        }\n        if((grounded || fly) && v && (i==83 || i==40)){ // s or down-arrow\n          bobv=1\n          eXv-=S(Yw)*mv*(a[16]?runfactor:1)*(fly?S(Pt+Math.PI/2):1)\n          eYv+=(fly?S(Pt+Math.PI/2):0)*mv*(a[16]?runfactor:1)\n          eZv+=C(Yw)*mv*(a[16]?runfactor:1)*(fly?S(Pt+Math.PI/2):1)\n        }\n        if((grounded || fly) && v && (i==68 || i==39)){ // d or right-arrow\n          eXv-=S(Yw+Math.PI/2)*mv*(a[16]?runfactor:1)*(fly?S(Pt+Math.PI/2):1)\n          eYv+=(fly?C(Pt+Math.PI/2):0)*mv*(a[16]?runfactor:1)\n          eZv+=C(Yw+Math.PI/2)*mv*(a[16]?runfactor:1)*(fly?S(Pt+Math.PI/2):1)\n          //Ywv-=rv\n        }\n      })\n      if(grounded || fly) eXv/=1.1\n      eYv/=1.02\n      if(grounded || fly) eZv/=1.1\n      bobv/=1.2\n      eX+=eXv\n      eY+=eYv\n      eZ+=eZv\n      oeX=oX\n      oeY=oY\n      oeZ=oZ\n      Rlv/=1.2\n      Ptv/=1.2\n      Ywv/=1.2\n      Rl+=Rlv\n      Pt+=Ptv\n      Yw+=Ywv\n      if(!grounded && !fly) eYv-=.05\n      eY=Math.max(getFloor(-eX, -eZ)-.5, eY)\n      grounded = Math.abs(eY-getFloor(-eX, -eZ)+.5)<.5\n\n      B.map(v=>{\n        if((-eX-v[0])<-cl/2*sp)v[0]-=cl*sp*2\n        if((-eX-v[0])>cl/2*sp)v[0]+=cl*sp\n        if((-eZ-v[2])<-rw/2*sp)v[2]-=rw*sp*2\n        if((-eZ-v[2])>rw/2*sp)v[2]+=rw*sp\n        tx=v[0]+eX\n        ty=v[1]+eY+1.5//+S(t*16*(keystates[16]?2:1)*(fly?0:bobv))/10\n        tz=v[2]+eZ\n\n        CB.map((q,j)=>{\n          if(j<4){\n            if(!(j%4))x.beginPath()\n            X=q[0]+tx\n            Z=q[2]+tz\n            Y=q[1]*.3+ty+(l=-getFloor(X-eX,Z-(eZ)))\n            R(Rl,Pt,Yw,0)\n            if(Z>0)x.lineTo(...Q())\n            if(j%4==3){\n              x.globalAlpha=1/(1+H(-eX-v[0],-eZ-v[2])**8/9999999999)\n              x.lineWidth=Math.min(100, 200/(Z**1.5))\n              x.fillStyle=x.strokeStyle=`hsla(${(l)*50/2+q[1]*200},99%,${50}%,.3)`\n              x.closePath()\n              x.stroke()\n              x.fill()\n            }\n          }\n        })\n      })\n      x.globalAlpha=1\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'Y-axis / object CD on uneven surfaces', 145, 'whitehot robot', '2022-08-13 15:51:32', '[600254,600253,600252,600251,600248,600247]', 67, '', 0, 0),
