           X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(0,0,t*5)\n                q[0]=X\n                q[1]=Y\n                q[2]=Z\n                d=Math.hypot(...q)\n                q[0]/=d\n                q[1]/=d\n                q[2]/=d\n                q[0]*=ls\n                q[1]*=ls\n                q[2]*=ls\n              })\n            })\n            return ret\n          }\n          \n          Icosahedron=ls=>{\n            let a=[1,1],ret=[]\n            let b\n            for(i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]];\n            let phi=a[l]/a[l-1]\n            a=[[[-phi,-1,0],[phi,-1,0],[phi,1,0],[-phi,1,0]],[[0,-phi,-1],[0,phi,-1],[0,phi,1],[0,-phi,1]],[[-1,0,-phi],[-1,0,phi],[1,0,phi],[1,0,-phi]]]\n            let ico=[[[0,1],[1,0],[1,3]],[[0,1],[2,3],[1,0]],[[2,0],[2,3],[1,0]],[[0,1],[2,3],[0,2]],[[1,1],[2,3],[0,2]],[[1,1],[2,3],[2,0]],[[1,1],[1,2],[0,2]],[[0,1],[2,2],[0,2]],[[0,0],[1,0],[2,0]],[[2,0],[0,3],[0,0]],[[1,1],[1,2],[0,3]],[[1,1],[2,0],[0,3]],[[0,1],[1,3],[2,2]],[[1,3],[2,1],[2,2]],[[2,1],[0,3],[1,2]],[[2,1],[0,0],[1,3]],[[1,2],[2,2],[2,1]],[[2,2],[1,2],[0,2]],[[0,3],[2,1],[0,0]],[[1,3],[1,0],[0,0]]]\n            ico.map((v,i)=>{\n              b=[]\n              v.map(q=>{\n                t1=q[0],t2=q[1]\n                X=a[t1][t2][0],Y=a[t1][t2][1],Z=a[t1][t2][2]\n                b=[...b, [X,Y,Z]]\n              })\n              ret=[...ret, b]\n            })\n            ret.map(v=>{\n              v.map(q=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(0,0,t*5)\n                q[0]=X\n                q[1]=Y\n                q[2]=Z\n                d=Math.hypot(...q)\n                q[0]/=d\n                q[1]/=d\n                q[2]/=d\n                q[0]*=ls\n                q[1]*=ls\n                q[2]*=ls\n              })\n            })\n            return ret\n          }\n\n          Dodecahedron=ls=>{\n            let ret=[]\n            let sd=5\n            let a=[], b=[]\n            mind=6e6\n            for(let i=sd;i--;){\n              X=S(p=Math.PI*2/sd*i)\n              Y=C(p)\n              Z=0\n              if(Y<mind)mind=Y\n              a = [...a, [X,Y,Z]]\n            }\n            a=a.map(v=>{\n              X=v[0]\n              Y=v[1]-=mind\n              Z=v[2]\n              R(0,.5535735,0)\n              return [X,Y,Z]\n            })\n            \n            ret = [...ret, a]\n            b=JSON.parse(JSON.stringify(a)).map(v=>{\n              d=Math.hypot(v[0],v[1])\n              v[0]=S(p=Math.atan2(v[0],v[1])+Math.PI)*d\n              v[1]=C(p)*d\n              return v\n            })\n            ret = [...ret, b]\n            \n            ret.map(v=>{\n              v.map(q=>{\n                if(q[2]<mind)mind=q[2]\n              })\n            })\n            ret.map(v=>{\n              v.map(q=>{\n                q[2]+=ang=1.538840639715\n              })\n            })\n            b=JSON.parse(JSON.stringify(ret)).map(v=>{\n              v.map(q=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(Math.PI,0,Math.PI)\n                q[0]=X\n                q[1]=Y\n                q[2]=Z\n              })\n              return v\n            })\n            e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n            \n            b=JSON.parse(JSON.stringify(ret)).map(v=>{\n              v.map(q=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(0,Math.PI/2,Math.PI/2)\n                q[0]=X\n                q[1]=Y\n                q[2]=Z\n              })\n              return v\n            })\n            ret = [...ret, ...b]\n\n            b=JSON.parse(JSON.stringify(e)).map(v=>{\n              v.map(q=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(Math.PI/2,0,Math.PI/2)\n                q[0]=X\n                q[1]=Y\n                q[2]=Z\n              })\n              return v\n            })\n            ret = [...ret, ...b]\n            \n            ret.map(v=>{\n              v.map(q=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(0,0,t*5)\n                q[0]=X\n                q[1]=Y\n                q[2]=Z\n                d=Math.hypot(...q)\n                q[0]/=d\n                q[1]/=d\n                q[2]/=d\n                q[0]*=ls\n                q[1]*=ls\n                q[2]*=ls\n              })\n            })\n            return ret\n          }\n\n          rw=20,cl=20,sp=70\n          B=Array(cl*rw).fill().map((v,i)=>{\n            X=((i%cl)-cl/2+.5)*sp\n            Y=0\n            Z=((i/cl|0)-rw/2+.5)*sp\n            return [X,Y,Z]\n          })\n          GG=()=>{\n            return 0-Math.min(0,S(t*8-1.8)*420)/(1+Math.hypot(X,Z)**3/20000000)\n          }\n          switch(Rn()*5|0){\n            case 0: chosenShape = Tetrahedron; break\n            case 1: chosenShape = Octahedron; break\n            case 2: chosenShape = Cube; break\n            case 3: chosenShape = Dodecahedron; break\n            case 4: chosenShape = Icosahedron; break\n          }\n        }\n\n        x.fillStyle=\'#0008\'\n        x.fillRect(0,0,c.width,c.height)\n        x.lineJoin=x.lineCap=\'round\'\n\n        oX=0, oY=0, oZ=800+S(t*2)*300\n        Rl=t/3,Pt=-1+S(t)/1.0,Yw=S(t/4)*3\n\n        B.map(v=>{\n          x.beginPath()\n          X=v[0],Z=v[2],Y=v[1]+GG(),R(Rl,0,Yw,0),R(0,Pt,0,1);if(Z>0)x.lineTo(...Q())\n          X=v[0]+sp,Z=v[2],Y=v[1]+GG(),R(Rl,0,Yw,0),R(0,Pt,0,1);if(Z>0)x.lineTo(...Q())\n          X=v[0]+sp,Z=v[2]+sp,Y=v[1]+GG()\n          a=H(X,Z)\n          R(Rl,0,Yw,0),R(0,Pt,0,1);if(Z>0)x.lineTo(...Q())\n          x.globalAlpha=1/(1+a**9/599999999999999999999999)\n          x.lineWidth=Math.min(200, 4e5/(Z**1.5))\n          \n          x.strokeStyle=\'#60f4\'\n          x.stroke()\n          x.lineWidth/=4\n          x.strokeStyle=\'#fffc\'\n          x.stroke()\n        })\n        B.map(v=>{\n          X=v[0]\n          Z=v[2]\n          Y=v[1]+GG()\n          a=H(X,Z)\n          x.globalAlpha=1/(1+a**9/599999999999999999999999)\n          R(Rl,0,Yw,0)\n          R(0,Pt,0,1)\n          l=Q()\n          s=Math.min(500,2e5/(Z**1.25))\n          x.fillStyle=\'#0fc3\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          s/=3\n          x.fillStyle=\'#fff\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        })\n\n        dodec=chosenShape(220+Math.abs(S(t*4))*50**2/20)\n        DrawSolid(dodec, -2, 260-Math.abs(S(t*4))*900, 0, `hsla(${t*20},99%,50%,.8)`, `hsla(${t*20},99%,50%,.1)`, \'#fff\', 1, .2)\n        x.globalAlpha=1\n\n        t+=1/60\n        requestAnimationFrame(Draw)\n      }\n      Draw()\n', 'body,html{\n  background: linear-gradient(46deg,#201, #000, #102);\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'the physical world', 145, 'whitehot robot', '2022-08-13 18:38:39', '[600381,600253,600252,600251,600248,600247]', 62, 'https://code.dweet.net/thumbs/ccd96b7ac5c6fde8e16ee0001c08e418.jpg', 10, 0),
(600385, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/1xo7om.gif);\n  background-size: 100% 100%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'the physical world (gif)', 145, 'whitehot robot', '2022-08-13 19:34:29', '[600380,600367,600366,600364,600363,600360,600359,600358,600357,600356,600355,600354,600353,600288,600253,600252,600251,600248,600247]', 68, '', 0, 0),
(600387, '', '\n      c=document.querySelector(\'#c\')\n      x=c.getContext(\'2d\')\n      S=Math.sin\n      C=Math.cos\n      t=playing=0\n      window.onclick=()=>{if(!playing)mp3.play()}\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n      Draw=()=>{\n        if(!t){\n          mp3 = new Audio()\n          mp3.loop=true\n          mp3.onplaying=()=>{playing=true}\n          mp3.oncanplay=()=>{go=true;if(!playing)mp3.play()}\n          mp3.src=\'https://audiocloud.rotoblaster.com/audio/92accddb0055a6f7103030b91d1b5c62.MP3\'\n          Rn=Math.random\n          bg=new Image()\n          go=playing=false\n          bg.onload=()=>{\n            go=true\n          }\n          bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/25HlU2.jpg\'\n          cvrs=300\n          R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n          Q=()=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n          for(phi=[1,1],j=0;j<25;j++)phi.push(phi[j]+phi[j+1])\n          phi=phi[l=phi.length-1]/phi[l-1]\n          DR=(tx,ty,scl,rl,mx,my,mz)=>{\n            d4=0\n            t2=20+S(t/2.5)*20+t*8\n            V=(((t2%4)+2)**2.75)/8\n            ms=(1+V/2)\n            x.beginPath()\n            ox+=-((t2%4)**.29)*1.82\n            oy+=-(t2%4)/32\n\n            X=-phi/2*scl+tx,Y=.5*scl+ty,Z=0\n            R(rl,0,0,0)\n            X+=ox,Y+=oy\n            d4+=H(X*=ms,Y*=ms)\n            X+=mx,Y+=my,Z+=mz\n            R(Rl,Pt,Yw,1)\n            l=Q(),lz1=Z\n            if(Z>0)x.lineTo(lx1=l[0],ly1=l[1])\n            \n            X=-phi/2*scl+tx,Y=-.5*scl+ty,Z=0\n            R(rl,0,0,0)\n            X+=ox,Y+=oy\n            d4+=H(X*=ms,Y*=ms)\n            X+=mx,Y+=my,Z+=mz\n            R(Rl,Pt,Yw,1)\n            l=Q(),lz2=Z\n            if(Z>0)x.lineTo(lx2=l[0],ly2=l[1])\n            \n            X=phi/2*scl+tx,Y=-.5*scl+ty,Z=0\n            R(rl,0,0,0)\n            X+=ox,Y+=oy\n            d4+=H(X*=ms,Y*=ms)\n            X+=mx,Y+=my,Z+=mz\n            R(Rl,Pt,Yw,1)\n            l=Q(),lz3=Z\n            if(Z>0)x.lineTo(lx3=l[0],ly3=l[1])\n            \n            X=phi/2*scl+tx,Y=.5*scl+ty,Z=0\n            R(rl,0,0,0)\n            X+=ox,Y+=oy\n            d4+=H(X*=ms,Y*=ms)\n            X+=mx,Y+=my,Z+=mz\n            R(Rl,Pt,Yw,1)\n            l=Q(),lz4=Z\n            if(Z>0)x.lineTo(lx4=l[0],ly4=l[1])\n            if(Z>1){\n              if(j<3||lm<1){\n                x.lineTo(...Q())\n                ox-=-((t2%4)**.29)*1.82\n                oy-=-(t2%4)/32\n                x.closePath()\n                x.globalAlpha=Math.max(0,Math.min(.2,3/(1+(1+d4*300)**2.75/3e14)*(S(t*.85)*2)))\n                x.strokeStyle=`hsla(${t*199},99%,50%,.8)`\n                x.lineWidth=Math.max(1,Math.min(500,1+(d4)**.65*400/Z))\n                x.stroke()\n                x.strokeStyle=`#fff`\n                x.globalAlpha=Math.max(0,Math.min(1,3/(1+(1+d4*300)**2.75/3e14)*(S(t*.85)*2)))\n                x.lineWidth=Math.max(1,x.lineWidth/4)\n                x.stroke()\n              }\n\n              lxa=(lx1+lx2)/2\n              lya=(ly1+ly2)/2\n              lza=(lz1+lz2)/2\n              lxb=(lx2+lx3)/2\n              lyb=(ly2+ly3)/2\n              lzb=(lz2+lz3)/2\n              lxc=(lx3+lx4)/2\n              lyc=(ly3+ly4)/2\n              lzc=(lz3+lz4)/2\n              lxd=(lx4+lx1)/2\n              lyd=(ly4+ly1)/2\n              lzd=(lz4+lz1)/2\n              if(omxa!==null){\n                if(omxb!==null && j){\n                  x.beginPath()\n                  switch((lm+(Math.abs(Yw)%Math.PI>Math.PI/2||Math.abs(Yw)%Math.PI<-Math.PI/2?1:1))%2){\n                    case 0:\n                    x.moveTo(omxa,omya)\n                    x.bezierCurveTo(omxa,omya-(omya-omyb)/cvrs,omxa,omyb-(omyb-omya)/cvrs,omxb,omyb);\n                    break\n                    case 1:\n                    x.moveTo(omxb,omyb)\n                    x.bezierCurveTo(omxb,omyb-(omyb-omya)/cvrs,omxb,omya-(omya-omyb)/cvrs,omxa,omya);\n                    break\n                  }\n                  x.strokeStyle=`hsla(${d4/200-t*200},99%,50%,1)`\n                  x.lineWidth=(1+d4)/200\n                  x.globalAlpha=Math.min(.25,1/(1+(1+d4*300)**2/2e11))\n                  x.stroke()\n                  x.globalAlpha=Math.min(1,4/(1+(1+d4*300)**2/8e10))\n                  x.strokeStyle=\'#fff\'\n                  x.lineWidth=(1+d4)/800\n                  x.lineWidth+=2\n                  x.stroke()\n              }\n                omxb=omxa,omyb=omya\n              }\n              switch((lm)%2){\n                case 0: omxa=lxa,omya=lya; break\n                case 1: omxa=lxc,omya=lyc; break\n              }\n            }\n          }\n        }\n\n        if(go){\n          x.globalAlpha=.4\n          x.drawImage(bg,0,0,c.width,c.height)\n          x.globalAlpha=1\n          x.fillStyle=\'#0001\',x.fillRect(0,0,c.width,c.height)\n          x.lineJoin=x.lineCap=\'round\'\n          Rl=C(t*.4)/3,Pt=S(t/4.2)*1.5*C(t*.4),Yw=S(t/3.2)*4\n          oX=0,oY=0,oZ=5000+S(t*1.2)*300\n\n          omxa=omxb=omxc=omxd=null\n          rw=3,cl=3,br=3,sp=2200\n          for(let k=rw*cl*br;k--;){\n            mx=((k%cl)-cl/2+.5)*sp\n            my=(((k/cl|0)%rw)-rw/2+.5)*sp\n            mz=((k/rw/cl|0)-br/2+.5)*sp\n            for(j=0;j<4;++j){\n              s=phi**(j*4)\n              switch(j){\n                case 0: ox=phi**(j+4)/2, oy=-j*phi*phi/2; break\n                case 1: ox=phi**(j+4)/2, oy=-j*phi*phi/2; break\n                case 2: ox=phi**(j+4)/.9, oy=-j*phi*phi*2; break\n                case 3: ox=phi**(j+4)/.9*3.7, oy=-j*phi*phi*9; break\n              }\n              lm=0\n              DR(0,0,s,0,mx,my,mz)\n              lm=1\n              DR(-phi/2*s,0,phi*s,Math.PI/2*1,mx,my,mz)\n              lm=2\n              DR((phi**2)/2*s,-phi/2*s,(phi**2)*s,Math.PI/2*2,mx,my,mz)\n              lm=3\n              DR(-(phi**2)/2*s,(phi**2)/2*s,(phi**3)*s,Math.PI/2*3,mx,my,mz)\n            }\n          }\n        } else {\n          x.fillStyle=\'#0003\',x.fillRect(0,0,c.width,c.height)\n        }\n        t+=1/60\n        requestAnimationFrame(Draw)\n      }\n      Draw()\n    ', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'golden spiral (w/audio)', 145, 'whitehot robot', '2022-08-13 21:33:58', '[600253,600252,600251,600248,600247]', 69, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600389, 'https://srmcgann.github.io/assets/YNduX.mp4', '      c=document.querySelector(\'#c\')\n      x=c.getContext(\'2d\')\n      S=Math.sin\n      C=Math.cos\n      t=playing=0\n      window.onclick=()=>{if(!playing)mp3.play()}\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n      Draw=()=>{\n        x.fillStyle=\'#0008\'\n        x.fillRect(0,0,c.width,c.height)\n        \n        if(!t){\n         mp3 = new Audio()\n          mp3.loop=true\n          go=playing=false\n          mp3.onplaying=()=>{playing=true}\n          mp3.oncanplay=()=>{go=true;if(!playing)mp3.play()}\n          mp3.src=\'//audiocloud.rotoblaster.com/audio/e83b4c7d8dfb69013396b5627fbb1fbb.MP3\'\n          Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n          Rn=Math.random\n          P=[]\n          W=[]\n          I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0;\n          bgimg = new Image()\n          bgimg.addEventListener(\'load\', ()=>{\n            go=true\n          })\n          bgimg.src=\'/proxy.php?url=srmcgann.github.io/assets/1CsTVH.png\'\n          R=(Rl,Pt,Yw,o)=>{\n            X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n            if(o)X+=oX,Y+=oY,Z+=oZ\n          }\n          B=[]\n          l_=l=0.8660254037844386\n          plotHex=(tx,ty)=>{\n            if((d=Math.hypot(tx,ty))>=20 || !!B.filter(v=>Math.hypot(v[0]-tx,v[1]-ty)<.01).length) return\n            let a=[]\n            for(let i=6;i--;){\n              let X=S(p=Math.PI*2/6*i)\n              let Y=C(p)\n              let Z=0\n              a=[...a, [X,Y,Z]]\n            }\n            B.push([tx,ty,0,a])\n            for(let i=6;i--;){\n              let X=S(p=Math.PI*2/6*i+Math.PI/6)\n              let Y=C(p)\n              let Z=0\n              plotHex(tx+X*l_*2,ty+Y*l_*2)\n            }\n          }\n          plotHex(0,0)\n\n          P=[]\n          X=B[l=B.length-1][0]\n          Y=B[l][1]\n          Z=B[l][2]\n          P.push([X,Y,Z,X,Y,Z,[]])\n          plotMaze=idx=>{\n            if(B.length==P.length) return\n            px=P[idx][0]\n            py=P[idx][1]\n            pz=P[idx][2]\n            let n = B.filter(v=>{\n              return (d=Math.hypot(v[0]-px, v[1]-py)) <= l_*2.1 && d>.1\n            })\n            if(n.length){\n              np=false\n              for(let k=4;k--&&!np;){\n                idx_ = Rn()*n.length|0\n                if(!P.filter(v=>Math.hypot(v[0]-n[idx_][0],v[1]-n[idx_][1])<.1).length){\n                  np=true\n                  n[idx_][4]=P.length\n                  P=[...P, [n[idx_][0],n[idx_][1],n[idx_][2], px, py, 0, [idx]]]\n                }\n              }\n              if(np){\n                plotMaze(P.length-1)\n              } else {\n                plotMaze(P.length*Rn()|0)\n              }\n            }\n          }\n          plotMaze(0)\n          P.map((v,i)=>{\n            a=[]\n            P.map((q,j)=>{\n              if(q[6].indexOf(i)!==-1) a=[...a, j]\n            })\n            v[6]=[...a]\n          })\n          B.map(v=>{\n            tx=v[0]\n            ty=v[1]\n            tz=v[2]\n            v[3].map((q,j)=>{\n              tx1=tx+q[0]\n              ty1=ty+q[1]\n              tx2=tx+v[3][(j+1)%v[3].length][0]\n              ty2=ty+v[3][(j+1)%v[3].length][1]\n              let cull = !P.filter(n=>{\n                tx3=n[0]\n                ty3=n[1]\n                tx4=n[3]\n                ty4=n[4]\n                return I(tx1,ty1,tx2,ty2,tx3,ty3,tx4,ty4)\n              }).length\n              q.push(cull)\n            })\n          })\n\n          mx=my=mz=mx_=my_=mz_=0\n          window.onmousemove=e=>{\n            mtimer=0\n            let rect = c.getBoundingClientRect()\n            mx=(e.pageX-(rect.left+2))/(c.clientWidth)*c.width\n            my=(e.pageY-(rect.top+2))/(c.clientHeight)*c.height\n          }\n          window.ontouchmove=e=>{\n            mtimer=0\n            let rect = c.getBoundingClientRect()\n            e=(l=e.originalEvent.touches[0])?l:e\n            mx=(l.pageX-(rect.left+2))/(c.clientWidth)*c.width\n            my=(l.pageY-(rect.top+2))/(c.clientHeight)*c.height\n          }\n          vl=0\n          button=false\n          window.onmousedown=e=>{\n            if(e.button==0)button=true\n          }\n          window.ontouchstart=e=>{\n            button=true\n            let rect = c.getBoundingClientRect()\n            e=(l=e.originalEvent.touches[0])?l:e\n            mx=(l.pageX-(rect.left+2))/(c.clientWidth)*c.width\n            my=(l.pageY-(rect.top+2))/(c.clientHeight)*c.height\n          }\n          window.onmouseup=e=>{\n            if(e.button==0)button=false\n          }\n          window.ontouchend=e=>{\n            button=false\n          }\n          \n          pointInPoly = (poly, mx, my) => {\n            let p=[], a=[]\n            poly.map((n, m)=>{\n              p=[...p, Math.atan2(mx-n[0], my-n[1])]\n            })\n            \n            p.sort((a,b)=>a-b)\n            \n            p.map((v,i)=>{\n              if(i) a=[...a, p[i]-p[i-1]]\n            })\n            \n            p[0]+=Math.PI*2\n            a=[...a, p[0]-p[p.length-1]]\n            return !!!a.filter(v=>v>Math.PI).length\n          }\n\n          drawSeg=idx=>{\n            if(typeof P[idx] !== \'undefined\'){\n              x.beginPath()\n              X=P[idx][0]\n              Y=P[idx][1]\n              Z=P[idx][2]\n              R(Rl,Pt,Yw,1)\n              if(Z>0) x.lineTo(...Q())\n              X=P[idx][3]\n              Y=P[idx][4]\n              Z=P[idx][5]\n              R(Rl,Pt,Yw,1)\n              if(Z>0) x.lineTo(...Q())\n              x.strokeStyle=\'#0faa\'\n              x.lineWidth=2e3/(Z**1.5)\n              x.stroke()\n            }\n          }\n\n          solveFrom=(idx, eidx)=>{\n            if(idx==eidx){\n              path=[...path, idx]\n              return true\n            }\n            if(memo.indexOf(idx) !=-1 || typeof P[idx] == \'undefined\' || typeof P[idx][6]==\'undefined\') return false\n            memo=[...memo, idx]\n            let pass=false\n            P[idx][6].map(v=>{\n              if(solveFrom(v, eidx)){\n                path=[...path, idx]\n                pass =true\n              }\n            })\n            return pass\n          }\n          mtimer=1, showPath=false, tgx=960,tgy=540\n          star1=new Image()\n          star1Loaded=false\n          star1.onload=()=>{\n            star1Loaded=true\n          }\n          star1.src=\'/proxy.php?url=srmcgann.github.io/assets/vtpHy.png\'\n          star2=new Image()\n          star2Loaded=false\n          star2.onload=()=>{\n            star2Loaded=true\n          }\n          star2.src=\'/proxy.php?url=srmcgann.github.io/assets/19fCSk.png\'\n          go=false\n          bgimg = new Image()\n          bgimg.onload=()=>{\n            go=true\n          }\n          bgimg.src=\'proxy.php?url=srmcgann.github.io/assets/2h9kBr.jpg\'\n        }\n        mtimer+=.2\n        if(go){\n          x.globalAlpha=.8\n          x.drawImage(bgimg,0,0,c.width,c.height)\n          x.globalAlpha=1\n          x.fillStyle=\'#0008\'\n          x.fillRect(0,0,c.width,c.height)\n        }else{\n          x.fillStyle=\'#0008\'\n          x.fillRect(0,0,c.width,c.height)\n        }\n        x.lineJoin=x.lineCap=\'butt\'\n        \n        if(mtimer>1){\n          mx=c.width/2-C(t*4)*c.width/8\n          my=c.height/2+S(t*3)*c.height/6\n          tgx=c.width/2+S(t*5)*c.width/8\n          tgy=c.height/2+C(t*2)*c.height/6\n          Rl=S(t/4)*3,Pt=S(t)/2,Yw=S(t)*2*(Math.max(0,S(t/2)*14-11))\n          oX=0,oY=0,oZ=30+S(t)*10\n        }\n\n        if(showPath){\n          tlc=x.lineJoin\n          x.lineJoin=x.lineCap=\'butt\'\n          P.map((v,i)=>{\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            x.fillStyle=\'#84f3\'\n            R(Rl,Pt,Yw,1)\n            s=2e3/(Z**1.5)\n            l=Q()\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n            if(Z>0){\n              x.beginPath()\n              x.lineTo(...l)\n              X=v[3]\n              Y=v[4]\n              Z=v[5]\n              R(Rl,Pt,Yw,1)\n              if(Z>0){\n                x.lineTo(...Q())\n                x.strokeStyle=\'#84f3\'\n                x.lineWidth=1e3/(Z**1.5)\n                x.stroke()\n              }\n            }\n          })\n          x.lineJoin=x.lineCap=tlc\n        }\n   \n        stidx = tgtidx = -1\n\n        B.map((v,i)=>{\n          tx=v[0]\n          ty=v[1]\n          tz=v[2]\n          v[3].map((q,j)=>{\n            if(q[3]){\n              x.beginPath()\n              X=q[0]+tx\n              Y=q[1]+ty\n              Z=q[2]+tz\n              R(Rl,Pt,Yw,1)\n              if(Z>0)x.lineTo(...Q())\n              X=v[3][l=(j+1)%v[3].length][0]+tx\n              Y=v[3][l=(j+1)%v[3].length][1]+ty\n              Z=v[3][l=(j+1)%v[3].length][2]+tz\n              R(Rl,Pt,Yw,1)\n              if(Z>0){\n                x.lineTo(...Q())\n                x.strokeStyle=\'#fff2\'\n                x.lineWidth=2e3/(Z**1.5)\n                x.stroke()\n                x.lineWidth/=5\n                x.strokeStyle=\'#fff8\'\n                x.stroke()\n                x.beginPath()\n              }\n            }\n          })\n\n          a=[]\n          l=JSON.parse(JSON.stringify(v[3])).map(q=>{\n            X=q[0]+=tx\n            Y=q[1]+=ty\n            Z=q[2]+=tz\n            R(Rl,Pt,Yw,1)\n            a=[...a, Q()]\n            return [...q]\n          })\n          \n          let fill=pointInPoly(a, tgx, tgy)\n          if(fill){\n            tgtidx=v[4]\n            if(!star1Loaded){\n              x.beginPath()\n              l.map((q,j)=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(Rl,Pt,Yw,1)\n                if(Z>0)x.lineTo(...Q())\n              })\n              x.fillStyle=\'#f00\'\n              x.fill()\n            } else {\n              if(star1Loaded){\n                sw=Math.min(2e3, 100200/(Z**1.5))\n                sh=sw/(star1.width/star1.height)\n                x.drawImage(star1, tgx-sw/2, tgy-sh/2,sw,sh)\n              }\n            }\n          }\n\n          fill = pointInPoly(a,mx,my)\n          if(fill){\n            stidx=v[4]\n            if(!star2Loaded){\n              x.beginPath()\n              l.map((q,j)=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(Rl,Pt,Yw,1)\n                if(Z>0)x.lineTo(...Q())\n              })\n              x.fillStyle=\'#0f8\'\n              x.fill()\n            } else {\n              if(star2Loaded){\n                sw=Math.min(2e3, 100200/(Z**1.5))\n                sh=sw/(star2.width/star2.height)\n                x.drawImage(star2, mx-sw/2, my-sh/2,sw,sh)\n              }\n            }\n          }\n        })\n\n        if(stidx!=-1 && tgtidx!=-1){\n          memo=[]\n          tlc=x.lineJoin\n          x.lineJoin=x.lineCap=\'round\'\n          path=[]\n          solveFrom(stidx, tgtidx)\n          path=path.filter(v=>{\n            let ep = -1\n            tx=P[v][3]\n            ty=P[v][4]\n            P.map((q,j)=>{\n              if(Math.hypot(tx-q[0],ty-q[1])<.01) ep=j\n            })\n            return path.indexOf(ep)!=-1\n          })\n          path.map((v,i)=>{\n            drawSeg(v)\n          })\n          x.lineJoin=x.lineCap=tlc\n        }\n        \n        t+=1/60\n        requestAnimationFrame(Draw)\n      }\n      Draw()\n', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'greece (w/audio)', 145, 'whitehot robot', '2022-08-13 21:48:50', '[600253,600252,600251,600248,600247]', 67, 'https://code.dweet.net/thumbs/22251a6dedc91ed1863a7cf5b94b3b56.jpg', 6, 0),
(600390, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/B1vC.gif);\n  background-size: 100% 100%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'greece (gif)', 145, 'whitehot robot', '2022-08-13 22:22:34', '[600385,600380,600367,600366,600364,600363,600360,600359,600358,600357,600356,600355,600354,600353,600288,600253,600252,600251,600248,600247]', 63, '', 0, 0),
(600391, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/byxA5.gif);\n  background-size: 100% 100%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'sea cucumber breakfast (gif)', 145, 'whitehot robot', '2022-08-13 23:02:47', '[600390,600385,600380,600367,600366,600364,600363,600360,600359,600358,600357,600356,600355,600354,600353,600288,600253,600252,600251,600248,600247]', 72, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600392, '', 'showHotkeys=()=>{\n  alert(\"W/A/S/D - movement\\nARROW KEYS - look\\nSHIFT - increased speed\\nF - toggle floor, V - toggle viewfinder\\nG - toggle background\\n\\n  TRANSFORM  MODES\\nM - move\\nR - rotate\\nL - scale/size\\n\\n  SELECT MODES\\n1 - vertex\\n2 - face\\n3 - shape\\n\\n  MODIFIERS\\nshift + rotate (mouse x)  = roll\\nctrl + up/down arrows = move camera vertically\\n\\n  SPECIAL KEYS\\nY - toggle \\\"y-lock\\\"\\nshift + camera tool (mouse y) vertical movement\\nshift + move shape = duplicate\")\n}\n\ncanvas2 = document.querySelector(\"#c\")\ncanvas2.width = 1920|0\ncanvas2.height = 1080|0\nx2 = canvas2.getContext(\'2d\')\nc = canvas2.cloneNode()\nc.id = \'canvas2\'\nc.style.visibility = \'hidden\'\nc.style.position = \'absolute\'\ndocument.body.appendChild(c)\nc.width=1920\nc.height=1080\nc.style.width=\'calc(\' + 1920 + \'px - 10px)\'\nc.style.height=\'calc(\' + 1080 + \'px - 10px)\'\n\nurlOBJ=false\nx = c.getContext(\'2d\')\nC = Math.cos\nS = Math.sin\nt = 0\nT = Math.tan\n\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778+1|0){\n      c.style.height = \'calc(100vh - 40px)\'\n      setTimeout(()=>c.style.width = \'calc(\' + (c.clientHeight*1.77777778+1|0)+\'px)\',0)\n    }else{\n      c.style.width = \'calc(100vw - 40px)\'\n      setTimeout(()=>c.style.height = \'calc(\' + (c.clientWidth/1.77777778+1|0)+\'px)\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778+1|0\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778+1|0){\n      canvas2.style.height = \'calc(100vh - 40px)\'\n      setTimeout(()=>canvas2.style.width = \'calc(\' + (canvas2.clientHeight*1.77777778+1|0)+\'px)\',0)\n    }else{\n      canvas2.style.width = \'calc(100vw - 40px)\'\n      setTimeout(()=>canvas2.style.height = \'calc(\' + (canvas2.clientWidth/1.77777778+1|0)+\'px)\',0)\n    }\n    canvas2.width=c.width\n    canvas2.height=canvas2.width/1.777777778+1|0\n  },0)\n  redraw=true\n}\nrsz()\n\nasync function Draw(){\n\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    Q=q=>[c.width/2+X/Z*1e3,c.height/2+Y/Z*1e3]\n    Rn=Math.random\n    document.querySelector(\'#button\').style.display=\'none\'\n    x.lineJoin=x.lineCap=\'butt\'\n      cloneShapeQueue=[] \n      shiftCloneComplete=false\n      history=[]\n      editable = false\n      allSelected = false\n      cct=0\n      draggingShapes=[]\n      freshClick=true\n      greyButtonImg = new Image()\n      greyButtonImg.src = \'/proxy.php?url=https://srmcgann.github.io/assets/11UEjG.png\'\n      greenButtonImg = new Image()\n      greenButtonImg.src = \'/proxy.php?url=https://srmcgann.github.io/assets/h4Bwh.png\'\n      redButtonImg = new Image()\n      redButtonImg.src = \'/proxy.php?url=https://srmcgann.github.io/assets/2dNSSS.png\'\n      fullScreenButtonImg = new Image()\n      fullScreenButtonImg.src = \'/proxy.php?url=https://srmcgann.github.io/assets/ERPZC.png\'\n      checkImg = new Image()\n      checkImg.src = \'/proxy.php?url=https://srmcgann.github.io/assets/h79WY.png\'\n      \n\n      async function loadReducedOBJ(url, scale, tx, ty, tz, rl, pt, yw, reduce) {\n        let res\n        await fetch(url+\'?reduce=\'+reduce, res => res).then(data=>data.text()).then(data=>{\n          res=JSON.parse(data)\n          ax=ay=az=ct=0\n          res.map(v=>{\n            v.map(q=>{\n              q[1]*=-1\n              q[0]*=scale\n              q[1]*=scale\n              q[2]*=scale\n              ax+=q[0]\n              ay+=q[1]\n              az+=q[2]\n              ct++\n            })\n          })\n          ax/=ct\n          ay/=ct\n          az/=ct\n          res.map(v=>{\n            v.map(q=>{\n              X=q[0]-ax\n              Y=q[1]-ay\n              Z=q[2]-az\n              R2(rl,pt,yw,0)\n              q[0]=X+tx\n              q[1]=Y+ty\n              q[2]=Z+tz\n            })\n          })\n        })\n        return res\n      }\n      \n      async function loadOBJ(url, scale, tx, ty, tz, rl, pt, yw) {\n        let res\n        await fetch(url, res => res).then(data=>data.text()).then(data=>{\n          a=[]\n          data.split(\"\\nv \").map(v=>{\n            a=[...a, v.split(\"\\n\")[0]]\n          })\n          a=a.filter((v,i)=>i).map(v=>[...v.split(\' \').map(n=>(+n.replace(\"\\n\", \'\')))])\n          ax=ay=az=0\n          a.map(v=>{\n            v[1]*=-1\n            ax+=v[0]\n            ay+=v[1]\n            az+=v[2]\n          })\n          ax/=a.length\n          ay/=a.length\n          az/=a.length\n          a.map(v=>{\n            X=(v[0]-ax)*scale\n            Y=(v[1]-ay)*scale\n            Z=(v[2]-az)*scale\n            R2(rl,pt,yw,0)\n            v[0]=X\n            v[1]=Y\n            v[2]=Z\n          })\n          maxY=-6e6\n          a.map(v=>{\n            if(v[1]>maxY)maxY=v[1]\n          })\n          a.map(v=>{\n            v[1]-=maxY-oY\n            v[0]+=tx\n            v[1]+=ty\n            v[2]+=tz\n          })\n\n          b=[]\n          data.split(\"\\nf \").map(v=>{\n            b=[...b, v.split(\"\\n\")[0]]\n          })\n          b.shift()\n          b=b.map(v=>v.split(\' \'))\n          b=b.map(v=>{\n            v=v.map(q=>{\n              return +q.split(\'/\')[0]\n            })\n            v=v.filter(q=>q)\n            return v\n          })\n          \n          res=[]\n          b.map(v=>{\n            e=[]\n            v.map(q=>{\n              e=[...e, a[q-1]]\n            })\n            e = e.filter(q=>q)\n            res=[...res, e]\n          })\n        })\n        return res\n      }\n\n      tools={\n        defaultCursor: \'crosshair\',\n        show: true,\n        hover: false,\n        marq:{\n          x: -1,\n          y: -1,\n          w: 0,\n          h: 0\n        },\n        menu:{\n          boundingRect: [],\n          toggled: false,\n          visible: false,\n          hover: false,\n          toggleButton: [],\n          fontSize: 20,\n          x: c.width-50-100-100,\n          y: 140,\n          options: [],\n          items:[],\n          optionsMode:{\n            vertex: [\n            ],\n            face: [\n              {\n                name: \'\',\n                type: \'text\',\n                height: 1\n              },\n              {\n                name:\'DETACH FACE\',\n                type: \'text\',\n                height: -.15\n              },\n              {\n                name:\'DETACH\',\n                type: \'toggle-button\',\n                category: \'detachMode\',\n                color: \'#fff\',\n                value: true,\n                func: \'setFaceDetachMode\'\n              },\n              {\n                name:\'NO-DETACH\',\n                type: \'toggle-button\',\n                category: \'detachMode\',\n                color: \'#fff\',\n                value: false,\n                func: \'setFaceDetachMode\'\n              },\n            ],\n            shape: [\n              {\n                name: \'ACTIONS\',\n                type: \'text\',\n                height: -.2\n              },\n              {\n                name:\'delete shape\',\n                type: \'button\',\n                color: \'#faa\',\n                buttonType: redButtonImg,\n                func: \'deleteShape\'\n              },\n              {\n                name:\'duplicate shape\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'duplicateShape\'\n              },\n              {\n                name:\'align to floor\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'alignToFloor\'\n              },\n              {\n                name: \'TRANSFORM MODE\',\n                type: \'text\',\n                height: 0\n              },\n              {\n                name:\'move   [M]\',\n                type: \'toggle-button\',\n                color: \'#fff\',\n                category: \'transformMode\',\n                value: \'move\',\n                func: \'setTransformMode\'\n              },\n              {\n                name:\'rotate [R]\',\n                type: \'toggle-button\',\n                color: \'#fff\',\n                category: \'transformMode\',\n                value: \'rotate\',\n                func: \'setTransformMode\'\n              },\n              {\n                name:\'scale  [L]\',\n                type: \'toggle-button\',\n                color: \'#fff\',\n                category: \'transformMode\',\n                value: \'scale\',\n                func: \'setTransformMode\'\n              },\n              {\n                name: \'\',\n                type: \'text\',\n                height: 0\n              },\n            ],\n            allMenus: [\n              {\n                name: \'\',\n                type: \'text\',\n                height: 0\n              },\n              {\n                name: \'SELECTION MODE\',\n                type: \'text\',\n                height: -.15\n              },\n              {\n                name:\'VERTEX [1]\',\n                type: \'toggle-button\',\n                category: \'selectMode\',\n                color: \'#fff\',\n                value: \'vertex\',\n                func: \'setSelectionMode\'\n              },\n              {\n                name:\'FACE   [2]\',\n                type: \'toggle-button\',\n                category: \'selectMode\',\n                color: \'#fff\',\n                value: \'face\',\n                func: \'setSelectionMode\'\n              },\n              {\n                name:\'SHAPE  [3]\',\n                type: \'toggle-button\',\n                category: \'selectMode\',\n                color: \'#fff\',\n                value: \'shape\',\n                func: \'setSelectionMode\'\n              },\n            ],\n            \'default\': [\n              {\n                name: \'CREATE SHAPE\',\n                type: \'text\',\n                color: \'#aff\',\n                height: -.25,\n              },\n              {\n                name: \'tetrahedron\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 0\n              },\n              {\n                name: \'cube\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 1\n              },\n              {\n                name: \'octahedron\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 2\n              },\n              {\n                name: \'dodecahedron\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 3\n              },\n              {\n                name: \'icosahedron\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 4\n              },\n              {\n                name: \'sphere\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 5\n              },\n              {\n                name: \'chair\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 6\n              },\n              {\n                name: \'tiger\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 7\n              },\n              {\n                name: \'fish\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 8\n              },\n              {\n                name: \'house 1\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 9\n              },\n              {\n                name: \'house 2\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 18\n              },\n              {\n                name: \'axe\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 14\n              },\n              {\n                name: \'pickaxe\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 15\n              },\n              {\n                name: \'tree 1\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 16\n              },\n              {\n                name: \'tree 2\',\n                type: \'button\',\n                color: \'#aff\',\n                buttonType: greenButtonImg,\n                func: \'createShape\',\n                shapeChoice: 19\n              },\n            ]\n          }\n        },\n        transformMode: \'move\',\n        selectMode: \'shape\',\n        showFloor: true,\n        showGlobalSphere: true,\n        detachFace: false,\n        viewfinder:{\n          visible: true,\n          img: (function(){let i=(new Image());i.src=\'/proxy.php?url=https://srmcgann.github.io/assets/1STcyi.png\';return i})(),\n          alpha: .2\n        },\n        editMode: \'move\',\n        fly: {\n          enabled: false\n        },\n        gyro:{\n          hover: false,\n          x: c.width/2-50-10,\n          y: 50+10\n        },\n        move:{\n          hover: false,\n          x: c.width-10-100-100,\n          y: 50+10\n        },\n        info:{\n          toggled: false,\n          visible: false,\n          hover: false,\n          toggleButton: [],\n          fontSize: 20,\n          x: c.width-50-100-100,\n          y: 140\n        }\n      }\n      \n      draggingShape=false\n      \n      showIcon = new Image()\n      showIcon.src = \'/proxy.php?url=https://srmcgann.github.io/assets/8lHEh.png\'\n      hideIcon = new Image()\n      hideIcon.src = \'/proxy.php?url=https://srmcgann.github.io/assets/YUlip.png\'\n      \n      duplicateShape=(newshp, clonePos)=>{\n        newshp=JSON.parse(JSON.stringify(newshp))\n        newshp[6]=newshp[6].filter((q,j)=>j<newshp[6].length-1)\n        newshp[6]=newshp[6].map(v=>{\n          v=v.filter((q,j)=>j<v.length-1)\n          v=v.map((q,j)=>{\n            q=q.filter((n,m)=>m<q.length-1)\n            return q\n          })\n          return v\n        })\n        let tx,ty,tz,rl,pt,yw\n        if(clonePos){\n          tx=newshp[0]\n          ty=newshp[1]\n          tz=newshp[2]\n          rl=newshp[3]\n          pt=newshp[4]\n          yw=newshp[5]\n        }else {\n          tx=-oX-S(p=Yw)*C(q=Pt)*10+1\n          ty=-oY-S(q)*10\n          tz=-oZ+C(p)*C(q)*10\n          rl=0,pt=0,yw=0\n        }\n        cloneShapeQueue=[...cloneShapeQueue, [newshp[6], tx,ty,tz,rl,pt,yw,\'#0643\',newshp[9],newshp[10],newshp[11]]]\n      }\n\n\n      doAction=v=>{\n        if(tools.menu.visible){\n          func=v[0].func\n          switch(func){\n            case \'setFaceDetachMode\':\n              tools.detachFace = v[0].value\n              closeMenus()\n            break\n            case \'setSelectionMode\':\n              tools.selectMode = v[0].value\n              if(tools.selectMode !== \'shape\') tools.transformMode = \'move\'\n              tools.menu.items=[]\n              tools.menu.options=[]\n              rw=0\n              tools.menu.options.map(v=>{\n                renderMenuItem(tools.menu.x,tools.menu.y+tools.menu.fontSize*(rw+1), v, rw++)\n              })\n            break\n            case \'setTransformMode\':\n              tools.transformMode = v[0].value\n              tools.menu.items=[]\n              tools.menu.options=[]\n              rw=0\n              tools.menu.options.map(v=>{\n                renderMenuItem(tools.menu.x,tools.menu.y+tools.menu.fontSize*(rw+1), v, rw++)\n              })\n              closeMenus()\n            break\n            case \'createShape\':\n              tx=-oX-S(p=Yw)*C(q=Pt)*10\n              ty=-oY-S(q)*10\n              tz=-oZ+C(p)*C(q)*10\n\n              pushShape(base_shapes[v[0].shapeChoice].shape, tx,ty,tz,0,-q,-p,base_shapes[v[0].shapeChoice].color,base_shapes[v[0].shapeChoice].wireframe,base_shapes[v[0].shapeChoice].useFill, base_shapes[v[0].shapeChoice].gyro) \n              draggingShapes=[]\n              closeMenus()\n            break\n            case \'deleteShape\':\n              shps=shps.filter(v=>{\n                return !(v[v.length-1] || v[6].filter(q=>{\n                  return q[q.length-1] || (q.length && q.filter(n=>n[3]).length)\n                }).length)\n              })\n              draggingShapes=[]\n              closeMenus()\n            break\n            case \'alignToFloor\':\n              maxY=-6e6;\n              (l=shps.filter(v=>{\n                let sel = false\n                sel = v[v.length-1]\n                if(!sel){\n                  v[6].map(q=>{\n                    if(q[q.length-1]) sel = true\n                    if(q.length && !sel){\n                      q.map(n=>{\n                        if(n[3]) sel = true\n                      })\n                    }\n                  })\n                }\n                return sel\n              })).map(v=>{\n                v[6].map((q,j)=>{\n                  if(q.length){\n                    q.map(n=>{\n                      X=n[0]\n                      Y=n[1]\n                      Z=n[2]\n                      if(Y>maxY){\n                        maxY=Y\n                      }\n                    })\n                  }\n                })\n              })\n              l.map(v=>{\n                v[1]=-maxY\n              })\n              closeMenus()\n            break\n            case \'duplicateShape\':\n              cloneShapeQueue=[]\n              shps.map(v=>{\n                if(v[v.length-1] || v[6].filter(q=>{\n                  return q.length && q[length-1]\n                }).length){\n                  let newShp = JSON.parse(JSON.stringify(v))\n                  newShp[6].map(q=>{\n                    if(q.length){\n                      q.map(n=>{\n                        n[3]=false\n                      })\n                      q[length-1]=false\n                    }\n                  })\n                  duplicateShape(newShp,0)\n                }\n              })\n              draggingShapes=[]\n              closeMenus()\n            break\n          }\n        }\n      }\n      \n      selectedShapes=()=>{\n        return shps.filter(v=>{\n          return v[v.length-1] || v[6].filter(q=>{\n            return q[q.length-1] || (q.length && q.filter(n=>n[3]).length)\n          }).length\n        })\n      }\n      \n      renderMenuItem=(tx, ty, v, rw)=>{\n        if(tools.menu.visible){\n          switch(v.type){\n            case \'text\':\n              x.fillStyle=\'#000\'\n              x.strokeStyle=\'#fff\'\n              rw+=v.height\n              printLn(`${v.name}`, rw*2.2, 0, \'menu\')\n            break\n            case \'checkbox\':\n              printLn(`${v.name}`, ++rw, 2, \'menu\')                \n              x.fillStyle=\'#555\'\n              x.fillRect(...(a=[tx-2.5,ty-52.5+25*rw,30,30]))\n              if(v.value){\n                x.drawImage(checkImg,tx,ty-50+25*rw,25,25)\n              }\n            break;\n            case \'toggle-button\':\n              if(v.buttonType){\n                bimg = v.buttonType\n              } else {\n                switch(v.category){\n                  case \'transformMode\':\n                    bimg = tools.transformMode == v.value ? greenButtonImg : greyButtonImg\n                  break\n                  case \'selectMode\':\n                    bimg = tools.selectMode == v.value ? greenButtonImg : greyButtonImg\n                  break\n                  case \'detachMode\':\n                    bimg = tools.detachFace == v.value ? greenButtonImg : greyButtonImg\n                  break\n                }\n              }\n              x.drawImage(bimg, ...(a=[tx,ty-50+25*rw,285,35]))\n              x.strokeStyle=\'#000c\'\n              x.lineWidth=5\n              x.strokeText(`${v.name}`,tx+15,ty-25+25*rw-2)\n              x.strokeStyle=v.color\n              x.lineWidth=2\n              x.strokeText(`${v.name}`,tx+15,ty-25+25*rw-2)\n              x.fillStyle=v.color\n              x.fillText(`${v.name}`,tx+15,ty-25+25*rw-2)\n              tools.menu.items.push([v, a])\n            break;\n            case \'button\':\n              bimg = v.buttonType\n              x.drawImage(bimg, ...(a=[tx,ty-50+25*rw,285,35]))\n              x.strokeStyle=\'#000c\'\n              x.lineWidth=5\n              x.strokeText(`${v.name}`,tx+15,ty-25+25*rw-2)\n              x.strokeStyle=v.color\n              x.lineWidth=2\n              x.strokeText(`${v.name}`,tx+15,ty-25+25*rw-2)\n              x.fillStyle=v.color\n              x.fillText(`${v.name}`,tx+15,ty-25+25*rw-2)\n              tools.menu.items.push([v, a])\n            break;\n          }\n        }\n      }\n\n      closeMenus=()=>{\n        tools.menu.options=[]\n        tools.menu.items=[]\n        tools.menu.visible=false\n      }\n\n      doMove=(v)=>{\n        if(keys[16] && !shiftCloneComplete){\n          duplicateShape(v, 1)\n        }\n        tools.marq.x=-1\n        tools.marq.y=-1\n        tools.marq.w=tools.marq.h=0\n        v[0]+=S(p=-Yw+Math.PI/2)*d1*C(Pt)-S(Pt)*(S(q=-Yw+Math.PI/2)*d1+C(q)*d2)*-S(Pt)\n        v[1]+=C(Pt)*d2\n        v[2]+=C(p)*d1*C(Pt)+S(Pt)*(S(q)*d2-C(q)*d1)\n      }\n      \n      doRotation=v=>{\n        td1=d1,td2=d2\n        tools.marq.x=-1\n        tools.marq.y=-1\n        tools.marq.w=tools.marq.h=0\n        if(cct){\n          if(!gotRotCenters){\n            gotRotCenters=true\n            rcx=rcy=rcz=0;\n            (l=shps.filter((v,i)=>i<shps.length-1&&v[v.length-1])).map(v=>{\n              rcx+=v[0]\n              rcy+=v[1]\n              rcz+=v[2]\n            })\n            rcx/=l.length\n            rcy/=l.length\n            rcz/=l.length;\n          }\n          (l=shps.filter((v,i)=>i<shps.length-1&&v[v.length-1])).map(v=>{\n            X=v[0]-rcx\n            Y=v[1]-rcy\n            Z=v[2]-rcz\n            R(Rl,Pt,Yw,0)\n            if(keys[16]){\n              R2(-td1/10/(l.length+1), -td2/10/(l.length+1), 0, 0)\n            }else{\n              R2(0,-td2/10/(l.length+1),-td1/10/(l.length+1),0)\n            }\n            R(-Rl,-Pt,-Yw,0)\n            v[0]=rcx+X\n            v[1]=rcy+Y\n            v[2]=rcz+Z\n          })\n        }\n        \n        v[6].map(q=>{\n          if(q.length){\n            q.map(n=>{\n              X=n[0]\n              Y=n[1]\n              Z=n[2]\n              R(Rl,Pt,Yw,0)\n              if(keys[16]){\n                R2(-td1/10, -td2/10, 0, 0)\n              }else{\n                R2(0, -td2/10, -td1/10, 0)\n              }\n              R(-Rl,-Pt,-Yw,0)\n              n[0]=X\n              n[1]=Y\n              n[2]=Z\n            })\n          }\n        })\n\n        if(typeof v[11] !== \'undefined\'){\n          v[11].map(q=>{\n            q.map(n=>{\n              X=n[0]\n              Y=n[1]\n              Z=n[2]\n              R(Rl,Pt,Yw,0)\n              if(keys[16]){\n                R2(-td1/10, -td2/10, 0, 0)\n              }else{\n                R2(0, -td2/10, -td1/10, 0)\n              }\n              R(-Rl,-Pt,-Yw,0)\n              n[0]=X\n              n[1]=Y\n              n[2]=Z\n            })\n          })\n        }\n      }\n      \n      doFaceRotation=v=>{\n        tools.marq.x=-1\n        tools.marq.y=-1\n        tools.marq.w=tools.marq.h=0\n        if(!gotRotCenters){\n          gotRotCenters=true\n          c_=rcx=rcy=rcz=0;\n          (l=shps.filter((v,i)=>i<shps.length-1)).map(v=>{\n            v[6].map(q=>{\n              if(q.length && (!tools.detachFace || !q.filter(v=>v.length&&!v[3]).length)){\n                q.map(n=>{\n                  if(n[3]){\n                    rcx+=n[0]\n                    rcy+=n[1]\n                    rcz+=n[2]\n                    c_++\n                  }\n                })\n              }\n            })\n          })\n          rcx/=c_\n          rcy/=c_\n          rcz/=c_;\n        };\n        (l=shps.filter((v,i)=>i<shps.length-1)).map(v=>{\n          v[6].map(q=>{\n            if(q.length && (!tools.detachFace || !q.filter(v=>v.length&&!v[3]).length)){\n              q.map(n=>{\n                if(n[3]){\n                  X=n[0]-rcx\n                  Y=n[1]-rcy\n                  Z=n[2]-rcz\n                  R2(0,-d2/20,-d1/20,0)\n                  n[0]=X+rcx\n                  n[1]=Y+rcy\n                  n[2]=Z+rcz\n                }\n              })\n            }\n          })\n        })\n      }\n\n      doFaceMove=v=>{\n        tools.marq.x=-1\n        tools.marq.y=-1\n        tools.marq.w=tools.marq.h=0;\n        (l=shps.filter((v,i)=>i<shps.length-1)).map(v=>{\n          v[6].map(q=>{\n            if(q.length && (!tools.detachFace || !q.filter(v=>v.length&&!v[3]).length)){\n              q.map(n=>{\n                if(n[3]){\n                  n[0]+=S(p=-Yw+Math.PI/2)*d1*C(Pt)-S(Pt)*(S(q=-Yw+Math.PI/2)*d1+C(q)*d2)*-S(Pt)\n                  n[1]+=C(Pt)*d2\n                  n[2]+=C(p)*d1*C(Pt)+S(Pt)*(S(q)*d2-C(q)*d1)\n                }\n              })\n            }\n          })\n        })\n      }\n\n      doScale=v=>{\n        tools.marq.x=-1\n        tools.marq.y=-1\n        tools.marq.w=tools.marq.h=0\n        v[6].map(q=>{\n          if(q.length){\n            q.map(v=>{\n              if(v.length){\n                v[0]*=1-(d2/10)\n                v[1]*=1-(d2/10)\n                v[2]*=1-(d2/10)\n              }\n            })\n          }\n        })\n      }\n\n      drawMenu=()=>{\n        x.globalAlpha=1\n        rw=0\n        mbuttons.map(v=>false)\n        tools.menu.visible=true\n        mw=300\n        mh=925\n        x.strokeStyle=\'#8fc6\'\n        x.lineWidth = 1\n        omx=Math.max(20, omx)\n        omy=Math.max(20, omy)\n        ox=Math.max(0,mw-(c.width-omx)+10)\n        oy=Math.max(0,mh-(c.height-omy)+10)\n        a=[omx-ox,omy-oy,mw,mh]\n        x.strokeRect(a[0]-10,a[1]-10,a[2],a[3])\n        tools.menu.x=a[0]\n        tools.menu.y=a[1]\n        x.strokeStyle=\'#fff3\'\n        x.fillStyle=\'#023c\'\n        x.fillRect(...tools.menu.boundingRect=[a[0]-10,a[1]-10,a[2],a[3]])\n        x.lineJoin=x.lineCap=\'butt\'\n        x.font=tools.menu.fontSize+\'px courier\'\n        x.fillStyle=\'#8fc\'\n        \n        x.globalAlpha=.6\n        x.drawImage(tools.menu.visible?hideIcon:showIcon,...(tools.menu.toggleButton=[a[0]+a[2]-65,a[1]+3,40,40]))\n        x.globalAlpha=1\n        \n        if(!tools.menu.options.length){\n          if(draggingShape && draggingShapes.length){\n            tools.menu.options=[\n              ...tools.menu.optionsMode.allMenus,\n              ...tools.menu.optionsMode[tools.selectMode],\n            ]\n          } else {\n            tools.menu.options=[\n              ...tools.menu.optionsMode.allMenus,\n              ...tools.menu.optionsMode[\'default\'],\n            ]\n          }\n        }\n        \n        rw=0\n        tools.menu.options.map(v=>{\n          renderMenuItem(tools.menu.x,tools.menu.y+tools.menu.fontSize*(rw+1), v, rw++)\n        })\n      }\n      \n      processMouse=e=>{\n        \n        dmX=dmY=0\n        if(e.movementX>0)dmX=(100+e.movementX)/10\n        if(e.movementX<0)dmX=(-100+e.movementX)/10\n        if(e.movementY>0)dmY=(100+e.movementY)/10\n        if(e.movementY<0)dmY=(-100+e.movementY)/10\n        if(mbuttons[0] && !freshClick && tools.menu.visible) return\n        if(editable && !tools.hover){\n          if(mbuttons[0] && !menuHover()){\n            tools.marq.x=tools.marq.x==-1?mx:tools.marq.x\n            tools.marq.y=tools.marq.y==-1?my:tools.marq.y\n            tools.marq.w+=e.movementX\n            tools.marq.h+=e.movementY\n          }\n        }\n        \n        if((tools.selectMode !==\'shape\' && !mbuttons[0]) || !cct && !tools.menu.visible && !tools.hover){\n          draggingShape=false\n          draggingShapes=[]\n        }\n        if((tools.marq.x==-1 || (cct && freshClick || draggingShape)) && (mbuttons[0] || mbuttons[2]) && editable && !menuHover()){\n          d1=dmX*500/(1+100/((1+Z)**2))/8000\n          d2=dmY*500/(1+100/((1+Z)**2))/8000\n          let Z_=6e6\n          if(tools.selectMode==\'face\'){\n            switch(tools.transformMode){\n              case \'move\':\n                doFaceMove()\n              break\n              case \'rotate\':\n                doFaceRotation()\n              break\n              case \'scale\':\n              break\n            }\n          }\n          shps.map((v,i)=>{\n            if(i<shps.length-1){\n              if(v[v.length-1]){\n                if(tools.selectMode==\'shape\'){\n                  switch(tools.transformMode){\n                    case \'move\':\n                      doMove(v)\n                    break\n                    case \'rotate\':\n                      doRotation(v)\n                    break\n                    case \'scale\':\n                      doScale(v)\n                    break\n                  }\n                }\n              }\n              X=v[0]\n              Y=v[1]\n              Z=v[2]\n              R(Rl,Pt,Yw,1)\n              switch(tools.selectMode){\n                case \'vertex\':\n                  v[6].map((n,m)=>{\n                    if(n.length>1){\n                      n.map(v=>{\n                        if(v[v.length-1]){\n                          draggingShape=true\n                          draggingShapes=[...draggingShapes,[i,m]]\n                          if(mbuttons[0]){\n                            switch(tools.transformMode){\n                              case \'move\':\n                                v[0]+=S(p=-Yw+Math.PI/2)*d1*C(Pt)-S(Pt)*(S(q=-Yw+Math.PI/2)*d1+C(q)*d2)*-S(Pt)\n                                v[1]+=C(Pt)*d2\n                                v[2]+=C(p)*d1*C(Pt)+S(Pt)*(S(q)*d2-C(q)*d1)\n                              break\n                              case \'rotate\':\n                              break\n                              case \'scale\':\n                              break\n                            }\n                          }\n                        }\n                      })\n                    }\n                  })\n                break\n                case \'face\':\n                  if(cct){\n                    v[6].map((n,m)=>{\n                      if(n.length>1){\n                        n.map(v=>{\n                          if(!tools.detachFace){\n                            if(v[v.length-1]){\n                              draggingShape=true\n                              draggingShapes=[...draggingShapes,[i,m]]\n                              if(mbuttons[0]){\n                                switch(tools.transformMode){\n                                  case \'move\':\n                                  break\n                                  case \'rotate\':\n                                    //console.log(2)\n                                    //doFaceRotation(v)\n                                  break\n                                  case \'scale\':\n                                    //doScale(v)\n                                  break\n                                }\n                              }\n                            }\n                          } else {\n                            if(n[n.length-1]){\n                              draggingShape=true\n                              draggingShapes=[...draggingShapes,[i,m]]\n                              if(mbuttons[0]){\n                                switch(tools.transformMode){\n                                  case \'move\':\n                                    v[0]+=S(p=-Yw+Math.PI/2)*d1*C(Pt)-S(Pt)*(S(q=-Yw+Math.PI/2)*d1+C(q)*d2)*-S(Pt)\n                                    v[1]+=C(Pt)*d2\n                                    v[2]+=C(p)*d1*C(Pt)+S(Pt)*(S(q)*d2-C(q)*d1)\n                                  break\n                                  case \'rotate\':\n                                    //doFaceRotation(v)\n                                  break\n                                  case \'scale\':\n                                    //doScale(v)\n                                  break\n                                }\n                              }\n                            }\n                          }\n                        })\n                      }\n                    })\n                  } else {\n                    v[6].map((n,m,a)=>{\n                      if(n.length>1){\n                        n.map((v,i)=>{\n                          if(!tools.detachFace){\n                            if(n[n.length-1]){\n                              draggingShape=true\n                              draggingShapes=[...draggingShapes,[i,m]]\n                              if(mbuttons[0]){\n                                switch(tools.transformMode){\n                                  case \'move\':\n                                    lx=v[0]\n                                    ly=v[1]\n                                    lz=v[2]\n                                    v[0]+=S(p=-Yw+Math.PI/2)*d1*C(Pt)-S(Pt)*(S(q=-Yw+Math.PI/2)*d1+C(q)*d2)*-S(Pt)\n                                    v[1]+=C(Pt)*d2\n                                    v[2]+=C(p)*d1*C(Pt)+S(Pt)*(S(q)*d2-C(q)*d1)\n                                    a.map((q,j)=>{\n                                      if(q.length){\n                                        q.map((l,n)=>{\n                                          if(l.length){\n                                            if((d=H(l[0]-lx,l[1]-ly,l[2]-lz))<.1){\n                                              l[0]=v[0]\n                                              l[1]=v[1]\n                                              l[2]=v[2]\n                                            }\n                                          }\n                                        })\n                                      }\n                                    })\n                                  break\n                                  case \'rotate\':\n                                    //doFaceRotation(v)\n                                  break\n                                  case \'scale\':\n                                    //doScale(v)\n                                  break\n                                }\n                              }\n                            }\n                          } else {\n                            if(n[n.length-1]){\n                              draggingShape=true\n                              draggingShapes=[...draggingShapes,[i,m]]\n                              if(mbuttons[0]){\n                                switch(tools.transformMode){\n                                  case \'move\':\n                                    v[0]+=S(p=-Yw+Math.PI/2)*d1*C(Pt)-S(Pt)*(S(q=-Yw+Math.PI/2)*d1+C(q)*d2)*-S(Pt)\n                                    v[1]+=C(Pt)*d2\n                                    v[2]+=C(p)*d1*C(Pt)+S(Pt)*(S(q)*d2-C(q)*d1)\n                                  break\n                                  case \'rotate\':\n                                    //doFaceRotation(v)\n                                  break\n                                  case \'scale\':\n                                    //doScale(v)\n                                  break\n                                }\n                              }\n                            }\n                          }\n                        })\n                      }\n                    })\n                  }\n                break\n                case \'shape\':\n                  if(Z>0&&Z<Z_&&v[6].filter(q=>q[q.length-1]).length){\n                    draggingShape=true\n                    draggingShapes=[...draggingShapes,[i]]\n                    if(mbuttons[0]){\n                      switch(tools.transformMode){\n                        case \'move\':\n                          //v[0]+=S(p=-Yw+Math.PI/2)*d1*C(Pt)-S(Pt)*(S(q=-Yw+Math.PI/2)*d1+C(q)*d2)*-S(Pt)\n                          //v[1]+=C(Pt)*d2\n                          //v[2]+=C(p)*d1*C(Pt)+S(Pt)*(S(q)*d2-C(q)*d1)\n                        break\n                        case \'rotate\':\n                          //doRotation(v)\n                        break\n                        case \'scale\':\n                          //doScale(v)\n                        break\n                      }\n                      Z_=Z\n                    }\n                  }\n                break\n              }\n            }\n          })\n        }\n        tools.gyro.hover=Math.hypot(mx-(tools.gyro.x+c.width/2),my-tools.gyro.y)<75\n        tools.move.hover=Math.hypot(mx-tools.move.x,my-tools.move.y)<75\n        tools.info.hover= mx>tools.info.toggleButton[0] && mx < tools.info.toggleButton[0]+tools.info.toggleButton[2] &&\n           my>tools.info.toggleButton[1] && my < tools.info.toggleButton[1]+tools.info.toggleButton[3]\n        tools.menu.hover= mx>tools.menu.toggleButton[0] && mx < tools.menu.toggleButton[0]+tools.menu.toggleButton[2] &&\n           my>tools.menu.toggleButton[1] && my < tools.menu.toggleButton[1]+tools.menu.toggleButton[3]\n        for (let [key, value] of Object.entries(tools)){\n          if(mbuttons[0] && tools[key].hover){\n            switch(key){\n              case \'menu\':\n               if(!tools.menu.toggled){\n                tools.menu.visible = !tools.menu.visible\n                tools.menu.toggled = true\n               }\n              break\n              case \'info\':\n               if(!tools.info.toggled){\n                tools.info.visible = !tools.info.visible\n                tools.info.toggled = true\n               }\n              break\n              case \'gyro\':\n                if(!tools.menu.visible){\n                  if(keys[16]){\n                    Rl+=dmX/1000\n                    Pt-=dmY/1000\n                    Pt=Math.min(Math.PI/2, Math.max(-Math.PI/2,Pt))\n                  }else{\n                    Yw-=dmX/1000\n                    Pt-=dmY/1000\n                    Pt=Math.min(Math.PI/2, Math.max(-Math.PI/2,Pt))\n                  }\n                }\n              break;\n              case \'move\':\n                if(!tools.menu.visible){\n                  d1=dmX/100\n                  d2=dmY/100\n                  if(keys[16]){\n                    oX-=S(p=-Yw+Math.PI/2)*d1\n                    oY-=d2\n                    oZ-=C(p)*d1\n                  } else {\n                    oX-=S(p=-Yw+Math.PI/2)*d1-S(q=-Yw)*d2\n                    oY-=0\n                    oZ-=C(p)*d1-C(q)*d2\n                  }\n                }\n              break;\n            }\n          }\n        }\n        \n        //document.body.style.cursor = editable ? \'pointer\' : tools.defaultCursor\n        document.body.style.cursor = tools.hover ? \'pointer\' : tools.defaultCursor\n        tools.menu.items.map(v=>{\n          if(mx>v[1][0] && mx<v[1][0]+v[1][2] &&  my>v[1][1]&&my<v[1][1]+v[1][3]){\n            document.body.style.cursor=\'pointer\'\n            if(mbuttons[0] && v[0].func){\n              doAction(v)\n            }\n          }\n        })\n        if(mbuttons[0]){\n          if(!menuHover()){\n            closeMenus()\n          }\n        }\n        if(tools.menu.visible){\n          draggingShape=true\n        }\n        if(!cct && !draggingShape && freshClick && !draggingShapes.length){\n          tools.marq.x=-1\n          tools.marq.y=-1\n          tools.marq.w=tools.marq.h=0\n        }\n      }\n      \n      menuHover=()=>{\n        return tools.menu.visible && !(mx<tools.menu.boundingRect[0] || my<tools.menu.boundingRect[1] ||\n           mx>tools.menu.boundingRect[0]+tools.menu.boundingRect[2] ||\n           my>tools.menu.boundingRect[1]+tools.menu.boundingRect[3])\n      }\n\n      processKeys=e=>{\n        switch(e.keyCode){\n          case 46:\n            switch(tools.selectMode){\n              case \'vertex\':\n                shps=shps.map(v=>{\n                  v[6]=v[6].filter(q=>{\n                    keepPoly=true\n                    if(q.length){\n                      keepPoly=!q.filter(n=>{\n                        return n[3]\n                      }).length\n                    }\n                    return keepPoly\n                  })\n                  return v\n                })\n              break\n              case \'face\':\n                shps=shps.map(v=>{\n                  v[6]=v[6].filter(q=>{\n                    return !q.length || !q.filter(n=>n[n.length-1]).length\n                  })\n                  return v\n                })\n              break\n              case \'shape\':\n                shps=shps.filter((v,i)=>!v[v.length-1])\n              break\n            }\n            draggingShapes=[]\n          break;\n          case 27:\n            tools.marq.x=tools.marq.y=-1\n            tools.marq.w=tools.marq.h=0\n            if(tools.menu.visible) closeMenus()\n          break\n          case 116:\n            window.location.reload()\n          break\n          case 49:\n            tools.selectMode=\'vertex\'\n          break\n          case 50:\n            tools.selectMode=\'face\'\n          break\n          case 71:\n            tools.showGlobalSphere=!tools.showGlobalSphere\n          break\n          case 51:\n            tools.selectMode=\'shape\'\n          break\n          case 84:\n            tools.show = !tools.show\n          break\n          case 70:\n            tools.showFloor=!tools.showFloor\n          break\n          case 89:\n            tools.fly.enabled = !tools.fly.enabled\n          break\n          case 86:\n            tools.viewfinder.visible = !tools.viewfinder.visible\n          break\n        }\n        if(tools.selectMode !== \'shape\') tools.transformMode = \'move\'\n      }\n\n      moveIcon = new Image()\n      moveIcon.src = \'/proxy.php?url=https://srmcgann.github.io/assets/1jIQ7v.png\'\n      showCursorDot=false\n      mx=c.width-10\n      my=10\n      mdx=mdy=0\n      mbuttons=Array(3).fill(false)\n      keys=Array(256).fill(false)\n      window.onkeydown=e=>{\n        e.stopPropagation()\n        e.preventDefault()\n        keys[e.keyCode]=true\n        processKeys(e)\n      }\n      window.onkeyup=e=>{\n        keys[e.keyCode]=false\n        if(e.keyCode==68) shiftCloneComplete=false\n      }\n      window.onwheel=e=>{\n        if(!tools.menu.visible){\n          oXv+=S(p=-Yw)*C(q=Pt)*e.deltaY/300\n          if(tools.fly.enabled) oYv-=S(q)*e.deltaY/300\n          oZv+=C(p)*C(q)*e.deltaY/300\n        }\n      }\n      window.onmousemove=e=>{\n        if(!mbuttons[0] && !mbuttons[2]){\n          let rect = c.getBoundingClientRect()\n          mx=(e.x-(rect.left+2))/(c.clientWidth)*c.width\n          my=(e.y-(rect.top+2))/(c.clientHeight)*c.height\n        }\n\n        if(!shiftCloneComplete && cloneShapeQueue.length){\n          cloneShapeQueue.map(v=>{\n            pushShape(...v)\n          })\n          cloneShapeQueue=[] \n          shiftCloneComplete=true\n        }\n\n        processMouse(e)\n      }\n      \n      c.onmousedown = c.onmouseup = canvas2.onmousedown = canvas2.onmouseup = e => {\n        //e.stopPropagation()\n        e.preventDefault()\n        return null\n      }\n      \n      deselectAll=()=>{\n        ct=cct=0\n        shps.map((v,i)=>{\n          if(i<shps.length-1){\n            v[v.length-1]=false\n            v[6].map((q,j)=>{\n              if(j<v[6].length-1){\n                q[q.length-1]=false\n                if(j<v[6].length){\n                  q.map(n=>{\n                    n[3]=false\n                  })\n                }\n              }\n            })\n          }\n        })\n        //freshClick=true\n        allSelected = false\n        tools.marq.x=-1\n        tools.marq.y=-1\n        tools.marq.w=tools.marq.h=0\n        draggingShape=false\n        draggingShapes=[]\n      }\n      \n      canvas2.onmousedown=e=>{\n        if(tools.transformMode==\'rotate\')gGyro=defaultGyro()\n        e.preventDefault()\n        e.stopPropagation()\n        c.requestPointerLock()\n        let rect = c.getBoundingClientRect()\n        mx=(e.x-(rect.left+2))/(c.clientWidth)*c.width\n        my=(e.y-(rect.top+2))/(c.clientHeight)*c.height\n        mdx=mx\n        mdy=my\n        freshClick=true\n        mbuttons[e.button]=true\n        if(keys[16] && mbuttons[0]) shiftCloneComplete=false\n\n        if(mbuttons[0] && tools.transformMode == \'rotate\'){\n          gGyro = defaultGyro()\n        }\n\n        if(mbuttons[2]){\n          if(tools.menu.visible){\n            draggingShape=false\n            draggingShapes=[]\n            closeMenus()\n            omx=mx\n            omy=my\n            //processMouse(e)\n          }\n          omx=mx\n          omy=my\n        }\n          if(e.button==0 && !tools.menu.visible && !tools.hover && !menuHover() && !draggingShape) deselectAll()\n          //checkHover()\n          processMouse(e)\n      }\n      window.onmouseup=e=>{\n        d1=d2=td1=td2=0\n        if(tools.transformMode==\'rotate\')gGyro=defaultGyro()\n        shiftCloneComplete = false\n        e.preventDefault()\n        e.stopPropagation()\n        gotRotCenters=false\n        mbuttons[e.button]=false\n        document.exitPointerLock()\n        tools.info.toggled=false\n        tools.menu.toggled=false\n        //setTimeout(()=>{\n          if(Math.abs(tools.marq.w)<3 && Math.abs(tools.marq.h)<3) deselectAll()\n        //},0)\n      }\n      R=(Rl,Pt,Yw,o)=>{\n        if(o)X+=oX,Y+=oY,Z+=oZ\n        A=(M=Math).atan2\n        H=M.hypot\n        X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n        X=S(p=A(X,Y)+Rl)*(d=H(X,Y)),Y=C(p)*d\n        Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d\n      }\n      R2=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n      printLn=(s,ln,indent,dest)=>{\n        x.fillText(s, tools[dest].x+(tools[dest].fontSize*indent), tools[dest].y+tools[dest].fontSize*(ln+1))\n        x.strokeText(s, tools[dest].x+(tools[dest].fontSize*indent), tools[dest].y+tools[dest].fontSize*(ln+1))\n      }\n      DrawSolid=(dod, sx, sy, sz, rl, pt, yw, strokeStyle, fillStyle, useFill, globalAlpha, editable, wireframe) => {\n        dod.sort((a,b)=>{\n          if(a.length&&b.length){\n            ax=zy=az=0\n            a.filter(q=>q.length).map(q=>{\n              X=q[0]\n              Y=q[1]\n              Z=q[2]\n              R2(rl,pt,yw,0)\n              ax+=X+sx\n              ay+=Y+sy\n              az+=Z+sz\n            })\n            X=ax/=a.length-1\n            Y=ay/=a.length-1\n            Z=az/=a.length-1\n            R(Rl,Pt,Yw,1)\n            Z1=Z\n            bx=by=bz=0\n            b.filter(q=>q.length).map(q=>{\n              X=q[0]\n              Y=q[1]\n              Z=q[2]\n              //R2(rl,pt,yw,0)\n              bx+=X+sx\n              by+=Y+sy\n              bz+=Z+sz\n            })\n            X=bx/=b.length-1\n            Y=by/=b.length-1\n            Z=bz/=b.length-1\n            R(Rl,Pt,Yw,1)\n            Z2=Z\n            return Z2-Z1\n          }\n        })\n        dod.map((v,i)=>{\n          if(v.length){\n            if(wireframe) x.beginPath()\n            if(editable) a=[]\n            v.map((q,j)=>{\n              if(q.length){\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                //R2(rl,pt,yw,0)\n                X+=sx\n                Y+=sy\n                Z+=sz\n                R(Rl,Pt,Yw,1)\n                let l=[...Q(), Z, j, i]\n                if(editable){\n                  a = [...a, l]\n                }\n                if(Z>0 && wireframe) x.lineTo(...l)\n              }\n            })\n            if(Z>0 && wireframe){\n              if(editable) interfaceBufferQueue=[...interfaceBufferQueue, a]\n              x.closePath()\n              x.lineWidth=Math.min(200,500/(Z**1.35))|0\n              //x.globalAlpha=.3*globalAlpha\n              //x.strokeStyle=strokeStyle\n              //x.stroke()\n              x.lineWidth/=7\n              x.lineWidth=Math.max(x.lineWidth|0, 1)\n              x.globalAlpha=1*globalAlpha\n              x.strokeStyle=strokeStyle\n              x.stroke()\n            }\n          }\n        })\n\n        \n        let sel=editable && tools.selectMode==\'shape\'&&(dod.filter(v=>v[v.length-1]).length)\n        dod.map((v,i)=>{\n          if(useFill){\n            if(v.length){\n              x.beginPath()\n              v.map((q,j)=>{\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                //R2(rl,pt,yw,0)\n                X+=sx\n                Y+=sy\n                Z+=sz\n                R(Rl,Pt,Yw,1)\n                if(Z>0)x.lineTo(...Q())\n              })\n              x.globalAlpha=globalAlpha\n              x.fillStyle=(v[v.length-1]&&tools.selectMode==\'face\'||sel?highlightColor:fillStyle)\n              x.fill()\n            }\n          }\n        })\n        \n        // vertex hover\n        if(editable && tools.selectMode == \'vertex\'){\n          dod.map((v,i)=>{\n            if(v.length){\n              v.map((q,j)=>{\n                if(q[3]){\n                  X=q[0]\n                  Y=q[1]\n                  Z=q[2]\n                  //R2(rl,pt,yw,0)\n                  X+=sx\n                  Y+=sy\n                  Z+=sz\n                  R(Rl,Pt,Yw,1)\n                  if(Z>0){\n                    l=Q()\n                    s=Math.max(10, Math.min(100, 200/(1+Z)))\n                    x.fillStyle=highlightColor\n                    x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n                  }\n                }\n                //if(!draggingShape) q[3]=false\n              })\n            }\n          })\n        }\n      }\n\n      Sphere=(ls,cl,rw)=>{\n        let X,Y,Z\n        let ret=[]\n        for(i=cl*rw;i--;){\n          a=[]\n          j=i%cl\n          k=(i/cl|0)\n          l=(j+1)%cl\n          \n          X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*k)*ls\n          Y=C(q)*ls\n          Z=C(p)*S(q)*ls\n          a=[...a,[X,Y,Z]]\n          X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*k)*ls\n          Y=C(q)*ls\n          Z=C(p)*S(q)*ls\n          a=[...a,[X,Y,Z]]\n          X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*(k+1))*ls\n          Y=C(q)*ls\n          Z=C(p)*S(q)*ls\n          a=[...a,[X,Y,Z]]\n          X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*(k+1))*ls\n          Y=C(q)*ls\n          Z=C(p)*S(q)*ls\n          a=[...a,[X,Y,Z]]\n          \n          ret = [...ret, a]\n        }\n        return ret\n      }\n\n      Tetrahedron=ls=>{\n        let ret=[]\n        let a = []\n        let theta=1.2217304763960306\n        for(let i=3;i--;){\n          X=S(p=Math.PI*2/3*i)\n          Y=C(p)+.5\n          Z=0\n          R2(0,-theta/2,0)\n          a=[...a, [X,Y,Z]]\n        }\n        ret=[...ret, a]\n        b=JSON.parse(JSON.stringify(a))\n        ax=ay=az=0\n        b.map(v=>{\n          X=v[0]\n          Y=v[1]\n          Z=v[2]\n          R2(0,theta,0)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n        })\n        ret=[...ret, b]\n        ct=0\n        ret.map(v=>{\n          v.map(q=>{\n            ax+=q[0]\n            ay+=q[1]\n            az+=q[2]\n            ct++\n          })\n        })\n        ax/=ct\n        ay/=ct\n        az/=ct\n        ret.map(v=>{\n          v.map(q=>{\n            q[0]-=ax*1.5\n            q[1]-=ay*1.5\n            q[2]-=az*1.5\n          })\n        })\n\n        b=JSON.parse(JSON.stringify(ret))\n        b.map(v=>{\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R2(0,Math.PI,Math.PI/2)\n            q[0]=X\n            q[1]=Y\n            q[2]=Z\n          })\n        })\n        ret=[...ret, ...b]\n        \n        ret.map(v=>{\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R2(0,.96,0)\n            R2(0,0,t*5)\n            R2(0,Math.PI,0)\n            q[0]=X\n            q[1]=Y\n            q[2]=Z\n            d=Math.hypot(...q)\n            q[0]/=d\n            q[1]/=d\n            q[2]/=d\n            q[0]*=ls\n            q[1]*=ls\n            q[2]*=ls\n          })\n        })\n        return ret\n      }\n      \n      Octahedron=ls=>{\n        ret = []\n        a=[]\n        for(i=4;i--;){\n          X1=S(p=Math.PI*2/4*i+Math.PI/4)\n          Y1=C(p)\n          Z1=0\n          X2=S(p=Math.PI*2/4*(i+1)+Math.PI/4)\n          Y2=C(p)\n          Z2=0\n          X3=0\n          Y3=0\n          Z3=1\n          a=[\n            [X1,Y1,Z1],\n            [X2,Y2,Z2],\n            [X3,Y3,Z3]\n          ]\n          ret=[...ret, a]\n          a=[\n            [X1,Y1,-Z1],\n            [X2,Y2,-Z2],\n            [X3,Y3,-Z3]\n          ]\n          ret=[...ret, a]\n        }\n        ret.map(v=>{\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R2(0,Math.PI/2,Math.PI/2)\n            q[0]=X\n            q[1]=Y\n            q[2]=Z\n            d=Math.hypot(...q)\n            q[0]/=d\n            q[1]/=d\n            q[2]/=d\n            q[0]*=ls\n            q[1]*=ls\n            q[2]*=ls\n          })\n        })\n        return ret\n      }\n      \n      Cube=ls=>{\n        let ret=[]\n        for(j=6;j--;ret=[...ret,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-ls:ls),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n        ret.map(v=>{\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R2(0,0,t*5)\n            q[0]=X\n            q[1]=Y\n            q[2]=Z\n            d=Math.hypot(...q)\n            q[0]/=d\n            q[1]/=d\n            q[2]/=d\n            q[0]*=ls\n            q[1]*=ls\n            q[2]*=ls\n          })\n        })\n        return ret\n      }\n      \n      Icosahedron=ls=>{\n        let a=[1,1],ret=[]\n        let b\n        for(i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]];\n        let phi=a[l]/a[l-1]\n        a=[[[-phi,-1,0],[phi,-1,0],[phi,1,0],[-phi,1,0]],[[0,-phi,-1],[0,phi,-1],[0,phi,1],[0,-phi,1]],[[-1,0,-phi],[-1,0,phi],[1,0,phi],[1,0,-phi]]]\n        let ico=[[[0,1],[1,0],[1,3]],[[0,1],[2,3],[1,0]],[[2,0],[2,3],[1,0]],[[0,1],[2,3],[0,2]],[[1,1],[2,3],[0,2]],[[1,1],[2,3],[2,0]],[[1,1],[1,2],[0,2]],[[0,1],[2,2],[0,2]],[[0,0],[1,0],[2,0]],[[2,0],[0,3],[0,0]],[[1,1],[1,2],[0,3]],[[1,1],[2,0],[0,3]],[[0,1],[1,3],[2,2]],[[1,3],[2,1],[2,2]],[[2,1],[0,3],[1,2]],[[2,1],[0,0],[1,3]],[[1,2],[2,2],[2,1]],[[2,2],[1,2],[0,2]],[[0,3],[2,1],[0,0]],[[1,3],[1,0],[0,0]]]\n        ico.map((v,i)=>{\n          b=[]\n          v.map(q=>{\n            t1=q[0],t2=q[1]\n            X=a[t1][t2][0],Y=a[t1][t2][1],Z=a[t1][t2][2]\n            b=[...b, [X,Y,Z]]\n          })\n          ret=[...ret, b]\n        })\n        ret.map(v=>{\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R2(0,0,Math.PI/2)\n            q[0]=X\n            q[1]=Y\n            q[2]=Z\n            d=Math.hypot(...q)\n            q[0]/=d\n            q[1]/=d\n            q[2]/=d\n            q[0]*=ls\n            q[1]*=ls\n            q[2]*=ls\n          })\n        })\n        return ret\n      }\n\n      Dodecahedron=ls=>{\n        let ret=[]\n        let sd=5\n        let a=[], b=[]\n        mind=6e6\n        for(let i=sd;i--;){\n          X=S(p=Math.PI*2/sd*i)\n          Y=C(p)\n          Z=0\n          if(Y<mind)mind=Y\n          a = [...a, [X,Y,Z]]\n        }\n        a=a.map(v=>{\n          X=v[0]\n          Y=v[1]-=mind\n          Z=v[2]\n          R2(0,.5535735,0)\n          return [X,Y,Z]\n        })\n        \n        ret = [...ret, a]\n        b=JSON.parse(JSON.stringify(a)).map(v=>{\n          d=Math.hypot(v[0],v[1])\n          v[0]=S(p=Math.atan2(v[0],v[1])+Math.PI)*d\n          v[1]=C(p)*d\n          return v\n        })\n        ret = [...ret, b]\n        \n        ret.map(v=>{\n          v.map(q=>{\n            if(q[2]<mind)mind=q[2]\n          })\n        })\n        ret.map(v=>{\n          v.map(q=>{\n            q[2]+=ang=1.538840639715\n          })\n        })\n        b=JSON.parse(JSON.stringify(ret)).map(v=>{\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R2(Math.PI,0,Math.PI)\n            q[0]=X\n            q[1]=Y\n            q[2]=Z\n          })\n          return v\n        })\n        e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n        \n        b=JSON.parse(JSON.stringify(ret)).map(v=>{\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R2(0,Math.PI/2,Math.PI/2)\n            q[0]=X\n            q[1]=Y\n            q[2]=Z\n          })\n          return v\n        })\n        ret = [...ret, ...b]\n\n        b=JSON.parse(JSON.stringify(e)).map(v=>{\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R2(Math.PI/2,0,Math.PI/2)\n            q[0]=X\n            q[1]=Y\n            q[2]=Z\n          })\n          return v\n        })\n        ret = [...ret, ...b]\n        \n        ret.map(v=>{\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R2(0,0,t*5)\n            q[0]=X\n            q[1]=Y\n            q[2]=Z\n            d=Math.hypot(...q)\n            q[0]/=d\n            q[1]/=d\n            q[2]/=d\n            q[0]*=ls\n            q[1]*=ls\n            q[2]*=ls\n          })\n        })\n        return ret\n      }\n\n      bcl=32,brw=32,sp=(2**.5)*4\n      a=[]\n      B=Array(bcl*brw+1).fill().map((v,i)=>{\n        tx=((i%bcl)-bcl/2+.5)*sp\n        ty=0\n        tz=((i/bcl|0)-brw/2+.5)*sp\n        sp=2**.5/2*4\n        for(j=4;j--;){\n          X=S(p=Math.PI*2/4*j+Math.PI/4)/2*4\n          Y=0\n          Z=C(p)/2*4\n          a=[...a, [tx,ty,tz,X,Y,Z]]\n        }\n      })\n      B=a\n      ls=.05\n      tools.gyro.y = 50+10\n      Gyro=Array(3).fill().map((v,i)=>{\n        return Array(20).fill().map((q,j)=>{\n          a=[S(p=Math.PI*2/20*j)*ls,C(p)*ls,0]\n          return [a[i],a[(i+1)%3],a[(i+2)%3]]\n        })\n      })\n      oRl=Rl=0,oPt=Pt=0,oYw=Yw=0\n      ooX=oX=0,ooY=oY=3,ooZ=oZ=20\n      \n      iSc=0, G=30, shape_ls=3\n      \n      \n      defaultGyro = () => {\n        rsd=20, ret=[], axisLength=4\n        a=[]\n        for(let i=rsd;i--;){\n          X=S(p=Math.PI*2/rsd*i)*axisLength\n          Y=0\n          Z=C(p)*axisLength\n          a=[...a, [X,Y,Z]]\n        }\n        ret=[...ret, a]\n        a=[]\n        for(let i=rsd;i--;){\n          X=0\n          Y=S(p=Math.PI*2/rsd*i)*axisLength\n          Z=C(p)*axisLength\n          a=[...a, [X,Y,Z]]\n        }\n        ret=[...ret, a]\n        a=[]\n        for(let i=rsd;i--;){\n          X=S(p=Math.PI*2/rsd*i)*axisLength\n          Y=C(p)*axisLength\n          Z=0\n          a=[...a, [X,Y,Z]]\n        }\n        ret=[...ret, a]\n      \n        return ret\n      }\n      \n      gGyro=defaultGyro()\n      \n      base_shapes=[\n        {shape: Tetrahedron(shape_ls), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: Cube(shape_ls), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: Octahedron(shape_ls), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: Dodecahedron(shape_ls), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: Icosahedron(shape_ls), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: Sphere(shape_ls, 10, 8), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: await loadOBJ(\'https://twilightparadox.com/chair.obj\', 8, 0, 0, 0, 0, 0, Math.PI), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        //{shape: await loadOBJ(\'https://twilightparadox.com/wolf.obj\', .005, 0, 0, 0, 0, 0, Math.PI), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: await loadOBJ(\'https://twilightparadox.com/tiger.obj\', .01, 2, 0, 0, 0, 0, Math.PI/4+Math.PI/2), color: \'#fc02\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: await loadOBJ(\'https://twilightparadox.com/fish.obj\', 2, 0, 0, 0, 0, 0, Math.PI/2), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: await loadOBJ(\'https://twilightparadox.com/WoodHouse.obj\', 8, 0, 0, 0, 0, 0,0), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        //{shape: await loadOBJ(\'https://twilightparadox.com/gymnast.obj\', 1, 0, 0, 0, 0, Math.PI/2, 0), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        //{shape: await loadOBJ(\'https://twilightparadox.com/angel.obj\', 1, 0, 0, 0, 0, Math.PI/2, 0), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: Sphere(shape_ls, 10*1.5*1|0, 8*1.5*1|0), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: Sphere(shape_ls, 10*1.5*2|0, 8*1.5*2|0), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: Sphere(shape_ls, 10*1.5*3|0, 8*1.5*3|0), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: Sphere(shape_ls, 10*1.5*4|0, 8*1.5*4|0), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        //{shape: await loadOBJ(\'https://twilightparadox.com/stool.obj\', 1.5, 0, 0, 0, 0, 0,0), color: \'#4403\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        //{shape: await loadOBJ(\'https://twilightparadox.com/eyeball.obj\', 1.5, 0, 0, 0, 0, 0,0), color: \'#4403\', wireframe: false, useFill: true, gyro: defaultGyro()},\n        {shape: await loadOBJ(\'https://twilightparadox.com/axe.obj\', 20, 0, 0, 0, 0, 0,Math.PI/2), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: await loadOBJ(\'https://twilightparadox.com/pickaxe.obj\', 20, 0, 0, 0, 0, 0,Math.PI/2), color: \'#2063\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: await loadOBJ(\'https://twilightparadox.com/tree1.obj\', 1, 0, 0, 0, 0, 0,Math.PI/2), color: \'#2063\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        //{shape: await loadReducedOBJ(\'https://twilightparadox.com/reduceObjPolys/fish.obj\', 2,0,0,0,0,0,Math.PI/2, 80), color: \'#2063\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: await loadOBJ(\'https://twilightparadox.com/house2.obj\', 1, 0, 0, 0, 0, 0,0), color: \'#f001\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        {shape: await loadOBJ(\'https://twilightparadox.com/tree2.obj\', .03, 0, 0, 0, 0, -Math.PI/2, 0), color: \'#0633\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        //{shape: await loadOBJ(\'https://twilightparadox.com/butterfly.obj\', 150, 0, 0, 0, 0, 0, Math.PI/2), color: \'#0643\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        //{shape: await loadReducedOBJ(\'https://twilightparadox.com/reduceObjPolys/butterfly.obj\', 50,0,0,0,0,0,Math.PI/2, 80), color: \'#2063\', wireframe: true, useFill: true, gyro: defaultGyro()},\n        //{shape: await loadOBJ(\'https://twilightparadox.com/ladybug.obj\', 1500, 5, 0, 0, 0, 0, Math.PI/2), color: \'#f003\', wireframe: true, useFill: true, gyro: defaultGyro()},\n      ]\n      if(urlOBJ) base_shapes=[...base_shapes, {shape: await loadOBJ(OBJurl, 5, 0, 0, 0, 0, 0, Math.PI/2), color: \'#2063\', wireframe: true, useFill: true, gyro: defaultGyro()}]\n      pushShape=(shape, tx, ty, tz, rl, pt, yw, color, wireframe, useFill, gyro) =>  {\n\n        shp = JSON.parse(JSON.stringify(shape))\n        shp = shp.map(q=>{\n          q=q.map(n=>{\n            X=n[0]\n            Y=n[1]\n            Z=n[2]\n            R(rl,0,0,0)\n            R(0,pt,0,0)\n            R(0,0,yw,0)\n            //X+=tx\n            //Y+=ty\n            //Z+=tz\n            return [X,Y,Z]\n          })\n          return q\n        })\n        shp.push(false)\n        shp.map(v=>{\n          if(v){\n            v.map(q=>{\n              q.push(false)\n            })\n            v.push(false)\n          }\n        })\n        states = JSON.parse(JSON.stringify(shp)).map(v=>{\n          if(v){\n            return v.map(q=>{\n              if(q){\n                q.map(n=>{\n                  return [Array(4).fill(false)]\n                })\n                return [q, false]\n              }\n            })\n          }\n        })\n        shps = [[tx, ty, tz, 0,0,0, shp, states, color, wireframe, useFill, gyro, false], ...shps]\n      }\n      \n      let id\n      if(urlOBJ){\n        initConfig = 5\n        id=base_shapes.length-1\n        iSc=1\n      } else {\n        initConfig = 0\n        id=11\n      }\n      rl=pt=yw=0\n      shps=[]\n      let shp, states, color\n      for(let i=0;i<iSc+1;i++){\n        color = base_shapes[id].color\n        let shape = base_shapes[id].shape\n        gyro = base_shapes[id].gyro\n        wireframe = base_shapes[id].wireframe\n        useFill = base_shapes[id].useFill\n        if(i==iSc){\n          X=0\n          Y=0\n          Z=0\n          shp = JSON.parse(JSON.stringify(Sphere(10,20,12)))\n        }else{\n          switch(initConfig){\n            case 0:\n              tx=0\n              ty=-shape_ls/1.5*3/2\n              tz=0\n              rl=pt=yw=0\n              shp = JSON.parse(JSON.stringify(shape))\n              shp = shp.map(q=>{\n                q=q.map(n=>{\n                  X=n[0]\n                  Y=n[1]\n                  Z=n[2]\n                  //R(Math.PI*2/(iSc)*i,0,0,0)\n                  return [X,Y,Z]\n                })\n                return q\n              })\n            break\n            case 1: //random everything\n              tx=(Rn()-.5)*G\n              ty=-shape_ls/1.5-(Rn())*shape_ls*10\n              tz=(Rn()-.5)*G\n              rl=pt=yw=0\n              shp = JSON.parse(JSON.stringify(shape))\n              shp = shp.map(q=>{\n                q=q.map(n=>{\n                  X=n[0]\n                  Y=n[1]\n                  Z=n[2]\n                  R(Math.PI*2/(iSc)*i,0,0,0)\n                  return [X,Y,Z]\n                })\n                return q\n              })\n            break\n            case 2:\n              tx=0\n              ty=-shape_ls/1.5\n              tz=i*shape_ls*4\n              rl=pt=yw=0\n              shp = JSON.parse(JSON.stringify(shape))\n              shp = shp.map(q=>{\n                q=q.map(n=>{\n                  X=n[0]\n                  Y=n[1]\n                  Z=n[2]\n                  R(Math.PI*2/(iSc)*i,0,0,0)\n                  return [X,Y,Z]\n                })\n                return q\n              })\n            break\n            case 3:\n              tx=S(p=Math.PI*2/iSc*(i-1))*20\n              ty=0\n              tz=C(p)*20\n              rl=pt=yw=0\n              shp = JSON.parse(JSON.stringify(shape))\n              shp = shp.map(q=>{\n                q=q.map(n=>{\n                  X=n[0]\n                  Y=n[1]\n                  Z=n[2]\n                  R(0,0, Math.PI*2/iSc*(i-1),0)\n                  return [X,Y,Z]\n                })\n                return q\n              })\n              maxY=-6e6\n              shp.map(v=>{\n                if(v.length){\n                  v.map((q,j)=>{\n                    if((Y=q[1])>maxY){\n                      maxY=Y\n                    }\n                  })\n                }\n              })\n              ty=-maxY\n            break\n            case 4:\n              tx=S(p=Math.PI*2/25*(i-1))*(ls=2000/(.1+((i+1)**.5)*500))\n              ty=-i/4\n              tz=C(p)*ls\n              rl=pt=yw=0\n              shp = JSON.parse(JSON.stringify(shape))\n              shp = shp.map(q=>{\n                q=q.map(n=>{\n                  X=n[0]*ls/6\n                  Y=n[1]*ls/6\n                  Z=n[2]*ls/6\n                  R(0,0, Math.PI*2/iSc*(i-1),0)\n                  return [X,Y,Z]\n                })\n                return q\n              })\n            break\n            case 5:\n              tx=0\n              ty=-shape_ls/1.5*3/2\n              tz=0\n              rl=pt=yw=0\n              shp = JSON.parse(JSON.stringify(shape))\n              shp = shp.map(q=>{\n                q=q.map(n=>{\n                  X=n[0]\n                  Y=n[1]\n                  Z=n[2]\n                  //R(Math.PI*2/(iSc)*i,0,0,0)\n                  return [X,Y,Z]\n                })\n                return q\n              })\n            break                  \n          }\n          X=tx\n          Y=ty\n          Z=tz\n        }\n        shp.push(false)\n        shp.map(v=>{\n          if(v){\n            v.map(q=>{\n              q.push(false)\n            })\n            v.push(false)\n          }\n        })\n        states = JSON.parse(JSON.stringify(shp)).map(v=>{\n          if(v){\n            return v.map(q=>{\n              if(q){\n                q.map(n=>{\n                  return [Array(4).fill(false)]\n                })\n                return [q, false]\n              }\n            })\n          }\n        })\n        shps = [...shps, [X, Y, Z, rl, pt, yw, shp, states, color, wireframe, useFill, gyro, false]]\n      }\n      \n      //for(let m=1;m--;) pushShape(base_shapes[9].shape, 5, -4,0, 0, .4, Math.PI/2, \'#0643\', wireframe, gyro)\n      //for(let m=3;m--;) pushShape(base_shapes[8].shape, (Rn()-.5)*G, -2-Rn()*G/4, (Rn()-.5)*G, 0,0,Rn()*Math.PI*2, \'#0643\', wireframe, gyro)\n\n      interfaceBuffer=Array(shps.length-1).fill().map((v,i)=>{\n        return [[],[],0,i]\n      })\n\n      oXv=oYv=oZv=0\n      Rlv=Ptv=Ywv=0\n      mv=.06,rv=.024\n    }\n    selectAll=()=>{\n      gGyro=defaultGyro()\n      allSelected = true\n      ct=cct=0\n      tools.marq.x=tools.marq.y=0\n      tools.marq.w=c.width\n      tools.marq.h=c.height\n      shps.filter((v,i)=>i<shps.length-1).map(v=>{\n        v[6].map(q=>{\n          q[q.length-1]=true\n          cct++\n        })\n        v[v.length-1]=true\n      })\n    }\n    \n    checkHover=()=>{\n      ct=0\n      cct=0\n      tools.hover=false\n      interfaceBuffer.map((v,i,a)=>{\n        if(1||i<interfaceBuffer.length-1){\n          let p\n          if(tools.selectMode !== \'vertex\'){\n            switch(tools.selectMode){\n              case \'shape\':\n                ct=(shps.filter(v=>{\n                  return v[6].filter(q=>{\n                    return q[q.length-1]\n                  }).length\n                }).length)\n                v=interfaceBuffer[interfaceBuffer.length-1-i]\n              break\n              case \'face\':\n                //v=interfaceBuffer[interfaceBuffer.length-1-i]\n                //shps.map(v=>{\n                //  v[6].map(q=>{\n                //    q[q.length-1]=false\n                //  })\n                //})\n              break\n            }\n          }\n          \n          if(1||tools.marq.x!==-1){\n            v[1].map((q,j)=>{\n              if(q.length<v[1].length-1){\n                if(tools.selectMode == \'face\') v[0][j][v[0][j].length-1]=false\n                p=[]\n                a=[]\n                inFront=true\n                q.map((n, m)=>{\n                  if(typeof v[0][j][m] !== \'undefined\'){\n                    if(n[2]<0)inFront=false\n                    if(n.length>2){\n                      if(tools.selectMode==\'vertex\'){\n                        v[0][j][m][3]=n[2]>0&&Math.hypot(mx-n[0], my-n[1])<10\n                        if(v[0][j][m][3]) tools.hover = true\n                      }else{\n                        p=[...p, Math.atan2(mx-n[0], my-n[1])+Math.PI]\n                      }\n                    }\n                  }\n                })\n                if(inFront && tools.selectMode != \'vertex\' && (!ct || cct)){\n                  p.sort((a,b)=>a-b)\n                  p.map((v,i)=>{if(i)a=[...a, p[i]-p[i-1]]})\n                  p[0]+=Math.PI*2\n                  a=[...a, p[0]-p[p.length-1]]\n                  v[0][j][v[0][j].length-1]=!a.filter(v=>v>Math.PI).length\n                  if(v[0][j][v[0][j].length-1]) tools.hover = true\n                }\n                q.map((n, m)=>{\n                  if(typeof v[0][j][m] !== \'undefined\' && n.length>2 && n[2]>=0){\n                    if((tools.selectMode != \'vertex\' || tools.marq.x!==-1) && tools.marq.w!=-1){\n                        X1=Math.min(tools.marq.x,tools.marq.x+tools.marq.w)\n                        X2=Math.max(tools.marq.x,tools.marq.x+tools.marq.w)\n                        Y1=Math.min(tools.marq.y,tools.marq.y+tools.marq.h)\n                        Y2=Math.max(tools.marq.y,tools.marq.y+tools.marq.h)\n                        v[0][j][m][3]=n[0]>X1&&n[0]<X2&&n[1]>Y1&&n[1]<Y2\n                    } else {\n                       if(tools.selectMode != \'vertex\'){\n                         v[0][j][m][3]=!a.filter(v=>v>Math.PI).length\n                       }\n                    }\n                    if(v[0][j][m][3]){\n                      cct++\n                      if(tools.selectMode != \'vertex\') v[0][j][v[0][j].length-1]=true\n                    }\n                    if(v[0][j][v[0][j].length-1] && Math.hypot(mx-n[0], my-n[1])<10){\n                      tools.hover=true\n                    }\n                  }\n                })\n              }\n            })\n          }\n        }\n      })\n      if(tools.selectMode==\'face\' && !cct){\n        shps.map((v,i)=>{\n          v[6].map(q=>{\n            tt=0\n            shps.map(v=>tt+=v[6].filter(q=>q[q.length-1]).length)\n            if(tt>1){\n              q[q.length-1]=false\n            }\n          })\n        })\n      }\n      if(tools.selectMode==\'shape\'){\n        shps.map((v,i)=>{\n          v[v.length-1]=false\n          v[6].map(q=>{\n            if(q[q.length-1]) v[v.length-1] = true\n          })\n        })\n      }\n    }\n    \n    document.body.onfocus=()=>{\n      keys[18]=false\n    }\n    \n    run=keys[16]?3:1\n    keys.map((v,i)=>{\n      if(v){\n        switch(i){\n          case 90:\n            Rlv-=rv\n          break\n          case 82:\n            tools.transformMode = \'rotate\'\n          break\n          case 77:\n            tools.transformMode = \'move\'\n          break\n          case 76:\n            tools.transformMode = \'scale\'\n          break\n          case 88:\n            Rlv+=rv\n          break\n          case 67:\n            oXv=oYv=oZv=Rlv=Ptv=Ywv=0\n            Rl=oRl,Pt=oPt,Yw=oYw\n            oX=ooX,oY=ooY,oZ=ooZ\n          break\n          case 37:\n            if(keys[18]){\n              oXv+=S(p=-Yw+Math.PI/2)*mv*run\n              oZv+=C(p)*mv*run\n            }else{\n              if(0&&keys[16]){\n                Rlv-=rv\n              }else{\n                Ywv+=rv\n              }\n            }\n          break\n          case 38:\n            if(keys[17]){\n              oYv+=mv*run\n            } else {\n              Ptv+=rv\n            }\n          break\n          case 39:\n            if(keys[18]){\n              oXv-=S(p=-Yw+Math.PI/2)*mv*run\n              oZv-=C(p)*mv*run\n            }else{\n              if(0&&keys[16]){\n                Rlv+=rv\n              }else{\n                Ywv-=rv\n              }\n            }\n          break\n          case 40:\n            if(keys[17]){\n              oYv-=mv*run\n            } else {\n              Ptv-=rv\n            }\n          break\n          case 87: //w\n            if(0&&keys[16]){\n              oYv+=mv*run\n            } else {\n              oXv-=S(p=-Yw)*C(q=Pt)*mv*run\n              if(tools.fly.enabled) oYv+=S(q)*mv*run\n              oZv-=C(p)*C(q)*mv*run\n            }\n          break\n          case 65: //a\n            if(keys[17]){\n              selectAll()\n            } else {\n              oXv+=S(p=-Yw+Math.PI/2)*mv*run\n              oZv+=C(p)*mv*run\n            }\n          break\n          case 83: //s\n            if(0&&keys[16]){\n              oYv-=mv*run\n            } else {\n              oXv+=S(p=-Yw)*C(q=Pt)*mv*run\n              if(tools.fly.enabled) oYv-=S(q)*mv*run\n              oZv+=C(p)*C(q)*mv*run\n            }\n          break\n          case 68: //d\n            if(keys[17]){\n              if(!shiftCloneComplete){\n                selectedShapes().map(v=>{\n                  duplicateShape(v)\n                })\n                shiftCloneComplete=true\n              }\n            }else{\n              oXv-=S(p=-Yw+Math.PI/2)*mv*run\n              oZv-=C(p)*mv*run\n            }\n          break\n        }\n      }\n    })\n            \n    Rl+=Rlv/=1.3\n    Pt+=Ptv/=1.3\n    Yw+=Ywv/=1.3\n    //Pt=Math.min(Math.PI/2, Math.max(-Math.PI/2,Pt))\n\n    oX+=oXv/=1.1\n    oY+=oYv/=1.1\n    oZ+=oZv/=1.1\n    \n    x.clearRect(0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#111c\'\n    x.fillRect(0,0,c.width,c.height)\n    if(tools.showGlobalSphere){\n      shps.map((v,i)=>{\n        if(i==shps.length-1){\n          X=v[0]-oX\n          Y=v[1]-oY\n          Z=v[2]-oZ\n          if(H(-X-oX,-Y-oY,-Z-77)<500){\n            DrawSolid(v[6], X, Y, Z, v[3], v[4], v[5], \'#ccffee44\', \'#000c\', 1, 1/(1+H(-oX-X,-oY-Y,-oZ-Z)**9/59999999999999999999999), false, 1)\n          }\n        }\n      })\n    }\n    \n    if(tools.showFloor){\n      B.map((v,i)=>{\n        if(i>3){\n          if(-oX-v[0]<-sp*bcl/2)v[0]-=sp*bcl\n          if(-oX-v[0]>sp*bcl/2)v[0]+=sp*bcl\n          if(-oZ-v[2]<-sp*brw/2)v[2]-=sp*brw\n          if(-oZ-v[2]>sp*brw/2)v[2]+=sp*brw\n          if(!(i%4))x.beginPath()\n          X=(v[0]+v[3])\n          Y=v[1]+v[4]\n          Z=(v[2]+v[5])\n          R(Rl,Pt,Yw,1)\n          if(Z>0)x.lineTo(...Q())\n          if(i%4==3){\n            x.closePath()\n            x.lineWidth=Math.min(200, 50/(Z**1.5))\n            //x.strokeStyle=\'#fff1\'\n            //x.stroke()\n            x.lineWidth/=6\n            x.lineWidth=Math.max(1,x.lineWidth)\n            x.globalAlpha=(1/(1+H(-oX-v[0],-oZ-v[2])**10/1e15))*Math.min(1, Math.max(.03, H(-oX-v[0],-oZ-v[2])**2/50))\n            x.strokeStyle=\'#fff4\'\n            x.stroke()\n            x.fillStyle=((i/4|0)%bcl+i/4/bcl|0)%2?\'#111c\':\'#222c\'\n            x.fill()\n          }\n        }\n      })\n      highlightColor=\'#0f43\'\n    }\n    //highlightColor=`hsla(${t*1000},99%,50%,.2)`\n    \n\n\n    // model data section\n    interfaceBuffer_ = Array(shps.length).fill().map((v,i)=>{\n      return [[],[],0,i]\n    })\n\n    editable = !(tools.gyro.hover || tools.move.hover || tools.info.hover || tools.menu.hover)\n    \n    shps=[...shps.filter((v,i)=>i<shps.length-1).sort((a,b)=>{\n      X=-oX-a[0]\n      Y=-oY-a[1]\n      Z=-oZ-a[2]\n      R(Rl,Pt,Yw,1)\n      Z1=Z\n      X=-oX-b[0]\n      Y=-oY-b[1]\n      Z=-oZ-b[2]\n      R(Rl,Pt,Yw,1)\n      Z2=Z\n      return Z1-Z2\n    }), shps[shps.length-1]]\n    \n    shps.map((v,i)=>{\n      if(i<shps.length-1){// && interfaceBuffer[i].length>2){\n        let n = shps[interfaceBuffer[i][3]]\n        if(typeof n !== \'undefined\'){\n          X=n[0]\n          Y=n[1]\n          Z=n[2]\n          if(H(-X-oX,-Y-oY,-Z-oZ)<500){\n            interfaceBufferQueue = []\n            DrawSolid(n[6], X, Y, Z, n[3], n[4], n[5], \'#fff2\', n[8], n[10], 1/(1+H(-oX-X,-oY-Y,-oZ-Z)**9/59999999999999999999999), editable, n[9])\n            X=n[0]\n            Y=n[1]\n            Z=n[2]\n            R(Rl,Pt,Yw,1)\n            if(editable) interfaceBuffer_=[...interfaceBuffer_, [n[6], [...interfaceBufferQueue, Z, interfaceBuffer[i][3]]]]\n          }\n        //} else {\n        //    if(interfaceBuffer_=[...interfaceBuffer_, [v[6], [0, Z, i]]]\n        }\n      }\n    })\n    interfaceBuffer = interfaceBuffer_\n\n    l=selectedShapes()\n    if(l.length){\n      tlj=x.lineJoin\n      axisLength=4\n      x.lineJoin=x.lineCap=\'round\'\n      cx=cy=cz=tx=ty=tz=rl=pt=yw=ct=0\n      l.map((v,i)=>{\n        switch(tools.selectMode){\n          case \'face\':\n          case \'vertex\':\n            //if(v[6].length){\n              v[6].map(q=>{\n                if(q.length){\n                  q.map(n=>{\n                    if(n.length && n[3]){\n                      tx+=n[0]\n                      ty+=n[1]\n                      tz+=n[2]\n                      ct++\n                    }\n                  })\n                }\n              })\n            //}\n          break\n          case \'shape\':\n            ct++\n          break\n        }\n        cx+=v[0]\n        cy+=v[1]\n        cz+=v[2]\n        \n      })\n      if(l.length>1 && mbuttons[0]){\n        gGyro.map(v=>{\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R(Rl,Pt,Yw,0)\n            if(keys[16]){\n              R2(-d1/20,-d2/20,0,0)\n            }else{\n              R2(0,-d2/20,-d1/20,0)\n            }\n            R(-Rl,-Pt,-Yw,0)\n            q[0]=X\n            q[1]=Y\n            q[2]=Z\n          })\n        })\n      }\n      tx/=ct\n      ty/=ct\n      tz/=ct\n      X=tx+=cx/l.length\n      Y=ty+=cy/l.length\n      Z=tz+=cz/l.length\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        switch(tools.transformMode){\n          case \'move\':\n            x.beginPath()\n            X=tx\n            Y=ty\n            Z=tz\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=tx+axisLength\n            Y=ty\n            Z=tz\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            x.strokeStyle=\'#f003\'\n            x.lineWidth=300/Z\n            x.stroke()\n            x.lineWidth/=6\n            x.strokeStyle=\'#fff8\'\n            x.stroke()\n            x.beginPath()\n            X=tx\n            Y=ty\n            Z=tz\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=tx\n            Y=ty-axisLength\n            Z=tz\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            x.strokeStyle=\'#0f03\'\n            x.lineWidth=300/Z\n            x.stroke()\n            x.lineWidth/=6\n            x.strokeStyle=\'#fff8\'\n            x.stroke()\n            x.beginPath()\n            X=tx\n            Y=ty\n            Z=tz\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=tx\n            Y=ty\n            Z=tz-axisLength\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            x.strokeStyle=\'#04f3\'\n            x.lineWidth=300/Z\n            x.stroke()\n            x.lineWidth/=6\n            x.strokeStyle=\'#fff8\'\n            x.stroke()\n          break\n          case \'rotate\':\n            if(l.length==1){\n              if(typeof l[0][11] !== \'undefined\'){\n                l[0][11].map((v,i)=>{\n                  x.beginPath()\n                  v.map(q=>{\n                    X=q[0]+tx\n                    Y=q[1]+ty\n                    Z=q[2]+tz\n                    R(Rl,Pt,Yw,1)\n                    if(Z>0) x.lineTo(...Q())\n                  })\n                  x.closePath()\n                  switch(i){\n                    case 0: x.strokeStyle=\'#0f03\'; break\n                    case 1: x.strokeStyle=\'#04f3\'; break\n                    case 2: x.strokeStyle=\'#f003\'; break\n                  }\n                  x.lineWidth=300/Z\n                  x.stroke()\n                  x.lineWidth/=6\n                  x.strokeStyle=\'#fff8\'\n                  x.stroke()\n                })\n              }\n            } else {\n              gGyro.map((v,i)=>{\n                x.beginPath()\n                v.map(q=>{\n                  X=q[0]+tx\n                  Y=q[1]+ty\n                  Z=q[2]+tz\n                  R(Rl,Pt,Yw,1)\n                  if(Z>0) x.lineTo(...Q())\n                })\n                x.closePath()\n                switch(i){\n                  case 0: x.strokeStyle=\'#0f03\'; break\n                  case 1: x.strokeStyle=\'#04f3\'; break\n                  case 2: x.strokeStyle=\'#f003\'; break\n                }\n                x.lineWidth=300/Z\n                x.stroke()\n                x.lineWidth/=6\n                x.strokeStyle=\'#fff8\'\n                x.stroke()\n              })\n            }\n          break\n          case \'scale\':\n          break\n        }\n        //x.arc(...Q(),200/Z,0,7)\n        //x.fillStyle=\'#0f8\'\n        //x.fill()\n      }\n      x.lineJoin=x.lineCap=tlj\n    }\n    \n    if(!allSelected && !draggingShape && tools.selectMode==\'shape\'){\n      shps.map(v=>{\n        v[6].map(q=>{\n          q[q.length-1]=false\n        })\n      })\n    }\n    \n    if(!draggingShape || (!mbuttons[0] && !cct)){\n      checkHover()\n    }\n    if(tools.menu.visible){\n      if(mbuttons[2]){\n        tools.menu.visible = !tools.menu.visible\n        tools.menu.toggled = true\n      } else {\n        drawMenu()\n        //x2.drawImage(c,0,0,canvas2.width,canvas2.height)\n        //requestAnimationFrame(Draw)\n        //return\n      }\n    }\n    \n    if(tools.menu.visible){\n      //if(menuHover()\n    }\n\n    if(tools.show){\n      s=100\n      x.globalAlpha=tools.move.hover?1:.5\n      x.drawImage(moveIcon, tools.move.x-s/2,tools.move.y-s/2,s,s)\n      x.globalAlpha=1\n      \n      x.lineJoin=x.lineCap=\'round\'\n      Gyro.map((v,i)=>{\n        x.beginPath()\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(Rl,Pt,Yw)\n          Z+=1\n          l=Q()\n          x.lineTo(l[0]+tools.gyro.x,-c.height/2+l[1]+tools.gyro.y)\n        })\n        x.closePath()\n        x.lineWidth=10/(Z**1.5)\n        x.strokeStyle=`hsla(${360/3*i},99%,50%,${tools.gyro.hover?.4:.2})`\n        x.stroke()\n        x.lineWidth/=5\n        x.strokeStyle=`hsla(${360/3*i},99%,50%,${tools.gyro.hover?.8:.4})`\n        x.stroke()\n      })\n      \n      \n      x.strokeStyle=\'#fff3\'\n      x.fillStyle=\'#0006\'\n      x.strokeRect(...(a=[tools.info.x-10, tools.info.y-10, 250, tools.info.visible?940:46]))\n      x.fillRect(...a)\n      x.lineJoin=x.lineCap=\'butt\'\n      x.font=tools.info.fontSize+\'px courier\'\n      x.fillStyle=\'#8fc\'\n      \n      x.globalAlpha=.6\n      x.drawImage(tools.info.visible?hideIcon:showIcon,...(tools.info.toggleButton=[a[0]+a[2]-45,a[1]+3,40,40]))\n      x.globalAlpha=1\n      \n      if(!tools.info.visible){\n        printLn(`INFO -`, 0, 0, \'info\')\n      } else {\n        let rw=0\n        printLn(`CAMERA -`, rw, 0, \'info\')\n        printLn(`POSITION`, rw+=2, 1, \'info\')\n        printLn(`X = ${Math.round(oX*1e3)/1e3}`, ++rw, 2, \'info\')\n        printLn(`Y = ${Math.round(oY*1e3)/1e3}`, ++rw, 2, \'info\')\n        printLn(`Z = ${Math.round(oZ*1e3)/1e3}`, ++rw, 2, \'info\')\n        printLn(`ORIENTATION`, rw+=2, 1, \'info\')\n        printLn(`ROLL  = ${Math.round(Rl*1e3)/1e3}`, ++rw, 2, \'info\')\n        printLn(`PITCH = ${Math.round(Pt*1e3)/1e3}`, ++rw, 2, \'info\')\n        printLn(`YAW   = ${Math.round(Yw*1e3)/1e3}`, ++rw, 2, \'info\')\n\n        printLn(`MODES -`, rw+=2, 0, \'info\')\n        printLn(`TOOLS [T] = ${tools.show}`, ++rw, 1, \'info\')\n        printLn(`Y-LOCK[F] = ${tools.fly.enabled}`, ++rw, 1, \'info\')\n        printLn(`VWFNDR[V] = ${tools.viewfinder.visible}`, ++rw, 1, \'info\')\n        printLn(`SELECT MODE -`, rw+=2, 0, \'info\')\n        printLn(`${tools.selectMode}`, ++rw, 1, \'info\')\n      }\n    }\n    if(tools.viewfinder.visible){\n      x.globalAlpha=tools.viewfinder.alpha\n      x.drawImage(tools.viewfinder.img,0,0,c.width,c.height)\n      x.globalAlpha=1\n    }\n    \n    if(tools.marq.x!=-1){\n      x.strokeStyle=\'#4f84\'\n      x.lineWidth=4\n      x.strokeRect(tools.marq.x,tools.marq.y,tools.marq.w,tools.marq.h)\n      x.fillStyle=\'#0f41\'\n      x.fillRect(tools.marq.x,tools.marq.y,tools.marq.w,tools.marq.h)\n    }\n\n    if(mbuttons[2]){\n      drawMenu()\n      mbuttons[2]=false\n    }\n\n    if(showCursorDot){\n      s=15\n      x.fillStyle=\'#4f8a\'\n      x.fillRect(mx-s/2,my-s/2,s,s)\n    }\n    \n    freshClick=false\n    t+=1/60\n    x2.clearRect(0,0,w=canvas2.width|=0,w)\n    x2.drawImage(c,0,0,canvas2.width,canvas2.height)\n    requestAnimationFrame(Draw)\n}\n\nDraw()', 'body, html{\n  margin: 0;\n  width: 100%;\n  height: 100vh;\n  overflow: hidden;\n  background: #000;\n}\ncanvas{\n  border: 2px solid #486;\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  background: url(/1HZmm6.png);\n  background-color: #222;\n  background-position: center center;\n  background-size: 100% 100%;\n  transform: translate(-50%, -50%);\n}\n.downloadLink{\n  text-decoration: none;\n  font-family: courier;\n  font-size: 24px;\n  color: #044;\n  text-shadow: 1px 1px 1px #000;\n  margin: 50px;\n  padding: 10px;\n  background: #0fa;\n  display: inline-block;\n  border-radius: 10px;\n}\n.newDiv{\n  text-align: center;\n}\n.imgThumb{\n  width: calc(100% - 50px);\n  margin:25px;\n}\n#button{\n  position:absolute;\n  left:50%;\n  top:50%;\n  transform: translate(-50%,-50%);\n  font-size: 24px;\n}\n#hotkeys{\n  font-family: courier;\n  color: #fff;\n  font-size: 16px;\n  text-shadow: 1px 1px 1px #000;\n  background: #206;\n  cursor: pointer;\n  border: none;\n  border-radius: 5px;\n  top: 5px;\n  left: 5px;\n  position: fixed;\n  z-index: 20;\n}', '<button id=\"hotkeys\" onclick=\"showHotkeys()\">hotkeys</button>\n<button onclick=\"Draw()\" id=\"button\">Draw</button>\n<div style=\"font-family: alice;position:absolute; z-index:-100\">a</div>\n<canvas id=\"c\"></canvas>\n', 'autodraw', 145, 'whitehot robot', '2022-08-13 23:17:19', '', 88, '', 0, 0);
