(600396, '', 'function project3D(x,y,z,vars){\n\n	var p,d;\n	x-=vars.camX;\n	y-=vars.camY;\n	z-=vars.camZ;\n	p=Math.atan2(x,z);\n	d=Math.sqrt(x*x+z*z);\n	x=Math.sin(p-vars.yaw)*d;\n	z=Math.cos(p-vars.yaw)*d;\n	p=Math.atan2(y,z);\n	d=Math.sqrt(y*y+z*z);\n	y=Math.sin(p-vars.pitch)*d;\n	z=Math.cos(p-vars.pitch)*d;\n	var x1=-9;\n	var y1=1;\n	var x2=9;\n	var y2=1;\n	var x3=0;\n	var y3=0;\n	var x4=x;\n	var y4=z;\n	var uc=(y4-y3)*(x2-x1)-(x4-x3)*(y2-y1);\n	var ua=((x4-x3)*(y1-y3)-(y4-y3)*(x1-x3))/uc;\n	var ub=((x2-x1)*(y1-y3)-(y2-y1)*(x1-x3))/uc;\n	if(ua>0&&ua<1&&ub>0&&ub<1){\n		return {\n			x:vars.cx+(x1+ua*(x2-x1))*vars.scale,\n			y:vars.cy+y/z*vars.scale,\n			d:Math.sqrt(x*x+y*y+z*z)\n		};\n	}else{\n		return { d:-1 };\n	}\n}\n\nfunction reverseRasterize(x, y, depth, vars){\n\n	var vert={x:0,y:0,z:0},d,p;\n	vert.x=vars.camX+(-vars.cx+x)/vars.scale*depth;\n	vert.y=vars.camY+(-vars.cy+y)/vars.scale*depth;\n	vert.z=vars.camZ+depth;    \n	d=Math.sqrt((vert.y-vars.camY)*(vert.y-vars.camY)+(vert.z-vars.camZ)*(vert.z-vars.camZ));\n	p=Math.atan2(vert.y-vars.camY,vert.z-vars.camZ);\n	vert.y=vars.camY+Math.sin(p+vars.pitch)*d;\n	vert.z=vars.camZ+Math.cos(p+vars.pitch)*d;\n	d=Math.sqrt((vert.x-vars.camX)*(vert.x-vars.camX)+(vert.z-vars.camZ)*(vert.z-vars.camZ));\n	p=Math.atan2(vert.x-vars.camX,vert.z-vars.camZ);\n	vert.x=vars.camX+Math.sin(p+vars.yaw)*d;\n	vert.z=vars.camZ+Math.cos(p+vars.yaw)*d;\n\n	d=Math.sqrt((vert.x-vars.camX)*(vert.x-vars.camX)+\n				(vert.y-vars.camY)*(vert.y-vars.camY)+\n				(vert.z-vars.camZ)*(vert.z-vars.camZ));\n	var x = vert.x-vars.camX;\n	var y = vert.y-vars.camY;\n	var z = vert.z-vars.camZ;\n	var t=d/depth;\n	vert.x=vars.camX+x/t;\n	vert.y=vars.camY+y/t;\n	vert.z=vars.camZ+z/t;\n	return vert;\n}\n\n\nfunction elevation(x,y,z){\n\n	var dist = Math.sqrt(x*x+y*y+z*z);\n	if(dist && z/dist>=-1 && z/dist <=1) return Math.acos(z / dist);\n	return 0.00000001;\n}\n\n\nfunction elevation(x,y,z){\n\n	var dist = Math.sqrt(x*x+y*y+z*z);\n	if(dist && z/dist>=-1 && z/dist <=1) return Math.acos(z / dist);\n	return 0.00000001;\n}\n\n\nfunction process(vars){\n	var d,x1,y1,z1,x2,y2,z2,t,p1,p2;\n	for(var i=0;i<vars.shapes.length;++i){\n		x1=vars.shapes[i].x;\n		y1=vars.shapes[i].y;\n		z1=vars.shapes[i].z;\n		vars.shapes[i].x+=vars.shapes[i].vx;\n		vars.shapes[i].y+=vars.shapes[i].vy;\n		vars.shapes[i].z+=vars.shapes[i].vz;\n		vars.shapes[i].vx-=vars.shapes[i].x/600;\n		vars.shapes[i].vy-=vars.shapes[i].y/600;\n		vars.shapes[i].vz-=vars.shapes[i].z/600;\n		vars.shapes[i].vx=vars.shapes[i].vx/1.01+(-.05+Math.random()/10);\n		vars.shapes[i].vy=vars.shapes[i].vy/1.01+(-.05+Math.random()/10);\n		vars.shapes[i].vz=vars.shapes[i].vz/1.01+(-.05+Math.random()/10);\n		for(var j=0;j<vars.shapes.length;++j){\n			if(i!=j){\n				x2=vars.shapes[j].x;\n				y2=vars.shapes[j].y;\n				z2=vars.shapes[j].z;\n				d=Math.sqrt((x2-x1)*(x2-x1)+(y2-y1)*(y2-y1)+(z2-z1)*(z2-z1));\n				t=vars.shapes[i].radius+vars.shapes[j].radius;\n				vars.shapes[i].vx+=(vars.shapes[j].x-vars.shapes[i].x)/vars.shapes[i].radius*vars.shapes[j].radius/800;\n				vars.shapes[i].vy+=(vars.shapes[j].y-vars.shapes[i].y)/vars.shapes[i].radius*vars.shapes[j].radius/800;\n				vars.shapes[i].vz+=(vars.shapes[j].z-vars.shapes[i].z)/vars.shapes[i].radius*vars.shapes[j].radius/800;\n				if(d<t){\n					p1=Math.atan2(x2-x1,z2-z1);\n					p2=elevation(x2-x1,z2-z1,y2-y1);\n					ox=vars.shapes[i].x;\n					oy=vars.shapes[i].y;\n					oz=vars.shapes[i].z;\n					vars.shapes[j].x+=Math.sin(p1)*Math.sin(p2)*(t-d);\n					vars.shapes[j].y+=Math.cos(p1)*Math.sin(p2)*(t-d);\n					vars.shapes[j].z+=Math.cos(p2)*(t-d);\n					vars.shapes[j].vx-=(vars.shapes[i].x-ox)/10;\n					vars.shapes[j].vy-=(vars.shapes[i].y-oy)/10;\n					vars.shapes[j].vz-=(vars.shapes[i].z-oz)/10;\n				}\n			}\n		}\n	}\n}\n\n\nfunction rayTrace(vars){\n	\n	var imgData=vars.ctx.createImageData(vars.canvas.width, vars.canvas.height);\n	var x,y,z,x1,y1,z1,x2,y2,z2,x3,y3,z3,x4,y4,z4,a,b,c,u,m,d,r,p1,p2,rayLength;\n	for(var i=0;i<vars.canva