(600402, '', '// external js: packery.pkgd.js\n\n$(\'.grid\').packery({\n  itemSelector: \'.grid-item\',\n  percentPosition: true\n});\n', '* {\n  box-sizing: border-box;\n}\n\nhtml {\n  overflow-y: scroll;\n}\n\nbody {\n  font-family: sans-serif;\n}\n\n.grid:after {\n  content: \"\";\n  display: block;\n  clear: both;\n}\n\n.grid-item {\n  float: left;\n  width: 20%;\n  height: 100px;\n  background: #fff;\n  border: 1px solid #ccc;\n}\n\n.grid-item--width2 {\n  width: 40%;\n}\n\n.grid-item--height2 {\n  height: 200px;\n}\n\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n}\n\nbody {\n  width: 80%;\n  margin: 0 auto;\n  background: white;\n  color: black;\n}\n\nheader {\n  background: #000099;\n  height: 200px;\n}\n\nh2 {\n  font-weight: normal;\n  font-size: 20px !important;\n  padding: 10px;\n  display: flex;\n}\n\nheader img {\n  width: 35%;\n  position: relative;\n  top: -25px;\n  left: -10px;\n}\n\nh2 {\n  background: black;\n  color: white;\n}\n\n.swiper-container {\n  overflow: hidden;\n  //overflow: clip;\n}\n\n.swiper-slide {\n  overflow: hidden;\n  text-align: center;\n  font-size: 18px;\n  display: -webkit-box;\n  display: -ms-flexbox;\n  display: -webkit-flex;\n  display: flex;\n  -webkit-box-pack: center;\n  -ms-flex-pack: center;\n  -webkit-justify-content: center;\n  justify-content: center;\n  -webkit-box-align: center;\n  -ms-flex-align: center;\n  -webkit-align-items: center;\n  align-items: center;\n}\n\n.iframely-embed {\n  width: 100%;\n  height: 100%;\n  overflow: auto;\n  padding-left: 8%;\n  padding-right: 8%;\n}\n\n.iframely-responsive {\n  top: 22% !important;\n  left: -10% !important;\n  width: 120% !important;\n  height: 50% !important;\n  position: relative;\n  padding-bottom: 50%;\n  box-sizing: border-box;\n}\n\nh1,\nh2,\nh3,\nh4 {\n  letter-spacing: -0.2px;\n}\n\nh1 {\n  font-size: 55px;\n}\n\nh2 {\n  font-size: 33px;\n}\n\nh3 {\n  position: absolute;\n  color: white;\n}\n\nh3.artist {\n  top: 20%;\n  font-size: 74px;\n}\n\nh3.track {\n  bottom: 20%;\n  font-size: 66px;\n}\n\nh3.artist,\nh3.track {\n  position: absolute;\n  z-index: 1;\n}\n', '<head>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<script src=\"//cdnjs.cloudflare.com/ajax/libs/jquery/2.1.3/jquery.min.js\"></script>\n<script src=\"https://unpkg.com/packery@2/dist/packery.pkgd.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/Swiper/8.3.2/swiper-bundle.min.js\"></script>\n  <script async charset=\"utf-8\" src=\"https://cdn.iframe.ly/embed.js?api_key=78d408e0b569d36bb547fe\"></script>\n<link rel=\"stylesheet\" type=\"text/css\" href=\"https://unpkg.com/swiper/swiper-bundle.min.css\">\n</head>\n\n<body>\n  <header>\n    <img src=\"https://i.imgur.com/wZwIp7a.png\">\n  </header>\n\n  <h2>Multiple videos, use swipe to navigate</h2>\n\n  <div class=\"grid\">\n    <div class=\"grid-item grid-item--width2\">\n      <div class=\"swiper-container swiper-container-h\">\n        <div class=\"swiper-wrapper\">\n          <div class=\"swiper-slide\">\n            <h3 class=\"artist\">Kemt</h3>\n            <a href=\"https://www.youtube.com/watch?v=8SQZtBRdSbE\" data-iframely-url class=\"iframely-anchor\">https://www.youtube.com/watch?v=8SQZtBRdSbE</a>\n            <h3 class=\"track\">Next To You</h3>\n          </div>\n          <div class=\"swiper-slide\">\n            <h3 class=\"artist\">Röyksopp</h3>\n            <a href=\"https://youtube.com/watch?v=QLnFpjHArwQ\" data-iframely-url class=\"iframely-anchor\">https://youtube.com/watch?v=QLnFpjHArwQ</a>\n            <h3 class=\"track\">In Space</h3>\n          </div>\n          <div class=\"swiper-slide\">\n            <h3 class=\"artist\">Daniel Klauser</h3>\n            <a href=\"https://youtube.com/watch?v=H6jNYY4GRr0\" data-iframely-url class=\"iframely-anchor\">https://youtube.com/watch?v=H6jNYY4GRr0</a>\n            <h3 class=\"track\">Always I\'m Back Here</h3>\n          </div>\n          <div class=\"swiper-slide\">\n            <h3 class=\"artist\">Röyksopp</h3>\n            <a href=\"https://youtube.com/watch?v=8Gy_zq_YuQQ\" data-iframely-url class=\"iframely-anchor\">https://youtube.com/watch?v=8Gy_zq_YuQQ</a>\n            <h3 class=\"track\">Remind Me</h3>\n          </div>\n          <div class=\"swiper-slide\">\n            <h3 class=\"artist\">Afta-1</h3>\n            <a href=\"https://youtube.com/watch?v=fzBuXumxDX4\" data-iframely-url class=\"iframely-anchor\">https://youtube.com/watch?v=fzBuXumxDX4</a>\n            <h3 class=\"track\">4nia (92)</h3>\n          </div>\n          <div class=\"swiper-slide\">\n            <h3 class=\"artist\">Guizz</h3>\n            <a href=\"https://www.youtube.com/watch?v=9FfLoFaryxw\" data-iframely-url class=\"iframely-anchor\">https://www.youtube.com/watch?v=9FfLoFaryxw</a>\n            <h3 class=\"track\">Introspección</h3>\n          </div>\n          <div class=\"swiper-slide\">\n            <h3 class=\"artist\">Afta-1</h3>\n            <a href=\"https://youtube.com/watch?v=ADvXTRu9yJM\" data-iframely-url class=\"iframely-anchor\">https://youtube.com/watch?v=ADvXTRu9yJM</a>\n            <h3 class=\"track\">Yellow</h3>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"grid-item\">\n    <blockquote class=\"tiktok-embed\" cite=\"https://www.tiktok.com/@martinelunde/video/7125760529796304133\" data-video-id=\"7125760529796304133\" style=\"max-width: 605px;min-width: 325px;\">\n      <section> <a target=\"_blank\" title=\"@martinelunde\" href=\"https://www.tiktok.com/@martinelunde\">@martinelunde</a>\n        <p>⚓️⚓️</p> <a target=\"_blank\" title=\"♬ Shootout - Izzamuzzic &#38; Julien Marchal\" href=\"https://www.tiktok.com/music/Shootout-7100626164536494849\">♬ Shootout - Izzamuzzic &#38; Julien Marchal</a>\n      </section>\n    </blockquote>\n    <script async src=\"https://www.tiktok.com/embed.js\"></script>\n  </div>\n  <div class=\"grid-item\">\n\n    <div class=\"grid-item\">\n      Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.\n    </div>\n  </div>\n\n  <div class=\"grid-item grid-item--width2\"><iframe width=\"100%\" height=\"300\" scrolling=\"no\" frameborder=\"no\" allow=\"autoplay\" src=\"https://w.soundcloud.com/player/?url=https%3A//api.soundcloud.com/tracks/43665505&color=%23ff5500&auto_play=false&hide_related=false&show_comments=true&show_user=true&show_reposts=false&show_teaser=true&visual=true\"></iframe>\n    <div style=\"font-size: 10px; color: #cccccc;line-break: anywhere;word-break: normal;overflow: hidden;white-space: nowrap;text-overflow: ellipsis; font-family: Interstate,Lucida Grande,Lucida Sans Unicode,Lucida Sans,Garuda,Verdana,Tahoma,sans-serif;font-weight: 100;\"><a href=\"https://soundcloud.com/haukeland\" title=\"haukeland\" target=\"_blank\" style=\"color: #cccccc; text-decoration: none;\">haukeland</a> · <a href=\"https://soundcloud.com/haukeland/afta1-various\" title=\"AFTA-1 - Various\" target=\"_blank\" style=\"color: #cccccc; text-decoration: none;\">AFTA-1 - Various</a></div>\n  </div>\n  </div>\n  <script>\n    window.onload = function() {\n      var swiperH = new Swiper(\".swiper-container-h\", {\n        spaceBetween: 50,\n        pagination: {\n          el: \".swiper-pagination-h\",\n          clickable: true\n        }\n      });\n      var swiperV = new Swiper(\".swiper-container-v\", {\n        direction: \"vertical\",\n        spaceBetween: 50,\n        pagination: {\n          el: \".swiper-pagination-v\",\n          clickable: true\n        }\n      });\n      var linkElement = document.querySelector(\"a.iframely-anchor\");\n      iframely.load(linkElement);\n    }\n  </script>\n</body>', 'Packery - fluid sizing', 145, 'whitehot robot', '2022-08-18 23:44:38', '', 165, '', 0, 0),
(600403, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/gfI3L.gif);\n  background-size: 100% 100%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'refraction (gif)', 145, 'whitehot robot', '2022-08-21 18:24:53', '[600401,600399,600391,600390,600385,600380,600367,600366,600364,600363,600360,600359,600358,600357,600356,600355,600354,600353,600288,600253,600252,600251,600248,600247]', 77, '', 0, 0),
