(600412, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/14pFzW.gif);\n  background-size: 100% 100%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'brain blast spectrum (gif)', 145, 'whitehot robot', '2022-08-26 02:49:02', '[600403,600401,600399,600391,600390,600385,600380,600367,600366,600364,600363,600360,600359,600358,600357,600356,600355,600354,600353,600288,600253,600252,600251,600248,600247]', 67, '', 0, 0),
(600413, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R2=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          if(m)X+=oX,Y+=oY,Z+=oZ\n        }\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m)X+=oX,Y+=oY,Z+=oZ\n        }\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n\n        iBv=.1,iBlen=90,iBrad=.23,iBseglen=12\n        sd=10,trainv=24,trainpv=4,G=0\n        B=[[0,0,0,Rn()-.5,Rn()-.5,Rn()-.5]]\n        pushSeg=()=>{\n          l=B.length-1\n          X=B[l][0]\n          Y=B[l][1]\n          Z=B[l][2]\n          tx=vx=B[l][3]\n          ty=vy=B[l][4]/1.12\n          tz=vz=B[l][5]\n          d=Math.hypot(vx,vy,vz)\n          vx/=d\n          vy/=d\n          vz/=d\n          dx=Rn()-.5\n          dy=Rn()-.5\n          dz=Rn()-.5\n          d=Math.hypot(dx,dy,dz)\n          dx/=d\n          dy/=d\n          dz/=d\n          nx=(vx+dx*iBrad)/2\n          ny=(vy+dy*iBrad)/2\n          nz=(vz+dz*iBrad)/2\n          d=Math.hypot(nx,ny,nz)\n          vx=nx/d*iBv\n          vy=ny/d*iBv\n          vz=nz/d*iBv\n          B=[...B, [X+vx*iBseglen,Y+vy*iBseglen,Z+vz*iBseglen,vx,vy,vz]]\n          while(B.length>iBlen)G++,B.shift()\n        }\n        for(i=iBlen;i--;){\n          pushSeg()\n        }\n\n        Stroke=h=>{\n          x.strokeStyle=`hsla(${h*2-t*600},99%,${200+S(t)*175}%,.1)`\n          x.lineWidth=Math.min(500,700/((4+Z**1.05)**1))\n          x.stroke()\n          x.lineWidth/=5\n          x.strokeStyle=`hsla(0,99%,100%,${.35+S(t*3)*.2})`\n          x.stroke()\n        }\n\n        iSTG=4e3,iSTc=3e3\n        ST=Array(iSTc).fill().map(v=>{\n          X=(Rn()-.5)*iSTG\n          Y=(Rn()-.5)*iSTG\n          Z=(Rn()-.5)*iSTG\n          return [X,Y,Z]\n        })\n        Rl=0,Pt=0,Yw=0\n        tRl=0,tPt=0,tYw=0\n        oX=0,oY=0,oZ=0\n        mX=0,mY=0,mZ=0\n      }\n\n      x.fillStyle=\'#000f\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'butt\'\n\n\n      ST.map(v=>{\n        X=0\n        Y=0\n        Z=-20\n        R(Rl,0,-Yw,0)\n        X=v[0]+=X\n        Y=v[1]+=Y\n        Z=v[2]+=Z\n        if(X<-iSTG/2)v[0]=iSTG/2\n        if(X>iSTG/2)v[0]=-iSTG/2\n        if(Y<-iSTG/2)v[1]=iSTG/2\n        if(Y>iSTG/2)v[1]=-iSTG/2\n        if(Z<-iSTG/2)v[2]=iSTG/2\n        if(Z>iSTG/2)v[2]=-iSTG/2\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          x.globalAlpha=Math.min(1,(Z/900)**2)\n          s=Math.min(500, 8e4/(Z**1.1))\n          l=Q()\n          x.fillStyle=\'#fff2\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          x.fillStyle=\'#fff\'\n          s/=4\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        }\n      })\n      x.globalAlpha=1\n\n      if(!((t*60|0)%2)){\n        pushSeg()\n      }\n\n      while(Math.abs(tPt-Pt)>Math.PI){\n        if(tPt<Pt){\n          tPt+=Math.PI*2\n        } else {\n          tPt-=Math.PI*2          \n        }\n      }\n      while(Math.abs(tYw-Yw)>Math.PI){\n        if(tYw<Yw){\n          tYw+=Math.PI*2\n        } else {\n          tYw-=Math.PI*2          \n        }\n      }\n      Rl=0\n      Pt=Pt+(tPt-Pt)/trainv\n      Yw=Yw+(tYw-Yw)/trainv\n      mX=mX+(B[2][0]-mX)/trainpv\n      mY=mY+(B[2][1]-mY)/trainpv\n      mZ=mZ+(B[2][2]-mZ)/trainpv\n\n      a=[]\n      B.map((v,i)=>{\n        if(i){\n          //x.beginPath()\n          X1=X=B[i-1][0]-mX\n          Y1=Y=B[i-1][1]-mY\n          Z1=Z=B[i-1][2]-mZ\n          //R(Rl,Pt,Yw,1)\n          //if(Z>0)x.lineTo(...Q())\n          X2=X=v[0]-mX\n          Y2=Y=v[1]-mY\n          Z2=Z=v[2]-mZ\n          //R(Rl,Pt,Yw,1)\n          //if(Z>0)x.lineTo(...Q())\n          //Stroke()\n\n          x.beginPath()\n          p1=Math.atan2(X2-X1,Z2-Z1)\n          p2=Math.PI/2-Math.acos((Y2-Y1)/Math.hypot(X2-X1,Y2-Y1,Z2-Z1))\n          if(i==10) tPt=-p2,tYw=-p1\n          cull=0\n          ls=1.1+(6+S(-t+C(t/1.5)*10+Math.PI*2*1/B.length*(i+G))*5)**20/1e20\n          for(j=sd;j--;){\n            X=S(p=Math.PI*2/sd*j)*ls\n            Y=C(p)*ls\n            Z=0\n            R2(0,p2,p1,0)\n            ax=X+=X2\n            ay=Y+=Y2\n            az=Z+=Z2\n            R(Rl,Pt,Yw,1)\n            if(Z>0){\n              x.lineTo(...Q())\n            } else {\n              cull=1\n            }\n            a=[...a,[ax,ay,az,i]]\n          }\n          x.closePath()\n          if(!cull)Stroke(i)\n        }\n      })\n\n      a.map((q,j)=>{\n        if(j>=sd){\n          x.beginPath()\n          X=a[j-sd][0]\n          Y=a[j-sd][1]\n          Z=a[j-sd][2]\n          R(Rl,Pt,Yw,1)\n          if(Z>0)x.lineTo(...Q())\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(Rl,Pt,Yw,1)\n          if(Z>0)x.lineTo(...Q())\n          Stroke(q[3])\n        }\n      })\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'conduit', 145, 'whitehot robot', '2022-08-26 13:15:31', '[600253,600252,600251,600248,600247]', 97, '', 0, 0),
