(600423, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    R = function(r,g,b,a) {\n      a = a === undefined ? 1 : a;\n      return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n    };\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        Rn = Math.random\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n        }\n        for(CB=[],i=6;i--;)for(j=4;j--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*j+Math.PI/4),C(p),2**.5/2])[i%3]*(l=i<3?1:-1),a[(i+1)%3]*l,a[(i+2)%3]*l]]\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n        stroke=col=>{\n          x.closePath()\n          x.globalAlpha=.2\n          x.strokeStyle=col\n          x.lineWidth=Math.min(500,300/Z)\n          x.stroke()\n          x.globalAlpha=1\n          x.lineWidth/=5\n          x.stroke()\n        }\n\n        sf=1,mrsp=.06\n        cl=6*2/sf|0,rw=4*2/sf|0,sp=sf*(2**.5/2)*2\n        B=Array(cl*rw).fill().map((v,i)=>{\n          X=((i%cl)-cl/2+.5)*sp\n          Y=((i/cl|0)-rw/2+.5)*sp\n          Z=0\n          iconchoice = Rn()<.25?Rn()*8|0:-1\n          return [X,Y,Z, iconchoice]\n        })\n\n        let prefix = \'proxy.php/?url=https://srmcgann.github.io/assets/\'\n\n        imgdata = [\n          {name: \'180l\', src: prefix+\'MOkRb.png\'},\n          {name: \'180u\', src: prefix+\'dkl89.png\'},\n          {name: \'180r\', src: prefix+\'1mXHSr.png\'},\n          {name: \'180d\', src: prefix+\'1EwUpx.png\'},\n          {name: \'90l\',  src: prefix+\'gi1OO.png\'},\n          {name: \'90u\',  src: prefix+\'FbzGA.png\'},\n          {name: \'90r\',  src: prefix+\'1AeLis.png\'},\n          {name: \'90d\',  src: prefix+\'l30Y7.png\'}\n        ]\n\n        P=[]\n        loadP=()=>{\n          iPc=3e3,iPv=.1\n          P=Array(iPc).fill().map(v=>{\n            X=(Rn()-.5)*cl*sp\n            Y=(Rn()-.5)*rw*sp\n            Z=0\n            vx=(Rn()-.5)*iPv\n            vy=(Rn()-.5)*iPv\n            vz=0\n            return [X,Y,Z,vx,vy,vz,1,X,Y,Z,0]\n          })\n        }\n\n        go=false\n        icons = Array(imgdata.length).fill({loaded: false})\n        icons = Array(imgdata.length).fill().map((v,i)=>{\n          let imgobj = imgdata[i]\n          imgobj.img = new Image()\n          imgobj.loaded = false\n          setTimeout(()=>{\n            imgobj.img.onload=()=>{\n              imgobj.loaded = true\n              let allLoaded = true\n              icons.map(q=>{\n                if(!q.loaded) allLoaded = false\n              })\n              if(allLoaded) go = true, loadP()\n            }\n            imgobj.img.src = imgobj.src\n          },0)\n          return imgobj\n        })\n      }\n\n      x.fillStyle=\'#0004\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'butt\'\n      oX=oY=0, oZ=12\n      Rl=0,Pt=Math.PI/2-.2,Yw=0\n      Rl=0,Pt=C(t/2)/4,Yw=S(t/2)/4\n\n      P.map(v=>{\n        X=v[0]+=v[6]?v[3]:0\n        Y=v[1]+=v[6]?v[4]:0\n        Z=v[2]+=v[6]?v[5]:0\n        d=Math.hypot(v[7]-X,v[8]-Y,v[9]-Z)\n        if(d<.1){\n          v[10]++\n          if(v[10]>5){\n            v[0]=X=(Rn()-.5)*cl*sp\n            v[1]=Y=(Rn()-.5)*rw*sp\n            v[2]=Z=0\n            v[3]=vx=(Rn()-.5)*iPv\n            v[4]=vy=(Rn()-.5)*iPv\n            v[5]=vz=0\n            v[7]=X\n            v[8]=Y\n            v[9]=Z\n            v[10]=0\n          }\n        }else{\n          v[10]=0\n        }\n        v[6]=1\n        if(v[0]>sp*cl/2)v[0]=-sp*cl/2\n        if(v[0]<-sp*cl/2)v[0]=sp*cl/2\n        if(v[1]>sp*rw/2)v[1]=-sp*rw/2\n        if(v[1]<-sp*rw/2)v[1]=sp*rw/2\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          l=Q()\n          s=Math.min(500,400/Z)\n          x.fillStyle = \'#4f81\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          x.fillStyle = \'#fffc\'\n          s/=5\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        }\n        \n      })\n\n      B.map((v,i)=>{\n        tx=v[0]\n        ty=v[1]\n        tz=v[2]\n        if(v[3]!=-1){\n          P.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            if(\n              X>tx-sp/2&&X<tx+sp/2 &&\n              Y>ty-sp/2&&Y<ty+sp/2 &&\n              Z>tz-sp/2&&Z<tz+sp/2\n            ){\n              q[6]=0 \n              switch(icons[v[3]].name){\n                case \'180l\':\n                  cx = tx - sp/2\n                  cy = ty\n                break\n                case \'180u\':\n                  cx = tx\n                  cy = ty - sp/2\n                break\n                case \'180r\':\n                  cx = tx + sp/2\n                  cy = ty\n                break\n                case \'180d\':\n                  cx = tx\n                  cy = ty + sp/2\n                break\n                case \'90l\':\n                  cx = tx - sp/2\n                  cy = ty - sp/2\n                break\n                case \'90u\':\n                  cx = tx + sp/2\n                  cy = ty - sp/2\n                break\n                case \'90r\':\n                  cx = tx + sp/2\n                  cy = ty + sp/2\n                break\n                case \'90d\':\n                  cx = tx - sp/2\n                  cy = ty + sp/2\n                break\n              }\n              p = Math.atan2(cx-X,cy-Y)-mrsp\n              d = Math.hypot(cx-X,cy-Y)\n              q[0]=cx-S(p)*d\n              q[1]=cy-C(p)*d\n              p = Math.atan2(q[3],q[4])-mrsp\n              d = Math.hypot(q[3],q[4])\n              q[3]=S(p)*d\n              q[4]=C(p)*d\n            }\n          })\n          if(go){\n            X=tx\n            Y=ty\n            Z=tz\n            R(Rl,Pt,Yw,1)\n            s=1000/Z\n            l=Q()\n            x.globalAlpha=.75\n            x.drawImage(icons[v[3]].img,l[0]-s/2,l[1]-s/2,s,s)\n            x.globalAlpha=1\n          }\n        }\n        CB.map((q,j)=>{\n          if(j>=20){\n            if(!(j%4))x.beginPath()\n            X=q[0]+tx\n            Y=q[1]+ty\n            Z=q[2]*0+tz\n            R(Rl,Pt,Yw,1)\n            if(Z>0) x.lineTo(...Q())\n            if(j%4==3) stroke(\'#60f8\')\n          }\n        })\n      })\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'directional grid', 145, 'whitehot robot', '2022-10-04 20:25:13', '[600422,600373,600347,600253,600252,600251,600248,600247]', 76, '', 0, 0),
