(600426, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    R = function(r,g,b,a) {\n      a = a === undefined ? 1 : a;\n      return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n    };\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n        }\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n      }\n\n      //x.fillStyle=\'#0008\'\n      //x.fillRect(0,0,c.width,c.height)\n      oX=oY=0, oZ=5\n      Rl=0,Pt=0,Yw=0\n\n      P=t?P:[]\n      x.lineWidth=9\n      X=S(p=Math.PI/2*t*60**140.5)*(h=2e3)\n      Y=C(p)*h\n      P=[...P,[960+X,540+Y,-X/99,-Y/99,0]]\n      P.map(v=>{\n        v[4]||(v[0]+=v[2],v[1]+=v[3])\n        P.map(q=>{\n          if((l=Math.hypot(v[0]-q[0],v[1]-q[1]))<25&&l){\n            v[4]++\n            x.beginPath()\n            x.lineTo(...v)\n            x.lineTo(...q)\n            x.stroke()\n          }\n        })\n      })\n      P=P.filter(v=>v[4]<50)\n      \n\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'dweet (unfinished)', 145, 'whitehot robot', '2022-10-05 01:31:47', '[600422,600373,600347,600253,600252,600251,600248,600247]', 56, '', 0, 0);
