(600428, '', 'let x=(document.createElement(\'canvas\')).getContext(\'2d\')\n\n\nlet getTokens = str => {\n  let ar = str.split(\' \')\n  let a = [], l\n  ar.map(v=>{\n    if((l=v.split(\';\')).length>1){\n      l.map(q=>{\n        a=[...a, q]\n      })\n    }else{\n      a=[...a, v]\n    }\n  })\n  a=a.filter(v=>v)\n}\n\nlet getProps = (base, depth, lastprop) => {\n  if(lastprop == \'arguments\' || lastprop == \'caller\' || lastprop == \'callee\' || depth > 2 || (typeof base !== \'object\' && typeof base !== \'function\')|| !base || (lastprop == \'location\') || (typeof base == \'function\' ? base.name : base+\'\')==lastprop) return []\n  let ar = Object.getOwnPropertyNames(base).map(v=>{\n    //console.log(base, v)\n    if(v != \'7\' && v != \'this\' && v != \'_events\' && v != \'top\' && v != \'prototype\' && v != \'parent\' && v != \'arguments\' && v != \'caller\' && v != \'web3\' && v != \'callee\' && v != \'_metamask\' && (typeof base[v] == \'object\' || typeof base[v] == \'function\')){\n      v=[v, ...getProps(base[v], depth+1, v)]\n    }\n    return v\n  })\n  let bd = ar_ => {\n    if(typeof ar_ == \'string\'){\n      if((l=ar_.split(\',\')).length>1) bd(l)\n      if((/[a-zA-Z]/).test(ar_[0])) a=[...a, ar_]\n      return ar_\n    }\n    if(typeof ar_ !== \'object\') return\n    ar_.map(v=>{\n      if(typeof v == \'object\'){\n        v.map(q=>{\n          bd(q)\n        })\n      }else{\n        if((/[a-zA-Z]/).test(v[0])) a=[...a, v]\n      }\n    })\n  }\n  let a = []\n  bd(ar)\n  return a\n}\nlet dict  = [\n  \'var\',\n  \'style\',\n  \'forEach\',\n  \'else\',\n  \'map\',\n  \'switch\',\n  \'for\',\n  \'case\',\n  \'break\',\n  \'return\',\n  \'let\',\n  \'const\',\n  \'async\',\n  \'await\',\n  \'function\',\n]\ndict  = [...dict, ...getProps(window, 0, \'\')]\n\nrecurseObj = obj => {\n  for (var m in obj) {\n    if (typeof obj[m] == \"object\") {\n      recurseObj(m)\n    } else {\n      if((/[a-zA-Z]/).test(m[0])) dict = [...dict, m]\n    }\n  }\n}\n\nrecurseObj(document)\nrecurseObj(document.createElement(\'input\'))\nrecurseObj(document.createElement(\'button\'))\nrecurseObj(document.createElement(\'select\'))\nrecurseObj(document.createElement(\'option\'))\nrecurseObj(document.createElement(\'div\'))\nrecurseObj(document.createElement(\'canvas\'))\nrecurseObj(document.createElement(\'p\'))\nrecurseObj(document.createElement(\'ul\'))\nrecurseObj(document.createElement(\'ol\'))\nrecurseObj(document.createElement(\'span\'))\nrecurseObj(document.createElement(\'a\'))\nrecurseObj(document.createElement(\'video\'))\nrecurseObj(document.createElement(\'image\'))\nrecurseObj(document.createElement(\'textarea\'))\nrecurseObj(document.createElement(\'canvas\').getContext(\'2d\'))\n\ndict = [...new Set(dict)].filter(v=>{\n  return v &&\n    v !== \'Document\' &&\n    v !== \'Window\' &&\n    v !== \'Q\' &&\n    v !== \'s\' &&\n    v !== \'E\'\n})\n\noutput.innerHTML = dict.join(\'<br>\')\n', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#output{\n  position: absolute;\n  top: 0;\n  left: 0;\n  z-index: 100;\n  width: calc(100% - 40px);\n  height: calc(100% - 40px);\n  margin: 0;\n  font-size: 12px;\n  color: #fff;\n  background: #4f82;\n  font-family: courier;\n  line-height: 1em;\n  padding: 10px;\n  overflow-x: hidden;\n  overflow-y: auto;\n}', '<div id=\"output\"></div>\n', 'build javascript dictionary', 145, 'whitehot robot', '2022-10-05 17:08:48', '[600426,600422,600373,600347,600253,600252,600251,600248,600247]', 35, '', 0, 1),
(600430, '', 'el=document.querySelector(\'#div1\')\n\nnormalRemove=()=>{\n  el.remove()\n}\n\nparentNodeRemove=()=>{\n  el.parentNode.removeChild(el)\n}', 'body,html{\n  text-align: center;\n  margin: 0;\n  height: 100vh;\n  background: #000;\n  color: #fff;\n}\n#div1{\n  border: 1px solid white;\n  color: #fff;\n  font-family: courier;\n  width: 200px;\n  display: inline-block;\n  margin: 20px;\n}\nbutton{\n  width: 200px;\n}', '<div id=\"div1\">\n  div with contents\n</div><br>\n<button onclick=\"normalRemove()\">\n  remove\n</button><br>\n<button onclick=\"parentNodeRemove()\">\n  parentNode.removeChild\n</button>', 'remove vs parentNode.removeChild', 145, 'whitehot robot', '2022-10-07 14:19:41', '', 50, '', 0, 0),
(600431, '', 'let balls = []\nlet funballs = []\n\nlet svgy = document.getElementById(\'svgy\')\nlet groupy = document.getElementById(\'groupy\')\nlet ngroupy = document.getElementById(\'ngroupy\')\nlet select = document.getElementById(\'select\')\n\nlet t = 0 \nlet id =0 \n\nlet step = 1000/30 ;\n\nfunction loop( ) \n{\n\n	let margins = {left:25 , bottom:15 , top:15}\n	let speedbreak = [{duration:5 ,	 pos:85 },\n					{duration:15 	, pos:70 },\n					{duration:35 	, pos:55 },\n					{duration:75 	, pos:40 },\n					{duration:155 	, pos:25 },\n					{duration:315 	, pos:10 },\n					{duration:635 	, pos:0 }] \n	let yrange = {min:0 , max:120}\n	// console.log(svgy.clientWidth)\n\n\n	let xscale =  (svgy.clientWidth - margins.left)/100\n	let yscale =  (svgy.clientHeight - margins.bottom)/(yrange.max - yrange.min) + yrange.min\n\n	for (var i = 0; i < speedbreak.length ; i++) {\n		speedbreak[i].clientpos = speedbreak[i].pos * xscale +margins.left\n		// console.log(speedbreak[i])\n	}\n\n	t ++\n\n	if( t%60 == 0 )\n	{\n		// console.log(\'pushing?\')\n		let yVal = Math.random()*5 +50 +Math.sin(t/600)*50 + 0\n		if(select.value == \'noise\')\n			yVal = Math.random()*50 +50  //+Math.sin(t/600)*200 + 200\n		// console.log(y)\n		// yVal = 100\n		let yClient = (yrange.max - yVal)*yscale\n\n		balls.push( {x:(svgy.clientWidth-1)  , yClient:yClient , yVal:yVal , id:id , dy:0 , mode:\'normal\' , progress:0 ,opacity:255})\n\n		let i = balls.length - 1 \n	\n		if(i>0)\n		ngroupy.innerHTML += \'<line id=\"\' + (\'ballline\' + balls[i-1].id ) + \'\" x1=\"\' + (balls[i-1].x +5) + \'\" y1=\"\' + (balls[i-1].yClient +5) + \'\" x2=\"\' + (balls[i].x +5) + \'\" y2=\"\' + (balls[i].yClient  +5)+ \'\" style=\"stroke:rgb(200,60,50);stroke-width:2\" />\'\n\n		ngroupy.innerHTML += \'<text id=\"\' + (\'balltext\' + balls[i].id)  +\'\" x=\"\' + balls[i].x + \'\" y=\"\' + balls[i].yClient + \'\"\' + \' fill=\"#000000\' + dectohex(balls[i].opacity) + \'\" >\' + Math.round(balls[i].yVal*10)/10.0 + \'</text>\'\n\n		ngroupy.innerHTML += \'<circle id=\"\' + (\'ballcircle\' + balls[i].id) + \'\" cx=\"\' + balls[i].x + \'\" cy=\"\' + balls[i].yClient + \'\" r=\"\' + 5 + \'\" stroke=\"#eeeeeeff\" stroke-width=\"2\" fill=\"#440088\' + dectohex(balls[i].opacity) + \'\" />\'\n\n\n		id ++ ;\n		// console.log(balls)\n	}\n\n	let inner = \'\' \n\n	inner += \'<rect x=\"10\" y=\"10\" rx=\"15\" ry=\"15\" width=99% height=99% style=\"fill:#80200010;stroke:#70707000;stroke-width:0.5;opacity:1\" />\'\n\n	// if(t<10)\n	for (var i = 0; i <= 6; i++) \n	{\n		let lineelement = document.getElementById(\'yline\' + i );\n   		let textelement = document.getElementById(\'ytext\' + i );\n   \n		if(lineelement == null)\n		{\n			ngroupy.innerHTML += \'<line id=\"\' + (\'yline\' + i) + \'\" x1=\"\' + margins.left + \'\" y1=\"\' + ( (svgy.clientHeight - margins.bottom)*(6-i)/6 )  + \'\" x2=\"\' + svgy.clientWidth + \'\" y2=\"\' + ( (svgy.clientHeight - margins.bottom)*(6-i)/6 )  + \'\" style=\"stroke:#aaa8;stroke-width:1\" />\'\n		}else\n		{\n			lineelement.setAttribute(\'x1\', margins.left);\n			lineelement.setAttribute(\'y1\', ( (svgy.clientHeight - margins.bottom)*(6-i)/6 ));\n			lineelement.setAttribute(\'x2\', svgy.clientWidth);\n			lineelement.setAttribute(\'y2\',  ( (svgy.clientHeight - margins.bottom)*(6-i)/6 ));\n		}\n		if(textelement == null)\n		{\n			ngroupy.innerHTML += \'<text id=\"\' + \'ytext\' + i + \'\" x=\"\' + (margins.left -20  ) + \'\" y=\"\' + ( (svgy.clientHeight - margins.bottom)*(6-i)/6 + 10)  + \'\"\' + \' fill=\"#000000ff\" >\' + (yrange.max*i/6  +yrange.min)  + \'</text>\'\n		}else\n		{\n			// console.log(\'found\' + i)\n			// console.log(textelement)\n			textelement.setAttribute(\'x\',  (margins.left -20  ));\n			textelement.setAttribute(\'y\', ( (svgy.clientHeight - margins.bottom)*(6-i)/6 + 10))\n		}\n	}\n	\n	if(balls.length>0)\n	{\n		if(balls[0].x < margins.left )\n		{\n			let ballelement = document.getElementById(\'ballline\' + balls[0].id );\n			let ballelementcircle = document.getElementById(\'ballcircle\' + balls[0].id );\n			let ballelementtext = document.getElementById(\'balltext\' + balls[0].id );\n			ballelement.remove();\n			ballelementcircle.remove()\n			ballelementtext.remove()\n			balls.shift()\n		}\n	}\n	for (var i = 0; i < balls.length; i++) {\n\n		let breaknum = 2\n		for (var j = 0; j < speedbreak.length; j++) \n		{\n			let offset = breaknum -1\n// 1 2\n// 3 4\n// 7 8\n// 15 16\n\n		if(balls[i].x < speedbreak[j].clientpos)\n		{\n			// console.log(offset + \' , \' + balls[i].id + \' , \' + (breaknum /2))\n			if(  ( (balls[i].id  )/(breaknum /2))%2==1 && balls[i].mode != \'delete\')\n			{\n				balls[i-1].dy += (balls[i].yClient + balls[i-1].yClient)/2 - balls[i-1].yClient\n				if(i>2  && balls[i-2].mode == \'delete\')\n					balls[i-2].dy +=  ((balls[i].yClient + balls[i-1].yClient)/2 - balls[i-1].yClient)/2\n\n				balls[i].dy += ((balls[i+1].yClient) + (balls[i-1].yClient+balls[i-1].dy))/2 - balls[i].yClient\n				balls[i].mode = \'delete\'\n\n			}\n		}\n			breaknum *= 2\n\n		}\n		// if(balls[i].x < speedbreak[1].clientpos)\n		// 	if(((balls[i].id-1)/2)%2==0 && balls[i].mode != \'delete\')\n		// 	{\n		// 		balls[i-1].dy += (balls[i].yClient + balls[i-1].yClient)/2 - balls[i-1].yClient\n		// 		if(i>2&& balls[i-2].mode == \'delete\')\n		// 			balls[i-2].dy +=  ((balls[i].yClient + balls[i-1].yClient)/2 - balls[i-1].yClient)/2\n		// 		balls[i].dy += ((balls[i+1].yClient) + (balls[i-1].yClient+balls[i-1].dy))/2 - balls[i].yClient\n\n		// 		balls[i].mode = \'delete\'\n		// 	}\n\n		// if(balls[i].x < speedbreak[2].clientpos)\n		// 	if(((balls[i].id+1)/4)%2==0 && balls[i].mode != \'delete\')\n		// 	{\n		// 		balls[i-1].dy += (balls[i].yClient + balls[i-1].yClient)/2 - balls[i-1].yClient\n		// 		if(i>2 && balls[i-2].mode == \'delete\')\n		// 			balls[i-2].dy +=  ((balls[i].yClient + balls[i-1].yClient)/2 - balls[i-1].yClient)/2\n\n		// 		balls[i].dy += ((balls[i+1].yClient) + (balls[i-1].yClient+balls[i-1].dy))/2 - balls[i].yClient\n\n		// 		balls[i].mode = \'delete\'\n		// 	}\n		// 	// \n		// if(balls[i].x < speedbreak[3].clientpos)\n		// 	if(((balls[i].id-3)/8)%2==0 && balls[i].mode != \'delete\')\n		// 	{\n		// 		balls[i-1].dy += (balls[i].yClient + balls[i-1].yClient)/2 - balls[i-1].yClient\n		// 		if(i> 2 && balls[i-2].mode == \'delete\')\n		// 			balls[i-2].dy +=  ((balls[i].yClient + balls[i-1].yClient)/2 - balls[i-1].yClient)/2\n\n		// 		balls[i].dy += ((balls[i+1].yClient) + (balls[i-1].yClient+balls[i-1].dy))/2 - balls[i].yClient\n\n		// 		balls[i].mode = \'delete\'\n		// 	}\n\n	}\n	// 	\n\n	inner += \'<line x1=\"\' + margins.left + \'\" y1=\"0\" x2=\"\' + margins.left + \'\" y2=\"\' + \n				svgy.clientHeight + \'\" style=\"stroke:#000f;stroke-width:1\" />\'\n\n	inner += \'<line x1=\"0\" y1=\"\' + (svgy.clientHeight-margins.bottom) + \'\" x2=\"\' + (svgy.clientWidth) + \'\" y2=\"\' + (svgy.clientHeight-margins.bottom) + \'\" style=\"stroke:#000f;stroke-width:1\" />\'\n\n	for (var i = 0; i < speedbreak.length; i++) {\n\n		let lineelement = document.getElementById(\'xline\' + i );\n\n		if(lineelement == null)\n		{\n			ngroupy.innerHTML += \'<line id=\"\' + (\'xline\' + i ) + \'\" x1=\"\' + (speedbreak[i].clientpos)+ \'\" y1=\"0\" x2=\"\' +  (speedbreak[i].clientpos) + \'\" y2=\"\' + svgy.clientHeight + \'\" style=\"stroke:#aaa8;stroke-width:1\" />\'\n		}else\n		{\n			lineelement.setAttribute(\'x1\',  (speedbreak[i].clientpos) );\n			lineelement.setAttribute(\'y1\',  0 );\n			lineelement.setAttribute(\'x2\',  (speedbreak[i].clientpos));\n			lineelement.setAttribute(\'y2\',  svgy.clientHeight);\n		}\n\n		let textelement = document.getElementById(\'xtext\' + i );\n\n		if(textelement == null)\n		{\n			ngroupy.innerHTML += \'<text id=\"\' + (\'xtext\' + i ) + \'\" x=\"\' + (speedbreak[i].clientpos + 10) + \'\" y=\"\' + (svgy.clientHeight -15) + \'\"\' + \' fill=\"#000000ff\" >\' + speedbreak[i].duration +\'</text>\'\n		}else\n		{\n			textelement.setAttribute(\'x\', (speedbreak[i].clientpos + 10)) ;\n			textelement.setAttribute(\'y\', (svgy.clientHeight  -15 )) ;\n\n		}\n\n\n	}\n\n\n	for (var i = 0; i < balls.length; i++) {\n\n		// balls[i].x -= (balls[i].x*balls[i].x*balls[i].x)/300000000  +0.03\n\n		for (var j = 0; j < speedbreak.length; j++) {			\n\n			let prevClientpos = 0 \n			let prevTime = 0 \n			if(j ==0 ) \n			{\n				prevClientpos = svgy.clientWidth\n			}else{\n				prevClientpos = speedbreak[j-1][\'clientpos\']	\n				prevTime  = speedbreak[j-1][\'duration\']	\n			}\n\n			if(balls[i].x >=speedbreak[j][\'clientpos\'] && balls[i].x < prevClientpos)\n			{\n				let width = ( prevClientpos - speedbreak[j][\'clientpos\'])\n				let time  = speedbreak[j][\'duration\'] - prevTime\n				let nowstep = step * width / time / 1000\n				// console.log(nowstep)\n				balls[i].x	-= nowstep \n			} \n		}\n		// else if(balls[i].x >speedbreak[1][\'clientpos\'] )\n		// {\n		// 	let width = ( prevClientpos - speedbreak[1][\'clientpos\'])\n		// 	let time  = speedbreak[1][\'duration\'] - speedbreak[0][\'duration\']\n		// 	let nowstep = step * width / time / 1000\n		// 	// console.log(nowstep)\n		// 	balls[i].x	-= nowstep \n		// }\n		// else if(balls[i].x >speedbreak[2][\'clientpos\'] )\n		// {\n			\n		// 	let width = ( prevClientpos - speedbreak[2][\'clientpos\'])\n		// 	let time  = speedbreak[2][\'duration\'] - speedbreak[1][\'duration\']\n		// 	let nowstep = step * width / time / 1000\n		// 	// console.log(nowstep)\n		// 	balls[i].x	-= nowstep \n		// }\n		// else if(balls[i].x >speedbreak[3][\'clientpos\'] )\n		// {\n			\n		// 	let width = ( prevClientpos - speedbreak[3][\'clientpos\'])\n		// 	let time  = speedbreak[3][\'duration\'] - speedbreak[2][\'duration\']\n		// 	let nowstep = step * width / time / 1000\n		// 	// console.log(nowstep)\n		// 	balls[i].x	-= nowstep \n		// }\n		// else if(balls[i].x >speedbreak[4][\'clientpos\'] )\n		// {\n			\n		// 	let width = ( prevClientpos - speedbreak[4][\'clientpos\'])\n		// 	let time  = speedbreak[4][\'duration\'] - speedbreak[3][\'duration\']\n		// 	let nowstep = step * width / time / 1000\n		// 	// console.log(nowstep)\n		// 	balls[i].x	-= nowstep \n		// }\n		// else if(balls[i].x >speedbreak[5][\'clientpos\'] )\n		// {\n			\n		// 	let width = ( prevClientpos - speedbreak[5][\'clientpos\'])\n		// 	let time  = speedbreak[5][\'duration\'] - speedbreak[4][\'duration\']\n		// 	let nowstep = step * width / time / 1000\n		// 	// console.log(nowstep)\n		// 	balls[i].x	-= nowstep \n		// }\n\n		balls[i].opacity = 255\n		if(balls[i].mode == \'delete\')\n		{\n			if(balls[i].progress < 100 )\n			{\n				balls[i].progress += 4; \n				balls[i].opacity = 255 *(100 - balls[i].progress)/100\n\n			}else\n			{\n				let ballelement = document.getElementById(\'ballline\' + balls[i].id );\n				let ballelementcircle = document.getElementById(\'ballcircle\' + balls[i].id );\n				let ballelementtext = document.getElementById(\'balltext\' + balls[i].id );\n				\n				ballelement.remove();\n				ballelementtext.remove()\n				ballelementcircle.remove()\n				balls.splice(i, 1)\n				// funballs.push(balls[i])\n			}\n		}\n\n		let progstep = 1\n		if(balls[i].dy > 25 ||balls[i].dy < -25 )\n			progstep = 2 \n		if(balls[i].dy > 50 ||balls[i].dy < -50 )\n			progstep = 3 \n		if(balls[i].dy > 75 ||balls[i].dy < -75 )\n			progstep = 4 \n		if(balls[i].dy > progstep)\n		{\n			balls[i].yClient += progstep	\n			balls[i].dy-= progstep\n		}\n		if(balls[i].dy < -progstep)\n		{\n			balls[i].yClient -= progstep		\n			balls[i].dy+= progstep\n		}\n		if(balls[i].dy != 0 && balls[i].dy  <progstep && balls[i].dy > -progstep )\n		{\n			balls[i].yClient += balls[i].dy		\n			balls[i].dy= 0\n		}\n		balls[i].yVal = yrange.max - balls[i].yClient/yscale \n\n	}\n\n   	// let textelement = document.getElementById(\'ytext\' + i );\n\n\n	for (var i = 1; i < balls.length; i++) {\n\n	  	let ballelement = document.getElementById(\'ballline\' + balls[i-1].id );\n	  	if(ballelement != null)\n		{\n			ballelement.setAttribute(\'x1\', (balls[i-1].x ) ) ;\