(600436, '', '    c=document.querySelector(\'#c\')\n    input=document.querySelector(\'#mainInput\')\n    c.addEventListener(\'click\', ()=>{input.focus()})\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    R = function(r,g,b,a) {\n      a = a === undefined ? 1 : a;\n      return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n    };\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n        }\n        Q=()=>[c.width/2+X/Z*800,c.height/1.01+Y/Z*800]\n        I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n        stroke=(col)=>{\n          //x.closePath()\n          x.lineWidth=Math.min(500, 150/Z)\n          x.strokeStyle=col\n          x.globalAlpha=.2\n          x.stroke()\n          x.lineWidth/=5\n          x.globalAlpha=1\n          x.stroke()\n        }\n      }\n\n        rw=8,cl2=14,cl=14, sp=1, ls=sp*(2**.5/2),q2=-.25-Math.PI\n        sp2=sp,q4=0,osp=1.2,ofx=2.2\n        segs = []\n        B=Array(cl*rw).fill().map((v,i)=>{\n          if(i%cl<cl-1&&(i%cl)<cl-2){\n            q=Math.PI*2/(cl)