c(...Q(),20,0,7)\n            //x.fillStyle=\'#4f8a\'\n            //x.fill()\n            //x.beginPath()\n            X=X3=segs[l[3]][0]\n            Y=Y3=segs[l[3]][1]\n            Z=Z3=segs[l[3]][2]\n            //R(Rl,Pt,Yw,1)\n            //x.arc(...Q(),20,0,7)\n            //x.fillStyle=\'#4f8a\'\n            //x.fill()\n            \nif(showWhole){\n            x.beginPath()\n            X=cx2=(X2+X1)/2\n            Y=cy2=(Y2+Y1)/2\n            Z=cz2=(Z2+Z1)/2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=cx1=X2+(X4-X2)/2\n            Y=cy1=Y2+(Y4-Y2)/2\n            Z=cz1=Z2+(Z4-Z2)/2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            stroke(\'#000\')\n\n            x.beginPath()\n            X=cx1=(X3+X1)/2\n            Y=cy1=(Y3+Y1)/2\n            Z=cz1=(Z3+Z1)/2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=cx2=(X2+X1)/2\n            Y=cy2=(Y2+Y1)/2\n            Z=cz2=(Z2+Z1)/2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            stroke(\'#000\')\n\n            x.beginPath()\n            X=cx1=(X4+X3)/2\n            Y=cy1=(Y4+Y3)/2\n            Z=cz1=(Z4+Z3)/2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=cx2=(X1+X3)/2\n            Y=cy2=(Y1+Y3)/2\n            Z=cz2=(Z1+Z3)/2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            stroke(\'#000\')\n\n            x.beginPath()\n            X=cx1=(X4+X3)/2\n            Y=cy1=(Y4+Y3)/2\n            Z=cz1=(Z4+Z3)/2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=cx2=(X2+X4)/2\n            Y=cy2=(Y2+Y4)/2\n            Z=cz2=(Z2+Z4)/2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            stroke(\'#000\')\n\n            x.beginPath()\n            X=cx1=(X1+X3)/2\n            Y=cy1=(Y1+Y3)/2\n            Z=cz1=(Z1+Z3)/2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=cx2=(X2+X4)/2\n            Y=cy2=(Y2+Y4)/2\n            Z=cz2=(Z2+Z4)/2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            stroke(\'#000\')\n\n            x.beginPath()\n            X=cx1=(X4+X3)/2\n            Y=cy1=(Y4+Y3)/2\n            Z=cz1=(Z4+Z3)/2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=cx2=(X2+X1)/2\n            Y=cy2=(Y2+Y1)/2\n            Z=cz2=(Z2+Z1)/2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            stroke(\'#000\')\n\n            x.beginPath()\n            X=cx1=X1+(X2-X1)/3\n            Y=cy1=Y1+(Y2-Y1)/3\n            Z=cz1=Z1+(Z2-Z1)/3\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=cx1=X3+(X4-X3)/3\n            Y=cy1=Y3+(Y4-Y3)/3\n            Z=cz1=Z3+(Z4-Z3)/3\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            stroke(\'#000\')\n\n            x.beginPath()\n            X=cx1=X1+(X2-X1)/3*2\n            Y=cy1=Y1+(Y2-Y1)/3*2\n            Z=cz1=Z1+(Z2-Z1)/3*2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=cx1=X3+(X4-X3)/3*2\n            Y=cy1=Y3+(Y4-Y3)/3*2\n            Z=cz1=Z3+(Z4-Z3)/3*2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            stroke(\'#000\')\n\n            x.beginPath()\n            X=cx1=X3+(X1-X3)/3*2\n            Y=cy1=Y3+(Y1-Y3)/3*2\n            Z=cz1=Z3+(Z1-Z3)/3*2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=cx1=X4+(X2-X4)/3*2\n            Y=cy1=Y4+(Y2-Y4)/3*2\n            Z=cz1=Z4+(Z2-Z4)/3*2\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            stroke(\'#000\')\n\n            x.beginPath()\n            X=cx1=X3+(X1-X3)/3\n            Y=cy1=Y3+(Y1-Y3)/3\n            Z=cz1=Z3+(Z1-Z3)/3\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=cx1=X4+(X2-X4)/3\n            Y=cy1=Y4+(Y2-Y4)/3\n            Z=cz1=Z4+(Z2-Z4)/3\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            stroke(\'#000\')\n            }\n          }\n        \n         }\n          if(v[1]<6 && v[4]<6){\n            x.beginPath()\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            X=v[3]\n            Y=v[4]\n            Z=v[5]\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n            stroke(\'#000\')\n          }\n      })\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  border: 1px solid #4ff8;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>\n', 'mesh', 145, 'whitehot robot', '2022-10-08 20:20:33', '[600428,600426,600422,600373,600347,600253,600252,600251,600248,600247]', 56, '', 0, 0),
