INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600444, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=to=0\n\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth/document.body.clientWidth < 1.7777778)\n    {\n      c.style.width  = document.body.clientWidth + \'px\'\n      c.style.height = (document.body.clientWidth/1.777777778) + \'px\'\n    }else{\n      c.style.height = document.body.clientHeight + \'px\'\n      c.style.width  = (document.body.clientHeight*1.777777778) + \'px\'\n    }\n    c.width  = 1920\n    c.height = 1080\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Rn=Math.random\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[(j+0)%3]*(l=j<3?1:-1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n    stroke=(strokeCol, fillCol)=>{\n      x.closePath()\n      x.lineWidth= Math.min(500, 800/Z)\n      //x.globalAlpha=.2\n      x.strokeStyle=strokeCol\n      //x.stroke()\n      x.lineWidth/=5\n      x.globalAlpha=.75\n      x.stroke()\n      x.globalAlpha=1\n      if(fillCol){\n        x.fillStyle=fillCol\n        x.fill()\n      }\n    }\n    drawCube = (tx, ty, tz, ls, scol, fcol) => {\n      CB.map((v,i)=>{\n        if(!(i%4))x.beginPath()\n        X=tx+v[0]*ls\n        Y=ty+v[1]*ls\n        Z=tz+v[2]*ls\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        if(i%4==3)stroke(scol, fcol)\n      })\n    }\n\n    rw=2,cl=10,br=10,sp=2**.5*3\n    G=Math.hypot(rw*sp, cl*sp)\n    B=[]\n    Array(rw*cl*br).fill().map((v,i)=>{\n      tx=((i%cl)-cl/2+.5)*sp\n      ty=(((i/cl|0)%rw)-rw/2+.5)*sp\n      tz=((i/cl/rw|0)-br/2+.5)*sp\n      a=[]\n      CB.map(q=>{\n        X=q[0]+tx\n        Y=q[1]+ty\n        Z=q[2]+tz\n        a=[...a, [X,Y,Z,X,Y,Z,0,0,0]]\n      })\n      B=[...B, ...a]\n    })\n    iPGv=.02, iPmaxls=20\n    P=[]\n    iSTC=3e3,iSTG=1e3\n    ST=Array(iSTC).fill().map(v=>{\n      X=(Rn()-.5)*iSTG \n      Y=(Rn()-.5)*iSTG \n      Z=(Rn()-.5)*iSTG \n      return [X,Y,Z]\n    })\n  }\n\n  Rl=0,Pt=Math.max(-.3,Math.min(Math.PI/2+Math.PI,-C(t)*5)),Yw=Math.max(-Math.PI/2, Math.min(Math.PI/2, S(t)*3))\n  //Rl=0,Pt=-Math.PI/2,Yw=0\n  oX=0,oY=0,oZ=Math.max(30, Math.min(60, C(t)*200))\n  //oX=oY=0, oZ=40\n\n  x.fillStyle=\'#000a\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin=x.linCap=\'butt\'\n\n  if(!((t*60|0)%20))P=[...P, [(Rn()-.5)*G, 0, (Rn()-.5)*G, 0]]\n\n  ST.map(v=>{\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      s=Math.min(500, 1e4/Z)\n      x.globalAlpha=Math.min(1,Z/600)\n      x.fillStyle=\'#fff2\'\n      l=Q()\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      s/=4\n      x.fillStyle=\'#fff\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n    }\n  })\n  x.globalAlpha=1\n\n  P.map(v=>{\n    sd=20\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R(Rl,Pt,Yw,0)\n    tx=X,ty=Y,tz=Z\n    v[3]+=v[3]/6+iPGv\n    x.beginPath()\n    for(j=sd;j--;){\n      X=tx+S(p=Math.PI*2/sd*j)*v[3]\n      Y=ty+C(p)*v[3]\n      Z=tz\n      R(0,0,0,1)\n      if(Z>0) x.lineTo(...Q())\n    }\n    stroke(`rgba(255,255,255,${1/(1+v[3]**1e10)})`, `rgba(0,200,255,${.4/(1+v[3]**8/1e10)})`)\n  })\n\n  P=P.filter(v=>v[3]<iPmaxls)\n\n  B.map((v, i)=>{\n    if(!(i%4))x.beginPath()\n    v[6]+=(v[3]-v[0])/40\n    v[7]+=(v[4]-v[1])/40\n    v[8]+=(v[5]-v[2])/40\n    X=v[0]+=v[6]/=1.1\n    Y=v[1]+=v[7]/=1.1\n    Z=v[2]+=v[8]/=1.1\n    P.map(q=>{\n      tx=q[0]\n      ty=q[1]\n      tz=q[2]\n      d=Math.hypot(dx=X-tx,dy=Y-ty,dz=Z-tz)\n      if(d<q[3]){\n        dx/=d\n        dy/=d\n        dz/=d\n        v[0]=tx+dx*q[3]\n        v[1]=ty+dy*q[3]\n        v[2]=tz+dz*q[3]\n        v[6]+=dx/1\n        v[7]+=dy/1\n        v[8]+=dz/1\n      }\n    })\n    R(Rl, Pt, Yw, 1)\n    if(Z>0) x.lineTo(...Q())\n    if(i%4==3) stroke(\'#0ff6\', \'#60f2\')\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  margin: 0;\n  overflow: hidden;\n  height: 100vh;\n  background: #000;\n}\n#c{\n  position: absolute;\n  background: #0008;\n  border: 1px solid #fff;\n  left: 50%;\n  top:50%;\n  transform: translate(-50%,-50%);\n}', '<canvas id=c>', 'cube warp fancy', 145, 'whitehot robot', '2022-10-12 20:04:03', '', 59, '', 0, 0),
