.stroke()\n          x.lineWidth/=5\n          x.globalAlpha=1\n          x.stroke()\n        }\n        fill=col=>{\n          x.closePath()\n          x.fillStyle=col\n          x.fill()\n        }\n        P=Array(iBc).fill().map(v=>[])\n        iSTG=4e4, iSTc=3e3\n        ST=Array(iSTc).fill().map(v=>{\n          X=(Rn()-.5)*iSTG\n          Y=(Rn()-.5)*iSTG\n          Z=(Rn()-.5)*iSTG\n          return [X,Y,Z]\n        })\n      }\n\n      x.fillStyle=\'#0008\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineCap=x.lineJoin=\'butt\'\n      oX=oY=0, oZ=2800+Math.max(-1600,Math.min(1600,S(t*1.5)*1e4))\n      Rl=t/4\n      Pt=Math.max(0,Math.min(Math.PI,S(t/2)*5))\n      Yw=Math.max(-Math.PI,Math.min(Math.PI,C(t/2)*5))\n\n      axisSegs=1,segLen=2\n      maxCondLen=12\n      showAxis=false\n\n      ST.map(v=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          l=Q()\n          x.globalAlpha=Math.min(1, ((Z/6000)**2)/2)\n          s=Math.min(500, 2e5/Z)\n          x.fillStyle=\'#fff2\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          s/=3\n          x.fillStyle=\'#fffa\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        }\n      })\n\n      B.map((v,i)=>{\n        sd=v[6]\n        ls=v[7]\n        d=Math.hypot(v[3],v[4],v[5])\n        v[3]/=d\n        v[4]/=d\n        v[5]/=d\n        v[3]*=iBv\n        v[4]*=iBv\n        v[5]*=iBv\n        p1=Math.atan2(v[3],v[5])\n        p2=Math.acos(v[4]/Math.hypot(v[3],v[4],v[5]))-Math.PI/2\n        X=0\n        Y=0\n        Z=iBv\n        R(0,p2,p1)\n        vx=X,vy=Y,vz=Z\n        tx=v[0]+=vx\n        ty=v[1]+=vy\n        tz=v[2]+=vz\n        p3=Math.atan2(v[0],v[2])\n        p4=Math.acos(v[1]/Math.hypot(v[0],v[1],v[2]))-Math.PI/2\n        X=0\n        Y=0\n        Z=iBv\n        R(0,p4,p3)\n        vx_=X,vy_=Y,vz_=Z\n        v[3]-=(vx_-vx)/6+(Rn()-.5)/2\n        v[4]+=(vy_-vy)/200+S(t/20+i)*18+(Rn()-.5)/2\n        v[5]-=(vz_-vz)/6+(Rn()-.5)/2\n        x.beginPath()\n        for(a=[],j=sd;j--;){\n          X=S(p=Math.PI*2/sd*j+Math.PI/sd+S(t/2+i)*50)*ls\n          Y=C(p)*ls\n          Z=0\n          R(0,p2,p1)\n          X+=tx\n          Y+=ty\n          Z+=tz\n          a=[[X,Y,Z], ...a]\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n        }\n        P[i]=[a, ...P[i]]\n        stroke(\'#fff\')\n        if(showAxis)for(j=axisSegs;j--;){\n          x.beginPath()\n          X=0\n          Y=0\n          Z=i*segLen\n          R(0,p2,p1)\n          X+=tx,Y+=ty,Z+=tz\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n          X=0\n          Y=0\n          Z=(j+1)*segLen\n          R(0,p2,p1)\n          X+=tx,Y+=ty,Z+=tz\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n          stroke(\'#4f86\')\n        }\n      })\n\n\n      P=P.map((v,i)=>{\n        v=v.filter((q,j)=>j<maxCondLen)\n        v.map((q,j)=>{\n          col1=`rgba(255,255,255,${.65-(j/maxCondLen)*.65})`\n          x.beginPath()\n          q.map(n=>{\n            X=n[0]\n            Y=n[1]\n            Z=n[2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0) x.lineTo(...Q())\n          })\n          stroke(col1)\n        })\n        v.map((q,j)=>{\n          if(j){\n            col1=`rgba(255,255,255,${.5-(j/maxCondLen)*.5})`\n            q.map((n,m)=>{\n              x.beginPath()\n              X=n[0]\n              Y=n[1]\n              Z=n[2]\n              R(Rl,Pt,Yw,1)\n              if(Z>0) x.lineTo(...Q())\n              X=v[j-1][m][0]\n              Y=v[j-1][m][1]\n              Z=v[j-1][m][2]\n              R(Rl,Pt,Yw,1)\n              if(Z>0) x.lineTo(...Q())\n              stroke(col1)\n            })\n          }\n        })\n        v.map((q,j)=>{\n          if(j){\n            col1=`rgba(255,255,255,${.5-(j/maxCondLen)*.5})`\n            q.map((n,m)=>{\n              col2=`hsla(${j/maxCondLen*360/2+i*200-t*300},99%,${Math.max(50, 100-((j/maxCondLen)**3)*1200)}%,${.2-(j/maxCondLen)*.2})`\n              x.beginPath()\n              X=v[j][l=(m+0)%q.length][0]\n              Y=v[j][l][1]\n              Z=v[j][l][2]\n              R(Rl,Pt,Yw,1)\n              if(Z>0) x.lineTo(...Q())\n              X=v[j][l=(m+1)%q.length][0]\n              Y=v[j][l][1]\n              Z=v[j][l][2]\n              R(Rl,Pt,Yw,1)\n              if(Z>0) x.lineTo(...Q())\n              X=v[j-1][l=(m+1)%q.length][0]\n              Y=v[j-1][l][1]\n              Z=v[j-1][l][2]\n              R(Rl,Pt,Yw,1)\n              if(Z>0) x.lineTo(...Q())\n              X=v[j-1][l=(m+0)%q.length][0]\n              Y=v[j-1][l][1]\n              Z=v[j-1][l][2]\n              R(Rl,Pt,Yw,1)\n              if(Z>0) x.lineTo(...Q())\n              fill(col2)\n            })\n          }\n        })\n        return v\n      })\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}\n', '<canvas id=c></canvas>', 'things you like', 145, 'whitehot robot', '2022-10-13 17:35:54', '[600428,600426,600422,600373,600347,600253,600252,600251,600248,600247]', 81, '', 0, 0),
