(600451, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    R = function(r,g,b,a) {\n      a = a === undefined ? 1 : a;\n      return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n    };\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n        }\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?1:-1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n        plotCluster = (tx,ty,tz,count,size,iBv) => {\n          ret = []\n          for(i=count;i--;){\n            ls=(Rn()**.5)*S(p2=Math.PI/2*Rn()**(1/3))*size\n            X=2+S(p1=Math.PI*2*Rn())*ls\n            Y=C(p2)*size*(Rn()<.5?1:-1)\n            Z=C(p1)*ls\n            X+=tx\n            Y+=ty\n            Z+=tz\n            vx=S(p=p1+Math.PI/2)*iBv\n            vy=0\n            vz=C(p)*iBv\n            ret=[...ret, [X,Y,Z,vx,vy,vz]]\n          }\n          return ret\n        }\n\n        drawCube = (tx,ty,tz,rad,col,fcol) => {\n          CB.map((v,i)=>{\n            if(i%4==0)x.beginPath()\n            X=v[0]*rad+tx\n            Y=v[1]*rad+ty\n            Z=v[2]*rad+tz\n            R(Rl,Pt,Yw,1)\n            if(Z>0) x.lineTo(...Q())\n            if(i%4==3) stroke(col, fcol)\n          })\n        }\n\n        stroke = (strokecol, fillcol) => {\n          x.closePath()\n          x.strokeStyle=strokecol\n          //x.globalAlpha=.2\n          x.lineWidth = Math.min(500, 100/Z)\n          //x.stroke()\n          x.lineWidth/=5\n          x.globalAlpha=1\n          x.stroke()\n          if(fillcol){\n            x.fillStyle=fillcol\n            x.fill()\n          }\n        }\n\n        rad = 3\n        iBc = 20\n        iBv = .2\n        B = plotCluster(0, 0, 0, iBc, rad, iBv)\n\n        ls=2**.5/2\n        divideSpace = (tx, ty, tz, nrad) => {\n          if(nrad<rad/16) return\n          let good = false\n          B.map(v=>{\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            if(\n              X>tx-nrad && X<tx+nrad &&\n              Y>ty-nrad && Y<ty+nrad &&\n              Z>tz-nrad && Z<tz+nrad){\n              good=true\n            }\n          })\n          if(good){\n            containers=[...containers, [tx, ty, tz, nrad]]\n            for(let i=8;i--;){\n              let nx=tx+((i%2)-.5)*nrad*ls\n              let ny=ty+(((i/2|0)%2)-.5)*nrad*ls\n              let nz=tz+(((i/4|0)%2)-.5)*nrad*ls\n              divideSpace(nx, ny, nz, nrad/2)\n            }\n          }\n        }\n      }\n\n      x.fillStyle=\'#0008\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'butt\'\n      oX=oY=0, oZ=6\n      Rl=t/4,Pt=-t/2,Yw=t/8\n      //Rl=0,Pt=0,Yw=0\n\n      containers = []\n      divideSpace(0, 0, 0, rad*1)\n      containers.map(v=>{\n        drawCube(...v,\'#fff1\',\'#44ffff03\')\n      })\n\n      B.map((v,i)=>{\n        X=v[0]+=v[3]-=v[0]/1e3\n        Y=v[1]+=v[4]-=v[1]/1e3\n        Z=v[2]+=v[5]-=v[2]/1e3\n        B.map((q,j)=>{\n          if(i!=j){\n            tx=q[0]\n            ty=q[1]\n            tz=q[2]\n            d=Math.hypot(a=tx-X,b=ty-Y,e=tz-Z)\n            v[3]+=a/2e4\n            v[4]+=b/2e4\n            v[5]+=e/2e4\n          }\n        })\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          l=Q()\n          s=Math.min(500, 150/Z)\n          x.fillStyle=\'#fff2\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          s/=3\n          x.fillStyle=\'#fff\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        }\n      })\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'barnes hut space-partitioning (oct-tree)', 145, 'whitehot robot', '2022-10-14 15:06:22', '[600422,600373,600347,600253,600252,600251,600248,600247]', 68, '', 0, 0),
