           if(i%4==0)x.beginPath()\n            X=v[0]*rad+tx\n            Y=v[1]*rad+ty\n            Z=v[2]*rad+tz\n            R(Rl,Pt,Yw,1)\n            if(Z>0) x.lineTo(...Q())\n            if(i%4==3) stroke(\'\', fcol)\n          })\n        }\n\n        iPc=3e3, G=4, sx=sy=sz=0, ls=.2,ls_=2**.5/2\n        P=Array(iPc).fill().map(v=>{\n          switch(Rn()*6|0){\n            case 0: sx+=ls; break\n            case 1: sy+=ls; break\n            case 2: sz+=ls; break\n            case 3: sx-=ls; break\n            case 4: sy-=ls; break\n            case 5: sz-=ls; break\n          }\n          if(sx>G*ls_)sx-=G*2*ls_\n          if(sx<-G*ls_)sx+=G*2*ls_\n          if(sy>G*ls_)sy-=G*2*ls_\n          if(sy<-G*ls_)sy+=G*2*ls_\n          if(sz>G*ls_)sz-=G*2*ls_\n          if(sz<-G*ls_)sz+=G*2*ls_\n          return [sx,sy,sz,sx,sy,sz]\n        })\n        rad = G, subs=8\n        divideSpace = (tx, ty, tz, nrad) => {\n          let ls=2**.5/2\n          if(nrad<rad/subs) return\n          containers=[...containers, [tx, ty, tz, nrad]]\n          for(let i=8;i--;){\n            let nx=tx+((i%2)-.5)*nrad*ls\n            let ny=ty+(((i/2|0)%2)-.5)*nrad*ls\n            let nz=tz+(((i/4|0)%2)-.5)*nrad*ls\n            divideSpace(nx, ny, nz, nrad/2)\n          }\n        }\n        containers=[]\n        divideSpace(0, 0, 0, rad)\n\n        containers.map((e,m)=>{\n          n=e\n          tx=n[0]\n          ty=n[1]\n          tz=n[2]\n          P.map((v,i)=>{\n            X=v[0]\n            Y=v[1]\n            Z=v[2]\n            if(\n              X>tx-rad/subs && X<tx+rad/subs &&\n              Y>ty-rad/subs && Y<ty+rad/subs &&\n              Z>tz-rad/subs && Z<tz+rad/subs){\n              v[3]=m\n            }\n          })\n        })\n      }\n\n      x.fillStyle=\'#fffa\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineCap=x.lineJoin=\'butt\'\n      oX=oY=0, oZ=8\n      Rl=0,Pt=S(t/2)*6,Yw=t*2\n\n      contrar=[]\n      containers.map((v,i)=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R(Rl,Pt,Yw,1)\n        contrar=[...contrar,[X,Y,Z,i]]\n      })\n      contrar=contrar.sort((a,b)=>b[2]-a[2])\n\n\n      containers.map((e,m)=>{\n        l_=contrar[m][3]\n        n=containers[l_]\n        tx=n[0]\n        ty=n[1]\n        tz=n[2]\n        P.map((v,i)=>{\n          if(v[3]!=l_) return\n          X=v[0]\n          Y=v[1]\n          Z=v[2]\n          if(\n            X>tx-rad/4 && X<tx+rad/4 &&\n            Y>ty-rad/4 && Y<ty+rad/4 &&\n            Z>tz-rad/4 && Z<tz+rad/4){\n            R(Rl,Pt,Yw,1)\n            if(Z>0){\n              x.fillStyle=`hsla(${360/P.length*i},99%,50%,.1)`\n              s=Math.min(300/Z)\n              l=Q()\n              x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n              x.fillStyle=`hsla(${360/P.length*i},99%,60%,.9)`\n              s/=3\n              x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n            }\n          }\n        })\n        drawCube(...n,\'#fff0\',\'#00000008\')\n      })\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'depth sorting by octant space partitioning', 145, 'whitehot robot', '2022-10-14 22:52:36', '[600422,600373,600347,600253,600252,600251,600248,600247]', 62, '', 0, 0),
