 X=v[0]*rad+tx\n            Y=v[1]*rad+ty\n            Z=v[2]*rad+tz\n            R(Rl,Pt,Yw,1)\n            if(Z>0) x.lineTo(...Q())\n            if(i%4==3) stroke(col, fcol)\n          })\n        }\n        iPc=60,sd=12\n        P=Array(iPc).fill().map((v,i)=>{\n          ls=1*(iPc-i/1.05)/40\n          a=[]\n          for(j=sd;j--;){\n            X=S(p=Math.PI*2/sd*j)*ls-((i/20)**.5*2)\n            Y=C(p)*ls-ls*2\n            Z=0\n            R(0,Math.PI*2/iPc*3*i-.5,0)\n            a=[...a, [X,Y,Z]]\n          }\n          return a\n        })\n      }\n\n      x.fillStyle=\'#fffa\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineCap=x.lineJoin=\'butt\'\n      oX=oY=0, oZ=8\n      Rl=0,Pt=t*2,Yw=t/2\n\n      P.map((v,i)=>{\n        x.beginPath()\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(Rl,Pt,Yw,1)\n          if(Z>0)x.lineTo(...Q())\n        })\n        stroke(\'#000a\')\n        if(i<P.length-1){\n          v.map((q,j)=>{\n            x.beginPath()\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0)x.lineTo(...Q())\n            X=P[(i+1)%P.length][j][0]\n            Y=P[(i+1)%P.length][j][1]\n            Z=P[(i+1)%P.length][j][2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0)x.lineTo(...Q())\n            X=P[(i+1)%P.length][(j+1)%v.length][0]\n            Y=P[(i+1)%P.length][(j+1)%v.length][1]\n            Z=P[(i+1)%P.length][(j+1)%v.length][2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0)x.lineTo(...Q())\n            X=P[i][(j+1)%v.length][0]\n            Y=P[i][(j+1)%v.length][1]\n            Z=P[i][(j+1)%v.length][2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0)x.lineTo(...Q())\n            stroke(\'#000a\',\'#4f82\')\n          })\n        }\n      })\n      \n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  h