(600456, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    R = function(r,g,b,a) {\n      a = a === undefined ? 1 : a;\n      return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n    };\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        bgvid=document.createElement(\'video\')\n        bgvid.muted = true\n        bgvid.loop = true\n        bgvid.oncanplay=()=>{\n          go=true\n          bgvid.play()\n        }\n        bgvid.src=\"/proxy.php?url=https://srmcgann.github.io/assets/ExMOp.mp4\"\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n        }\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n        \n        stroke = (scol, fcol) => {\n          //x.closePath()\n          if(scol){\n            x.lineWidth = Math.min(500, 10/Z)\n            x.strokeStyle = scol\n            x.stroke()\n          }\n          if(fcol){\n            x.fillStyle = fcol\n            x.fill()\n          }\n        }\n\n        neighborless=k=>{\n          cx = k%cl\n          cy = k/cl|0\n          let ct=0, tx, ty         \n          B.map((v,i)=>{\n            let X = i%cl\n            let Y = i/cl|0\n            for(let j=8;j--;){\n              switch(j){\n                case 0:\n                  tx=X-1\n                  ty=Y\n                break\n                case 1:\n                  tx=X-1\n                  ty=Y-1\n                break\n                case 2:\n                  tx=X\n                  ty=Y-1\n                break\n                case 3:\n                  tx=X+1\n                  ty=Y-1\n                break\n                case 4:\n                  tx=X+1\n                  ty=Y\n                break\n                case 5:\n                  tx=X+1\n                  ty=Y+1\n                break\n                case 6:\n                  tx=X\n                  ty=Y+1\n                break\n                case 7:\n                  tx=X-1\n                  ty=Y+1\n                break\n              }\n              if(tx>cl-1) tx=0\n              if(tx<0)    tx=cl-1\n              if(ty>rw-1) ty=0\n              if(ty<0)    ty=rw-1\n              let k2 = cl*ty+tx\n              if(k != k2 && Math.abs(cx-tx)<=1 && Math.abs(cy-ty)<=1  && B[k2][3]) ct++\n            }\n          })\n          ret = ct<16\n          return ret\n        }\n\n        tgt = 160\n        rw=70, cl=rw\n        sp=.3\n        B=Array(rw*cl).fill().map((v,i)=>{\n          X=((i%cl)-cl/2+.5)*sp\n          Y=(((i/cl|0)%rw)-rw/2+.5)*sp\n          Z=0\n          return [X, Y, Z, 0]\n        })\n        B__=JSON.parse(JSON.stringify(B))\n        recurse = k => { \n          if(B.filter(v=>v[3]).length>tgt) return\n          let X = k%cl\n          let Y = k/cl|0\n          let placed = false\n          if(B[k][3] && !placed){\n            let ct=0, k2\n            do{\n              switch(Rn()*8|0){\n                case 0:\n                  tx=X-1\n                  ty=Y\n                break\n                case 1:\n                  tx=X-1\n                  ty=Y-1\n                break\n                case 2:\n                  tx=X\n                  ty=Y-1\n                break\n                case 3:\n                  tx=X+1\n                  ty=Y-1\n                break\n                case 4:\n                  tx=X+1\n                  ty=Y\n                break\n                case 5:\n                  tx=X+1\n                  ty=Y+1\n                break\n                case 6:\n                  tx=X\n                  ty=Y+1\n                break\n                case 7:\n                  tx=X-1\n                  ty=Y+1\n                break\n              }\n              if(tx>cl-1) tx=0\n              if(tx<0)    tx=cl-1\n              if(ty>rw-1) ty=0\n              if(ty<0)    ty=rw-1\n              k2 = cl*ty+tx\n              ct++\n              good = neighborless(k2)\n            }while(!placed && !good && ct<10);\n            if(good) B[k2][3]=1, placed = true, recurse(k2)\n          }\n        }\n\n        build=()=>{\n          B=JSON.parse(JSON.stringify(B__))\n          for(let j = 4;j--;){\n            B3=JSON.parse(JSON.stringify(B__))\n            let len\n            do{\n              let seed = Rn()*rw*cl|0\n              if(neighborless(seed)){\n                B[seed][3] = 1\n                recurse(seed)\n              }\n              len = B.filter(v=>v[3]).length\n            }while(len<tgt);\n            B2=JSON.parse(JSON.stringify(B))\n            B=B3\n            len=0\n            do{\n              let seed = Rn()*rw*cl|0\n              if(neighborless(seed)){\n                B[seed][3] = 1\n                recurse(seed)\n              }\n              len = B.filter(v=>v[3]).length\n            }while(len<tgt);\n            B.map((v,i)=>{\n              if(B2[i][3]) v[3]=1\n            })\n          }\n        }\n        build()\n\n\n        setItOff = () => {\n          startMode = Rn() < .75 ? \'single\' : \'random\'\n          rpts = 25\n          switch(startMode){\n            case \'single\':\n              (l=B.filter(v=>v[3]))[l.length*Rn()|0][3]=2\n            break\n            case \'random\':\n              for(let i=rpts;i--;) (l=B.filter(v=>v[3]))[l.length*Rn()|0][3]=2\n            break\n          }\n        }\n        setItOff()\n\n        process=()=>{\n          B_=JSON.parse(JSON.stringify(B))\n          B.map((v,i)=>{\n            if(v[3]==1){\n              let X = i%cl\n              let Y = i/cl|0\n              for(let l=8;l--;){\n                switch(l){\n                  case 0:\n                    tx=X-1\n                    ty=Y\n                  break\n                  case 1:\n                    tx=X-1\n                    ty=Y-1\n                  break\n                  case 2:\n                    tx=X\n                    ty=Y-1\n                  break\n                  case 3:\n                    tx=X+1\n                    ty=Y-1\n                  break\n                  case 4:\n                    tx=X+1\n                    ty=Y\n                  break\n                  case 5:\n                    tx=X+1\n                    ty=Y+1\n                  break\n                  case 6:\n                    tx=X\n                    ty=Y+1\n                  break\n                  case 7:\n                    tx=X-1\n                    ty=Y+1\n                  break\n                }\n                if(tx>cl-1) tx=0\n                if(tx<0)    tx=cl-1\n                if(ty>rw-1) ty=0\n                if(ty<0)    ty=rw-1\n                let k2 = cl*ty+tx\n                if(B_[k2][3]==2 && Math.abs(X-tx)<=1 && Math.abs(Y-ty)<=1) v[3]=2\n              }\n            }\n            if(B_[i][3]==3) v[3]=1\n            if(B_[i][3]==2) v[3]=3\n          })\n        }\n      }\n\n      if(1||go){\n        x.globalAlpha = .15\n        x.drawImage(bgvid,0,0,c.width,c.height)\n        x.globalAlpha = 1\n        x.fillStyle=\'#0008\'\n        x.fillRect(0,0,c.width,c.height)\n        oX=oY=0, oZ=14+S(t)*4\n        Rl=S(t/2)*2,Pt=Math.max(-.15,Math.min(.15,C(t))),Yw=Math.max(-.15,Math.min(.15,S(t)))\n\n        if(!((t*60|0)%(60*10))) build()\n        if(!((t*60|0)%16)) setItOff()\n        if(!((t*60|0)%1)) for(m=1;m--;)process()\n\n        ls=2**.5*sp/2\n        for(let n=1;n--;) B.map(v=>{\n          tx=v[0]\n          ty=v[1]\n          tz=v[2]+n/6\n          x.beginPath()\n          for(i=4;i--;){\n            X=tx+S(p=Math.PI*2/4*i+Math.PI/4)*ls\n            Y=ty+C(p)*ls\n            Z=tz\n            R(Rl,Pt,Yw,1)\n            if(Z>0)x.lineTo(...Q())\n          }\n          let col = \'\'\n          switch(v[3]){\n            case 1: col = \'#6664\'; break\n            case 2: col = \'#0ff\'; break\n            case 3: col = \'#80f\'; break\n          }\n          stroke(\'\', col)\n        })\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'wires', 145, 'whitehot robot', '2022-10-19 15:39:10', '[600422,600373,600347,600253,600252,600251,600248,600247]', 71, '', 0, 0),
