         Y=600+(Rn()-.5)*800\n            ls=20//5+Rn()*100\n            P.map(q=>{\n              if(!good) return\n              tx=q[0]\n              ty=q[1]\n              d=Math.hypot(tx-X,ty-Y)\n              if(d<q[2]+ls) good=false\n            })\n            ct++\n          }while(!good&&ct<2000);\n          if(good) P=[...P, [X,Y,ls]]\n        }while(ct<2000);\n      }\n\n      x.fillStyle=\'#fff8\'\n      x.fillRect(0,0,c.width,c.height)\n      oX=oY=0, oZ=5\n      Rl=0,Pt=0,Yw=0\n\n      x.beginPath()\n      x.lineTo(960,0)\n      x.lineTo(960,1080)\n      x.lineWidth=9\n      x.stroke()\n\n      x.font=\"64px courier\"\n      x.fillStyle=\'#000\'\n      x.fillText(\'classic circle packing\',50,60)\n\n      x.font=\"64px courier\"\n      x.fillStyle=\'#000\'\n      x.fillText(\'min-dist packing\',960+150,60)\n\n      B.map(v=>{\n        X=v[0]\n        Y=v[1]\n        x.beginPath()\n        x.arc(X,Y,v[2],0,7)\n        x.stroke()\n      })\n\n      P.map(v=>{\n        X=v[0]\n        Y=v[1]\n        x.beginPath()\n        x.arc(X,Y,v[2],0,7)\n        x.stroke()\n      })\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'circle packing vs vertex-spacing', 145, 'whitehot robot', '2022-10-20 18:04:05', '[600422,600373,600347,600253,600252,600251,600248,600247]', 53, '', 0, 0),
