neTo(X,Y)\n        X=960\n        Y=540+(i+1)*s\n        x.lineTo(X,Y)\n        x.strokeStyle=\'#000\'\n        x.stroke()\n      }\n\n      x.font=\'100px courier\'\n      x.fillText(\'y\',880,80)\n      x.fillText(\'x\',1400,620)\n\n      x.beginPath()\n      x.lineTo(X=960,Y=540)\n      for(i=0;i<Math.min((t*6|0)%20,13);++i){\n        nx =  (i+2)%4?1:-1\n        ny =  (i+5)%4?1:-1\n        mx =  (i+1)%2\n        my =  i%2\n        p  =  1+(i/2|0)\n        tx =  X  +=  p*mx*nx*s\n        ty =  Y  -=  p*my*ny*s\n        x.lineTo(X,Y)\n      }\n      x.lineWidth=12\n      x.strokeStyle=\'#f00\'\n      x.stroke()\n\n      if((t*6|0)%20>=13){\n        x.beginPath()\n        p=-Math.PI/4\n        X=tx+S(p)*s/2\n        Y=ty+C(p)*s/2\n        x.beginPath()\n        x.lineTo(tx, ty)\n        x.lineTo(X, Y)\n        x.stroke()\n        x.beginPath()\n        p=-Math.PI/4\n        X=tx+S(p)*s/2\n        Y=ty-C(p)*s/2\n        x.lineTo(tx, ty)\n        x.lineTo(X, Y)\n        x.stroke()\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'math problem', 145, 'whitehot robot', '2022-10-22 19:01:06', '[600422,600373,600347,600253,600252,600251,600248,600247]', 59, '', 0, 0),
