(600467, 'https://srmcgann.github.io/assets/BWOn5.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/JJkEM.gif);\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: contain;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'ike dithered (gif)', 145, 'whitehot robot', '2022-10-23 00:40:23', '[600466,600463,600462,600461,600454,600453,600450,600448,600447,600445,600442,600441,600440,600439,600438,600435,600427,600420,600419,600417,600414,600412,600403,600401,600399,600391,600390,600385,600380,600367,600366,600364,600363,600360,600359,600358,600357,600356,600355,600354,600353,600288,600253,600252,600251,600248,600247]', 75, 'https://code.dweet.net/thumbs/35d477510955d04908a2a028e2a39e37.jpg', 0, 0),
(600468, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    R = function(r,g,b,a) {\n      a = a === undefined ? 1 : a;\n      return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n    };\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n        }\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n        stroke=(scol,fcol)=>{\n          if(scol){\n            x.closePath()\n            x.lineWidth=Math.min(500, 500/Z)\n            x.globalAlpha=.2\n            x.strokeStyle=scol\n            x.stroke()\n            x.globalAlpha=1\n            x.lineWidth/=5\n            x.stroke()\n          }\n          if(fcol){\n            x.fillStyle=fcol\n            x.fill()\n          }\n        }\n        spawnBoard=()=>{\n          stage = gameover = 0\n          begCol=-1\n          sp=2, mx=my=turn=0\n          B=Array(100).fill().map((v,i)=>{\n            X=((i%10)-5+.5)*sp\n            Y=((i/10|0)-5+.5)*sp\n            Z=0\n            return [X,Y,Z,i]\n          })\n\n          P=Array(122).fill().map((v,i)=>{\n            ret = -1\n            if(i>0&&(i<121)&&(i%2)){\n              val = (((i+(i/11|0))|0))%2?3:2\n              ret = val\n            }\n            return ret\n          })\n        }\n\n        c.onmousedown=e=>{\n          switch(stage){\n            case 0:\n              if(!gameover && e.button==0 && begCol != -1){\n                turn=begCol\n                stage++\n              }\n            break\n            case 1:\n              if(e.button==0){\n                if(gameover) spawnBoard()\n                if(P[tgt_]==-1){\n                  turn=(turn+1)%2\n                  P[tgt_]=turn\n                }\n              }\n          }\n        }\n        c.onmousemove=e=>{\n          let rect = c.getBoundingClientRect()\n          mx=(e.pageX-rect.left)/c.clientWidth*c.width\n          my=(e.pageY-rect.top)/c.clientHeight*c.height\n        }\n        bgimg = new Image()\n        bgimg.onload=()=>{\n          go=true\n          spawnBoard()\n        }\n        //bgimg.src=\'/proxy.php?url=https://srmcgann.github.io/assets/1s3j4w.jpg\'\n        bgimg.src=\'/proxy.php?url=https://srmcgann.github.io/assets/1NWwfr.jpg\'\n      }\n\n      if(go){\n        x.globalAlpha=.2\n        x.drawImage(bgimg,0,0,c.width,c.height)\n        x.globalAlpha=1\n        x.fillStyle=\'#0004\'\n        x.fillRect(0,0,c.width,c.height)\n        x.lineCap=x.lineJoin=\'round\'\n        oX=oY=0, oZ=20\n        Rl=0\n        Pt=gameover?C(t/2)*10:0\n        Yw=gameover?S(t/2)*10:0\n\n        B.map(v=>{\n          tx=v[0]\n          ty=v[1]\n          tz=v[2]\n          ls=sp*(2**.5/2)\n          x.beginPath()\n          for(i=4;i--;){\n            X=tx+S(p=Math.PI*2/4*i+Math.PI/4)*ls\n            Y=ty+C(p)*ls\n            Z=tz\n            R(Rl,Pt,Yw,1)\n            if(Z>0) x.lineTo(...Q())\n          }\n          stroke(\'#fff2\',\'4f86\')\n        })\n\n        for(i=110;i--;){\n          if(i%10<9&&!(i%2)&&!((i/10|0)%2)){\n            X=((i%10)-5+.5)*sp+sp/2\n            Y=((i/10|0)-5+.5)*sp-sp/2\n            Z=0\n            x.beginPath()\n            R(Rl,Pt,Yw,1)\n            s=Math.min(500, 300/Z)\n            x.arc(...Q(),s,0,7)\n            x.fillStyle=\'#f00\'\n            x.fill()\n\n            X=((i/10|0)-5+.5)*sp-sp/2\n            Y=((i%10)-5+.5)*sp+sp/2\n            Z=0\n            x.beginPath()\n            R(Rl,Pt,Yw,1)\n            s=Math.min(500, 300/Z)\n            x.arc(...Q(),s,0,7)\n            x.fillStyle=\'#08F\'\n            x.fill()\n          }\n        }\n        l=2**.5*5*sp*1.01\n        for(i=4;i--;){\n          x.beginPath()\n          x.lineWidth=Math.min(500, 600/Z)\n          x.strokeStyle=i%2?\'#f008\':\'#08F8\'\n          X=S(p=Math.PI*2/4*i+Math.PI/4)*l\n          Y=C(p)*l\n          Z=0\n          R(Rl,Pt,Yw,1)\n          x.lineTo(...Q())\n          X=S(p=Math.PI*2/4*(i+1)+Math.PI/4)*l\n          Y=C(p)*l\n          Z=0\n          R(Rl,Pt,Yw,1)\n          x.lineTo(...Q())\n          x.stroke()\n          x.lineWidth/=3\n          x.strokeStyle=i%2?\'#f00\':\'#08F\'\n          x.stroke()\n        }\n        switch(stage){\n          case 0:\n            l_=[]\n            x.font=\'90px courier\'\n            x.textAlign=\'center\'\n            x.fillStyle=\'#fff\'\n            x.fillText(\'choose a color to go first\',960,70)\n            x.beginPath()\n            X=-16, Y=0, Z=0\n            R(Rl,Pt,Yw,1)\n            s=Math.min(500, 2e3/Z)\n            x.arc(...(l_[0]=Q()),s,0,7)\n            x.fillStyle=\'#f00\'\n            x.fill()\n            x.strokeStyle=\'#fff8\'\n            ga=t*200%200\n            x.beginPath()\n            x.arc(...Q(),s+ga,0,7)\n            x.globalAlpha=1/(1+ga**3/99999)\n            x.lineWidth=Math.min(500,500/Z)\n            x.stroke()\n            X=16, Y=0, Z=0\n            R(Rl,Pt,Yw,1)\n            x.beginPath()\n            x.arc(...Q(),s+ga,0,7)\n            x.globalAlpha=1/(1+ga**3/99999)\n            x.lineWidth=Math.min(500,500/Z)\n            x.stroke()\n            x.globalAlpha=1\n            x.beginPath()\n            s=Math.min(500, 2e3/Z)\n            x.arc(...(l_[1]=Q()),s,0,7)\n            x.fillStyle=\'#08f\'\n            x.fill()\n            \n            for(let m=2;m--;){\n              v=l_[m]\n              d=Math.hypot(v[0]-mx,v[1]-my)\n              if(d<200){\n                begCol=m\n                x.beginPath()\n                x.strokeStyle=\'#4ff8\'\n                s=120\n                x.arc(...v,s,0,7)\n                x.lineWidth=1e3/Z\n                x.stroke()\n              }\n            }\n          break\n          case 1:\n            tgt_=-1\n            for(i=122;i--;){\n              if((!(i%2))&&((i/11|0)>0)&&(i%11!==10)&&(i%11)&&((i/11|0)<10)){\n                X=((i%11)-5.5+.5)*sp\n                Y=((i/11|0)-5.5+.5)*sp\n                Z=0\n                R(Rl,Pt,Yw,1)\n                tgt=Q()\n                d=Math.hypot(tgt[0]-mx,tgt[1]-my)\n                if(d<sp*25){\n                  x.beginPath()\n                  s=Math.min(500, 500/Z)\n                  x.arc(...Q(),s,0,7)\n                  x.fillStyle=\'#0f0\'\n                  if(P[i]==-1)x.fill()\n                  tgt_=i\n                }\n              }\n            }\n            P.map((v,i)=>{\n              if(v!=-1&&v<2){\n                if((v&&((i/11|0)%2))||(!v&&(!((i/11|0)%2)))){\n                  x.fillStyle=v?\'#f008\':\'#08fa\'\n                  X=((i%11)-5.5+.5)*sp\n                  Y=((i/11|0)-5.5+.5)*sp\n                  Z=0\n                  R(Rl,Pt,Yw,1)\n                  x.beginPath()\n                  s=Math.min(500,750/Z)\n                  x.arc(...Q(),s,0,7)\n                  x.fill()\n                  x.beginPath()\n                  X=((i%11)-5.5+.5)*sp\n                  Y=((i/11|0)-5.5+.5)*sp-sp\n                  Z=0\n                  R(Rl,Pt,Yw,1)\n                  x.lineTo(...Q())\n                  X=((i%11)-5.5+.5)*sp\n                  Y=((i/11|0)-5.5+.5)*sp+sp\n                  Z=0\n                  R(Rl,Pt,Yw,1)\n                  x.lineTo(...Q())\n                  x.lineWidth=Math.min(500,500/Z)\n                  x.strokeStyle=v?\'#f44c\':\'#48fc\'\n                  x.stroke()\n                }else{\n                  x.fillStyle=v?\'#f008\':\'#08fa\'\n                  X=((i%11)-5.5+.5)*sp\n                  Y=((i/11|0)-5.5+.5)*sp\n                  Z=0\n                  R(Rl,Pt,Yw,1)\n                  x.beginPath()\n                  s=Math.min(500,750/Z)\n                  x.arc(...Q(),s,0,7)\n                  x.fill()\n                  x.beginPath()\n                  X=((i%11)-5.5+.5)*sp-sp\n                  Y=((i/11|0)-5.5+.5)*sp\n                  Z=0\n                  R(Rl,Pt,Yw,1)\n                  x.lineTo(...Q())\n                  X=((i%11)-5.5+.5)*sp+sp\n                  Y=((i/11|0)-5.5+.5)*sp\n                  Z=0\n                  R(Rl,Pt,Yw,1)\n                  x.lineTo(...Q())\n                  x.lineWidth=Math.min(500,500/Z)\n                  x.strokeStyle=v?\'#f44c\':\'#48fc\'\n                  x.stroke()\n                }\n              }\n            })\n            recursered=(idx)=>{\n              if(P[idx]!==1 && P[idx]!=3) return\n              if(idx>120 || idx<1) return\n              if(memo[idx]) return\n              if(idx>100){\n                good = true\n                return\n              }\n              memo[idx]=true\n              let X=idx%11\n              let Y=idx/11|0\n              recursered(idx+1)\n              recursered(idx-1)\n              recursered(idx+11)\n              recursered(idx-11)\n            }\n            for(let j=5;j--;){\n              good=false\n              memo=Array(122).fill(false)\n              recursered(1+j*2,0)\n              if(good) gameover=true, victor=1\n            }\n\n            //check blue victory\n            recurseblue=(idx)=>{\n              if(P[idx]!==0 && P[idx]!=2) return\n              if(idx>120 || idx<1) return\n              if(memo[idx]) return\n              if(idx%11==10){\n                good = true\n                return\n              }\n              memo[idx]=true\n              let X=idx%11\n              let Y=idx/11|0\n              recurseblue(idx+1)\n              recurseblue(idx-1)\n              recurseblue(idx+11)\n              recurseblue(idx-11)\n            }\n            for(let j=5;j--;){\n              good=false\n              memo=Array(122).fill(false)\n              recurseblue(11+11*j*2,0)\n              if(good) gameover=true, victor=0\n            }\n            if(!gameover){\n              x.font=\'90px courier\'\n              x.textAlign=\'center\'\n              x.fillStyle=turn?\'#08f\':\'#f00\'\n              x.fillText((turn?\'blue\':\'red\')+\'\\\'s\'+\' turn\',960,80)\n            } else {\n              x.globalAlpha=1\n              x.font=\'200px courier\'\n              x.textAlign=\'center\'\n              x.fillStyle=!victor?\'#08f\':\'#f00\'\n              x.strokeStyle=!victor?\'#8cf8\':\'#faa8\'\n              x.lineWidth=20\n              x.strokeText((!victor?\'blue\':\'red\')+\' WON!\',960,500)\n              x.fillText((!victor?\'blue\':\'red\')+\' WON!\',960,500)\n              x.fillStyle=\'#fff\'\n              x.font=\'120px courier\'\n              x.fillText(\'click to play again...\',960,640)\n            }\n          break\n        }\n      } else {\n        x.fillStyle=\'#0008\'\n        x.fillRect(0,0,c.width,c.height)\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'side to side', 145, 'whitehot robot', '2022-10-23 01:04:23', '[600422,600373,600347,600253,600252,600251,600248,600247]', 81, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600469, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    R = function(r,g,b,a) {\n      a = a === undefined ? 1 : a;\n      return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n    }\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        bg=new Image()\n        bg.src=\'/proxy.php?url=https://srmcgann.github.io/assets/1p7iM4.jpg\' \n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n          stroke=(scol, fcol)=>{\n            if(scol){\n              x.closePath()\n              x.strokeStyle=scol\n              x.globalAlpha=.2\n              x.lineWidth=Math.min(500,100/Z)\n              x.stroke()\n              x.globalAlpha=1\n              x.lineWidth/=3\n              x.stroke()\n            }\n            if(fcol){\n              x.fillStyle=fcol\n              x.fill()\n            }\n          }\n        }\n        Q=()=>[c.width/2+450+X/Z*800,c.height/2+Y/Z*800]\n        Q_=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n        window.onmousemove=e=>{\n          let rect = c.getBoundingClientRect()\n          mx=(e.pageX-rect.left)/c.clientWidth*c.width\n          my=(e.pageY-rect.top)/c.clientHeight*c.height\n        }\n\n        swapping = false\n        doSwapAnimation=(a,b)=>{\n          swapping=true\n          sourceP=JSON.parse(JSON.stringify(P))\n          let tx = a[0]\n          let ty = a[1]\n          a[0]=b[0]\n          a[1]=b[1]\n          b[0]=tx\n          b[1]=ty\n          destP=JSON.parse(JSON.stringify(P))\n        }\n\n        doSwapWithEmptyCellAnimation=(P_,i)=>{\n      \n          X1=X=((i%cl)-cl/2+.5)*sp\n          Y1=Y=(((i/cl|0)%rw)-rw/2+.5)*sp\n          Z1=Z=0\n          R(Rl,Pt,Yw,1)\n          tx1=X,ty1=Y,tz1=Z\n\n          X2=X=P_[0]\n          Y2=Y=P_[1]\n          Z2=Z=P_[2]\n          R(Rl,Pt,Yw,1)\n          tx2=X,ty2=Y,tz2=Z\n\n          d=Math.hypot(tx1-tx2,ty1-ty2)\n          if(d<1.5){\n            P_[0]  = X1\n            P_[1]  = Y1\n            P_[2]  = Z1\n            P_[7]  = i\n            P_[8]  = 0\n          }\n        }\n\n        settled = true\n        grav=.01, tgt_ls=400\n\n        dropPieces=()=>{\n          settled = true\n          P.map(v=>{\n            let idx   = v[7]\n            let cbidx = idx+8\n            if(cbidx<64){\n              if(P.filter(v=>v[7]==cbidx).length){\n                v[5]=0\n                v[1]=((v[7]/8|0)-4+.5)*sp\n              }else{\n                settled = false\n                v[5] += grav\n              }\n            }else{\n              v[5]=0\n              v[1]=((v[7]/8|0)-4+.5)*sp\n            }\n          })\n          for(i=8;i--;){\n            if(!P.filter(v=>v[7]==i).length){\n              X=((i%cl)-cl/2+.5)*sp\n              Y=(((i/cl|0)%rw)-rw/2+.5)*sp\n              Z=0\n              P=[...P, spawnP(X,Y,Z,i)]\n            }\n          }\n        }\n\n        checkBoard=()=>{\n          if(!settled || swapping) return\n          P.map(v=>{\n            v[10]=0\n          })\n          for(let j=0;j<8;j++){\n            good=true\n            ct=0\n            idxs=[]\n            for(let i=0;i<8;i++){\n              idx=i*8+j\n              let cellid = !(l=P.filter(v=>v[7]==idx)).length?-1:l[0][3]\n              if(i && ocv==cellid){\n                ct++\n              }else{\n                if(ct>1){\n                  idxs.map(v=>{\n                    P.map((q,j)=>{\n                      if(q[7]==v[0])q[10]=1, score+=scorIncr\n                    })\n                  })\n                }\n                ct=0\n                idxs=[]\n              }\n              idxs=[...idxs, [idx, cellid]]\n              ocv = cellid\n            }\n            if(ct>1){\n              idxs.map(v=>{\n                P.map((q,j)=>{\n                  if(q[7]==v[0])q[10]=1\n                })\n              })\n            }\n          }\n\n\n          for(let i=0;i<8;i++){\n            good=true\n            ct=0\n            idxs=[]\n            for(let j=0;j<8;j++){\n              idx=i*8+j\n              let cellid = !(l=P.filter(v=>v[7]==idx)).length?-1:l[0][3]\n              if(j && ocv==cellid){\n                ct++\n              }else{\n                if(ct>1){\n                  idxs.map(v=>{\n                    P.map((q,j)=>{\n                      if(q[7]==v[0])q[10]=1, score+=scorIncr\n                    })\n                  })\n                }\n                ct=0\n                idxs=[]\n              }\n              idxs=[...idxs, [idx, cellid]]\n              ocv = cellid\n            }\n            if(ct>1){\n              idxs.map(v=>{\n                P.map((q,j)=>{\n                  if(q[7]==v[0])q[10]=1, score+=scorIncr\n                })\n              })\n            }\n          }\n        }\n\n        processSelection = () =>{\n          Array(rw*cl).fill().map((v,i)=>{\n            X=((i%cl)-cl/2+.5)*sp\n            Y=(((i/cl|0)%rw)-rw/2+.5)*sp\n            Z=0\n            R(Rl,Pt,Yw,1)\n            l=Q()\n            d=Math.hypot(l[0]-mx,l[1]-my)\n            if(d<tgt_ls/Z){\n              occupied=false\n              P.map((q,j)=>{\n                swapped=false\n                if(q[7]==i){\n                  occupied=true\n                  switch(q[8]){\n                    case 0:\n                      P.map((n,m)=>{\n                        if(n[8]&&m!=j){\n                          X1=q[7]%8\n                          Y1=q[7]/8|0\n                          X2=n[7]%8\n                          Y2=n[7]/8|0\n                          d=Math.hypot(X1-X2,Y1-Y2)\n                          if(d<1.1){\n                            swapped=true\n                            doSwapAnimation(n,q)\n                            n[8]=q[8]=n[9]=q[9]=0\n                          }\n                        }\n                      })\n                      if(!swapped){\n                        q[8]++\n                        q[8]%=2\n                      }\n                    break\n                    case 1:\n                      q[8]=0\n                    break\n                  }\n                }\n              })\n              if(!occupied){\n                if(P.filter(v=>v[8]).length){\n                  P.map(q=>{\n                    if(q[8]) doSwapWithEmptyCellAnimation(q,i)\n                  })\n                }\n              }\n            } else {\n              if(P.filter(v=>v[8]).length>1) P.map(v=>v[8]=0)\n            }\n          })\n        }\n\n        settled = true\n        window.onmousedown=e=>{\n          if(e.button==0 && settled && !swapping){\n            let rect = c.getBoundingClientRect()\n            mx=(e.pageX-rect.left)/c.clientWidth*c.width\n            my=(e.pageY-rect.top)/c.clientHeight*c.height\n            processSelection()\n          }\n        }\n\n        rw=cl=8,sp=1,mx=my=0\n\n        go=false\n        tiles=Array(8).fill().map((v,i)=>{\n          let img = {img: new Image(), loaded: false}\n          img.img.onload=()=>{\n            img.loaded=true\n            if(tiles.filter(v=>v.loaded).length==8) go=true\n          }\n          img.img.src=\'/proxy.php?url=https://whitehot.ninja/symbols/\'+(i+1)+\'.png\'\n          return img\n        })\n        spawnP = (X,Y,Z,i) => {\n          return [X,Y,Z,Rn()*7|0,0,0,0,i,0,0,0]\n        }\n        SP=[], iSPv=.1, iSPs=100, iSPc=200\n        spawnSplosion = (X,Y,Z) => {\n          a=Array(iSPc).fill().map(v=>{\n            return [X,Y,Z,(Rn()-.5)*iSPv,(Rn()-.5)*iSPv,(Rn()-.5)*iSPv,iSPs]\n          })\n          SP=[...SP, ...a]\n        }\n        getCellIdx=v=>{\n          let X=(v[0]+cl/2)|0\n          let Y=(v[1]-.5+rw/2)|0\n          return Y*cl+X\n        }\n\n        scorIncr = 8**2\n        init = () => {\n          score = 0\n          P=Array(64).fill().map((v,i)=>{\n            X=(i%8-4+.5)*sp\n            Y=((i/8|0)-4+.5)*sp\n            Z=0\n            return spawnP(X,Y,Z,i)\n          })\n        }\n        init()\n      }\n\n      if(go){\n        x.globalAlpha=.5\n        x.drawImage(bg,0,0,c.width,c.height)\n        x.fillStyle=\'#0001\'\n        x.globalAlpha=1\n        x.fillRect(0,0,c.width,c.height)\n        oX=oY=0, oZ=7\n        Rl=0,Pt=C(t/2)/8,Yw=S(t/2)/8\n\n        B=Array(rw*cl).fill().map((v,i)=>{\n          tx=X=((i%cl)-cl/2+.5)*sp\n          ty=Y=(((i/cl|0)%rw)-rw/2+.5)*sp\n          tz=Z=0\n          R(Rl,Pt,Yw,1)\n          l=Q()\n          d=Math.hypot(l[0]-mx,l[1]-my)\n          let hover = d<tgt_ls/Z\n          let state\n          P.map((q,j)=>{\n            if(q[7]==i){\n              state = q[8]\n              q[9]=hover\n            }\n          })\n          return [tx, ty, tz, hover, state]\n        })\n\n        B.map(v=>{\n          tx=v[0]\n          ty=v[1]\n          tz=v[2]\n          ls=2**.5/2*sp/1.05\n          x.beginPath()\n          for(i=4;i--;){\n            X=tx+S(p=Math.PI*2/4*i+Math.PI/4)*ls\n            Y=ty+C(p)*ls\n            Z=tz\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n          }\n          stroke(\'#fff2\',\'\')\n          x.beginPath()\n          ls/=1.05\n          for(i=4;i--;){\n            X=tx+S(p=Math.PI*2/4*i+Math.PI/4)*ls\n            Y=ty+C(p)*ls\n            Z=tz\n            R(Rl,Pt,Yw,1)\n            l=Q()\n            x.lineTo(l[0]-3,l[1]-3)\n          }\n          stroke(\'\',(v[3]||v[4])?\'#888\':\'#222\')\n        })\n\n        if(swapping){\n          swapping = false\n          sourceP.map((v,i)=>{\n            if(\n              (d=Math.hypot(v[0]-destP[i][0],v[1]-destP[i][1]))>.1\n            ){\n              swapping = true\n            }\n            X=tx=v[0]+=(destP[i][0]-v[0])/5\n            Y=ty=v[1]+=(destP[i][1]-v[1])/5\n            Z=tz=v[2]+=(destP[i][2]-v[2])/5\n            R(Rl,Pt,Yw,1)\n            if(Z>0){\n              s=700/Z\n              l=Q()\n              x.globalCompositeOperation=\'source-over\'\n              x.drawImage(tiles[v[3]].img,l[0]-s/2,l[1]-s/2,s,s)\n              x.globalCompositeOperation=\'multiply\'\n              ls=2**.5/2*sp/1.1\n              x.beginPath()\n              for(let i=4;i--;){\n                X=tx+S(p=Math.PI*2/4*i+Math.PI/4)*ls\n                Y=ty+C(p)*ls\n                Z=tz\n                R(Rl,Pt,Yw,1)\n                x.lineTo(...Q())\n              }\n              switch(v[8]){\n                case 0:\n                  bcol = v[9]?\'#0f0\':(v[10]?`#f00`:`hsla(${360/8*v[3]+45*4-0},99%,65%,.8)`)\n                  fcol = ``\n                  break\n                case 1:\n                  bcol = `#fff`\n                  fcol = ``\n                  break\n                case 2:\n                  bcol = `#f00`\n                  fcol = ``\n                  break\n              }\n              stroke(fcol, bcol)\n            }\n          })\n          x.globalCompositeOperation=\'source-over\'\n        }else{\n\n          P.map(v=>{\n            X=tx=v[0]+=v[4]\n            Y=ty=v[1]+=v[5]\n            Z=tz=v[2]+=v[6]\n            v[7] = getCellIdx(v)\n            let hover = B[v[7]][3]\n            R(Rl,Pt,Yw,1)\n            if(Z>0){\n              s=700/Z\n              l=Q()\n              x.globalCompositeOperation=\'source-over\'\n              x.drawImage(tiles[v[3]].img,l[0]-s/2,l[1]-s/2,s,s)\n              x.globalCompositeOperation=\'multiply\'\n              ls=2**.5/2*sp/1.1\n              x.beginPath()\n              for(let i=4;i--;){\n                X=tx+S(p=Math.PI*2/4*i+Math.PI/4)*ls\n                Y=ty+C(p)*ls\n                Z=tz\n                R(Rl,Pt,Yw,1)\n                x.lineTo(...Q())\n              }\n              switch(v[8]){\n                case 0:\n                  bcol = v[9]?\'#0f0\':(v[10]?`#f00`:`hsla(${360/8*v[3]+45*4-0},99%,65%,.8)`)\n                  fcol = ``\n                  break\n                case 1:\n                  bcol = `#fff`\n                  fcol = ``\n                  break\n                case 2:\n                  bcol = `#f00`\n                  fcol = ``\n                  break\n              }\n              stroke(fcol, bcol)\n            }\n            if(v[10]){\n              spawnSplosion(tx,ty,tz)\n            }\n          })\n          P=P.filter(v=>!v[10])\n          x.globalCompositeOperation=\'source-over\'\n          dropPieces()\n          checkBoard()\n          \n          SP.map(v=>{\n            X=v[0]+=v[3]\n            Y=v[1]+=v[4]\n            Z=v[2]+=v[5]\n            R(Rl,Pt,Yw,1)\n            v[6]-=2\n            if(Z>0){\n              l=Q()\n              x.globalAlpha=(1/iSPs*v[6])\n              x.fillStyle=\'#fff2\'\n              s=Math.min(500, 5*(iSPs-v[6])/Z)\n              x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n              x.fillStyle=\'#fff\'\n              s/=4\n              x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n            }\n          })\n          x.globalAlpha=1 \n          SP=SP.filter(v=>v[6]>0)\n        }\n        x.textAlign=\'left\'\n        x.font = \'130px courier\'\n        x.fillStyle=\'#fff\'\n        x.fillText(\'BEJEMMED!\',10,100)\n\n        x.font = \'75px courier\'\n        x.fillStyle=\'#fff\'\n        x.fillText(\'get 3 or more\',10,200)\n        x.fillText(\'in a row\',10,275)\n\n        x.font = \'120px courier\'\n        x.fillStyle=\'#fff\'\n        x.fillText(\'score\',10,500)\n        x.font = \'120px courier\'\n        x.fillStyle=\'#0fa\'\n        x.fillText(score.toLocaleString(\"en-US\"),10,600)\n      }else{\n        x.textAlign=\'center\'\n        x.font = \'130px courier\'\n        x.fillStyle=\'#fff\'\n        x.fillText(\'BEJEMMED!\',960/2,100)\n        x.textAlign=\'center\'\n        x.font = \'130px courier\'\n        x.fillStyle=\'#fff\'\n        x.fillText(\'loading...\',960/2,300)\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'bejemmed!', 145, 'whitehot robot', '2022-10-25 17:19:21', '[600422,600373,600347,600253,600252,600251,600248,600247]', 95, '', 0, 0),
(600470, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    R = function(r,g,b,a) {\n      a = a === undefined ? 1 : a;\n      return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n    };\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        go=false\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n        }\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n        bg = document.createElement(\'video\')\n        bg.oncanplay=()=>{\n          go=true\n          bg.play()\n        }\n        bg.muted=true\n        bg.loop = true\n        bg.src=\'/proxy.php?url=https://twilightparadox.com/rds_final.mp4\'\n      }\n\n      if(go){\n        //.fillStyle=\'#0008\'\n        //x.fillRect(0,0,c.width,c.height)\n        x.clearRect(0,0,c.width,c.height)\n        x.globalCompositeOperation=\'difference\'\n        vw=bg.videoWidth\n        vh=bg.videoHeight\n        for(j=10;--j;){\n          cl=j\n          sp=c.width/cl\n          rw=(1+cl/1.77777778)|0\n          for(i=cl*rw;i--;){\n            X=960+((i%cl)-cl/2+.5)*sp\n            Y=540+((i/cl|0)-rw/2+.5)*sp\n            x.drawImage(bg,X-sp/2,Y-sp/2,sp,sp)\n          }\n        }\n        x.globalCompositeOperation=\'source-over\'\n      }\n       \n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'madprops animation', 145, 'whitehot robot', '2022-10-27 02:20:19', '[600422,600373,600347,600253,600252,600251,600248,600247]', 61, '', 0, 0),
(600471, 'https://srmcgann.github.io/assets/29cxK3.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/XpsUz.gif);\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: contain;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'madprops final (gif)', 145, 'whitehot robot', '2022-10-27 03:28:05', '[600467,600466,600463,600462,600461,600454,600453,600450,600448,600447,600445,600442,600441,600440,600439,600438,600435,600427,600420,600419,600417,600414,600