(600473, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.lineWidth=Math.min(500, 500/Z)\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=5\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n    spawnBoard=()=>{\n      stage = gameover = 0\n      begCol=-1\n      sp=2, mx=my=turn=0\n      B=Array(100).fill().map((v,i)=>{\n        X=((i%10)-5+.5)*sp\n        Y=((i/10|0)-5+.5)*sp\n        Z=0\n        return [X,Y,Z,i]\n      })\n\n      P=Array(122).fill().map((v,i)=>{\n        ret = -1\n        if(i>0&&(i<121)&&(i%2)){\n          val = (((i+(i/11|0))|0))%2?3:2\n          ret = val\n        }\n        return ret\n      })\n    }\n\n    c.onmousedown=e=>{\n      switch(stage){\n        case 0:\n          if(!gameover && e.button==0 && begCol != -1){\n            turn=begCol\n            stage++\n          }\n        break\n        case 1:\n          if(e.button==0){\n            if(gameover) spawnBoard()\n            if(P[tgt_]==-1){\n              turn=(turn+1)%2\n              P[tgt_]=turn\n            }\n          }\n      }\n    }\n    c.onmousemove=e=>{\n      let rect = c.getBoundingClientRect()\n      mx=(e.pageX-rect.left)/c.clientWidth*c.width\n      my=(e.pageY-rect.top)/c.clientHeight*c.height\n    }\n    bgimg = new Image()\n    bgimg.onload=()=>{\n      go=true\n      spawnBoard()\n      hideSpinner()\n    }\n    //bgimg.src=\'/proxy.php?url=https://srmcgann.github.io/assets/1s3j4w.jpg\'\n    //bgimg.src=\'/proxy.php?url=https://srmcgann.github.io/assets/1NWwfr.jpg\'\n    bgimg.src=\'/proxy.php?url=https://srmcgann.github.io/assets/15Tw5B.jpg\'\n\n    showSpinner=()=>{\n      let el=document.querySelector(\'#spinner\')\n      if(el.classList.contains(\'hidden\')) el.classList.toggle(\"hidden\")\n    }\n\n    hideSpinner=()=>{\n      let el=document.querySelectorAll(\'#spinner\')[0]\n      if(!el.classList.contains(\'hidden\')) el.classList.toggle(\"hidden\")\n    }\n\n    doAIMove=()=>{\n      showSpinner()\n      setTimeout(()=>{\n        let moved = false\n        tgt_=-1\n\n        let maxDepth = 2\n        let victor=-1, tcell\n\n        forecast = (P, depth) => {\n          if(depth > maxDepth || victor != -1) return\n          for(let i=122;i--;){\n            if(victor==-1 && P[i]==-1 && (!(i%2))&&((i/11|0)>0)&&(i%11!==10)&&(i%11)&&((i/11|0)<10)){\n              let hP=JSON.parse(JSON.stringify(P))\n              hP[i]=turn\n              for(let j=5;j--;){\n                good=false\n                memo=Array(122).fill(false)\n                if(!begCol){\n                  recursepurple(1+j*2, hP)\n                }else{\n                  recursegreen(11+11*j*2, hP)\n                }\n                if(good) victor=!turn, tcell=i\n              }\n              if(victor==-1){\n                forecast(hP, depth+1)\n              }\n            }\n          }\n        }\n        forecast(P, 0)\n\n        // opponent is not 1 move away from victory\n        if(victor==-1){\n          let ct=0\n          do{\n            i=Rn()*122|0\n            if(!moved && P[i]==-1 && (!(i%2))&&((i/11|0)>0)&&(i%11!==10)&&(i%11)&&((i/11|0)<10)){\n              tgt_=i\n              moved = true\n            }\n            ct++\n          }while(!moved && ct<200);\n          if(P[tgt_]==-1){\n            turn=(turn+1)%2\n            P[tgt_]=turn\n          }\n        } else { // else block\n          turn=(turn+1)%2\n          P[tcell]=turn        \n        }\n        hideSpinner()\n      },0)\n    }\n  }\n\n  if(go){\n    x.globalAlpha=1\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#000a\'\n    x.fillRect(0,0,c.width,c.height)\n    x.lineCap=x.lineJoin=\'round\'\n    oX=oY=0, oZ=20\n    Rl=0\n    Pt=gameover?C(t/2)*10:0\n    Yw=gameover?S(t/2)*10:0\n\n    B.map(v=>{\n      tx=v[0]\n      ty=v[1]\n      tz=v[2]\n      ls=sp*(2**.5/2)\n      x.beginPath()\n      for(i=4;i--;){\n        X=tx+S(p=Math.PI*2/4*i+Math.PI/4)*ls\n        Y=ty+C(p)*ls\n        Z=tz\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n      }\n      stroke(\'#fff2\',\'\')\n    })\n\n    for(i=110;i--;){\n      if(i%10<9&&!(i%2)&&!((i/10|0)%2)){\n        X=((i%10)-5+.5)*sp+sp/2\n        Y=((i/10|0)-5+.5)*sp-sp/2\n        Z=0\n        x.beginPath()\n        R(Rl,Pt,Yw,1)\n        s=Math.min(500, 300/Z)\n        x.arc(...Q(),s,0,7)\n        x.fillStyle=\'#80f\'\n        x.fill()\n\n        X=((i/10|0)-5+.5)*sp-sp/2\n        Y=((i%10)-5+.5)*sp+sp/2\n        Z=0\n        x.beginPath()\n        R(Rl,Pt,Yw,1)\n        s=Math.min(500, 300/Z)\n        x.arc(...Q(),s,0,7)\n        x.fillStyle=\'#0f8\'\n        x.fill()\n      }\n    }\n    l=2**.5*5*sp*1.01\n    for(i=4;i--;){\n      x.beginPath()\n      x.lineWidth=Math.min(500, 600/Z)\n      x.strokeStyle=i%2?\'#80f8\':\'#0f88\'\n      X=S(p=Math.PI*2/4*i+Math.PI/4)*l\n      Y=C(p)*l\n      Z=0\n      R(Rl,Pt,Yw,1)\n      x.lineTo(...Q())\n      X=S(p=Math.PI*2/4*(i+1)+Math.PI/4)*l\n      Y=C(p)*l\n      Z=0\n      R(Rl,Pt,Yw,1)\n      x.lineTo(...Q())\n      x.stroke()\n      x.lineWidth/=3\n      x.strokeStyle=i%2?\'#80f\':\'#0f8\'\n      x.stroke()\n    }\n    switch(stage){\n      case 0:\n        l_=[]\n        x.font=\'90px courier\'\n        x.textAlign=\'center\'\n        x.fillStyle=\'#fff\'\n        x.fillText(\'choose a color to go first\',960,70)\n        x.beginPath()\n        X=-16, Y=0, Z=0\n        R(Rl,Pt,Yw,1)\n        s=Math.min(500, 2e3/Z)\n        x.arc(...(l_[0]=Q()),s,0,7)\n        x.fillStyle=\'#80f\'\n        x.fill()\n        x.strokeStyle=\'#fff8\'\n        ga=t*200%200\n        x.beginPath()\n        x.arc(...Q(),s+ga,0,7)\n        x.globalAlpha=1/(1+ga**3/99999)\n        x.lineWidth=Math.min(500,500/Z)\n        x.stroke()\n        X=16, Y=0, Z=0\n        R(Rl,Pt,Yw,1)\n        x.beginPath()\n        x.arc(...Q(),s+ga,0,7)\n        x.globalAlpha=1/(1+ga**3/99999)\n        x.lineWidth=Math.min(500,500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.beginPath()\n        s=Math.min(500, 2e3/Z)\n        x.arc(...(l_[1]=Q()),s,0,7)\n        x.fillStyle=\'#0f8\'\n        x.fill()\n        \n        for(let m=2;m--;){\n          v=l_[m]\n          d=Math.hypot(v[0]-mx,v[1]-my)\n          if(d<200){\n            begCol=m\n            x.beginPath()\n            x.strokeStyle=\'#0f8\'\n            s=120\n            x.arc(...v,s,0,7)\n            x.lineWidth=1e3/Z\n            x.stroke()\n          }\n        }\n      break\n      case 1:\n        tgt_=-1\n        for(i=122;i--;){\n          if((!(i%2))&&((i/11|0)>0)&&(i%11!==10)&&(i%11)&&((i/11|0)<10)){\n            X=((i%11)-5.5+.5)*sp\n            Y=((i/11|0)-5.5+.5)*sp\n            Z=0\n            R(Rl,Pt,Yw,1)\n            tgt=Q()\n            d=Math.hypot(tgt[0]-mx,tgt[1]-my)\n            if(d<sp*25){\n              x.beginPath()\n              s=Math.min(500, 500/Z)\n              x.arc(...Q(),s,0,7)\n              x.fillStyle=\'#0f0\'\n              if(P[i]==-1)x.fill()\n              tgt_=i\n            }\n          }\n        }\n        P.map((v,i)=>{\n          if(v!=-1&&v<2){\n            if((v&&((i/11|0)%2))||(!v&&(!((i/11|0)%2)))){\n              x.fillStyle=v?\'#80f8\':\'#0f8a\'\n              X=((i%11)-5.5+.5)*sp\n              Y=((i/11|0)-5.5+.5)*sp\n              Z=0\n              R(Rl,Pt,Yw,1)\n              x.beginPath()\n              s=Math.min(500,750/Z)\n              x.arc(...Q(),s,0,7)\n              x.fill()\n              x.beginPath()\n              X=((i%11)-5.5+.5)*sp\n              Y=((i/11|0)-5.5+.5)*sp-sp\n              Z=0\n              R(Rl,Pt,Yw,1)\n              x.lineTo(...Q())\n              X=((i%11)-5.5+.5)*sp\n              Y=((i/11|0)-5.5+.5)*sp+sp\n              Z=0\n              R(Rl,Pt,Yw,1)\n              x.lineTo(...Q())\n              x.lineWidth=Math.min(500,500/Z)\n              x.strokeStyle=v?\'#84fc\':\'#0f8c\'\n              x.stroke()\n            }else{\n              x.fillStyle=v?\'#80f8\':\'#0f8a\'\n              X=((i%11)-5.5+.5)*sp\n              Y=((i/11|0)-5.5+.5)*sp\n              Z=0\n              R(Rl,Pt,Yw,1)\n              x.beginPath()\n              s=Math.min(500,750/Z)\n              x.arc(...Q(),s,0,7)\n              x.fill()\n              x.beginPath()\n              X=((i%11)-5.5+.5)*sp-sp\n              Y=((i/11|0)-5.5+.5)*sp\n              Z=0\n              R(Rl,Pt,Yw,1)\n              x.lineTo(...Q())\n              X=((i%11)-5.5+.5)*sp+sp\n              Y=((i/11|0)-5.5+.5)*sp\n              Z=0\n              R(Rl,Pt,Yw,1)\n              x.lineTo(...Q())\n              x.lineWidth=Math.min(500,500/Z)\n              x.strokeStyle=v?\'#84fc\':\'#0f8c\'\n              x.stroke()\n            }\n          }\n        })\n        recursepurple=(idx, P)=>{\n          if(P[idx]!==1 && P[idx]!=3) return\n          if(idx>120 || idx<1) return\n          if(memo[idx]) return\n          if(idx>100){\n            good = true\n            return\n          }\n          memo[idx]=true\n          let X=idx%11\n          let Y=idx/11|0\n          recursepurple(idx+1, P)\n          recursepurple(idx-1, P)\n          recursepurple(idx+11, P)\n          recursepurple(idx-11, P)\n        }\n        for(let j=5;j--;){\n          good=false\n          memo=Array(122).fill(false)\n          recursepurple(1+j*2, P)\n          if(good) gameover=true, victor=1\n        }\n\n        //check green victory\n        recursegreen=(idx, P)=>{\n          if(P[idx]!==0 && P[idx]!=2) return\n          if(idx>120 || idx<1) return\n          if(memo[idx]) return\n          if(idx%11==10){\n            good = true\n            return\n          }\n          memo[idx]=true\n          let X=idx%11\n          let Y=idx/11|0\n          recursegreen(idx+1, P)\n          recursegreen(idx-1, P)\n          recursegreen(idx+11, P)\n          recursegreen(idx-11, P)\n        }\n        for(let j=5;j--;){\n          good=false\n          memo=Array(122).fill(false)\n          recursegreen(11+11*j*2, P)\n          if(good) gameover=true, victor=0\n        }\n\n        if(!gameover){\n          x.font=\'90px courier\'\n          x.textAlign=\'center\'\n          x.fillStyle=turn?\'#0f8\':\'#80f\'\n          x.fillText((turn?\'green\':\'purple\')+\'\\\'s\'+\' turn\',960,80)\n          if((turn+begCol)%2) doAIMove()\n        } else {\n          x.globalAlpha=1\n          x.font=\'200px courier\'\n          x.textAlign=\'center\'\n          x.fillStyle=!victor?\'#0f8\':\'#80f\'\n          x.strokeStyle=!victor?\'#8fc8\':\'#a6f8\'\n          x.lineWidth=20\n          x.strokeText((!victor?\'green\':\'purple\')+\' WON!\',960,500)\n          x.fillText((!victor?\'green\':\'purple\')+\' WON!\',960,500)\n          x.fillStyle=\'#fff\'\n          x.font=\'120px courier\'\n          x.fillText(\'click to play again...\',960,640)\n        }\n      break\n    }\n  } else {\n    x.fillStyle=\'#0008\'\n    x.fillRect(0,0,c.width,c.height)\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}\n.hidden{\n  visibility: hidden;\n}\n#spinner{\n  top: 0;\n  pointer-events: none;\n  left: 0;\n  opacity: .25;\n  position: absolute;\n  width: 100vw;\n  height: 100vh;\n  z-index: 10;\n  background-image: url(https://srmcgann.github.io/assets/7ERcg.gif);\n  background-size: contain;\n  background-position: center center;\n  background-repeat: no-repeat;\n}', '<canvas id=\"c\"></canvas>\n<div id=\"spinner\"></div>', 'side to side (w/ AI)', 145, 'whitehot robot', '2022-10-27 14:39:36', '[600468,600422,600373,600347,600253,600252,600251,600248,600247]', 109, '', 0, 0),
(600474, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    R = function(r,g,b,a) {\n      a = a === undefined ? 1 : a;\n      return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n    };\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n        }\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n        stroke=(scol,fcol)=>{\n          if(scol){\n            x.closePath()\n            x.strokeStyle=scol\n            x.lineWidth=Math.min(500,200/Z)\n            x.globalAlpha=.3\n            x.stroke()\n            x.globalAlpha=1\n            x.lineWidth/=4\n            x.stroke()\n          }\n          if(fcol){\n            x.fillStyle=fcol\n            x.fill()\n          }\n        }\n        oX=oY=0,oZ=6\n      }\n\n      x.fillStyle=\'#000\'\n      x.fillRect(0,0,c.width,c.height)\n\n      doClock=()=>{\n        x.lineCap=x.lineJoin=\'round\'\n        toX=oX,toY=oY,toZ=oZ\n        oX=oY=0, oZ=6\n        tRl=0,tPt=C(t)/2,tYw=S(t)/2\n\n        let sd=50, ls=3\n        x.beginPath()\n        for(let i=sd; i--;){\n          X=S(p=Math.PI*2/sd*i)*ls\n          Y=C(p)*ls\n          Z=0\n          R(tRl,tPt,tYw,1)\n          if(Z>0)x.lineTo(...Q())\n        }\n        stroke(\'#fff\',\'#fff2\')\n\n        spd=-6\n        x.beginPath()\n        X=0,Y=0,Z=0\n        R(tRl,tPt,tYw,1)\n        if(Z>0)x.lineTo(...Q())\n        tx=X=S(q_=p=t*spd)*ls*.8\n        ty=Y=C(p)*ls*.8\n        tz=Z=0\n        R(tRl,tPt,tYw,1)\n        if(Z>0)x.lineTo(...Q())\n        stroke(\'#fff\',\'\')\n\n        x.beginPath()\n        X=tx\n        Y=ty\n        Z=0\n        R(tRl,tPt,tYw,1)\n        if(Z>0)x.lineTo(...Q())\n        X=tx+S(q_-Math.PI/4+Math.PI)*.35\n        Y=ty+C(q_-Math.PI/4+Math.PI)*.35\n        Z=0\n        R(tRl,tPt,tYw,1)\n        if(Z>0)x.lineTo(...Q())\n        stroke(\'#fff\',\'\')\n\n        x.beginPath()\n        X=tx\n        Y=ty\n        Z=0\n        R(tRl,tPt,tYw,1)\n        if(Z>0)x.lineTo(...Q())\n        X=tx+S(q_+Math.PI/4+Math.PI)*.35\n        Y=ty+C(q_+Math.PI/4+Math.PI)*.35\n        Z=0\n        R(tRl,tPt,tYw,1)\n        if(Z>0)x.lineTo(...Q())\n        stroke(\'#fff\',\'\')\n\n        x.beginPath()\n        X=0,Y=0,Z=0\n        R(tRl,tPt,tYw,1)\n        if(Z>0)x.lineTo(...Q())\n        tx=X=S(q1_=p=t*spd/12)*ls*.6\n        ty=Y=C(p)*ls*.6\n        tz=Z=0\n        R(tRl,tPt,tYw,1)\n        if(Z>0)x.lineTo(...Q())\n        stroke(\'#fff\',\'\')\n\n        x.beginPath()\n        X=tx\n        Y=ty\n        Z=0\n        R(tRl,tPt,tYw,1)\n        if(Z>0)x.lineTo(...Q())\n        X=tx+S(q1_-Math.PI/4+Math.PI)*.35\n        Y=ty+C(q1_-Math.PI/4+Math.PI)*.35\n        Z=0\n        R(tRl,tPt,tYw,1)\n        if(Z>0)x.lineTo(...Q())\n        stroke(\'#fff\',\'\')\n\n        x.beginPath()\n        X=tx\n        Y=ty\n        Z=0\n        R(tRl,tPt,tYw,1)\n        if(Z>0)x.lineTo(...Q())\n        X=tx+S(q1_+Math.PI/4+Math.PI)*.35\n        Y=ty+C(q1_+Math.PI/4+Math.PI)*.35\n        Z=0\n        R(tRl,tPt,tYw,1)\n        if(Z>0)x.lineTo(...Q())\n        stroke(\'#fff\',\'\')      \n\n        for(i=12;i--;){\n          x.beginPath()\n          X=S(p=Math.PI*2/12*i)*ls*.9\n          Y=C(p)*ls*.9\n          Z=0\n          R(tRl,tPt,tYw,1)\n          if(Z>0)x.lineTo(...Q())\n          X=S(p=Math.PI*2/12*i)*ls*.92\n          Y=C(p)*ls*.92\n          Z=0\n          R(tRl,tPt,tYw,1)\n          if(Z>0)x.lineTo(...Q())\n          stroke(\'#fff\',\'\')      \n          \n        }\n        oX=toX,oY=toY,oZ=toZ\n      }\n      doClock()\n\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'clock animation', 145, 'whitehot robot', '2022-10-27 17:19:24', '[600422,600373,600347,600253,600252,600251,600248,600247]', 82, '', 0, 0),
(600475, '', '', '.test{\n  width: 100vw;\n  height: 100vh;\n  background-color: #0f0;\n  background-size: contain;\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-image: url(https://srmcgann.github.io/assets/Q2rJ7.jpg);\n}', '<div class=\"test\"></div>', 'css test', 145, 'whitehot robot', '2022-10-27 19:34:53', '', 81, '', 0, 0),
(600476, 'https://srmcgann.github.io/assets/18Lot0.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/1QV7m0.gif);\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: contain;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'divide by zero (gif)', 145, 'whitehot robot', '2022-10-28 18:38:21', '[600472,600471,600467,600466,600463,600462,600461,600454,600453,600450,600448,600447,600445,600442,600441,600440,600439,600438,600435,600427,600420,600419,600417,600414,600412,600403,600401,600399,600391,600390,600385,600380,600367,600366,600364,600363,600360,600359,600358,600357,600356,600355,600354,600353,600288,600253,600252,600251,600248,600247]', 86, 'https://code.dweet.net/thumbs/34918f1920b39452d0e7521da7afa7f7.jpg', 0, 0);
