(600477, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    R = function(r,g,b,a) {\n      a = a === undefined ? 1 : a;\n      return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n    };\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n        }\n        Q=()=>[c.width/2+X/Z*1200,c.height/2+Y/Z*1200]\n        I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n        for(CB=[],j=6;j--;CB=[...CB,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n\n        stroke=(scol,fcol)=>{\n          if(scol){\n            //x.closePath()\n            x.strokeStyle = scol\n            x.lineWidth = Math.min(500, 2000/Z)\n            x.globalAlpha = .2\n            x.stroke()\n            x.lineWidth /= 6\n            x.globalAlpha = 1\n            x.stroke()\n          }\n          if(fcol){\n            x.fillStyle=fcol\n            x.fill()\n          }\n        }\n\n        cl=1,rw=50,br=25,sp=2**.5/2/1.5\n        B=Array(cl*br).fill().map((v,i)=>{\n          a=[]\n          for(j=rw;j--;){\n            X=((i%cl)-cl/2+.5)*sp*2\n            Y=(j-rw/2+.5)*sp\n            Z=((i/cl|0)-br/2+.5)*sp*2\n            a=[...a, [X,Y,Z,X,Y,Z,0,0,0]]\n          }\n          return a\n        })\n\n        P=[]\n\n        go=false\n        bg = new Image()\n        bg.onload=()=>{\n          go=true\n        }\n        bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/15Tw5B.jpg\'\n      }\n\n      if(go){\n        iPv=3//+S(t)/4\n        iPr=5-S(t)*2\n\n\n        x.globalAlpha=.4\n        x.drawImage(bg,0,0,c.width,c.height)\n        x.globalAlpha=1\n        x.fillStyle=\'#0004\'\n        x.fillRect(0,0,c.width,c.height)\n        x.lineJoin=x.lineCap=\'butt\'\n        oX=oY=0, oZ=80-C(t)*20\n        Rl=t/3\n        Pt=Math.max(-1,Math.min(1,C(t/4)*5))\n        Yw=Math.max(-Math.PI-.5,Math.min(Math.PI+.5,S(t/4)*10))\n\n        if(!((t*60|0)%1)){\n          ls=S(t/2)*12\n          for(G=3;G--;){\n            ny=S(p=Math.PI*2/3*G+S(t/2)*40)*ls\n            nz=C(p)*ls\n            l=S(t/2)\n            tx_=-50*l\n            ty_=0+ny\n            tz_=0+nz\n            P=[...P, [tx_,ty_,tz_,iPv*(l>0?1:-1),(Rn()-.5)*iPv/5,(Rn()-.5)*iPv/5, iPr]]\n\n            CB.map(v=>{\n              x.beginPath()\n              v.map(q=>{\n                X=tx_+q[0]/1*iPr\n                Y=ty_+q[1]/1*iPr\n                Z=tz_+q[2]/1*iPr\n                R(Rl,Pt,Yw,1)\n                if(Z>0) x.lineTo(...Q())\n              })\n              stroke(\'#fff6\',\'#f004\')\n            })\n          }\n        }\n\n        CB.map(v=>{\n          x.beginPath()\n          v.map(q=>{\n            X=q[0]*2\n            Y=q[1]*16.5\n            Z=q[2]*16.5\n            R(Rl,Pt,Yw,1)\n            if(Z>0) x.lineTo(...Q())\n          })\n          stroke(\'#fff4\',\'#40f1\')\n        })\n\n        B.map((v,i)=>{\n          x.beginPath()\n          v.map((q,j)=>{\n\n            for(J=1;J--;){\n\n            tx1=ty1=tz1=0\n            tx2=ty2=tz2=0\n            if(j<v.length-1){\n              n=v[j+1]\n              tx=n[0]\n              ty=n[1]\n              tz=n[2]\n              d=Math.hypot(e=tx-q[0],f=ty-q[1],g=tz-q[2])\n              tx1=tx-(e)/d*sp\n              ty1=ty-(f)/d*sp\n              tz1=tz-(g)/d*sp\n            }else{\n              tx1=v[v.length-1][0]\n              ty1=v[v.length-1][1]\n              tz1=v[v.length-1][2]\n            }\n            if(j){\n              n=v[j-1]\n              tx=n[0]\n              ty=n[1]\n              tz=n[2]\n              d=Math.hypot(e=tx-q[0],f=ty-q[1],g=tz-q[2])\n              tx2=tx-(e)/d*sp\n              ty2=ty-(f)/d*sp\n              tz2=tz-(g)/d*sp\n            }else{\n              tx2=tx1\n              ty2=ty1\n              tz2=tz1\n            }\n            tx=(tx1+tx2)/2\n            ty=(ty1+ty2)/2\n            tz=(tz1+tz2)/2\n\n            q[6]+=(tx-q[0])/50\n            q[7]+=(ty-q[1])/50\n            q[8]+=(tz-q[2])/50\n            q[0]=tx\n            q[1]=ty\n            q[2]=tz\n            q[6]+=(q[3]-q[0])/100\n            q[7]+=(q[4]-q[1])/100\n            q[8]+=(q[5]-q[2])/100\n\n            X=q[0]+=q[6]\n            Y=q[1]+=q[7]\n            Z=q[2]+=q[8]\n\n            q[6]/=1.03\n            q[7]/=1.03\n            q[8]/=1.03\n\n            P.map(n=>{\n              tx=n[0]\n              ty=n[1]\n              tz=n[2]\n              d=Math.hypot(e=tx-q[0],f=ty-q[1],g=tz-q[2])\n              if(d<n[6]*1){\n                q[0]=tx-e/d*n[6]*1\n                q[1]=ty-f/d*n[6]*1\n                q[2]=tz-g/d*n[6]*1\n              }\n            })\n  }\n\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n          })\n          stroke(\'#fff8\')\n        })\n\n        P.map((v,i) => {\n          X=v[0]+=v[3]\n          Y=v[1]+=v[4]\n          Z=v[2]+=v[5]\n          R(Rl,Pt,Yw,1)\n          if(Z>0){\n            x.beginPath()\n            s=Math.min(1e3, 600*v[6]/Z)\n            x.arc(...Q(),s,0,7)\n            stroke(\'\', \'#4fc2\')\n            x.beginPath()\n            s/=1.25\n            //x.arc(...Q(),s,0,7)\n            //stroke(\'\', \'#fff2\')\n            x.beginPath()\n            s/=1.25\n            x.arc(...Q(),s,0,7)\n            stroke(\'\', \'#fff4\')\n          }\n        })\n\n        P=P.filter(v=>Math.abs(v[0])<50)\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'string theory', 145, 'whitehot robot', '2022-10-29 15:13:06', '[600422,600373,600347,600253,600252,600251,600248,600247]', 84, '', 0, 0),
