     Y=v[1]-=mind\n        Z=v[2]\n        R2(0,.5535735,0)\n        return [X,Y,Z]\n      })\n\n      ret = [...ret, a]\n      b=JSON.parse(JSON.stringify(a)).map(v=>{\n        d=Math.hypot(v[0],v[1])\n        v[0]=S(p=Math.atan2(v[0],v[1])+Math.PI)*d\n        v[1]=C(p)*d\n        return v\n      })\n      ret = [...ret, b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          if(q[2]<mind)mind=q[2]\n        })\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]+=ang=1.538840639715\n        })\n      })\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI,0,Math.PI)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      b=JSON.parse(JSON.stringify(e)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI/2,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n    stroke = (scol, fcol) => {\n      if(scol){\n        x.closePath()\n        x.strokeStyle = scol\n        x.globalAlpha = .2\n        x.lineWidth = Math.min(1e3, 300/Z)\n        x.stroke()\n        x.globalAlpha = 1\n        x.lineWidth /= 5\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n  }\n\n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n  oX=oY=0, oZ=10\n  Rl=0,Pt=0,Yw=0\n  \n  \n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'new template', 145, 'whitehot robot', '2022-11-01 21:49:06', '[600482,600422,600373,600347,600253,600252,600251,600248,600247]', 97, '', 0, 1),
(600486, 'https://srmcgann.github.io/assets/1BsMaA.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/1KuksL.gif);\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: contain;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'pitch (gif)', 145, 'whitehot robot', '2022-11-01 23:07:04', '[600483,600481,600480,600478,600476,600472,600471,600467,600466,600463,600462,600461,600454,600453,600450,600448,600447,600445,600442,600441,600440,600439,600438,600435,600427,600420,600419,600417,600414,600412,600403,600401,600399,600391,600390,600385,600380,600367,600366,600364,600363,600360,600359,600358,600357,600356,600355,600354,600353,600288,600253,600252,600251,600248,600247]', 83, 'https://code.dweet.net/thumbs/eddc7453f0c01301983e860fae1da2ca.jpg', 0, 0),
(600487, 'https://srmcgann.github.io/assets/21MrkT.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/kGixp.gif);\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: contain;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'until psychedelic light (gif)', 145, 'whitehot robot', '2022-11-09 03:08:03', '[600481,600480,600478,600476,600472,600471,600467,600466,600463,600462,600461,600454,600453,600450,600448,600447,600445,600442,600441,600440,600439,600438,600435,600427,600420,600419,600417,600414,600412,600403,600401,600399,600391,600390,600385,600380,600367,600366,600364,600363,600360,600359,600358,600357,600356,600355,600354,600353,600288,600253,600252,600251,600248,600247]', 86, 'https://code.dweet.net/thumbs/37ece8e06943eb6fdf596d7fd87b9961.jpg', 0, 0),
(600490, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=to=0\n\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth/document.body.clientWidth < 1.7777778)\n    {\n      c.style.width  = document.body.clientWidth + \'px\'\n      c.style.height = (document.body.clientWidth/1.777777778) + \'px\'\n    }else{\n      c.style.height = document.body.clientHeight + \'px\'\n      c.style.width  = (document.body.clientHeight*1.777777778) + \'px\'\n    }\n    c.width  = 1920\n    c.height = 1080\n  },0)\n}\nrsz()\n\nDraw=()=>{\n \n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      if(m) X+=oX,Y+=oY,Z+=oZ\n    }\n    Q=()=>[c.width/2+X/Z*400,c.height/2+Y/Z*400]\n    for(CB=[],j=6;j--;CB=[...CB,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.lineWidth=Math.min(500,2e4/Z)\n        x.strokeStyle=scol\n        x.globalAlpha=.3\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth=Math.min(35, Math.max(2,x.lineWidth/5))|0\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n    for(Φ=[1,1],i=50;i--;)Φ=[...Φ, Φ[l=Φ.length-2]+Φ[l+1]];Φ=Φ[l+1]/Φ[l]\n    P_=[\n      [[0,0],[2,3],[1,1]],\n      [[0,0],[1,1],[1,0]],\n      [[0,0],[2,0],[1,0]],\n      [[2,2],[1,1],[0,3]],\n      [[1,0],[1,1],[0,3]],\n      [[1,0],[2,1],[0,3]],\n      [[2,3],[0,1],[1,2]],\n      [[2,3],[1,1],[2,2]],\n      [[2,3],[1,2],[2,2]],\n      [[2,1],[2,0],[1,0]],\n      [[2,1],[2,0],[1,3]], \n      [[2,1],[0,2],[1,3]],\n      [[1,3],[0,1],[2,0]],\n      [[0,3],[0,2],[2,2]],\n      [[0,3],[2,1],[0,2]],\n      [[0,0],[0,1],[2,0]],\n      [[2,2],[1,2],[0,2]],\n      [[1,3],[1,2],[0,2]],\n      [[1,3],[1,2],[0,1]],\n      [[2,3],[0,0],[0,1]],\n    ]\n\n\n    renderShape=(subs)=>{\n      a=[\n          [\n            [-Φ,-1,0],\n            [-Φ,1,0],\n            [Φ,1,0],\n            [Φ,-1,0],\n          ]\n        ]\n      P=[]\n      for(i=3;i--;){\n        b=JSON.parse(JSON.stringify(a)).map((q,j)=>{\n          q=q.map((m,n)=>{\n            X=q[n][(i+0)%3]\n            Y=q[n][(i+1)%3]\n            Z=q[n][(i+2)%3]\n            return [X,Y,Z]\n          })\n          return q\n        })\n        P=[...P, ...b]\n      }\n      L=[]\n      P_.map((v,i)=>{\n        a=[]\n        v.map((q,j)=>{\n          X=P[q[0]][q[1]][0]\n          Y=P[q[0]][q[1]][1]\n          Z=P[q[0]][q[1]][2]\n          a=[...a, [X,Y,Z]]\n        })\n        L=[...L, a]\n      })\n      subdivide=()=>{\n        let a=[]\n        L.map(v=>{\n          b=[]\n          X1=v[0][0]\n          Y1=v[0][1]\n          Z1=v[0][2]\n          X2=v[1][0]\n          Y2=v[1][1]\n          Z2=v[1][2]\n          X3=v[2][0]\n          Y3=v[2][1]\n          Z3=v[2][2]\n          ax1=(X1+X2)/2\n          ay1=(Y1+Y2)/2\n          az1=(Z1+Z2)/2\n          ax2=(X2+X3)/2\n          ay2=(Y2+Y3)/2\n          az2=(Z2+Z3)/2\n          ax3=(X3+X1)/2\n          ay3=(Y3+Y1)/2\n          az3=(Z3+Z1)/2\n          b=[...b, [[ax1,ay1,az1],[ax2,ay2,az2],[ax3,ay3,az3]]]\n          b=[...b, [[ax1,ay1,az1],[ax2,ay2,az2],[X2,Y2,Z2]]]\n          b=[...b, [[ax2,ay2,az2],[ax3,ay3,az3],[X3,Y3,Z3]]]\n          b=[...b, [[ax3,ay3,az3],[ax1,ay1,az1],[X1,Y1,Z1]]]\n          a=[...a, ...b]\n        })\n        L=a\n      }\n      for(let m=subs;m--;)subdivide()\n      L=L.map(v=>{\n        v=v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          d=Math.hypot(X,Y,Z)\n          X/=d\n          Y/=d\n          Z/=d\n          X1=q[0]*ls*2\n          Y1=q[1]*ls*2\n          Z1=q[2]*ls*2\n          X2=X*ls*4\n          Y2=Y*ls*4\n          Z2=Z*ls*4\n          X=(X1*ipl)+(X2*(1-ipl))\n          Y=(Y1*ipl)+(Y2*(1-ipl))\n          Z=(Z1*ipl)+(Z2*(1-ipl))\n          return [X,Y,Z]\n        })\n        return v\n      })\n    }\n    go=false\n    bg=new Image()\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=http://home.whitehot.ninja/nebula.jpg\'\n  }\n\n  if(go){\n    ls = 100\n    ipl=-(.65+S(t*2))*8\n\n    x.globalAlpha=.2\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.fillStyle=\'#0002\'\n    x.globalAlpha=1\n    x.fillRect(0,0,c.width,c.height)\n    x.lineJoin=x.lineCap=\'butt\'\n    oX=0,oY=0,oZ=Math.max(500,Math.min(1000,S(t)*4000))\n    //Rl=0,Pt=-t/2,Yw=S(t/2)*4\n    Rl=0,Pt=-t/2,Yw=S(t/16)*8\n\n    renderShape(3)\n    L.map(v=>{\n      x.beginPath()\n      v.map(q=>{\n        X=q[0]\n        Y=q[1]\n        Z=q[2]\n        d1=Math.hypot(X,Y,Z)**2/50\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n      })\n      col=`hsla(${d1/150+t*300},99%,${Math.max(50,150-d1/280)}%,.065)`\n      stroke(\'#fff1\', col)\n    })\n\n    P.map((v,i)=>{\n      x.beginPath()\n      v.map((q,j)=>{\n        X=q[0]*ls*2\n        Y=q[1]*ls*2\n        Z=q[2]*ls*2\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          x.lineTo(...Q())\n          x.font=\'66px courier\'\n          x.fillStyle=\'#fffa\'\n          //x.fillText(i+\',\'+j,...Q())\n        }\n      })\n      stroke(\'#0f08\')\n    })\n\n    CB.map(v=>{\n       x.beginPath()\n       v.map(q=>{\n         X=q[0]*ls*2\n         Y=q[1]*ls*2\n         Z=q[2]*ls*2\n         R(Rl,Pt,Yw,1)\n         if(Z>0)x.lineTo(...Q())\n       })\n       stroke(\'#0ff8\',\'#60f2\')\n    })\n  }else{\n    x.fillStyle=\'#000\'\n    x.fillRect(0,0,c.width,c.height)\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  overflow: hidden;\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'nebula deluxe', 145, 'whitehot robot', '2022-11-13 21:59:29', '[600422,600373,600347,600253,600252,600251,600248,600247]', 20, '', 0, 1);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600491, '', '    c=document.querySelector(\'#c\')\n    c.setAttribute(\'tabindex\', 1)\n    c.focus()\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        max_velocity=20000000\n        showHUD=true\n        hRl=0\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(showHUD){\n            X=S(p=A(X,Y)+hRl)*(d=H(X,Y))\n            Y=C(p)*d\n          }\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n        }\n        R_=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt-(showHUD?0:.15))*(d=H(Y,Z))\n          Z=C(p)*d\n          if(showHUD){\n            X=S(p=A(X,Y)+hRl)*(d=H(X,Y))\n            Y=C(p)*d\n          }\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n        }\n        for(j=6,CB=[];j--;CB=[...CB,b])for(i=4,b=[];i--;)b=[...b,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n        stroke = (scol, fcol, closePath, lineWidthUpscale, globalAlphaOverride=1) => {\n          x.globalAlpha=globalAlphaOverride\n          if(scol){\n            if(closePath) x.closePath()\n            x.strokeStyle=scol\n            x.lineWidth = Math.min(500,1000/Z*(lineWidthUpscale?lineWidthUpscale:1))\n            //x.globalAlpha=.5*globalAlphaOverride\n            //x.stroke()\n            x.lineWidth=x.lineWidth/4|0\n            x.stroke()\n          }\n          if(fcol){\n            x.fillStyle=fcol\n            x.fill()\n          }\n        }\n\n        buildDaPlane = (tx,ty,tz,ls) => {\n          daPlane=[]\n          planeLen = 100\n          lenSegs = 16\n          sd=8\n          for(m=lenSegs;m--;){\n            ls_=(.5+C(Math.PI*2/(lenSegs-1)/1.5*m-Math.PI/1.5)/2)*ls\n            a=[]\n            for(i=sd;i--;){\n              X=tx+S(p=Math.PI*2/sd*i)*ls_\n              Y=ty+C(p)*ls_\n              Z=tz+(m-lenSegs/2+.5)*planeLen/lenSegs\n              a=[...a, [X,Y,Z]]\n            }\n            daPlane=[...daPlane, a]\n          }\n          a=[]\n          for(n=3;n--;){\n            a=[...a, ...JSON.parse(JSON.stringify(CB)).map(v=>v.map(q=>{\n              q[0]*=ls*3.5/3\n              q[1]*=ls/10\n              q[2]*=ls*(.5+(4-n)/1)**1.5/6\n              q[0]+=tx-ls*1.75-ls*3.5/3*n*1.4\n              q[1]+=ty\n              q[2]+=tz\n              return q\n            }))]\n            a=[...a, ...JSON.parse(JSON.stringify(CB)).map(v=>v.map(q=>{\n              q[0]*=ls*3.5/3\n              q[1]*=ls/10\n              q[2]*=ls*(.5+(4-n)/1)**1.5/6\n              q[0]-=tx-ls*1.75-ls*3.5/3*n*1.4\n              q[1]+=ty\n              q[2]+=tz\n              return q\n            }))]\n          }\n          a=[...a, ...JSON.parse(JSON.stringify(CB)).map(v=>v.map(q=>{\n            q[0]*=ls/10\n            q[1]*=ls*3.5/2\n            q[2]*=ls/2\n            q[0]+=tx\n            q[1]+=ty\n            q[2]-=tz+ls*5\n            return q\n          }))]\n          a=[...a, ...JSON.parse(JSON.stringify(CB)).map(v=>v.map(q=>{\n            q[0]*=ls*3.5/2\n            q[1]*=ls/10\n            q[2]*=ls/2\n            q[0]+=tx\n            q[1]+=ty\n            q[2]-=tz+ls*5\n            return q\n          }))]\n          daPlane=[...daPlane, ...a]\n          return daPlane\n        }\n        loadGame=()=>{\n          plane = buildDaPlane(0,0,0,10)\n          propeller = [\n            JSON.parse(JSON.stringify(CB)).map(v=>{\n              v=v.map(q=>{\n                X1=q[0]*40\n                Y1=q[1]*2\n                Z1=q[2]\n                X=X1+plane[0][0][0]\n                Y=Y1+plane[0][0][1]\n                Z=Z1+plane[0][0][2]\n                return [X,Y,Z,X1,Y1,Z]\n              })\n              return v\n            }),\n            JSON.parse(JSON.stringify(CB)).map(v=>{\n              v=v.map(q=>{\n                X=q[0]*40\n                Y=q[1]*2\n                Z=q[2]\n                R(Math.PI/2,0,0)\n                X1=X,Y1=Y,Z1=Z\n                X+=plane[0][0][0]\n                Y+=plane[0][0][1]\n                Z+=plane[0][0][2]\n                return [X,Y,Z,X1,Y1,Z1+plane[0][0][2]]\n              })\n              return v\n            }),\n          ]\n          \n          oalt=altitude=25000,mvx=mvz=0\n          iTc=50, iTsp=10000, tsp1=.0001, tsp2=.002, tsp3=.0001\n          actx=acty=actz=iPvx=iPvy=iPvz=0\n          Alt=(X,Z,mode)=>{ \n            tx=X\n            tz=Z\n            let texture1 =(S(tx/500*tsp1)*S(tz/500*tsp1)*52)**6/3e3\n            let texture2 =(S(tx/1000*tsp2)*S(tz/1000*tsp2)*54)**6/8e4\n            return altitude - 1*(S(tx/2000*tsp3)*S(tz/2400*tsp3)*55)**7/9e5 - texture1 - texture2\n          }\n          Floor=()=>{\n            X=0\n            Y=-200\n            Z=2000\n            R_(Rl,Pt,-Yw)\n            return iPvy+Y+Alt(X+mvx,Z+mvz,0)\n          }\n\n          pptv=prlv=pywv=0\n          ppt=prl=pyw=0\n          keys=Array(256).fill(false)\n          window.onkeydown=e=>{\n            if(e.keyCode==84) showTracking=!showTracking\n            if(e.keyCode==73) showInfo=!showInfo\n            if(e.keyCode==72){\n              showHUD=!showHUD\n            }\n            e.stopPropagation()\n            e.preventDefault()\n            keys[e.keyCode]=true\n          }\n          window.onkeyup=e=>{\n            if(e.keyCode != 76) doLevel=false\n            e.stopPropagation()\n            e.preventDefault()\n            keys[e.keyCode]=false\n          }\n          doLevel=false\n          level=()=>{\n            if(\n              Math.abs(ppt)>.05 ||\n              Math.abs(Pt)>.05 ||\n              Math.abs(prl)>.05 ||\n              Math.abs(Rl)>.05 ||\n              Math.abs(pyw)>.05 //||\n              //Math.abs(Yw)>.05\n            ){\n              if(Math.abs(ppt)>.01) ppt+=.02*(ppt>0?-1:1)\n              if(Math.abs(Pt)>.01) Pt+=.02*(Pt>0?-1:1)\n              if(Math.abs(prl)>.01) prl+=.02*(prl>0?-1:1)\n              if(Math.abs(Rl)>.01) Rl+=.02*(Rl>0?-1:1)\n              if(Math.abs(pyw)>.01) pyw+=.02*(pyw>0?-1:1)\n              //if(Math.abs(Yw)>.01) Yw+=.02*(Yw>0?-1:1)\n            }else{\n              ppt=Pt=0\n              prl=Rl=0\n              pyw=0//Yw=0\n              doLevel=false\n            }\n          }\n          pv=.0075\n          doKeys=()=>{\n            keys.map((v,i)=>{\n              if(v) switch(i){\n                case 49:\n                  hudChoice=0\n                break\n                case 50:\n                  hudChoice=1\n                break\n                case 51:\n                  hudChoice=2\n                break\n                case 52:\n                  hudChoice=3\n                break\n                case 53:\n                  hudChoice=4\n                break\n                case 65:\n                  pfv+=300+pfv/300\n                  pfv=Math.min(max_velocity, pfv)\n                break\n                case 90:\n                  pfv-=300+pfv/300\n                  pfv=Math.max(0, pfv)\n                break\n                case 76:\n                  doLevel=true\n                break\n                case 32:\n                  if(!flying) loadGame()\n                break\n                case 37:\n                  pywv-=pv\n                break\n                case 38:\n                  pptv+=pv\n                break\n                case 39:\n                  pywv+=pv\n                break\n                case 40:\n                  pptv-=pv\n                break\n              }\n            })\n          }\n          Rl=Yw=Pt=0\n          iPvx=iPvy=iPvz=0\n\n          gameover = new Image()\n          gameover.onload=()=>{\n            \n          }\n          //gameover.src=\'proxy.php?url=https://srmcgann.github.io/assets/15wfQj.png\'\n          gameover.src=\'proxy.php?url=https://srmcgann.github.io/assets/15wfQj.png\'\n          iSTc=1e3\n          iSTG=1e8\n          ST=Array(iSTc).fill().map(v=>{\n            X=(Rn()-.5)*iSTG\n            Y=-Rn()*iSTG\n            Z=(Rn()-.5)*iSTG\n            return [X,Y,Z]\n          })\n\n          flying=true\n          crashVid=document.createElement(\'video\')\n          go=false\n          crashVid.oncanplay=()=>{\n            go=true\n          }\n          crashEnded = false\n          crashVid.onended=()=>{\n            crashEnded = true\n            //crashVid.src = \'proxy.php?url=https://srmcgann.github.io/assets/hBSq1.mp4\'\n            crashVid.src = \'proxy.php?url=https://srmcgann.github.io/assets/1oT95v.mp4\'\n          }\n          //crashVid.src = \'proxy.php?url=https://srmcgann.github.io/assets/hBSq1.mp4\'\n          crashVid.src = \'proxy.php?url=https://srmcgann.github.io/assets/1oT95v.mp4\'\n          buffer = document.createElement(\'canvas\')\n          bctx=buffer.getContext(\'2d\')\n          doCrash=()=>{\n            crashEnded = false\n            buffer.width=crashVid.videoWidth\n            buffer.height=crashVid.videoHeight\n            crashVid.play()\n            flying=false\n          }\n          showTracking=true\n          pfv=500\n          mvx=mvy=mvz=0\n          TB=[]\n        }\n\n        modalNames = [\n          \'hotkeys\',\n        ]\n\n        modals=Array(modalNames.length).fill().map((v,i)=>{\n          return {\n            name: modalNames[i],\n            display: false\n          }\n        })\n\n        closeModals=()=>{\n          modals.map(v=>{\n            document.querySelector(\'#\'+v.name).classList.toggle(\'noDisplay\')\n          })\n          document.querySelector(\'#closeModals\').classList.toggle(\'noDisplay\')\n          modals.map(v=>{\n            v.display=false\n          })\n        }\n\n        showModal = modal => {\n          document.querySelector(\'#\'+modal).classList.toggle(\'noDisplay\')\n          document.querySelector(\'#closeModals\').classList.toggle(\'noDisplay\')\n          modals.map(v=>{\n            if(v.name == modal) v.display = true\n          })\n        }\n\n        hudsLoaded=false\n        loadGame()\n        huds=Array(5).fill().map(v=>({loaded:false}))\n        huds=huds.map((v,i)=>{\n          let src\n          switch(i){\n            case 0: src=\'igzKX\'; break\n            case 1: src=\'hyRGN\'; break\n            case 2: src=\'1ERFSs\'; break\n            case 3: src=\'puo9D\'; break\n            case 4: src=\'MPYAx\'; break\n          }\n          let img = {\n            img: new Image(),\n            loaded: false,\n            src : \'proxy.php?url=https://srmcgann.github.io/assets/\'+src+\'.png\'\n          }\n          img.img.onload=()=>{\n            img.loaded = true \n            hudsLoaded=true\n            huds.map(q=>{\n              if(!q.loaded) hudsLoaded=false\n            })\n          }\n          img.img.src=img.src\n          return img\n        })\n        printText=(caption, X, Y, fcol, size)=>{\n          x.fillStyle=fcol\n          x.font = size+\'px courier\'\n          caption.split(\"\\n\").map((v,i)=>{\n            x.fillText(v,X,Y+i*size)\n          })\n        }\n        hudChoice=1\n        showInfo=true\n      }\n\n      x.fillStyle=\'#0008\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'butt\'\n      oX=0\n      oY=4\n      oZ=showHUD?0:90\n\n      if(!hudsLoaded){\n        x.textAlign=\'center\'\n        printText((\'.\'.repeat((t*10|0)%5))+\'LOADING\'+(\'.\'.repeat((t*10|0)%5)), 960, 640, \'#FFF\', 100)\n        x.textAlign=\'left\'\n      }\n\n      if(go && hudsLoaded){\n        if(doLevel) level()\n        doKeys()\n\n        modalVisible = modals.filter(v=>v.display).length\n\n        if(!modalVisible&&flying){\n          prl+=prlv\n          ppt+=pptv\n          pyw+=pywv\n\n          pyw=Math.min(Math.PI/4,Math.max(-Math.PI/4, pyw))\n          prl=Math.min(Math.PI/4,Math.max(-Math.PI/4, prl))\n          ppt=Math.min(Math.PI/4,Math.max(-Math.PI/4, ppt))\n\n          prl=-pyw*3\n          prlv/=1.5\n          pptv/=1.5\n          pywv/=1.5\n\n          hRl=-prl\n          Pt-=ppt/9\n          Yw-=pyw/9\n\n          mvx+=S(Yw)*C(Pt)*pfv\n          mvy+=S(Pt)*pfv\n          mvz+=-C(Yw)*C(Pt)*pfv\n\n          iPvx+=S(Yw)*C(Pt)*pfv\n          iPvy+=S(Pt)*pfv\n          iPvz+=-C(Yw)*C(Pt)*pfv\n        }else{\n          pfv=0\n        }\n        ST.map(v=>{\n          X=v[0]+=S(Yw)*C(Pt)*pfv\n          Y=v[1]+=S(Pt)*pfv\n          Z=v[2]+=-C(Yw)*C(Pt)*pfv\n          if(X>iSTG/2)v[0]=-iSTG/2\n          if(X<-iSTG/2)v[0]=iSTG/2\n          if(Y>0+iSTG/8)v[1]=-iSTG/2+iSTG/8\n          if(Y<-iSTG+iSTG/8)v[1]=iSTG+iSTG/8\n          if(Z>iSTG/2)v[2]=-iSTG/2\n          if(Z<-iSTG/2)v[2]=iSTG/2\n\n          R_(Rl,Pt,Yw,1)\n          if(Z>0){\n            s=Math.min(500, 1e9/Z)\n            x.fillStyle=\'#fff1\'\n            l=Q()\n            x.globalAlpha=1/(1+Z**9/1e180)\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n            s/=4\n            x.fillStyle=\'#fffa\'\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          }\n        })\n        x.globalAlpha=1\n\n        trls=1000, ls=iTsp,l_=0,mls=2e8\n        if(showTracking){\n          if(!modalVisible){\n            for(i=0;i<trls**2;i++){\n              if(Rn()<.0005){\n                ls=Rn()*mls\n                nx=X=S(p=-Yw+(Rn()-.5)*1.7)*ls\n                nz=Z=C(p)*ls\n                l_=H(nx,nz)\n                if(Rn()**.04<1-l_/mls/2){\n                  Y=0\n                  R_(Rl,Pt,Yw,1)\n                  if(Z>100000)TB=[...TB,[nx-mvx,0,nz-mvz,1]]\n                }\n              }\n            }\n          }\n          TB=TB.filter(v=>{return v[3]>0}).map(v=>{\n            X=v[0]+mvx\n            Z=v[2]+mvz\n            Y=iPvy+(ty=Alt(X-iPvx,Z-iPvz,0))\n            R_(Rl,Pt,Yw,1)\n            if(Z>0){\n              x.globalAlpha=v[3]\n              s=Math.min(50, 2e5/Z**.5)\n              l=Q()\n              x.fillStyle=`hsla(${ty/20000+120},99%,50%,.2)`\n              x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n              s/=4\n              x.fillStyle=\'#8ff\'\n              x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n            }else{\n              v[3]=0\n            }\n            v[3]-=modalVisible?0:.02\n            return v\n          })\n          x.globalAlpha=1\n        }\n\n        if(flying && altitude+Floor()<oalt-200) {\n          x.fillStyle=\'#ff8\'\n          x.fillRect(0,0,c.width,c.height)\n          doCrash()\n        }\n\n        if(flying){\n          if(showHUD){\n            if(huds[hudChoice].img.width/huds[hudChoice].img.height<1920/1080){\n              w=1080*(huds[hudChoice].img.width/huds[hudChoice].img.height)\n              h=1080\n            }else{\n              w=1920\n              h=1920*(huds[hudChoice].img.height/huds[hudChoice].img.width)\n            }\n            x.drawImage(huds[hudChoice].img,c.width/2-w/2,c.height/2-h/2,w,h)\n          }else{\n            propSpeed=modalVisible?0:-.2-pfv/100000\n            propeller.map(v=>{ \n              v.map(q=>{\n                x.beginPath()\n                q.map(n=>{\n                  X=n[3]\n                  Y=n[4]\n                  Z=n[5]\n                  R(propSpeed,0,0)\n                  n[3]=X\n                  n[4]=Y\n                  n[5]=Z\n                  R_(prl,ppt+.25,pyw)\n                  R_(0,0,0,1)\n                  if(Z>0) x.lineTo(...Q())\n                })\n                stroke(\'#fff1\',\'#4fb2\',1,2)\n              })\n            })\n\n            plane.map((v,i)=>{\n              if(i&&i<lenSegs){\n                v.map((q,j)=>{\n                  x.beginPath()\n                  l=j\n                  X=v[l][0]\n                  Y=v[l][1]\n                  Z=v[l][2]\n                  R_(prl,ppt+.25,pyw)\n                  R_(0,0,0,1)\n                  if(Z>0) x.lineTo(...Q())\n                  l=j\n                  X=plane[i-1][l][0]\n                  Y=plane[i-1][l][1]\n                  Z=plane[i-1][l][2]\n                  R_(prl,ppt+.25,pyw)\n                  R_(0,0,0,1)\n                  if(Z>0) x.lineTo(...Q())\n                  l=(j+1)%v.length\n                  X=plane[i-1][l][0]\n                  Y=plane[i-1][l][1]\n                  Z=plane[i-1][l][2]\n                  R_(prl,ppt+.25,pyw)\n                  R_(0,0,0,1)\n                  if(Z>0) x.lineTo(...Q())\n                  l=(j+1)%v.length\n                  X=plane[i][l][0]\n                  Y=plane[i][l][1]\n                  Z=plane[i][l][2]\n                  R_(prl,ppt+.25,pyw)\n                  R_(0,0,0,1)\n                  if(Z>0) x.lineTo(...Q())\n                  stroke(\'#fff1\', \'#4fb2\', 1)\n                })\n              } else{\n                x.beginPath()\n                v.map(q=>{\n                  X=q[0]\n                  Y=q[1]\n                  Z=q[2]\n                  R_(prl,ppt+.25,pyw)\n                  R_(0,0,0,1)\n                  if(Z>0){\n                    x.lineTo(...Q())\n                  }\n                })\n                stroke(\'#fff1\', \'#4fb2\', 1)\n              }\n            })\n          }\n        }else{\n          if(!flying && !crashEnded){\n            x.fillStyle=\'#f004\'\n            x.fillRect(0,0,c.width,c.height)\n            bctx.drawImage(crashVid,0,0,buffer.width,buffer.height)\n            let data = bctx.getImageData(0,0,buffer.width,buffer.height)\n            let l = data.data\n            for(let i = 0; i<l.length; i+=4){\n              red   = l[i+0]\n              green = l[i+1]\n              blue  = l[i+2]\n              alpha = l[i+3]\n              lum = (red+green+blue)/3\n              l[i+3] = lum>40?alpha:0\n            }\n            bctx.putImageData(data,0,0)\n            x.globalAlpha=.75\n            x.drawImage(buffer,c.width/2-buffer.width*3,c.height/2-buffer.height*3,buffer.width*6,buffer.height*6)\n            x.globalAlpha=1\n          }\n        }\n        if(!flying && crashEnded){\n          x.drawImage(gameover,0,0,c.width,c.height)\n        }\n      }\n\n      if(showInfo){\n        let spd = 99+pfv/500\n        let mg =20\n        let w = 500\n        let h = 200\n        let fontsize = 50\n        x.fillStyle=\'#0048\'\n        x.fillRect(c.width-w-mg*2,0,w+mg*2,h+mg*2)\n        x.fillStyle=\'#203a\'\n        x.fillRect(c.width-w-mg,mg,w,h)\n        let caption = `INFO\n\nspeed: ${Math.round(spd)} MpH\n`\n        printText(caption,c.width-w-mg+mg,fontsize+mg*2,\'#fff\',fontsize)\n      }\n\n      modals.map(v=>{\n        if(v.display){\n          switch(v.name){\n            case \'hotkeys\':\n              x.globalAlpha=1\n              x.fillStyle=\'#000a\'\n              x.fillRect(0,0,c.width,c.height)\n              let caption=`\nKEY    FUNCTION\n A     accelerate\n Z     decelerate\n L     auto-level\n H     toggle HUD (heads-up-display) view\n I     toggle INFO visibility\n ↑     pitch (nose) down\n ↓     pitch (nose) up\n →     roll right\n ←     roll left\n1-5    set HUD style\n`\n              printText(caption, 100, 200, \'#fff\', 64)\n            break\n          }\n        }\n      })\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  margin: 0;\n  overflow: hidden;\n  height: 100vh;\n  background: #000;\n}\n#c{\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top:50%;\n  transform: translate(-50%,-50%);\n}\n#c:focus{\n  outline: none;\n}\n#closeModals{\n  background-color: #611;\n  color: #fff;\n  opacity: 1;\n}\n#hotkeys{\n  opacity: .5;\n  background-image: url(https://srmcgann.github.io/assets/LUEfb.png);\n  background-size: 100px;\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-color: #0000;\n}\n.modalsButton{\n  border-radius: 5px;\n  position: fixed;\n  z-index: 100;\n  font-size: 20px;\n  font-family: courier, arial;\n  height: 40px;\n  width: 102px;\n  margin: 5px;\n  cursor: pointer;\n}\n.noDisplay{\n  display: none;\n}', '<canvas id=c></canvas>\n<button\n  id=\"hotkeys\"\n  class=\"modalsButton\"\n  title=\"hotkeys/controls\"\n  onclick=\"showModal(\'hotkeys\')\"\n></button>\n<button\n  id=\"closeModals\"\n  class=\"modalsButton noDisplay\"\n  title=\"close\"\n  onclick=\"closeModals()\"\n>close</button>', 'flight simulator', 145, 'whitehot robot', '2022-11-19 06:32:14', '', 72, '', 0, 0),
(600492, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    R = function(r,g,b,a) {\n      a = a === undefined ? 1 : a;\n      return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n    }\n\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n        }\n        R2=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX\n            Y+=oY\n            Z+=oZ\n          }\n        }\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n\n        Sphere=(ls,cl,rw)=>{\n          let X,Y,Z\n          let ret=[]\n          for(i=cl*rw;i--;){\n            a=[]\n            j=i%cl\n            k=(i/cl|0)\n            l=(j+1)%cl\n            \n            X=S(p=Math.PI*2/cl*j)*S(q=Math.P