0,0,0,0,0]\n        })\n        G=20\n        iSc=5\n        shapes = Array(iSc).fill().map((v,i)=>{\n          let ret, ls=10\n          tx=S(p=Math.PI*2/iSc*i)*G\n          ty=0\n          tz=C(p)*G\n          switch(i){\n            case 0:\n              ret = [tx, ty, tz, Tetrahedron(ls),  \'\', \'#4f82\']\n            break\n            case 1:\n              ret = [tx, ty, tz,  Cube(ls),         \'\', \'#4f82\']\n            break\n            case 2:\n              ret = [tx, ty, tz,  Octahedron(ls),   \'\', \'#4f82\']\n            break\n            case 3:\n              ret = [tx, ty, tz,  Dodecahedron(ls), \'\', \'#4f82\']\n            break\n            case 4:\n              ret = [tx, ty, tz,  Icosahedron(ls),  \'\', \'#4f82\']\n            break\n          }\n          return ret\n        })\n        curShape = 0\n\n        bg = new Image()\n        go=false\n        bg.onload=()=>{\n          go=true\n        }\n        bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/1XLOpt.png\'\n      }\n\n      if(go){\n        x.globalAlpha=.3\n        bgw=bg.width\n        bgh=bg.height\n        x.drawImage(bg,c.width/2-bgw/2,c.height/2-bgh/2,bgw,bgh)\n        x.globalAlpha=1\n        x.fillStyle=\'#0002\'\n        x.fillRect(0,0,c.width,c.height)\n        x.lineJoin=x.lineCap=\'round\'\n        oX=oY=0, oZ=60+S(t/3)*10\n        //Rl=S(t/6)*6,Pt=Math.max(-Math.PI/4,Math.min(Math.PI/4,C(t/2)*8))\n        //Yw=Math.max(-Math.PI/4,Math.min(Math.PI/4,S(t/2)*8))\n        Rl=S(t/12)*6,Pt=-t/8+Math.PI/2,Yw=t/4+Math.PI\n\n        shapes.map((v,i)=>{\n          drawShape(v,i)\n        })\n        pulse=true\n        if(!((t*60|0)%200)){\n          curShape = (curShape+1)%shapes.length\n          pulse=false\n        }\n\n        cur_int.map(v=>{\n          lx=v[0]-(v[3]+=v[6])\n          ly=v[1]-(v[4]+=v[7])\n          lz=v[2]-(v[5]+=v[8])\n          d=1+Math.hypot(lx,ly,lz)\n          lx/=d\n          ly/=d\n          lz/=d\n          v[6]+=lx/20\n          v[7]+=ly/20\n          v[8]+=lz/20\n          v[6]/=1.015\n          v[7]/=1.015\n          v[8]/=1.015\n          v[3]+=lx/3\n          v[4]+=ly/3\n          v[5]+=lz/3\n          X=v[3]\n          Y=v[4]\n          Z=v[5]\n          R(Rl,Pt,Yw,1)\n          if(lx+ly+lz && Z>0){\n            let s=Math.min(500, 1500/Z)\n            let l=Q()\n            x.fillStyle=\'#fff1\'\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n            s/=4\n            x.fillStyle=\'#fffa\'\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          }\n        })\n      }else{\n        x.globalAlpha=1\n        x.fillStyle=\'#000a\'\n        x.fillRect(0,0,c.width,c.height)\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'point jumper fancy', 145, 'whitehot robot', '2022-11-19 21:26:00', '', 66, '', 0, 0),
(600493, 'https://srmcgann.github.io/assets/1BsMaA.mp4', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/1KuksL.gif);\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: contain;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'pitch (gif)', 145, 'whitehot robot', '2022-11-19 21:34:45', '[600487,600481,600480,600478,600476,600472,600471,600467,600466,600463,600462,600461,600454,600453,600450,600448,600447,600445,600442,600441,600440,600439,600438,600435,600427,600420,600419,600417,600414,600412,600403,600401,600399,600391,600390,600385,600380,600367,600366,600364,600363,600360,600359,600358,600357,600356,600355,600354,600353,600288,600253,600252,600251,600248,600247]', 69, 'https://code.dweet.net/thumbs/eddc7453f0c01301983e860fae1da2ca.jpg', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600494, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*1e3,c.height/2+Y/Z*1e3]\n\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    getHSVfromRGB = (red, green, blue)=>{\n      let r_ = red//256\n      let g_ = green//256\n      let b_ = blue//256\n      let cmax=Math.max(r_, g_ , b_)\n      let cmin=Math.min(r_, g_ , b_)\n      let delta = cmax - cmin\n      let hue = 0\n      if(delta == 0)   hue = 0\n      if(cmax  == r_)  hue = (((g_-b_)/delta)%6)*60\n      if(cmax  == g_)  hue = (((b_-r_)/delta+2))*60\n      if(cmax  == b_)  hue = (((r_-g_)/delta+4))*60\n      let sat\n      if(cmax == 0) sat = 0\n      else sat = delta/cmax\n      let val = cmax\n      return [hue, sat, val]\n    }\n\n    getRGBfromHSV = (hue, sat, val) => {\n      sat=Math.max(1,sat)\n      let e_ = val * sat\n      let x_ = e_*(1-(Math.abs(((hue/60)%2)-1)))\n      let m_ = val - e_\n      let rgb = [e_, e_, e_]\n      if(hue <  60) rgb = [e_, x_, 0]\n      if(hue >= 60  && hue < 120) rgb = [e_, 0, x_]\n      if(hue >= 120 && hue < 180) rgb = [x_, e_, 0]\n      if(hue >= 180 && hue < 240) rgb = [0, e_, x_]\n      if(hue >= 240 && hue < 300) rgb = [0, x_, e_]\n      if(hue >= 300 && hue < 360) rgb = [x_, 0, e_]\n      return rgb\n    }\n\n    for(CB=[],j=6;j--;CB=[...CB,b])for(i=4,b=[];i--;)b=[...b,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),sp=2**.5/2])[j%3]*(l=j<3?1:-1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 100/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    omx=omy=mx=my=0\n    window.onkeydown=e=>{\n      if(e.keyCode==32 && matchOver) resetScores()\n    }\n    window.onmousemove=e=>{\n      let rect = c.getBoundingClientRect()\n      omx=mx\n      omy=my\n      mx = (e.pageX-rect.left)/c.clientWidth*c.width\n      my = (e.pageY-rect.top)/c.clientHeight*c.height\n    }\n\n    printText = (caption, X, Y, size, col, justify=\'left\') => {\n      x.font=size+\'px courier\'\n      x.textAlign = justify\n      x.fillStyle=col\n      caption.split(\"\\n\").map((v,i)=>{\n        x.fillText(v, X, Y+size*i)\n      })\n    }\n\n    window.onmousedown=e=>{\n      if(e.button==0) mbutton=true\n    }\n    window.onmouseup=e=>{\n      if(e.button==0) mbutton=false\n    }\n\n    iPv=0,mx=my=mbutton=0\n\n    initGame = lvl =>{\n      ls=1\n      lvlTransition=false\n      P=Array(10).fill().map((v,i)=>{\n        X=S(p=Math.PI*2/5*i+(i>=5?Math.PI:0))*ls\n        Y=sp/4\n        Z=3*(i<5?-1:1)+C(p)*ls\n        vx=(Rn()-.5)*iPv\n        vz=(Rn()-.5)*iPv\n        return [X,Y,Z,vx,0,vz,false, 0, 0, false]\n      })\n      APITimer=0\n      AIPieceSelected = -1\n      level = lvl\n    }\n    resetScores=()=>{\n      humanScore = 0\n      AIScore = 0\n      gameInPlay=true\n      matchOver=false\n      initGame(1)\n    }\n    resetScores()\n\n    doAI = () => {\n      if(lvlTransition) return\n      difficulty=level*(1/3)\n      if(AIPieceSelected == -1 && APITimer < t){\n        l=P.filter(v=>v[2]>0)\n        if(l.length){\n          AIPieceSelected = l [Rn()*l.length|0]\n        } else {\n          AIPieceSelected = -1\n        }\n      }\n      if(AIPieceSelected !== -1){\n        if(AIPieceSelected[2]<=5.35){\n          AIPieceSelected[2]+=.1+(difficulty/4)\n          AIPieceSelected[8]=true\n        }else{\n          AIPieceSelected[8]=false\n          AIPieceSelected[3]=-AIPieceSelected[0]/3.25+(Rn()-.5)/(1+difficulty/1.5**2)\n          AIPieceSelected[5]=-1.5\n          AIPieceSelected = -1\n          APITimer=t+1/(1+difficulty)\n        }\n      }\n    }\n    doVictory=wnr=>{\n      if(!lvlTransition) setTimeout(()=>{\n        if(winner){\n          AIScore++\n        }else{\n          humanScore++\n        }\n        if(Math.abs(AIScore-humanScore)>9){\n          matchOver=true\n        } else {\n          initGame(level+1)\n        }\n      }, 2000)\n      lvlTransition = true\n      x.fillStyle = wnr ? \'#400c\' : \'#041c\'\n      x.fillRect(0,0,c.width,c.height)\n      winner=wnr\n    }\n    p1col=\'#0f42\'\n    p2col=\'#ff12\'\n  }\n  x.fillStyle=\'#1028\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin=x.lineCap=\'round\'\n  oX=0\n  oY=-1\n  oZ=10\n  Yw=C(t/4)/10\n  Pt=S(t/2)/10-.5\n  Rl=0\n  \n  let size = 100\n  let caption = `M U L T I B O A R D`\n  printText(caption, 100, size, size, \'#0ff\', \'left\')\n  caption = `a game for\nEVERYONE\n\n\nOBJECTIVE`\n  size=50\n  printText(caption, 100, size*3, size, \'#fff8\', \'left\')\n  size=30\n  caption=`be the first\nto gain 10 points\non your opponent!\n`\n  printText(caption, 100, 400, size, \'#fff8\', \'left\')\n\n  printText(\'LEVEL \' + level, c.width-500,300,100,\'#0f0\', \'left\')\n  printText(\'YOUR SCORE \' + humanScore, c.width-500,550,50,\'#0f0\', \'left\')\n  printText(\'AI SCORE   \' + AIScore, c.width-500,600,50,\'#0f0\', \'left\')\n\n\n  for(m=2;m--;)CB.map((v,i)=>{\n    if((!m&&(i==0||i==2)) || (m&&(i==2||i==3)))return\n    x.beginPath()\n    v.map((q,j)=>{\n      X=q[1]*4\n      Y=q[2]*.25\n      Z=q[0]*4-4*(m?sp:-sp)\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        x.lineTo(...Q())\n      }\n    })\n    stroke(\'#ffffff08\',m?p1col:p2col)\n  })\n  for(n=2;n--;)for(m=2;m--;)CB.map((v,i)=>{\n    if((!m&&i==0) || (m&&i==3)){\n      x.beginPath()\n      v.map((q,j)=>{\n        X=(q[1]*(1+(2/3))-sp*(2+(1/3)))*(n?-1:1)\n        Y=q[2]*.25\n        Z=q[0]*4-4*(m?sp:-sp)\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          x.lineTo(...Q())\n        }\n      })\n      stroke(\'#fff1\',m?p1col:p2col)\n    }\n  })\n\n  sd=12,iPls=sp/2.53,iPh=.1\n\n  P.map((v,i)=>{\n    X=tx=tvx=v[0]\n    Y=ty=tvy=v[1]\n    Z=tz=tvz=v[2]\n    v[3]/=1.125\n    v[4]/=1.125\n    v[5]/=1.125\n    R(Rl,Pt,Yw,1)\n    v[7]=mbutton&&v[6]\n    if(!mbutton) v[6]=false\n    l=Q()\n    if(Math.hypot(mx-l[0],my-l[1])<iPls*1e3/Z && P.filter(q=>q[6]).length==0) v[6]=true\n    if(v[2]>0){\n      if(Math.abs(v[0])>.4&&v[2]+v[5]*1.01-iPls<0)v[2]=0+iPls,v[5]*=-.5,v[5]=.2\n    }else{\n      if(Math.abs(v[0])>.4&&v[2]+v[5]*1.01+iPls>0)v[2]=0-iPls,v[5]*=-.5,v[5]=.2\n    }\n    if(v[2]<0 && v[8]) v[8]=false,AIPieceSelected=-1\n    if(v[2]<0&&mbutton&&v[6]){\n      scl=.01\n      v[0]+=(mx-l[0])/99\n      v[2]-=(my-l[1])/99\n      x.beginPath()\n      x.arc(...Q(),15,0,7)\n      x.fillStyle=\'#f00\'\n      x.fill()\n    }else{\n      if(!lvlTransition){\n        tx=v[0]+=v[3]\n        ty=v[1]+=v[4]\n        tz=v[2]+=v[5]\n      }\n    }\n    if(tx>4*sp-iPls || tx<-4*sp+iPls)v[3]*=-.15\n    if(tz>8*sp-iPls || tz<-8*sp+iPls)v[5]*=-.25\n    if(v[0]-iPls<-4*sp)v[0]=-4*sp+iPls\n    if(v[0]+iPls>4*sp)v[0]=4*sp-iPls\n\n    if(v[2]-iPls<-8*sp)v[2]=-8*sp+iPls\n    if(v[2]+iPls>8*sp)v[2]=8*sp-iPls\n\n    X1=v[0]\n    Z1=v[2]\n    if(!v[6] && !v[8]){\n      d1=Math.hypot(v[3],v[5])\n      P.map((q,j)=>{\n        X2=q[0]\n        Z2=q[2]\n        if(i!=j){\n          d=Math.hypot(X1-X2,Z1-Z2)\n          d2=Math.hypot(q[3],q[5])\n          if(d<iPls*2){\n            q[3]/=1.04\n            q[5]/=1.04\n            v[3]/=1.04\n            v[5]/=1.04\n            v[0]=X2+(X1-X2)/d*iPls*2\n            v[2]=Z2+(Z1-Z2)/d*iPls*2\n            v[3]+=(X1-X2)*d2\n            v[5]+=(Z1-Z2)*d2\n            if(!q[6]){\n              q[3]-=(X1-X2)*d1\n              q[5]-=(Z1-Z2)*d1\n            }\n          }\n        }\n      })\n    }\n    if(v[2]<0 && v[7] ){\n      v[5]-=n=(my-omy)/60\n      v[3]+= -v[0]/100*(n*4)*(1+(Rn()-.5)/20)\n    }\n  })\n\n  selected = -1\n  for(m=3;m--;)P.map(v=>{\n    X=tx=v[0]\n    Y=ty=v[1]\n    Z=tz=v[2]\n    if(m<2){\n      x.beginPath()\n      for(let i=sd;i--;){\n        X=tx+S(p=Math.PI*2/sd*i)*iPls\n        Y=ty-(m?iPh:0)\n        Z=tz+C(p)*iPls\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          x.lineTo(...Q())\n        }\n      }\n      stroke(\'#fff2\', v[6]?(v[2]>0?\'#f00a\':\'#0f8a\'):(v[8]?\'#f00a\':\'#6668\'))\n    }else{\n      for(let i=sd;i--;){\n        x.beginPath()\n        X=tx+S(p=Math.PI*2/sd*i)*iPls\n        Y=ty-0\n        Z=tz+C(p)*iPls\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          x.lineTo(...Q())\n        }\n        X=tx+S(p=Math.PI*2/sd*(i+1))*iPls\n        Y=ty-0\n        Z=tz+C(p)*iPls\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          x.lineTo(...Q())\n        }\n        X=tx+S(p=Math.PI*2/sd*(i+1))*iPls\n        Y=ty-iPh\n        Z=tz+C(p)*iPls\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          x.lineTo(...Q())\n        }\n        X=tx+S(p=Math.PI*2/sd*i)*iPls\n        Y=ty-iPh\n        Z=tz+C(p)*iPls\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          x.lineTo(...Q())\n        }\n        stroke(\'#fff2\', v[6]?(v[2]>0?\'#f00a\':\'#0f8a\'):(v[8]?\'#f00a\':\'#6668\'))\n      }\n    }\n  })\n\n  let pulled = P.filter(v