= [e_, e_, e_]\n      if(hue <  60) rgb = [e_, x_, 0]\n      if(hue >= 60  && hue < 120) rgb = [e_, 0, x_]\n      if(hue >= 120 && hue < 180) rgb = [x_, e_, 0]\n      if(hue >= 180 && hue < 240) rgb = [0, e_, x_]\n      if(hue >= 240 && hue < 300) rgb = [0, x_, e_]\n      if(hue >= 300 && hue < 360) rgb = [x_, 0, e_]\n      return rgb\n    }\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n  }\n\nF=(s,Z)=>x.fillRect(960+X/Z*(h=540)-(s/=Z)/2,h+Y/Z*h-s/2,s,s)\nfor(F(i=c.width|=X=Y=0,1);i--;){\n  X=((i**3.1+S(t/4)*50)%(G=200))-99\n  Y=(i**4.1+t*8)%99-50\n  Z=i/25\n  x.fillStyle=\'#fff2\'\n  F(G*8,Z)\n  x.fillStyle=\'#fff\'\n  F(G,Z)\n}\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'snow dweet', 145, 'whitehot robot', '2022-12-02 16:29:46', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 20, '', 0, 1);
