(600504, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=to=0\n\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth/document.body.clientWidth < 1.7777778)\n    {\n      c.style.width  = document.body.clientWidth + \'px\'\n      c.style.height = (document.body.clientWidth/1.777777778) + \'px\'\n    }else{\n      c.style.height = document.body.clientHeight + \'px\'\n      c.style.width  = (document.body.clientHeight*1.777777778) + \'px\'\n    }\n    c.width  = 1920\n    c.height = 1080\n  },0)\n}\nrsz()\n\nDraw=()=>{\n\n  if(!t){\n    Rn = Math.random\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      if(m){\n        X+=oX,Y+=oY,Z+=oZ\n      }\n      X+=960\n      Y+=540\n    }\n    Q=q=>[c.width/2+(X-960)/Z*700,c.height/2+(Y-540)/Z*700]\n    for(CB=[],j=6;j--;CB=[...CB,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.strokeStyle=scol\n        x.closePath()\n        x.globalAlpha=.05\n        x.lineWidth=Math.min(500, 200/Z)\n        x.stroke()\n        x.lineWidth/=4\n        x.globalAlpha=1\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    cl = 26\n    rw = cl*3.2|0\n    rad = 3**.5/3\n    sp=1, maxv=3\n    b=[]\n    Array(cl*rw).fill().map((v,i)=>{\n      tx=(((i%cl)-cl/2+.5)*sp+((i/cl|0)%2?sp/2:0))*1.75\n      ty=((i/cl|0)-rw/2+.5)*sp/2\n      tz=0\n      if(Math.hypot(tx,ty)<cl*.6){\n        a=[]\n        for(j=6;j--;){\n          X=tx+S(p=Math.PI*2/6*j+Math.PI/6)*rad\n          Y=ty+C(p)*rad\n          Z=tz\n          a=[...a, [X,Y,Z,X,Y,Z,tx,ty,tz]]\n        }\n        b=[...b, a]\n      }\n    })\n    b.map((v,i)=>{\n      v.map((q,j)=>{\n        a=[]\n        X1=q[0]\n        Y1=q[1]\n        Z1=q[2]\n        b.map((k,l)=>{\n          if(l!=i){\n            k.map((n,m)=>{\n              X2=n[0]\n              Y2=n[1]\n              Z2=n[2]\n              if(Math.hypot(X1-X2,Y1-Y2,Z1-Z2)<.01){\n                a=[...a, [l,m]]\n              }\n            })\n          }\n        })\n        q[9] = a\n        q[10]=0\n        q[11]=0\n        q[12]=0\n      })\n    })\n    B=b\n    elasticity = 25, inertia=.5\n\n    P = [], iPv = 3, iPs = 5\n    spawnP = () => {\n      X = 0\n      Y = 0\n      Z = -50\n      vx = (Rn()-.5)*iPv/3\n      vy = (Rn()-.5)*iPv/3\n      vz = iPv\n      a = [ X, Y, Z, vx, vy, vz, 1]\n      P = [...P, a]\n    }\n\n    star = new Image()\n    star.src = \'proxy.php?url=https://srmcgann.github.io/temp/stars/star1.png\'\n    bg = new Image()\n    go=false\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/1IwVSv.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha = .2\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha = 1\n    x.fillStyle=\'#0003\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=0, oY=0, oZ=cl\n    Rl=C(t/2)/4, Pt=S(t)/1.5, Yw=S(t)*1.6\n    x.lineJoin=x.lineCap=\'round\'\n\n    if(!((t*60|0)%10)) spawnP()\n\n    B.map(v=>{\n      v.map((q,j)=>{\n        q[9].map(n=>{\n          el = B[n[0]][n[1]]\n          X = el[3]\n          Y = el[4]\n          Z = el[5]\n          q[10] += (X-q[3])/2\n          q[11] += (Y-q[4])/2\n          q[12] += (Z-q[5])/2\n        })\n        X1=q[3]\n        Y1=q[4]\n        Z1=q[5]\n        P.map(n=>{\n          X2=n[0]\n          Y2=n[1]\n          Z2=n[2]\n          if((d=Math.hypot(X1-X2,Y1-Y2,Z1-Z2))<iPs){\n            q[3]=X2+(X1-X2)/d*iPs\n            q[4]=Y2+(Y1-Y2)/d*iPs\n            q[5]=Z2+(Z1-Z2)/d*iPs\n            q[10]+=(X1-X2)/d*iPs/8\n            q[11]+=(Y1-Y2)/d*iPs/8\n            q[12]+=(Z1-Z2)/d*iPs/8\n            n[3]-=(X1-X2)/d/100\n            n[4]-=(Y1-Y2)/d/100\n            n[5]-=(Z1-Z2)/d/100\n          }\n          if((d=Math.hypot(q[6]-X2,q[7]-Y2,q[8]-Z2))<iPs){\n            q[6]=X2+(q[6]-X2)/d*iPs\n            q[7]=Y2+(q[7]-Y2)/d*iPs\n            q[8]=Z2+(q[8]-Z2)/d*iPs\n          }\n        })\n      })\n      cx=cy=cz=0\n      v.map((q,j)=>{\n        X1 = q[6]\n        Y1 = q[7]\n        Z1 = q[8]\n        X2 = q[3]\n        Y2 = q[4]\n        Z2 = q[5]\n        d = Math.hypot(X1-X2,Y1-Y2,Z1-Z2)\n        X = X1 + (X2-X1)/d*rad\n        Y = Y1 + (Y2-Y1)/d*rad\n        Z = Z1 + (Z2-Z1)/d*rad\n        q[3] += (X-q[3])/elasticity*30\n        q[4] += (Y-q[4])/elasticity*30\n        q[5] += (Z-q[5])/elasticity*30\n        q[10] += (q[0]-q[3])/elasticity/3\n        q[11] += (q[1]-q[4])/elasticity/3\n        q[12] += (q[2]-q[5])/elasticity/3\n        cx+=q[3]\n        cy+=q[4]\n        cz+=q[5]\n        q[10]=Math.max(-maxv, Math.min(maxv, q[10]))\n        q[11]=Math.max(-maxv, Math.min(maxv, q[11]))\n        q[12]=Math.max(-maxv, Math.min(maxv, q[12]))\n        q[3]+=q[10]/=1.4\n        q[4]+=q[11]/=1.4\n        q[5]+=q[12]/=1.4\n      })\n      cx/=6\n      cy/=6\n      cz/=6\n      v.map(q=>{\n        q[6]=cx\n        q[7]=cy\n        q[8]=cz\n      })\n\n      x.beginPath()\n      v.map(q=>{\n        X = q[3]\n        Y = q[4]\n        Z = q[5]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n      })\n      stroke(\'#0f84\', \'#50f2\')\n    })\n\n    P=P.filter(v=>v[6]>0)\n\n    P.map(v=>{\n      X=v[0]+=v[3]\n      Y=v[1]+=v[4]\n      Z=v[2]+=v[5]\n      v[6]-=.035\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s=Math.min(1e3, 4e4/Z)\n        l=Q()\n        x.globalAlpha=Math.max(0, (1-(1-v[6])**6)*.8)\n        x.drawImage(star,l[0]-s/2,l[1]-s/2,s,s)\n      }\n    })\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'wave maker', 145, 'whitehot robot', '2023-01-05 01:31:40', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 20, '', 0, 1),
(600505, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/K4PnO.gif);\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: contain;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'wave maker (gif)', 145, 'whitehot robot', '2023-01-05 22:20:34', '[600503,600502,600497,600496,600493,600487,600481,600480,600478,600476,600472,600471,600467,600466,600463,600462,600461,600454,600453,600450,600448,600447,600445,600442,600441,600440,600439,600438,600435,600427,600420,600419,600417,600414,600412,600403,600401,600399,600391,600390,600385,600380,600367,600366,600364,600363,600360,600359,600358,600357,600356,600355,600354,600353,600288,600253,600252,600251,600248,600247]', 52, '', 0, 0),
(600506, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*1400,c.height/2+Y/Z*1400]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.strokeStyle=\'#f001\'\n        x.lineWidth=Math.min(500, 1600/Z)\n        x.stroke()\n        x.strokeStyle=`#faaa`\n        x.lineWidth/=10\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    rw=34, cl=34, sp=1\n    B=Array(rw*cl).fill().map((v,i)=>{\n      X=((i%cl)-cl/2)*sp\n      Y=0\n      Z=(((i/cl|0)%rw)-rw/2)*sp\n      return [X,Y,Z]\n    })\n    bg=new Image()\n    go=false\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/13N4IN.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.3\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0003\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=0, oY=-4, oZ=35\n    Rl=0,Pt=-.75,Yw=-t/12\n    x.lineJoin=x.lineCap=\'round\'\n\n    segres=5\n\n    getFloor=(X,Z)=>{\n      d1=d=Math.hypot(X,Z)/1.1\n      d+=Math.atan2(X,Z)*2\n      return Math.min(0,(.1+S(d-t*3))**3*2/Math.max(1, ((d1/11)**99)))\n    }\n\n    Seg=(X1,Y1,Z1,X2,Y2,Z2) => {\n      for(let m=segres+1;m--;){\n        X=X1+(X2-X1)/segres*m\n        Z=Z1+(Z2-Z1)/segres*m\n        Y=getFloor(X,Z)\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n      }\n    }\n\n    B.map((v,i)=>{\n      if(i>cl && i%cl && i%cl){\n        l=i\n        X1=B[l][0]\n        Y1=B[l][1]\n        Z1=B[l][2]\n        l=i-cl\n        X2=B[l][0]\n        Y2=B[l][1]\n        Z2=B[l][2]\n        X=(X1+X2)/2\n        Y=(Y1+Y2)/2\n        Z=(Z1+Z2)/2\n        d=Math.hypot(X,Y,Z)\n        if(d>17) return\n        x.globalAlpha=1/(1+d**20/5e22)\n\n        if(i%cl!=1){\n          x.beginPath()\n          l=i\n          X1=B[l][0]\n          Y1=B[l][1]\n          Z1=B[l][2]\n          l=i-1\n          X2=B[l][0]\n          Y2=B[l][1]\n          Z2=B[l][2]\n          Seg(X1,Y1,Z1,X2,Y2,Z2)\n          stroke(\'#fff4\')\n        }\n\n        if((i/cl|0)!=1){\n          x.beginPath()\n          l=i\n          X1=B[l][0]\n          Y1=B[l][1]\n          Z1=B[l][2]\n          l=i-cl\n          X2=B[l][0]\n          Y2=B[l][1]\n          Z2=B[l][2]\n          Seg(X1,Y1,Z1,X2,Y2,Z2)\n          stroke(\'#fff\')\n        }\n      }\n    })\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'flat spiral', 145, 'whitehot robot', '2023-01-05 23:43:41', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 41, '', 0, 0);
