y=(Rn()-.5)*GY\n    tz=(Rn()-.5)*GZ\n    B.map((v,i)=>{\n      X=v[0]\n      Y=v[1]\n      Z=v[2]\n      //if((d=1+Math.hypot(X-tx,Y-ty,Z-tz))<rad){\nd=50+Math.hypot(X-tx,Y-ty,Z-tz)\n        v[6]-=(tx-X)*2E17/d**9\n        v[7]-=(ty-Y)*2E17/d**9\n        v[8]-=(tz-Z)*2E17/d**9\n      //}\n    })\n  }\n  \n  iBv = 6\n  B.map((v,i)=>{\n    v[6]/=1.3\n    v[7]/=1.3\n    v[8]/=1.3\n    v[6]+=(v[3]-v[0])/50\n    v[7]+=(v[4]-v[1])/50\n    v[8]+=(v[5]-v[2])/50\n    d1=Math.hypot(v[6],v[7],v[8])\n    d=Math.min(maxv, d1)\n    v[6]/=d1\n    v[7]/=d1\n    v[8]/=d1\n    v[6]*=d\n    v[7]*=d\n    v[8]*=d\n    v[0]+=v[6]\n    v[1]+=v[7]\n    v[2]+=v[8]\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    if(v[1]>GY/2) v[4]-=GY, v[1]-=GY\n    if(X>GX/2)X-=GX,v[0]-=GX,v[3]-=GX\n    if(X<-GX/2)X+=GX,v[0]+=GX,v[3]+=GX\n    if(Z>GZ/2)Z-=GZ,v[2]-=GZ,v[5]-=GZ\n    if(Z<-GZ/2)Z+=GZ,v[2]+=GZ,v[5]+=GZ\n    v[4]+=iBv\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    if(Math.hypot(X,Z)<GX/2){\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s=Math.min(500, 8e4/Z**1.5)\n        l=Q()\n        x.globalAlpha=.02\n        x.fillStyle=`hsla(${v[9]},99%,${50+70/B.length*i}%,1)`\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=12\n        x.globalAlpha=1\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n    }\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'cheese 4', 145, 'whitehot robot', '2023-01-06 02:20:15', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 14, 'http://img.youtube.com/vi/cz0OckKCbK0/0.jpg', 0, 1),
