     })\n      d=Math.hypot(tx,ty,tz)\n      tx/=d\n      ty/=d\n      tz/=d\n      v[0]=tx\n      v[1]=ty\n      v[2]=tz\n    })\n  }\n\n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n  oX=oY=0, oZ=2\n  Rl=0,Pt=0,Yw=t\n  \n  B.map((v,i)=>{\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      s=Math.min(500,150/Z)\n      l=Q()\n      x.fillStyle=\'#ffffff02\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      s/=8\n      x.fillStyle=\'#fff\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n    }\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'shape ψ', 145, 'whitehot robot', '2023-01-06 16:15:00', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 12, '', 0, 1),
(600510, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    iBc = 70\n    B=Array(iBc).fill().map((v,i)=>{\n      X = Rn()-.5\n      Y = Rn()-.5\n      Z = Rn()-.5\n      return [X,Y,Z]\n    })\n    for(m=100;m--;) B.map(v=>{\n      tx = v[0]\n      ty = v[1]\n      tz = v[2]\n      B.map(q=>{\n        X=q[0]\n        Y=q[1]\n        Z=q[2]\n        d=5000+((Math.hypot(X-tx,Y-ty,Z-tz))*100)**3\n        tx+=(tx-X)*1e3/d\n        ty+=(ty-Y)*1e3/d\n        tz+=(tz-Z)*1e3