\n        v.map(q=>{\n          q[2]+=ang=1.538840639715\n        })\n      })\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI,0,Math.PI)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      b=JSON.parse(JSON.stringify(e)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI/2,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        //x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 1000/Z)\n        //x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=10\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n    ls=6,rw=3,cl=3,br=1, sp_=ls*3\n    shapes = Array(rw*cl*br).fill().map((v,i)=>{\n      switch(id=Rn()*6|0){\n        case 0: shp = Sphere(ls,6,4); break\n        case 1: shp = Tetrahedron(ls); break\n        case 2: shp = Cube(ls); break\n        case 3: shp = Octahedron(ls); break\n        case 4: shp = Dodecahedron(ls); break\n        case 5: shp = Icosahedron(ls); break\n      }\n      X = ((i%cl)-cl/2+.5)*sp_\n      Y = (((i/cl|0)%rw)-rw/2+.5)*sp_\n      Z = ((i/cl/rw|0)-br/2+.5)*sp_\n      return [X,Y,Z, shp, id]\n    })\n    P = []\n    go=false\n    bg=new Image()\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/23Zhj2.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.4\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0003\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=oY=0, oZ=30+C(t)*20\n    Rl=t/6,Pt=-S(t/3)/2,Yw=S(t/4)*6\n    x.lineJoin=x.lineCap=\'butt\'\n\n    showNormals = true\n    shapes.map((shape, N)=>{\n      tx_=shape[0]\n      ty_=shape[1]\n      tz_=shape[2]\n      shape[3].map((v,i)=>{\n        x.beginPath()\n        cx=cy=cz=0\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          cx+=X\n          cy+=Y\n          cz+=Z\n          R(0, -t/2*(N%2?-1:1), N+t)\n          X+=tx_\n          Y+=ty_\n          Z+=tz_\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n        })\n        stroke(\'#8fc4\', \'#40f1\')\n        tx=X=cx/=v.length\n        ty=Y=cy/=v.length\n        tz=Z=cz/=v.length\n        p1=Math.atan2(X,Z)\n        p2=Math.acos(Y/Math.hypot(X,Y,Z))\n        x.beginPath()\n        X=tx\n        Y=ty\n        Z=tz\n        R(0, -t/2*(N%2?-1:1), N+t)\n        X+=tx_\n        Y+=ty_\n        Z+=tz_\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        X=tx+S(p1)*S(p2)*2\n        Y=ty+C(p2)*2\n        Z=tz+C(p1)*S(p2)*2\n        R(0, -t/2*(N%2?-1:1), N+t)\n        X+=tx_\n        Y+=ty_\n        Z+=tz_\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        if(showNormals) stroke(\'#0f0a\')\n        v_ = v.map((q,j)=>{\n          X=q[0]-tx\n          Y=q[1]-ty\n          Z=q[2]-tz\n          shape[4]==2?R(0,Math.PI/2-p2,-p1+Math.PI):R(0,-Math.PI/2-p2,-p1+Math.PI)\n          return [X,Y,Z]\n        })\n        v_.map((q,j)=>{\n          X1=q[0]\n          Y1=q[1]\n          Z1=q[2]\n          X2=v_[(j+1)%v_.length][0]\n          Y2=v_[(j+1)%v_.length][1]\n          Z2=v_[(j+1)%v_.length][2]\n          for(m=1;m--;){\n            X3=0\n            Y3=0\n            Z3=0\n            X4=S(p=Math.PI*2*Rn())*10\n            Y4=C(p)*10\n            Z4=0\n            if((pt=I(X1,Y1,X2,Y2,X3,Y3,X4,Y4))){\n              X=(l=Rn()**.5)*pt[0]\n              Y=l*pt[1]\n              Z=0\n              R2(0,Math.PI/2+p2,p1+Math.PI+(shape[4]==2&&(i==1||i==4)?.92*(i==1?1:-1):0))\n              X+=tx\n              Y+=ty\n              Z+=tz\n              P=[...P, [X,Y,Z,1,tx_,ty_,tz_,N]]\n            }\n          }\n        })\n      })\n    })\n    P=P.filter(v=>v[3]>0)\n    P.map(v=>{\n      X=v[0]\n      Y=v[1]\n      Z=v[2]\n      v[3]-=.1\n      x.globalAlpha=Math.max(0,v[3])**.2\n      R(0,-t/2*(v[7]%2?-1:1),v[7]+t)\n      X+=v[4]\n      Y+=v[5]\n      Z+=v[6]\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s=Math.min(1e3, 600/Z)\n        x.fillStyle=\'#0ff2\'\n        l=Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=6\n        x.fillStyle=\'#fff\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n    })\n  }\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'sparklehedrons', 145, 'whitehot robot', '2023-01-06 22:29:16', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 51, '', 0, 0),
(600517, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/1H1yZ0.gif);\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: contain;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'sparklehedrons (gif)', 145, 'whitehot robot', '2023-01-07 02:42:19', '[600515,600513,600511,600508,600505,600503,600502,600497,600496,600493,600487,600481,600480,600478,600476,600472,600471,600467,600466,600463,600462,600461,600454,600453,600450,600448,600447,600445,6004