(600518, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n\n    P=[]\n    iPv=2\n    star1 = new Image()\n    star2 = new Image()\n    star1.src=\'proxy.php?url=https://srmcgann.github.io/temp/stars/star5.png\'\n    star2.src=\'proxy.php?url=https://srmcgann.github.io/temp/stars/star1.png\'\n    bg=new Image()\n    go=false\n    bg.onload = () => {\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/1tJK1Y.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.4\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0002\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=oY=0, oZ=150+S(t)*50\n    Rl=Math.PI/2,Pt=-S(t/6)*8,Yw=t/4\n\n    for(m=6;m--;){\n      iBc=50, ix=iy=iz=0\n      B=Array(iBc).fill().map((v,i)=>{\n        X = S(p=Math.PI*2/iBc*i+(m%2?-1:1)*t*4+m)*30\n        Y = (i/iBc-.5)*200\n        Z = (-3+m)*40\n        if(!i)ix=X, iy=Y, iz=Z\n        return [X,Y,Z]\n      })\n\n      P.map(v=>{\n        if(v[7]==m){\n          tx=v[0]\n          ty=v[1]\n          tz=v[2]\n          B.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            d=600+(1+Math.hypot(tx-X,ty-Y,tz-Z))**4\n            v[3]-=(tx-X)/d*100\n            v[4]-=(ty-Y)/d*100\n            v[5]-=(tz-Z)/d*100\n          })\n          X = v[0]+=v[3]\n          Y = v[1]+=v[4]+=.1\n          Z = v[2]+=v[5]\n          v[3]/=1.02\n          v[4]/=1.02\n          v[5]/=1.02\n          v[6]-=.006\n          tx=X, ty=Y,tz=Z\n          X=tx\n          Y=ty\n          Z=tz\n          R(Rl,Pt,Yw,1)\n          if(Z>0){\n            l=Q()\n            x.globalAlpha=.5\n            s=Math.min(1e3,4e4/Z)\n            x.drawImage(star1,l[0]-s/2,l[1]-s/2,s,s)\n            s/=1.5\n            x.globalAlpha=1\n            x.drawImage(star2,l[0]-s/2,l[1]-s/2,s,s)\n          }\n        }\n      })\n      x.globalAlpha=1\n\n      B.map(v=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          l=Q()\n          s=Math.min(1e3,8e3/Z)\n          x.fillStyle=\'#4400ff06\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          s/=10\n          x.fillStyle=\'#8ff\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        }\n      })\n\n      if(!((t*60|0)%4)) P=[...P, [ix-1, iy, iz, iPv, 0, 0, 1, m]]\n      P=P.filter(v=>v[6]>0)\n    }\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'gravity strings', 145, 'whitehot robot', '2023-01-07 15:21:07', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 56, '', 0, 0);
