ub.io/assets/WuP3u.png\'\n    ball2 = new Image()\n    ball2.src=\'proxy.php?url=https://srmcgann.github.io/assets/15Z7FA.png\'\n\n    P=[], iPv=20, iPs_=200, iPfreq=6\n    spawnP=()=>{\n      iPs=16+Rn()**5*(iPs_-16)\n      X = -300\n      ls=Rn()*100\n      Y = S(p=Math.PI*2*Rn())*ls\n      Z = C(p)*ls\n      vx = iPv\n      vy = 0\n      vz = 0\n      P=[...P, [X,Y,Z,X,Y,Z,vx,vy,vz,1,iPs]]\n    }\n    bg=new Image()\n    go=false\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/2e6372.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.3\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0003\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=oY=0, oZ=200+S(t)*50\n    Rl=S(t/2)/3,Pt=S(t/2)/8,Yw=(-C(t/4)-Math.PI/2)*1.25\n\n    if(!((t*60|0)%iPfreq))spawnP()\n\n    a=[]\n    B.map((v,i)=>{\n      X1=v[0]\n      Y1=v[1]\n      Z1=v[2]\n      P.map(q=>{\n        X2=q[0]\n        Y2=q[1]\n        Z2=q[2]\n        if((d=Math.hypot(X1-X2,Y1-Y2,Z1-Z2))<(q[10]+iBs)/2*1.2){\n          v[0]=X2+(X1-X2)/d*(q[10]+iBs)/2*1.2\n          v[1]=Y2+(Y1-Y2)/d*(q[10]+iBs)/2*1.2\n          v[2]=Z2+(Z1-Z2)/d*(q[10]+iBs)/2*1.2\n            v[6]+=(X1-X2)/d*6\n            v[7]+=(Y1-Y2)/d*2\n            v[8]+=(Z1-Z2)/d*2\n        }\n      })\n      B.map((q,j)=>{\n        if(j!=i){\n          X2=q[0]\n          Y2=q[1]\n          Z2=q[2]\n          if((d=Math.hypot(X1-X2,Y1-Y2,Z1-Z2))<iBs){\n            v[0]=X2+(X1-X2)/d*iBs\n            v[1]=Y2+(Y1-Y2)/d*iBs\n            v[2]=Z2+(Z1-Z2)/d*iBs\n            v[6]+=(X1-X2)/d/500\n            v[7]+=(Y1-Y2)/d/500\n            v[8]+=(Z1-Z2)/d/500\n          }\n        }\n      })\n      v[6]+=(v[3]-v[0])/150\n      v[7]+=(v[4]-v[1])/150\n      v[8]+=(v[5]-v[2])/150\n      X=v[0]+=v[6]\n      Y=v[1]+=v[7]\n      Z=v[2]+=v[8]\n      v[6]/=1.1\n      v[7]/=1.1\n      v[8]/=1.1\n      R(Rl,Pt,Yw,1)\n      a=[...a, [Z,i]]\n    })\n    a.sort((a,b)=>b[0]-a[0])\n    x.globalAlp