(600538, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\"\n}\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    playing = false\n    fftSize = 64\n    setupAnalyser = () => {\n      showAnalyser = 1\n      mp3 = new Audio()\n      mp3.src = \'proxy.php?url=https://play.rotoblaster.com/roadtrip/tracks/The%20Princess%20and%20the%20Warrior%3A%20Touched.mp3\'\n      mp3.oncanplay = () => {\n        if(!playing){\n          playing = true\n          audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n          analyser = audioCtx.createAnalyser()\n          analyser.fftSize = fftSize\n          source = audioCtx.createMediaElementSource(mp3)\n          source.connect(analyser)\n          analyser.connect(audioCtx.destination)\n          mp3.loop = true\n          mp3.play()\n        }\n      }\n    }\n    setupAnalyser()\n\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n  }\n\n  x.fillStyle=\'#111c\'\n  x.fillRect(0,0,c.width,c.height)\n  oX=oY=0, oZ=10\n  Rl=0,Pt=0,Yw=0\n  x.lineJoin=x.lineCap=\'round\'\n\n  if(playing){\n\n    frequencyData = new Uint8Array();\n    analyser.getByteFrequencyData(frequencyData);\n    dataArray = new Uint8Array(analyser.frequencyBinCount)\n    analyser.getByteFrequencyData(dataArray)\n    data = dataArray\n    B=Array(data.length).fill().map((v,i)=>{\n      return data[i/(1.5+fftSize**.25/30)|0]/255\n    })\n\n    if(showAnalyser){\n      let cl = data.length\n      let s = c.width/data.length/1.1|0\n      for(i=0; i<data.length;i+=1){\n        j = cl / data.length * i | 0\n        X = c.width/cl*i\n        val = -(data[j/(1.5+fftSize**.25/30)|0])/255 * 800\n        Y = val\n        Z = 0\n        x.fillStyle = `hsla(${0},0%,${-val/255*40}%,1)`\n        x.fillRect(X, 1000, s, Y-10)\n      }\n    }\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'new temp [audio analyser]', 145, 'whitehot robot', '2023-01-12 17:54:19', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 75, '', 0, 1),
