)**4\n            X+=(X-X2)*5/d\n            Y+=(Y-Y2)*5/d\n            Z+=(Z-Z2)*5/d\n          }\n        })\n        d=Math.hypot(X,Y,Z)\n        X/=d\n        Y/=d\n        Z/=d\n        v[0]=X\n        v[1]=Y\n        v[2]=Z\n      })\n    }\n  }\n\n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n  oX=oY=0, oZ=3\n  Rl=0,Pt=0,Yw=t\n  \n  B.map(v=>{\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      l=Q()\n      s=Math.min(500,50/Z)\n      x.fillStyle=\'#fff2\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      s/=3\n      x.fillStyle=\'#fffa\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n    }\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'geosphere', 145, 'whitehot robot', '2023-01-13 15:33:53', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 45, '', 0, 0),
(600543, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    // [geosphere]\n\n    iBc = 200, collapse=1\n    B=Array(iBc).fill().map(v=>{\n      X = Rn()-.5\n      Y = Rn()-.5\n      Z = Rn()-.5\n      return  [X,Y,Z]\n    })\n    render = () => {\n      for(m=20;m--;){\n        B.map((v,i)=>{\n          X = v[0]\n          Y = v[1]\n          Z = v[2]\n          B.map((q,j)=>{\n            if(j!=i){\n              X2=q[0]\n              Y2=q[1]\n              Z2=q[2]\n              d=1+(Math.hypot(X-X2,Y-Y2,Z-Z2)*(3+iBc/30)*3)**4\n              X+=(X-X2)*99/d\n              Y+=(Y-Y2)*99/d\n              Z+=(Z-Z2)*99/d\n            }\n          })\n          d=Math.hypot(X,Y,Z)\n          v[0]=X/d\n          v[1]=Y/d\n          v[2]=Z/d\n          if(collapse){\n            d=25+Math.hypot(X,Y,Z)\n            v[0]=(X-X/d)/1.1\n            v[1]=(Y-Y/d)/1.1\n            v[2]=(Z-Z/d)/1.1\n          }\n        })\n      }\n    }\n    render()\n  }\n\n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n  oX=oY=0, oZ=3//+S(t*2)*2\n  Rl=0,Pt=0,Yw=t/4\n\n  \n  B.map(v=>{\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      l=Q()\n      s=Math.min(500,100/Z)\n      x.fillStyle=\'#fff2\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      s/=3\n      x.fillStyle=\'#fffa\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n    }\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'collapsible geosphere', 145, 'whitehot robot', '2023-01-13 16:14:13', '[600542,600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 44, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600544, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n}\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        //x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 1e3/Z)\n        //x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=10\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    // [geosphere]\n\n    geoSphere = (mx, my, mz, iBc, size) => {\n      let collapse=0\n      let B=Array(iBc).fill().map(v=>{\n        X = Rn()-.5\n        Y = Rn()-.5\n        Z = Rn()-.5\n        return  [X,Y,Z]\n      })\n      for(let m=99;m--;){\n        B.map((v,i)=>{\n          X = v[0]\n          Y = v[1]\n          Z = v[2]\n          B.map((q,j)=>{\n            if(j!=i){\n              X2=q[0]\n              Y2=q[1]\n              Z2=q[2]\n              d=1+(Math.hypot(X-X2,Y-Y2,Z-Z2)*(3+iBc/40)*3)**4\n              X+=(X-X2)*99/d\n              Y+=(Y-Y2)*99/d\n              Z+=(Z-Z2)*99/d\n            }\n          })\n          d=Math.hypot(X,Y,Z)\n          v[0]=X/d\n          v[1]=Y/d\n          v[2]=Z/d\n          if(collapse){\n            d=25+Math.hypot(X,Y,Z)\n            v[0]=(X-X/d)/1.1\n         \n            v[2]=(Z-Z/d)/1.1\n          }\n        })\n      }\n      B.map(v=>{\n        v[0]*=size\n        v[1]*=size\n        v[2]*=size\n        v[0]+=mx\n        v[1]+=my\n        v[2]+=mz\n      })\n      return [mx, my, mz, size, B]\n    }\n    \n    size = 1\n    Geo = geoSphere(0,0,0,120,size)\n    mind = 6e6\n    Geo[4].map((q,j)=>{\n      X1=q[0]\n      Y1=q[1]\n      Z1=q[2]\n      Geo[4].map((e,f)=>{\n        if(f!=j){\n          X2=e[0]\n          Y2=e[1]\n          Z2=e[2]\n          if((d=Math.hypot(X2-X1,Y2-Y1,Z2-Z1))<mind) mind=d\n        }\n      })\n    })\n\n    rGeo = (lx, ly, lz, size) => {\n      let tg = JSON.parse(JSON.stringify(Geo))\n      return [lx,ly,lz,tg[3],tg[4].map((v,i)=>{\n        X = v[0]*=size\n        Y = v[1]*=size\n        Z = v[2]*=size\n        //R(t*2,-t*2,t)\n        v[0] = X+lx\n        v[1] = Y+ly\n        v[2] = Z+lz\n        return v\n      })]\n    }\n    ls = 0, sd = 3\n    render = () => {\n      ols=ls\n      ls = 10+S(t)*10\n      if(ols<.1 && ols>ls && ls < 10)sd = 2+Rn()*10|0\n      size = 12\n      shapes=[], P=[]\n      for(let m = sd;m--;) shapes = [...shapes, rGeo(S(p=Math.PI*2/sd*m)*ls,C(p)*ls,0, size)]\n      shapes.map((n,m)=>{\n        X1 = n[0]\n        Y1 = n[1]\n        Z1 = n[2]\n        shapes.map((k,l)=>{\n          if(l!=m){\n            k[4] = k[4].filter(q=>{\n              X2=q[0]\n              Y2=q[1]\n              Z2=q[2]\n              if((d=Math.hypot(X2-X1,Y2-Y1,Z2-Z1))<(k[3]+n[3])/2*size)return false\n              return true\n            })\n          }\n        })\n      })\n\n      P=[]\n      shapes.map((n,m)=>{\n        n[4].map((q,j)=>{\n          X1=q[0]\n          Y1=q[1]\n          Z1=q[2]\n          shapes.map((k,l)=>{\n            k[4].map((e,f)=>{\n              if(l==m){\n                if(f!=j){\n                  X2=e[0]\n                  Y2=e[1]\n                  Z2=e[2]\n                  if(Math.hypot(X2-X1,Y2-Y1,Z2-Z1)<mind*size*1.63){\n                    P=[...P, [X1,Y1,Z1,X2,Y2,Z2]]\n                  }\n                }\n              }else{\n                X2=e[0]\n                Y2=e[1]\n                Z2=e[2]\n                if(Math.hypot(X2-X1,Y2-Y1,Z2-Z1)<mind*size*1.63){\n                  P=[...P, [X1,Y1,Z1,X2,Y2,Z2]]\n                }\n              }\n            })\n          })\n        })\n      })\n    }\n    bg = new Image()\n    go=false\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/17vAGx.jpg\'\n    star = new Image()\n    star.src=\'proxy.php?url=https://srmcgann.github.io/temp/stars/star7.png\'\n  }\n\n  if(go){\n    x.globalAlpha=.5\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0008\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=oY=0, oZ=24\n    Rl=S(t/4)*2,Pt=S(t)*3,Yw=t/6\n    x.lineJoin=x.lineCap=\'butt\'\n    \n    render()\n\n    if(1)shapes.map(n=>{\n      n[4].map(v=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          l=Q()\n          s=Math.min(500,2000/Z)\n          x.globalAlpha=.8\n          x.drawImage(star,l[0]-s/2,l[1]-s/2,s,s)\n          /*x.fillStyle=\'#fff2\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          s/=3\n          x.fillStyle=\'#fffa\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)*/\n        }\n      })\n    })\n\n    if(1)P.map(v=>{\n        x.beginPath()\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        X=v[3]\n        Y=v[4]\n        Z=v[5]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        stroke(\'#3f82\')\n    })\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'meta shapes', 145, 'whitehot robot', '2023-01-13 19:16:26', '[600543,600542,600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 47, '', 0, 0),
