= [e_, e_, e_]\n      if(hue <  60) rgb = [e_, x_, 0]\n      if(hue >= 60  && hue < 120) rgb = [e_, 0, x_]\n      if(hue >= 120 && hue < 180) rgb = [x_, e_, 0]\n      if(hue >= 180 && hue < 240) rgb = [0, e_, x_]\n      if(hue >= 240 && hue < 300) rgb = [0, x_, e_]\n      if(hue >= 300 && hue < 360) rgb = [x_, 0, e_]\n      return rgb\n    }\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    vid = document.createElement(\'video\')\n    vid.muted = true\n    vid.loop = true\n    vid.defaultPlaybackRate=1\n    go = false\n    vid.oncanplay=()=>{\n      vid.play()\n      go = true\n      buffer = document.createElement(\'canvas\')\n      res = .06\n      lumThreshold = 60\n      buffer.width = vid.videoWidth*res\n      buffer.height= vid.videoHeight*res\n      bctx = buffer.getContext(\'2d\', {willReadFrequently: true})\n    }\n    vid.src=\'proxy.php?url=https://srmcgann.github.io/assets/1BT7cU.mp4\'\n    B = []\n    star = new Image()\n    star.src = \'proxy.php?url=https://srmcgann.github.io/temp/stars/star2.png\'\n    bg = new Image()\n    go=false\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src = \'proxy.php?url=https://srmcgann.github.io/assets/pH05g.jpg\'\n  }\n\n\n  if(go){\n    x.globalAlpha = .5\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.fillStyle=\'#0003\'\n    x.globalAlpha = 1\n    x.fillRect(0,0,c.width,c.height)\n    bctx.drawImage(vid,0,0,w=buffer.width|0,h=buffer.height|0)\n    data = bctx.getImageData(0,0,w,h)\n\n    iBv = .35\n    if(!((t*60|0)%20)){\n      X  = -15\n      Y  = 0\n      Z  = 0\n      vx = iBv\n      vy = (Rn()-.5)*iBv\n      vz = 0\n      iBr = (.3+Rn())*1.25\n      B = [...B, [X, Y, Z, vx, vy, vz, 1, iBr]]\n    }\n\n    l = data.