  Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n\n        ret = [...ret, a]\n      }\n      return ret\n    }\n\n    Tetrahedron=ls=>{\n      let ret=[]\n      let a = []\n      let theta=1.2217304763960306\n      for(let i=3;i--;){\n        X=S(p=Math.PI*2/3*i)\n        Y=C(p)+.5\n        Z=0\n        R2(0,-theta/2,0)\n        a=[...a, [X,Y,Z]]\n      }\n      ret=[...ret, a]\n      b=JSON.parse(JSON.stringify(a))\n      ax=ay=az=0\n      b.map(v=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R2(0,theta,0)\n        v[0]=X\n        v[1]=Y\n        v[2]=Z\n      })\n      ret=[...ret, b]\n      ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax*1.5\n          q[1]-=ay*1.5\n          q[2]-=az*1.5\n        })\n      })\n\n      b=JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n      })\n      ret=[...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,.96,0)\n          R2(0,0,t*5)\n          R2(0,Math.PI,0)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Octahedron=ls=>{\n      ret = []\n      a=[]\n      for(i=4;i--;){\n        X1=S(p=Math.PI*2/4*i+Math.PI/4)\n        Y1=C(p)\n        Z1=0\n        X2=S(p=Math.PI*2/4*(i+1)+Math.PI/4)\n        Y2=C(p)\n        Z2=0\n        X3=0\n        Y3=0\n        Z3=1\n        a=[\n          [X1,Y1,Z1],\n          [X2,Y2,Z2],\n          [X3,Y3,Z3]\n        ]\n        ret=[...ret, a]\n        a=[\n          [X1,Y1,-Z1],\n          [X2,Y2,-Z2],\n          [X3,Y3,-Z3]\n        ]\n        ret=[...ret, a]\n      }\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Cube=ls=>{\n      let ret=[]\n      for(j=6;j--;ret=[...ret,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2                                                                                                            ])[j%3]*(l=j<3?-ls:ls),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Icosahedron=ls=>{\n      let a=[1,1],ret=[]\n      let b\n      for(i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]];\n      let phi=a[l]/a[l-1]\n      a=[[[-phi,-1,0],[phi,-1,0],[phi,1,0],[-phi,1,0]],[[0,-phi,-1],[0,phi,-1],[0,phi,1],[0,-phi,1]],[[                                                                                                            -1,0,-phi],[-1,0,phi],[1,0,phi],[1,0,-phi]]]\n      let ico=[[[0,1],[1,0],[1,3]],[[0,1],[2,3],[1,0]],[[2,0],[2,3],[1,0]],[[0,1],[2,3],[0,2]],[[1,1],[                                                                                                            2,3],[0,2]],[[1,1],[2,3],[2,0]],[[1,1],[1,2],[0,2]],[[0,1],[2,2],[0,2]],[[0,0],[1,0],[2,0]],[[2,0],[0,3                                                                                                            ],[0,0]],[[1,1],[1,2],[0,3]],[[1,1],[2,0],[0,3]],[[0,1],[1,3],[2,2]],[[1,3],[2,1],[2,2]],[[2,1],[0,3],[                                                                                                            1,2]],[[2,1],[0,0],[1,3]],[[1,2],[2,2],[2,1]],[[2,2],[1,2],[0,2]],[[0,3],[2,1],[0,0]],[[1,3],[1,0],[0,0                                                                                                            ]]]\n      ico.map((v,i)=>{\n        b=[]\n        v.map(q=>{\n          t1=q[0],t2=q[1]\n          X=a[t1][t2][0],Y=a[t1][t2][1],Z=a[t1][t2][2]\n          b=[...b, [X,Y,Z]]\n        })\n        ret=[...ret, b]\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Dodecahedron=ls=>{\n      let ret=[]\n      let sd=5\n      let a=[], b=[]\n      mind=6e6\n      for(let i=sd;i--;){\n        X=S(p=Math.PI*2/sd*i)\n        Y=C(p)\n        Z=0\n        if(Y<mind)mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a=a.map(v=>{\n        X=v[0]\n        Y=v[1]-=mind\n        Z=v[2]\n        R2(0,.5535735,0)\n        return [X,Y,Z]\n      })\n\n      ret = [...ret, a]\n      b=JSON.parse(JSON.stringify(a)).map(v=>{\n        d=Math.hypot(v[0],v[1])\n        v[0]=S(p=Math.atan2(v[0],v[1])+Math.PI)*d\n        v[1]=C(p)*d\n        return v\n      })\n      ret = [...ret, b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          if(q[2]<mind)mind=q[2]\n        })\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]+=ang=1.538840639715\n        })\n      })\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI,0,Math.PI)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      b=JSON.parse(JSON.stringify(e)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI/2,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.15\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 350/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=12\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    stroke2=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        //x.globalAlpha=.15\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 650/Z)\n        //x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=12\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    segs = 10\n    iPsd = 12\n    iPv = .2\n    iPcv = .1\n    iPulseFreq = 30\n    iPcdierate = .05\n    iPc_= 3\n\n    Rl=Pt=Yw=oX=oY=0, oZ=4\n    ls = 8 \n    base_shapes = [\n      Tetrahedron(ls),\n      Cube(ls),\n      Sphere(ls/1.1,6,4),\n      Octahedron(ls),\n      Dodecahedron(ls),\n      Icosahedron(ls),\n      ...shps\n    ]\n\n    rw=1, cl=3, br=1, sp=16\n    iShapesC = rw*cl*br\n    shapes = Array(iShapesC).fill().map((shp,m)=>{\n      tx = ((m%cl)-cl/2+.5)*sp\n      ty = (((m/cl|0)%rw)-rw/2+.5)*sp\n      tz = ((m/cl/rw|0)-br/2+.5)*sp\n      switch(m){\n        case 0: shpsel = 5; break\n        case 1: shpsel = 6; break\n        case 2: shpsel = 4; break\n      }\n      a = JSON.parse(JSON.stringify(base_shapes[shpsel%base_shapes.length]))\n      switch(shpsel){\n        case 0:\n          iPc = iPc_\n        break\n        case 1:\n          iPc = iPc_*4\n        break\n        case 2:\n          iPc = Math.max(1, iPc_/3|0)\n        break\n        case 3:\n          iPc = iPc_\n        break\n        case 4:\n          iPc = Math.max(1, iPc_/1.5|0)\n        break\n        case 5:\n          iPc = Math.max(1, iPc_/2|0)\n        break\n        default:\n        break\n      }\n      a = a.map((v,i)=>{\n        P = []\n        if(shpsel>5) iPc = (Rn()<.033)?1:0\n        ax = ay = az = 0\n        v.map(q=>{\n          ax += q[0]\n          ay += q[1]\n          az += q[2]\n        })\n        ax /= v.length\n        ay /= v.length\n        az /= v.length\n        d  = Math.hypot(ax,ay,az)\n        p1 = Math.atan2(ax, az)\n        p2 = Math.acos(ay/d)\n        X1 = Y1 = Z1 = 0\n        for(let k=iPc; k--;){\n          X2 = S(p=Math.PI*2*Rn())*1e3\n          Y2 = C(p)*1e3\n          Z2 = 0\n          v.map((q,j)=>{\n            l = j\n            X = v[l][0]-ax\n            Y = v[l][1]-ay\n            Z = v[l][2]-az\n            R(0,0,-p1)\n            R(0,p2+Math.PI/2,0)\n            X3 = X\n            Y3 = Y\n            l = (j+1)%v.length\n            X = v[l][0]-ax\n            Y = v[l][1]-ay\n            Z = v[l][2]-az\n            R(0,0,-p1)\n            R(0,p2+Math.PI/2,0)\n            X4 = X\n            Y4 = Y\n            if(pt = I(X1,Y1,X2,Y2,X3,Y3,X4,Y4)){\n              ls = Rn()**.5\n              X = pt[0] * ls\n              Y = pt[1] * ls\n              Z = 0\n              R(0,-Math.PI/2-p2,0)\n              R(0,0,p1)\n              X += ax\n              Y += ay\n              Z += az\n              vx = S(p=Math.PI*2*Rn())*iPv\n              vy = C(p)*iPv\n              vz = 0\n              P = [...P, [X, Y, Z, vx, vy, vz, [], []]]\n            }\n          })\n        }\n        return [v, P]\n      })\n      return [tx, ty, tz, a]\n    })\n\n    bg = new Image()\n    go = false\n    bg.onload = () =>{\n      go=true\n    }\n    bg.src = \'proxy.php?url=https://srmcgann.github.io/assets/4EOt3.jpg\'\n\n    cols=[\n      \'#00ffff08\',\n      \'#ffff8806\',\n      \'#4400ff08\',\n      \'\',\n      \'\',\n      \'\',\n    ]\n  }\n\n  if(go){\n    x.globalAlpha=.4\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0005\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=0\n    oY=0\n    oZ=22\n    x.lineJoin=x.lineCap=\'butt\'\n\n    shapes.map((shp, m) => {\n      Rl=0\n      Pt=S(t)/2\n      Yw=C(t)/2\n      tx = shp[0]\n      ty = shp[1]\n      tz = shp[2]\n      shp[3].map((v,i) => {\n        ax = ay = az = 0\n        x.beginPath()\n        v[0].map(q=>{\n          ax += X = q[0]\n          ay += Y = q[1]\n          az += Z = q[2]\n          R(Rl,Pt,Yw,1)\n          X+=tx\n          Y+=ty\n          Z+=tz\n          if(Z>0) x.lineTo(...Q())\n        })\n        if(m==1){\n          stroke2(\'#ffffff08\', cols[m])\n        } else{\n          stroke2(\'#00ffff16\', cols[m])\n        }\n        ax/=v[0].length\n        ay/=v[0].length\n        az/=v[0].length\n\n        d  = Math.hypot(ax,ay,az)\n        p1 = Math.atan2(ax, az)\n        p2 = Math.acos(ay/d)\n        v[1].map((q,gg) => {\n          q[7] = q[7].filter(n=>n[4]>0)\n          q[7].map((n,j)=>{\n            //cx = n[0]\n            //cy = n[1]\n            //cz = n[2]\n            x.beginPath()\n            n[3].map(k => {\n              X = k[0] - ax\n              Y = k[1] - ay\n              Z = k[2] - az\n              R(0, 0, -p1)\n              R(0, p2+Math.PI/2, 0)\n              X_ = X\n              Y_ = Y\n              Z_ = Z\n              X1 = 0\n              Y1 = 0\n              Z1 = 0\n              X2 = X + k[3]\n              Y2 = Y + k[4]\n              Z2 = Z\n              if(m!=1) v[0].map((n,m) => {\n                l = m\n                X = v[0][l][0]-ax\n                Y = v[0][l][1]-ay\n                Z = v[0][l][2]-az\n                R(0,0,-p1)\n                R(0,p2+Math.PI/2,0)\n                X3 = X\n                Y3 = Y\n                l = (m+1)%v[0].length \n                X = v[0][l][0]-ax\n                Y = v[0][l][1]-ay\n                Z = v[0][l][2]-az\n                R(0,0,-p1)\n                R(0,p2+Math.PI/2,0)\n                X4 = X\n                Y4 = Y\n                if(pt = I(X1,Y1,X2,Y2,X3,Y3,X4,Y4)){\n                  //q[3] *= -1//(X_ - pt[0])/300\n                  //q[4] *= -1//(Y_ - pt[1])/300\n                  k[3] -= (X2 - pt[0])*3\n                  k[4] -= (Y2 - pt[1])*3\n                }\n              })\n\n              d=Math.hypot(k[3], k[4], k[5])\n              k[3]/=d\n              k[4]/=d\n              k[5]/=d\n              k[3]*=iPcv\n              k[4]*=iPcv\n              k[5]*=iPcv\n\n              X = X_ + k[3]\n              Y = Y_ + k[4]\n              Z = Z_ + k[5]\n\n              R(0,-Math.PI/2-p2,0)\n              R(0,0,p1)\n              X += ax\n              Y += ay\n              Z += az\n              k[0] = X\n              k[1] = Y\n              k[2] = Z\n              R(Rl,Pt,Yw,1)\n              if(Z>0){\n                X+=tx\n                Y+=ty\n                Z+=tz\n                x.lineTo(...Q())\n              }\n            })\n            stroke(`hsla(${n[4]*360},99%,${120-(1-n[4]**2)*70}%,${n[4]}`)\n            n[4] -= iPcdierate\n          })\n\n          q[6] = q[6].filter((v,i)=>i<segs)\n          q[6].map((n,j)=>{\n            n[3]-=.025\n            if(j){\n              x.beginPath()\n              l = j\n              X = q[6][l][0]\n              Y = q[6][l][1]\n              Z = q[6][l][2]\n              R(Rl,Pt,Yw,1)\n              X+=tx\n              Y+=ty\n              Z+=tz\n              if(Z>0) x.lineTo(...Q())\n              l = j-1\n              X = q[6][l][0]\n              Y = q[6][l][1]\n              Z = q[6][l][2]\n              R(Rl,Pt,Yw,1)\n              X+=tx\n              Y+=ty\n              Z+=tz\n              if(Z>0) x.lineTo(...Q())\n              //x.strokeStyle=\'#50f2\'\n              x.lineWidth = Math.min(1e3,10+(800/segs*j)/Z)\n              //x.stroke()\n              x.strokeStyle=\'#0f84\'\n              x.lineWidth /= 4\n              x.stroke()\n            }\n          })\n\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          X = q[0] - ax\n          Y = q[1] - ay\n          Z = q[2] - az\n          R(0,0,-p1)\n          R(0,p2+Math.PI/2,0)\n          X_ = X\n          Y_ = Y\n          Z_ = Z\n\n          X1 = 0\n          Y1 = 0\n          Z1 = 0\n          X2 = X + (q[3] += (Rn()-.5)*iPv)\n          Y2 = Y + (q[4] += (Rn()-.5)*iPv)\n          Z2 = Z\n          v[0].map((n,m)=>{\n            l = m\n            X = v[0][l][0]-ax\n            Y = v[0][l][1]-ay\n            Z = v[0][l][2]-az\n            R(0,0,-p1)\n            R(0,p2+Math.PI/2,0)\n            X3 = X\n            Y3 = Y\n            l = (m+1)%v[0].length \n            X = v[0][l][0]-ax\n            Y = v[0][l][1]-ay\n            Z = v[0][l][2]-az\n            R(0,0,-p1)\n            R(0,p2+Math.PI/2,0)\n            X4 = X\n            Y4 = Y\n            if(pt = I(X1,Y1,X2,Y2,X3,Y3,X4,Y4)){\n              //q[3] *= -1//(X_ - pt[0])/300\n              //q[4] *= -1//(Y_ - pt[1])/300\n              q[3] -= (X2 - pt[0])*2\n              q[4] -= (Y2 - pt[1])*2\n            }\n          })\n\n          d=Math.hypot(q[3],q[4],q[5])\n          q[3]/=d\n          q[4]/=d \n          q[5]/=d\n          q[3]*=iPv\n          q[4]*=iPv\n          q[5]*=iPv\n\n          X = X_ + q[3]\n          Y = Y_ + q[4]\n          Z = Z_ + q[5]\n\n          R(0,-Math.PI/2-p2,0)\n          R(0,0,p1)\n          X += ax\n          Y += ay\n          Z += az\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n          q[6] = [[X,Y,Z,1], ...q[6]]\n          if(!((j+i*21+q.length+gg*5+(t*60)|0)%iPulseFreq)){\n            a = []\n            for(let i = iPsd; i--;){\n              let cx = X-S(p=Math.PI*2/iPsd*i)*.01\n              let cy = Y-C(p)*.01\n              let cz = Z\n              vx = S(p)\n              vy = C(p)\n              a = [...a, [cx,cy,cz,vx,vy,0]]\n            }\n            q[7] = [[X,Y,Z,a,1], ...q[7]]\n          }\n          /*R(Rl,Pt,Yw,1)\n          if(Z>0){\n            X+=tx\n            Y+=ty\n            Z+=tz\n            l = Q()\n            s = Math.min(1e3, 100/Z)\n            x.fillStyle=\'#fff1\'\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s) \n            s/=6\n            x.fillStyle=\'#fffa\'\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          }*/\n        })\n      })\n    })\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'facecrawl 2', 145, 'whitehot robot', '2023-01-18 15:36:50', '[600564,600484,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 27, '', 0, 0);
