              X = k[0] - ax\n              Y = k[1] - ay\n              Z = k[2] - az\n              R(0, 0, -p1)\n              R(0, p2+Math.PI/2, 0)\n              X_ = X\n              Y_ = Y\n              Z_ = Z\n              X1 = 0\n              Y1 = 0\n              Z1 = 0\n              X2 = X + k[3]\n              Y2 = Y + k[4]\n              Z2 = Z\n              if(0&&m!=1) v[0].map((n,m) => {\n                l = m\n                X = v[0][l][0]-ax\n                Y = v[0][l][1]-ay\n                Z = v[0][l][2]-az\n                R(0,0,-p1)\n                R(0,p2+Math.PI/2,0)\n                X3 = X\n                Y3 = Y\n                l = (m+1)%v[0].length \n                X = v[0][l][0]-ax\n                Y = v[0][l][1]-ay\n                Z = v[0][l][2]-az\n                R(0,0,-p1)\n                R(0,p2+Math.PI/2,0)\n                X4 = X\n                Y4 = Y\n                if(pt = I(X1,Y1,X2,Y2,X3,Y3,X4,Y4)){\n                  //q[3] *= -1//(X_ - pt[0])/300\n                  //q[4] *= -1//(Y_ - pt[1])/300\n                  k[3] -= (X2 - pt[0])*3\n                  k[4] -= (Y2 - pt[1])*3\n                }\n              })\n\n              d=Math.hypot(k[3], k[4], k[5])\n              k[3]/=d\n              k[4]/=d\n              k[5]/=d\n              k[3]*=iPcv\n              k[4]*=iPcv\n              k[5]*=iPcv\n\n              X = X_ + k[3]\n              Y = Y_ + k[4]\n              Z = Z_ + k[5]\n\n              R(0,-Math.PI/2-p2,0)\n              R(0,0,p1)\n              X += ax\n              Y += ay\n              Z += az\n              k[0] = X\n              k[1] = Y\n              k[2] = Z\n              R(Rl,Pt,Yw,1)\n              if(Z>0){\n                X+=tx\n                Y+=ty\n                Z+=tz\n                x.lineTo(...Q())\n              }\n            })\n            stroke(`hsla(${n[4]*360},99%,${120-(1-n[4]**2)*70}%,${n[4]}`)\n            n[4] -= iPcdierate\n          })\n\n          q[6] 