      x.lineTo(...Q())\n              }\n            })\n            stroke2(`hsla(${n[4]*360+t*200},99%,${120-(1-n[4]**2)*70}%,${n[4]}`)\n            n[4] -= iPcdierate\n          })\n\n          q[6] = q[6].filter((v,i)=>i<segs)\n          q[6].map((n,j)=>{\n            n[3]-=.025\n            if(j){\n              x.beginPath()\n              l = j\n              X = q[6][l][0]\n              Y = q[6][l][1]\n              Z = q[6][l][2]\n              R(Rl,Pt,Yw,1)\n              X+=tx\n              Y+=ty\n              Z+=tz\n              if(Z>0) x.lineTo(...Q())\n              l = j-1\n              X = q[6][l][0]\n              Y = q[6][l][1]\n              Z = q[6][l][2]\n              R(Rl,Pt,Yw,1)\n              X+=tx\n              Y+=ty\n              Z+=tz\n              if(Z>0) x.lineTo(...Q())\n              //x.strokeStyle=\'#50f2\'\n              x.lineWidth = Math.min(1e3,10+(800/segs*j)/Z)\n              //x.stroke()\n              x.strokeStyle=\'#fff4\'\n              x.lineWidth /= 4\n              x.stroke()\n            }\n          })\n\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          X = q[0] - ax\n          Y = q[1] - ay\n          Z = q[2] - az\n          R(0,0,-p1)\n          R(0,p2+Math.PI/2,0)\n          X_ = X\n          Y_ = Y\n          Z_ = Z\n\n          X1 = 0\n          Y1 = 0\n          Z1 = 0\n          X2 = X + (q[3] += (Rn()-.5)*iPv)\n          Y2 = Y + (q[4] += (Rn()-.5)*iPv)\n          Z2 = Z\n          v[0].map((n,m)=>{\n            l = m\n            X = v[0][l][0]-ax\n            Y = v[0][l][1]-ay\n            Z = v[0][l][2]-az\n            R(0,0,-p1)\n            R(0,p2+Math.PI/2,0)\n            X3 = X\n            Y3 = Y\n            l = (m+1)%v[0].length \n            X = v[0][l][0]-ax\n            Y = v[0][l][1]-ay\n            Z = v[0][l][2]-az\n            R(0,0,-p1)\n            R(0,p2+Math.PI/2,0)\n            X4 = X\n            Y4 = Y\n            if(pt = I(X1,Y1,X2,Y2,X3,Y3,X4,Y4)){\n              //q[3] *= -1//(X_ - pt[0])/300\n              //q[4] *= -1//(Y_ - pt[1])/300\n              q[3] -= (X2 - pt[0])*2\n              q[4] -= (Y2 - pt[1])*2\n            }\n          })\n\n          d=Math.hypot(q[3],q[4],q[5])\n          q[3]/=d\n          q[4]/=d \n          q[5]/=d\n          q[3]*=iPv\n          q[4]*=iPv\n          q[5]*=iPv\n\n          X = X_ + q[3]\n          Y = Y_ + q[4]\n          Z = Z_ + q[5]\n\n          R(0,-Math.PI/2-p2,0)\n          R(0,0,p1)\n          X += ax\n          Y += ay\n          Z += az\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n          q[6] = [[X,Y,Z,1], ...q[6]]\n          if(!((j+i*21+q.length+gg*5+(t*60)|0)%iPulseFreq)){\n            a = []\n            for(let i = iPsd; i--;){\n              let cx = X-S(p=Math.PI*2/iPsd*i)*.01\n              let cy = Y-C(p)*.01\n              let cz = Z\n              vx = S(p)\n              vy = C(p)\n              a = [...a, [cx,cy,cz,vx,vy,0]]\n            }\n            q[7] = [[X,Y,Z,a,1], ...q[7]]\n          }\n          /*R(Rl,Pt,Yw,1)\n          if(Z>0){\n            X+=tx\n            Y+=ty\n            Z+=tz\n            l = Q()\n            s = Math.min(1e3, 100/Z)\n            x.fillStyle=\'#fff1\'\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s) \n            s/=6\n            x.fillStyle=\'#fffa\'\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          }*/\n        })\n      })\n    })\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'overly aware cat', 145, 'whitehot robot', '2023-01-18 21:55:10', '[600573,600572,600571,600569,600564,600484,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 23, '', 0, 0),
(600576, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n      rsz=window.onresize=()=>{\n        setTimeout(()=>{\n          if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n            c.style.height = \'100vh\'\n            setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n          }else{\n            c.style.width = \'100vw\'\n            setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n          }\n          c.width=1920\n          c.height=c.width/1.777777778\n        },0)\n      }\n      rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n        Q=()=>[c.width/2+X/Z*900,c.height/2+Y/Z*900]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n      x.fillStyle=\'#0000\'\n      x.fillRect(0,0,c.width,c.height)\n      x.lineJoin=x.lineCap=\'round\'\n      Rl=0,Pt=0,Yw=0\n      oX=0,oY=0,oZ=10\n\n      \n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background: url(https://srmcgann.github.io/assets/1McM75.gif);\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: contain;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'overly aware cat (gif)', 145, 'whitehot robot', '2023-01-18 23:26:37', '[600574,600570,600565,600560,600558,600556,600549,600545,600541,600537,600536,600535,600534,600531,600529,600526,600525,600523,600520,600519,600517,600515,600513,600511,600508,600505,600503,600502,600497,600496,600493,600487,600481,600480,600478,600476,600472,600471,600467,600466,600463,600462,600461,600454,600453,600450,600448,600447,600445,600442,600441,600440,600439,600438,600435,600427,600420,600419,600417,600414,600412,600403,600401,600399,600391,600390,600385,600380,600367,600366,600364,600363,600360,600359,600358,600357,600356,600355,600354,600353,600288,600253,600252,600251,600248,600247]', 21, '', 0, 0);
