(600578, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n\n\nF=(a,b)=>b<0||b>a?-1:l=1-.1/n,w=c.width=99,c.height=w/1.8,P=t?P:Array(9).fill().map(v=>[k=20,9,0,0]);for(n=i=6e3;i--;x.fillRect(X,Y,1,1,x.fillStyle=`hsl(${d/9},99%,${25+S(d**.4)*75}%)`)){X=i%w,Y=i/w|(d=0),P.map((v,i)=>{d+=n/((k+Math.hypot(X-(v[0]+=v[2]+=S(t+i)/1e8),Y-(v[1]+=v[3]+=C(i-t*2)/1e8)))/w),v[2]*=F(w,v[0]),v[3]*=F(56,v[1])})}\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #fff;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'grid dweet', 145, 'whitehot robot', '2023-01-18 23:50:10', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 16, '', 0, 0),
(600579, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    ls = 10, iPc=10, iPv=1, iPs=.5\n    P=Array(iPc).fill().map((v,i)=>{\n      X  = S(p=Math.PI*2/iPc*i)*ls\n      Y  = C(p)*ls\n      Z  = 0\n      switch(i%3){\n        case 0:\n          vx = S(p+=Math.PI/2)*iPv\n          vy = C(p)*iPv\n          vz = 0\n        break\n        case 1:\n          vx = S(p+=Math.PI/2)*iPv\n          vy = 0\n          vz = C(p)*iPv\n        case 2:\n          vx = 0\n          vy = S(p+=Math.PI/2)*iPv\n          vz = C(p)*iPv\n        break\n      }\n      return [X,Y,Z,vx,vy,vz]\n    })\n    ball1 = new Image()\n    ball1.src = \'proxy.php?url=https://srmcgann.github.io/assets/WuP3u.png\'\n\n    ball2 = new Image()\n    ball2.src = \'proxy.php?url=https://srmcgann.github.io/assets/2bieuS.png\'\n\n    star = new Image()\n    star.src = \'proxy.php?url=https://srmcgann.github.io/temp/stars/star6.png\'\n\n    B = []\n    iBc = 20, ls = 6\n    for(j=3;j--;) B = [...B, ...Array(iBc).fill().map((v,i) => {\n      a = [S(p=Math.PI*2/iBc*i)*ls, C(p=Math.PI*2/iBc*i)*ls, 0]\n      return [a[(j+0)%3],a[(j+1)%3],a[(j+2)%3]]\n    })]\n\n    B = B.filter((v,i) => {\n      k = true\n      B.map((q,j) => {\n        if(i<j && Math.hypot(v[0]-q[0], v[1]-q[1], v[2]-q[2])<.01) k = false\n      })\n      return k\n    })\n\n    K = [], iKv=.5\n    spawnK = () => {\n      d=Math.hypot(X,Y,Z)\n      vx = X/d*iKv\n      vy = Y/d*iKv\n      vz = Z/d*iKv\n      K = [...K, [X, Y, Z, vx, vy, vz, 1]]\n    }\n\n    go = false\n    bg = new Image()\n    bg.onload=()=>{\n      go = true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/hxtdg.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha = .3\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha = 1\n    x.fillStyle=\'#0002\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=oY=0, oZ=25+S(t)*6\n    Rl=0, Pt=-t/2, Yw=S(t/3)*6\n    \n    X=Y=Z=0\n    R(Rl,Pt,Yw,1)\n    l=Q()\n    x.globalAlpha=.5\n    s=Math.min(1e3,7e3/Z)\n    x.drawImage(ball2,l[0]-s/2,l[1]-s/2,s,s)\n    x.globalAlpha=1\n    s*=3\n    x.drawImage(star,l[0]-s/2.06,l[1]-s/2.06,s,s)\n\n    a = JSON.parse(JSON.stringify(P)).map((v,i)=>{\n      X = v[0]\n      Y = v[1]\n      Z = v[2]\n      R(Rl,Pt,Yw,1)\n      return [Z, i]\n    })\n\n    a.sort((a,b)=>b[0]-a[0])\n\n    P.map((n,i)=>{\n      v=P[a[i][1]]\n      X1 = v[0]\n      Y1 = v[1]\n      Z1 = v[2]\n      P.map((q,j)=>{\n        if(i!=j){\n          X2 = q[0]\n          Y2 = q[1]\n          Z2 = q[2]\n          d = 200 + Math.hypot(X2-X1,Y2-Y1,Z2-Z1)**3\n          v[3]+=(X2-X1)*3/d/2\n          v[4]+=(Y2-Y1)*3/d/2\n          v[5]+=(Z2-Z1)*3/d/2\n        }\n      })\n      v[3] -= v[0]/300\n      v[4] -= v[1]/300\n      v[5] -= v[2]/300\n      v[3]/=1.0002\n      v[4]/=1.0002\n      v[5]/=1.0002\n      X = v[0]+=v[3]\n      Y = v[1]+=v[4]\n      Z = v[2]+=v[5]\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s=Math.min(1e3,iPs*7e3/Z)\n        l=Q()\n        x.globalAlpha=.5\n        x.drawImage(ball1,l[0]-s/2,l[1]-s/2,s,s)\n      }\n    })\n\n    B.map(v=>{\n      X = v[0]\n      Y = v[1]\n      Z = v[2]\n      spawnK()\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s=Math.min(1e3,2e4/Z**1.5)\n        l=Q()\n        x.globalAlpha=.75\n        x.drawImage(star,l[0]-s/2,l[1]-s/2,s,s)\n      }\n    })\n\n    K = K.filter(v=>v[6]>.1)\n\n    K.map(v => {\n      X1 = v[0]\n      Y1 = v[1]\n      Z1 = v[2]\n      d1 = 0\n      P.map(q => {\n        X2 = q[0]\n        Y2 = q[1]\n        Z2 = q[2]\n        d = (5 + Math.hypot(X1-X2, Y1-Y2, Z1-Z2))**4\n        dvx = (X2-X1) * 30 / d \n        dvy = (Y2-Y1) * 30 / d \n        dvz = (Z2-Z1) * 30 / d \n        d1 += Math.hypot(dvx,dvy,dvz)*999\n        v[3] += dvx\n        v[4] += dvy\n        v[5] += dvz\n      })\n      X = v[0] += v[3]\n      Y = v[1] += v[4]\n      Z = v[2] += v[5]\n      v[6]-=.05\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s=Math.min(1e3,1e4*v[6]/Z**1.5)\n        l=Q()\n        //x.globalAlpha=.25*v[6]**2\n        x.fillStyle = `hsla(${d1*6},99%,${Math.max(50, 125-d1**4/99999)}%,.025)`\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=8\n        x.fillStyle=\'#fffa\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        //x.drawImage(star,l[0]-s/2,l[1]-s/2,s,s)\n      }\n    })\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: a