        ls = Rn()**.5\n              X = pt[0] * ls\n              Y = pt[1] * ls\n              Z = 0\n              R(0,-Math.PI/2-p2,0)\n              R(0,0,p1)\n              X += ax\n              Y += ay\n              Z += az\n              vx = S(p=Math.PI*2*Rn())*iPv\n              vy = C(p)*iPv\n              vz = 0\n              P = [...P, [X, Y, Z, vx, vy, vz, [], []]]\n            }\n          })\n        }\n        return [v, P]\n      })\n      return [tx, ty, tz, a]\n    })\n\n    bg = new Image()\n    go = false\n    bg.onload = () =>{\n      go=true\n    }\n    bg.src = \'proxy.php?url=https://srmcgann.github.io/assets/1TO10k.jpg\'\n\n    cols=[\n      \'#ffffff10\',\n      \'#ffff8806\',\n      \'#4400ff08\',\n      \'\',\n      \'\',\n      \'\',\n    ]\n    mode=scr=0\n  }\n\n  if(go){\n    x.globalAlpha=.6\n    scr+=20\n    scr%=bg.width\n    x.drawImage(bg,scr,0,c.width*2,c.height)\n    x.drawImage(bg,-c.width*2+scr,0,c.width*2,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0003\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=0\n    oY=0\n    oZ=12\n    x.lineJoin=x.lineCap=\'round\'\n\n    if(!((t*60|0)%60))mode=false\n    if(!((t*60|0)%(60*4)))mode=true\n\n\n    shapes.map((shp, m) => {\n      Rl=0\n      Pt=mode?((t*60|0)%60)*Math.PI*2/60:0\n      Yw=0\n      tx = shp[0]\n      ty = shp[1]\n      tz = shp[2]\n      shp[3].map((v,i) => {\n        ax = ay = az = 0\n        x.beginPath()\n        v[0].map(q=>{\n          ax += X = q[0]\n          ay += Y = q[1]+S(X/2-t*10)\n          az += Z = q[2]\n          R(Rl,Pt,Yw,1)\n          X+=tx\n          Y+=ty\n          Z+=tz\n          if(Z>0) x.lineTo(...Q())\n        })\n        if(m==1){\n          stroke2(\'#ffffff08\', cols[m])\n        } else{\n          stroke2(\'#ffffff20\', cols[m])\n        }\n        ax/=v[0].length\n        ay/=v[0].length\n        az/=v[0].length\n\n        d  = Math.hypot(ax,ay,az)\n        p1 = Math.atan2(ax, az)\n        p2 = Math.acos(ay/d)\n        v[1].ma