 fetch(url, res => res).then(data=>data.text()).then(data=>{\n        a=[]\n        data.split(\"\\nv \").map(v=>{\n          a=[...a, v.split(\"\\n\")[0]]\n        })\n        a=a.filter((v,i)=>i).map(v=>[...v.split(\' \').map(n=>(+n.replace(\"\\n\", \'\')))])\n        ax=ay=az=0\n        a.map(v=>{\n          v[1]*=-1\n          ax+=v[0]\n          ay+=v[1]\n          az+=v[2]\n        })\n        ax/=a.length\n        ay/=a.length\n        az/=a.length\n        a.map(v=>{\n          X=(v[0]-ax)*scale\n          Y=(v[1]-ay)*scale\n          Z=(v[2]-az)*scale\n          R2(rl,pt,yw,0)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n        })\n        maxY=-6e6\n        a.map(v=>{\n          if(v[1]>maxY)maxY=v[1]\n        })\n        a.map(v=>{\n          v[1]-=maxY-oY\n          v[0]+=tx\n          v[1]+=ty\n          v[2]+=tz\n        })\n\n        b=[]\n        data.split(\"\\nf \").map(v=>{\n          b=[...b, v.split(\"\\n\")[0]]\n        })\n        b.shift()\n        b=b.map(v=>v.split(\' \'))\n        b=b.map(v=>{\n          v=v.map(q=>{\n            return +q.split(\'/\')[0]\n          })\n          v=v.filter(q=>q)\n          return v\n        })\n        \n        res=[]\n        b.map(v=>{\n          e=[]\n          v.map(q=>{\n            e=[...e, a[q-1]]\n          })\n          e = e.filter(q=>q)\n          res=[...res, e]\n        })\n      })\n      res = res.map(v=>{\n        return JSON.parse(JSON.stringify(v))\n      })\n      return res\n    }\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.05\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 1000/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=14\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    G = 20\n    iShpsv = 0\n    iShpsRv = 0\n    shps = []\n    shps.push([\n      X  = 0,\n      Y  = 0,\n      Z  = 0,\n      vx = (Rn()-.5)*iShpsv,\n      vy = (Rn()-.5)*iShpsv,\n      vz = (Rn()-.5)*iShpsv,\n      rl = 0,\n      pt = 0,\n      yw = 0,\n      rlv = (Rn()-.5)*iShpsRv,\n      ptv = (Rn()-.5)*iShpsRv,\n      ywv = (Rn()-.5)*iShpsRv,\n      (await loadOBJ(`https://twilightparadox.com/sea_turtle.obj`, 2, 0, 1, 0, 0, 0, Math.PI/2)).map(v=>{\n        v.map(q=>{\n          q[3]=q[0], q[4]=q[1], q[5]=q[2]\n          q[6]=q[7]=q[8]=0\n        })\n        return v\n      })\n    ])\n    elasticity = 20\n    grav = .05\n    bg = new Image()\n    go = false\n    bg.onload = () => {\n      go = true\n    }\n    bg.src = \'proxy.php?url=https://srmcgann.github.io/assets/Y0zH8.jpg\'\n  }\n \n  if(go){\n    x.globalAlpha = .3\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha = 1\n    x.fillStyle=\'#0006\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=oY=0, oZ=25\n    Rl=0,Pt=-S(t*2)/2,Yw=S(t/2)*8\n    x.lineJoin=x.lineCap=\'round\'\n\n    ls=G*2**.5/2\n    CB.map(v=>{\n      x.beginPath()\n      v.map(q=>{\n        X=q[0]*ls\n        Y=q[1]*ls\n        Z=q[2]*ls\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n      })\n      stroke(\'#fff2\', \'#50f1\')\n    })\n\n    sv = .3\n    shps.map(shp => {\n      tx = shp[0]\n      ty = shp[1]\n      tz = shp[2]\n\n      shp[6] += (Rn()-.5) * sv * 2\n      shp[7] += (Rn()-.5) * sv * 2\n      shp[8] += (Rn()-.5) * sv * 10\n      shp[6] /= 1.5\n      shp[7] /= 1.5\n      shp[8] /= 1.5\n\n      shp[9]  += (Rn()-.5) * sv\n      shp[10] += (Rn()-.5) * sv\n      shp[11] += (Rn()-.5) * sv\n      shp[9]  /= 1.5\n      shp[10] /= 1.5\n      shp[11] /= 1.5\n\n      //shp[6]+=shp[9]\n      //shp[7]+=shp[10]\n      //shp[8]+=shp[11]\n      ax=ay=az=ct=0\n      shp[12].map(v=>{\n        x.beginPath()\n        v.map(q=>{\n          q[6] += shp[6]\n          q[7] += shp[7]\n          q[8] += shp[8]\n          q[6] += (q[3]-q[0]) / elasticity\n          q[7] += (q[4]-q[1]) / elasticity\n          q[8] += (q[5]-q[2]) / elasticity\n          q[6] /= 1.125\n          q[7] /= 1.125\n          q[8] /= 1.125\n          q[0] += q[6]\n          q[1] += q[7] += grav\n          q[2] += q[8]\n          for(m=3;m--;){\n            if(q[m]>G/2)q[m]=G/2\n            if(q[m]<-G/2)q[m]=-G/2\n          }\n          X = q[0] - tx\n          Y = q[1] - ty\n          Z = q[2] - tz\n          R(shp[9],shp[10],shp[11])\n          ax += q[0] = X += tx\n          ay += q[1] = Y += ty\n          az += q[2] = Z += tz\n          ct++\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n        })\n        stroke(\'#0f43\', \'#40f1\')\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      shp[0]=ax\n      shp[1]=ay\n      shp[2]=az\n    })\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'harassed sea turtle', 145, 'whitehot robot', '2023-01-20 16:55:12', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 6, '', 0, 0);
