(600587, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 150/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n    \n    iPc = 8\n    P=Array(iPc).fill().map((v,i)=>{\n      X = Rn()-.5\n      Y = Rn()-.5\n      Z = Rn()-.5\n      return [X,Y,Z]\n    })\n    for(m=250;m--;) P.map(v=>{\n      tx = v[0]\n      ty = v[1]\n      tz = v[2]\n      P.map(q=>{\n        X=q[0]\n        Y=q[1]\n        Z=q[2]\n        d=9+((Math.hypot(X-tx,Y-ty,Z-tz))*3)**4\n        tx+=(tx-X)*5/d\n        ty+=(ty-Y)*5/d\n        tz+=(tz-Z)*5/d\n      })\n      d=Math.hypot(tx,ty,tz)\n      tx/=d\n      ty/=d\n      tz/=d\n      v[0]=tx\n      v[1]=ty\n      v[2]=tz\n    })\n\n    oF = (X,Y) => {\n      d=(1+(Math.hypot(X,Y)))**1.5/20\n      return Math.min(ipls*.5, (10/d + S(Math.PI/2/ipls*Math.hypot(X,Y)+t*20)*10)/200)*10\n    }\n\n    bg=new Image()\n    go=false\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/1CQVnc.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.5\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0006\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=oY=0, oZ=16\n    Rl=t/4,Pt=-t/4,Yw=t/2\n    x.lineJoin=x.lineCap=\'butt\'\n\n\n    ls=5\n    P.map((v,i)=>{\n      X=tx=v[0]*ls\n      Y=ty=v[1]*ls\n      Z=tz=v[2]*ls\n      p1 = Math.atan2(X,Z)\n      p2 = Math.acos(Y/Math.hypot(X,Y,Z))\n      /*X=S(p1)*S(p2)*(ls-1)\n      Y=C(p2)*(ls-1)\n      Z=C(p1)*S(p2)*(ls-1)\n      x.beginPath()\n      R(Rl,Pt,Yw,1)\n      x.lineTo(...Q())\n      X=S(p1)*S(p2)*(ls-.5)\n      Y=C(p2)*(ls-.5)\n      Z=C(p1)*S(p2)*(ls-.5)\n      R(Rl,Pt,Yw,1)\n      x.lineTo(...Q())\n      stroke(\'#f00a\')\n\n      X=S(p1)*S(p2)*(ls+.5)\n      Y=C(p2)*(ls+.5)\n      Z=C(p1)*S(p2)*(ls+.5)\n      x.beginPath()\n      R(Rl,Pt,Yw,1)\n      x.lineTo(...Q())\n      X=S(p1)*S(p2)*(ls+1)\n      Y=C(p2)*(ls+1)\n      Z=C(p1)*S(p2)*(ls+1)\n      R(Rl,Pt,Yw,1)\n      x.lineTo(...Q())\n      stroke(\'#f00a\')*/\n\n      rw=12, cl=16, ipls=.75\n      for(j=rw;j--;){\n        for(k=cl;k--;){\n          ls_=ipls/9*(k+0)*5**2/5\n          x.beginPath()\n          X=S(p=Math.PI*2/rw*j)*ls_\n          Y=C(p)*ls_\n          Z = ls\n          d=Math.hypot(X,Y,Z)\n          X=X/d*ls\n          Y=Y/d*ls\n          Z=Z/d*ls-ls+oF(X,Y)\n          R(0,Math.PI/2-p2,p1)\n          X+=tx\n          Y+=ty\n          Z+=tz\n          R(Rl,Pt,Yw,1)\n          if(Z>0)x.lineTo(...Q())\n\n          X=S(p=Math.PI*2/rw*(j+1))*ls_\n          Y=C(p)*ls_\n          Z = ls\n  