ata = bctx.getImageData(0,0,100,100)\n      let l = data.data\n      ct = maxd = 0\n      for(j=0; j<l.length; j+=4){\n        red    = l[j+0]\n        green  = l[j+1]\n        blue   = l[j+2]\n        a      = l[j+3]\n        lum = (red + green + blue) / 3\n        if(lum > 3) ct++\n        if(ct>maxd)maxd=ct\n      }\n      alpha = [...alpha, [char, ct]]\n    }\n    alpha.sort((a,b)=>a[1]-b[1])\n    alpha.map((v,i)=>{\n      v[1]=Math.round((i+1)/alpha.length*255)\n    })\n\n    bg = document.createElement(\'video\')\n    go-false\n    bg.oncanplay=()=>{\n      buffer.width = bg.videoWidth\n      buffer.height = bg.videoHeight\n      w=bg.videoWidth\n      h=bg.videoHeight\n      go=true\n      bg.play()\n    }\n    bg.muted = true\n    bg.loop = true\n    bg.defaultPlaybackRate=.1\n    bg.src = \'proxy.php?url=https://srmcgann.github.io/assets/CmPAM.mp4\'\n  }\n\n  x.fillStyle=\'#000\'\n  x.fillRect(0,0,c.width,c.height)\n  oX=oY=0, oZ=10\n  Rl=0,Pt=0,Yw=0\n  x.lineJoin=x.lineCap=\'round\'\n\n  if(go){\n    bctx.drawImage(bg,0,0,(w=buffer.width)/1.666,(h=buffer.height)/1.666)\n    data = bctx.getImageData(0,0,buffer.width,buffer.height)\n    l = data.data\n    cl = 128, rw = cl \n    sp = w/cl\n    ip1=Math.max(0,Math.min(1,(S(t*2)/2)*3))\n    ip2=1-ip1\n    ra=c.width/buffer.width\n    tsp=sp*ra\n    x.font=tsp*1.1+\'px courier\'\n    for(i=0;i<cl*rw|0;i++){\n      X=(i%cl)*sp\n      Y=(i/cl|0)*sp\n      tx=X*ra\n      ty=Y*ra\n      idx=((Y*sp*cl+X)|0)*4\n      red    = l[idx+0]\n      green  = l[idx+1]\n      blue   = l[idx+2]\n      a      = l[idx+3]\n      let lum = (red + green + blue)/3\n      x.fillStyle=`rgba(${red},${green},${blue*ip1},${1})`\n      x.globalAlpha=ip1\n      x.fillRect(tx,ty,tsp,tsp)\n      //x.fillStyle=\'#fff\'\n      x.globalAlpha=ip2\n      x.fillStyle=`rgba(${lum},${lum},${lum},${1})`\n      a_idx = lum/256*alpha.length|0\n      x.fillText(alpha[a_idx][0],tx,ty+tsp*.6,tsp,tsp)\n    }\n  }\n  x.globalAlpha=1\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'video to asc', 145, 'whitehot robot', '2023-01-20 19:46:47', '', 3, '', 0, 0),
(600598, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          spx=0\n          spy=0\n          spz=4\n          spr=6*sp\n          d=H(X-spx,Y-spy,Z-spz)\n          if(d<spr){\n            X=spx+(X-spx)/d*spr            \n            Y=spy+(Y-spy)/d*spr            \n            Z=spz+(Z-spz)/d*spr            \n          }\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX,Y+=oY,Z+=oZ\n          }\n        }\n\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background-repeat: no-repeat;\n  background-size: contain;\n  background-position: center center;\n  background-image: url(https://srmcgann.github.io/assets/1g4dfi.gif);\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'visitors ultra deluxe [gif]',