(600602, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n    iPc = 200, ls1=2, iPv=.5\n    iBc = 3, ls2=50, iBv=.5\n    B=Array(iBc).fill().map((v,i)=>{\n      ls2_=ls2//3-ls2/iBc*i\n      tx = S(p=Math.PI*2/iBc*i+Math.PI/iBc)*ls2_\n      ty = C(p)*ls2_\n      tz = 0\n      tvx = S(p+=Math.PI/2)*iBv\n      tvy = C(p)*iBv\n      tvz = 0\n      a = Array(iPc).fill().map((q,j)=>{\n        ls1_ = ls1//1*Rn()**.5\n        X = tx + S(p=Math.PI*2/iPc*j)*ls1_\n        Y = ty + C(p)*ls1_\n        Z = tz\n        vx = S(p+=Math.PI/2)*iPv\n        vy = C(p)*iPv\n        vz = 0\n        return [X, Y, Z, vx, vy, vz]\n      })\n\n      return [tx, ty, tz, tvx, tvy, tvz, a]\n    })\n    gravA = 100\n    gravB = 500/2\n\n    abberZ=()=>{\n      B.map(v=>{\n        v[6].map(q=>{\n          q[5]+=(Rn()-.5)*iPv*10\n        })\n      })\n      //abber = true\n    }\n    abber = false\n    star1 = new Image()\n    star2 = new Image()\n    star1.src=\'proxy.php?url=https://srmcgann.github.io/temp/stars/star2.png\'\n    star2.src=\'proxy.php?url=https://srmcgann.github.io/temp/stars/star7.png\'\n    bg=new Image()\n    go=false\n    bg.onload = () => {\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/2cyBpz.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.2\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0002\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=oY=0, oZ=110\n    //Rl=0,Pt=-S(t/2)/3,Yw=S(t/3)*2\n    Rl=t/2,Pt=C(t/2)/2,Yw=Math.PI/2+S(t/8)*3\n    x.lineJoin=x.lineCap=\'round\'\n\n    if(t&&!((t*60|0)%(60*12)) && !abber) abberZ()\n\n    B.map((v,i)=>{\n      X=tx1=v[0]=S(p=Math.PI/iBc+Math.PI*2/iBc*i-S(t/4)*16)*ls2*S(t/1.5)//v[0]+=v[3]+=(0-v[0])/gravB\n      Y=ty1=v[1]=C(p)*ls2*S(t/1.5)\n      Z=tz1=v[2]=0\n      v[6].map(q=>{\n        B.map(v=>{\n          tx=v[0]\n          ty=v[1]\n          tz=v[2]\n          d=(.5+(Math.hypot(a=tx-q[0],b=ty-q[1],e=tz-q[2])))**1.25\n          X=q[0]+=q[3]+=a/d/gravA\n          Y=q[1]+=q[4]+=b/d/gravA\n          Z=q[2]+=q[5]+=e/d/gravA*3\n          R(Rl,Pt,Yw,1)\n          if(Z>0){\n            s=Math.min(1000, 10000/Z)\n            x.fillStyle=\'#4400ff01\'\n            l=Q()\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n            s/=2.5\n            x.fillStyle=\'#2288ff02\'\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n            s/=4\n            x.fillStyle=\'#00ffff01\'\n            x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          }\n   