(600606, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920|0\nc.height = 1080|0\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=(c.width/1.777777778|0)+1\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    R2=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n    }\n    Q=()=>[c.width/2-c.width/4.5+X/Z*800,c.height/2+Y/Z*800]\n    Q2=()=>[c.width/2+c.width/4+X/Z*800,c.height/2+Y/Z*800]\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.globalAlpha=.16\n        x.strokeStyle=\'#40f\'\n        x.lineWidth=Math.min(500, 350/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=5\n        x.strokeStyle=scol\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n    lineres=8\n    tight=10/1|0\n    renderHilbertCurve = (size) => {\n      tight=10/(1+size/4)|0\n      p1v=0\n      p2v=Math.PI*1.9\n      oxv=oyv=ozv=l1=l2=0\n      b=[],l1=l2=l1_=l2_=1,t_=0\n      B=[\n        [-1,1,0],\n        [-1,-1,0],\n        [1,-1,0],\n        [1,1,0],\n      ]\n      Hil = d => {\n        a=[]\n        f=Array(32).fill().map((v,i)=>[2**i,i%2?-1:1]).filter(v=>v[0]==d)[0][1]%2?-1:1\n        for(i=4;i--;){\n          switch(i){\n            case 0: ox=-2*d,oy=2*d,rl=Math.PI/2,dir=1*f;break\n            case 1: ox=-2*d,oy=-2*d,rl=0,dir=-1*f;break\n            case 2: ox=2*d,oy=-2*d,rl=0,dir=-1*f;break\n            case 3: ox=2*d,oy=2*d,rl=-Math.PI/2,dir=1*f;break\n          }\n          a=[...B.map(v=>{\n            X=v[0]+ox\n            Y=v[1]+oy\n            Z=v[2]\n            R(rl,0,0)\n          return [X*dir,Y,Z]}),...a]\n        }\n        B=a\n      }\n      sz=size\n      for(m=0;m<sz;++m)Hil(2**m)\n\n      B.map((v,i)=>{\n        if(i<B.length-2){\n          l=i\n          X1=B[l][0]\n          Y1=B[l][1]\n          Z1=B[l][2]\n          l=i+1\n          X2=B[l][0]\n          Y2=B[l][1]\n          Z2=B[l][2]\n          l=i+1\n          X3=B[l][0]\n          Y3=B[l][1]\n          Z3=B[l][2]\n          l=i+2\n          X4=B[l][0]\n          Y4=B[l][1]\n          Z4=B[l][2]\n          if(!i){\n            X=X1,Y=Y1,Z=Z1\n            b=[...b, [X,Y,Z]]\n          }\n          for(k=0;k<lineres+1;++k){\n            ip1=1/lineres*k\n            XA=X1+(X2-X1)*ip1\n            YA=Y1+(Y2-Y1)*ip1\n            ZA=Z1+(Z2-Z1)*ip1\n            XB=X2+(X3-X2)*ip1\n            YB=Y2+(Y3-Y2)*ip1\n            ZB=Z2+(Z3-Z2)*ip1\n            XC=X3+(X4-X3)*ip1\n            YC=Y3+(Y4-Y3)*ip1\n            ZC=Z3+(Z4-Z3)*ip1\n            X1_=XA+(XB-XA)*ip1\n            Y1_=YA+(YB-YA)*ip1\n            Z1_=ZA+(ZB-ZA)*ip1\n            X2_=XB+(XC-XB)*ip1\n            Y2_=YB+(YC-YB)*ip1\n            Z2_=ZB+(ZC-ZB)*ip1\n            X=X1_+(X2_-X1_)*ip1\n            Y=Y1_+(Y2_-Y1_)*ip1\n            Z=Z1_+(Z2_-Z1_)*ip1\n            if((k>lineres/5 && k<lineres-lineres/5)) b=[...b, [X_=X,Y_=Y,Z_=Z]]\n          }\n        }\n        if(i==B.length-1){\n          X__=v[0]\n          Y__=v[1]\n          Z__=v[2]\n          for(k=0;k<lineres/2;++k){\n            ip1=1/lineres*k\n            X=X_+(X__-X_)*ip1*3\n            Y=Y_+(Y__-Y_)*ip1*3\n            Z=Z_+(Z__-Z_)*ip1*3\n            b=[...b, [X,Y,Z]]\n          }\n        }\n      })\n    }\n    curveSize = sz = 0\n    progressive=true\n    p1v=p2v=oxv=oyv=ozv=oxv2=oyv2=ozv2=l1=l2=0\n    renderHilbertCurve(curveSize)\n\n    crosshair = new Image()\n    go=false\n    crosshair.onload=()=>{\n      go=true\n    }\n    crosshair.src = \'proxy.php?url=https://srmcgann.github.io/temp/stars/hud4.png\'\n    XV=YV=ZV=0\n  }\n\n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n  oX=oY=0, oZ=2**(sz)*3\n  Rl=0,Pt=0,Yw=0\n  x.lineJoin=x.lineCap=\'round\'\n\n\n  if(progressive) if(l1==b.length-0){\n    curveSize++\n    curveSize%=4\n    renderHilbertCurve(curveSize)\n  }\n\n  l1=(t_*6*(curveSize+1)|0)%(b.length+1)\n  l1_=Math.max(0,(b.length?((l1*2)/(lineres+2)|0):0)%B.length)\n\n  l2_=Math.max(0,(l1_+1)%B.length)\n  l2=Math.max(0,l1+1)\n  X1=B[l1_][0]\n  Y1=B[l1_][1]\n  Z1=B[l1_][2]\n  X2=B[l2_][0]\n  Y2=B[l2_][1]\n  Z2=B[l2_][2]\n  XV+=((X1+(X2-X1)*(l=((l1*2)/(lineres+2))%1))-XV)/tight\n  YV+=((Y1+(Y2-Y1)*l)-YV)/tight\n  ZV+=((Z1+(Z2-Z1)*l)-ZV)/tight\n\n  l1__=Math.min(b.length-2,Math.max(0,l1))\n  l2=l1__+1\n  ox=b[l1__][0]\n  oy=b[l1__][1]\n  oz=b[l1__][2]\n  oxv+=(ox-oxv)/tight\n  oyv+=(oy-oyv)/tight\n  ozv+=(oz-ozv)/tight\n  oxv2+=(ox-oxv2)/3\n  oyv2+=(oy-oyv2)/3\n  ozv2+=(oz-ozv2)/3\n  p1=Math.atan2(b[l2][0]-b[l1__][0],b[l2][1]-b[l1__][1])\n  p2=Math.acos((b[l2][2]-b[l1__][2])/(.0001+Math.hypot(b[l2][0]-b[l1__][0],b[l2][1]-b[l1__][1],b[l2][2]-b[l1__][2])))+Math.PI\n  if(Math.abs(p1-p1v)>Math.PI){\n    if(p1>p1v){\n      p1v+=Math.PI*2\n    }else{\n      p1v-=Math.PI*2\n    }\n  }\n  p2v+=(p2-p2v)/tight\n  p1v+=(p1-p1v)/tight\n\n  b.map((v,i)=>{\n    if(i<b.length-1){\n      x.beginPath()\n      X=b[i+1][0]\n      Y=b[i+1][1]\n      Z=b[i+1][2]\n      X-=oxv, Y-=oyv, Z-=ozv\n      X*=-1\n      R2(0,p2v,p1v)\n      R(0,-.5,0)\n      Z+=3\n      if(Z>0)x.lineTo(...Q2())\n      X=v[0]\n      Y=v[1]\n      Z=v[2]\n      X-=oxv, Y-=oyv, Z-=ozv\n      X*=-1\n      R2(0,p2v,p1v)\n      R(0,-.5,0)\n      Z+=3\n      if(Z>0)x.lineTo(...Q2())\n      stroke(\'#0fbc\')\n    }\n  })\n  X=ox-oxv\n  Y=oy-oyv\n  Z=oz-ozv\n  X*=-1\n  R2(0,p2v,p1v)\n  R(0,-.5,0)\n  Z+=3\n  R(Rl,Pt,Yw,1)\n  s=Math.min(500,1e3/Z)\n  x.beginPath()\n  x.arc(...Q2(),s,0,7)\n  x.fillStyle=\'#2ff3\'\n  x.fill()\n  x.beginPath()\n  s/=2\n  x.arc(...Q2(),s,0,7)\n  x.fillStyle=\'#fffa\'\n  x.fill()\n\n  x.fillStyle=\'#1028\'\n  x.fillRect(10,20,920+75*1.6,920+75*1.6)\n\n  x.beginPath()\n  B.map((v,i)=>{\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R(Rl,Pt,Yw,1)\n    if(Z>0)x.lineTo(...Q())\n  })\n  stroke(\'#0fbc\',\'\')\n\n  X=XV\n  Y=YV\n  Z=ZV\n  R(Rl,Pt,Yw,1)\n  x.beginPath()\n  s=Math.min(500,500/Z)\n  x.arc(...Q(),s,0,7)\n  x.fillStyle=\'#2ff3\'\n  x.fill()\n  s/=2\n  x.fillStyle=\'#fffa\'\n  x.beginPath()\n  x.arc(...Q(),s,0,7)\n  x.fill()\n\n  x.font=\"90px courier\"\n  x.fillStyle=\'#fff\'\n  x.textAlign=\'center\'\n  x.fillText(\'level \' + (curveSize+1),1920*.75,100)\n\n  if(go){\n    x.drawImage(crosshair, c.width/2+c.width/4-crosshair.width/2*3,c.height/2-crosshair.height/2*3,crosshair.width*3,crosshair.height*3)\n  }\n\n  t_+=1/60\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'hilbert world', 145, 'whitehot robot', '2023-01-20 19:55:53', '', 4, '', 0, 0),
