(600608, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        //x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 50/Z)\n        //x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    buffer = document.createElement(\'canvas\')\n    buffer.width = 100\n    buffer.height = 100\n    bctx = buffer.getContext(\'2d\')\n    bctx.font = \'100px courier\'\n    alphabet = \' 0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ\'\n    alphabet = alphabet.split(\'\').map(v=>{\n      bctx.fillStyle=\'#000\'\n      bctx.fillRect(0,0,buffer.width,buffer.height)\n      bctx.fillStyle=\'#fff\'\n      bctx.fillText(v,0,65)\n      data = bctx.getImageData(0,0,buffer.width,buffer.height)\n      return [v, data.data]\n    })\n\n    renderB=()=>{\n      res = 2\n      text = \'jello world   \'.split(\'\')\n      rw=280*res, cl=20*res, ls1=1.5, ls2=1,r=-t*4\n      B=Array(rw*2+1|0).fill().map((v,i)=>{\n        k=(rw*2+1)-1-i\n        letter = text[((i)*2/cl|0)%text.length]\n        char = alphabet.filter(v=>v[0]==letter)[0]\n        a=[]\n        for(j=cl;j--;){\n          m=cl-1-j\n          tx=(i*2%cl)/cl*60|0\n          ty=j/cl/1.15*100|0\n          idx   = (ty*100+tx)*4|0\n          red   = char[1][idx+0]\n          green = char[1][idx+1]\n          blue  = char[1][idx+2]\n          lum   = (red+green+blue)/3\n          X = 0\n          Y = -ls1/2+ls1/cl*m\n          Z = 0\n          R(-Math.PI/2,0,0)\n          X+=ls2\n          R(Math.PI*2*1.5/rw*k-1.5*r,0,0)\n          X+=ls2*3\n          R(0,0,Math.PI*2/rw*k-r)\n          a=[...a, [X,Y*1.5,Z,lum>10]]\n        }\n        return a\n      })\n    }\n\n    go=true\n  }\n\n  if(go){\n    x.globalAlpha=1\n    x.fillStyle=\'#000c\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=0, oY=-.5, oZ=8\n    Rl=0,Pt=-.85+S(t)/2,Yw=-S(t*4)/3+.3\n    x.lineJoin=x.lineCap=\'butt\'\n\n    renderB()\n\n    B.map((v,i)=>{\n      if(i){\n        v.map((q,j)=>{\n          x.beginPath()\n          l1=i\n          l2=j\n          X=B[l1][l2][0]\n          Y=B[l1][l2][1]\n          Z=B[l1][l2][2]\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n          l1=i-1\n          l2=j\n          X=B[l1][l2][0]\n          Y=B[l1][l2][1]\n          Z=B[l1][l2][2]\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n          l1=i-1\n          l2=(j+1)%v.length\n          X=B[l1][l2][0]\n          Y=B[l1][l2][1]\n          Z=B[l1][l2][2]\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n          l1=i\n          l2=(j+1)%v.length\n          X=B[l1][l2][0]\n          Y=B[l1][l2][1]\n          Z=B[l1][l2][2]\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n          stroke(\'#fff2\', q[3]?`hsla(${(l=B.length/360*i)/8+t*600},99%,${100+S(l/100-t*16)*50}%,.8)`:\'\')\n        })\n      }\n    })\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'jello world temp', 145, 'whitehot robot', '2023-01-20 19:57:36', '', 4, '', 0, 0),
