(600630, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    getHSVfromRGB = (red, green, blue)=>{\n      let r_ = red//256\n      let g_ = green//256\n      let b_ = blue//256\n      let cmax=Math.max(r_, g_ , b_)\n      let cmin=Math.min(r_, g_ , b_)\n      let delta = cmax - cmin\n      let hue = 0\n      if(delta == 0)   hue = 0\n      if(cmax  == r_)  hue = (((g_-b_)/delta)%6)*60\n      if(cmax  == g_)  hue = (((b_-r_)/delta+2))*60\n      if(cmax  == b_)  hue = (((r_-g_)/delta+4))*60\n      let sat\n      if(cmax == 0) sat = 0\n      else sat = delta/cmax\n      let val = cmax\n      return [hue, sat, val]\n    }\n\n    getRGBfromHSV = (hue, sat, val) => {\n      sat=Math.max(1,sat)\n      let e_ = val * sat\n      let x_ = e_*(1-(Math.abs(((hue/60)%2)-1)))\n      let m_ = val - e_\n      let rgb = [e_, e_, e_]\n      if(hue <  60) rgb = [e_, x_, 0]\n      if(hue >= 60  && hue < 120) rgb = [e_, 0, x_]\n      if(hue >= 120 && hue < 180) rgb = [x_, e_, 0]\n      if(hue >= 180 && hue < 240) rgb = [0, e_, x_]\n      if(hue >= 240 && hue < 300) rgb = [0, x_, e_]\n      if(hue >= 300 && hue < 360) rgb = [x_, 0, e_]\n      return rgb\n    }\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    iBc=4e3\n    Gw=9, Gh=9\n    B=Array(iBc).fill().map(v=>{\n      X=(Rn()-.5)*Gw*2\n      Y=(Rn()-.5)*Gh*2\n      Z=0\n      return [X,Y,Z,X,Y,Z,0,0,0]\n    })\n    B=B.filter(v=>{\n      X=v[0]\n      Y=v[1]\n      Z=v[2]\n      d=Math.hypot(X,Y,Z)\n      return d<Math.hypot(Gw,Gh)/1.6\n    })\n\n    iPc=2,iPls=4,iPsd=3,iPv=1\n    P=Array(iPc).fill().map((v,i)=>{\n      tx=(Rn()-.5)*Gw\n      ty=(Rn()-.5)*Gh\n      tz=0\n      vx=(Rn()-.5)*iPv\n      vy=(Rn()-.5)*iPv\n      vz=0\n      a=[]\n      for(j=iPsd;j--;){\n        X=S(p=Math.PI*2/iPsd*j)*iPls\n        Y=C(p)*iPls\n        Z=0\n        a=[...a, [X,Y,Z]]\n      }\n      return [tx,ty,tz,vx,vy,vz, a]\n    })\n    bg=new Image()\n    go=false\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/1lm0L1.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.3\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0001\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=0, oY=0, oZ=14-C(t)*4\n    Rl=-S(t/2)*5,Pt=C(t/2)/3,Yw=C(t/2)\n    \n    P.map((v,i)=>{\n      tx=v[0]+=v[3]\n      ty=v[1]+=v[4]\n      tz=v[2]+=v[5]\n      if(v[0]<-Gw/2 || v[0]>Gw/2) v[3]*=-1\n      if(v[1]<-Gh/2 || v[1]>Gh/2) v[4]*=-1\n      v[6].map((q,j)=>{\n        X=q[0]\n        Y=q[1]\n        Z=q[2]\n        R(S(t+i)/5,0,0)\n        q[0]=X\n        q[1]=Y\n        X+=tx\n        Y+=ty\n        //Z+=Math.hypot(X,Y)**2/20\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          l=Q()\n          s=Math.min(500, 1000/Z)\n          x.beginPath()\n          x.fillStyle=\'#60f3\'\n          //x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          x.arc(...l,s,0,7)\n          x.fill()\n          x.beginPath()\n          s/=2\n          x.fillStyle=\'#f0f2\'\n          //x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          x.arc(...l,s,0,7)\n          x.fill()\n          x.beginPath()\n          s/=3\n          x.fillStyle=\'#fff\'\n          //x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          x.arc(...l,s,0,7)\n          x.fill()\n        }\n      })\n    })\n\n    B.map((v,i)=>{\n      X=v[0]+=v[6]\n      Y=v[1]+=v[7]\n      Z=v[2]+=v[8]\n      P.map((q,j)=>{\n        tx=q[0]\n        ty=q[1]\n        tz=q[2]\n        q[6].map(n=>{\n          X2=tx+n[0]\n          Y2=ty+n[1]\n          Z2=tz+n[2]\n          d=(5+Math.hypot(a=X2-X,b=Y2-Y,e=Z2-Z)*9)**3\n          v[6]-=a*3e3/d\n          v[7]-=b*3e3/d\n          v[8]-=e*3e3/d\n        })\n      })\n      v[6]+=(v[3]-v[0])*.25\n      v[7]+=(v[4]-v[1])*.25\n      v[8]+=(v[5]-v[2])*.25\n      v[6]/=2\n      v[7]/=2\n      v[8]/=2\n      //Z+=Math.hypot(X,Y)**2/20\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        l=Q()\n        s=Math.min(500, 1000/Z)\n        x.fillStyle=\'#00ffcc04\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=14\n        x.fillStyle=\'#fff\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n    })\n  }\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'flow', 145, 'whitehot robot', '2023-01-20 20:15:28', '', 2, '', 0, 1),
