 x.beginPath()\n        X_=S(-theta+Math.PI/2)*800\n        Y_=C(-theta+Math.PI/2)*800\n        for(m=4;m--;){\n          X=X_+S(p=Math.PI*2/4*m-theta+Math.PI/4)*800*(2**.5/1)\n          Y=Y_+C(p)*800*(2**.5/1)\n          x.lineTo(960+X,540+Y)\n        }\n        x.fill()\n        x.beginPath()\n        x.arc(960,540,600,0+Math.PI+Math.PI/6+theta,Math.PI+Math.PI+Math.PI/6+theta)\n        x.fill()\n        x.fillStyle=col\n        x.beginPath()\n        x.arc(960,540,ls,-Math.PI*2/3+Math.PI/6+theta,Math.PI/6+theta)\n        x.fill()\n        if(typeof d_ != \'undefined\'){\n          x.fillStyle=\'#000\'\n          x.beginPath()\n          x.arc(960,540,d_,0,7)\n          x.fill()\n          x.fillStyle=\'#4f48\'\n          x.beginPath()\n          x.arc(960,540,d_,-Math.PI/2+theta,Math.PI/2+theta)\n          x.fill()\n          x.fillStyle=\'#000\'\n          x.beginPath()\n          x.arc(960,540,d_,-Math.PI/2+Math.PI/1.5+theta,Math.PI/2+Math.PI/1.5+theta)\n          x.fill()\n        }\n      }\n\n\n      theta=(t|0)*Math.PI/1.5, col=\'#368\'\n      shade2(theta, col)\n      \n      a.map((v,i)=>{\n        X1_=X1=v[0]\n        Y1_=Y1=v[1]\n        l=(i+1)%a.length\n        X2_=X2=a[l][0]\n        Y2_=Y2=a[l][1]\n        p1=Math.atan2(X2-X1,Y2-Y1)\n        X2=X1+S(p1)*1000\n        Y2=Y1+C(p1)*1000\n        x.beginPath()\n        x.lineTo(960+X1,540+Y1)\n        x.lineTo(960+X2,540+Y2)\n        x.strokeStyle=\'#fff\'\n        x.stroke()\n        p1=Math.atan2(X2-X1,Y2-Y1)+Math.PI\n        X2=X1+S(p1)*1000\n        Y2=Y1+C(p1)*1000\n        x.beginPath()\n        x.lineTo(960+X1,540+Y1)\n        x.lineTo(960+X2,540+Y2)\n        x.strokeStyle=\'#fff\'\n        x.stroke()\n      })\n\n      mx=(X1_+X2_)/2\n      my=(Y1_+Y2_)/2\n      d_=d=Math.hypot(mx,my)\n\n      x.beginPath()\n      X=S(p=Math.PI/3)*1e3\n      Y=C(p)*1e3\n      x.lineTo(960+X,540+Y)\n      x.lineTo(960-X,540-Y)\n      x.stroke()\n\n      x.beginPath()\n      x.lineTo(960,-1e3)\n      x.lineTo(960,1