(600638, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          spx=0\n          spy=0\n          spz=4\n          spr=6*sp\n          d=H(X-spx,Y-spy,Z-spz)\n          if(d<spr){\n            X=spx+(X-spx)/d*spr            \n            Y=spy+(Y-spy)/d*spr            \n            Z=spz+(Z-spz)/d*spr            \n          }\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX,Y+=oY,Z+=oZ\n          }\n        }\n\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background-repeat: no-repeat;\n  background-size: contain;\n  background-position: center center;\n  background-image: url(https://srmcgann.github.io/assets/13mP3q.gif);\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'visitors (gif)', 145, 'whitehot robot', '2023-01-20 20:18:23', '', 4, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600639, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    getHSVfromRGB = (red, green, blue)=>{\n      let r_ = red//256\n      let g_ = green//256\n      let b_ = blue//256\n      let cmax=Math.max(r_, g_ , b_)\n      let cmin=Math.min(r_, g_ , b_)\n      let delta = cmax - cmin\n      let hue = 0\n      if(delta == 0)   hue = 0\n      if(cmax  == r_)  hue = (((g_-b_)/delta)%6)*60\n      if(cmax  == g_)  hue = (((b_-r_)/delta+2))*60\n      if(cmax  == b_)  hue = (((r_-g_)/delta+4))*60\n      let sat\n      if(cmax == 0) sat = 0\n      else sat = delta/cmax\n      let val = cmax\n      return [hue, sat, val]\n    }\n\n    getRGBfromHSV = (hue, sat, val) => {\n      sat=Math.max(1,sat)\n      let e_ = val * sat\n      let x_ = e_*(1-(Math.abs(((hue/60)%2)-1)))\n      let m_ = val - e_\n      let rgb = [e_, e_, e_]\n      if(hue <  60) rgb = [e_, x_, 0]\n      if(hue >= 60  && hue < 120) rgb = [e_, 0, x_]\n      if(hue >= 120 && hue < 180) rgb = [x_, e_, 0]\n      if(hue >= 180 && hue < 240) rgb = [0, e_, x_]\n      if(hue >= 240 && hue < 300) rgb = [0, x_, e_]\n      if(hue >= 300 && hue < 360) rgb = [x_, 0, e_]\n      return rgb\n    }\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        //x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 400/Z)\n        //x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    cl=2,rw=2,br=2,sp=40\n    iBc=12, G=20\n    B=Array(cl*rw*br).fill().map((v,i)=>{\n      //X=S(p=Math.PI*2/iBc*i+Math.PI/4)*G\n      //Y=C(p)*G\n      X=((i%cl)-cl/2+.5)*sp\n      Y=(((i/cl|0)%rw)-rw/2+.5)*sp\n      Z=((i/cl/rw|0)-br/2+.5)*sp\n      return [X,Y,Z]\n    })\n    rand=seed=>((1+seed*seed*9)*30**2.1234/99)%1\n    renderP=(iPc=10,sd=99,ls=10,iPls=10,length=5,growth=.1)=>{\n      let pts=Array(iPc).fill().map((v,i)=>{\n        X=rand(i*3+1)-.5\n        Y=rand(i*3+2)-.5\n        Z=rand(i*3+3)-.5\n        return [X,Y,Z]\n      })\n      for(let m=200;m--;) pts.map((v,i)=>{\n        lx=ly=lz=0\n        pts.map((q,j)=>{\n          if(j!=i){\n            X1=v[0]\n            Y1=v[1]\n            Z1=v[2]\n            X2=q[0]\n            Y2=q[1]\n            Z2=q[2]\n            d=(1+Math.hypot(a=X1-X2,b=Y1-Y2,e=Z1-Z2)*9)**3\n            lx+=a*99**3/d\n            ly+=b*99**3/d\n            lz+=e*99**3/d\n          }\n        })\n        d=Math.hypot(v[0]+=lx,v[1]+=ly,v[2]+=lz)\n        v[0]/=d\n        v[1]/=d\n        v[2]/=d\n      })\n      P=Array(iPc).fill().map((v,i)=>{\n        tx=pts[i][0]\n        ty=pts[i][1]\n        tz=pts[i][2]\n        d=Math.hypot(tx,ty,tz)\n        tx/=d\n        ty/=d\n        tz/=d\n        tx_=tx*=iPls\n        ty_=ty*=iPls\n        tz_=tz*=iPls\n        p1=Math.atan2(tx,tz)\n        p2=-Math.acos(ty/Math.hypot(tx,ty,tz))+Math.PI/2\n        let b=[]\n        for(k=length;k--;){\n          let a = []\n          ls_=ls*((1-((k/1.2)/length))**2)\n          for(let i=sd;i--;){\n            X=S(p=Math.PI*2/sd*i)*ls_\n            Y=C(p)*ls_\n            Z=0\n            R(0,p2,0)\n            R(0,0,p1)\n            X+=tx\n            Y+=ty\n            Z+=tz\n            a=[...a, [X,Y,Z]]\n          }\n          tx-=tx_/growth\n          ty-=ty_/growth\n          tz-=tz_/growth\n          b=[...b, a]\n        }\n        return b\n      })\n    }\n    iPc=4,sd=6,ls=3,iPls=12,length=10,growth=10\n    renderP(iPc,sd,ls,iPls,length,growth)\n    ors=Array(length+1).fill().map(v=>{\n      return [0,0,0]\n    })\n    mrl=mpt=myw=0\n    bg = new Image()\n    go=false\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/15Tw5B.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.3\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0004\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=oY=0, oZ=50+S(t)*20\n    Rl=2+t/6,Pt=t/2,Yw=-S(t/5)*2\n\n    for(i=ors.length-2;i--;){\n      ors[i][0]+=(ors[i+1][0]-ors[i][0])/(l=2+(ors.length-1-i)**3/1000)\n      ors[i][1]+=(ors[i+1][1]-ors[i][1])/l\n      ors[i][2]+=(ors[i+1][2]-ors[i][2])/l\n    }\n    ors[ors.length-2][0]=S(t)/25\n    ors[ors.length-2][1]=S(t*1.5)/15\n    ors[ors.length-2][2]=C(t*3)/15\n\n\n    B.map((v,i)=>{\n      tx=v[0]\n      ty=v[1]\n      tz=v[2]\n      P.map((q,j)=>{\n        q.map((n,m)=>{\n          n.map((g,o)=>{\n            if(!i){\n              X=g[0]\n              Y=g[1]\n              Z=g[2]\n              R(...ors[m])\n              g[0]=X\n              g[1]=Y\n              g[2]=Z\n            }\n            if(m){\n              x.beginPath()\n              X=tx+g[0]\n              Y=ty+g[1]\n              Z=tz+g[2]\n              R(Rl,Pt,Yw,1)\n              if(Z>0)x.lineTo(...Q())\n              X=tx+q[m-1][l=o][0]\n              Y=ty+q[m-1][l][1]\n              Z=tz+q[m-1][l][2]\n              R(Rl,Pt,Yw,1)\n              if(Z>0)x.lineTo(...Q())\n              X=tx+q[m-1][l=(o+1)%n.length][0]\n              Y=ty+q[m-1][l][1]\n              Z=tz+q[m-1][l][2]\n              R(Rl,Pt,Yw,1)\n              if(Z>0)x.lineTo(...Q())\n              X=tx+q[m][l][0]\n              Y=ty+q[m][l][1]\n              Z=tz+q[m][l][2]\n              R(Rl,Pt,Yw,1)\n              if(Z>0)x.lineTo(...Q())\n              stroke(\'#fff3\', \'#0ef2\')\n            }\n          })\n        })\n      })\n    })\n  }\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'visitors', 145, 'whitehot robot', '2023-01-20 20:18:55', '', 4, '', 0, 0),
(600640, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          spx=0\n          spy=0\n          spz=4\n          spr=6*sp\n          d=H(X-spx,Y-spy,Z-spz)\n          if(d<spr){\n            X=spx+(X-spx)/d*spr            \n            Y=spy+(Y-spy)/d*spr            \n            Z=spz+(Z-spz)/d*spr            \n          }\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX,Y+=oY,Z+=oZ\n          }\n        }\n\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background-repeat: no-repeat;\n  background-size: contain;\n  background-position: center center;\n  background-image: url(https://srmcgann.github.io/assets/F3zXe.gif);\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'nested toruses (gif)'