(600641, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(typeof t_ == \'undefined\'){\n    t_=0\n    R=(Rl,Pt,Yw,m)=>{\n      if(Rl==0&&Pt==0&&Yw==0&&!m)return\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n\n    Q=()=>[c.width/2+X/Z*500,c.height/2+Y/Z*500]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    getHSVfromRGB = (red, green, blue)=>{\n      let r_ = red//256\n      let g_ = green//256\n      let b_ = blue//256\n      let cmax=Math.max(r_, g_ , b_)\n      let cmin=Math.min(r_, g_ , b_)\n      let delta = cmax - cmin\n      let hue = 0\n      if(delta == 0)   hue = 0\n      if(cmax  == r_)  hue = (((g_-b_)/delta)%6)*60\n      if(cmax  == g_)  hue = (((b_-r_)/delta+2))*60\n      if(cmax  == b_)  hue = (((r_-g_)/delta+4))*60\n      let sat\n      if(cmax == 0) sat = 0\n      else sat = delta/cmax\n      let val = cmax\n      return [hue, sat, val]\n    }\n\n    getRGBfromHSV = (hue, sat, val) => {\n      sat=Math.max(1,sat)\n      let e_ = val * sat\n      let x_ = e_*(1-(Math.abs(((hue/60)%2)-1)))\n      let m_ = val - e_\n      let rgb = [e_, e_, e_]\n      if(hue <  60) rgb = [e_, x_, 0]\n      if(hue >= 60  && hue < 120) rgb = [e_, 0, x_]\n      if(hue >= 120 && hue < 180) rgb = [x_, e_, 0]\n      if(hue >= 180 && hue < 240) rgb = [0, e_, x_]\n      if(hue >= 240 && hue < 300) rgb = [0, x_, e_]\n      if(hue >= 300 && hue < 360) rgb = [x_, 0, e_]\n      return rgb\n    }\n\n    stroke=(scol,fcol,globalAlphaOverride=1)=>{\n      if(scol){\n        x.closePath()\n        //x.globalAlpha=.2*globalAlphaOverride\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 800/Z)\n        //x.stroke()\n        x.globalAlpha=1*globalAlphaOverride\n        x.lineWidth/=5\n        x.lineWidth|=0\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    Torus=(tx,ty,tz,rl,pt,yw,ls1,ls2,rw,cl)=>{\n      a=[]\n      for(j=cl;j--;){\n        for(k=rw;k--;){\n          b=[]\n          X=S(p=Math.PI*2/rw*k+Math.PI/4)*ls1+ls2\n          Y=C(p)*ls1\n          Z=0\n          R(0,0,Math.PI*2/cl*j)\n          R(rl,pt,yw)\n          b=[...b, [X,Y,Z]]\n          X=S(p=Math.PI*2/rw*(k+1)+Math.PI/4)*ls1+ls2\n          Y=C(p)*ls1\n          Z=0\n          R(0,0,Math.PI*2/cl*j)\n          R(rl,pt,yw)\n          b=[...b, [X,Y,Z]]\n          X=S(p=Math.PI*2/rw*(k+1)+Math.PI/4)*ls1+ls2\n          Y=C(p)*ls1\n          Z=0\n          R(0,0,Math.PI*2/cl*(j+1))\n          R(rl,pt,yw)\n          b=[...b, [X,Y,Z]]\n          X=S(p=Math.PI*2/rw*k+Math.PI/4)*ls1+ls2\n          Y=C(p)*ls1\n          Z=0\n          R(0,0,Math.PI*2/cl*(j+1))\n          R(rl,pt,yw)\n          b=[...b, [X,Y,Z]]\n          a=[...a, b]\n        }\n      }\n      return [tx,ty,tz,a]\n    }\n    recurse = (tx,ty,tz,rl,pt,yw,ls1,ls2,rw,cl,rf,dpth) => {\n      if(dpth>=tgt_dpth) return\n      Toruses.push(Torus(tx,ty,tz,rl,pt,yw,ls1,ls2,rw,cl))\n      pt+=Math.PI/2\n      recurse(ls2,ty,tz,rl,pt,yw,ls1/(1.5+rf),ls2/(1.5+rf),rw/(1+reductionFactor)|0,cl/(1+reductionFactor*2)|0,rf+=reductionFactor,dpth+1)\n    }\n    Toruses = [], reductionFactor=.2\n    tx=0, ty=0, tz=0, rl=0, pt=0, yw=0, ls1=4, ls2=20, rw=12, cl=32\n    tgt_dpth=5\n    recurse(tx,ty,tz,rl,pt,yw,ls1,ls2,rw,cl,0,0)\n    nx_=ny_=nz_=0\n\n    bg=new Image()\n    go=false\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/Euupi.jpg\'\n  }\n\n  if(go){\n    t+=1/60\n    x.globalAlpha=.6\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#000c\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=0\n    oY=-5\n    oZ=(62+Math.min(20,Math.max(0,C(t/1.5+Math.PI/1+.5)*300)))/1.6\n    Rl=S(t/2)/2\n    Pt=S(t/1.5-1)/2\n    Yw=-.75-t/1.5\n    x.lineCap=x.lineJoin=\'butt\'\n\n    trl=tpt=tyw=0\n    trl2=tpt2=tyw2=0\n    trl3=tpt3=tyw3=0\n    trl4=tpt4=tyw4=0\n    trl5=tpt5=tyw5=0\n    tx=ty=tz=nx=ny=nz=0\n    t_=t/2000\n    Toruses.map((v,i)=>{\n      spd=1+(i*2**12)\n      l=0\n      if(i){\n        switch(i-1){\n          case 0:\n            trl+=0\n            tpt+=0\n            tyw+=t_*spd\n          break\n          case 1:\n            trl+=t_*spd\n            tpt+=0\n            tyw+=0\n          break\n          case 2:\n            trl2+=0\n            tpt2+=0\n            tyw2+=t_*spd \n          break\n          case 3:\n            trl2+=t_*spd\n            tpt2+=0\n            tyw2+=0\n          break\n          case 4:\n            trl3+=0\n            tpt3+=0\n            tyw3+=t_*spd\n          break\n          case 5:\n            trl3+=t_*spd\n            tpt3+=0\n            tyw3+=0\n          break\n          case 6:\n            trl4+=0\n            tpt4+=0\n            tyw4+=t_*spd\n          break\n          case 7:\n            trl4+=t_*spd\n            tpt4+=0\n            tyw4+=0\n          break\n        }\n      }\n      X=v[0]\n      Y=v[1]\n      Z=v[2]\n      R(trl4,tpt4,tyw4)\n      R(trl3,tpt3,tyw3)\n      R(trl2,tpt2,tyw2)\n      R(trl,tpt,tyw)\n      x.beginPath()\n      x.fillStyle=\'#f00\'\n      nx=tx=X+nx\n      ny=ty=Y+ny\n      nz=tz=Z+nz\n      X=nx,Y=ny,Z=nz\n\n      v[3].map(q=>{\n        x.beginPath()\n        q.map(n=>{\n          X=n[0]\n          Y=n[1]\n          Z=n[2]\n          R(trl4,tpt4,tyw4)\n          R(trl3,tpt3,tyw3)\n          R(trl2,tpt2,tyw2)\n          R(trl,tpt,tyw)\n          X+=tx, Y+=ty, Z+=tz\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n        })\n        stroke(\'#ffffff60\', `hsla(${360/Toruses.length*i},99%,50%,.2)`, .2+(i/Toruses.length)**1.5/2)\n      })\n    })\n  }\n\n  t_+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'nested toruses', 145, 'whitehot robot', '2023-01-20 20:20:01', '', 4, '', 0, 0),
