(600645, '', 'c=document.querySelector(\'#c\')\ntc=c.cloneNode()\nctx = tc.getContext(\'2d\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=playing=0\nrsz=window.onresize=()=>{\nsetTimeout(()=>{\n  if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n    tc.width=100\n    tc.height=100\n  },0)\n}\nrsz()\nDraw=()=>{\n  if(!t){\n    Rn=Math.random\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    ctx = tc.getContext(\'2d\')\n    drawText=(tx,ty,tz,raw,size)=>{\n      raw.map((v,i)=>{\n        X=v[0]/9+tx\n        Y=v[1]/9+ty\n        Z=v[2]/9+tz\n        for(j=(G/2/(iCr))|0;j--;){\n          cx=0,cy=0,cz=(j+1)*iCr*2\n          d=Math.hypot(X-cx,Y-cy,Z-cz)\n          if(d<iCr){\n            X-=cx\n            Y-=cy\n            Z-=cz\n            X/=d\n            Y/=d\n            Z/=d\n            X=cx+X*iCr\n            Y=cy+Y*iCr\n            Z=cz+Z*iCr\n          }\n        }\n\n        R(Rl,Pt,Yw,1)\n        if(Z>.5){\n          l=Q()\n          s=Math.min(500, 120*size/(Z))\n          //x.fillStyle=\'#8fe4\'\n          //x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          //x.globalAlpha = .2\n          //x.drawImage(star,l[0]-s/2,l[1]-s/2,s,s)\n          //s/=3\n          x.globalAlpha = 1\n          x.drawImage(star,l[0]-s/2,l[1]-s/2,s,s)\n          //x.fillStyle=\'#fffc\'\n          //x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        }\n      })\n    } \n    input = document.querySelectorAll(\'#textInput\')[0]\n    genText=(text, tx, ty, tz, font, size, mode)=>{\n      text+=\'\'\n      switch(font){\n        case 0: sp=1; break\n        case 1: sp=1; break\n        case 2: sp=1; break\n        case 3: sp=1; break\n        case 4: sp=.9; break\n        case 5: sp=1; break\n        case 6: sp=1; break\n        case 7: sp=.8; break\n        case 8: sp=1; break\n        case 9: sp=.7; break\n      }\n      sp*=.7\n      fonts=[\'arial\',\'verdana\',\'helvetica\',\'tahoma\',\'trebuchet\',\'Times New Roman\',\'Georgia\',\'Garamond\',\'Courier New\',\'Brush Script MT\']\n      ctx.clearRect(0,0,tc.width,tc.height)\n      text.split(\' \').map((v, i)=>{\n        ctx.font=size+\'px \' + fonts[font]\n        ctx[mode?\'fillStyle\':\'strokeStyle\']=\'#fff\'\n        ctx.textAlign=\'center\'\n        ctx[mode?\'fillText\':\'strokeText\'](v, tc.width/2, size + i*size*sp*1.2)\n      })\n        d=ctx.getImageData(0,0,tc.width,tc.height)\n        ar=[]\n        minX=6e6,maxX=-6e6\n        minY=6e6,maxY=-6e6\n        for(i=0; i < d.data.length; i+=4){\n          if(!(i%4)){\n            j=i/4|0\n            X=j%tc.width\n            Y=(j/tc.width|0)\n            red=d.data[i]\n            green=d.data[i+1]\n            blue=d.data[i+2]\n            alpha=d.data[i+3]\n            AL=(red+green+blue+alpha)/4\n            if(AL>128){\n              ar=[...ar,[X,Y,0]]\n              if(X<minX)minX=X\n              if(X>maxX)maxX=X\n              if(Y<minY)minY=Y\n              if(Y>maxY)maxY=Y\n            }\n          }\n        }\n        mw=maxX-minX\n        mh=maxY-minY\n        ar.map((v,i)=>{\n          v[0]-=minX+mw/2\n          v[1]-=minY+mh/2\n          v[0]+=tx\n          v[1]+=ty\n          v[2]+=tz\n        })\n      return ar\n    }\n    makeText=()=>{\n      texts = Array(1).fill().map((v, i) => {\n        return genText(document.querySelector(\'#textInput\').value, 0, 0, 0, 8, 20, 1)\n      })\n\n      G=50\n      B=Array(3).fill().map((v, i)=>{\n        bx=(Rn()-.5)*G/5\n        by=(Rn()-.5)*G/5\n        bz=Rn()*G\n        return [bx, by, bz, texts[i%texts.length]]\n      })\n    }\n    makeText()\n    star=new Image()\n    go=false\n    star.onload=()=>{\n      go=true\n    }\n    star.src=\"proxy.php?url=https://srmcgann.github.io/assets/vtpHy.png\"\n    bg = new Image()\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/vtpHy.png\'\n  }\n\n\n  if(go){\n    x.globalAlpha=.5\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0001\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=oY=0, oZ=0\n    Rl=S(t/3)/2,Pt=0,Yw=S(t/2)/2\n    iCr=20\n    B.map(v=>{\n      X=v[0]\n      Y=v[1]\n      Z=v[2]-=.5+S(t/3)/2\n\n      x.globalAlpha=1/(1+Z**6/1e9)\n      if(Z<0)v[0]=(Rn()-.5)*G/5,v[1]=(Rn()-.5)*G/5,v[2]+=G\n      if(Z>G)v[0]=(Rn()-.5)*G/5,v[1]=(Rn()-.5)*G/5,v[2]-=G\n      drawText(X, Y, Z, v[3], 2)\n    })\n  }\n  x.globalAlpha=1\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()\n', 'body, html{\n  margin: 0;\n  width: 100%;\n  height: 100vh;\n  overflow: hidden;\n  background: #000;\n}\n#c{\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 100%;\n  height: 100%;\n  background: url(VoZVF.jpg);\n  background-position: center center;\n  background-size: fill;\n  transform: translate(-50%, -50%);\n}\n#textInput{\n  position: fixed;\n  width: 100vw;\n  font-size: 32px;\n  border: none;\n  background: #000;\n  color: #fff;\n  text-align: center;\n  border-bottom: 1px solid #4fc;\n  font-family: courier, arial;\n}\n#textInput:focus{\n  outline: none;\n}', '<canvas id=c></canvas>\n<input id=\"textInput\" placeholder=\"enter text\" value=\"DUKE NUGUM\" oninput=\"makeText()\" spellcheck=\"false\" autofocus=\"true\">', 'DUKE NUGUM', 145, 'whitehot robot', '2023-01-20 20:21:39', '', 6, '', 0, 0),
