(600650, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    Rn=Math.random\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    getHSVfromRGB = (red, green, blue)=>{\n      let r_ = red//256\n      let g_ = green//256\n      let b_ = blue//256\n      let cmax=Math.max(r_, g_ , b_)\n      let cmin=Math.min(r_, g_ , b_)\n      let delta = cmax - cmin\n      let hue = 0\n      if(delta == 0)   hue = 0\n      if(cmax  == r_)  hue = (((g_-b_)/delta)%6)*60\n      if(cmax  == g_)  hue = (((b_-r_)/delta+2))*60\n      if(cmax  == b_)  hue = (((r_-g_)/delta+4))*60\n      let sat\n      if(cmax == 0) sat = 0\n      else sat = delta/cmax\n      let val = cmax\n      return [hue, sat, val]\n    }\n\n    getRGBfromHSV = (hue, sat, val) => {\n      sat=Math.max(1,sat)\n      let e_ = val * sat\n      let x_ = e_*(1-(Math.abs(((hue/60)%2)-1)))\n      let m_ = val - e_\n      let rgb = [e_, e_, e_]\n      if(hue <  60) rgb = [e_, x_, 0]\n      if(hue >= 60  && hue < 120) rgb = [e_, 0, x_]\n      if(hue >= 120 && hue < 180) rgb = [x_, e_, 0]\n      if(hue >= 180 && hue < 240) rgb = [0, e_, x_]\n      if(hue >= 240 && hue < 300) rgb = [0, x_, e_]\n      if(hue >= 300 && hue < 360) rgb = [x_, 0, e_]\n      return rgb\n    }\n\n    stroke=(scol,fcol,globalAlphaOverride=0)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2*(globalAlphaOverride?globalAlphaOverride:1)\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500,2e3/Z)\n        x.stroke()\n        x.globalAlpha=1*(globalAlphaOverride?globalAlphaOverride:1)\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n    iBc=4,maxBc=iBc+1,iBG=20,iBv=10,dev=5\n    iBsplitProbability=.25,iBdieRate=.15\n    B=Array(iBc).fill().map(v=>{\n      X=S(p=Math.PI*2*Rn())*S(q=Math.PI/2*Rn()**.5)*iBG\n      Y=C(q)*iBG*(l=Rn()<.5?1:-1)\n      Z=C(p)*S(q)*iBG\n      vx=S(p)*S(q)*iBv\n      vy=C(q)*iBv*(l)\n      vz=C(p)*S(q)*iBv\n      return [X,Y,Z,vx,vy,vz,1]\n    })\n    P=[],iPsd=5,iPls=5\n    dieRate=.05,ograv=1.5\n    iSPv=2, SP=[], iSPdieRate=.05,iSPc=20\n    splode=(tx,ty,tz)=>{\n      for(let i=iSPc;i--;){\n        vx=S(p=Math.PI*2*Rn())*S(q=Math.PI/2*Rn()**.5)*iSPv\n        vy=C(q)*iSPv*(l=Rn()<.5?1:-1)\n        vz=C(p)*S(q)*iSPv\n        SP=[...SP, [tx,ty,tz,vx,vy,vz,1]]\n      }\n    }\n    idiev=2, die_ar=[], idiedieRate=.05,idiec=20\n    die=(tx,ty,tz)=>{\n      for(let i=idiec;i--;){\n        vx=S(p=Math.PI*2*Rn())*S(q=Math.PI/2*Rn()**.5)*idiev\n        vy=C(q)*idiev*(l=Rn()<.5?1:-1)\n        vz=C(p)*S(q)*iSPv\n        die_ar=[...die_ar, [tx,ty,tz,vx,vy,vz,1]]\n      }\n    }\n    go=false\n    bg = new Image()\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'/proxy.php?url=https://srmcgann.github.io/assets/2cyBpz.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.3\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0004\'\n    x.fillRect(0,0,c.width,c.height)\n    x.lineCap=x.lineJoin=\'round\'\n    oX=oY=0, oZ=100\n    Rl=t/2,Pt=-t,Yw=t*2\n\n    if(B.length>1)B=B.filter(v=>{\n      if(v[6]<0){\n        die(tx,ty,tz)\n        return false\n      }\n      return true\n    })\n\n    SP=SP.filter(v=>{\n      return v[6]>=0\n    })\n\n    SP.map(v=>{\n      X=v[0]+=v[3]\n      Y=v[1]+=v[4]\n      Z=v[2]+=v[5]\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        l=Q()\n        x.fillStyle=\'#80f2\'\n        s=Math.min(500,10000*v[6]/Z)\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=6\n        x.fillStyle=\'#f8fa\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n      v[6]-=iSPdieRate\n    })\n\n    die_ar=die_ar.filter(v=>{\n      return v[6]>=0\n    })\n\n    die_ar.map(v=>{\n      X=v[0]+=v[3]\n      Y=v[1]+=v[4]\n      Z=v[2]+=v[5]\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        l=Q()\n        x.fillStyle=\'#0f82\'\n        s=Math.min(500,10000*v[6]/Z)\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=6\n        x.fillStyle=\'#8ff\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n      v[6]-=iSPdieRate\n    })\n\n    B.map(v=>{\n\n      tx=v[0]\n      ty=v[1]\n      tz=v[2]\n      if(B.length<maxBc && Rn()<iBsplitProbability)splode(v[0],v[1],v[2]),B=[...B, [v[0],v[1],v[2],Rn()-.5,Rn()-.5,Rn()-.5,1]]\n\n      let a=[]\n      p1=Math.atan2(v[3],v[5])\n      p2=-Math.acos(v[4]/Math.hypot(v[3],v[4],v[5]))\n      for(j=iPsd;j--;){\n        X=S(p=Math.PI*2/iPsd*j)*iPls\n        Y=0\n        Z=C(p)*iPls\n        R(0,p2,p1)\n        X1=X+tx\n        Y1=Y+ty\n        Z1=Z+tz\n        X2=X+tx-v[3]\n        Y2=Y+ty-v[4]\n        Z2=Z+tz-v[5]\n        a=[...a, [X1,Y1,Z1,X2,Y2,Z2]]\n      }\n      P=[...P, [a,1]]\n      v[3]+=(Rn()-.5)*dev\n      v[4]+=(Rn()-.5)*dev\n      v[5]+=(Rn()-.5)*dev\n      p1=Math.atan2(v[0],v[2])\n      p2=-Math.acos(v[1]/Math.hypot(v[0],v[1],v[1]))\n      X=0\n      Y=ograv\n      Z=0\n      R(0,p2,p1)\n      v[3]-=X\n      v[4]-=Y\n      v[5]-=Z\n      d=Math.hypot(v[3],v[4],v[5])\n      v[3]/=d\n      v[4]/=d\n      v[5]/=d\n      v[3]*=iBv\n      v[4]*=iBv\n      v[5]*=iBv\n      X=v[0]+=v[3]\n      Y=v[1]+=v[4]\n      Z=v[2]+=v[5]\n\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s=Math.min(500,500/Z)\n        x.fillStyle=\'#fff2\'\n        l=Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=5\n        x.fillStyle=\'#fffa\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n\n      v[6]-=iBdieRate\n    })\n\n    P=P.filter(v=>v[1]>=0)\n\n    P.map(v=>{\n      v[0].map((q,j)=>{\n        x.beginPath()\n        X=q[0]\n        Y=q[1]\n        Z=q[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        X=q[3]\n        Y=q[4]\n        Z=q[5]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        X=v[0][(j+1)%v[0].length][3]\n        Y=v[0][(j+1)%v[0].length][4]\n        Z=v[0][(j+1)%v[0].length][5]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        X=v[0][(j+1)%v[0].length][0]\n        Y=v[0][(j+1)%v[0].length][1]\n        Z=v[0][(j+1)%v[0].length][2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        stroke(\'#0fa3\',\'#60f2\',v[1])\n      })\n      v[1]-=dieRate\n    })\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'wormholes fancy', 145, 'whitehot robot', '2023-01-20 20:25:39', '', 8, '', 0, 0),
(600651, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          spx=0\n          spy=0\n          spz=4\n          spr=6*sp\n          d=H(X-spx,Y-spy,Z-spz)\n          if(d<spr){\n            X=spx+(X-spx)/d*spr            \n            Y=spy+(Y-spy)/d*spr            \n            Z=spz+(Z-spz)/d*spr            \n          }\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX,Y+=oY,Z+=oZ\n          }\n        }\n\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background-repeat: no-repeat;\n  background-size: contain;\n  background-position: center center;\n  background-image: url(https://srmcgann.github.io/assets/1Sy6XR.gif);\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'cats eye (gif)', 145, 'whitehot robot', '2023-01-20 20:26:00', '', 8, '', 0, 0);
