(600652, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*1e3,c.height/2+Y/Z*1e3]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    for(j=6,CB=[];j--;CB=[...CB,b])for(i=4,b=[];i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n\n    getHSVfromRGB = (red, green, blue)=>{\n      let r_ = red//256\n      let g_ = green//256\n      let b_ = blue//256\n      let cmax=Math.max(r_, g_ , b_)\n      let cmin=Math.min(r_, g_ , b_)\n      let delta = cmax - cmin\n      let hue = 0\n      if(delta == 0)   hue = 0\n      if(cmax  == r_)  hue = (((g_-b_)/delta)%6)*60\n      if(cmax  == g_)  hue = (((b_-r_)/delta+2))*60\n      if(cmax  == b_)  hue = (((r_-g_)/delta+4))*60\n      let sat\n      if(cmax == 0) sat = 0\n      else sat = delta/cmax\n      let val = cmax\n      return [hue, sat, val]\n    }\n\n    getRGBfromHSV = (hue, sat, val) => {\n      sat=Math.max(1,sat)\n      let e_ = val * sat\n      let x_ = e_*(1-(Math.abs(((hue/60)%2)-1)))\n      let m_ = val - e_\n      let rgb = [e_, e_, e_]\n      if(hue <  60) rgb = [e_, x_, 0]\n      if(hue >= 60  && hue < 120) rgb = [e_, 0, x_]\n      if(hue >= 120 && hue < 180) rgb = [x_, e_, 0]\n      if(hue >= 180 && hue < 240) rgb = [0, e_, x_]\n      if(hue >= 240 && hue < 300) rgb = [0, x_, e_]\n      if(hue >= 300 && hue < 360) rgb = [x_, 0, e_]\n      return rgb\n    }\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=10\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n    CBrw=10\n    CBcl=10\n    CBbr=2\n    CBsp=3\n    CBls = CBsp/(2**.5*2)\n    CBs=Array(CBrw*CBcl*CBbr).fill().map((v,i)=>{\n      X=((i%CBcl)-CBcl/2+.5)*CBsp\n      Y=(((i/CBcl|0)%CBrw)-CBrw/2+.5)*CBsp\n      Z=((i/CBcl/CBrw|0)-CBbr/2+.5)*CBsp\n      return [X,Y,Z,CBls,[]]\n    })\n    CBs=CBs.filter(v=>{\n      d=Math.hypot(v[0],v[1])\n      return d<11\n    })\n    iPv=.25\n    dieRate=.02\n    bg=new Image()\n    go=false\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/1Xj9w0.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.4\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0005\'\n    x.fillRect(0,0,c.width,c.height)\n    x.lineJoin=x.lineCap=\'butt\'\n    oX=oY=0, oZ=30\n    Rl=Math.min(Math.PI/2,Math.max(-Math.PI/2,C(t)*3))\n    //Pt=Math.min(.35,Math.max(-.35,C(t)*2))\n    Pt=S(t)/4\n    Yw=Math.min(.35,Math.max(-.35,C(t)*2))\n    \n    if(!((t*60|0)%1)){\n      for(m=2;m--;){\n        let obj = CBs[Rn()*CBs.length|0]\n        tx=(Rn()-.5)*CBls\n        ty=(Rn()-.5)*CBls\n        tz=(Rn()-.5)*CBls\n        for(j=10;j--;){\n          X=tx,Y=ty,Z=tz\n          vx=(Rn()-.5)*iPv\n          vy=(Rn()-.5)*iPv\n          vz=(Rn()-.5)*iPv\n          obj[4]=[...obj[4], [X,Y,Z,vx,vy,vz,1]]\n        }\n      }\n    }\n\n    CBs.map((v,i)=>{\n      tx=v[0]\n      ty=v[1]\n      lz=S(Math.PI*2/CBs.length*(50/(20+Math.hypot(4,4)*1))+t)*4**6*Math.min(0,S(t))/2\n      tz=v[2]-S(Math.PI*2/CBs.length*(50/(20+Math.hypot(tx,ty)*1))+t)*4**6*Math.min(0,S(t))/2+lz\n      v[4]=v[4].filter(q=>q[6]>0)\n      v[4].map(q=>{\n        X=q[0]+q[3]\n        Y=q[1]+q[4]\n        Z=q[2]+q[5]\n        if(X>CBls/2||X<-CBls/2)q[3]*=-1\n        if(Y>CBls/2||Y<-CBls/2)q[4]*=-1\n        if(Z>CBls/2||Z<-CBls/2)q[5]*=-1\n        X=tx+(q[0]+=q[3])\n        Y=ty+(q[1]+=q[4])\n        Z=tz+(q[2]+=q[5])\n        q[6]-=dieRate\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          l=Q()\n          s=Math.min(500,1500*q[6]/Z)\n          x.fillStyle=\'#80f1\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          s/=8\n          x.fillStyle=\'#fff\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        }\n      })\n      CB.map(q=>{\n        x.beginPath()\n        q.map(n=>{\n          X=tx+n[0]*v[3]\n          Y=ty+n[1]*v[3]\n          Z=tz+n[2]*v[3]\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n        })\n        stroke(\'#ffffff10\', \'#00ffaa06\')\n      })\n    })\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'cats eye', 145, 'whitehot robot', '2023-01-20 20:26:40', '', 10, '', 0, 0),
