0\n          R(Rl,Pt,0,1)\n          x.lineTo(...Q())        \n        })\n        stroke(\'#fff1\',\'#00ccff04\')\n      })\n    }\n\n    ST.map(v=>{\n      Butterfly(...v,true)\n    })\n\n    if(!freezeframe){\n      for(m=2;m--;)for(let i=bsd;i--;){\n        let p\n        let ls = 70\n        let q=-Math.PI*3/100*(((t-.00)*14)%100)\n        X=S(p=q+Math.PI*4/bsd*i+Math.PI/2+Math.PI*(m?1:0))*ls\n        Y=(20-i-10)*4.75-((((t)*14)%100)/100)**2.5*100\n        Z=C(p)*ls\n        rl=0\n        pt=0\n        yw=p\n        if(Y>oty_) freezeFrame()\n        if(!freezeframe) Butterfly(X,Y,Z,rl,pt,yw,(99+(m*bsd+i)*6)**3.1%(Math.PI*2),spawn,true,false)\n      }\n      if(!freezeframe)for(m=2;m--;)for(let i=bsd;i--;){\n        let p\n        let ls = 72\n        let q=-Math.PI*3/100*(((t+.03)*14)%100)\n        tx=S(p=q+Math.PI*4/bsd*i+Math.PI/2+Math.PI*(m?1:0))*ls\n        ty=(20-i-10)*4.75-((((t+.00)*14)%100)/100)**2.5*100\n        tz=C(p)*ls\n        rl=0\n        pt=0\n        yw=p\n        CB.map(v=>{\n          x.beginPath()\n          v.map(q=>{\n            X=q[0]*20\n            Y=q[1]*10\n            Z=q[2]*20\n            R(rl,pt,yw)\n            X+=tx\n            ly=Y+=ty+2\n            Z+=tz\n            R(0,0,Yw)\n            X-=skew/2\n            X+=skew/100*(50-ny)\n            R(Rl,Pt,0,1)\n            x.lineTo(...Q())\n          })\n          if(!freezeframe) stroke(\'#fff2\')\n        })\n      }\n    }\n  }\n\n  if(!freezeframe) t+=1/60\n  t_+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'butterflies fancier', 145, 'whitehot robot', '2023-01-20 20:27:56', '', 16, '', 0, 0),
