(600659, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n    if(!t){\n      t_=0\n      skew=100\n      R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    for(CB=[],j=6;j--;CB=[...CB, b])for(i=4,b=[];i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?1:-1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n    Q=()=>[c.width/2+X/Z*1e3,c.height/2+Y/Z*1e3]\n    stroke=(scol, fcol)=>{\n      if(scol){\n        x.strokeStyle=scol\n        x.closePath()\n        x.lineWidth=Math.min(500,6000/Z)\n        x.globalAlpha=.2\n        x.stroke()\n        x.lineWidth/=6\n        x.globalAlpha=1\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    ST=[]\n    oty_=6e6\n    freezeframe=false\n\n    Butterfly=(tx,ty,tz,rl,pt,yw,seed,spawn,flap,flapstate,special)=>{\n      if(spawn && !freezeframe){\n        if(ty>oty_){\n          freezeframe=true\n          setTimeout(()=>{freezeframe=false,ST=[],oty_ = 6e6,t=t_},4000)\n          ST=[...ST, [tx,tx,tz,rl,pt,yw,seed,false,false,t*10+seed]]\n          return\n        } \n        ST=[...ST, [tx,ty,tz,rl,pt,yw,seed,false,false,t*10+seed]]\n        oty_ = ty\n      }\n      B=[]\n      sd=30, ls=5, a=[]\n      for(let i=sd;i--;){\n        ls_=ls+S(Math.PI*2/sd*4*i-Math.PI/2)\n        ls__=ls+S(Math.PI*2/sd*3*i+1.5)\n        X=S(p=Math.PI*2/sd*i)*ls_\n        Y_=C(p)*ls_+.5\n        Y__=C(p)*ls__-2.2\n        Y=Y_<-1?Y_:(Y__>1?(Y__**.5*2-2)**1.5:0)\n        Z=0\n        if(Y) a=[...a, [X,Y,Z]]\n      }\n      maxd=-6e6\n      a.map(v=>{\n        if(v[1]>maxd)maxd=v[1]\n      })\n      a.map(v=>{\n        X=v[0]\n        Y=v[1]-maxd\n        Z=v[2]\n        R(0,1+S(flap?t*10+seed:flapstate)*.9,0)\n        v[0]=X\n        v[1]=Y+maxd\n        v[2]=Z\n      })\n      b=JSON.parse(JSON.stringify(a))\n      b.map(v=>{\n        v[2]*=-1\n      })\n      B=[...B, a, b]\n      B.map(v=>{\n        x.beginPath()\n        v.map(q=>{\n          X=q[0]*2\n          ty___=Y=q[1]*2\n          Z=q[2]*2\n          R(rl,pt,yw,0)\n          X+=tx\n          Z+=tz\n          ny=Y+=ty\n          R(0,0,Yw)\n          X-=skew/2\n          X+=skew/100*(50-ty)\n          R(Rl,Pt,0,1)\n          if(Z>0){\n            x.lineTo(...Q())\n          }\n        })\n        stroke(special?\'#3308\':\'#40f8\', special?\'#ff03\':\'#40f3\')\n      })\n    }\n    clk=oclk=ny=0\n  }\n\n  x.fillStyle=\'#ffec\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin=x.linCap=\'round\'\n  oX=oY=0, oZ=150*1.65-Math.min(0,Math.max(-50,C(t_/2)*500))\n  Rl=Math.min(.95,Math.max(0,-C(t_/2)*2))\n  Pt=Math.min(Math.PI/2,Math.max(0,-C(t_/2)*4))\n  Yw=t_*1.75+.2\n\n  let bsd = 1\n  lsx=59*2\n  lsy=bsd*1.1\n  lsz=59*2\n\n\n  if(1)CB.map(v=>{\n    x.beginPath()\n    v.map(q=>{\n      X=q[0]*125\n      Y=q[1]*80\n      Z=q[2]*125\n      R(0,0,Yw)\n      X-=skew/2\n      X+=Y<0?skew:0\n      R(Rl,Pt,0,1)\n      if(Z>0){\n        x.lineTo(...Q())\n      }\n    })\n    stroke(\'#0002\',\'#fff8\')\n  })\n\n\n  for(m=bsd*25;m--;)CB.map(v=>{\n    mx=(((m%5)-2.5+.5)*(2**.5/2)*lsx/5)*2\n    mz=((((m/5|0)%5)-2.5+.5)*(2**.5/2)*lsz/5)*2\n    x.beginPath()\n    v.map(q=>{\n      X=q[0]*lsx/5+mx\n      Y=ty=q[1]*75/lsy+((m/25|0)-10)*5\n      Z=q[2]*lsz/5+mz\n      R(Rl,Pt,Yw,1)\n      X-=skew/2\n      X+=Y<0?skew:0\n      if(Z>0){\n        x.lineTo(...Q())\n      }\n    })\n    //stroke(\'#00000004\')\n  })\n\n  for(m=2;m--;){\n    x.beginPath()\n    for(i=6;i--;){\n      X=S(p=Math.PI*2/6*i+Math.PI/6*(m?1:0))*lsx/4\n      Y=52\n      Z=C(p)*lsz/4\n      R(0,0,Yw)\n      X-=skew/2\n      X+=Y<0?skew:0\n      R(Rl,Pt,0,1)\n      if(Z>0){\n        x.lineTo(...Q())\n      }\n    }\n    //stroke(\'#0005\')\n  }\n\n  if(0)for(k=2;k--;)for(m=k?5:4;m--;){\n    ls=(lsx/2+(m+(k?0:1))*lsx/4)/2.01\n    x.beginPath()\n    for(i=12;i--;){\n      Y=70*(k?-1:1)\n      X=S(p=Math.PI*2/12*i+Math.PI/12*(m?1:0))*ls\n      Z=C(p)*ls\n      R(0,0,Yw)\n      X-=skew/2\n      X+=Y<0?skew:0\n      R(Rl,Pt,0,1)\n      if(Z>0){\n        x.lineTo(...Q())\n      }\n    }\n    stroke(\'#0005\')\n  }\n\n  spawn=false\n  clk=12*1.5/100*(((t+.02)*14)%100)|0\n  if(oclk!=clk) spawn=true\n  oclk=clk\n\n  for(i=12;i--;){\n    tx=S(p_=Math.PI*2/12*i)*68\n    tz=C(p_)*72\n    CB.map(v=>{\n      x.beginPath()\n      v.map(q=>{\n        X=q[0]*20\n        Y=q[1]*80\n        Z=q[2]*20\n        let q_=p_\n        let p=q_\n        R(0,0,p)\n        X+=tx\n        Z+=tz\n        R(0,0,Yw)\n        X-=skew/2\n        X+=Y<0?skew:0\n        R(Rl,Pt,0,1)\n        x.lineTo(...Q())        \n      })\n      stroke(\'#0001\')\n    })\n  }\n\n  ST.map(v=>{\n    Butterfly(...v,true)\n  })\n\n  if(!freezeframe){\n    for(m=2;m--;)for(let i=bsd;i--;){\n      let p\n      let ls = 70\n      let q=-Math.PI*3/100*(((t-.00)*14)%100)\n      X=S(p=q+Math.PI*4/bsd*i+Math.PI/2+Math.PI*(m?1:0))*ls\n      Y=(20-i-10)*4.75-((((t)*14)%100)/100)**2.5*100\n      Z=C(p)*ls\n      rl=0\n      pt=0\n      yw=p\n      if(Y>oty_)freezeframe=true\n      oty_=Y\n      if(!freezeframe) Butterfly(X,Y,Z,rl,pt,yw,(99+(m*bsd+i)*6)**3.1%(Math.PI*2),spawn,true,false)\n    }\n    if(!freezeframe)for(m=2;m--;)for(let i=bsd;i--;){\n      let p\n      let ls = 72\n      let q=-Math.PI*3/100*(((t-.00)*14)%100)\n      tx=S(p=q+Math.PI*4/bsd*i+Math.PI/2+Math.PI*(m?1:0))*ls\n      ty=(20-i-10)*4.75-((((t+.00)*14)%100)/100)**2.5*100\n      tz=C(p)*ls\n      rl=0\n      pt=0\n      yw=p\n      CB.map(v=>{\n        x.beginPath()\n        v.map(q=>{\n          X=q[0]*20\n          Y=q[1]*10\n          Z=q[2]*20\n          R(rl,pt,yw)\n          X+=tx\n          ly=Y+=ty+2\n          Z+=tz\n          R(0,0,Yw)\n          X-=skew/2\n          X+=skew/100*(50-ny)\n          R(Rl,Pt,0,1)\n          x.lineTo(...Q())\n        })\n        if(!freezeframe) stroke(\'#0002\')\n      })\n    }\n  }\n\n  if(!freezeframe) t+=1/60\n  t_+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  color: #fff;\n  font-family: courier, arial;\n  font-size: 16px;\n  background: #000;\n  margin: 0;\n  min-height: 100vh;\n}\ncanvas{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  cursor: pointer;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}        \n', '<canvas id=c></canvas>\n', 'butterflies 2', 145, 'whitehot robot', '2023-01-20 20:29:58', '', 21, '', 0, 0),
