(600661, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    getHSVfromRGB = (red, green, blue)=>{\n      let r_ = red//256\n      let g_ = green//256\n      let b_ = blue//256\n      let cmax=Math.max(r_, g_ , b_)\n      let cmin=Math.min(r_, g_ , b_)\n      let delta = cmax - cmin\n      let hue = 0\n      if(delta == 0)   hue = 0\n      if(cmax  == r_)  hue = (((g_-b_)/delta)%6)*60\n      if(cmax  == g_)  hue = (((b_-r_)/delta+2))*60\n      if(cmax  == b_)  hue = (((r_-g_)/delta+4))*60\n      let sat\n      if(cmax == 0) sat = 0\n      else sat = delta/cmax\n      let val = cmax\n      return [hue, sat, val]\n    }\n\n    getRGBfromHSV = (hue, sat, val) => {\n      sat=Math.max(1,sat)\n      let e_ = val * sat\n      let x_ = e_*(1-(Math.abs(((hue/60)%2)-1)))\n      let m_ = val - e_\n      let rgb = [e_, e_, e_]\n      if(hue <  60) rgb = [e_, x_, 0]\n      if(hue >= 60  && hue < 120) rgb = [e_, 0, x_]\n      if(hue >= 120 && hue < 180) rgb = [x_, e_, 0]\n      if(hue >= 180 && hue < 240) rgb = [0, e_, x_]\n      if(hue >= 240 && hue < 300) rgb = [0, x_, e_]\n      if(hue >= 300 && hue < 360) rgb = [x_, 0, e_]\n      return rgb\n    }\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n  }\n\n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n  oX=oY=0, oZ=10\n  Rl=0,Pt=0,Yw=0\n  x.lineJoin=x.lineCap=\'round\'\n\n  h=540,sd=18*2\n  P=t?[...P.filter(v=>v[2]>2),...Array(sd).fill().map((v,i)=>[i-6-S(t*2-1.5)*4,4,16,i])]:[]\n    P.map((v,i)=>{\n      v[2]-=1\n      for(j=2;j--;)if(i>=sd){\n        x.beginPath()\n        X=v[0]\n        Y=v[1]*(l=j?-1:1)+S(i/40+t*8)*(S(Math.PI*4/sd*v[3]+t))*2\n        Z=v[2]\n        X+=S(Z/2+t*2)*3+S(t*2-1.5)*4-11\n        x.lineTo(960+X/Z*h,h+Y/Z*h)\n        X=P[i-sd][0]\n        Y=P[i-sd][1]*l+S((i-sd)/40+t*8)*(S(Math.PI*4/sd*v[3]+t))*2\n        Z=P[i-sd][2]\n        X+=S(Z/2+t*2)*3+S(t*2-1.5)*4-11\n        x.globalAlpha=1/(1+Z**7/5e6)\n        x.lineTo(960+X/Z*h,h+Y/Z*h)\n        x.lineWidth=400/Z\n        x.strokeStyle=`hsla(${Y*40+t*50},99%,50%,.15`\n        x.stroke()\n        x.strokeStyle=\'#fffa\'\n        x.lineWidth/=6\n        x.stroke()\n        x.globalAlpha=1\n      }\n    })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'space dweet', 145, 'wh