(600666, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=to=0\n\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth/document.body.clientWidth < 1.7777778)\n    {\n      c.style.width  = document.body.clientWidth + \'px\'\n      c.style.height = (document.body.clientWidth/1.777777778) + \'px\'\n    }else{\n      c.style.height = document.body.clientHeight + \'px\'\n      c.style.width  = (document.body.clientHeight*1.777777778) + \'px\'\n    }\n    c.width  = 1920\n    c.height = 1080\n  },0)\n}\nrsz()\n\nDraw=()=>{\n\n  if(!t){\n    mscol=\'#fff\'\n    R=(Rl,Pt,Yw,m)=>{\n      X-=960\n      Y-=540\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      if(m){\n        X+=oX,Y+=oY,Z+=oZ\n      }\n      X+=960\n      Y+=540\n    }\n    Q=q=>[c.width/2+(X-960)/Z*700,c.height/2+(Y-540)/Z*700]\n    for(φ=[1,1],i=60;i--;)φ=[...φ,φ[l=φ.length-2]+φ[l+1]];φ=φ[l]/φ[l-1]\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.strokeStyle=scol\n        x.closePath()\n        x.globalAlpha=.125\n        x.lineWidth=Math.min(500,20000/Z)\n        x.stroke()\n        x.lineWidth/=8\n        x.globalAlpha=1\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n    bg = new Image()\n    go = false\n    bg.onload=()=>{\n      go = true\n    }\n    bg.src = \'proxy.php?url=https://srmcgann.github.io/assets/1fnt59.png\'\n    //bg.src = \'/video/1fnt59.png\'\n  }\n\n  if(go){\n    mfcol=`hsla(${t*20},99%,50%,.065)`\n\n    if(bg.width/bg.height<1920/1080){\n      w=1080*(bg.width/bg.height)/1.1\n      h=1080/1.1 \n    }else{\n      w=1920/1.1\n      h=1920*(bg.height/bg.width)/1.1\n    }\n    x.globalAlpha=.5-C(t*2)/2\n    x.drawImage(bg,c.width/2-w/2,c.height/2-h/2,w,h)\n    x.globalAlpha=1\n    x.fillStyle=\'#0006\'\n    x.fillRect(0,0,c.width,c.height)\n    x.lineJoin=x.lineCap=\'round\'\n\n    oX=oY=0, oZ=800\n    Rl=S(t/6)*4\n    Pt=Math.max(-.25,Math.min(.25,C(t*4)*1))*(v=Math.max(0,Math.min(1,-S(t)*4)))\n    Yw=Math.max(-.25,Math.min(.25,S(t*4)*1))*v\n\n    sd=5,ls=500\n    minimus=-6e6\n    x.beginPath()\n    for(i=sd;i--;){\n      X=S(p=Math.PI*2/sd*i+Math.PI/sd)*ls\n      Y=C(p)*ls, Z=0\n      if(Y>minimus)mn=minimus=Y\n      X+=960, Y+=540\n      R(Rl,Pt,Yw,1)\n      x.lineTo(...Q())\n    }\n    stroke(\'#fff4\', mfcol)\n\n    /*x.beginPath()\n    X=0, Y=540+minimus, Z=0\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    X=1920, Y=540+minimus, Z=0\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    stroke(\'#fff4\', mfcol)\n\n    x.beginPath()\n    X=0,Y=540,Z=0\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    X=1920,Y=540,Z=0\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    stroke(\'#fff4\', mfcol)\n\n    x.beginPath()\n    X=0,Y=540+minimus/2,Z=0\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    X=1920,Y=540+minimus/2,Z=0\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    stroke(\'#fff\', mfcol)\n\n    x.beginPath()\n    X=0, Y=540+minimus-minimus/4,Z=0\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    X=1920, Y=540+minimus-minimus/4,Z=0\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    stroke(\'#fff8\', mfcol)*/\n    \n\n    sd=5,ls=500\n    sd2=6,ls1=0\n    for(m=0;m<6;m++) for(i=6;i---1;){\n      X1=S(p=Math.PI*2/sd*-1+Math.PI/sd)*ls\n      Y1=C(p)*ls\n      X2=S(p=Math.PI*2/sd*0+Math.PI/sd)*ls\n      Y2=C(p)*ls\n      ls1=minimus/2-((((5-m)*10)**(2/3))*13.5)\n      ax=X=(X1+X2)/2\n      Y=(ay=(Y1+Y2)/2)-ls1\n      p=Math.atan2(X,Y)+Math.PI*2/5*i\n      d=Math.hypot(X,Y)\n      X=S(p)*d\n      Y=C(p)*d\n      x.beginPath()\n      if(ls1>0){\n        tx=960+X, ty=540+Y, tz=0\n        if(Z>0){\n          x.beginPath()\n          for(j=99;j--;){\n            X=tx+S(p=Math.PI*2/99*j)*ls1\n            Y=ty+C(p)*ls1\n            Z=0\n            R(Rl,Pt,Yw,1)\n            x.lineTo(...Q())\n          }\n          stroke(mscol, \'\')\n        }\n      }\n    }\n    for(m=0;m<8;m++) for(i=1;i--;){\n      ls1=(minimus/2-((((8-m)*10)**(2/3))*13.5))\n      x.beginPath()\n      for(j=99;j--;){\n        X=960+S(p=Math.PI*2/99*j)*(d=minimus/10+ls1**.39*50)\n        Y=540+C(p)*d\n        Z=0\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          x.lineTo(...Q())\n        }\n      }\n      stroke(\'#fff8\',\'\')\n    }\n\n    sd=5,ls=500\n    x.beginPath()\n    for(i=99;i--;){\n      X=960+S(p=Math.PI*2/99*i)*minimus\n      Y=540+C(p)*minimus \n      Z=0\n      R(Rl,Pt,Yw,1)\n      x.lineTo(...Q())\n    }\n    stroke(\'#fff8\', mfcol)\n\n    sd=5,ls=500\n    x.beginPath()\n    for(i=sd;i--;){\n      X=960+S(p=Math.PI*2/sd*i+Math.PI/sd)*minimus\n      Y=540+C(p)*minimus\n      Z=0\n      R(Rl,Pt,Yw,1)\n      x.lineTo(...Q())\n    }\n    stroke(\'#fff8\', mfcol)\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body, html{\n  margin: 0;\n  width: 100%;\n  height: 100vh;\n  overflow: hidden;\n  background: #000;\n}\n#c{\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  width: 100%;\n  height: 100%;\n  background-position: center center;\n  background-size: fill;\n  transform: translate(-50%, -50%);\n}\n#textInput{\n  position: fixed;\n  width: 100vw;\n  font-size: 32px;\n  border: none;\n  background: #000;\n  color: #fff;\n  text-align: center;\n  border-bottom: 1px solid #4fc;\n  font-family: courier, arial;\n}\n#textInput:focus{\n  outline: none;\n}', '<canvas id=c></canvas>\n', 'sacred geometry', 145, 'whitehot robot', '2023-01-20 20:35:16', '', 51, '', 0, 0),
(600667, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          spx=0\n          spy=0\n          spz=4\n          spr=6*sp\n          d=H(X-spx,Y-spy,Z-spz)\n          if(d<spr){\n            X=spx+(X-spx)/d*spr            \n            Y=spy+(Y-spy)/d*spr            \n            Z=spz+(Z-spz)/d*spr            \n          }\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX,Y+=oY,Z+=oZ\n          }\n        }\n\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background-repeat: no-repeat;\n  background-size: contain;\n  background-position: center center;\n  background-image: url(https://srmcgann.github.io/assets/ERabF.gif);\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'sacred geometry (gif)', 145, 'whitehot robot', '2023-01-20 20:35:53', '', 59, '', 0, 0);
