(600669, '', 'Rn=Math.random\nvar main = document.querySelector(\'.main\')\nvar letters = \'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789\'+\' \'.repeat(30)\nvar imgs=[\n  \'1Z8Fbl.gif\',\n  \'1CGB7A.gif\',\n  \'isWiC.gif\',\n  \'vXDaE.gif\',\n  \'1CK5II.gif\',\n  \'27xCaM.gif\',\n]\n\nTile=()=>{\n  img = document.createElement(\'img\')\n  img.src = \'https://srmcgann.github.io/assets/\'+imgs[Rn()*imgs.length|0]\n  span = document.createElement(\'span\')\n  span.innerHTML=Array(10+Rn()*50|0).fill().map(v=>letters[Rn()*letters.length|0]).join(\'\')\n  el = document.createElement(\'div\')\n  br = document.createElement(\'br\')\n  el.className=\'tile\'\n  el.appendChild(img)\n  el.appendChild(br)\n  el.appendChild(span)\n  return el\n}\n\nfor(i=50;i--;){\n  el = Tile()\n  main.appendChild(el)\n}', 'body,html{\n  margin: 0;\n  height: 100vh;\n  overflow: auto;\n  font-family: courier, arial;\n  background: #000;\n  color: #fff;\n}\n.main{\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: space-evenly;\n}\nimg{\n  margin: 10px;\n  width: calc(100% - 20px);\n}\n.tile{\n  background-color: #333;\n  text-align: center;\n  position: relative;\n  margin: 10px;\n  height: 200px;\n  width: 200px;\n  display: inline-block;\n  vertical-align: bottom;\n}\nspan{\n  background: #4ff4;\n  width: 100%;\n  position: absolute;\n  transform: translate(-50%);\n  bottom: 0;\n}', '<div class=\"main\">\n</div>', 'pin text to bottom', 145, 'whitehot robot', '2023-01-20 20:36:52', '', 76, '', 0, 0),
