(600673, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    for(CB=[],j=6;j--;CB=[...CB,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        //x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 300/Z)\n        //x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=12\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    geoSphere = (mx, my, mz, iBc, size) => {\n      let collapse=0\n      let B=Array(iBc).fill().map(v=>{\n        X = Rn()-.5\n        Y = Rn()-.5\n        Z = Rn()-.5\n        return  [X,Y,Z]\n      })\n      for(let m=50;m--;){\n        B.map((v,i)=>{\n          X = v[0]\n          Y = v[1]\n          Z = v[2]\n          B.map((q,j)=>{\n            if(j!=i){\n              X2=q[0]\n              Y2=q[1]\n              Z2=q[2]\n              d=1+(Math.hypot(X-X2,Y-Y2,Z-Z2)*(3+iBc/40)*3)**4\n              X+=(X-X2)*99/d\n              Y+=(Y-Y2)*99/d\n              Z+=(Z-Z2)*99/d\n            }\n          })\n          d=Math.hypot(X,Y,Z)\n          v[0]=X/d\n          v[1]=Y/d\n          v[2]=Z/d\n          if(collapse){\n            d=25+Math.hypot(X,Y,Z)\n            v[0]=(X-X/d)/1.1\n         \n            v[2]=(Z-Z/d)/1.1\n          }\n        })\n      }\n\n      mind=6e6\n      B.map((v,i) => {\n        X = v[0]\n        Y = v[1]\n        Z = v[2]\n        B.map((q,j) => {\n          if(j!=i){\n            X2 = q[0]\n            Y2 = q[1]\n            Z2 = q[2]\n            if((d=Math.hypot(X2-X,Y2-Y,Z2-Z))<mind)mind=d\n          }\n        })\n      })\n\n      P=[]\n      B.map((v,i) => {\n        X = v[0]\n        Y = v[1]\n        Z = v[2]\n        B.map((q,j) => {\n          if(j!=i){\n            X2 = q[0]\n            Y2 = q[1]\n            Z2 = q[2]\n            if(Math.hypot(X2-X,Y2-Y,Z2-Z)<mind*1.62){\n              P=[...P,[X,Y,Z,X2,Y2,Z2,i,j]]\n            }\n          }\n        })\n      })\n      P.map(v=>{\n        v[0]*=size\n        v[1]*=size\n        v[2]*=size\n        v[3]*=size\n        v[4]*=size\n        v[5]*=size\n      })\n      B.map(v=>{\n        v[0]*=size\n        v[1]*=size\n        v[2]*=size\n        v[0]+=mx\n        v[1]+=my\n        v[2]+=mz\n        v[3]=.01\n        v[4]=0\n      })\n      return [mx, my, mz, size, B, P]\n    }\n\n\n    ls = .2\n    sd = 150\n    freq = 200\n    G = 10\n\n    init=()=>{\n      iBc = 3+(Rn()*3|0)\n      expansion = .1\n\n      a = []\n      for(i = sd; i--;){\n        X = S(p=Math.PI*2/sd*i)*ls\n        Y = C(p)*ls\n        Z = 0\n        a = [...a, [X, Y, Z, ls, 0]]\n      }\n\n      B=Array(iBc).fill().map(v=>{\n        X = (Rn()-.5) * G/1.25\n        Y = (Rn()-.5) * G/1.25\n        Z = (Rn()-.5) * G/1.25\n        let sph = JSON.parse(JSON.stringify(Geo))\n        return [X,Y,Z,sph,1]\n      })\n    }\n\n    starsLoaded = false, stars = [{loaded: false}]\n    stars = Array(10).fill().map((v,i) => {\n      let a = {img: new Image(), loaded: false}\n      a.img.onload = () => {\n        a.loaded = true\n        setTimeout(()=>{\n          if(stars.filter(v=>v.loaded).length == 10) starsLoaded = true, init()\n        }, 0)\n      }\n      a.img.src = `proxy.php?url=https://srmcgann.github.io/temp/stars/star${i?i:\'\'}.png`\n      return a\n    })\n\n    Geo = geoSphere(0,0,0,sd,ls)\n\n    bg = new Image()\n    go = false\n    bg.onload=()=>{\n      go = true \n    }\n    bg.src = \'proxy.php?url=https://srmcgann.github.io/assets/2705Yc.jpg\'\n  }\n\n\n  if(go && starsLoaded){\n    x.globalAlpha = .3\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha = 1\n    x.fillStyle=\'#0003\'\n    x.fillRect(0,0,c.width,c.height)\n\n    oX=oY=0, oZ=G*1.5 \n    Rl=t/4,Pt=-C(t)/2,Yw=S(t)/2\n    x.lineJoin=x.lineCap=\'butt\'\n\n    if(!((t*60|0)%freq)) init()\n\n    CB.map(v=>{\n      let ls = G * (2**.5/2)\n      x.beginPath()\n      v.map(q=>{\n        X=q[0]*ls\n        Y=q[1]*ls\n        Z=q[2]*ls\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n      })\n      stroke(\'#fff1\', \'#00ccff06\')\n    })\n\n    for(let g=5;g--;) B.map((v,i) => {\n      tx = v[0]\n      ty = v[1]\n      tz = v[2]\n      st_=false\n      if(v[4]){\n        v[3][4].map(k => {\n          if(!k[4]){\n            X = tx + k[0] * k[3]\n            Y = ty + k[1] * k[3]\n            Z = tz + k[2] * k[3]\n            st = true\n            B.map((n,m)=>{\n              if(m!=i){\n                X2 = n[0]\n                Y2 = n[1]\n                Z2 = n[2]\n                d = Math.hypot(X2-X,Y2-Y,Z2-Z)*10\n                if(k[3] >= d/2 || X>G/2 || X<-G/2 || Y>G/2 || Y<-G/2 || Z>G/2 || Z<-G/2) st = false\n              }\n            })\n            if(st) k[3] += expansion\n            else k[4]++\n            if(st)st_=true\n           }\n           v[4] = st_\n         })\n       }\n     })\n     B.map((v,i) => {\n      tx = v[0]\n      ty = v[1]\n      tz = v[2]\n      v[3][5].map(k => {\n        x.beginPath()\n        X = tx + k[0] * v[3][4][k[6]][3]\n        Y = ty + k[1] * v[3][4][k[6]][3]\n        Z = tz + k[2] * v[3][4][k[6]][3]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        X = tx + k[3] * v[3][4][k[7]][3]\n        Y = ty + k[4] * v[3][4][k[7]][3]\n        Z = tz + k[5] * v[3][4][k[7]][3]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        stroke(v[3][4][k[7]][4]?\'#4f03\':\'#0afa\')\n      })\n      x.globalAlpha = (.5+S(t*16)/2)*.7\n      if(1)v[3][4].map(k => {\n        X = tx + k[0] * k[3]\n        Y = ty + k[1] * k[3]\n        Z = tz + k[2] * k[3]\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          l = Q()\n          s = Math.min(1e3, 500*(k[4]?3:5)/Z)\n          x.drawImage((k[4]?stars[1].img:stars[9].img),l[0]-s/2,l[1]-s/2,s,s)\n        }\n      })\n      x.globalAlpha = 1\n      X = tx\n      Y = ty\n      Z = tz\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        l = Q()\n        s = Math.min(1e3, 5000/Z)\n        x.drawImage(stars[5].img,l[0]-s/2,l[1]-s/2,s,s)\n      }\n    })\n  }\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'voronoi 3d deluxe', 145, 'whitehot robot', '2023-01-21 03:11:30', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 104, '', 0, 0),
