(600679, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      if(m){ \n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.lineJoin=x.lineCap=\'butt\'\n        x.closePath()\n        //x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 200/Z)\n        //x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n        x.lineJoin=x.lineCap=\'butt\'\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    stroke2=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=6\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n    floor = (X,Z) => {\n      return 20/(2+S(.8+Math.hypot(X,Z)**2/60+t*6))-10\n    }\n\n    rw = 34\n    cl = 34\n    br = 1\n    sp = 1\n    B=Array(rw*cl*br).fill().map((v,i)=>{\n      X = ((i%cl)-cl/2+.5)*sp\n      Z = (((i/cl|0)%rw)-rw/2+.5)*sp\n      Y = ((i/cl/rw|0)-br/2+.5)*sp + floor(X,Z)\n      return [X,Y,Z]\n    })\n\n    rw2 = 35\n    cl2 = 12\n    br2 = 1\n    sp2 = 2\n    B2 = Array(rw2*cl2*br2).fill().map((v,i)=>{\n      X = ((i%cl2)-cl2/2+.5)*sp2\n      Z = (((i/cl2|0)%rw2)-rw2/2+.5)*sp2\n      Y = ((i/cl2/rw2|0)-br2/2+.5)*sp + floor(X,Z)\n      return [X,Y,Z]\n    })\n\n    starsLoaded = false, stars = [{loaded: false}]\n    stars = Array(10).fill().map((v,i) => {\n      let a = {img: new Image(), loaded: false}\n      a.img.onload = () => {\n        a.loaded = true\n        setTimeout(()=>{\n          if(stars.filter(v=>v.loaded).length == 10) starsLoaded = true\n        }, 0)\n      }\n      a.img.src = `proxy.php?url=https://srmcgann.github.io/temp/stars/star${i?i:\'\'}.png`\n      return a\n    })\n\n    bg = new Image()\n    go = false\n    bg.onload=()=>{\n      go = true\n    }\n    bg.src = \'proxy.php?url=https://srmcgann.github.io/assets/2705Yc.jpg\'\n\n    P = []\n  }\n\n  if(starsLoaded && go){\n    x.globalAlpha=.2\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0005\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=oY=0, oZ=24\n    Rl=S(t)/4,Pt=-t/4,Yw=-t/2\n    x.lineJoin=x.lineCap=\'butt\'\n    \n    perim = 15, sd = 32\n\n    ls = perim + Math.hypot(sp,sp)/2\n    for(i=sd;i--;){\n      x.beginPath()\n      X = S(p=Math.PI*2/sd*i)*ls\n      Z = C(p)*ls\n      Y = floor(X,Z)\n      R(Rl,Pt,Yw,1)\n      if(Z>0) x.lineTo(...Q())\n      X = S(p=Math.PI*2/sd*(i+1))*ls\n      Z = C(p)*ls\n      Y = floor(X,Z)\n      R(Rl,Pt,Yw,1)\n      if(Z>0) x.lineTo(...Q())\n      stroke2(\'#0f88\')\n    }\n\n    for(m=5;m--;)if(!((t*60|0)%0)){\n      X = S(p=Math.PI*2*Rn())*perim\n      Z = C(p)*perim\n      Y = floor(X,Z)\n      P = [...P, [X,Y,Z,Rn()*10|0]]\n    }\n\n    ls2 = 1/1.5,ox=oz=0,tog=false\n    B2.map((v,i)=>{\n      tx = v[0]*2\n      ty = v[1]*2\n      tz = v[2]*0.8660254037844386/3*2\n      if(oz!=tz)tog=!tog\n      oz=tz \n      keep = true\n      x.beginPath()\n      for(j=6;j--;){\n        X = tx + (S(p=Math.PI*2/6*j+Math.PI/6)*ls2+(tog?ls2*1.5:0))*2\n        Z = tz + (C(p)*ls2)*2\n        if((d=Math.hypot(X,Z))>=perim*1.2)keep=false\n        if(keep){\n          if(d>perim){\n            X/=d\n            Z/=d\n            X*=perim*1.05\n            Z*=perim*1.05\n          }\n          Y = floor(X,Z)\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n        }\n      }\n      if(keep) stroke2(\'#0fc3\')\n    })\n\n    if(1) B.map((v,i)=>{\n      if(i%cl && i/cl|0){\n        ax=ay=az=0\n\n        l = i\n        ax += B[l][0]\n        az += B[l][2]\n        l = i-1\n        ax += B[l][0]\n        az += B[l][2]\n        l = i-1-cl\n        ax += B[l][0]\n        az += B[l][2]\n        l = i-cl\n        ax += B[l][0]\n        az += B[l][2]\n\n        ax/=4\n        az/=4\n\n        if((d=Math.hypot(ax,az))<perim*1.1){\n          x.beginPath()\n          l = i\n          X = B[l][0]\n          Z = B[l][2]\n          if((d=Math.hypot(X,Z))>perim*1.05){\n            X/=d\n            Z/=d\n            X*=perim*1.05\n            Z*=perim*1.05\n          }\n          Y = floor(X,Z)\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n          l = i-1\n          X = B[l][0]\n          Z = B[l][2]\n          if((d=Math.hypot(X,Z))>perim*1.05){\n            X/=d\n            Z/=d\n            X*=perim*1.05\n            Z*=perim*1.05\n          }\n          Y = floor(X,Z)\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n          l = i-1-cl\n          X = B[l][0]\n          Z = B[l][2]\n          if((d=Math.hypot(X,Z))>perim*1.05){\n            X/=d\n            Z/=d\n            X*=perim*1.05\n            Z*=perim*1.05\n          }\n          Y = floor(X,Z)\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n          l = i-cl\n          X = B[l][0]\n          Z = B[l][2]\n          if((d=Math.hypot(X,Z))>perim*1.05){\n            X/=d\n            Z/=d\n            X*=perim*1.05\n            Z*=perim*1.05\n          }\n          Y = floor(X,Z)\n          R(Rl,Pt,Yw,1)\n          if(Z>0) x.lineTo(...Q())\n          stroke(\'#f004\', \'#60F2\')\n        }\n      }\n    })\n\n    P = P.filter(v=>Math.hypot(v[0],v[2])>2)\n    spd = .2\n\n    P.map(v=>{\n      X=v[0]\n      Z=v[2]\n      d1=Math.hypot(X,Z)\n      p = Math.atan2(X,Z)+2/(1+d1**2/2)\n      v[0] = S(p)*d1\n      v[2] = C(p)*d1\n      X/=d1\n      Z/=d1\n      X = v[0] -= X*spd\n      Z = v[2] -= Z*spd\n      v[1]=Y=floor(X,Z)\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        x.globalAlpha = Math.min(1, (d1/4)**5)\n        s = Math.min(1e3, 1e4/Z**1.5)\n        l = Q()\n        x.drawImage(stars[v[3]].img,l[0]-s/2,l[1]-s/2,s,s)\n      }\n    })\n    x.globalAlpha = 1\n    Y=floor(X=0,Z=0)\n    R(Rl,Pt,Yw,1) \n    s=Math.min(3e3,1e4/Z)\n    l=Q()\n    if(Z>0) x.drawImage(stars[5].img,l[0]-s/2.1,l[1]-s/2.1,s,s)\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'blobbo', 145, 'whitehot robot', '2023-01-25 00:18:47', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 100, '', 0, 0),
(600680, '', '    c=document.querySelector(\'#c\')\n    x=c.getContext(\'2d\')\n    S=Math.sin\n    C=Math.cos\n    Rn=Math.random\n    t=go=0\n    rsz=window.onresize=()=>{\n      setTimeout(()=>{\n        if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n          c.style.height = \'100vh\'\n          setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n        }else{\n          c.style.width = \'100vw\'\n          setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n        }\n        c.width=1920\n        c.height=c.width/1.777777778\n      },0)\n    }\n    rsz()\n\n    Draw=()=>{\n      if(!t){\n        R=(Rl,Pt,Yw,m)=>{\n          M=Math\n          A=M.atan2\n          H=M.hypot\n          spx=0\n          spy=0\n          spz=4\n          spr=6*sp\n          d=H(X-spx,Y-spy,Z-spz)\n          if(d<spr){\n            X=spx+(X-spx)/d*spr            \n            Y=spy+(Y-spy)/d*spr            \n            Z=spz+(Z-spz)/d*spr            \n          }\n          X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n          Y=C(p)*d\n          X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n          Z=C(p)*d\n          Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n          Z=C(p)*d\n          if(m){\n            X+=oX,Y+=oY,Z+=oZ\n          }\n        }\n\n        Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n        for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      }\n\n      t+=1/60\n      requestAnimationFrame(Draw)\n    }\n    Draw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  background-repeat: no-repeat;\n  background-size: contain;\n  background-position: center center;\n  background-image: url(https://srmcgann.github.io/assets/1LhEtl.gif);\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'blobbo (gif)', 145, 'whitehot robot', '2023-01-25 02:39:54', '[600678,600675,600674,600672,600670]', 87, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600681, 'https://twilightparadox.com/gosper_el2.mp4', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n    c.height|=0\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol,tz=Z)=>{\n      if(scol){\n        //x.closePath()\n        x.globalAlpha=.1\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/tz)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=16\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    aturns=\"A-B--B+A++AA+B-\".split(\'\')\n    bturns=\"+A-BB--B-A++A+B\".split(\'\')\n    maxLen=38000*4\n    for(let m=2;m--;){\n      turns = []\n      aturns.map(q=>{\n        if(turns.length>maxLen) {fturns=turns; return}\n        switch(q){\n          case \'A\':\n            turns=[...turns, ...aturns]\n          break\n          case \'B\':\n            turns=[...turns, ...bturns]\n          break\n          case \'-\':\n            turns=[...turns, \'-\']\n          break\n          case \'+\':\n            turns=[...turns, \'+\']\n          break\n        }\n      })\n      aturns_ = turns\n\n      turns = []\n      bturns.map(q=>{\n        if(turns.length>maxLen) {fturns=turns; return}\n        switch(q){\n          case \'A\':\n            turns=[...turns, ...aturns]\n          break\n          case \'B\':\n            turns=[...turns, ...bturns]\n          break\n          case \'-\':\n            turns=[...turns, \'-\']\n          break\n          case \'+\':\n            turns=[...turns, \'+\']\n          break\n        }\n      })\n      aturns = aturns_\n      bturns = turns\n      fturns = turns = aturns\n      if(turns.length>maxLen) {fturns=turns; break}\n    }\n\n    getAverage = (turns, depth, q, X_, Y_, Z_) => {\n      avg = []\n      q=0\n      X_=Y_=Z_=0\n      recurse = (turns, depth, q, X_, Y_, Z_) => {\n        if(depth>0) return\n        turns.map(v=>{\n          switch(v){\n            case \'A\':\n              X_ += S(q)\n              Y_ += C(q)\n              Z_ =  0\n              avg = [...avg, [X_, Y_, Z_]]\n              recurse(aturns, depth+1, q, X_, Y_, Z_)\n            break\n            case \'B\':\n              X_ += S(q)\n              Y_ += C(q)\n              Z_ =  0\n              avg = [...avg, [X_, Y_, Z_]]\n              recurse(bturns, depth+1, q, X_, Y_, Z_)\n            break\n            case \'-\':\n              q -= Math.PI/3\n            break\n            case \'+\':\n              q += Math.PI/3\n            break\n          }\n        })\n      }\n      recurse(turns, depth, q, X_, Y_, Z_)\n      ax=ay=az=0\n      avg.map(v=>{\n        ax += v[0]\n        ay += v[1]\n        ax += v[2]\n      })\n      ax /= avg.length\n      ay /= avg.length\n      az /= avg.length\n    }\n\n    turns = fturns\n    getAverage(turns, 0, 0, 0, 0, 0)\n\n    plot = (turns, depth, q, X_, Y_, Z_, tx, ty, tz) => {\n      X=tx\n      Y=ty\n      Z=tz\n      q=0\n      x.beginPath()\n      //x.lineTo(...Q())\n      X_=Y_=Z_=X=Y=Z=0\n      recurse = (turns, depth, q, X_, Y_, Z_) => {\n        if(depth>0) return\n        turns.map(v=>{\n          switch(v){\n            case \'A\':\n              X_ = X = X_ + S(q)\n              Y_ = Y = Y_ + C(q)\n              Z_ = Z = 0\n              X+=tx\n              Y+=ty\n              Z+=tz\n              R(Rl,Pt,Yw,1)\n              x.lineTo(...Q())\n              recurse(aturns, depth+1, q, X_, Y_, Z_, tx, ty, tz)\n            break\n            case \'B\':\n              X_ = X = X_ + S(q)\n              Y_ = Y = Y_ + C(q)\n              Z_ = Z = 0\n              X+=tx\n              Y+=ty\n              Z+=tz\n              R(Rl,Pt,Yw,1)\n              x.lineTo(...Q())\n              recurse(bturns, depth+1, q, X_, Y_, Z_, tx, ty, tz)\n            break\n            case \'-\':\n              q -= Math.PI/3\n            break\n            case \'+\':\n              q += Math.PI/3\n            break\n          }\n        })\n      }\n      recurse(turns, depth, q, X_, Y_, Z_, tx, ty, tz)\n      stroke(\'#afca\',\'\',tz+oZ)\n    }\n    bg = new Image()\n    go = false\n    bg.onload=()=>{\n      go = true\n    }\n    bg.src = \'proxy.php?url=https://srmcgann.github.io/assets/74qWo.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha = .3\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha = 1\n    x.fillStyle=\'#0004\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=oY=0, oZ=35+Math.max(-15,Math.min(15, S(t)*40))/1\n    Rl=t/2\n    Pt=Math.max(-.25,Math.min(.25,S(-t)*1))\n    Yw=Math.max(-.25,Math.min(.25,C(-t)*1))\n    //Rl=Pt=Yw=0\n\n    x.lineJoin = x.lineCap = \'butt\'\n  \n    for(m=1;m--;) plot (turns, 0, 0, 0, 0, 0, -ax, -ay, -5 + m*(Math.max(0,Math.min(1,(.33+S(t*4)*1)*2))))\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'gosper curve', 145, 'whitehot robot', '2023-01-25 15:55:21', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 95, 'https://code.dweet.net/thumbs/790733b3b5c808751a3dbf21c08f2f41.jpg', 0, 0),
(600682, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle=scol\n        x.lineWidth=Math.min(500, 500/Z)\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=4\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    P=[]\n\n    G=100, iPv=0\n\n    spawnP = () => {\n      X = (Rn()-.5)*G\n      Y = 0\n      Z = (Rn()-.5)*G\n      vx = S(p=Rn()*Math.PI*2)*(v=Rn()*iPv)\n      vy = 0\n      vz = C(p)*v\n      P=[...P, [X,Y,Z,vx,vy,vz,1,Rn()*10|0]]\n    }\n\n    iBc = 16, iBv=2\n    B=Array(iBc).fill().map(v => {\n      X = (Rn()-.5)*G/1.5\n      Y = 0\n      Z = (Rn()-.5)*G/1.5\n      vx = (Rn()-.5)*iBv\n      vy = 0\n      vz = (Rn()-.5)*iBv\n      return [X,Y,Z,vx,vy,vz]\n    })\n\n    floor = (X,Z) => {\n      g=0\n      B.map(v=>{\n        X2=v[0]\n        Y2=v[1]\n        Z2=v[2]\n        d=(3+Math.hypot(X-X2,Z-Z2))**2/4\n        g+=100/(1+d)\n      })\n      return g\n    }\n\n    bg = new Image()\n    go=false\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/2705Yc.jpg\'\n\n    starsLoaded = false, stars = [{loaded: false}]\n    stars = Array(10).fill().map((v,i) => {\n      let a = {img: new Image(), loaded: false}\n      a.img.onload = () => {\n        a.loaded = true\n        setTimeout(()=>{\n          if(stars.filter(v=>v.loaded).length == 10) starsLoaded = true, init()\n        }, 0)\n      }\n      a.img.src = `proxy.php?url=https://srmcgann.github.io/temp/stars/star${i?i:\'\'}.png`\n      return a\n    })\n  }\n\n  if(go && starsLoaded){\n    x.globalAlpha = .2\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha = 1\n    x.fillStyle=\'#0006\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=0, oY=0, oZ=80+Math.max(-20,Math.min(20,S(t)*80))\n    Rl=S(t)/2,Pt=Math.PI/2-S(t/2)/1,Yw=C(t*2)/2\n\n    for(m=50;m--;)if(!((t*60|0)%0)) spawnP()\n\n    P=P.filter(v=>v[6]>0)\n\n    P.map(v=>{\n      X=v[0]+=v[3]\n      Z=v[2]+=v[5]\n      if(X>G/2)X-=G\n      if(X<-G/2)X+=G\n      if(Z>G/2)Z-=G\n      if(Z<-G/2)Z+=G\n      if((d_=Math.hypot(X,Z))<G/2){\n        L=Y=floor(X,Z)\n        v[6]-=.02\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          s=Math.min(1e3,Math.max(0,Math.min(20,L-7)*600/Z))\n          l=Q()\n          x.drawImage(stars[9].img,l[0]-s/2,l[1]-s/2,s,s)\n        }\n      }\n    })\n\n    B.map(v=>{\n      X=v[0]+=v[3]\n      Z=v[2]+=v[5]\n      Y=floor(X,Z)\n      if(X>G/2.5 || X<-G/2.5) v[3]*=-1\n      if(Z>G/2.5 || Z<-G/2.5) v[5]*=-1\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s=Math.min(1e3,15000/Z)\n        l=Q()\n        x.drawImage(stars[7].img,l[0]-s/2,l[1]-s/2,s,s)\n        /*\n        x.fillStyle=\'#0f82\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=3\n        x.fillStyle=\'#8ff\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)*/\n      }\n    })\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'meandering vortices', 145, 'whitehot robot', '2023-01-26 00:12:40', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 100, '', 0, 0),
