/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Cube=ls=>{\n      let ret=[]\n      for(j=6;j--;ret=[...ret,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2                                                                                                            ])[j%3]*(l=j<3?-ls:ls),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Icosahedron=ls=>{\n      let a=[1,1],ret=[]\n      let b\n      for(i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]];\n      let phi=a[l]/a[l-1]\n      a=[[[-phi,-1,0],[phi,-1,0],[phi,1,0],[-phi,1,0]],[[0,-phi,-1],[0,phi,-1],[0,phi,1],[0,-phi,1]],[[                                                                                                            -1,0,-phi],[-1,0,phi],[1,0,phi],[1,0,-phi]]]\n      let ico=[[[0,1],[1,0],[1,3]],[[0,1],[2,3],[1,0]],[[2,0],[2,3],[1,0]],[[0,1],[2,3],[0,2]],[[1,1],[                                                                                                            2,3],[0,2]],[[1,1],[2,3],[2,0]],[[1,1],[1,2],[0,2]],[[0,1],[2,2],[0,2]],[[0,0],[1,0],[2,0]],[[2,0],[0,3                                                                                                            ],[0,0]],[[1,1],[1,2],[0,3]],[[1,1],[2,0],[0,3]],[[0,1],[1,3],[2,2]],[[1,3],[2,1],[2,2]],[[2,1],[0,3],[                                                                                                            1,2]],[[2,1],[0,0],[1,3]],[[1,2],[2,2],[2,1]],[[2,2],[1,2],[0,2]],[[0,3],[2,1],[0,0]],[[1,3],[1,0],[0,0                                                                                                            ]]]\n      ico.map((v,i)=>{\n        b=[]\n        v.map(q=>{\n          t1=q[0],t2=q[1]\n          X=a[t1][t2][0],Y=a[t1][t2][1],Z=a[t1][t2][2]\n          b=[...b, [X,Y,Z]]\n        })\n        ret=[...ret, b]\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Dodecahedron=ls=>{\n      let ret=[]\n      let sd=5\n      let a=[], b=[]\n      mind=6e6\n      for(let i=sd;i--;){\n        X=S(p=Math.PI*2/sd*i)\n        Y=C(p)\n        Z=0\n        if(Y<mind)mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a=a.map(v=>{\n        X=v[0]\n        Y=v[1]-=mind\n        Z=v[2]\n        R2(0,.5535735,0)\n        return [X,Y,Z]\n      })\n\n      ret = [...ret, a]\n      b=JSON.parse(JSON.stringify(a)).map(v=>{\n        d=Math.hypot(v[0],v[1])\n        v[0]=S(p=Math.atan2(v[0],v[1])+Math.PI)*d\n        v[1]=C(p)*d\n        return v\n      })\n      ret = [...ret, b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          if(q[2]<mind)mind=q[2]\n        })\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]+=ang=1.538840639715\n        })\n      })\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI,0,Math.PI)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      b=JSON.parse(JSON.stringify(e)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI/2,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        //x.globalAlpha=.2\n        x.lineWidth=Math.min(1e3,1600/Z)\n        x.strokeStyle=scol\n        //x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=8\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    //shp = Sphere(20,20,10)\n    //shp = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/house2.obj\', 2,0,24,0,0,0,0)\n    //shp = Dodecahedron(20)\n    //shp = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/axe.obj\', 300,0,40,0,0,0,Math.PI/2)\n    //shp = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/skull3.obj\', 2,0,24,0,0,0,Math.PI/2)\n    tree    = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/tree3.obj\', 6,0,24,0,0,0,0)\n    axe     = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/axe.obj\', 120,0,24,0,0,0,0)\n    pickaxe = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/pickaxe.obj\', 120,0,24,0,0,0,0)\n    hand    = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/hand.obj\', 2,0,24,0,0,0,0)\n    chair   = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/chair.obj\', 50,0,24,0,0,0,0)\n    rock    = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/rock.obj\', 20,0,24,0,0,0,0)\n\n    iShapesc = 6, G=150\n    shapes = Array(iShapesc).fill().map(v=>{\n      tx = (Rn()-.5)*G\n      ty = (Rn()-.5)*G\n      tz = (Rn()-.5)*G\n      let shp\n      switch(Rn()*13|0){\n        case 0:\n          shp = Tetrahedron(20)\n        break\n        case 1:\n          shp = Cube(20)\n        break\n        case 2:\n          shp = Octahedron(20)\n        break\n        case 3:\n          shp = Icosahedron(20)\n        break\n        case 4:\n          shp = Dodecahedron(20)\n        break\n        case 5:\n          shp = Sphere(20, 10,6)\n        break\n        case 6:\n          shp = Dodecahedron(20)\n        break\n        case 7:\n          shp = JSON.parse(JSON.stringify(tree))\n        break\n        case 8:\n          shp = JSON.parse(JSON.stringify(axe))\n        break\n        case 9:\n          shp = JSON.parse(JSON.stringify(pickaxe))\n        break\n        case 10:\n          shp = JSON.parse(JSON.stringify(hand))\n        break\n        case 11:\n          shp = JSON.parse(JSON.stringify(chair))\n        break\n        case 12:\n          shp = JSON.parse(JSON.stringify(rock))\n        break\n      }\n      rl=pt=yw=0\n      shp.map(v=>{\n        v.map(q=>{\n          q[0]+=tx\n          q[1]+=ty\n          q[2]+=tz\n        })\n      })\n      return [X, Y, Z, rl, pt, yw, shp]\n    })\n\n    rw=cl=br=12, sp = 10\n    P = Array(rw*cl*br).fill().map((v,i)=>{\n      let shp = shapes[shp_idx=shapes.length*Rn()|0][6]\n      X  = ((i%cl)-cl/2+.5)*sp\n      Y  = (((i/cl|0)%rw)-rw/2+.5)*sp\n      Z  = ((i/cl/rw|0)-br/2+.5)*sp\n      vx = 0\n      vy = 0\n      vz = 0\n      let face = shp.length*Rn()|0\n      let v1 = Rn()*shp[face].length|0\n      let v2 = (v1+1)%shp[face].length\n      let ip = Rn()\n      return [X,Y,Z,vx,vy,vz,face,v1,v2,ip,shp_idx]\n    })\n\n    go = false\n    bg = new Image()\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/Y0zH8.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.1\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0004\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=0, oY=0, oZ=200\n    Rl=0,Pt=-S(t/2)/4,Yw=S(t/2)*2\n    //Rl=0,Pt=0,Yw=0\n    x.lineJoin=x.lineCap=\'butt\'\n    \n    iPv=15\n    if(t&&!((t*60|0)%(60*10))){\n      P.map(v=>{\n        v[3]+=(Rn()-.5)*iPv\n        v[4]+=(Rn()-.5)*iPv\n        v[5]+=(Rn()-.5)*iPv\n      })\n    }\n\n    shapes.map((shp,shp_idx)=>{\n      mx=my=mz=ax=ay=az=ct=trl=tpt=tyw=0\n      mx  = C(t*2+shp_idx)/2\n      my  = 0\n      mz  = S(t*2+shp_idx)\n      trl = shp[3] + C(t*2+shp_idx)/30\n      tpt = shp[4] + C(t*1+shp_idx)/25\n      tyw = shp[5] + C(t*.5+shp_idx)/20\n      shp[6].map(v=>{\n        v.map(q=>{\n          ct++\n          ax += q[0]+=mx\n          ay += q[1]+=my\n          az += q[2]+=mz\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct  \n\n      shp[6].map(v=>{\n        v.map(q=>{\n          X=q[0]-ax\n          Y=q[1]-ay\n          Z=q[2]-az\n          R(trl,tpt,tyw)\n          q[0]=X+ax\n          q[1]=Y+ay\n          q[2]=Z+az\n        })\n        if(1){\n          x.beginPath()\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0)x.lineTo(...Q())\n          })\n          //stroke(\'#8ff2\',\'#44ff8808\')\n          stroke(\'#8ff4\',\'\')\n        }\n      })\n    })\n    homing = 1\n\n    P.map(v=>{\n      let shp = shapes[v[10]][6]\n      face = shp[v[6]]\n      v1 = face[v[7]]\n      v2 = face[v[8]]\n      tx = v1[0] + (v2[0] - v1[0])*v[9]\n      ty = v1[1] + (v2[1] - v1[1])*v[9]\n      tz = v1[2] + (v2[2] - v1[2])*v[9]\n\n      d1 = (5+Math.hypot(tx-v[0],ty-v[1],tz-v[2]))**1/10\n      d2 = (5+Math.hypot(ax-v[0],ay-v[1],az-v[2]))**2/30\n\n      vx = (tx-v[0])/(d1+d2)\n      vy = (ty-v[1])/(d1+d2)\n      vz = (tz-v[2])/(d1+d2)\n\n      v[3]/=1.05\n      v[4]/=1.05\n      v[5]/=1.05\n\n      X = v[0]+=v[3]+=vx/homing\n      Y = v[1]+=v[4]+=vy/homing\n      Z = v[2]+=v[5]+=vz/homing\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s = Math.min(1e3,8000/Z)\n        x.fillStyle=\'#4400ff03\'\n        l=Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=14\n        x.fillStyle=\'#fffa\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n    })\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'latent shapes', 145, 'whitehot robot', '2023-01-29 21:10:46', '[600684,600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 113, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600686, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nasync function Draw(){\n  if(!t){\n    oX=oY=oZ=0\n    Rl=Pt=Yw=0\n\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    R2=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n\n    async function loadOBJ(url, scale, tx, ty, tz, rl, pt, yw) {\n      let res\n      await fetch(url, res => res).then(data=>data.text()).then(data=>{\n        a=[]\n        data.split(\"\\nv \").map(v=>{\n          a=[...a, v.split(\"\\n\")[0]]\n        })\n        a=a.filter((v,i)=>i).map(v=>[...v.split(\' \').map(n=>(+n.replace(\"\\n\", \'\')))])\n        ax=ay=az=0\n        a.map(v=>{\n          v[1]*=-1\n          ax+=v[0]\n          ay+=v[1]\n          az+=v[2]\n        })\n        ax/=a.length\n        ay/=a.length\n        az/=a.length\n        a.map(v=>{\n          X=(v[0]-ax)*scale\n          Y=(v[1]-ay)*scale\n          Z=(v[2]-az)*scale\n          R2(rl,pt,yw,0)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n        })\n        maxY=-6e6\n        a.map(v=>{\n          if(v[1]>maxY)maxY=v[1]\n        })\n        a.map(v=>{\n          v[1]-=maxY-oY\n          v[0]+=tx\n          v[1]+=ty\n          v[2]+=tz\n        })\n\n        b=[]\n        data.split(\"\\nf \").map(v=>{\n          b=[...b, v.split(\"\\n\")[0]]\n        })\n        b.shift()\n        b=b.map(v=>v.split(\' \'))\n        b=b.map(v=>{\n          v=v.map(q=>{\n            return +q.split(\'/\')[0]\n          })\n          v=v.filter(q=>q)\n          return v\n        })\n        \n        res=[]\n        b.map(v=>{\n          e=[]\n          v.map(q=>{\n            e=[...e, JSON.parse(JSON.stringify(a[q-1]))]\n          })\n          e = e.filter(q=>q)\n          res=[...res, e]\n        })\n      })\n      return res\n    }\n\n    Sphere=(ls,cl,rw)=>{\n      let X,Y,Z\n      let ret=[]\n      for(i=cl*rw;i--;){\n        a=[]\n        j=i%cl\n        k=(i/cl|0)\n        l=(j+1)%cl\n\n        X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*k)*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*k)*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*(k+1))*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*(k+1))*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n\n        ret = [...ret, a]\n      }\n      return ret\n    }\n\n    Tetrahedron=ls=>{\n      let ret=[]\n      let a = []\n      let theta=1.2217304763960306\n      for(let i=3;i--;){\n        X=S(p=Math.PI*2/3*i)\n        Y=C(p)+.5\n        Z=0\n        R2(0,-theta/2,0)\n        a=[...a, [X,Y,Z]]\n      }\n      ret=[...ret, a]\n      b=JSON.parse(JSON.stringify(a))\n      ax=ay=az=0\n      b.map(v=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R2(0,theta,0)\n        v[0]=X\n        v[1]=Y\n        v[2]=Z\n      })\n      ret=[...ret, b]\n      ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax*1.5\n          q[1]-=ay*1.5\n          q[2]-=az*1.5\n        })\n      })\n\n      b=JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n      })\n      ret=[...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,.96,0)\n          R2(0,0,t*5)\n          R2(0,Math.PI,0)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Octahedron=ls=>{\n      ret = []\n      a=[]\n      for(i=4;i--;){\n        X1=S(p=Math.PI*2/4*i+Math.PI/4)\n        Y1=C(p)\n        Z1=0\n        X2=S(p=Math.PI*2/4*(i+1)+Math.PI/4)\n        Y2=C(p)\n        Z2=0\n        X3=0\n        Y3=0\n        Z3=1\n        a=[\n          [X1,Y1,Z1],\n          [X2,Y2,Z2],\n          [X3,Y3,Z3]\n        ]\n        ret=[...ret, a]\n        a=[\n          [X1,Y1,-Z1],\n          [X2,Y2,-Z2],\n          [X3,Y3,-Z3]\n        ]\n        ret=[...ret, a]\n      }\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Cube=ls=>{\n      let ret=[]\n      for(j=6;j--;ret=[...ret,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2                                                                                                            ])[j%3]*(l=j<3?-ls:ls),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Icosahedron=ls=>{\n      let a=[1,1],ret=[]\n      let b\n      for(i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]];\n      let phi=a[l]/a[l-1]\n      a=[[[-phi,-1,0],[phi,-1,0],[phi,1,0],[-phi,1,0]],[[0,-phi,-1],[0,phi,-1],[0,phi,1],[0,-phi,1]],[[                                                                                                            -1,0,-phi],[-1,0,phi],[1,0,phi],[1,0,-phi]]]\n      let ico=[[[0,1],[1,0],[1,3]],[[0,1],[2,3],[1,0]],[[2,0],[2,3],[1,0]],[[0,1],[2,3],[0,2]],[[1,1],[                                                                                                            2,3],[0,2]],[[1,1],[2,3],[2,0]],[[1,1],[1,2],[0,2]],[[0,1],[2,2],[0,2]],[[0,0],[1,0],[2,0]],[[2,0],[0,3                                                                                                            ],[0,0]],[[1,1],[1,2],[0,3]],[[1,1],[2,0],[0,3]],[[0,1],[1,3],[2,2]],[[1,3],[2,1],[2,2]],[[2,1],[0,3],[                                                                                                            1,2]],[[2,1],[0,0],[1,3]],[[1,2],[2,2],[2,1]],[[2,2],[1,2],[0,2]],[[0,3],[2,1],[0,0]],[[1,3],[1,0],[0,0                                                                                                            ]]]\n      ico.map((v,i)=>{\n        b=[]\n        v.map(q=>{\n          t1=q[0],t2=q[1]\n          X=a[t1][t2][0],Y=a[t1][t2][1],Z=a[t1][t2][2]\n          b=[...b, [X,Y,Z]]\n        })\n        ret=[...ret, b]\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Dodecahedron=ls=>{\n      let ret=[]\n      let sd=5\n      let a=[], b=[]\n      mind=6e6\n      for(let i=sd;i--;){\n        X=S(p=Math.PI*2/sd*i)\n        Y=C(p)\n        Z=0\n        if(Y<mind)mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a=a.map(v=>{\n        X=v[0]\n        Y=v[1]-=mind\n        Z=v[2]\n        R2(0,.5535735,0)\n        return [X,Y,Z]\n      })\n\n      ret = [...ret, a]\n      b=JSON.parse(JSON.stringify(a)).map(v=>{\n        d=Math.hypot(v[0],v[1])\n        v[0]=S(p=Math.atan2(v[0],v[1])+Math.PI)*d\n        v[1]=C(p)*d\n        return v\n      })\n      ret = [...ret, b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          if(q[2]<mind)mind=q[2]\n        })\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]+=ang=1.538840639715\n        })\n      })\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI,0,Math.PI)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      b=JSON.parse(JSON.stringify(e)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI/2,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.1\n        x.lineWidth=Math.min(1e3,4000/Z)\n        x.strokeStyle=scol\n        x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=8\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    //shp = Sphere(20,20,10)\n    //shp = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/house2.obj\', 2,0,24,0,0,0,0)\n    //shp = Dodecahedron(20)\n    //shp = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/axe.obj\', 300,0,40,0,0,0,Math.PI/2)\n    //shp = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/skull3.obj\', 2,0,24,0,0,0,Math.PI/2)\n    tree    = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/tree3.obj\', 6,0,24,0,0,0,0)\n    axe     = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/axe.obj\', 120,0,24,0,0,0,0)\n    pickaxe = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/pickaxe.obj\', 120,0,24,0,0,0,0)\n    hand    = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/hand.obj\', 2,0,24,0,0,0,0)\n    chair   = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/chair.obj\', 50,0,24,0,0,0,0)\n    rock    = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/rock.obj\', 20,0,24,0,0,0,0)\n\n    iShapesc = 1, G=0\n    shapes = Array(iShapesc).fill().map(v=>{\n      tx = (Rn()-.5)*G\n      ty = (Rn()-.5)*G\n      tz = (Rn()-.5)*G\n      let shp\n      switch(4){\n        case 0:\n          shp = Tetrahedron(20)\n        break\n        case 1:\n          shp = Cube(60)\n        break\n        case 2:\n          shp = Octahedron(20)\n        break\n        case 3:\n          shp = Icosahedron(20)\n        break\n        case 4:\n          shp = Dodecahedron(60)\n        break\n        case 5:\n          shp = Sphere(20, 10,6)\n        break\n        case 6:\n          shp = Dodecahedron(20)\n        break\n        case 7:\n          shp = JSON.parse(JSON.stringify(tree))\n        break\n        case 8:\n          shp = JSON.parse(JSON.stringify(axe))\n        break\n        case 9:\n          shp = JSON.parse(JSON.stringify(pickaxe))\n        break\n        case 10:\n          shp = JSON.parse(JSON.stringify(hand))\n        break\n        case 11:\n          shp = JSON.parse(JSON.stringify(chair))\n        break\n        case 12:\n          shp = JSON.parse(JSON.stringify(rock))\n        break\n      }\n      rl=pt=yw=0\n      shp.map(v=>{\n        v.map(q=>{\n          q[0]+=tx\n          q[1]+=ty\n          q[2]+=tz\n        })\n      })\n      return [X, Y, Z, rl, pt, yw, shp]\n    })\n\n    rw=cl=br=14, sp = 10\n    P = Array(rw*cl*br).fill().map((v,i)=>{\n      let shp = shapes[shp_idx=shapes.length*Rn()|0][6]\n      X  = ((i%cl)-cl/2+.5)*sp\n      Y  = (((i/cl|0)%rw)-rw/2+.5)*sp\n      Z  = ((i/cl/rw|0)-br/2+.5)*sp\n      vx = 0\n      vy = 0\n      vz = 0\n      let face = shp.length*Rn()|0\n      let v1 = Rn()*shp[face].length|0\n      let v2 = (v1+1)%shp[face].length\n      let ip = Rn()\n      return [X,Y,Z,vx,vy,vz,face,v1,v2,ip,shp_idx]\n    })\n\n    go = false\n    bg = new Image()\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/21rYJy.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.2\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0003\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=0, oY=0, oZ=200\n    Rl=0,Pt=-S(t/2)/4,Yw=S(t/2)*2\n    //Rl=0,Pt=0,Yw=0\n    x.lineJoin=x.lineCap=\'round\'\n    \n    iPv=15\n    if(t&&!((t*60|0)%(60*10))){\n      P.map(v=>{\n        v[3]+=(Rn()-.5)*iPv\n        v[4]+=(Rn()-.5)*iPv\n        v[5]+=(Rn()-.5)*iPv\n      })\n    }\n\n    shapes.map((shp,shp_idx)=>{\n      mx=my=mz=ax=ay=az=ct=trl=tpt=tyw=0\n      mx  = C(t*2+shp_idx)/2\n      my  = 0\n      mz  = S(t*2+shp_idx)\n      trl = shp[3] + C(t*2+shp_idx)/30\n      tpt = shp[4] + C(t*1+shp_idx)/25\n      tyw = shp[5] + C(t*.5+shp_idx)/20\n      shp[6].map(v=>{\n        v.map(q=>{\n          ct++\n          ax += q[0]+=mx\n          ay += q[1]+=my\n          az += q[2]+=mz\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct  \n\n      shp[6].map(v=>{\n        v.map(q=>{\n          X=q[0]-ax\n          Y=q[1]-ay\n          Z=q[2]-az\n          R(trl,tpt,tyw)\n          q[0]=X+ax\n          q[1]=Y+ay\n          q[2]=Z+az\n        })\n        if(1){\n          x.beginPath()\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0)x.lineTo(...Q())\n          })\n          stroke(\'#8ff4\',\'#4400ff08\')\n          //stroke(\'#8ff4\',\'\')\n        }\n      })\n    })\n    homing = .8\n\n    P.map(v=>{\n      let shp = shapes[v[10]][6]\n      face = shp[v[6]]\n      v1 = face[v[7]]\n      v2 = face[v[8]]\n      tx = v1[0] + (v2[0] - v1[0])*v[9]\n      ty = v1[1] + (v2[1] - v1[1])*v[9]\n      tz = v1[2] + (v2[2] - v1[2])*v[9]\n\n      d1 = (5+Math.hypot(tx-v[0],ty-v[1],tz-v[2]))**1/10\n      d2 = (5+Math.hypot(ax-v[0],ay-v[1],az-v[2]))**2/30\n\n      vx = (tx-v[0])/(d1+d2)\n      vy = (ty-v[1])/(d1+d2)\n      vz = (tz-v[2])/(d1+d2)\n\n      v[3]/=1.05\n      v[4]/=1.05\n      v[5]/=1.05\n\n      X = v[0]+=v[3]+=vx/homing\n      Y = v[1]+=v[4]+=vy/homing\n      Z = v[2]+=v[5]+=vz/homing\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s = Math.min(1e3,8000/Z)\n        x.fillStyle=\'#4400ff04\'\n        l=Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=12\n        x.fillStyle=\'#fffa\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n    })\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'latent shapes 2', 145, 'whitehot robot', '2023-01-30 13:59:50', '[600685,600684,600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 109, '', 0, 0),
