})\n      ret = [...ret, ...b]\n\n      b=JSON.parse(JSON.stringify(e)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI/2,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        //x.globalAlpha=.1\n        x.lineWidth=Math.min(1e3,32000/Z)\n        x.strokeStyle=scol\n        //x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=20\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    //shp = Sphere(20,20,10)\n    //shp = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/house2.obj\', 2,0,24,0,0,0,0)\n    //shp = Dodecahedron(20)\n    //shp = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/axe.obj\', 300,0,40,0,0,0,Math.PI/2)\n    //shp = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/skull3.obj\', 2,0,24,0,0,0,Math.PI/2)\n    tree    = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/tree3.obj\', 6,0,24,0,0,0,0)\n    axe     = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/axe.obj\', 120,0,24,0,0,0,0)\n    pickaxe = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/pickaxe.obj\', 120,0,24,0,0,0,0)\n    hand    = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/hand.obj\', 6,0,150,0,0,0,0)\n    chair   = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/chair.obj\', 200,0,60,0,0,0,0)\n    rock    = await loadOBJ(\'proxy.php?url=https://twilightparadox.com/rock.obj\', 20,0,24,0,0,0,0)\n\n    iShapesc = 4, G=0\n    shapes = Array(iShapesc).fill().map((v,i)=>{\n      tx = (Rn()-.5)*G\n      ty = (Rn()-.5)*G\n      tz = (Rn()-.5)*G\n      let shp\n      switch(i){\n        case 0:\n          size = 100\n          shp = JSON.parse(JSON.stringify(hand))\n          //shp = Dodecahedron(size)\n          //shp = Tetrahedron(size)\n        break\n        case 1:\n          size = 200\n          shp = Dodecahedron(size)\n        break\n        case 2:\n          size = 350\n          shp = Cube(size)\n          //shp = Octahedron(size)\n        break\n        case 3:\n          size = 450\n          shp = Dodecahedron(size)\n          shp = Icosahedron(size)\n          //shp = Icosahedron(size)\n        break\n        case 4:\n           size = 60\n          shp = Dodecahedron(size)\n        break\n        case 5:\n          size = 60\n          shp = Sphere(size, 10,6)\n        break\n        case 6:\n          size=60\n          shp = JSON.parse(JSON.stringify(tree))\n        break\n        case 7:\n          size=60\n          shp = JSON.parse(JSON.stringify(axe))\n        break\n        case 8:\n          size=60\n          shp = JSON.parse(JSON.stringify(pickaxe))\n        break\n        case 9:\n          size=60\n          shp = JSON.parse(JSON.stringify(hand))\n        break\n        case 10:\n          size=60\n          shp = JSON.parse(JSON.stringify(chair))\n        break\n        case 11:\n          size=60\n          shp = JSON.parse(JSON.stringify(rock))\n        break\n      }\n      rl=pt=yw=0\n      shp.map(v=>{\n        v.map(q=>{\n          q[0]+=tx\n          q[1]+=ty\n          q[2]+=tz\n        })\n      })\n      return [X, Y, Z, rl, pt, yw, shp, size]\n    })\n\n    rw=cl=br=17, sp = 40\n    P = Array(rw*cl*br).fill().map((v,i)=>{\n      let shp = shapes[shp_idx=shapes.length*Rn()|0][6]\n      X  = 0 //((i%cl)-cl/2+.5)*sp\n      Y  = 0 //(((i/cl|0)%rw)-rw/2+.5)*sp\n      Z  = 0 //((i/cl/rw|0)-br/2+.5)*sp\n      vx = 0\n      vy = 0\n      vz = 0\n      let face = shp.length*(Rn()**.4)|0\n      let v1 = Rn()*shp[face].length|0\n      let v2 = (v1+1)%shp[face].length\n      let ip = Rn()\n      return [X,Y,Z,vx,vy,vz,face,v1,v2,ip,shp_idx]\n    })\n\n    go = false\n    bg = new Image()\n    bg.onload=()=>{\n      go=true\n    }\n    bg.src=\'proxy.php?url=https://srmcgann.github.io/assets/ZHaiE.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.2\n    x.drawImage(bg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0003\'\n    x.fillRect(0,0,c.width,c.height)\n    oX=0, oY=0, oZ=600+S(t*1.5)*400\n    Rl=t/4,Pt=-S(t/2)/4,Yw=S(t/2)*2\n    //Rl=0,Pt=0,Yw=0\n    x.lineJoin=x.lineCap=\'butt\'\n\n    iPv=15\n    if(t&&!((t*60|0)%(60*20))){\n      P.map(v=>{\n        v[3]+=(Rn()-.5)*iPv\n        v[4]+=(Rn()-.5)*iPv\n        v[5]+=(Rn()-.5)*iPv\n      })\n    }\n\n    homing = .2\n\n    P.map(v=>{\n      let shp = shapes[v[10]][6]\n      face = shp[v[6]]\n      v1 = face[v[7]]\n      v2 = face[v[8]]\n      tx = v1[0] + (v2[0] - v1[0])*v[9]\n      ty = v1[1] + (v2[1] - v1[1])*v[9]\n      tz = v1[2] + (v2[2] - v1[2])*v[9]\n\n      d1 = (5+Math.hypot(tx-v[0],ty-v[1],tz-v[2]))**1/10\n      d2 = (5+Math.hypot(ax-v[0],ay-v[1],az-v[2]))**2/30\n\n      vx = (tx-v[0])/(d1+d2)\n      vy = (ty-v[1])/(d1+d2)\n      vz = (tz-v[2])/(d1+d2)\n\n      v[3]/=1.075\n      v[4]/=1.075\n      v[5]/=1.075\n\n      X = v[0]+=v[3]+=vx/homing\n      Y = v[1]+=v[4]+=vy/homing\n      Z = v[2]+=v[5]+=vz/homing\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s = Math.min(1e3,6e4/Z)\n        x.fillStyle=\'#4400ff03\'\n        l=Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=5\n        x.fillStyle=\'#00ff0003\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=3\n        x.fillStyle=\'#fff8\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n    })\n\n    shapes.map((shp,shp_idx)=>{\n      mx=my=mz=ax=ay=az=ct=trl=tpt=tyw=0\n      mx  = 0//C(t*2+shp_idx)/2\n      my  = 0\n      mz  = 0//S(t*2+shp_idx)\n      trl = shp[3] + C(t/2+shp_idx)*4/(1+shp[7]/2)\n      tpt = shp[4] + C(t/1.5+shp_idx)*4/(1+shp[7]/2)\n      tyw = shp[5] + C(t+shp_idx)*4/(1+shp[7]/2)\n      shp[6].map(v=>{\n        v.map(q=>{\n          ct++\n          ax += q[0]+=mx\n          ay += q[1]+=my\n          az += q[2]+=mz\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n\n      shp[6].map(v=>{\n        v.map(q=>{\n          X=q[0]-ax\n          Y=q[1]-ay\n          Z=q[2]-az\n          R(trl,tpt,tyw)\n          q[0]=X+ax\n          q[1]=Y+ay\n          q[2]=Z+az\n        })\n        if(1){\n          x.beginPath()\n          v.map(q=>{\n            X=q[0]\n            Y=q[1]\n            Z=q[2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0)x.lineTo(...Q())\n          })\n          stroke(\'#fff6\',\'#4400ff0c\')\n          //stroke(\'#fff6\',\'\')\n        }\n      })\n    })\n  }\n\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'the hand of god', 145, 'whitehot robot', '2023-01-31 18:14:00', '[600686,600685,600684,600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 105, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600691, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol,fcol)=>{\n      if(scol){\n        x.closePath()\n        x.globalAlpha=.2\n        x.strokeStyle = scol\n        x.lineWidth = Math.min(1e3, 200/Z)\n        x.lineWidth/=5\n        x.globalAlpha=1\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n\n    getIdx=()=>{\n      mind=6e6,idx=false\n      P.map((v,i)=>{\n        if(v[3]){\n          if((d=Math.hypot(pcx-v[0],pcy-v[1]))<mind)mind=d,idx=i\n        }\n      })\n      return [idx, mind]\n    }\n    tryLeft=()=>{\n      if(dir==2) return true\n      l = (l2=getIdx())[0]-1\n      if(((!pvx && !pvy) || dir==0 || l2[1]<.01) && l>=0 && l<=P.length-1){\n        d = Math.hypot(P[l][0]-pcx,P[l][1]-pcy)\n        return P[l][3] || (dir==0 && d>sp)\n      }\n     return false\n    }\n    tryRight=()=>{\n      if(dir==0) return true\n      l = (l2=getIdx())[0]+1\n      if(((!pvx && !pvy) || dir==2 || l2[1]<.01) && l>=0 && l<=P.length-1){\n        d = Math.hypot(P[l][0]-pcx,P[l][1]-pcy)\n        return P[l][3] || (dir == 2 && d>sp)\n      }\n      return false\n    }\n    tryUp=()=>{\n      if(dir==3) return true\n      l = (l2=getIdx())[0]-cl\n      if(((!pvx && !pvy) || dir == 1 || l2[1]<.01) && l>=0 && l<=P.length-1){\n        d = Math.hypot(P[l][0]-pcx,P[l][1]-pcy)\n        return P[l][3] || (dir == 1 && d>sp)\n      }\n      return false\n    }\n    tryDown=()=>{\n      if(dir==1) return true\n      l = (l2=getIdx())[0]+cl\n      if(((!pvx && !pvy) || dir == 3 || l2[1]<.01) && l>=0 && l<=P.length-1){\n        d = Math.hypot(P[l][0]-pcx,P[l][1]-pcy)\n        return P[l][3] || (dir == 3 && d>sp)\n      }\n      return false\n    }\n\n    newGhostDir = (gidx,cdir) => {\n      switch(Rn()*4|0){\n        case 0:\n          if(cdir!=0 && tryGhostLeft(gidx)) ghosts[gidx][2] = 0;\n        break\n        case 1:\n          if(cdir!=1 && tryGhostUp(gidx)) ghosts[gidx][2] = 1;\n        break\n        case 2:\n          if(cdir!=2 && tryGhostRight(gidx)) ghosts[gidx][2] = 2;\n        break\n        case 3:\n          if(cdir!=3 && tryGhostDown(gidx)) ghosts[gidx][2] = 3;\n        break\n      }\n    }\n\n    getGhostIdx=gidx=>{\n      gmind=6e6,idx=false\n      P.map((v,i)=>{\n        if(v[3]){\n          if((d=Math.hypot(ghosts[gidx][0]-v[0],ghosts[gidx][1]-v[1]))<gmind)gmind=d,idx=i\n        }\n      })\n      return [idx, gmind]\n    }\n    tryGhostLeft=gidx=>{\n      l = (l2=getGhostIdx(gidx))[0]-1\n      let dir = ghosts[gidx][2]\n      let pvx = ghosts[gidx][4]\n      let pvy = ghosts[gidx][5]\n      if(((!pvx && !pvy) || dir==0 || l2[1]<.01) && l>=0 && l<=P.length-1){\n        d = Math.hypot(P[l][0]-ghosts[gidx][0],P[l][1]-ghosts[gidx][1])\n        return P[l][3] || (dir == 0 && d>sp)\n      }else{\n        newGhostDir(gidx,0)\n      }\n     return false\n    }\n    tryGhostRight=gidx=>{\n      l = (l2=getGhostIdx(gidx))[0]+1\n      let dir = ghosts[gidx][2]\n      let pvx = ghosts[gidx][4]\n      let pvy = ghosts[gidx][5]\n      if(((!pvx && !pvy) || dir == 2 || l2[1]<.01) && l>=0 && l<=P.length-1){\n        d = Math.hypot(P[l][0]-ghosts[gidx][0],P[l][1]-ghosts[gidx][1])\n        return P[l][3] || (dir == 2 && d>sp)\n      }else{\n        newGhostDir(gidx,2)\n      }\n      return false\n    }\n    tryGhostUp=gidx=>{\n      l = (l2=getGhostIdx(gidx))[0]-cl\n      let dir = ghosts[gidx][2]\n      let pvx = ghosts[gidx][4]\n      let pvy = ghosts[gidx][5]\n      if(((!pvx && !pvy) || dir == 1 || l2[1]<.01) && l>=0 && l<=P.length-1){\n        d = Math.hypot(P[l][0]-ghosts[gidx][0],P[l][1]-ghosts[gidx][1])\n        return P[l][3] || (dir == 1 && d>sp)\n      }else{\n        newGhostDir(gidx,1)\n      }\n      return false\n    }\n    tryGhostDown=gidx=>{\n      l = (l2=getGhostIdx(gidx))[0]+cl\n      let dir = ghosts[gidx][2]\n      let pvx = ghosts[gidx][4]\n      let pvy = ghosts[gidx][5]\n      if(((!pvx && !pvy) || dir == 3 || l2[1]<.01) && l>=0 && l<=P.length-1){\n        d = Math.hypot(P[l][0]-ghosts[gidx][0],P[l][1]-ghosts[gidx][1])\n        return P[l][3] || (dir == 3 && d>sp)\n      }else{\n        newGhostDir(gidx,3)\n      }\n      return false\n    } \n\n    c.tabIndex = 0\n    c.focus()\n    keys=Array(256).fill(false)\n    c.onkeydown = e => {\n      e.stopPropagation()\n      e.preventDefault()\n      keys[e.keyCode]=true\n    }\n    c.onkeyup = e => {\n      e.stopPropagation()\n      e.preventDefault()\n      keys[e.keyCode]=false\n    }\n\n    doKeys=()=>{\n      keys.map((v,i)=>{\n        if(v){\n          switch(i){\n            case 37:\n              if(tryLeft()) dir=0\n            break\n            case 38:\n              if(tryUp()) dir=1\n            break\n            case 39:\n              if(tryRight()) dir=2\n            break\n            case 40:\n              if(tryDown()) dir=3\n            break\n          }\n        }\n      })\n    }\n\n    spawnGhosts = (n,speed) => {\n      a=Array(n).fill().map((v,i)=>{\n        let stp = cl*10-8\n        let pcx = P[stp][0]+i*2*sp\n        let pcy = P[stp][1]\n        let dir = 0\n        let pcr = Math.PI/2\n        let pvx = pvy = pvz = 0\n        let ipv = speed\n        let pv  = 0\n\n        return [pcx,pcy,dir,pcr,pvx,pvy,ipv,pv,true]\n      })\n      ghosts = typeof ghosts == \'undefined\' ? [] : ghosts\n      ghosts = [...ghosts, ...a]\n    }\n    \n    starsLoaded = false, stars = [{loaded: false}]\n    stars = Array(9).fill().map((v,i) => {\n      let a = {img: new Image(), loaded: false}\n      a.img.onload = () => {\n        a.loaded = true\n        setTimeout(()=>{\n          if(stars.filter(v=>v.loaded).length == 9) starsLoaded = true, init()\n        }, 0)\n      }\n      a.img.src = `https://srmcgann.github.io/temp/stars/star${i+1}.png`\n      return a\n    })\n\n    chuckie = new Image()\n    chuckie.src = \'http://srmcgann.github.io/temp5/vJJgD.png\'\n    \n    init = level => {\n      score = 0\n      switch(level){\n        case 1:\n          cl = 24\n          rw = cl/1.7777778|0\n          sp = 1\n          omit=[\n            49+cl*4,\n            50+cl*4,\n            51+cl*4,\n            49+cl*4+20,\n            50+cl*4+20,\n            51+cl*4+20,\n            49+cl*4+8,\n            50+cl*4+8,\n            51+cl*4+8,\n            49+cl*4+12,\n            50+cl*4+12,\n            51+cl*4+12,\n            28,\n            52,\n            28+8,\n            52+8,\n            28+16,\n            52+16,\n            28+cl*9,\n            52+cl*9,\n            28+8+cl*9,\n            52+8+cl*9,\n            28+16+cl*9,\n            52+16+cl*9,\n          ]\n          path = Array(iPc=rw*(cl)).fill().map((v,i)=>{\n            ret = 0\n            if(!((i/cl|0)%3) || !(i%4))ret=2\n           return omit.filter(v=>v==i).length? 0 : ret\n          })\n          P=Array(iPc).fill().map((v,i)=>{\n            X = ((i%cl)-cl/2)*sp\n            Y = (((i/cl|0))-rw/2+.5)*sp\n            Z = 0\n            return [X, Y, Z, path[i]]\n          })\n          ls = 2**.5/2\n          stp =  cl*1+6\n          ipcy = P[stp][1]\n          stp = cl*3+1\n          ipcx = pcx = X=P[stp][0]\n          pcy = Y=P[stp][1]\n          pcz = Z=P[stp][2]\n          pup_idxs=[\n            30+cl*5, 42+cl*5, 36+cl*5\n          ]\n          Powerups = Array(pup_idxs.length).fill().map((v,i)=>{\n            X = P[pup_idxs[i]][0]\n            Y = P[pup_idxs[i]][1]\n            return [X,Y,true]\n          })\n          dir=2\n          powerUpTimer = 0\n          powerUpTimerInterval = 6\n          pcr=-Math.PI/2\n          pvx=pvy=pvz=0\n          ipv = .05\n          pv = 0\n          alive = true\n          ghosts=[]\n          spawnGhosts(4,.075)\n        break\n        case 2:\n          cl = 24\n          rw = cl/1.7777778|0\n          sp = 1\n          omit=[\n            cl+1+cl*2,\n            cl+2+cl*2,\n            cl+3+cl*2,\n            cl+1+cl*8,\n            cl+2+cl*8,\n            cl+3+cl*8,\n            cl+1+cl*2+20,\n            cl+2+cl*2+20,\n            cl+3+cl*2+20,\n            cl+1+cl*8+20,\n            cl+2+cl*8+20,\n            cl+3+cl*8+20,\n            cl+4,\n            cl*2+4,\n            cl+8,\n            cl*2+8,\n            cl+16,\n            cl*2+16,\n            cl+20,\n            cl*2+20,\n            cl+4+cl*9,\n            cl*2+4+cl*9,\n            cl+8+cl*9,\n            cl*2+8+cl*9,\n            cl+16+cl*9,\n            cl*2+16+cl*9,\n            cl+20+cl*9,\n            cl*2+20+cl*9,\n          ]\n          path = Array(iPc=rw*(cl)).fill().map((v,i)=>{\n            ret = 0\n            if(!((i/cl|0)%3) || !(i%4))ret=2\n           return omit.filter(v=>v==i).length? 0 : ret\n          })\n          P=Array(iPc).fill().map((v,i)=>{\n            X = ((i%cl)-cl/2)*sp\n 