(600701, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    R2=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n\n    async function loadOBJ(url, scale, tx, ty, tz, rl, pt, yw) {\n      let res\n      await fetch(url, res => res).then(data=>data.text()).then(data=>{\n        a=[]\n        data.split(\"\\nv \").map(v=>{\n          a=[...a, v.split(\"\\n\")[0]]\n        })\n        a=a.filter((v,i)=>i).map(v=>[...v.split(\' \').map(n=>(+n.replace(\"\\n\", \'\')))])\n        ax=ay=az=0\n        a.map(v=>{\n          v[1]*=-1\n          ax+=v[0]\n          ay+=v[1]\n          az+=v[2]\n        })\n        ax/=a.length\n        ay/=a.length\n        az/=a.length\n        a.map(v=>{\n          X=(v[0]-ax)*scale\n          Y=(v[1]-ay)*scale\n          Z=(v[2]-az)*scale\n          R2(rl,pt,yw,0)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n        })\n        maxY=-6e6\n        a.map(v=>{\n          if(v[1]>maxY)maxY=v[1]\n        })\n        a.map(v=>{\n          v[1]-=maxY-oY\n          v[0]+=tx\n          v[1]+=ty\n          v[2]+=tz\n        })\n\n        b=[]\n        data.split(\"\\nf \").map(v=>{\n          b=[...b, v.split(\"\\n\")[0]]\n        })\n        b.shift()\n        b=b.map(v=>v.split(\' \'))\n        b=b.map(v=>{\n          v=v.map(q=>{\n            return +q.split(\'/\')[0]\n          })\n          v=v.filter(q=>q)\n          return v\n        })\n        \n        res=[]\n        b.map(v=>{\n          e=[]\n          v.map(q=>{\n            e=[...e, a[q-1]]\n          })\n          e = e.filter(q=>q)\n          res=[...res, e]\n        })\n      })\n      return res\n    }\n\n    Sphere=(ls,cl,rw)=>{\n      let X,Y,Z\n      let ret=[]\n      for(i=cl*rw;i--;){\n        a=[]\n        j=i%cl\n        k=(i/cl|0)\n        l=(j+1)%cl\n\n        X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*k)*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*k)*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*(k+1))*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*(k+1))*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n\n        ret = [...ret, a]\n      }\n      return ret\n    }\n\n    Tetrahedron=ls=>{\n      let ret=[]\n      let a = []\n      let theta=1.2217304763960306\n      for(let i=3;i--;){\n        X=S(p=Math.PI*2/3*i)\n        Y=C(p)+.5\n        Z=0\n        R2(0,-theta/2,0)\n        a=[...a, [X,Y,Z]]\n      }\n      ret=[...ret, a]\n      b=JSON.parse(JSON.stringify(a))\n      ax=ay=az=0\n      b.map(v=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R2(0,theta,0)\n        v[0]=X\n        v[1]=Y\n        v[2]=Z\n      })\n      ret=[...ret, b]\n      ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax*1.5\n          q[1]-=ay*1.5\n          q[2]-=az*1.5\n        })\n      })\n\n      b=JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n      })\n      ret=[...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,.96,0)\n          R2(0,0,t*5)\n          R2(0,Math.PI,0)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Octahedron=ls=>{\n      ret = []\n      a=[]\n      for(i=4;i--;){\n        X1=S(p=Math.PI*2/4*i+Math.PI/4)\n        Y1=C(p)\n        Z1=0\n        X2=S(p=Math.PI*2/4*(i+1)+Math.PI/4)\n        Y2=C(p)\n        Z2=0\n        X3=0\n        Y3=0\n        Z3=1\n        a=[\n          [X1,Y1,Z1],\n          [X2,Y2,Z2],\n          [X3,Y3,Z3]\n        ]\n        ret=[...ret, a]\n        a=[\n          [X1,Y1,-Z1],\n          [X2,Y2,-Z2],\n          [X3,Y3,-Z3]\n        ]\n        ret=[...ret, a]\n      }\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          