(600706, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    R2=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n\n    async function loadOBJ(url, scale, tx, ty, tz, rl, pt, yw) {\n      let res\n      await fetch(url, res => res).then(data=>data.text()).then(data=>{\n        a=[]\n        data.split(\"\\nv \").map(v=>{\n          a=[...a, v.split(\"\\n\")[0]]\n        })\n        a=a.filter((v,i)=>i).map(v=>[...v.split(\' \').map(n=>(+n.replace(\"\\n\", \'\')))])\n        ax=ay=az=0\n        a.map(v=>{\n          v[1]*=-1\n          ax+=v[0]\n          ay+=v[1]\n          az+=v[2]\n        })\n        ax/=a.length\n        ay/=a.length\n        az/=a.length\n        a.map(v=>{\n          X=(v[0]-ax)*scale\n          Y=(v[1]-ay)*scale\n          Z=(v[2]-az)*scale\n          R2(rl,pt,yw,0)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n        })\n        maxY=-6e6\n        a.map(v=>{\n          if(v[1]>maxY)maxY=v[1]\n        })\n        a.map(v=>{\n          v[1]-=maxY-oY\n          v[0]+=tx\n          v[1]+=ty\n          v[2]+=tz\n        })\n\n        b=[]\n        data.split(\"\\nf \").map(v=>{\n          b=[...b, v.split(\"\\n\")[0]]\n        })\n        b.shift()\n        b=b.map(v=>v.split(\' \'))\n        b=b.map(v=>{\n          v=v.map(q=>{\n            return +q.split(\'/\')[0]\n          })\n          v=v.filter(q=>q)\n          return v\n        })\n        \n        res=[]\n        b.map(v=>{\n          e=[]\n          v.map(q=>{\n            e=[...e, a[q-1]]\n          })\n          e = e.filter(q=>q)\n          res=[...res, e]\n        })\n      })\n      return res\n    }\n\n    Sphere=(ls,cl,rw)=>{\n      let X,Y,Z\n      let ret=[]\n      for(i=cl*rw;i--;){\n        a=[]\n        j=i%cl\n        k=(i/cl|0)\n        l=(j+1)%cl\n\n        X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*k)*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*k)*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*(k+1))*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*(k+1))*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n\n        ret = [...ret, a]\n      }\n      return ret\n    }\n\n    Tetrahedron=ls=>{\n      let ret=[]\n      let a = []\n      let theta=1.2217304763960306\n      for(let i=3;i--;){\n        X=S(p=Math.PI*2/3*i)\n        Y=C(p)+.5\n        Z=0\n        R2(0,-theta/2,0)\n        a=[...a, [X,Y,Z]]\n      }\n      ret=[...ret, a]\n      b=JSON.parse(JSON.stringify(a))\n      ax=ay=az=0\n      b.map(v=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R2(0,theta,0)\n        v[0]=X\n        v[1]=Y\n        v[2]=Z\n      })\n      ret=[...ret, b]\n      ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax*1.5\n          q[1]-=ay*1.5\n          q[2]-=az*1.5\n        })\n      })\n\n      b=JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n      })\n      ret=[...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,.96,0)\n          R2(0,0,t*5)\n          R2(0,Math.PI,0)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Octahedron=ls=>{\n      ret = []\n      a=[]\n      for(i=4;i--;){\n        X1=S(p=Math.PI*2/4*i+Math.PI/4)\n        Y1=C(p)\n        Z1=0\n        X2=S(p=Math.PI*2/4*(i+1)+Math.PI/4)\n        Y2=C(p)\n        Z2=0\n        X3=0\n        Y3=0\n        Z3=1\n        a=[\n          [X1,Y1,Z1],\n          [X2,Y2,Z2],\n          [X3,Y3,Z3]\n        ]\n        ret=[...ret, a]\n        a=[\n          [X1,Y1,-Z1],\n          [X2,Y2,-Z2],\n          [X3,Y3,-Z3]\n        ]\n        ret=[...ret, a]\n      }\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Cube=ls=>{\n      let ret=[]\n      for(j=6;j--;ret=[...ret,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2                                                                                                            ])[j%3]*(l=j<3?-ls:ls),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Icosahedron=ls=>{\n      let a=[1,1],ret=[]\n      let b\n      for(i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]];\n      let phi=a[l]/a[l-1]\n      a=[[[-phi,-1,0],[phi,-1,0],[phi,1,0],[-phi,1,0]],[[0,-phi,-1],[0,phi,-1],[0,phi,1],[0,-phi,1]],[[                                                                                                            -1,0,-phi],[-1,0,phi],[1,0,phi],[1,0,-phi]]]\n      let ico=[[[0,1],[1,0],[1,3]],[[0,1],[2,3],[1,0]],[[2,0],[2,3],[1,0]],[[0,1],[2,3],[0,2]],[[1,1],[                                                                                                            2,3],[0,2]],[[1,1],[2,3],[2,0]],[[1,1],[1,2],[0,2]],[[0,1],[2,2],[0,2]],[[0,0],[1,0],[2,0]],[[2,0],[0,3                                                                                                            ],[0,0]],[[1,1],[1,2],[0,3]],[[1,1],[2,0],[0,3]],[[0,1],[1,3],[2,2]],[[1,3],[2,1],[2,2]],[[2,1],[0,3],[                                                                                                            1,2]],[[2,1],[0,0],[1,3]],[[1,2],[2,2],[2,1]],[[2,2],[1,2],[0,2]],[[0,3],[2,1],[0,0]],[[1,3],[1,0],[0,0                                                                                                            ]]]\n      ico.map((v,i)=>{\n        b=[]\n        v.map(q=>{\n          t1=q[0],t2=q[1]\n          X=a[t1][t2][0],Y=a[t1][t2][1],Z=a[t1][t2][2]\n          b=[...b, [X,Y,Z]]\n        })\n        ret=[...ret, b]\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Dodecahedron=ls=>{\n      let ret=[]\n      let sd=5\n      let a=[], b=[]\n      mind=6e6\n      for(let i=sd;i--;){\n        X=S(p=Math.PI*2/sd*i)\n        Y=C(p)\n        Z=0\n        if(Y<mind)mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a=a.map(v=>{\n        X=v[0]\n        Y=v[1]-=mind\n        Z=v[2]\n        R2(0,.5535735,0)\n        return [X,Y,Z]\n      })\n\n      ret = [...ret, a]\n      b=JSON.parse(JSON.stringify(a)).map(v=>{\n        d=Math.hypot(v[0],v[1])\n        v[0]=S(p=Math.atan2(v[0],v[1])+Math.PI)*d\n        v[1]=C(p)*d\n        return v\n      })\n      ret = [...ret, b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          if(q[2]<mind)mind=q[2]\n        })\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]+=ang=1.538840639715\n        })\n      })\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI,0,Math.PI)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      b=JSON.parse(JSON.stringify(e)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI/2,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    stroke = (scol, fcol) =>{\n      if(scol){\n        x.closePath()\n        x.strokeStyle=scol\n        //x.globalAlpha = .2\n        x.lineWidth = Math.min(1e3, 300/Z)\n        //x.stroke()\n        x.globalAlpha = 1\n        x.lineWidth/=5\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n\n    body1 = Icosahedron(1)\n    body2 = Tetrahedron(1)\n    body3 = Dodecahedron(1)\n\n    init=()=>{\n      iBc=300, iBmass = 2, iBv = .25, iBr=.2\n      sp = 1\n      B = Array(iBc).fill().map((v, i)=>{\n        mass = i?5+Rn()*iBmass:40\n        ls = i ? (i/200+2)*sp : 0\n        if(i){\n          X  = S(p=Math.PI*2*Rn())*ls\n          Y  = C(p)*ls\n          Z  = 0//(Rn()-.5)*2\n        } else {\n          X=Y=Z=0\n        }\n        vx = S(p+=Math.PI/2)*iBv*(1+i/1000)\n        vy = C(p)*iBv*(1+i/1000) \n        vz = 0\n        id=Rn()<.05?Rn()*9|0:0\n        return [X,Y,Z,vx,vy,vz,mass,id]\n      })\n    }\n\n    iPc = 1\n    P = Array(iPc).fill().map((v, i)=>{\n      mass = i?.2+Rn()*iBmass:20\n      ls = i ? (i/80+5)*sp : 0\n      X = 10\n      Y = 0\n      Z = 25\n      vx = vy = vz = 0\n      return [X, Y, Z, vx, vy, vz, mass]\n    })\n\n    bg = new Image()\n    bg.src = \'proxy.php?url=https://srmcgann.github.io/assets/GAVb5.jpg\'\n\n    star=Array(9).fill().map((v,i)=>{\n      let a = new Image\n      a.src = `proxy.php?url=https://srmcgann.github.io/temp/stars/star${i+1}.png`\n      return a\n    })\n  }\n\n  x.globalAlpha = .2\n  x.drawImage(bg,0,0,c.width,c.height)\n  x.globalAlpha = 1\n  x.fillStyle=\'#0003\'\n  x.fillRect(0,0,c.width,c.height)\n  oX=0, oY=-3, oZ=15\n  Yw=0//t/8\n  Pt=Math.PI/2-.7\n  Rl=-t\n  x.lineJoin=x.lineCap=\'round\'\n  if(!((t*60|0)%(60*4)))init()\n\n  B.map((v,i)=>{\n    tx = v[0]\n    ty = v[1]\n    tz = v[2]\n    v[5]/=1.1\n    if(i){\n      tx_ = v[0]\n      ty_ = v[1]\n      tz_ = v[2]\n      d_ = (100+Math.hypot(tx_,ty_,tz_))**2\n      tx_/=d_\n      ty_/=d_\n      tz_/=d_\n      tx_*=.5\n      ty_*=.5\n      tz_*=.5\n      tx = v[0] += v[3] -= tx_\n      ty = v[1] += v[4] -= ty_\n      tz = v[2] += v[5] -= tz_\n      B.map((q,j)=>{\n        if(j && j!=i){\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          d = (31+Math.hypot(q[0]-tx,q[1]-ty,q[2]-tz))**20*(1+v[6])/(1+q[6])\n          v[3] += (X-tx) * 2e26 / d\n          v[4] += (Y-ty) * 2e26 / d\n          v[5] += (Z-tz) * 2e26 / d\n        }\n      })\n      X = tx, Y = ty, Z = tz\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s = Math.min(1e3,(v[7]?4000:1000)/Z)\n        //x.fillStyle=\'#0fc1\'\n        l=Q()\n        //x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        x.drawImage(star[v[7]],l[0]-s/2,l[1]-s/2,s,s)\n      }\n    }\n  })\n\n\n  if(0)P.map((v,i)=>{\n    tx = v[0]\n    ty = v[1]\n    tz = v[2] = Math.max(-10, Math.min(10, C(t)*40))\n    body3.map(q=>{\n      x.beginPath()\n      q.map(n=>{\n        X = n[0] * iBr * v[6] + tx\n        Y = n[1] * iBr * v[6] + ty\n        Z = n[2] * iBr * v[6] + tz\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n      })\n      stroke(i?\'\':\'#fff1\', i?\'#0ff2\':\'#f001\')\n    })\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background