(600707, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\n\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    stroke=(scol, fcol)=>{\n      if(scol){\n        x.closePath()\n        //x.globalAlpha=.2\n        x.lineWidth = Math.min(1e3, 5000/Z)\n        x.strokeStyle = scol\n        //x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=5\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n\n    }\n      prng = seed =>{\n        return (Math.abs(100+seed+S(t/20)*1000000)**3.1/6000000000000000)*10**3&Math.PI*2\n      }\n\n    floor = (X,Z)=>{\n      return S(prng(X))*S(prng(Z))*50\n    }\n\n    bg = new Image()\n    bg.src = \'proxy.php?url=https://assets.dweet.net/misc/fe4e68acd5d6c161e0cb311b45269a73\'\n\n    rw = 1\n    cl = 50\n    br = 50\n    sp = 8\n    B = Array(rw*cl*br).fill().map((v,i)=>{\n      X = ((i%cl)-cl/2+.5)*sp\n      Y = (((i/cl|0)%rw)-rw/2+.5)*sp\n      Z = ((i/cl/rw|0)-br/2+.5)*sp\n      return [X,Y,Z]\n    })\n    mox=moy=moz=ox=oy=oz=10\n  }\n\n  x.globalAlpha = .3\n  x.drawImage(bg,0,0,c.width,c.height)\n  x.globalAlpha = 1\n  x.fillStyle=\'#0005\'\n  x.fillRect(0,0,c.width,c.height)\n  oX = 0\n  oY = -20\n  oZ = 150+Math.min(300,Math.max(-10,S(t)*1000))\n  Rl = 0\n  Pt = -.5+S(t*2)/4\n  Yw = S(t)+Math.PI\n\n  ox+=C(t/4)*22\n  oz+=S(t/4)*22\n\n  B.map((v,i)=>{\n    if(i%cl && i>cl){\n      x.beginPath()\n      l = i\n      X = B[l][0]\n      Z = B[l][2]\n      y1 = Y = B[l][1]+floor(B[l][0]-ox,B[l][2]-oz)\n      R(Rl,Pt,Yw,1)\n      if(Z>0)x.lineTo(...Q())\n      l = i-1\n      X = B[l][0]\n      Z = B[l][2]\n      y2 = Y = B[l][1]+floor(B[l][0]-ox,B[l][2]-oz)\n      R(Rl,Pt,Yw,1)\n      if(Z>0)x.lineTo(...Q())\n      l = i-1-cl\n      X = B[l][0]\n      Z = B[l][2]\n      y3 = Y = B[l][1]+floor(B[l][0]-ox,B[l][2]-oz)\n      R(Rl,Pt,Yw,1)\n      if(Z>0)x.lineTo(...Q())\n      l = i-cl\n      X = B[l][0]\n      Z = B[l][2]\n      y4 = Y = B[l][1]+floor(B[l][0]-ox,B[l][2]-oz)\n      R(Rl,Pt,Yw,1)\n      if(Z>0)x.lineTo(...Q())\n      stroke(\'#0008\',`hsla(${(y1+y2+y3+y4)/100*360+110+t*100}, 99%, 50%, .2)`)\n    }\n  })  \n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'perlin like noise function', 145, 'whitehot robot', '2023-03-19 20:13:42', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 86, '', 0, 0),
