v=>{\n          X=(v[0]-ax)*scale\n          Y=(v[1]-ay)*scale\n          Z=(v[2]-az)*scale\n          R2(rl,pt,yw,0)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n        })\n        maxY=-6e6\n        a.map(v=>{\n          if(v[1]>maxY)maxY=v[1]\n        })\n        a.map(v=>{\n          v[1]-=maxY-oY\n          v[0]+=tx\n          v[1]+=ty\n          v[2]+=tz\n        })\n\n        b=[]\n        data.split(\"\\nf \").map(v=>{\n          b=[...b, v.split(\"\\n\")[0]]\n        })\n        b.shift()\n        b=b.map(v=>v.split(\' \'))\n        b=b.map(v=>{\n          v=v.map(q=>{\n            return +q.split(\'/\')[0]\n          })\n          v=v.filter(q=>q)\n          return v\n        })\n        \n        res=[]\n        b.map(v=>{\n          e=[]\n          v.map(q=>{\n            e=[...e, a[q-1]]\n          })\n          e = e.filter(q=>q)\n          res=[...res, e]\n        })\n      })\n      return res\n    }\n\n    Sphere=(ls,cl,rw)=>{\n      let X,Y,Z\n      let ret=[]\n      for(i=cl*rw;i--;){\n        a=[]\n        j=i%cl\n        k=(i/cl|0)\n        l=(j+1)%cl\n\n        X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*k)*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*k)*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*(k+1))*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*(k+1))*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n\n        ret = [...ret, a]\n      }\n      return ret\n    }\n\n    Tetrahedron=ls=>{\n      let ret=[]\n      let a = []\n      let theta=1.2217304763960306\n      for(let i=3;i--;){\n        X=S(p=Math.PI*2/3*i)\n        Y=C(p)+.5\n        Z=0\n        R2(0,-theta/2,0)\n        a=[...a, [X,Y,Z]]\n      }\n      ret=[...ret, a]\n      b=JSON.parse(JSON.stringify(a))\n      ax=ay=az=0\n      b.map(v=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R2(0,theta,0)\n        v[0]=X\n        v[1]=Y\n        v[2]=Z\n      })\n      ret=[...ret, b]\n      ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax*1.5\n          q[1]-=ay*1.5\n          q[2]-=az*1.5\n        })\n      })\n\n      b=JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n      })\n      ret=[...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,.96,0)\n          R2(0,0,t*5)\n          R2(0,Math.PI,0)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Octahedron=ls=>{\n      ret = []\n      a=[]\n      for(i=4;i--;){\n        X1=S(p=Math.PI*2/4*i+Math.PI/4)\n        Y1=C(p)\n        Z1=0\n        X2=S(p=Math.PI*2/4*(i+1)+Math.PI/4)\n        Y2=C(p)\n        Z2=0\n        X3=0\n        Y3=0\n        Z3=1\n        a=[\n          [X1,Y1,Z1],\n          [X2,Y2,Z2],\n          [X3,Y3,Z3]\n        ]\n        ret=[...ret, a]\n        a=[\n          [X1,Y1,-Z1],\n          [X2,Y2,-Z2],\n          [X3,Y3,-Z3]\n        ]\n        ret=[...ret, a]\n      }\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Cube=ls=>{\n      let ret=[]\n      for(j=6;j--;ret=[...ret,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2                                                                                                            ])[j%3]*(l=j<3?-ls:ls),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Icosahedron=ls=>{\n      let a=[1,1],ret=[]\n      let b\n      for(i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]];\n      let phi=a[l]/a[l-1]\n      a=[[[-phi,-1,0],[phi,-1,0],[phi,1,0],[-phi,1,0]],[[0,-phi,-1],[0,phi,-1],[0,phi,1],[0,-phi,1]],[[                                                                                                            -1,0,-phi],[-1,0,phi],[1,0,phi],[1,0,-phi]]]\n      let ico=[[[0,1],[1,0],[1,3]],[[0,1],[2,3],[1,0]],[[2,0],[2,3],[1,0]],[[0,1],[2,3],[0,2]],[[1,1],[                                                                                                            2,3],[0,2]],[[1,1],[2,3],[2,0]],[[1,1],[1,2],[0,2]],[[0,1],[2,2],[0,2]],[[0,0],[1,0],[2,0]],[[2,0],[0,3                                                                                                            ],[0,0]],[[1,1],[1,2],[0,3]],[[1,1],[2,0],[0,3]],[[0,1],[1,3],[2,2]],[[1,3],[2,1],[2,2]],[[2,1],[0,3],[                                                                                                            1,2]],[[2,1],[0,0],[1,3]],[[1,2],[2,2],[2,1]],[[2,2],[1,2],[0,2]],[[0,3],[2,1],[0,0]],[[1,3],[1,0],[0,0                                                                                                            ]]]\n      ico.map((v,i)=>{\n        b=[]\n        v.map(q=>{\n          t1=q[0],t2=q[1]\n          X=a[t1][t2][0],Y=a[t1][t2][1],Z=a[t1][t2][2]\n          b=[...b, [X,Y,Z]]\n        })\n        ret=[...ret, b]\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Dodecahedron=ls=>{\n      let ret=[]\n      let sd=5\n      let a=[], b=[]\n      mind=6e6\n      for(let i=sd;i--;){\n        X=S(p=Math.PI*2/sd*i)\n        Y=C(p)\n        Z=0\n        if(Y<mind)mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a=a.map(v=>{\n        X=v[0]\n        Y=v[1]-=mind\n        Z=v[2]\n        R2(0,.5535735,0)\n        return [X,Y,Z]\n      })\n\n      ret = [...ret, a]\n      b=JSON.parse(JSON.stringify(a)).map(v=>{\n        d=Math.hypot(v[0],v[1])\n        v[0]=S(p=Math.atan2(v[0],v[1])+Math.PI)*d\n        v[1]=C(p)*d\n        return v\n      })\n      ret = [...ret, b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          if(q[2]<mind)mind=q[2]\n        })\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]+=ang=1.538840639715\n        })\n      })\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI,0,Math.PI)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      b=JSON.parse(JSON.stringify(e)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI/2,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    iPc = 1, iPs = 1.5, G = 1*iPc*1.5, iPrt = Rn()*Math.PI*2/200\n    iBc = 1, ls = 3.5, sp =  1 * (2**.5/2)*4\n    iSplitV = .5\n\n\n    spawnB = () => {\n      B = Array(iBc).fill().map((v, i)=>{\n        a = []\n        for(let j=4; j--;){\n          X = S(p = Math.PI*2/4*j+Math.PI/4+t*3) * ls * (2**.5/2)*1.5\n          Y = C(p) * ls * (2**.5/2)*1.5\n          Z = S(t)*sp*.5\n          a = [...a, [X,Y,Z]]\n        }\n        return [0, 0, Z, [a], 1]\n      })\n    }\n\n    P = []\n    spawnShapes=()=>{\n      P = [...P, ...Array(iPc).fill().map((v,i)=>{\n        switch(Rn()*6|0){\n          case 0:\n            shp = Sphere(iPs,8,6)\n          break\n          case 1:\n            shp = Tetrahedron(iPs)\n          break\n          case 2:\n            shp = Octahedron(iPs)\n          break\n          case 3:\n            shp = Cube(iPs)\n          break\n          case 4:\n            shp = Dodecahedron(iPs)\n          break\n          case 5:\n            shp = Icosahedron(iPs)\n          break\n          case 1:\n            shp = Tetrahedron(iPs)\n          break\n        }\n        tx = (Rn()-.5)*G*1.5\n        ty = (Rn()-.5)*G*1.5\n        tz = (Rn()-.5)*G*1.5\n        vx = 0\n        vy = 0\n        vz = 0\n     \n        rl = (Rn()-.5)*Math.PI*2\n        pt = (Rn()-.5)*Math.PI*2\n        yw = (Rn()-.5)*Math.PI*2\n        shp.map(v=>{\n          v.map(q=>{\n            X = q[0]\n            Y = q[1]\n            Z = q[2]\n            R(rl,pt,yw)\n            q[0] = X\n            q[1] = Y\n            q[2] = Z\n          })\n        })\n        return [tx, ty, tz, shp, vx, vy, vz, 0, 0, 0, 1.1]\n      })]\n    }\n    stroke = (scol, fcol) => {\n      if(scol){\n        x.closePath()\n        x.globalAlpha = .2\n        x.strokeStyle = scol\n        x.lineWidth = Math.min(1e3,100/Z)\n        x.stroke()\n        x.globalAlpha = 1\n        x.lineWidth /= 5\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n    B=[]\n    bounding = Cube(ls)\n    bg = new Image()\n    bg.src = \'proxy.php?url=https://srmcgann.github.io/assets/1kh6Ln.jpg\'\n  }\n\n  x.globalAlpha=.2\n  x.drawImage(bg,0,0,c.width,c.height)\n  x.globalAlpha=1\n  x.fillStyle=\'#0003\'\n  x.fillRect(0,0,c.width,c.height)\n  oX=0\n  oY=0\n  oZ=6\n  Rl=t/8\n  Pt=-t/6\n  Yw=Math.PI/2-t/4\n  x.lineCap=x.lineJoin = \'round\'\n\n  bounding.map(v=>{\n    x.beginPath()\n    v.map(q=>{\n      X = q[0]\n      Y = q[1]\n      Z = q[2]\n      R(Rl,Pt,Yw,1)\n      if(Z>0)x.lineTo(...Q())\n    })\n    stroke(\'#ff000020\',\'#4400ff04\')\n  })\n\n  if(!((t*60|0)%60))spawnShapes()\n  if(t && !((t*60|0)%2))spawnB()\n\n  B = B.filter(v=>v[4]>0)\n\n  for(N_=0;N_<B.length;++N_){\n\n    splits = []\n    P.map(v=>{\n      tx1 = v[0] += v[4] /= 1.02\n      ty1 = v[1] += v[5] /= 1.02\n      tz1 = v[2] += v[6] /= 1.02\n      a = []\n      v[3].map((q,j)=>{\n        q.map((n, m)=>{\n          l = m\n          X1 = tx1 + q[l][0]\n          Y1 = ty1 + q[l][1]\n          Z1 = tz1 + q[l][2]\n          l = (m+1)%q.length\n          X2 = tx1 + q[l][0]\n          Y2 = ty1 + q[l][1]\n          Z2 = tz1 + q[l][2]\n          B.map((k,N)=>{\n            if(N==N_){\n              if(k[4]==1){\n                Y3 = -G*2\n                Z3 = k[2]*2\n                Y4 = G*2\n                Z4 = k[2]*2\n                if(l=I(Y1,Z1,Y2,Z2,Y3,Z3,Y4,Z4)){\n                  X = (X1 + X2) / 2\n                  a = [...a, [j, m, [X-tx1, l[0]-ty1, l[1]-tz1]]]\n                }\n              }\n            }\n          })\n        })\n      })\n      if(a.length){\n        b1 = [], b2 = []\n        dz=a[0][2][2]\n        v[3].map((n,m)=>{\n          tface = []\n          n.map((k,K)=>{\n            if(k[2] > dz){\n              tface = [...tface, k]\n            }\n            a.map((q,j)=>{\n              if(q[0]==m && q[1] == K){\n                tface = [...tface, [...q[2]]]\n              }\n            })\n          })\n          b1 = [...b1, tface]\n\n          /*\n          tface = []\n          a.map((q,j)=>{\n            if(!j){\n              tface = [...tface, [...q[2]]]\n            }\n          })\n          b1 = [...b1, tface]*/\n\n          tface = []\n          n.map((k,K)=>{\n            if(k[2] < dz){\n              tface = [...tface, [...k]]\n            }\n            a.map((q,j)=>{\n              if(q[0]==m && q[1] == K){\n                tface = [...tface, [...q[2]]]\n              }\n            })\n          })\n          b2 = [...b2, tface]\n        })\n\n        /*tface = []\n        a.map((q,j)=>{\n          tface = [...tface, [...q[2]]]\n        })\n        b1 = [...b1, tface]\n        tface = []\n        a.map((q,j)=>{\n          tface = [...tface, [...q[2]]]\n        })\n        b2 = [...b2, tface]*/ \n\n        rl1 = (Rn()-.5)*iPrt\n        pt1 = (Rn()-.5)*iPrt\n        yw1 = (Rn()-.5)*iPrt\n        rl2 = (Rn()-.5)*iPrt\n        pt2 = (Rn()-.5)*iPrt\n        yw2 = (Rn()-.5)*iPrt\n\n        splits = [\n          ...splits,\n          [\n            tx1,ty1,tz1,\n            [...b1],\n            (Rn()-.5)/4*iSplitV,\n            (Rn()-.5)/4*iSplitV,\n            0,\n            rl1,pt1,yw1,1\n          ]\n        ]\n\n        splits = [\n          ...splits,\n          [\n            tx1,ty1,tz1,\n            [...b2],\n            (Rn()-.5)/4*iSplitV,\n            (Rn()-.5)/4*iSplitV,\n            0,\n            rl2,pt2,yw2,1\n          ]\n        ]\n      } else {\n        splits = [...splits, [...v]]\n      }\n    })\n\n    if(splits.length){\n      P = splits\n    }\n  }\n\n  P = P.filter(v=>v[10]>.2)\n\n  if(!P.length) spawnShapes()\n\n  P.map(v=>{\n    tx = v[0]\n    ty = v[1]\n    tz = v[2]\n    rl = v[7]\n    pt = v[8]\n    yw = v[9]\n    if(v[10] <= 1) v[10]-=.01\n    v[3].map(q=>{\n      x.beginPath()\n      q.map(n=>{\n        X = n[0]\n        Y = n[1]\n        Z = n[2]\n        R(rl,pt,yw)\n        n[0] = X\n        n[1] = Y\n        n[2] = Z\n        X = tx + n[0]\n        Y = ty + n[1]\n        Z = tz + n[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n      })\n      stroke(`hsla(${150},99%,80%,${Math.min(1,v[10]*.5)**2})`, `hsla(${-150},99%,50%,${(.25*Math.min(1,v[10]))**2})`)\n    })\n  })\n\n  B.map(v=>{\n    tx = v[0]\n    ty = v[1]\n    tz = v[2]\n    v[4]-=.1\n    v[3].map(q=>{\n      x.beginPath()\n      q.map(n=>{\n        X = tx + n[0]\n        Y = ty + n[1]\n        Z = tz + n[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n      })\n      stroke(`hsla(0,99%,70%,${1*v[4]**3}`, `rgba(256,0,64,${.25*v[4]**3}`)\n    })\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'polyhedron lawnmower', 145, 'whitehot robot', '2023-03-20 17:15:44', '[600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 82, '', 0, 0),
(600709, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    res = document.createElement(\'video\')\n    res.oncanplay = e => {\n      go=true\n      buffer = document.createElement(\'canvas\')\n      buffer.width = res.videoWidth/2|0\n      buffer.height = res.videoHeight/2|0\n      bctx = buffer.getContext(\'2d\', {willReadFrequently: true})\n      res.play()\n    }\n    res.loop=true\n    res.muted=true\n    res.defaultPlaybackRate=1\n    res.src = \'proxy.php?url=https://srmcgann.github.io/assets/1Sf3kP.mp4\'\n  }\n\n  x.fillStyle=\'#0008\'\n  x.fillRect(0,0,c.width,c.height)\n\n  if(go){\n    shiftWidth = S(t*3)*30\n    bctx.drawImage(res,0,0,buffer.width,buffer.height)\n    data = bctx.getImageData(0,0,buffer.width,buffer.height)\n    l = data.data\n    //l2 = bctx.getImageData(0,0,buffer.width,buffer.height).data\n    for(m=1;m--;)for(i=0; i<l.length; i+=4){\n      X = (i/4|0) % buffer.width\n      Y = (i/4|0) / buffer.width | 0\n      red   = l[0+i]\n      green = l[1+i]\n      blue  = l[2+i]\n      lum = (red+green+blue)/3\n\n      tx_red = X - shiftWidth\n      red_redshift = green_redshift = blue_redshift = 0\n      tx_blue = X + shiftWidth\n      red_blueshift = green_blueshift = blue_blueshift = 0\n        if(tx_red >= 0 && Y>0){\n          j = (Y*buffer.width + tx_red)|0\n          red_redshift   = Math.min(4096, l[j * 4 + 0]*4)\n          green_redshift = 0//l[j * 1 + 1]\n          blue_redshift  = 0//l[j * 4 + 2]\n        }\n        if(tx_blue <= buffer.width-1 && Y < buffer.height-1){\n          j = (Y*buffer.width + tx_blue)|0\n          red_blueshift   = 0//l[j * 4 + 0]\n          green_blueshift = 0//l[j * 4 + 1]\n          blue_blueshift  = Math.min(4096, l[j * 4 + 2]*5)\n        }\n      new_red   = (red   + red_redshift   + red_blueshift)   / 256 * lum\n      new_green = (green + green_redshift + green_blueshift) / 256 * lum\n      new_blue  = (blue  + blue_redshift  + blue_blueshift)  / 256 * lum\n      l[0+i] = new_red\n      l[1+i] = new_green\n      l[2+i] = new_blue\n      l[3+i] = 255\n    }\n    bctx.putImageData(data,0,0)\n    x.drawImage(buffer,0,0,c.width,c.height)\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c></canvas>', 'Video red-blue shift 2', 145, 'whitehot robot', '2023-03-22 01:53:25', '[600703,600485,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 74, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600710, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nR = function(r,g,b,a) {\n  a = a === undefined ? 1 : a;\n  return \"rgba(\"+(r|0)+\",\"+(g|0)+\",\"+(b|0)+\",\"+a+\")\";\n};\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nDraw=()=>{\n  if(!t){\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    R2=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n\n    async function loadOBJ(url, scale, tx, ty, tz, rl, pt, yw) {\n      let res\n      await fetch(url, res => res).then(data=>data.text()).then(data=>{\n        a=[]\n        data.split(\"\\nv \").map(v=>{\n          a=[...a, v.split(\"\\n\")[0]]\n        })\n        a=a.filter((v,i)=>i).map(v=>[...v.split(\' \').map(n=>(+n.replace(\"\\n\", \'\')))])\n        ax=ay=az=0\n        a.map(v=>{\n          v[1]*=-1\n          ax+=v[0]\n          ay+=v[1]\n          az+=v[2]\n        })\n        ax/=a.length\n        ay/=a.length\n        az/=a.length\n        a.map(v=>{\n          X=(v[0]-ax)*scale\n          Y=(v[1]-ay)*scale\n          Z=(v[2]-az)*scale\n          R2(rl,pt,yw,0)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n        })\n        maxY=-6e6\n        a.map(v=>{\n          if(v[1]>maxY)maxY=v[1]\n        })\n        a.map(v=>{\n          v[1]-=maxY-oY\n          v[0]+=tx\n          v[1]+=ty\n          v[2]+=tz\n        })\n\n        b=[]\n        data.split(\"\\nf \").map(v=>{\n          b=[...b, v.split(\"\\n\")[0]]\n        })\n        b.shift()\n        b=b.map(v=>v.split(\' \'))\n        b=b.map(v=>{\n          v=v.map(q=>{\n            return +q.split(\'/\')[0]\n          })\n          v=v.filter(q=>q)\n          return v\n        })\n        \n        res=[]\n        b.map(v=>{\n          e=[]\n          v.map(q=>{\n            e=[...e, a[q-1]]\n          })\n          e = e.filter(q=>q)\n          res=[...res, e]\n        })\n      })\n      return res\n    }\n\n    Sphere=(ls,cl,rw)=>{\n      let X,Y,Z\n      let ret=[]\n      for(i=cl*rw;i--;){\n        a=[]\n        j=i%cl\n        k=(i/cl|0)\n        l=(j+1)%cl\n\n        X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*k)*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*k)*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*(k+1))*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*(k+1))*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n\n        ret = [...ret, a]\n      }\n      return ret\n    }\n\n    Tetrahedron=ls=>{\n      let ret=[]\n      let a = []\n      let theta=1.2217304763960306\n      for(let i=3;i--;){\n        X=S(p=Math.PI*2/3*i)\n        Y=C(p)+.5\n        Z=0\n        R2(0,-theta/2,0)\n        a=[...a, [X,Y,Z]]\n      }\n      ret=[...ret, a]\n      b=JSON.parse(JSON.stringify(a))\n      ax=ay=az=0\n      b.map(v=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R2(0,theta,0)\n        v[0]=X\n        v[1]=Y\n        v[2]=Z\n      })\n      ret=[...ret, b]\n      ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax*1.5\n          q[1]-=ay*1.5\n          q[2]-=az*1.5\n        })\n      })\n\n      b=JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n      })\n      ret=[...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,.96,0)\n          R2(0,0,t*5)\n          R2(0,Math.PI,0)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Octahedron=ls=>{\n      ret = []\n      a=[]\n      for(i=4;i--;){\n        X1=S(p=Math.PI*2/4*i+Math.PI/4)\n        Y1=C(p)\n        Z1=0\n        X2=S(p=Math.PI*2/4*(i+1)+Math.PI/4)\n        Y2=C(p)\n        Z2=0\n        X3=0\n        Y3=0\n        Z3=1\n        a=[\n          [X1,Y1,Z1],\n          [X2,Y2,Z2],\n          [X3,Y3,Z3]\n        ]\n        ret=[...ret, a]\n        a=[\n          [X1,Y1,-Z1],\n          [X2,Y2,-Z2],\n          [X3,Y3,-Z3]\n        ]\n        ret=[...ret, a]\n      }\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Cube=ls=>{\n      let ret=[]\n      for(j=6;j--;ret=[...ret,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2                                                                                                            ])[j%3]*(l=j<3?-ls:ls),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Icosahedron=ls=>{\n      let a=[1,1],ret=[]\n      let b\n      for(i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]];\n      let phi=a[l]/a[l-1]\n      a=[[[-phi,-1,0],[phi,-1,0],[phi,1,0],[-phi,1,0]],[[0,-phi,-1],[0,phi,-1],[0,phi,1],[0,-phi,1]],[[                                                                                                            -1,0,-phi],[-1,0,phi],[1,0,phi],[1,0,-phi]]]\n      let ico=[[[0,1],[1,0],[1,3]],[[0,1],[2,3],[1,0]],[[2,0],[2,3],[1,0]],[[0,1],[2,3],[0,2]],[[1,1],[                                                                                                            2,3],[0,2]],[[1,1],[2,3],[2,0]],[[1,1],[1,2],[0,2]],[[0,1],[2,2],[0,2]],[[0,0],[1,0],[2,0]],[[2,0],[0,3                                                                                                            ],[0,0]],[[1,1],[1,2],[0,3]],[[1,1],[2,0],[0,3]],[[0,1],[1,3],[2,2]],[[1,3],[2,1],[2,2]],[[2,1],[0,3],[                                                                                                            1,2]],[[2,1],[0,0],[1,3]],[[1,2],[2,2],[2,1]],[[2,2],[1,2],[0,2]],[[0,3],[2,1],[0,0]],[[1,3],[1,0],[0,0                                                                                                            ]]]\n      ico.map((v,i)=>{\n        b=[]\n        v.map(q=>{\n          t1=q[0],t2=q[1]\n          X=a[t1][t2][0],Y=a[t1][t2][1],Z=a[t1][t2][2]\n          b=[...b, [X,Y,Z]]\n        })\n        ret=[...ret, b]\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Dodecahedron=ls=>{\n      let ret=[]\n      let sd=5\n      let a=[], b=[]\n      mind=6e6\n      for(let i=sd;i--;){\n        X=S(p=Math.PI*2/sd*i)\n        Y=C(p)\n        Z=0\n        if(Y<mind)mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a=a.map(v=>{\n        X=v[0]\n        Y=v[1]-=mind\n        Z=v[2]\n        R2(0,.5535735,0)\n        return [X,Y,Z]\n      })\n\n      ret = [...ret, a]\n      b=JSON.parse(JSON.stringify(a)).map(v=>{\n        d=Math.hypot(v[0],v[1])\n        v[0]=S(p=Math.atan2(v[0],v[1])+Math.PI)*d\n        v[1]=C(p)*d\n        return v\n      })\n      ret = [...ret, b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          if(q[2]<mind)mind=q[2]\n        })\n      })\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]+=ang=1.538840639715\n        })\n      })\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI,0,Math.PI)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      e=JSON.parse(JSON.stringify(ret = [...ret, ...b]))\n\n      b=JSON.parse(JSON.stringify(ret)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      b=JSON.parse(JSON.stringify(e)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI/2,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    cl = 6, br = 30, rw = 30, sp = .6\n    B = Array(cl*rw*br).fill().map((v,i)=>{\n      X = ((i%cl)-cl/2+.5)*sp*3\n      Y = (((i/cl|0)%rw)-rw/2+.5)*sp\n      Z = ((i/cl/rw|0)-br/2+.5)*sp\n      vx=vy=vz=0\n      return [X,Y,Z,X,Y,Z,vx,vy,vz]\n    })\n\n    elasticity = 200\n    dampening = 1.3\n    iPulsev = 250000\n\n    iPc = 3, G = cl * sp\n    P = Array(iPc).fill().map((v,i)=>{\n      X = 0\n      Y = 0\n      Z = iPc*(i-iPc/2+.5)*2\n      return [X,Y,Z]\n    })\n\n    bounding = Cube((cl+4)*sp/(2**.5))\n\n    stroke = (scol, fcol) => {\n      if(scol){\n        x.closePath()\n        x.globalAlpha = .2\n        x.strokeStyle = scol\n        x.stroke()\n        x.lineWidth = Math.min(1e3, 500/Z)\n        x.globalAlpha = 1\n        x.lineWidth/=5\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n    bg = new Image()\n    bg.src = \'proxy.php?url=https://srmcgann.github.io/assets/fH9IY.jpg\'\n\n    star = new Image()\n    star.src = \'proxy.php?url=https://srmcgann.github.io/temp/stars/star6.png\'\n  }\n\n  x.globalAlpha = .4\n  x.drawImage(bg,0,-c.height/10,c.width,c.height*1.1)\n  x.globalAlpha = 1\n  x.fillStyle=\'#0001\'\n  x.fillRect(0,0,c.width,c.height)\n  oX=oY=0, oZ=8-C(t)*4\n  //Rl=0,Pt=S(t)/3,Yw=t\n  Rl=-t/4+Math.PI/2,Pt=-C(t/8)*8+Math.PI/2,Yw=S(t/4)*2\n\n  if(0)P.map(n=>{\n    bounding