obalAlpha = .3\n  x.drawImage(bg,0,0,c.width,c.height)\n  x.globalAlpha = 1\n  x.fillStyle=\'#0006\'\n  x.fillRect(0,0,c.width,c.height)\n  oX=oY=0\n  oZ=Math.min(40,Math.max(16,10+S(t)*100))\n  Rl=t/3\n  Pt=-t/2\n  Yw=S(t/8)*10\n  x.lineJoin=x.lineCap=\'round\'\n\n  P.map((v,i)=>{\n    rv=S(t/2+i)*15\n    tx = v[0]\n    ty = v[1]\n    tz = v[2]\n    v[3].map((q,j)=>{\n      tx_ = q[0]\n      ty_ = q[1]\n      tz_ = q[2]\n      d_ = Math.hypot(tx_+tx,ty_+ty)\n      p_ = Math.atan2(tx_+tx,ty_+ty)\n      if(j){\n        x.beginPath()\n        l = j\n        X = v[3][l][0]\n        Y = v[3][l][1]\n        Z = v[3][l][2]\n        if(1)switch(i%3){\n          case 0: R(0,0,Math.PI/2),R(rv,0,0); break\n          case 1: R(0,rv,0); break\n          case 2: R(0,0,rv); break\n        }\n        X+=tx\n        Y+=ty\n        Z+=tz\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n        l = j-1\n        X = v[3][l][0]\n        Y = v[3][l][1]\n        Z = v[3][l][2]\n        if(1)switch(i%3){\n          case 0: R(0,0,Math.PI/2),R(rv,0,0); break\n          case 1: R(0,rv,0); break\n          case 2: R(0,0,rv); break\n        }\n        X+=tx\n        Y+=ty\n        Z+=tz\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n      }\n      stroke(\'#4f86\')\n      for(k = 9;k--;){\n        x.beginPath()\n        X = 0\n        Y = (k+1)*len*2\n        Z = 0\n        R(0,t*toothSpeed+Math.PI*5/v[3].length*j,0)\n        R(p_,0,0)\n        X+=tx_\n        Y+=ty_\n        Z+=tz_\n        if(1)switch(i%3){\n          case 0: R(0,0,Math.PI/2),R(rv,0,0); break\n          case 1: R(0,rv,0); break\n          case 2: R(0,0,rv); break\n        }\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n\n        X = 0\n        Y = k*len*2\n        Z = 0\n        R(0,t*toothSpeed+Math.PI*5/v[3].length*j,0)\n        R(p_,0,0)\n        svx=X\n        svy=Y\n        svz=Z\n        X+=tx_+tx\n        Y+=ty_+ty\n        Z+=tz_+tz\n        if(1)switch(i%3){\n          case 0: R(0,0,Math.PI/2),R(rv,0