ret, ...b]\n\n      b=JSON.parse(JSON.stringify(e)).map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(Math.PI/2,0,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n        return v\n      })\n      ret = [...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n    geoSphere = (mx, my, mz, iBc, size) => {\n        let collapse=0\n        let B=Array(iBc).fill().map(v=>{\n          X = Rn()-.5\n          Y = Rn()-.5\n          Z = Rn()-.5\n          return  [X,Y,Z]\n        })\n        for(let m=120;m--;){\n          B.map((v,i)=>{\n            X = v[0]\n            Y = v[1]\n            Z = v[2]\n            B.map((q,j)=>{\n              if(j!=i){\n                X2=q[0]\n                Y2=q[1]\n                Z2=q[2]\n                d=1+(Math.hypot(X-X2,Y-Y2,Z-Z2)*(3+iBc/40)*3)**4\n                X+=(X-X2)*99/d\n                Y+=(Y-Y2)*99/d\n                Z+=(Z-Z2)*99/d\n              }\n            })\n            d=Math.hypot(X,Y,Z)\n            v[0]=X/d\n            v[1]=Y/d\n            v[2]=Z/d\n            if(collapse){\n              d=25+Math.hypot(X,Y,Z)\n              v[0]=(X-X/d)/1.1\n              v[1]=(X-X/d)/1.1\n              v[2]=(Z-Z/d)/1.1\n            }\n          })\n        }\n        B.map(v=>{\n          v[0]*=size\n          v[1]*=size\n          v[2]*=size\n          v[0]+=mx\n          v[1]+=my\n          v[2]+=mz\n          v[3]=v[0]\n          v[4]=v[1]\n          v[5]=v[2]\n        })\n\n        mind=6e6\n        P = []\n        B.map((v,i)=>{\n          X1 = v[0]\n          Y1 = v[1]\n          Z1 = v[2]\n          B.map((q,j)=>{\n            if(j!=i){\n              X2 = q[0]\n              Y2 = q[1]\n              Z2 = q[2]\n              if((d = Math.hypot(X1-X2,Y1-Y2,Z1-Z2))<mind)mind=d\n            }\n          })\n        })\n        B.map((v,i)=>{\n          X1 = v[0]\n          Y1 = v[1]\n          Z1 = v[2]\n          B.map((q,j)=>{\n            if(j!=i){\n              X2 = q[0]\n              Y2 = q[1]\n              Z2 = q[2]\n              if((d = Math.hypot(X1-X2,Y1-Y2,Z1-Z2))<mind*1.65){\n                P=[...P, [v,q]]\n              }\n            }\n          })\n        })\n      return [mx, my, mz, size, B, P]\n    }\n     \n    stroke=(scol,fcol,olw=1)=>{\n      if(scol){\n        x.closePath()\n        //x.globalAlpha=.1\n        x.lineWidth=Math.min(1e3,1500/Z) * olw\n        x.strokeStyle=scol\n        //x.stroke()\n        x.globalAlpha=1\n        x.lineWidth/=16\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle=fcol\n        x.fill()\n      }\n    }\n\n    iSc = 8\n    ls = 4\n    base_sphere = geoSphere(0,0,0,30,ls)\n\n    process = () => {\n      sp = (.55-C(t*2)/2)*3\n      e = []\n      shps = []\n      let a = [], br = 5\n      for(k=br;k--;){\n        a = []\n        for(let i=0; i<iSc; i++) {\n          tx = S(p=Math.PI*2/iSc*i+Math.PI/iSc) * ls * C(q_ = Math.PI*2/br*k) *sp\n          ty = C(p) * ls * C(q_) * sp\n          tz = S(q_) * ls * sp\n          b = []\n          base_sphere[4].map(n=>{\n            X = tx + n[0]\n            Y = ty + n[1]\n            Z = tz + n[2]\n            let cull = false\n            for(k2=br;!cull && k2--;){\n              for(let j=0; !cull && j<iSc; j++) {\n                if(j!=i || k2!=k){\n                  tx2 = S(p=Math.PI*2/iSc*j+Math.PI/iSc) * ls * C(q_ = Math.PI*2/br*k2) *sp\n                  ty2 = C(p) * ls * C(q_) * sp\n                  tz2 = S(q_) * ls * sp\n                  d1 = Math.hypot(tx2-X,ty2-Y,tz2-Z)\n                  if(d1 < ls-.1) cull = true\n                }\n              }\n            }\n            if(!cull){\n              b = [...b, [X,Y,Z]]\n            }\n          })\n          a = [...a, ...b]\n        }\n        a.map((v,i)=>{\n          a.map((q,j)=>{\n            if(i!==j){\n              if((d=Math.hypot(q[0]-v[0],q[1]-v[1],q[2]-v[2]))<mind*1.35){\n                e = [...e, [[...v],[...q]]]\n              }\n            }\n         })\n        })\n      }\n      shps = [[0,0,0,0,[],e]]\n    }\n    bg = new Image()\n    bg.src = \'proxy.php?url=https://srmcgann.github.io/assets/1kh6Ln.jpg\'\n  }\n\n\n  x.globalAlpha = .3\n  x.drawImage(bg,0,0,c.width,c.height)\n  x.globalAlpha = 1\n  x.fillStyle=\'#0003\'\n  x.fillRect(0,0,c.width,c.height)\n  oX=0\n  oY=0\n  oZ=Math.max(12,Math.min(40,C(t/2)*200))\n  Rl=t/4+1\n  Pt=-t/2\n  Yw=C(t/2)*8\n  x.lineJoin = x.lineCap = \'butt\'\n  \n  process()\n  if(1)shps.map(v=>{\n    tx = v[0]\n    ty = v[1]\n    tz = v[2]\n    v[5].map(q=>{\n      x.beginPath()\n      X = tx + q[0][0]\n      Y = ty + q[0][1]\n      Z = tz + q[0][2]\n      R(Rl,Pt,Yw,1)\n      if(Z>0)x.lineTo(...Q())\n      /*x.fillStyle = \'#fff8\'\n      s = Math.min(1e3, 500/Z)\n      l = Q()\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)*/\n      tx_ = X = tx + q[1][0]\n      ty_ = Y = ty + q[1][1]\n      tz_ = Z = tz + q[1][2]\n      R(Rl,Pt,Yw,1)\n      if(Z>0)x.lineTo(...Q())\n      /*x.fillStyle = \'#f008\'\n      s = Math.min(1e3, 20/Z)\n      l = Q()\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)*/\n      stroke(`hsla(${Math.hypot(tx_,ty_,tz_)*30-t*3000},99%,50%,.01)`,\'\',20)\n      stroke(\'#fff4\',\'\',2)\n    })\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  font-family: courier;\n}\n#c{\n  width: 100%;\n  height: 100%;\n  position: absolute;\n  background: #000;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'geospheres fancy', 145, 'whitehot robot', '2023-03-29 17:12:03', '[600484,600482,600422,600373,600347,600253,600252,600251,600248,600247]', 55, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600720, '', 'c=document.querySelector(\'#c\')\nc.width  = 1920\nc.height = 1080\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nRn=Math.random\nt=go=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\n\nasync function Draw(){\nif(!t){\n    oX=oY=oZ=0\n    Rl=Pt=Yw=0\n\n    R=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    R2=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n\n    R3=(Rl,Pt,Yw,m)=>{\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      if(m){\n        X+=0\n        Y+=0\n        Z+=25+S(t)*15\n      }\n    }\n\n    async function loadOBJ(url, scale, tx, ty, tz, rl, pt, yw) {\n      let res\n      await fetch(url, res => res).then(data=>data.text()).then(data=>{\n        a=[]\n        data.split(\"\\nv \").map(v=>{\n          a=[...a, v.split(\"\\n\")[0]]\n        })\n        a=a.filter((v,i)=>i).map(v=>[...v.split(\' \').map(n=>(+n.replace(\"\\n\", \'\')))])\n        ax=ay=az=0\n        a.map(v=>{\n          v[1]*=-1\n          ax+=v[0]\n          ay+=v[1]\n          az+=v[2]\n        })\n        ax/=a.length\n        ay/=a.length\n        az/=a.length\n        a.map(v=>{\n          X=(v[0]-ax)*scale\n          Y=(v[1]-ay)*scale\n          Z=(v[2]-az)*scale\n          R2(rl,pt,yw,0)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n        })\n        maxY=-6e6\n        a.map(v=>{\n          if(v[1]>maxY)maxY=v[1]\n        })\n        a.map(v=>{\n          v[1]-=maxY-oY\n          v[0]+=tx\n          v[1]+=ty\n          v[2]+=tz\n        })\n\n        b=[]\n        data.split(\"\\nf \").map(v=>{\n          b=[...b, v.split(\"\\n\")[0]]\n        })\n        b.shift()\n        b=b.map(v=>v.split(\' \'))\n        b=b.map(v=>{\n          v=v.map(q=>{\n            return +q.split(\'/\')[0]\n          })\n          v=v.filter(q=>q)\n          return v\n        })\n        \n        res=[]\n        b.map(v=>{\n          e=[]\n          v.map(q=>{\n            e=[...e, a[q-1]]\n          })\n          e = e.filter(q=>q)\n          res=[...res, e]\n        })\n      })\n      return res\n    }\n\n    Sphere=(ls,cl,rw)=>{\n      let X,Y,Z\n      let ret=[]\n      for(i=cl*rw;i--;){\n        a=[]\n        j=i%cl\n        k=(i/cl|0)\n        l=(j+1)%cl\n\n        X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*k)*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*k)*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*l)*S(q=Math.PI/rw*(k+1))*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n        X=S(p=Math.PI*2/cl*j)*S(q=Math.PI/rw*(k+1))*ls\n        Y=C(q)*ls\n        Z=C(p)*S(q)*ls\n        a=[...a,[X,Y,Z]]\n\n        ret = [...ret, a]\n      }\n      return ret\n    }\n\n    Tetrahedron=ls=>{\n      let ret=[]\n      let a = []\n      let theta=1.2217304763960306\n      for(let i=3;i--;){\n        X=S(p=Math.PI*2/3*i)\n        Y=C(p)+.5\n        Z=0\n        R2(0,-theta/2,0)\n        a=[...a, [X,Y,Z]]\n      }\n      ret=[...ret, a]\n      b=JSON.parse(JSON.stringify(a))\n      ax=ay=az=0\n      b.map(v=>{\n        X=v[0]\n        Y=v[1]\n        Z=v[2]\n        R2(0,theta,0)\n        v[0]=X\n        v[1]=Y\n        v[2]=Z\n      })\n      ret=[...ret, b]\n      ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax*1.5\n          q[1]-=ay*1.5\n          q[2]-=az*1.5\n        })\n      })\n\n      b=JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n        })\n      })\n      ret=[...ret, ...b]\n\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,.96,0)\n          R2(0,0,t*5)\n          R2(0,Math.PI,0)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Octahedron=ls=>{\n      ret = []\n      a=[]\n      for(i=4;i--;){\n        X1=S(p=Math.PI*2/4*i+Math.PI/4)\n        Y1=C(p)\n        Z1=0\n        X2=S(p=Math.PI*2/4*(i+1)+Math.PI/4)\n        Y2=C(p)\n        Z2=0\n        X3=0\n        Y3=0\n        Z3=1\n        a=[\n          [X1,Y1,Z1],\n          [X2,Y2,Z2],\n          [X3,Y3,Z3]\n        ]\n        ret=[...ret, a]\n        a=[\n          [X1,Y1,-Z1],\n          [X2,Y2,-Z2],\n          [X3,Y3,-Z3]\n        ]\n        ret=[...ret, a]\n      }\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,Math.PI/2,Math.PI/2)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Cube=ls=>{\n      let ret=[]\n      for(j=6;j--;ret=[...ret,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI/2*i+Math.PI/4),C(p),2**.5/2                                                                                                            ])[j%3]*(l=j<3?-ls:ls),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      ret.map(v=>{\n        v.map(q=>{\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R2(0,0,t*5)\n          q[0]=X\n          q[1]=Y\n          q[2]=Z\n          d=Math.hypot(...q)\n          q[0]/=d\n          q[1]/=d\n          q[2]/=d\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n      })\n      return ret\n    }\n\n    Icosahedron=ls=>{\n      let a=[1,1],ret=[]\n      let b\n      for(i=40;i--;)a=[...a,a[l=a.length-1]+a[l-1]];\n      let phi=a[l]/a[l-1]\n      a=[[[-phi,-1,0],[phi,-1,0],[phi,1,0],[-phi,1,0]],[[0,-phi,-1],[0,phi,-1],[0,phi,1],[0,-phi,1]],[[                                                                                                            -1,0,-phi],[-1,0,phi],[1,0,phi],[1,0,-phi]]]\n      let ico=[[[0,1],[1,0],[1,3]],[[0,1],[2,3],[1,0]],[[2,0],[2,3],[1,0]],[[0,1],[2,3],[0,2]],[[1,1],[                                                                                                            2,3],[0,2]],[[1,1],[2,3],[2,0]],[[1,1],[1,2],[0,2]],[[0,1],[2,2],[0,2]],[[0,0],[1,0],[2,0]],[[2,0],[0,3                                                                                                            ],[0,0]],[[1,1],[1,2],[0,3]],[[1,1],[2,0],[0,3]],[[0,1],[1,3],[2,2]],[[1,3],[2,1],[2,2]],[[2,1],[0,3],[                                                          