     Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      ax=ay=az=ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax\n          q[1]-=ay\n          q[2]-=az\n        })\n      })\n      return ret\n    }\n\n    Cube = size => {\n      for(CB=[],j=6;j--;CB=[...CB,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?size/1.5:-size/1.5),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      return CB\n    }\n    \n    Octahedron = size => {\n      ret = []\n      let h = size/1.25\n      for(j=8;j--;){\n        a = []\n        X = 0\n        Y = 0\n        Z = h * (j<4?-1:1)\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*j) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*(j+1)) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      return ret      \n    }\n    \n    Dodecahedron = size => {\n      ret = []\n      a = []\n      mind = -6e6\n      for(i=5;i--;){\n        X=S(p=Math.PI*2/5*i + Math.PI/5)\n        Y=C(p)\n        Z=0\n        if(Y>mind) mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a.map(v=>{\n        X = v[0]\n        Y = v[1]-=mind\n        Z = v[2]\n        R(0, .553573, 0)\n        v[0] = X\n        v[1] = Y\n        v[2] = Z\n      })\n      b = JSON.parse(JSON.stringify(a))\n      b.map(v=>{\n        v[1] *= -1\n      })\n      ret = [...ret, a, b]\n      mind = -6e6\n      ret.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          if(Z>mind)mind = Z\n        })\n      })\n      d1=Math.hypot(ret[0][0][0]-ret[0][1][0],ret[0][0][1]-ret[0][1][1],ret[0][0][2]-ret[0][1][2])\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]-=mind+d1/2\n        })\n      })\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          q[2]*=-1\n        })\n      })\n      ret = [...ret, ...b]\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(0,Math.PI/2,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      e = JSON.parse(JSON.stringify(ret))\n      e.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(Math.PI/2,0,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      ret = [...ret, ...b, ...e]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0] *= size/2\n          q[1] *= size/2\n          q[2] *= size/2\n        })\n      })\n      return ret\n    }\n    \n    Icosahedron = size => {\n      ret = []\n      let B = [\n        [[0,3],[1,0],[2,2]],\n        [[0,3],[1,0],[1,3]],\n        [[0,3],[2,3],[1,3]],\n        [[0,2],[2,1],[1,0]],\n        [[0,2],[1,3],[1,0]],\n        [[0,2],[1,3],[2,0]],\n        [[0,3],[2,2],[0,0]],\n        [[1,0],[2,2],[2,1]],\n        [[1,1],[2,2],[2,1]],\n        [[1,1],[2,2],[0,0]],\n        [[1,1],[2,1],[0,1]],\n        [[0,2],[2,1],[0,1]],\n        [[2,0],[1,2],[2,3]],\n        [[0,0],[0,3],[2,3]],\n        [[1,3],[2,0],[2,3]],\n        [[2,3],[0,0],[1,2]],\n        [[1,2],[2,0],[0,1]],\n        [[0,0],[1,2],[1,1]],\n        [[0,1],[1,2],[1,1]],\n        [[0,2],[2,0],[0,1]],\n      ]\n      for(p=[1,1],i=38;i--;)p=[...p,p[l=p.length-1]+p[l-1]]\n      phi = p[l]/p[l-1]\n      a = [\n        [-phi,-1,0],\n        [phi,-1,0],\n        [phi,1,0],\n        [-phi,1,0],\n      ]\n      for(j=3;j--;ret=[...ret, b])for(b=[],i=4;i--;) b = [...b, [a[i][j],a[i][(j+1)%3],a[i][(j+2)%3]]]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]*=size/2.25\n          q[1]*=size/2.25\n          q[2]*=size/2.25\n        })\n      })\n      cp = JSON.parse(JSON.stringify(ret))\n      out=[]\n      a = []\n      B.map(v=>{\n        idx1a = v[0][0]\n        idx2a = v[1][0]\n        idx3a = v[2][0]\n        idx1b = v[0][1]\n        idx2b = v[1][1]\n        idx3b = v[2][1]\n        a = [...a, [cp[idx1a][idx1b],cp[idx2a][idx2b],cp[idx3a][idx3b]]]\n      })\n      out = [...out, ...a]\n      return out\n    }\n    \n    stroke = (scol, fcol, lwo=1, od=true, oga=1) => {\n      if(scol){\n        x.closePath()\n        if(od) x.globalAlpha = .2*oga\n        x.strokeStyle = scol\n        x.lineWidth = Math.min(1000,100*lwo/Z)\n        if(od) x.stroke()\n        x.lineWidth /= 4\n        x.globalAlpha = 1*oga\n        x.stroke()\n      }\n      if(fcol){\n        x.globalAlpha = 1*oga\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n    \n    subbed = (subs, size, sphereize, shape) => {\n      for(let m=subs; m--;){\n        base = shape\n        shape = []\n        base.map(v=>{\n          l = 0\n          X1 = v[l][0]\n          Y1 = v[l][1]\n          Z1 = v[l][2]\n          l = 1\n          X2 = v[l][0]\n          Y2 = v[l][1]\n          Z2 = v[l][2]\n          l = 2\n          X3 = v[l][0]\n          Y3 = v[l][1]\n          Z3 = v[l][2]\n          if(v.length > 3){\n            l = 3\n            X4 = v[l][0]\n            Y4 = v[l][1]\n            Z4 = v[l][2]\n            if(v.length > 4){\n              l = 4\n              X5 = v[l][0]\n              Y5 = v[l][1]\n              Z5 = v[l][2]\n            }\n          }\n          mx1 = (X1+X2)/2\n          my1 = (Y1+Y2)/2\n          mz1 = (Z1+Z2)/2\n          mx2 = (X2+X3)/2\n          my2 = (Y2+Y3)/2\n          mz2 = (Z2+Z3)/2\n          a = []\n          switch(v.length){\n            case 3:\n              mx3 = (X3+X1)/2\n              my3 = (Y3+Y1)/2\n              mz3 = (Z3+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 4:\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X1)/2\n              my4 = (Y4+Y1)/2\n              mz4 = (Z4+Z1)/2\n              cx = (X1+X2+X3+X4)/4\n              cy = (Y1+Y2+Y3+Y4)/4\n              cz = (Z1+Z2+Z3+Z4)/4\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 5:\n              cx = (X1+X2+X3+X4+X5)/5\n              cy = (Y1+Y2+Y3+Y4+Y5)/5\n              cz = (Z1+Z2+Z3+Z4+Z5)/5\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X5)/2\n              my4 = (Y4+Y5)/2\n              mz4 = (Z4+Z5)/2\n              mx5 = (X5+X1)/2\n              my5 = (Y5+Y1)/2\n              mz5 = (Z5+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              break\n          }\n        })\n      }\n      if(sphereize){\n        ip1 = sphereize\n        ip2 = 1-sphereize\n        shape = shape.map(v=>{\n          v = v.map(q=>{\n            X = q[0]\n            Y = q[1]\n            Z = q[2]\n            d = Math.hypot(X,Y,Z)\n            X /= d\n            Y /= d\n            Z /= d\n            X *= size*.75*ip1 + d*ip2\n            Y *= size*.75*ip1 + d*ip2\n            Z *= size*.75*ip1 + d*ip2\n            return [X,Y,Z]\n          })\n          return v\n        })\n      }\n      return shape\n    }\n    \n    subDividedIcosahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Icosahedron(size))\n    subDividedTetrahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Tetrahedron(size))\n    subDividedOctahedron   = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Octahedron(size))\n    subDividedCube         = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Cube(size))\n    subDividedDodecahedron = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Dodecahedron(size))\n    \n    Rn = Math.random\n    \n    LsystemRecurse = (size, splits, p1, p2, stem, theta, LsystemReduction, twistFactor) => {\n      if(size < .25) return\n      let X1 = stem[0]\n      let Y1 = stem[1]\n      let Z1 = stem[2]\n      let X2 = stem[3]\n      let Y2 = stem[4]\n      let Z2 = stem[5]\n      let p1a = Math.atan2(X2-X1,Z2-Z1)\n      let p2a = -Math.acos((Y2-Y1)/(Math.hypot(X2-X1,Y2-Y1,Z2-Z1)+.0001))+Math.PI\n      size/=LsystemReduction\n      for(let i=splits;i--;){\n        X = 0\n        Y = -size\n        Z = 0\n        R(0, theta, 0)\n        R(0, 0, Math.PI*2/splits*i+twistFactor)\n        R(0, p2a, 0)\n        R(0, 0, p1a+twistFactor)\n        X+=X2\n        Y+=Y2\n        Z+=Z2\n        let newStem = [X2, Y2, Z2, X, Y, Z]\n        Lshp = [...Lshp, newStem]\n        LsystemRecurse(size, splits, p1+Math.PI*2/splits*i+twistFactor, p2+theta, newStem, theta, LsystemReduction, twistFactor)\n      }\n    }\n    DrawLsystem = shp => {\n      shp.map(v=>{\n        x.beginPath()\n        X = v[0]\n        Y = v[1]\n        Z = v[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        X = v[3]\n        Y = v[4]\n        Z = v[5]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        lwo = Math.hypot(v[0]-v[3],v[1]-v[4],v[2]-v[5])*4\n        stroke(\'#0f82\',\'\',lwo)\n      })\n      \n    }\n    Lsystem = (size, splits, theta, LsystemReduction, twistFactor) => {\n      Lshp = []\n      stem = [0,0,0,0,-size,0]\n      Lshp = [...Lshp, stem]\n      LsystemRecurse(size, splits, 0, 0, stem, theta, LsystemReduction, twistFactor)\n      Lshp.map(v=>{\n        v[1]+=size*1.5\n        v[4]+=size*1.5\n      })\n      return Lshp\n    }\n    \n    Sphere = (ls, rw, cl) => {\n      a = []\n      ls/=1.25\n      for(j = rw; j--;){\n        for(i = cl; i--;){\n          b = []\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          a = [...a, b]\n        }\n      }\n      return a\n    }\n    \n    Torus = (rw, cl, ls1, ls2, parts=1, twists=0, part_spacing=1.5) => {\n      let ret = [], tx=0, ty=0, tz=0, prl1 = 0, p2a = 0\n      let tx1 = 0, ty1 = 0, tz1 = 0, prl2 = 0, p2b = 0, tx2 = 0, ty2 = 0, tz2 = 0\n      for(let m=parts;m--;){\n        avgs = Array(rw).fill().map(v=>[0,0,0])\n        for(j=rw;j--;)for(let i = cl;i--;){\n          if(parts>1){\n            ls3 = ls1*part_spacing\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl1 = Math.PI*2/rw*(j-1)*twists,0,0)\n            tx1 = X\n            ty1 = Y \n            tz1 = Z\n            R(0, 0, Math.PI*2/rw*(j-1))\n            ax1 = X\n            ay1 = Y\n            az1 = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl2 = Math.PI*2/rw*(j)*twists,0,0)\n            tx2 = X\n            ty2 = Y\n            tz2 = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax2 = X\n            ay2 = Y\n            az2 = Z\n            p1a = Math.atan2(ax2-ax1,az2-az1)\n            p2a = Math.PI/2+Math.acos((ay2-ay1)/(Math.hypot(ax2-ax1,ay2-ay1,az2-az1)+.001))\n\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j)*twists,0,0)\n            tx1b = X\n            ty1b = Y\n            tz1b = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax1b = X\n            ay1b = Y\n            az1b = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j+1)*twists,0,0)\n            tx2b = X\n            ty2b = Y\n            tz2b = Z\n            R(0, 0, Math.PI*2/rw*(j+1))\n            ax2b = X\n            ay2b = Y\n            az2b = Z\n            p1b = Math.atan2(ax2b-ax1b,az2b-az1b)\n            p2b = Math.PI/2+Math.acos((ay2b-ay1b)/(Math.hypot(ax2b-ax1b,ay2b-ay1b,az2b-az1b)+.001))\n          }\n          a = []\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          ret = [...ret, a]\n        }\n      }\n      return ret\n    }\n\n    G_ = 100000, iSTc = 1e4\n    ST = Array(iSTc).fill().map(v=>{\n      X = (Rn()-.5)*G_\n      Y = (Rn()-.5)*G_\n      Z = (Rn()-.5)*G_\n      return [X,Y,Z]\n    })\n    \n    burst = new Image()\n    burst.src = \"https://srmcgann.github.io/temp/burst.png\"\n    \n    starsLoaded = false, starImgs = [{loaded: false}]\n    starImgs = Array(10).fill().map((v,i) => {\n      let a = {img: new Image(), loaded: false}\n      a.img.onload = () => {\n        a.loaded = true\n        setTimeout(()=>{\n          if(starImgs.filter(v=>v.loaded).length == 10) starsLoaded = true\n        }, 0)\n      }\n      a.img.src = `https://srmcgann.github.io/stars/star${i?i:\'\'}.png`\n      return a\n    })\n    \n    showstars = true\n    \n    \n    iBc = 200\n    G = 50\n    B = []\n    base = geoSphere(0, 0, 0, iBc, G/1.5)[4].map(v=>{\n      B = [...B, v]\n    })\n    \n    iPc = 200\n    PS = Array(iPc).fill().map(v=>[-1, -1, Rn()])\n    min = 13\n    pickNewTarget = idx => {\n      idx1 = PS[idx][0]\n      idx2 = PS[idx][1]\n      if(idx1 == -1) idx2 = Rn()*B.length|0\n      idx1 = idx2\n      let X1 = B[idx1][0]\n      let Y1 = B[idx1][1]\n      let Z1 = B[idx1][2]\n      ct = 0\n      do{\n        idx2 = Rn()*B.length|0\n        good = false\n        if(idx2 != idx1){\n          let X2 = B[idx2][0]\n          let Y2 = B[idx2][1]\n          let Z2 = B[idx2][2]\n          d = Math.hypot(X2-X1,Y2-Y1,Z2-Z1)\n          if(d<min) good = true\n        }\n        ct++\n      }while(ct<1000000 && (idx1==idx2 || !good));\n      PS[idx] = [idx1, idx2, PS[idx][2]]\n    }\n    for(idx=PS.length; idx--;) pickNewTarget(idx)\n    spd = .5\n  }\n  \n  oX=0, oY=0, oZ=Math.min(60,Math.max(32,(.3+C(t/4))*100))\n  Rl=C(t/8)/2, Pt=-C(t/8)/2, Yw=S(t/4)*2\n  \n  x.globalAlpha = 1\n  x.fillStyle=\'#000C\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin = x.lineCap = \'roud\'\n  \n  if(showstars) ST.map(v=>{\n    X = v[0]\n    Y = v[1]\n    Z = v[2]\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      if((x.globalAlpha = Math.min(1,(Z/5e3)**2))>.1){\n        s = Math.min(1e3, 4e5/Z)\n        x.fillStyle = \'#ffffff04\'\n        l = Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=5\n        x.fillStyle = \'#fffa\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n    }\n  })\n\n  x.globalAlpha = 1\n\n  if(oZ>=70){\n    X = Y = Z = 0\n    R(Rl, Pt, Yw, 1)\n    if(Z>0){\n      l = Q()\n      s = Math.min(1e4, 5e4/Z * (1+S(t*40)/20))\n      x.drawImage(burst, l[0]-s/2,l[1]-s/2,s,s)\n    }\n  }\n  \n  B.map((v,i) => {\n    X1 = X = v[0]\n    Y1 = Y = v[1]\n    Z1 = Z = v[2]\n    R(Rl, Pt, Yw, 1)\n    if(Z>0){\n      l = Q()\n      s = Math.min(1e3, 3000/Z)\n      x.fillStyle = \'#4400ff10\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      s/=3\n      x.fillStyle = \'#0088ff20\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      s/=3\n      x.fillStyle = \'#ffffffff\'\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      \n      \n      /*X = X1\n      Y = Y1\n      Z = Z1\n      R(Rl,Pt,Yw,0)\n      X += 1\n      Y -= .5\n      R(0,0,0,1)\n      l = Q()\n      x.font = (1500/Z)+\'px courier\'\n      x.fillStyle = \'#fff\'\n      x.fillText(i,...l) */\n    }\n  })\n  \n  PS.map((P, idx)=>{\n    x.beginPath()\n    X1 = X = B[P[0]][0]\n    Y1 = Y = B[P[0]][1]\n    Z1 = Z = B[P[0]][2]\n    R(Rl,Pt,Yw,1)\n    if(Z>0) x.lineTo(...Q())\n    X2 = X = B[P[1]][0]\n    Y2 = Y = B[P[1]][1]\n    Z2 = Z = B[P[1]][2]\n    R(Rl,Pt,Yw,1)\n    if(Z>0) x.lineTo(...Q())\n    stroke(\'#f004\',\'\',2,true)\n    lineRes = 1.5\n    d_ = Math.hypot(X2-X1,Y2-Y1,Z2-Z1)\n    for(l=m=1+d_/lineRes|0;m--;){\n      X = X1 + (X2-X1)*lineRes/d_*m\n      Y = Y1 + (Y2-Y1)*lineRes/d_*m\n      Z = Z1 + (Z2-Z1)*lineRes/d_*m\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        l = Q()\n        s = Math.min(1e3, 1000/Z)\n        x.drawImage(starImgs[3].img,l[0]-s/2/1.06,l[1]-s/2/1.06,s,s)\n      }\n    }\n    \n    X = X1 + (X2 - X1) * P[2]\n    Y = Y1 + (Y2 - Y1) * P[2]\n    Z = Z1 + (Z2 - Z1) * P[2]\n    P[2] += spd / d_\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      l = Q()\n      s = Math.min(1e3, 4000/Z)\n      x.drawImage(starImgs[6].img,l[0]-s/2/1.06,l[1]-s/2/1.06,s,s)\n    }\n    \n    if(P[2]>=1){\n      P[2] = 0\n      pickNewTarget(idx)\n    }\n  })\n  \n  if(oZ<70){\n    X = Y = Z = 0\n    R(Rl, Pt, Yw, 1)\n    if(Z>0){\n      l = Q()\n      s = Math.min(1e4, 5e4/Z * (1+S(t*40)/20))\n      x.drawImage(burst, l[0]-s/2,l[1]-s/2,s,s)\n    }\n  }\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  overflow: hidden;\n}\n#c{\n  background:#000;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'strange system', 145, 'whitehot robot', '2023-09-18 20:16:13', '[600728]', 22, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600730, '', 'c = document.querySelector(\'#c\')\nc.width = 1920\nc.height = 1080\nx = c.getContext(\'2d\')\nC = Math.cos\nS = Math.sin\nt = 0\nT = Math.tan\n\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height =     c.clientWidth/1.77777778 + \'px\',0)\n    }\n  },0)\n}\nrsz()\n\nasync function Draw(){\n  oX=oY=oZ=0\n  if(!t){\n    R=R2=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    \n    Rn = Math.random\n    async function loadOBJ(url, scale, tx, ty, tz, rl, pt, yw) {\n      let res\n      await fetch(url, res => res).then(data=>data.text()).then(data=>{\n        a=[]\n        data.split(\"\\nv \").map(v=>{\n          a=[...a, v.split(\"\\n\")[0]]\n        })\n        a=a.filter((v,i)=>i).map(v=>[...v.split(\' \').map(n=>(+n.replace(\"\\n\", \'\')))])\n        ax=ay=az=0\n        a.map(v=>{\n          v[1]*=-1\n          ax+=v[0]\n          ay+=v[1]\n          az+=v[2]\n        })\n        ax/=a.length\n        ay/=a.length\n        az/=a.length\n        a.map(v=>{\n          X=(v[0]-ax)*scale\n          Y=(v[1]-ay)*scale\n          Z=(v[2]-az)*scale\n          R2(rl,pt,yw,0)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n        })\n        maxY=-6e6\n        a.map(v=>{\n          if(v[1]>maxY)maxY=v[1]\n        })\n        a.map(v=>{\n          v[1]-=maxY-oY\n          v[0]+=tx\n          v[1]+=ty\n          v[2]+=tz\n        })\n\n        b=[]\n        data.split(\"\\nf \").map(v=>{\n          b=[...b, v.split(\"\\n\")[0]]\n        })\n        b.shift()\n        b=b.map(v=>v.split(\' \'))\n        b=b.map(v=>{\n          v=v.map(q=>{\n            return +q.split(\'/\')[0]\n          })\n          v=v.filter(q=>q)\n          return v\n        })\n        \n        res=[]\n        b.map(v=>{\n          e=[]\n          v.map(q=>{\n            e=[...e, a[q-1]]\n          })\n          e = e.filter(q=>q)\n          res=[...res, e]\n        })\n      })\n      return res\n    }\n\n    geoSphere = (mx, my, mz, iBc, size) => {\n      let collapse=0\n      let B=Array(iBc).fill().map(v=>{\n        X = Rn()-.5\n        Y = Rn()-.5\n        Z = Rn()-.5\n        return  [X,Y,Z]\n      })\n      for(let m=200;m--;){\n        B.map((v,i)=>{\n          X = v[0]\n          Y = v[1]\n          Z = v[2]\n          B.map((q,j)=>{\n            if(j!=i){\n              X2=q[0]\n              Y2=q[1]\n              Z2=q[2]\n              d=1+(Math.hypot(X-X2,Y-Y2,Z-Z2)*(3+iBc/40)*3)**4\n              X+=(X-X2)*99/d\n              Y+=(Y-Y2)*99/d\n              Z+=(Z-Z2)*99/d\n            }\n          })\n          d=Math.hypot(X,Y,Z)\n          v[0]=X/d\n          v[1]=Y/d\n          v[2]=Z/d\n          if(collapse){\n            d=25+Math.hypot(X,Y,Z)\n            v[0]=(X-X/d)/1.1\n            v[1]=(Y-Y/d)/1.1         \n            v[2]=(Z-Z/d)/1.1\n          }\n        })\n      }\n      mind = 6e6\n      B.map((v,i)=>{\n        X1 = v[0]\n        Y1 = v[1]\n        Z1 = v[2]\n        B.map((q,j)=>{\n          X2 = q[0]\n          Y2 = q[1]\n          Z2 = q[2]\n          if(i!=j){\n            d = Math.hypot(a=X1-X2, b=Y1-Y2, e=Z1-Z2)\n            if(d<mind) mind = d\n          }\n        })\n      })\n      a = []\n      B.map((v,i)=>{\n        X1 = v[0]\n        Y1 = v[1]\n        Z1 = v[2]\n        B.map((q,j)=>{\n          X2 = q[0]\n          Y2 = q[1]\n          Z2 = q[2]\n          if(i!=j){\n            d = Math.hypot(X1-X2, Y1-Y2, Z1-Z2)\n            if(d<mind*2){\n              if(!a.filter(q=>q[0]==X2&&q[1]==Y2&&q[2]==Z2&&q[3]==X1&&q[4]==Y1&&q[5]==Z1).length) a = [...a, [X1*size,Y1*size,Z1*size,X2*size,Y2*size,Z2*size]]\n            }\n          }\n        })\n      })\n      B.map(v=>{\n        v[0]*=size\n        v[1]*=size\n        v[2]*=size\n        v[0]+=mx\n        v[1]+=my\n        v[2]+=mz\n      })\n      return [mx, my, mz, size, B, a]\n    }\n\n    lineFaceI = (X1, Y1, Z1, X2, Y2, Z2, facet, autoFlipNormals=false, showNormals=false) => {\n      let X_, Y_, Z_, d, m, l_,K,J,L,p\n      let I_=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n      let Q_=()=>[c.width/2+X_/Z_*600,c.height/2+Y_/Z_*600]\n      let R_ = (Rl,Pt,Yw,m)=>{\n        let M=Math, A=M.atan2, H=M.hypot\n        X_=S(p=A(X_,Y_)+Rl)*(d=H(X_,Y_)),Y_=C(p)*d,X_=S(p=A(X_,Z_)+Yw)*(d=H(X_,Z_)),Z_=C(p)*d,Y_=S(p=A(Y_,Z_)+Pt)*(d=H(Y_,Z_)),Z_=C(p)*d\n        if(m){ X_+=oX,Y_+=oY,Z_+=oZ }\n      }\n      let rotSwitch = m =>{\n        switch(m){\n          case 0: R_(0,0,Math.PI/2); break\n          case 1: R_(0,Math.PI/2,0); break\n          case 2: R_(Math.PI/2,0,Math.PI/2); break\n        }        \n      }\n      let ax = 0, ay = 0, az = 0\n      facet.map(q_=>{ ax += q_[0], ay += q_[1], az += q_[2] })\n      ax /= facet.length, ay /= facet.length, az /= facet.length\n      let b1 = facet[2][0]-facet[1][0], b2 = facet[2][1]-facet[1][1], b3 = facet[2][2]-facet[1][2]\n      let c1 = facet[1][0]-facet[0][0], c2 = facet[1][1]-facet[0][1], c3 = facet[1][2]-facet[0][2]\n      let crs = [b2*c3-b3*c2,b3*c1-b1*c3,b1*c2-b2*c1]\n      d = Math.hypot(...crs)+.001\n      let nls = 1 //normal line length\n      crs = crs.map(q=>q/d*nls)\n      let X1_ = ax, Y1_ = ay, Z1_ = az\n      let flip = 1\n      if(autoFlipNormals){\n        let d1_ = Math.hypot(X1_-X1,Y1_-Y1,Z1_-Z1)\n        let d2_ = Math.hypot(X1-(ax + crs[0]/99),Y1-(ay + crs[1]/99),Z1-(az + crs[2]/99))\n        flip = d2_>d1_?-1:1\n      }\n      let X2_ = ax + (crs[0]*=flip), Y2_ = ay + (crs[1]*=flip), Z2_ = az + (crs[2]*=flip)\n      if(showNormals){\n        x.beginPath()\n        X_ = X1_, Y_ = Y1_, Z_ = Z1_\n        R_(Rl,Pt,Yw,1)\n        if(Z_>0) x.lineTo(...Q_())\n        X_ = X2_, Y_ = Y2_, Z_ = Z2_\n        R_(Rl,Pt,Yw,1)\n        if(Z_>0) x.lineTo(...Q_())\n        x.lineWidth = 5\n        x.strokeStyle=\'#f004\'\n        x.stroke()\n      }\n      \n      let p1_ = Math.atan2(X2_-X1_,Z2_-Z1_)\n      let p2_ = -(Math.acos((Y2_-Y1_)/(Math.hypot(X2_-X1_,Y2_-Y1_,Z2_-Z1_)+.001))+Math.PI/2)\n      let isc = false, iscs = [false,false,false]\n      X_ = X1, Y_ = Y1, Z_ = Z1\n      R_(0,-p2_,-p1_)\n      let rx_ = X_, ry_ = Y_, rz_ = Z_\n      for(let m=3;m--;){\n        if(isc === false){\n          X_ = rx_, Y_ = ry_, Z_ = rz_\n          rotSwitch(m)\n          X1_ = X_, Y1_ = Y_, Z1_ = Z_ = 5, X_ = X2, Y_ = Y2, Z_ = Z2\n          R_(0,-p2_,-p1_)\n          rotSwitch(m)\n          X2_ = X_, Y2_ = Y_, Z2_ = Z_\n          facet.map((q_,j_)=>{\n            if(isc === false){\n              let l = j_\n              X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n              R_(0,-p2_,-p1_)\n              rotSwitch(m)\n              let X3_=X_, Y3_=Y_, Z3_=Z_\n              l = (j_+1)%facet.length\n              X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n              R_(0,-p2_,-p1_)\n              rotSwitch(m)\n              let X4_ = X_, Y4_ = Y_, Z4_ = Z_\n              if(l_=I_(X1_,Y1_,X2_,Y2_,X3_,Y3_,X4_,Y4_)) iscs[m] = l_\n            }\n          })\n        }\n      }\n      if(iscs.filter(v=>v!==false).length==3){\n        let iscx = iscs[1][0], iscy = iscs[0][1], iscz = iscs[0][0]\n        let pointInPoly = true\n        ax=0, ay=0, az=0\n        facet.map((q_, j_)=>{ ax+=q_[0], ay+=q_[1], az+=q_[2] })\n        ax/=facet.length, ay/=facet.length, az/=facet.length\n        X_ = ax, Y_ = ay, Z_ = az\n        R_(0,-p2_,-p1_)\n        X1_ = X_, Y1_ = Y_, Z1_ = Z_\n        X2_ = iscx, Y2_ = iscy, Z2_ = iscz\n        facet.map((q_,j_)=>{\n          if(pointInPoly){\n            let l = j_\n            X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n            R_(0,-p2_,-p1_)\n            let X3_ = X_, Y3_ = Y_, Z3_ = Z_\n            l = (j_+1)%facet.length\n            X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n            R_(0,-p2_,-p1_)\n            let X4_ = X_, Y4_ = Y_, Z4_ = Z_\n            if(I_(X1_,Y1_,X2_,Y2_,X3_,Y3_,X4_,Y4_)) pointInPoly = false\n          }\n        })\n        if(pointInPoly){\n          X_ = iscx, Y_ = iscy, Z_ = iscz\n          R_(0,p2_,0)\n          R_(0,0,p1_)\n          isc = [[X_,Y_,Z_], [crs[0],crs[1],crs[2]]]\n        }\n      }\n      return isc\n    }\n    \n    TruncatedOctahedron = ls => {\n      let shp = [], a = []\n      mind = 6e6\n      for(let i=6;i--;){\n        X = S(p=Math.PI*2/6*i+Math.PI/6)*ls\n        Y = C(p)*ls\n        Z = 0\n        if(Y<mind) mind = Y\n        a = [...a, [X, Y, Z]]\n      }\n      let theta = .6154797086703867\n      a.map(v=>{\n        X = v[0]\n        Y = v[1] - mind\n        Z = v[2]\n        R(0,theta,0)\n        v[0] = X\n        v[1] = Y\n        v[2] = Z+1.5\n      })\n      b = JSON.parse(JSON.stringify(a)).map(v=>{\n        v[1] *= -1\n        return v\n      })\n      shp = [...shp, a, b]\n      e = JSON.parse(JSON.stringify(shp)).map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n        return v\n      })\n      shp = [...shp, ...e]\n      e = JSON.parse(JSON.stringify(shp)).map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n        return v\n      })\n      shp = [...shp, ...e]\n\n      coords = [\n        [[3,1],[4,3],[4,4],[3,2]],\n        [[3,4],[3,3],[2,4],[6,2]],\n        [[1,4],[0,3],[0,4],[4,2]],\n        [[1,1],[1,2],[6,4],[7,3]],\n        [[3,5],[7,5],[1,5],[3,0]],\n        [[2,5],[6,5],[0,5],[4,5]]\n      ]\n      a = []\n      coords.map(v=>{\n        b = []\n        v.map(q=>{\n          X = shp[q[0]][q[1]][0]\n          Y = shp[q[0]][q[1]][1]\n          Z = shp[q[0]][q[1]][2]\n          b = [...b, [X,Y,Z]]\n        })\n        a = [...a, b]\n      })\n      shp = [...shp, ...a]\n      return shp.map(v=>{\n        v.map(q=>{\n          q[0]/=3\n          q[1]/=3\n          q[2]/=3\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n        return v\n      })\n    }\n    \n    Cylinder = (rw,cl,ls1,ls2) => {\n      let a = []\n      for(let i=rw;i--;){\n        let b = []\n        for(let j=cl;j--;){\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n        }\n        //a = [...a, b]\n        for(let j=cl;j--;){\n          b = []\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(j+1)) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(j+1)) * ls1\n          Y = (1/rw*(i+1)-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*(i+1)-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          a = [...a, b]\n        }\n      }\n      b = []\n      for(let j=cl;j--;){\n        X = S(p=Math.PI*2/cl*j) * ls1\n        Y = ls2/2\n        Z = C(p) * ls1\n        b = [...b, [X,Y,Z]]\n      }\n      //a = [...a, b]\n      return a\n    }\n\n    Tetrahedron = size => {\n      ret = []\n      a = []\n      let h = size/1.4142/1.25\n      for(i=3;i--;){\n        X = S(p=Math.PI*2/3*i) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n      }\n      ret = [...ret, a]\n      for(j=3;j--;){\n        a = []\n        X = 0\n        Y = 0\n        Z = -h\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/3*j) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/3*(j+1)) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      ax=ay=az=ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax\n          q[1]-=ay\n          q[2]-=az\n        })\n      })\n      return ret\n    }\n\n    Cube = size => {\n      for(CB=[],j=6;j--;CB=[...CB,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?size/1.5:-size/1.5),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      return CB\n    }\n    \n    Octahedron = size => {\n      ret = []\n      let h = size/1.25\n      for(j=8;j--;){\n        a = []\n        X = 0\n        Y = 0\n        Z = h * (j<4?-1:1)\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*j) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*(j+1)) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      return ret      \n    }\n    \n    Dodecahedron = size => {\n      ret = []\n      a = []\n      mind = -6e6\n      for(i=5;i--;){\n        X=S(p=Math.PI*2/5*i + Math.PI/5)\n        Y=C(p)\n        Z=0\n        if(Y>mind) mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a.map(v=>{\n        X = v[0]\n        Y = v[1]-=mind\n        Z = v[2]\n        R(0, .553573, 0)\n        v[0] = X\n        v[1] = Y\n        v[2] = Z\n      })\n      b = JSON.parse(JSON.stringify(a))\n      b.map(v=>{\n        v[1] *= -1\n      })\n      ret = [...ret, a, b]\n      mind = -6e6\n      ret.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          if(Z>mind)mind = Z\n        })\n      })\n      d1=Math.hypot(ret[0][0][0]-ret[0][1][0],ret[0][0][1]-ret[0][1][1],ret[0][0][2]-ret[0][1][2])\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]-=mind+d1/2\n        })\n      })\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          q[2]*=-1\n        })\n      })\n      ret = [...ret, ...b]\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(0,Math.PI/2,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      e = JSON.parse(JSON.stringify(ret))\n      e.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(Math.PI/2,0,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      ret = [...ret, ...b, ...e]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0] *= size/2\n          q[1] *= size/2\n          q[2] *= size/2\n        })\n      })\n      return ret\n    }\n    \n    Icosahedron = size => {\n      ret = []\n      B = [\n        [[0,3],[1,0],[2,2]],\n        [[0,3],[1,0],[1,3]],\n        [[0,3],[2,3],[1,3]],\n        [[0,2],[2,1],[1,0]],\n        [[0,2],[1,3],[1,0]],\n        [[0,2],[1,3],[2,0]],\n        [[0,3],[2,2],[0,0]],\n        [[1,0],[2,2],[2,1]],\n        [[1,1],[2,2],[2,1]],\n        [[1,1],[2,2],[0,0]],\n        [[1,1],[2,1],[0,1]],\n        [[0,2],[2,1],[0,1]],\n        [[2,0],[1,2],[2,3]],\n        [[0,0],[0,3],[2,3]],\n        [[1,3],[2,0],[2,3]],\n        [[2,3],[0,0],[1,2]],\n        [[1,2],[2,0],[0,1]],\n        [[0,0],[1,2],[1,1]],\n        [[0,1],[1,2],[1,1]],\n        [[0,2],[2,0],[0,1]],\n      ]\n      for(p=[1,1],i=38;i--;)p=[...p,p[l=p.length-1]+p[l-1]]\n      phi = p[l]/p[l-1]\n      a = [\n        [-phi,-1,0],\n        [phi,-1,0],\n        [phi,1,0],\n        [-phi,1,0],\n      ]\n      for(j=3;j--;ret=[...ret, b])for(b=[],i=4;i--;) b = [...b, [a[i][j],a[i][(j+1)%3],a[i][(j+2)%3]]]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]*=size/2.25\n          q[1]*=size/2.25\n          q[2]*=size/2.25\n        })\n      })\n      cp = JSON.parse(JSON.stringify(ret))\n      out=[]\n      a = []\n      B.map(v=>{\n        idx1a = v[0][0]\n        idx2a = v[1][0]\n        idx3a = v[2][0]\n        idx1b = v[0][1]\n        idx2b = v[1][1]\n        idx3b = v[2][1]\n        a = [...a, [cp[idx1a][idx1b],cp[idx2a][idx2b],cp[idx3a][idx3b]]]\n      })\n      out = [...out, ...a]\n      return out\n    }\n    \n    stroke = (scol, fcol, lwo=1, od=true, oga=1) => {\n      if(scol){\n        //x.closePath()\n        if(od) x.globalAlpha = .2*oga\n        x.strokeStyle = scol\n        x.lineWidth = Math.min(1000,100*lwo/Z)\n        if(od) x.stroke()\n        x.lineWidth /= 4\n        x.globalAlpha = 1*oga\n        x.stroke()\n      }\n      if(fcol){\n        x.globalAlpha = 1*oga\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n    \n    subbed = (subs, size, sphereize, shape) => {\n      for(let m=subs; m--;){\n        base = shape\n        shape = []\n        base.map(v=>{\n          l = 0\n          X1 = v[l][0]\n          Y1 = v[l][1]\n          Z1 = v[l][2]\n          l = 1\n          X2 = v[l][0]\n          Y2 = v[l][1]\n          Z2 = v[l][2]\n          l = 2\n          X3 = v[l][0]\n          Y3 = v[l][1]\n          Z3 = v[l][2]\n          if(v.length > 3){\n            l = 3\n            X4 = v[l][0]\n            Y4 = v[l][1]\n            Z4 = v[l][2]\n            if(v.length > 4){\n              l = 4\n              X5 = v[l][0]\n              Y5 = v[l][1]\n              Z5 = v[l][2]\n            }\n          }\n          mx1 = (X1+X2)/2\n          my1 = (Y1+Y2)/2\n          mz1 = (Z1+Z2)/2\n          mx2 = (X2+X3)/2\n          my2 = (Y2+Y3)/2\n          mz2 = (Z2+Z3)/2\n          a = []\n          switch(v.length){\n            case 3:\n              mx3 = (X3+X1)/2\n              my3 = (Y3+Y1)/2\n              mz3 = (Z3+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 4:\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X1)/2\n              my4 = (Y4+Y1)/2\n              mz4 = (Z4+Z1)/2\n              cx = (X1+X2+X3+X4)/4\n              cy = (Y1+Y2+Y3+Y4)/4\n              cz = (Z1+Z2+Z3+Z4)/4\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 5:\n              cx = (X1+X2+X3+X4+X5)/5\n              cy = (Y1+Y2+Y3+Y4+Y5)/5\n              cz = (Z1+Z2+Z3+Z4+Z5)/5\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X5)/2\n              my4 = (Y4+Y5)/2\n              mz4 = (Z4+Z5)/2\n              mx5 = (X5+X1)/2\n              my5 = (Y5+Y1)/2\n              mz5 = (Z5+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              break\n          }\n        })\n      }\n      if(sphereize){\n        ip1 = sphereize\n        ip2 = 1-sphereize\n        shape = shape.map(v=>{\n          v = v.map(q=>{\n            X = q[0]\n            Y = q[1]\n            Z = q[2]\n            d = Math.hypot(X,Y,Z)\n            X /= d\n            Y /= d\n            Z /= d\n            X *= size*.75*ip1 + d*ip2\n            Y *= size*.75*ip1 + d*ip2\n            Z *= size*.75*ip1 + d*ip2\n            return [X,Y,Z]\n          })\n          return v\n        })\n      }\n      return shape\n    }\n    \n    subDividedIcosahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Icosahedron(size))\n    subDividedTetrahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Tetrahedron(size))\n    subDividedOctahedron   = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Octahedron(size))\n    subDividedCube         = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Cube(size))\n    subDividedDodecahedron = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Dodecahedron(size))\n    \n    Rn = Math.random\n    \n    LsystemRecurse = (size, splits, p1, p2, stem, theta, LsystemReduction, twistFactor) => {\n      if(size < .25) return\n      let X1 = stem[0]\n      let Y1 = stem[1]\n      let Z1 = stem[2]\n      let X2 = stem[3]\n      let Y2 = stem[4]\n      let Z2 = stem[5]\n      let p1a = Math.atan2(X2-X1,Z2-Z1)\n      let p2a = -Math.acos((Y2-Y1)/(Math.hypot(X2-X1,Y2-Y1,Z2-Z1)+.0001))+Math.PI\n      size/=LsystemReduction\n      for(let i=splits;i--;){\n        X = 0\n        Y = -size\n        Z = 0\n        R(0, theta, 0)\n        R(0, 0, Math.PI*2/splits*i+twistFactor)\n        R(0, p2a, 0)\n        R(0, 0, p1a+twistFactor)\n        X+=X2\n        Y+=Y2\n        Z+=Z2\n        let newStem = [X2, Y2, Z2, X, Y, Z]\n        Lshp = [...Lshp, newStem]\n        LsystemRecurse(size, splits, p1+Math.PI*2/splits*i+twistFactor, p2+theta, newStem, theta, LsystemReduction, twistFactor)\n      }\n    }\n    DrawLsystem = shp => {\n      shp.map(v=>{\n        x.beginPath()\n        X = v[0]\n        Y = v[1]\n        Z = v[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        X = v[3]\n        Y = v[4]\n        Z = v[5]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        lwo = Math.hypot(v[0]-v[3],v[1]-v[4],v[2]-v[5])*4\n        stroke(\'#0f82\',\'\',lwo)\n      })\n      \n    }\n    Lsystem = (size, splits, theta, LsystemReduction, twistFactor) => {\n      Lshp = []\n      stem = [0,0,0,0,-size,0]\n      Lshp = [...Lshp, stem]\n      LsystemRecurse(size, splits, 0, 0, stem, theta, LsystemReduction, twistFactor)\n      Lshp.map(v=>{\n        v[1]+=size*1.5\n        v[4]+=size*1.5\n      })\n      return Lshp\n    }\n    \n    Sphere = (ls, rw, cl) => {\n      a = []\n      ls/=1.25\n      for(j = rw; j--;){\n        for(i = cl; i--;){\n          b = []\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          a = [...a, b]\n        }\n      }\n      return a\n    }\n    \n    Torus = (rw, cl, ls1, ls2, parts=1, twists=0, part_spacing=1.5) => {\n      let ret = [], tx=0, ty=0, tz=0\n      for(let m=parts;m--;){\n        avgs = Array(rw).fill().map(v=>[0,0,0])\n        for(j=rw;j--;)for(let i = cl;i--;){\n          if(parts>1){\n            ls3 = ls1*part_spacing\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl1 = Math.PI*2/rw*(j-1)*twists,0,0)\n            tx1 = X\n            ty1 = Y \n            tz1 = Z\n            R(0, 0, Math.PI*2/rw*(j-1))\n            ax1 = X\n            ay1 = Y\n            az1 = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl2 = Math.PI*2/rw*(j)*twists,0,0)\n            tx2 = X\n            ty2 = Y\n            tz2 = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax2 = X\n            ay2 = Y\n            az2 = Z\n            p1a = Math.atan2(ax2-ax1,az2-az1)\n            p2a = Math.PI/2+Math.acos((ay2-ay1)/(Math.hypot(ax2-ax1,ay2-ay1,az2-az1)+.001))\n\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j)*twists,0,0)\n            tx1b = X\n            ty1b = Y\n            tz1b = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax1b = X\n            ay1b = Y\n            az1b = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j+1)*twists,0,0)\n            tx2b = X\n            ty2b = Y\n            tz2b = Z\n            R(0, 0, Math.PI*2/rw*(j+1))\n            ax2b = X\n            ay2b = Y\n            az2b = Z\n            p1b = Math.atan2(ax2b-ax1b,az2b-az1b)\n            p2b = Math.PI/2+Math.acos((ay2b-ay1b)/(Math.hypot(ax2b-ax1b,ay2b-ay1b,az2b-az1b)+.001))\n          }\n          a = []\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          ret = [...ret, a]\n        }\n      }\n      return ret\n    }\n\n    G_ = 100000, iSTc = 1e4\n    ST = Array(iSTc).fill().map(v=>{\n      X = (Rn()-.5)*G_\n      Y = (Rn()-.5)*G_\n      Z = (Rn()-.5)*G_\n      return [X,Y,Z]\n    })\n    \n    burst = new Image()\n    burst.src = \"https://srmcgann.github.io/temp/burst.png\"\n    \n    starsLoaded = false, starImgs = [{loaded: false}]\n    starImgs = Array(10).fill().map((v,i) => {\n      let a = {img: new Image(), loaded: false}\n      a.img.onload = () => {\n        a.loaded = true\n        setTimeout(()=>{\n          if(starImgs.filter(v=>v.loaded).length == 10) starsLoaded = true\n        }, 0)\n      }\n      a.img.src = `https://srmcgann.github.io/temp/stars/star${i?i:\'\'}.png`\n      return a\n    })\n    \n    starsLoaded = false, starImgs = [{loaded: false}]\n    starImgs = Array(10).fill().map((v,i) => {\n      let a = {img: new Image(), loaded: false}\n      a.img.onload = () => {\n        a.loaded = true\n        setTimeout(()=>{\n          if(starImgs.filter(v=>v.loaded).length == 10) starsLoaded = true\n        }, 0)\n      }\n      a.img.src = `https://srmcgann.github.io/temp/stars/star${i?i:\'\'}.png`\n      return a\n    })\n    \n    cl = 6\n    rw = 6\n    br = 3\n    ocl=orw=obr=-1\n    genMaze = (cl,rw,br) => {\n      if(cl==ocl&&rw==orw&&obr==br) return\n      ocl = cl\n      orw = rw\n      obr = br\n      start = dest = 0\n      sp = 1.75\n      baseCube = Cube(sp*1.06)\n      maze = []\n      Array(cl*rw*br).fill().map((v, i) => {\n        tx = ((i%cl)-cl/2+.5)*sp\n        ty = (((i/cl|0)%rw)-rw/2+.5)*sp\n        tz = ((i/cl/rw|0)-br/2+.5)*sp\n        if(Math.hypot(tx,ty,tz)<(rad=Math.hypot(cl*sp,rw*sp,br*sp)/3.75)) maze = [...maze, [ tx, ty, tz, JSON.parse(JSON.stringify(baseCube))]]\n      })\n      maze.map((v,i)=>{\n        X1 = v[0]\n        Y1 = v[1]\n        Z1 = v[2]\n        a = []\n        maze.map((q,j)=>{\n          if(j!=i){\n            X2 = q[0]\n            Y2 = q[1]\n            Z2 = q[2]\n            d = Math.hypot(X2-X1,Y2-Y1,Z2-Z1)\n            if(d<sp*1.2){\n              a = [...a, j]\n            }\n          }\n        })\n        v[4] = a\n        v[5] = false\n        v[6] = 0\n        v[7] = [] // forward path\n        v[8] = [] // reverse path\n      })\n      \n      oidx = -1\n      idx1 = maze.length * Rn() |0\n      let ct2 = 0\n      do{\n        let ct_=0\n        do{\n          cell1 = maze[idx1]\n          cell1[5] = true\n          cell1[6] = \'c1\'\n          let ct=0\n          good = false\n          do{\n            idx2 = cell1[4][cell1[4].length*Rn()|0]\n            ct++\n            if(oidx == -1 || (idx2 != oidx &&\n                              !maze[idx2][7].filter(v=>v==idx1).length  &&\n                              !maze[idx2][8].filter(v=>v==idx1).length &&\n                              !maze[idx1][7].filter(v=>v==idx2).length &&\n                              !maze[idx1][8].filter(v=>v==idx2).length\n                             )) good = true\n          }while(!good  && ct<10);\n          if(good){\n            cell2 = maze[idx2]\n            cell1[7] = [...cell1[7], idx2]\n            cell2[8] = [...cell2[8], idx1]\n            cell2[5] = true\n            cell2[6] = \'c2\'\n            dx = Math.abs(cell2[0] - cell1[0])\n            dy = Math.abs(cell2[1] - cell1[1])\n            dz = Math.abs(cell2[2] - cell1[2])\n            if(dx > dy && dx > dz){\n              maze[idx1][3] = maze[idx1][3].filter((q, j) => {\n                if((cell2[0] < cell1[0])){\n                  return j!=0\n                }else{\n                  return j!=3\n                }\n              })\n              maze[idx2][3] = maze[idx2][3].filter((q, j) => {\n                if((cell2[0] < cell1[0])){\n                  return j!=3\n                }else{\n                  return j!=0\n                }\n              })\n              cell2[5] = cell1[5] = \'#f004\'\n            }\n            if(dy > dx && dy > dz){\n              maze[idx1][3] = maze[idx1][3].filter((q, j) => {\n                if((cell2[1] < cell1[1])){\n                  return j!=1\n                }else{\n                  return j!=4\n                }\n              })\n              maze[idx2][3] = maze[idx2][3].filter((q, j) => {\n                if((cell2[1] < cell1[1])){\n                  return j!=4\n                }else{\n                  return j!=1\n                }\n              })\n              cell2[5] = cell1[5] = \'#ff04\'\n            }\n            if(dz > dy && dz > dx){\n              maze[idx1][3] = maze[idx1][3].filter((q, j) => {\n                if((cell2[2] < cell1[2])){\n                  return j!=2\n                }else{\n                  return j!=5\n                }\n              })\n              maze[idx2][3] = maze[idx2][3].filter((q, j) => {\n                if((cell2[2] < cell1[2])){\n                  return j!=5\n                }else{\n                  return j!=2\n                }\n              })\n              cell2[5] = cell1[5] = \'#04f4\'\n            }\n            oidx = idx1\n            idx1 = idx2\n          }else{\n            idx1 = Rn()*maze.length|0\n            if(!(maze[idx1][7].length || maze[idx1][8].length)) oidx=-1\n          }\n          ct_++\n        }while(ct_<8);\n        idx1 = Rn()*maze.length|0\n        if(!(maze[idx1][7].length || maze[idx1][8].length)) oidx=-1\n        ct2++\n      }while(ct2<1200 && maze.filter(v=>v[7].length && v[8].length).length != maze.length);\n    }\n    genMaze(cl,rw,br)\n    \n    md=-6e6\n    drawPath1 = (idx1, depth) => {\n      if(memo1.indexOf(idx1) != -1) return\n      if(depth>md)md=depth\n      memo1 = [...memo1, idx1]\n      maze[idx1][7].map(q=>{\n        x.beginPath()\n        X = maze[idx1][0]\n        Y = maze[idx1][1]\n        Z = maze[idx1][2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        idx2 = q\n        X = maze[idx2][0]\n        Y = maze[idx2][1]\n        Z = maze[idx2][2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        if(depth==((t*400%md)|0))stroke(\'#f00\',\'\',8,true)\n        drawPath1(idx2, depth+1)\n      })\n    }\n\n    drawPath2 = (idx1, depth) => {\n      if(memo2.indexOf(idx1) != -1) return\n      if(depth>md)md=depth\n      memo2 = [...memo2, idx1]\n      maze[idx1][7].map(q=>{\n        x.beginPath()\n        X = maze[idx1][0]\n        Y = maze[idx1][1]\n        Z = maze[idx1][2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        idx2 = q\n        X = maze[idx2][0]\n        Y = maze[idx2][1]\n        Z = maze[idx2][2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        if(depth<((t*400%md)|0))stroke(\'#ffffff16\',\'\',4,false)\n        //stroke(\'#40f2\',\'\',1,true)\n        drawPath2(idx2, depth+1)\n      })\n    }\n    \n    recursePath = (start, dest, depth) => {\n      if(start == dest){\n        path = [...path, dest]\n        return true\n      }\n      if(memo3.indexOf(start) != -1) return false\n      memo3 = [...memo3, start]\n      let ret = false\n      maze[start][8].map(q=>{\n        if(!ret){\n          let idx2 = q\n          if(recursePath(idx2, dest, depth+1)){\n            path = [...path, q]\n            ret = true\n          }\n        }\n      })\n      return ret\n    }    \n    \n    showStars = true\n    \n    iBv = 0    \n    mazeFreq = 5\n  }\n  oX=0, oY=0, oZ=Math.min(32, Math.max(25, (.3-C(t/3))*250))\n  Rl=C(t/2)/4, Pt=-C(t/3)/2, Yw = Math.min(Math.PI*.5, Math.max(-Math.PI, (.3+C(t/2-.5))*6))+Math.PI/2\n  \n  x.globalAlpha = 1\n  x.fillStyle=\'#000C\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin = x.lineCap = \'roud\'\n  \n  lr = Math.min(25,Math.max(5,(.3+C(t/2.25))*100))|0\n  if(!((t*60|0)%mazeFreq)) genMaze(cl=lr,rw=lr,br=Math.min(40,Math.max(3,(-.3-C(t/2.25))*250))|0)\n                                   \n  B = Array(2).fill().map((v, i)=>{\n    p_ = C(t)*Math.PI*3\n    X = S(p=Math.PI/2+Math.min(Math.PI,Math.max(-Math.PI,p_))+(i?Math.PI:0))*lr/2\n    Y = C(p)*lr/2\n    Z = 0\n    return [X, Y, Z, 0, 0, 0, 0, 0, 0]\n  })\n\n  if(showStars)ST.map(v=>{\n    X = v[0]\n    Y = v[1]\n    Z = v[2]\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      if((x.globalAlpha = Math.min(1,(Z/5e3)**2))>.1){\n        s = Math.min(1e3, 4e5/Z)\n        x.fillStyle = \'#ffffff04\'\n        l = Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=5\n        x.fillStyle = \'#fffa\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n    }\n  })\n  x.globalAlpha = 1\n\n  maze.map((v,i)=>{\n    X = tx = v[0]\n    Y = ty = v[1]\n    Z = tz = v[2]\n    /*R(Rl,Pt,Yw,1)\n    if(Z>0){\n      l = Q()\n      s = Math.min(2e3,600/Z)\n      x.drawImage(starImgs[1].img,l[0]-s/2,l[1]-s/2,s,s)\n    }*/\n    v[3].map((q,j) => {\n      if(v[6]){\n        ax = ay = az = 0\n        q.map(n=>{\n          ax += n[0] + tx\n          ay += n[1] + ty\n          az += n[2] + tz\n        })\n        X = ax/=q.length\n        Y = ay/=q.length\n        Z = az/=q.length\n        R(Rl,Pt,Yw,1)\n        l = Q()\n        /*x.textAlign = \'center\'\n        x.fillStyle = \'#fff\'\n        x.font = (400/Z)+\'px courier\'\n        x.fillText(j,...l)\n        x.fillText(v[6],l[0],l[1]+400/Z)*/\n      }\n      x.beginPath()\n      q.map(n=>{\n        X = n[0] + tx\n        Y = n[1] + ty\n        Z = n[2] + tz\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n      })\n      //col = v[5] ? \'\' : \'#4400ff01\'\n      col = \'\'\n      if(start == i) col = \'#ff03\'\n      if(dest  == i) col = \'#ff03\'\n      //stroke(\'\',col,1,false)\n    })\n  })\n  \n  x.lineJoin = x.lineCap = \'roud\'\n  memo1 = []\n  memo2 = []\n  memo3 = []\n  drawPath1(0,0)\n  drawPath2(0,0)\n  \n  squirreliness = 0\n  homing = 0//.0005\n  start = dest = 0\n  B.map((v, i)=>{\n    v[6] /= 1.05\n    v[7] /= 1.05\n    v[8] /= 1.05\n    v[6] += (Rn()-.5)*squirreliness\n    v[7] += (Rn()-.5)*squirreliness\n    v[8] += (Rn()-.5)*squirreliness\n    v[3] += v[6]\n    v[4] += v[7]\n    v[5] += v[8]\n    vx = v[0]\n    vy = v[1]\n    vz = v[2]\n    d = Math.hypot(vx,vy,vz) + .0001\n    vx/=d\n    vy/=d\n    vz/=d\n    v[3] -= vx * homing\n    v[4] -= vy * homing\n    v[5] -= vz * homing\n    d = Math.hypot(v[3],v[4],v[5]) + .0001\n    v[3]/=d\n    v[4]/=d\n    v[5]/=d\n    v[3] *= iBv\n    v[4] *= iBv\n    v[5] *= iBv\n    X = v[0] += v[3]\n    Y = v[1] += v[4]\n    Z = v[2] += v[5]\n    if(Math.abs(v[0])>cl*sp/3.5){\n      v[3] *= -1\n      v[6] *= -1\n      if(v[0]>0){\n        v[0] = cl*sp/3.5\n      }else{\n        v[0] = -cl*sp/3.5\n      }\n    }\n    if(Math.abs(v[1])>rw*sp/3.5){\n      v[4] *= -1\n      v[7] *= -1\n      if(v[1]>0){\n        v[1] = rw*sp/3.5\n      }else{\n        v[1] = -rw*sp/3.5\n      }\n    }\n    if(Math.abs(v[2])>br*sp/3.5){\n      v[5] *= -1\n      v[8] *= -1\n      if(v[2]>0){\n        v[2] = br*sp/3.5\n      }else{\n        v[2] = -br*sp/3.5\n      }\n    }\n    /*if(Math.hypot(v[0],v[1],v[2])>rad){\n      v[3]*=-1\n      v[4]*=-1\n      v[5]*=-1\n      v[6]*=-1\n      v[7]*=-1\n      v[8]*=-1\n    }*/\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      l = Q()\n      s = Math.min(2e3,((3e3*S(t*30))+1e4)/Z)\n      //x.drawImage(starImgs[1].img,l[0]-s,l[1]-s,s*2,s*2)\n      x.drawImage(starImgs[i?8:5].img,l[0]-s/2.1,l[1]-s/2.1,s,s)\n    }\n    mind = 6e6\n    maze.map((q,j)=>{\n      if((d = Math.hypot(q[0]-v[0],q[1]-v[1],q[2]-v[2]))<mind){\n        mind = d\n        idx = j\n      }\n    })\n    if(!i){\n      start = idx\n    }else{\n      dest = idx\n    }\n  })\n  \n  path = []\n  recursePath(start, dest)\n  path = [...path, start]\n\n  x.lineJoin = x.lineCap = \'round\'\n  fluxSpeed = 2.5\n  path.map((v,i)=>{\n    v2 = path.length/2|0\n    d_ = S(Math.PI*4 / v2 * (i+t*path.length/8*fluxSpeed|0)%v2)\n    col = `hsla(${d_**3*70 - 130 + t*30},99%,${Math.min(100,Math.max(50,-1000+d_*1150))}%, ${Math.min(1, Math.max(.33, .1+(.9 * (d_/2+.5))**4))})`\n    if(path.length>2){\n      if(i==0){\n        X = B[1][0]\n        Y = B[1][1]\n        Z = B[1][2]\n        R(Rl,Pt,Yw,1)\n        x.beginPath()\n        x.moveTo(...Q())\n        X1 = X = maze[path[1]][0]\n        Y1 = Y = maze[path[1]][1]\n        Z1 = Z = maze[path[1]][2]\n        R(Rl,Pt,Yw,1)\n        if(Z>.1) l1 = Q()\n        X = (X1 + maze[path[2]][0]) / 2\n        Y = (Y1 + maze[path[2]][1]) / 2\n        Z = (Z1 + maze[path[2]][2]) / 2\n        R(Rl,Pt,Yw,1)\n        if(Z>.1) l2 = Q()\n        if(Z>.1) x.quadraticCurveTo(...l1, ...l2)\n        if(Z>.1) stroke(col, \'\', 5, true)\n      }\n      if(i>1&&i<path.length-1){\n        l = i-1\n        X1 = maze[path[l]][0]\n        Y1 = maze[path[l]][1]\n        Z1 = maze[path[l]][2]\n        l = i\n        X2 = maze[path[l]][0]\n        Y2 = maze[path[l]][1]\n        Z2 = maze[path[l]][2]\n        l = i+1\n        X3 = maze[path[l]][0]\n        Y3 = maze[path[l]][1]\n        Z3 = maze[path[l]][2]\n        x.beginPath()\n        X = (X1+X2)/2\n        Y = (Y1+Y2)/2\n        Z = (Z1+Z2)/2\n        R(Rl,Pt,Yw,1)\n        if(Z>.1) l0 = Q()\n        x.moveTo(...l0)\n        X = X2\n        Y = Y2\n        Z = Z2\n        R(Rl,Pt,Yw,1)\n        if(Z>.1) l1 = Q()\n        X = (X2+X3)/2\n        Y = (Y2+Y3)/2\n        Z = (Z2+Z3)/2\n        R(Rl,Pt,Yw,1)\n        if(Z>.1) l2 = Q()\n        if(Z>.1) x.quadraticCurveTo(...l1, ...l2)\n        if(Z>.1) stroke(col, \'\', 4+((d_+1)*4)**2/10, true)\n      }\n      x.lineJoin = x.lineCap = \'roud\'\n\n\n      if(i == path.length-1){\n        x.beginPath()\n        X = B[0][0]\n        Y = B[0][1]\n        Z = B[0][2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        X1 = X = maze[path[path.length-1]][0]\n        Y1 = Y = maze[path[path.length-1]][1]\n        Z1 = Z = maze[path[path.length-1]][2]\n        R(Rl,Pt,Yw,1)\n        if(Z>.1) l1 = Q()\n        X = (X1 + maze[path[path.length-2]][0]) / 2\n        Y = (Y1 + maze[path[path.length-2]][1]) / 2\n        Z = (Z1 + maze[path[path.length-2]][2]) / 2\n        R(Rl,Pt,Yw,1)\n        if(Z>.1) l2 = Q()\n        if(Z>.1) x.quadraticCurveTo(...l1, ...l2)\n        if(Z>.1) stroke(col, \'\', 5, true)\n      }\n    }\n  })\n  x.lineJoin = x.lineCap = \'roud\'\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  overflow: hidden;\n}\n#c{\n  background:#000;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'cube maze fancy', 145, 'whitehot robot', '2023-09-18 21:59:55', '[600729,600728]', 18, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600731, '', 'function initVars(){\n\n  pi=Math.PI;\n  canvas=$(\"#canvas\")[0];\n  ctx=canvas.getContext(\"2d\");\n\n\n  rsz=window.onresize=()=>{\n    setTimeout(()=>{\n      if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n        canvas.style.height = \'100vh\'\n        setTimeout(()=>canvas.style.width = canvas.clientHeight*1.77777778+\'px\',0)\n      }else{\n        canvas.style.width = \'100vw\'\n        setTimeout(()=>canvas.style.height = canvas.clientWidth/1.77777778 + \'px\',0)\n      }\n    }, 0)\n  }\n  rsz()\n\n\n  puyoA = new Image();\n  puyoA.src=\"https://srmcgann.github.io/puyopuyo/puyoA.png\";\n  puyoB = new Image();\n  puyoB.src=\"https://srmcgann.github.io/puyopuyo/puyoB.png\";\n  puyoC = new Image();\n  puyoC.src=\"https://srmcgann.github.io/puyopuyo/puyoC.png\";\n  puyoD = new Image();\n  puyoD.src=\"https://srmcgann.github.io/puyopuyo/puyoD.png\";\n  puyoE = new Image();\n  puyoE.src=\"https://srmcgann.github.io/puyopuyo/puyoE.png\";\n  leftArrow = new Image();\n  leftArrow.src=\"https://srmcgann.github.io/puyopuyo/leftArrow.png\";\n  rightArrow = new Image();\n  rightArrow.src=\"https://srmcgann.github.io/puyopuyo/rightArrow.png\";\n  ctx.font = \'68px Square721\';\n  canvas.width=1360;\n  canvas.height=768;\n  cx=canvas.width/2;\n  cy=canvas.height/2;\n  leftkey=rightkey=upkey=downkey=spacekey=0;\n  moveTimer=0;moveInterval=5,moveDownTimer=0,moveDownInterval=1,rotateTimer=0,rotateInterval=10;\n  dropTimer=25;dropInterval=30;\n  settling=false, deletePending=false, collapsing=0, deleteGrid=emptyGrid(), offsetGrid=emptyGrid();\n  width=cx/2;\n  height=width*2;\n  pieces = new Array();\n  ojamas = new Array();\n  ojamaDropSpeed=height/12/2;\n  deletions=0;\n  box = emptyGrid();\n  frames = 0;\n  ctx.clearRect(0,0,cx*2,cy*2);\n  x=cx/8; y=cy/8;\n  gameover=false;\n}\n\nfunction drawRules(){\n  \n  for(i=25;i>0;--i){\n    ctx.globalAlpha=.5/i;\n    size=i;\n    ctx.fillStyle=\"#fff\";\n    ctx.fillRect(x-size,y,size,height);\n    ctx.fillRect(x+width,y,size,height);\n    ctx.fillRect(x-size,y+height,width+size*2,size);\n    ctx.fillRect(x-size,y-size,width+size*2,size);\n  }\n  x=cx*2-cx/2-cx/8; y=cy/8;\n  for(i=25;i>0;--i){\n    ctx.globalAlpha=.5/i;\n    size=i;\n    ctx.fillStyle=\"#fff\";\n    ctx.fillRect(x-size,y,size,height);\n    ctx.fillRect(x+width,y,size,height);\n    ctx.fillRect(x-size,y+height,width+size*2,size);\n    ctx.fillRect(x-size,y-size,width+size*2,size);\n  }\n  ctx.globalAlpha=1;\n  ctx.fillStyle = \"#0f8\";\n  ctx.strokeStyle = \"#006\";\n  ctx.font = \'100 42px Square721\';\n  ctx.lineWidth=1;\n  ctx.fillText(\"Connect 4 or more\",cx-225,cy-300);\n  ctx.strokeText(\"Connect 4 or more\",cx-225,cy-300);\n  ctx.fillText(\"puyos of the same \",cx-225,cy-250);\n  ctx.strokeText(\"puyos of the same\",cx-225,cy-250);\n  ctx.fillText(\"color to make a\",cx-225,cy-200);\n  ctx.strokeText(\"color to make a\",cx-225,cy-200);\n  ctx.fillText(\"rensa.\",cx-225,cy-150);\n  ctx.strokeText(\"rensa.\",cx-225,cy-150);\n  ctx.fillText(\"With each rensa, your\",cx-225,cy+200);\n  ctx.strokeText(\"With each rensa, your\",cx-225,cy+200);\n  ctx.fillText(\"opponent is buried\",cx-225,cy+250);\n  ctx.strokeText(\"opponent is buried\",cx-225,cy+250);\n  ctx.fillText(\"under ojama (clutter).\",cx-225,cy+300);\n  ctx.strokeText(\"under ojama (clutter).\",cx-225,cy+300);\n  \n  ctx.drawImage(leftArrow,cx-250,cy-120);\n  ctx.fillStyle = \"#ff8\";\n  ctx.strokeStyle = \"#000\";\n  ctx.font = \'100 72px Square721\';\n  ctx.lineWidth=2;\n  ctx.fillText(\"YOU\",cx-125,cy-31);\n  ctx.strokeText(\"YOU\",cx-125,cy-31);\n\n  ctx.drawImage(rightArrow,cx+115,cy+25);\n  ctx.fillStyle = \"#8ff\";\n  ctx.strokeStyle = \"#000\";\n  ctx.font = \'100 72px Square721\';\n  ctx.lineWidth=2;\n  ctx.fillText(\"CPU\",cx-25,cy+115);\n  ctx.strokeText(\"CPU\",cx-25,cy+115);\n  $(\"#pauseButton\").blur();\n  $(\"#pauseButton\").show();\n}\n\nfunction spawnPieces(){\n\n  if(box[2][1]){\n    gameover=1;\n    $(\"#pauseButton\").hide();\n  }else{\n    for(i=1;i<3;++i){\n      piece=new Object();\n      piece.x=cx/8+width/6*2;\n      piece.y=cy/8-i*height/12;\n      piece.ix=piece.x;\n      piece.iy=piece.y;\n      switch(parseInt(Math.random()*4)){\n        case 0: piece.img=puyoA; break;\n        case 1: piece.img=puyoB; break;\n        case 2: piece.img=puyoC; break;\n        case 3: piece.img=puyoD; break;\n      }\n      pieces.push(piece);\n    }\n  }\n}\n\nfunction clearLeft(){\n  \n  if(pieces[0].bx>0 && pieces[1].bx>0 && box[pieces[0].bx-1][pieces[0].by]==0 && box[pieces[1].bx-1][pieces[1].by]==0) return 1;\n  return 0;\n}\n\nfunction clearRight(){\n  \n  if(pieces[0].bx<5 && pieces[1].bx<5 && box[pieces[0].bx+1][pieces[0].by]==0 && box[pieces[1].bx+1][pieces[1].by]==0) return 1;\n  return 0;\n}\n\nfunction rotate(){\n  \n  p=Math.atan2(pieces[1].x-pieces[0].x,pieces[1].y-pieces[0].y);\n  x=pieces[0].x+Math.sin(p-pi/2)*width/6;\n  y=pieces[0].y+Math.cos(p-pi/2)*width/6;\n  bx=Math.round((x-cx/8)/width*6);\n  by=Math.round((y-cy/8)/height*12+1);\n  if(bx<0 || bx>5 || by>12 || box[bx][by]) return 0;\n  pieces[1].x=x;\n  pieces[1].y=y;\n  return 1;\n}\n\nfunction checkComplete(x,y,img){\n  \n  if(x<0 || x>5 || y<0 || y>11 || checkGrid[x][y])return;\n  if(box[x][y+1]==img){\n    rensa++;\n    checkGrid[x][y]=1;\n    checkComplete(x+1,y,img);\n    checkComplete(x-1,y,img);\n    checkComplete(x,y+1,img);\n    checkComplete(x,y-1,img);\n  }\n}\n\nfunction emptyGrid(){\n  \n  grid=new Array(6);\n  for(i2=0;i2<6;++i2){\n    grid[i2]=new Array(13);\n    for(j2=0;j2<13;++j2)grid[i2][j2]=0;\n  }\n  return grid;\n}\n\nfunction dropCells(){\n  \n  if(collapsing<.9){\n    if(collapsing==0){\n      for(i=0;i<6;++i){\n        for(j=1;j<13;++j){\n          if(box[i][j])offsetGrid[i][j]=.00001;\n        }\n      }\n    }\n    collapsing+=.1;\n    \n    for(i=0;i<6;++i){\n      for(j=1;j<13;++j){\n        if(offsetGrid[i][j]==0){\n          for(k=j-1;k>0;--k){\n            if(offsetGrid[i][k]){\n              for(k2=k;k2>0;--k2){\n                if(offsetGrid[i][k2])offsetGrid[i][k2]=(j-k)*collapsing;\n              }\n              break;\n            }\n          }\n        }\n      }\n    }\n  }else{\n    for(i=0;i<6;++i){\n      for(j=12;j>0;--j){\n        if(box[i][j]==0){\n          for(k=j-1;k>0;--k){\n            if(box[i][k]){\n              box[i][j]=box[i][k];\n              box[i][k]=0;\n              break;\n            }\n          }\n        }\n      }\n    }\n    collapsing=0;\n    deleteGrid=emptyGrid();\n    offsetGrid=emptyGrid();\n    deletePending=false;\n  }\n}\n\nfunction recurseBoard(){\n\n  deleteGrid=emptyGrid();\n  for(i=0;i<6;++i){\n    for(j=1;j<13;++j){\n      if(box[i][j] && box[i][j]!=puyoE){\n        checkGrid=emptyGrid();\n        rensa=0;\n        checkComplete(i,j-1,box[i][j]);\n        if(rensa>3){\n          for(i2=0;i2<6;++i2){\n            for(j2=0;j2<12;++j2){\n              if(checkGrid[i2][j2])deleteGrid[i2][j2]=2;\n            }\n          }\n          fade=1;\n          deletePending=true;\n        }\n      }\n    }\n  }\n}\n\nfunction syncPieces(){\n  \n  pieces[0].bx=Math.round((pieces[0].x-cx/8)/width*6);\n  pieces[0].by=Math.round((pieces[0].y-cy/8)/height*12+1);\n  pieces[1].bx=Math.round((pieces[1].x-cx/8)/width*6);\n  pieces[1].by=Math.round((pieces[1].y-cy/8)/height*12+1);\n}\n\nfunction doOjamas(){\n  \n  ctx.globalAlpha=1;\n  for(i=0;i<ojamas.length;++i){\n    x=ojamas[i].x;\n    y=ojamas[i].y;\n    if(y<cy/8){\n      y2=cy/8-y;\n      ctx.drawImage(ojamas[i].img,0,y2,55,55,x,cy/8,55,55);\n    }else{\n      ctx.drawImage(ojamas[i].img,x,y);\n    }\n    ojamas[i].bx=Math.round((ojamas[i].x-cx/8)/width*6);\n    ojamas[i].by=Math.round((ojamas[i].y-cy/8)/height*12+1);\n    if(ojamas[i].by<0)ojamas[i].by=0;\n    if(ojamas[i].by<12 && box[ojamas[i].bx][ojamas[i].by+1]==0){\n      ojamas[i].y+=ojamaDropSpeed;\n    }else{\n      box[ojamas[i].bx][ojamas[i].by]=ojamas[i].img;\n      ojamas.splice(i,1);\n    }\n  }\n}\n\nfunction sendOjamas(){\n  \n  for(i=0;i<(deletions/4)*(1+deletions/6)*(1+deletions/8)-2;++i){\n    piece=new Object();\n    y=AIy-parseInt(AIojamas.length/6+1)*height/12;\n    do{\n      x=AIx+width/6*(parseInt(Math.random()*6));\n      empty=1;\n      for(j=0;j<AIojamas.length;++j)if(AIojamas[j].x==x && AIojamas[j].y==y)empty=0;      \n    }while(!empty);\n    piece.x=x;\n    piece.y=y;\n    piece.ix=piece.x;\n    piece.iy=piece.y;\n    piece.img=puyoE;\n    AIojamas.push(piece);\n  }\n}\n\nfunction doLogic(){\n  \n  if(pieces.length){\n    deletions=0;\n    pieces[0].ix=pieces[0].ix+(pieces[0].x-pieces[0].ix)/3;\n    pieces[0].iy=pieces[0].iy+(pieces[0].y-pieces[0].iy)/3;\n    pieces[1].ix=pieces[1].ix+(pieces[1].x-pieces[1].ix)/3;\n    pieces[1].iy=pieces[1].iy+(pieces[1].y-pieces[1].iy)/3;\n    syncPieces();\n    if(!settling){\n      if(leftkey && moveTimer<frames && clearLeft()){\n        moveTimer=frames+moveInterval;\n        pieces[0].x-=width/6;\n        pieces[1].x-=width/6;\n      }\n      if(rightkey && moveTimer<frames && clearRight()){\n        moveTimer=frames+moveInterval;\n        pieces[0].x+=width/6;\n        pieces[1].x+=width/6;\n      }\n      if(upkey && rotateTimer<frames && rotate()){\n        rotateTimer=frames+rotateInterval;\n      }\n      syncPieces();\n      if(downkey && moveDownTimer<frames){\n        moveDownTimer=frames+moveDownInterval;\n        if(pieces[0].by<12 && pieces[1].by<12 && \n           box[pieces[0].bx][pieces[0].by+1]==0 &&\n           box[pieces[1].bx][pieces[1].by+1]==0){\n          pieces[0].y+=height/12;\n          pieces[1].y+=height/12;\n          dropTimer=frames+dropInterval;\n        }else{\n          settling=true;\n        }\n      }\n      if(dropTimer<frames){\n        if(pieces[0].by<12 && pieces[1].by<12 &&\n           box[pieces[0].bx][pieces[0].by+1]==0 &&\n           box[pieces[1].bx][pieces[1].by+1]==0){\n          pieces[0].y+=height/12;\n          pieces[1].y+=height/12;\n          dropTimer=frames+dropInterval;\n        }else{\n          settling=true;\n        }\n      }\n    }else{\n      if(pieces[0].by==pieces[1].by){\n        pieces[0].y=cy/8+height-height/12;\n        pieces[1].y=cy/8+height-height/12;\n        for(i=12;i>=0;--i){\n          if(box[pieces[0].bx][i+1])pieces[0].y=cy/8+(i-1)*height/12;\n          if(box[pieces[1].bx][i+1])pieces[1].y=cy/8+(i-1)*height/12;\n        }\n      }\n      if(Math.abs(pieces[0].y-pieces[0].iy)<5 && Math.abs(pieces[1].y-pieces[1].iy)<5){\n        box[pieces[0].bx][pieces[0].by]=pieces[0].img;\n        box[pieces[1].bx][pieces[1].by]=pieces[1].img;\n        recurseBoard();\n        pieces.splice(0,1);\n        pieces.splice(0,1);\n      }\n    }\n  }else{\n    if(deletePending){\n      if(fade>.1){\n        fade-=.1;\n      }else{\n        if(collapsing==0){\n          for(i=0;i<6;++i){\n            for(j=0;j<12;++j){\n              if(deleteGrid[i][j]){\n                deletions++;\n                box[i][j+1]=0;\n                if(i>0&&box[i-1][j+1]==puyoE)box[i-1][j+1]=0;\n                if(i<5&&box[i+1][j+1]==puyoE)box[i+1][j+1]=0;\n                if(j<11&&box[i][j+2]==puyoE)box[i][j+2]=0;\n                if(box[i][j]==puyoE)box[i][j]=0;\n              }\n            }\n          }\n        }\n        dropCells();\n        recurseBoard();\n      }\n    }else{\n      if(ojamas.length){\n        doOjamas();\n      }else{\n        if(deletions)sendOjamas();\n        spawnPieces();\n        settling=false;       \n      }\n    }\n  }\n}\n\n\nfunction drawContainers(){\n  \n  x=cx/8; y=cy/8;\n  ctx.globalAlpha=.8;\n  ctx.fillStyle=\"#001\";\n  ctx.fillRect(x,y,width,height);\n  ctx.globalAlpha=.1;\n  ctx.lineWidth=2;\n  ctx.strokeStyle=\"#fff\";\n  ctx.beginPath();\n  for(i=0;i<12;++i){\n    ctx.moveTo(x,y+height/12*i);\n    ctx.lineTo(x+width,y+height/12*i);\n  }\n  for(i=0;i<6;++i){\n    ctx.moveTo(x+width/6*i,y);\n    ctx.lineTo(x+width/6*i,y+height);\n  }\n  ctx.stroke();\n  ctx.closePath();\n  \n  x=cx*2-cx/2-cx/8; y=cy/8;\n  ctx.globalAlpha=.8;\n  ctx.fillStyle=\"#001\";\n  ctx.fillRect(x,y,width,height);\n  ctx.globalAlpha=.1;\n  ctx.lineWidth=2;\n  ctx.strokeStyle=\"#fff\";\n  ctx.beginPath();\n  for(i=0;i<12;++i){\n    ctx.moveTo(x,y+height/12*i);\n    ctx.lineTo(x+width,y+height/12*i);\n  }\n  for(i=0;i<6;++i){\n    ctx.moveTo(x+width/6*i,y);\n    ctx.lineTo(x+width/6*i,y+height);\n  }\n  ctx.stroke();\n  ctx.closePath();\n}\n\nfunction drawPieces(){\n  \n  ctx.globalAlpha=1;\n  for(i=0;i<pieces.length;++i){\n    x=pieces[i].ix;\n    y=pieces[i].iy;\n    if(y<cy/8){\n      y2=cy/8-y;\n      ctx.drawImage(pieces[i].img,0,y2,55,55,x,cy/8,55,55);\n    }else{\n      ctx.drawImage(pieces[i].img,x,y);\n    }\n  }\n}\n\nfunction drawBoards(){\n  \n  for(i=0;i<6;++i){\n    for(j=1;j<13;++j){\n      if(deleteGrid[i][j-1]){\n        ctx.globalAlpha=fade;\n      }else{\n        ctx.globalAlpha=1;\n      }\n      if(box[i][j]) ctx.drawImage(box[i][j],cx/8+width/6*i,cy/8+height/12*j-height/12+offsetGrid[i][j]*height/12);\n\n      if(AIdeleteGrid[i][j-1]){\n        ctx.globalAlpha=AIfade;\n      }else{\n        ctx.globalAlpha=1;\n      }\n      if(AIbox[i][j]) ctx.drawImage(AIbox[i][j],AIx+width/6*i,AIy+height/12*j-height/12+AIoffsetGrid[i][j]*height/12);\n    }\n  }\n}\n\nfunction draw(){\n  \n  x=cx/8; y=cy/8;\n  ctx.clearRect(x,y,width,height);\n  x=cx*2-cx/2-cx/8; y=cy/8;\n  ctx.clearRect(x,y,width,height);\n\n  drawContainers();\n  drawBoards();\n  drawPieces();\n  AIdrawAIpieces();\n}\n\nwindow.addEventListener(\"keydown\", function(e){\n\n  chr=e.keyCode || e.charCode;\n  switch(chr){\n    case 37:leftkey=1;break;\n    case 38:upkey=1;break;\n    case 39:rightkey=1;break;\n    case 40:downkey=1;break;\n    case 32:spacekey=1;break;\n  }\n});\n\nwindow.addEventListener(\"keyup\", function(e){\n\n  chr=e.keyCode || e.charCode;\n  switch(chr){\n    case 37:leftkey=0;moveTimer=0;break;\n    case 38:upkey=0;rotateTimer=0;break;\n    case 39:rightkey=0;moveTimer=0;break;\n    case 40:downkey=0;break;\n    case 32:spacekey=0;break;\n  }\n});\n\nfunction AIinitVars(){\n\n  AIleftkey=AIrightkey=AIupkey=AIdownkey=0;\n  AImoveTimer=0, AImoveDownTimer=0, AIrotateTimer=0;\n  AIdropTimer=30;\n  AImoveInterval=10,AImoveDownInterval=1,AIrotateInterval=5,AIdropInterval=25;\n  AIsettling=false, AIdeletePending=false, AIcollapsing=0, AIdeleteGrid=emptyGrid(), AIoffsetGrid=emptyGrid();\n  AIpieces = new Array();\n  AIojamas = new Array();\n  AIdeletions=0;\n  AIbox = emptyGrid();\n  AIx=cx*2-cx/2-cx/8;\n  AIy=cy/8;\n}\n\nfunction spawnAIpieces(){\n\n  if(AIbox[2][1]){\n    gameover=2;\n    $(\"#pauseButton\").hide();\n  }else{\n    for(i=0;i<2;++i){\n      piece=new Object();\n      piece.x=AIx+width/6*2;\n      piece.y=AIy-i*height/12;\n      piece.ix=piece.x;\n      piece.iy=piece.y;\n      switch(parseInt(Math.random()*4)){\n        case 0: piece.img=puyoA; break;\n        case 1: piece.img=puyoB; break;\n        case 2: piece.img=puyoC; break;\n        case 3: piece.img=puyoD; break;\n      }\n      AIpieces.push(piece);\n    }\n      \n    gridAnalysis=emptyGrid();\n    for(i=0;i<6;++i){\n      for(j=1;j<13;++j){\n        gridAnalysis[i][j]=new Array();\n        if(!AIbox[i][j]){\n          if(i>0 && AIbox[i-1][j]) gridAnalysis[i][j].push(AIbox[i-1][j]);\n          if(i<5 && AIbox[i+1][j]) gridAnalysis[i][j].push(AIbox[i+1][j]);\n          if(j<12 && AIbox[i][j+1]) gridAnalysis[i][j].push(AIbox[i][j+1]);\n        }\n      }\n    }\n    target=new Array(4);\n    for(i=0;i<4;++i){\n      target[i]=new Array(6);\n      for(j=0;j<6;++j)target[i][j]=0;\n    }\n    for(i=0;i<4;++i){\n      switch(i){\n        case 0:\n          for(j=0;j<6;++j){\n            k=0;while(k<12 && !AIbox[j][k+1])k++;\n            for(m=0;m<gridAnalysis[j][k].length;++m){\n              if(gridAnalysis[j][k][m]==AIpieces[0].img) target[i][j]++;\n              if(gridAnalysis[j][k-1][m]==AIpieces[1].img) target[i][j]++;\n            }\n          }\n        break;\n        case 1:\n          for(j=0;j<5;++j){\n            k=0;while(k<12 && !AIbox[j][k+1])k++;\n            for(m=0;m<gridAnalysis[j][k].length;++m){\n              if(gridAnalysis[j][k][m]==AIpieces[0].img) target[i][j]++;\n            }\n            k=0;while(k<12 && !AIbox[j+1][k+1])k++;\n            for(m=0;m<gridAnalysis[j+1][k].length;++m){\n              if(gridAnalysis[j+1][k][m]==AIpieces[1].img) target[i][j]++;\n            }\n          }\n        break;\n        case 2:\n          for(j=0;j<6;++j){\n            k=0;while(k<12 && !AIbox[j][k+1])k++;\n            for(m=0;m<gridAnalysis[j][k].length;++m){\n              if(gridAnalysis[j][k][m]==AIpieces[1].img) target[i][j]++;\n              if(gridAnalysis[j][k-1][m]==AIpieces[0].img) target[i][j]++;\n            }\n          }\n        break;\n        case 3:\n          for(j=1;j<6;++j){\n            k=0;while(k<12 && !AIbox[j][k+1])k++;\n            for(m=0;m<gridAnalysis[j][k].length;++m){\n              if(gridAnalysis[j][k][m]==AIpieces[0].img) target[i][j]++;\n            }\n            k=0;while(k<12 && !AIbox[j-1][k+1])k++;\n            for(m=0;m<gridAnalysis[j-1][k].length;++m){\n              if(gridAnalysis[j-1][k][m]==AIpieces[1].img) target[i][j]++;\n            }\n          }\n        break;      \n      }\n    }\n      \n    t=0;\n    for(i=0;i<4;++i){\n      for(j=0;j<6;++j){\n        if(t<target[i][j]){\n          t=target[i][j];\n          targetR=i;\n          targetX=j;\n        }\n      }\n    }\n    if(!t){\n      targetR=parseInt(Math.random()*4);\n      targetX=parseInt(Math.random()*6);\n    }\n    rotationCounter=0;\n  }\n}\n\nfunction AIclearLeft(){\n  \n  if(AIpieces[0].bx>0 && AIpieces[1].bx>0 && AIbox[AIpieces[0].bx-1][AIpieces[0].by]==0 && AIbox[AIpieces[1].bx-1][AIpieces[1].by]==0) return 1;\n  return 0;\n}\n\nfunction AIclearRight(){\n  \n  if(AIpieces[0].bx<5 && AIpieces[1].bx<5 && AIbox[AIpieces[0].bx+1][AIpieces[0].by]==0 && AIbox[AIpieces[1].bx+1][AIpieces[1].by]==0) return 1;\n  return 0;\n}\n\nfunction AIrotate(){\n  \n  p=Math.atan2(AIpieces[1].x-AIpieces[0].x,AIpieces[1].y-AIpieces[0].y);\n  x=AIpieces[0].x+Math.sin(p-pi/2)*width/6;\n  y=AIpieces[0].y+Math.cos(p-pi/2)*width/6;\n  bx=Math.round((x-AIx)/width*6);\n  by=Math.round((y-AIy)/height*12+1);\n  if(bx<0 || bx>5 || by>12 || AIbox[bx][by]) return 0;\n  AIpieces[1].x=x;\n  AIpieces[1].y=y;\n  return 1;\n}\n\nfunction AIcheckComplete(x,y,img){\n  \n  if(x<0 || x>5 || y<0 || y>11 || AIcheckGrid[x][y])return;\n  if(AIbox[x][y+1]==img){\n    rensa++;\n    AIcheckGrid[x][y]=1;\n    AIcheckComplete(x+1,y,img);\n    AIcheckComplete(x-1,y,img);\n    AIcheckComplete(x,y+1,img);\n    AIcheckComplete(x,y-1,img);\n  }\n}\n\nfunction AIdropCells(){\n  \n  if(AIcollapsing<.9){\n    if(AIcollapsing==0){\n      for(i=0;i<6;++i){\n        for(j=1;j<13;++j){\n          if(AIbox[i][j])AIoffsetGrid[i][j]=.00001;\n        }\n      }\n    }\n    AIcollapsing+=.1;\n    \n    for(i=0;i<6;++i){\n      for(j=1;j<13;++j){\n        if(AIoffsetGrid[i][j]==0){\n          for(k=j-1;k>0;--k){\n            if(AIoffsetGrid[i][k]){\n              for(k2=k;k2>0;--k2){\n                if(AIoffsetGrid[i][k2])AIoffsetGrid[i][k2]=(j-k)*AIcollapsing;\n              }\n              break;\n            }\n          }\n        }\n      }\n    }\n  }else{\n    for(i=0;i<6;++i){\n      for(j=12;j>0;--j){\n        if(AIbox[i][j]==0){\n          for(k=j-1;k>0;--k){\n            if(AIbox[i][k]){\n              AIbox[i][j]=AIbox[i][k];\n              AIbox[i][k]=0;\n              break;\n            }\n          }\n        }\n      }\n    }\n    AIcollapsing=0;\n    AIdeleteGrid=emptyGrid();\n    AIoffsetGrid=emptyGrid();\n    AIdeletePending=false;\n  }\n}\n\nfunction AIrecurseBoard(){\n\n  AIdeleteGrid=emptyGrid();\n  for(i=0;i<6;++i){\n    for(j=1;j<13;++j){\n      if(AIbox[i][j] && AIbox[i][j]!=puyoE){\n        AIcheckGrid=emptyGrid();\n        rensa=0;\n        AIcheckComplete(i,j-1,AIbox[i][j]);\n        if(rensa>3){\n          for(i2=0;i2<6;++i2){\n            for(j2=0;j2<12;++j2){\n              if(AIcheckGrid[i2][j2])AIdeleteGrid[i2][j2]=2;\n            }\n          }\n          AIfade=1;\n          AIdeletePending=true;\n        }\n      }\n    }\n  }\n}\n\nfunction AIsyncPieces(){\n  AIpieces[0].bx=Math.round((AIpieces[0].x-AIx)/width*6);\n  AIpieces[0].by=Math.round((AIpieces[0].y-AIy)/height*12+1);\n  AIpieces[1].bx=Math.round((AIpieces[1].x-AIx)/width*6);\n  AIpieces[1].by=Math.round((AIpieces[1].y-AIy)/height*12+1); \n}\n\nfunction AIdoOjamas(){\n  \n  ctx.globalAlpha=1;\n  for(i=0;i<AIojamas.length;++i){\n    x=AIojamas[i].x;\n    y=AIojamas[i].y;\n    if(y<AIy){\n      y2=AIy-y;\n      ctx.drawImage(AIojamas[i].img,0,y2,55,55,x,AIy,55,55);\n    }else{\n      ctx.drawImage(AIojamas[i].img,x,y);\n    }\n    AIojamas[i].bx=Math.round((AIojamas[i].x-AIx)/width*6);\n    AIojamas[i].by=Math.round((AIojamas[i].y-AIy)/height*12+1);\n    if(AIojamas[i].by<0)AIojamas[i].by=0;\n    if(AIojamas[i].by<12 && AIbox[AIojamas[i].bx][AIojamas[i].by+1]==0){\n      AIojamas[i].y+=ojamaDropSpeed;\n    }else{\n      AIbox[AIojamas[i].bx][AIojamas[i].by]=AIojamas[i].img;\n      AIojamas.splice(i,1);\n    }\n  }\n}\n\nfunction AIsendOjamas(){\n  \n  for(i=0;i<(AIdeletions/4)*(1+AIdeletions/6)*(1+AIdeletions/8)-2;++i){\n    piece=new Object();\n    y=cy/8-parseInt(ojamas.length/6+1)*height/12;\n    do{\n      x=cx/8+width/6*(parseInt(Math.random()*6));\n      empty=1;\n      for(j=0;j<ojamas.length;++j)if(ojamas[j].x==x && ojamas[j].y==y)empty=0;      \n    }while(!empty);\n    piece.x=x;\n    piece.y=y;\n    piece.ix=piece.x;\n    piece.iy=piece.y;\n    piece.img=puyoE;\n    ojamas.push(piece);\n  }\n}\n\nfunction AIdoLogic(){\n\n  if(AIpieces.length){\n    AIdeletions=0;\n    AIpieces[0].ix=AIpieces[0].ix+(AIpieces[0].x-AIpieces[0].ix)/3;\n    AIpieces[0].iy=AIpieces[0].iy+(AIpieces[0].y-AIpieces[0].iy)/3;\n    AIpieces[1].ix=AIpieces[1].ix+(AIpieces[1].x-AIpieces[1].ix)/3;\n    AIpieces[1].iy=AIpieces[1].iy+(AIpieces[1].y-AIpieces[1].iy)/3;\n    AIsyncPieces();\n    if(AIpieces[0].bx<targetX){\n      AIrightkey=true;\n      AIleftkey=false;\n    }\n    if(AIpieces[0].bx>targetX){\n      AIrightkey=false;\n      AIleftkey=true;\n    }\n    if(AIpieces[0].bx==targetX){\n      AIrightkey=false;\n      AIleftkey=false;      \n    }\n    if(rotationCounter<targetR){\n      AIupkey=true;\n    }else{\n      AIupkey=false;\n    }\n    if(Math.random()<.075){\n      AIdownkey=true;\n    }else{\n      AIdownkey=false;\n    }\n    \n    if(!AIsettling){\n      if(AIleftkey && AImoveTimer<frames && AIclearLeft()){\n        AImoveTimer=frames+AImoveInterval;\n        AIpieces[0].x-=width/6;\n        AIpieces[1].x-=width/6;\n      }\n      if(AIrightkey && AImoveTimer<frames && AIclearRight()){\n        AImoveTimer=frames+AImoveInterval;\n        AIpieces[0].x+=width/6;\n        AIpieces[1].x+=width/6;\n      }\n      if(AIupkey && AIrotateTimer<frames && AIrotate()){\n        rotationCounter++;\n        AIrotateTimer=frames+AIrotateInterval;\n      }\n      AIsyncPieces();\n      if(AIdownkey && AImoveDownTimer<frames){\n        AImoveDownTimer=frames+AImoveDownInterval;\n        if(AIpieces[0].by<12 && AIpieces[1].by<12 && \n           AIbox[AIpieces[0].bx][AIpieces[0].by+1]==0 &&\n           AIbox[AIpieces[1].bx][AIpieces[1].by+1]==0){\n          AIpieces[0].y+=height/12;\n          AIpieces[1].y+=height/12;\n          AIdropTimer=frames+AIdropInterval;\n        }else{\n          AIsettling=true;\n        }\n      }\n      if(AIdropTimer<frames){\n        if(AIpieces[0].by<12 && AIpieces[1].by<12 &&\n           AIbox[AIpieces[0].bx][AIpieces[0].by+1]==0 &&\n           AIbox[AIpieces[1].bx][AIpieces[1].by+1]==0){\n          AIpieces[0].y+=height/12;\n          AIpieces[1].y+=height/12;\n          AIdropTimer=frames+AIdropInterval;\n        }else{\n          AIsettling=true;\n        }\n      }\n    }else{\n      if(AIpieces[0].by==AIpieces[1].by){\n        AIpieces[0].y=cy/8+height-height/12;\n        AIpieces[1].y=cy/8+height-height/12;\n        for(i=12;i>=0;--i){\n          if(AIbox[AIpieces[0].bx][i+1])AIpieces[0].y=cy/8+(i-1)*height/12;\n          if(AIbox[AIpieces[1].bx][i+1])AIpieces[1].y=cy/8+(i-1)*height/12;\n        }\n      }\n      if(Math.abs(AIpieces[0].y-AIpieces[0].iy)<5 && Math.abs(AIpieces[1].y-AIpieces[1].iy)<5){\n        AIbox[AIpieces[0].bx][AIpieces[0].by]=AIpieces[0].img;\n        AIbox[AIpieces[1].bx][AIpieces[1].by]=AIpieces[1].img;\n        AIrecurseBoard();\n        AIpieces.splice(0,1);\n        AIpieces.splice(0,1);\n      }\n    }\n  }else{\n    if(AIdeletePending){\n      if(AIfade>.1){\n        AIfade-=.1;\n      }else{\n        if(AIcollapsing==0){\n          for(i=0;i<6;++i){\n            for(j=0;j<12;++j){\n              if(AIdeleteGrid[i][j]){\n                AIdeletions++;\n                AIbox[i][j+1]=0;\n                if(i>0&&AIbox[i-1][j+1]==puyoE)AIbox[i-1][j+1]=0;\n                if(i<5&&AIbox[i+1][j+1]==puyoE)AIbox[i+1][j+1]=0;\n                if(j<11&&AIbox[i][j+2]==puyoE)AIbox[i][j+2]=0;\n                if(AIbox[i][j]==puyoE)AIbox[i][j]=0;\n              }\n            }\n          }\n        }\n        AIdropCells();\n        AIrecurseBoard();\n      }\n    }else{\n      if(AIojamas.length){\n        AIdoOjamas();\n      }else{\n        if(AIdeletions)AIsendOjamas();\n        spawnAIpieces();\n        AIsettling=false;\n      }\n    }\n  }\n}\n\nfunction AIdrawAIpieces(){\n  \n  ctx.globalAlpha=1;\n  for(i=0;i<AIpieces.length;++i){\n    x=AIpieces[i].ix;\n    y=AIpieces[i].iy;\n    if(y<cy/8){\n      y2=cy/8-y;\n      ctx.drawImage(AIpieces[i].img,0,y2,55,55,x,cy/8,55,55);\n    }else{\n      ctx.drawImage(AIpieces[i].img,x,y);\n    }\n  }\n}\n\nfunction doGameOver(){\n  \n  ctx.globalAlpha=.04;\n  switch(gameover){\n    case 1:\n      ctx.fillStyle=\"#300\";\n      ctx.fillRect(0,0,cx*2,cy*2);\n      ctx.fillStyle = \"#f00\";\n      ctx.strokeStyle = \"#ff0\";\n      ctx.font = \'200px Square721\';\n      ctx.fillText(\"YOU LOST\",cx-500,cy-100);\n      ctx.strokeText(\"YOU LOST\",cx-500,cy-100);\n      ctx.font = \'64px Square721\';\n      ctx.fillText(\"CONTINUE?\",cx-180,cy+150);\n      ctx.strokeText(\"CONTINUE?\",cx-180,cy+150);\n      ctx.strokeStyle = \"#f00\";\n      ctx.font = \'32px Square721\';\n      ctx.strokeText(\"HIT THE SPACEBAR\",cx-150,cy+200);\n      break;\n    case 2:\n      ctx.fillStyle=\"#024\";\n      ctx.fillRect(0,0,cx*2,cy*2);\n      ctx.fillStyle = \"#0f8\";\n      ctx.strokeStyle = \"#0f8\";\n      ctx.font = \'200px Square721\';\n      ctx.fillText(\"YOU WON!\",cx-500,cy-100);\n      ctx.strokeText(\"YOU WON!\",cx-500,cy-100);\n      ctx.font = \'64px Square721\';\n      ctx.fillText(\"CONTINUE?\",cx-180,cy+150);\n      ctx.strokeText(\"CONTINUE?\",cx-180,cy+150);\n      ctx.strokeStyle = \"#0ff\";\n      ctx.font = \'32px Square721\';\n      ctx.strokeText(\"HIT THE SPACEBAR\",cx-150,cy+200);\n      break;\n  }\n  if(spacekey){\n    initVars();\n    AIinitVars();\n    drawRules();\n  }\n}\n\nfunction frame(){\n\n  frames++;\n  if(!gameover){\n    draw();\n    if(!paused){\n      doLogic();\n      AIdoLogic();\n    }\n  }else{\n    doGameOver();\n  }\n}\n\nfunction togglePause(){\n  paused=!paused;\n  if(paused){\n    $(\"#pauseScreen\").show();\n    $(\"#pauseButton\").html(\"UNPAUSE\");\n  }else{\n    $(\"#pauseScreen\").hide();\n    $(\"#pauseButton\").html(\"PAUSE\");\n  }\n}\n\nfunction kickoff(){\n\n  $(\"#loadingOuter\").hide();\n  drawRules();\n  paused=true;\n  setInterval(frame,30);\n}\n\ninitVars();\nAIinitVars();\nsetTimeout(kickoff,1000);', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  overflow: hidden;\n}\n#canvas{\n  background:#0000;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}\nbody{\n  font-family:arial, tahoma;\n  background:#000 url(https://srmcgann.github.io/puyopuyo/bg.jpg);\n  background-position: center;\n  background-size:cover;\n  color:#fff;\n}\n@font-face {\n  font-family: \'Square721\';\n  src: url(\'https://srmcgann.github.io/puyopuyo/TT0246M_.TTF\') format(\'truetype\'),\n     url(\'https://srmcgann.github.io/puyopuyo/TT0246M_.otf\') format(\'opentype\'),\n     url(\'https://srmcgann.github.io/puyopuyo/TT0246M_.woff\') format(\'woff\');\n}\n#loadingOuter{\n  position:absolute;\n  left:50%;\n  height:100%;\n}\n#loading{\n  position:relative;\n  left:-50%;\n  top:35%;\n  font-family:Square721,courier new;\n  font-size:4em;\n  border-radius:10px;\n  padding-left:50px;\n  padding-right:50px;\n  padding-top:10px;\n  padding-bottom:10px;\n  color:#0f4;\n  background:#112;\n  border:5px solid #0f4;\n}\n#pauseButton{\n  position:absolute;\n  background:#333;\n  color:#0f4;\n  font-family: Square721, courier new;\n  border-radius:5px;\n  font-size:2em;\n  display:none;\n  width:250px;\n  left:50%;\n  bottom:10px;\n  margin-left:-125px;\n}\n#pauseScreen{\n  position:absolute;\n  background: rgba(20,20,20,.85);\n  font-family: Square721, courier new;\n  font-size:5em;\n  color: rgba(0,255,128,.85);\n  width:100%;\n  text-align:center;\n  display:none;\n  height:100%;\n}', '<script src=\"//ajax.googleapis.com/ajax/libs/jquery/1.11.3/jquery.min.js\"></script>\n<div id=\"loadingOuter\">\n<div id=\"loading\">LOADING...</div>\n</div>\n<div id=\"pauseScreen\"><br><br><br>PAUSED</div>\n<canvas id=\"canvas\"></canvas>\n<button id=\"pauseButton\" onclick=\"togglePause()\">START GAME</button>\n<script src=\"game.js\"></script>\n', 'puyo puyo (game)', 145, 'whitehot robot', '2023-09-19 17:49:14', '[600730,600729,600728]', 12, '', 0, 0);
