     q[1] = Y\n          q[2] = Z\n        })\n        return v\n      })\n      shp = [...shp, ...e]\n\n      coords = [\n        [[3,1],[4,3],[4,4],[3,2]],\n        [[3,4],[3,3],[2,4],[6,2]],\n        [[1,4],[0,3],[0,4],[4,2]],\n        [[1,1],[1,2],[6,4],[7,3]],\n        [[3,5],[7,5],[1,5],[3,0]],\n        [[2,5],[6,5],[0,5],[4,5]]\n      ]\n      a = []\n      coords.map(v=>{\n        b = []\n        v.map(q=>{\n          X = shp[q[0]][q[1]][0]\n          Y = shp[q[0]][q[1]][1]\n          Z = shp[q[0]][q[1]][2]\n          b = [...b, [X,Y,Z]]\n        })\n        a = [...a, b]\n      })\n      shp = [...shp, ...a]\n      return shp.map(v=>{\n        v.map(q=>{\n          q[0]/=3\n          q[1]/=3\n          q[2]/=3\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n        return v\n      })\n    }\n    \n    Cylinder = (rw,cl,ls1,ls2) => {\n      let a = []\n      for(let i=rw;i--;){\n        let b = []\n        for(let j=cl;j--;){\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n        }\n        //a = [...a, b]\n        for(let j=cl;j--;){\n          b = []\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(j+1)) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(j+1)) * ls1\n          Y = (1/rw*(i+1)-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*(i+1)-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          a = [...a, b]\n        }\n      }\n      b = []\n      for(let j=cl;j--;){\n        X = S(p=Math.PI*2/cl*j) * ls1\n        Y = ls2/2\n        Z = C(p) * ls1\n        b = [...b, [X,Y,Z]]\n      }\n      //a = [...a, b]\n      return a\n    }\n\n    Tetrahedron = size => {\n      ret = []\n      a = []\n      let h = size/1.4142/1.25\n      for(i=3;i--;){\n        X = S(p=Math.PI*2/3*i) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n      }\n      ret = [...ret, a]\n      for(j=3;j--;){\n        a = []\n        X = 0\n        Y = 0\n        Z = -h\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/3*j) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/3*(j+1)) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      ax=ay=az=ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax\n          q[1]-=ay\n          q[2]-=az\n        })\n      })\n      return ret\n    }\n\n    Cube = size => {\n      for(CB=[],j=6;j--;CB=[...CB,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?size/1.5:-size/1.5),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      return CB\n    }\n    \n    Octahedron = size => {\n      ret = []\n      let h = size/1.25\n      for(j=8;j--;){\n        a = []\n        X = 0\n        Y = 0\n        Z = h * (j<4?-1:1)\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*j) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*(j+1)) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      return ret      \n    }\n    \n    Dodecahedron = size => {\n      ret = []\n      a = []\n      mind = -6e6\n      for(i=5;i--;){\n        X=S(p=Math.PI*2/5*i + Math.PI/5)\n        Y=C(p)\n        Z=0\n        if(Y>mind) mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a.map(v=>{\n        X = v[0]\n        Y = v[1]-=mind\n        Z = v[2]\n        R(0, .553573, 0)\n        v[0] = X\n        v[1] = Y\n        v[2] = Z\n      })\n      b = JSON.parse(JSON.stringify(a))\n      b.map(v=>{\n        v[1] *= -1\n      })\n      ret = [...ret, a, b]\n      mind = -6e6\n      ret.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          if(Z>mind)mind = Z\n        })\n      })\n      d1=Math.hypot(ret[0][0][0]-ret[0][1][0],ret[0][0][1]-ret[0][1][1],ret[0][0][2]-ret[0][1][2])\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]-=mind+d1/2\n        })\n      })\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          q[2]*=-1\n        })\n      })\n      ret = [...ret, ...b]\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(0,Math.PI/2,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      e = JSON.parse(JSON.stringify(ret))\n      e.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(Math.PI/2,0,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      ret = [...ret, ...b, ...e]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0] *= size/2\n          q[1] *= size/2\n          q[2] *= size/2\n        })\n      })\n      return ret\n    }\n    \n    Icosahedron = size => {\n      ret = []\n      B = [\n        [[0,3],[1,0],[2,2]],\n        [[0,3],[1,0],[1,3]],\n        [[0,3],[2,3],[1,3]],\n        [[0,2],[2,1],[1,0]],\n        [[0,2],[1,3],[1,0]],\n        [[0,2],[1,3],[2,0]],\n        [[0,3],[2,2],[0,0]],\n        [[1,0],[2,2],[2,1]],\n        [[1,1],[2,2],[2,1]],\n        [[1,1],[2,2],[0,0]],\n        [[1,1],[2,1],[0,1]],\n        [[0,2],[2,1],[0,1]],\n        [[2,0],[1,2],[2,3]],\n        [[0,0],[0,3],[2,3]],\n        [[1,3],[2,0],[2,3]],\n        [[2,3],[0,0],[1,2]],\n        [[1,2],[2,0],[0,1]],\n        [[0,0],[1,2],[1,1]],\n        [[0,1],[1,2],[1,1]],\n        [[0,2],[2,0],[0,1]],\n      ]\n      for(p=[1,1],i=38;i--;)p=[...p,p[l=p.length-1]+p[l-1]]\n      phi = p[l]/p[l-1]\n      a = [\n        [-phi,-1,0],\n        [phi,-1,0],\n        [phi,1,0],\n        [-phi,1,0],\n      ]\n      for(j=3;j--;ret=[...ret, b])for(b=[],i=4;i--;) b = [...b, [a[i][j],a[i][(j+1)%3],a[i][(j+2)%3]]]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]*=size/2.25\n          q[1]*=size/2.25\n          q[2]*=size/2.25\n        })\n      })\n      cp = JSON.parse(JSON.stringify(ret))\n      out=[]\n      a = []\n      B.map(v=>{\n        idx1a = v[0][0]\n        idx2a = v[1][0]\n        idx3a = v[2][0]\n        idx1b = v[0][1]\n        idx2b = v[1][1]\n        idx3b = v[2][1]\n        a = [...a, [cp[idx1a][idx1b],cp[idx2a][idx2b],cp[idx3a][idx3b]]]\n      })\n      out = [...out, ...a]\n      return out\n    }\n    \n    stroke = (scol, fcol, lwo=1, od=true, oga=1) => {\n      if(scol){\n        x.closePath()\n        if(od) x.globalAlpha = .2*oga\n        x.strokeStyle = scol\n        x.lineWidth = Math.min(1000,100*lwo/Z)\n        if(od) x.stroke()\n        x.lineWidth /= 4\n        x.globalAlpha = 1*oga\n        x.stroke()\n      }\n      if(fcol){\n        x.globalAlpha = 1*oga\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n    \n    subbed = (subs, size, sphereize, shape) => {\n      for(let m=subs; m--;){\n        base = shape\n        shape = []\n        base.map(v=>{\n          l = 0\n          X1 = v[l][0]\n          Y1 = v[l][1]\n          Z1 = v[l][2]\n          l = 1\n          X2 = v[l][0]\n          Y2 = v[l][1]\n          Z2 = v[l][2]\n          l = 2\n          X3 = v[l][0]\n          Y3 = v[l][1]\n          Z3 = v[l][2]\n          if(v.length > 3){\n            l = 3\n            X4 = v[l][0]\n            Y4 = v[l][1]\n            Z4 = v[l][2]\n            if(v.length > 4){\n              l = 4\n              X5 = v[l][0]\n              Y5 = v[l][1]\n              Z5 = v[l][2]\n            }\n          }\n          mx1 = (X1+X2)/2\n          my1 = (Y1+Y2)/2\n          mz1 = (Z1+Z2)/2\n          mx2 = (X2+X3)/2\n          my2 = (Y2+Y3)/2\n          mz2 = (Z2+Z3)/2\n          a = []\n          switch(v.length){\n            case 3:\n              mx3 = (X3+X1)/2\n              my3 = (Y3+Y1)/2\n              mz3 = (Z3+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 4:\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X1)/2\n              my4 = (Y4+Y1)/2\n              mz4 = (Z4+Z1)/2\n              cx = (X1+X2+X3+X4)/4\n              cy = (Y1+Y2+Y3+Y4)/4\n              cz = (Z1+Z2+Z3+Z4)/4\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 5:\n              cx = (X1+X2+X3+X4+X5)/5\n              cy = (Y1+Y2+Y3+Y4+Y5)/5\n              cz = (Z1+Z2+Z3+Z4+Z5)/5\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X5)/2\n              my4 = (Y4+Y5)/2\n              mz4 = (Z4+Z5)/2\n              mx5 = (X5+X1)/2\n              my5 = (Y5+Y1)/2\n              mz5 = (Z5+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              break\n          }\n        })\n      }\n      if(sphereize){\n        ip1 = sphereize\n        ip2 = 1-sphereize\n        shape = shape.map(v=>{\n          v = v.map(q=>{\n            X = q[0]\n            Y = q[1]\n            Z = q[2]\n            d = Math.hypot(X,Y,Z)\n            X /= d\n            Y /= d\n            Z /= d\n            X *= size*.75*ip1 + d*ip2\n            Y *= size*.75*ip1 + d*ip2\n            Z *= size*.75*ip1 + d*ip2\n            return [X,Y,Z]\n          })\n          return v\n        })\n      }\n      return shape\n    }\n    \n    subDividedIcosahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Icosahedron(size))\n    subDividedTetrahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Tetrahedron(size))\n    subDividedOctahedron   = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Octahedron(size))\n    subDividedCube         = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Cube(size))\n    subDividedDodecahedron = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Dodecahedron(size))\n    \n    Rn = Math.random\n    \n    LsystemRecurse = (size, splits, p1, p2, stem, theta, LsystemReduction, twistFactor) => {\n      if(size < .25) return\n      let X1 = stem[0]\n      let Y1 = stem[1]\n      let Z1 = stem[2]\n      let X2 = stem[3]\n      let Y2 = stem[4]\n      let Z2 = stem[5]\n      let p1a = Math.atan2(X2-X1,Z2-Z1)\n      let p2a = -Math.acos((Y2-Y1)/(Math.hypot(X2-X1,Y2-Y1,Z2-Z1)+.0001))+Math.PI\n      size/=LsystemReduction\n      for(let i=splits;i--;){\n        X = 0\n        Y = -size\n        Z = 0\n        R(0, theta, 0)\n        R(0, 0, Math.PI*2/splits*i+twistFactor)\n        R(0, p2a, 0)\n        R(0, 0, p1a+twistFactor)\n        X+=X2\n        Y+=Y2\n        Z+=Z2\n        let newStem = [X2, Y2, Z2, X, Y, Z]\n        Lshp = [...Lshp, newStem]\n        LsystemRecurse(size, splits, p1+Math.PI*2/splits*i+twistFactor, p2+theta, newStem, theta, LsystemReduction, twistFactor)\n      }\n    }\n    DrawLsystem = shp => {\n      shp.map(v=>{\n        x.beginPath()\n        X = v[0]\n        Y = v[1]\n        Z = v[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        X = v[3]\n        Y = v[4]\n        Z = v[5]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        lwo = Math.hypot(v[0]-v[3],v[1]-v[4],v[2]-v[5])*4\n        stroke(\'#0f82\',\'\',lwo)\n      })\n      \n    }\n    Lsystem = (size, splits, theta, LsystemReduction, twistFactor) => {\n      Lshp = []\n      stem = [0,0,0,0,-size,0]\n      Lshp = [...Lshp, stem]\n      LsystemRecurse(size, splits, 0, 0, stem, theta, LsystemReduction, twistFactor)\n      Lshp.map(v=>{\n        v[1]+=size*1.5\n        v[4]+=size*1.5\n      })\n      return Lshp\n    }\n    \n    Sphere = (ls, rw, cl) => {\n      a = []\n      ls/=1.25\n      for(j = rw; j--;){\n        for(i = cl; i--;){\n          b = []\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          a = [...a, b]\n        }\n      }\n      return a\n    }\n    \n    Torus = (rw, cl, ls1, ls2, parts=1, twists=0, part_spacing=1.5) => {\n      let ret = [], tx=0, ty=0, tz=0\n      for(let m=parts;m--;){\n        avgs = Array(rw).fill().map(v=>[0,0,0])\n        for(j=rw;j--;)for(let i = cl;i--;){\n          if(parts>1){\n            ls3 = ls1*part_spacing\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl1 = Math.PI*2/rw*(j-1)*twists,0,0)\n            tx1 = X\n            ty1 = Y \n            tz1 = Z\n            R(0, 0, Math.PI*2/rw*(j-1))\n            ax1 = X\n            ay1 = Y\n            az1 = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl2 = Math.PI*2/rw*(j)*twists,0,0)\n            tx2 = X\n            ty2 = Y\n            tz2 = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax2 = X\n            ay2 = Y\n            az2 = Z\n            p1a = Math.atan2(ax2-ax1,az2-az1)\n            p2a = Math.PI/2+Math.acos((ay2-ay1)/(Math.hypot(ax2-ax1,ay2-ay1,az2-az1)+.001))\n\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j)*twists,0,0)\n            tx1b = X\n            ty1b = Y\n            tz1b = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax1b = X\n            ay1b = Y\n            az1b = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j+1)*twists,0,0)\n            tx2b = X\n            ty2b = Y\n            tz2b = Z\n            R(0, 0, Math.PI*2/rw*(j+1))\n            ax2b = X\n            ay2b = Y\n            az2b = Z\n            p1b = Math.atan2(ax2b-ax1b,az2b-az1b)\n            p2b = Math.PI/2+Math.acos((ay2b-ay1b)/(Math.hypot(ax2b-ax1b,ay2b-ay1b,az2b-az1b)+.001))\n          }\n          a = []\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          ret = [...ret, a]\n        }\n      }\n      return ret\n    }\n\n    G_ = 100000, iSTc = 1e4\n    ST = Array(iSTc).fill().map(v=>{\n      X = (Rn()-.5)*G_\n      Y = (Rn()-.5)*G_\n      Z = (Rn()-.5)*G_\n      return [X,Y,Z]\n    })\n    \n    burst = new Image()\n    burst.src = \"https://srmcgann.github.io/temp/burst.png\"\n    starsLoaded = false, starImgs = [{loaded: false}]\n    starImgs = Array(10).fill().map((v,i) => {\n      let a = {img: new Image(), loaded: false}\n      a.img.onload = () => {\n        a.loaded = true\n        setTimeout(()=>{\n          if(starImgs.filter(v=>v.loaded).length == 10) starsLoaded = true\n        }, 0)\n      }\n      a.img.src = `https://srmcgann.github.io/temp/stars/star${i?i:\'\'}.png`\n      return a\n    })\n    \n    showStars = true\n\n    base_shp = []\n    a = []\n    sd = 3\n    for(i=sd;i--;){\n      X = S(p=Math.PI*2/sd*i + Math.PI/sd) /2\n      Y = C(p) * 2\n      Z = 0\n      a = [...a, [X,Y,Z]]\n    }\n    base_shp = [...base_shp, a]\n    tgtDepth = 4\n    recurseFronds = (tx, ty, tz, depth, theta, px, py, pz) => {\n      if(depth>tgtDepth) return\n      let a = JSON.parse(JSON.stringify(base_shp))\n      let ls = 1/(1+depth*1.2)\n      a.map((v,i)=>{\n        v.map(q => {\n         X = q[0] * ls\n         Y = q[1] * ls\n         Z = q[2] * ls\n         let p_ = Math.PI-Math.atan2(px-tx,py-ty)/10\n         R(theta+p_,0,0)\n         q[0] = X += tx\n         q[1] = Y += ty\n         q[2] = Z += tz\n         \n         recurseFronds(X, Y, Z, depth+1, theta+p_, tx, ty, tz)\n        })\n      })\n      fronds = [...fronds, ...a]\n    }\n  }\n  \n  oX=0, oY=0, oZ=5\n  Rl=C(t)/4, Pt=-.4-C(t)/3, Yw=S(t/4)*4\n  \n  x.globalAlpha = 1\n  x.fillStyle=\'#000C\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin = x.lineCap = \'roud\'\n\n  fronds = []\n  recurseFronds(0, .5, 0, 0, 0, 0, .5, 0)\n  fronds = [...fronds, ...JSON.parse(JSON.stringify(fronds)).map(v=>{\n    v.map(q=>{\n      X = q[0]\n      Y = q[1]\n      Z = q[2]\n      R(0,0,Math.PI/2)\n      q[0] = X\n      q[1] = Y\n      q[2] = Z\n    })\n    return v\n  })]\n\n  if(showStars) ST.map(v=>{\n    X = v[0]\n    Y = v[1]\n    Z = v[2]\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      if((x.globalAlpha = Math.min(1,(Z/5e3)**2))>.1){\n        s = Math.min(1e3, 4e5/Z)\n        x.fillStyle = \'#ffffff04\'\n        l = Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=5\n        x.fillStyle = \'#fffa\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n    }\n  })\n\n  x.globalAlpha = 1\n\n  fronds.map(v=>{\n    x.beginPath()\n    v.map(q=>{\n      X = q[0]\n      Y = -q[1]\n      Z = q[2]\n      R(Rl,Pt,Yw,1)\n      if(Z>0) x.lineTo(...Q())\n    })\n    stroke(\'\', \'#4f82\', 1, false)\n  })\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  overflow: hidden;\n}\n#c{\n  background:#000;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'new', 145, 'whitehot robot', '2023-09-20 19:18:23', '[600749,600748,600747,600746,600745,600744,600743,600742,600741,600740,600739,600738,600737,600736,600735,600730,600729,600728]', 12, '', 0, 1),
(600753, '', 'c         = document.querySelector(\'#c\')\nc.width   = 1920\nc.height  = 1080\nx         = c.getContext(\'2d\')\nM         = Math\nS         = M.sin\nC         = M.cos\nT         = M.tan\nt         = 0\n\nrsz=window.onresize=()=>{\n  let body = document.body\n  let ar1 = 1.777778\n  let ar2 = body.clientWidth/body.clientHeight\n  if(ar1<ar2){\n    c.style.height = body.clientHeight + \'px\'\n    setTimeout(()=>{c.style.width = c.clientHeight*ar1+\'px\'},0)\n  } else {\n    c.style.width  = body.clientWidth + \'px\'\n    setTimeout(()=>{c.style.height = c.clientWidth/ar1+\'px\'},0)\n  }\n}\nrsz()\n\n\nasync function Draw(){\n  if(!t){\n    Rn = M.random\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=M.atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m){X+=oX,Y+=oY,Z+=oZ}}\n    Q=()=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n    Cube = (size=1) => {\n      let Cb=[]\n      for(i=6;i--;Cb=[...Cb,b])for(b=[],j=4;j--;)b=[...b,[(a=[S(p=Math.PI*2/4*j+Math.PI/4),C(p),2**.5/2])[i%3]*(l=i<3?-size:size),a[(i+1)%3]*l,a[(i+2)%3]*l]]\n      return Cb\n    }\n    stroke = (scol, fcol,lw=1,dual=true) => {\n      if(scol){\n        x.closePath()\n        x.strokeStyle = scol\n        x.lineWidth = Math.min(150, 200/Z*lw)\n        x.globalAlpha = dual?.25:1\n        x.stroke()\n        if(dual){\n          x.globalAlpha = 1\n          x.lineWidth/=3\n          x.stroke()\n        }\n        x.globalAlpha = 1\n      }\n      if(fcol){\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n\n\n    rfunc = i => {\n      R(Math.PI*2/br*(i/cl/rw|0)-S(t/4)*32,C(t/4)*4,0)\n    }\n\n    spawnB = () => {\n      cubeSize = 2\n      shp = Cube(cubeSize+C(t*4)*cubeSize/2)\n      rw=1\n      cl=2\n      br=10\n      sp=cubeSize * 8\n      B=Array(rw*br*cl).fill().map((v,i)=>{\n        X = ((i%cl)-cl/2+.5)*sp\n        Y = (((i/cl|0)%rw)-rw/2+.5)*sp\n        Z = ((i/cl/rw|0)-br/2+.5)*sp/4\n        rfunc(i)\n        return [X,Y,Z]\n      })\n    }\n\n    colFunc = i => `hsla(${t*3e3+90/br*(i/rw/cl|0)},99%,${200+C(t)*150}%,.3)`\n\n\n    P = []\n    iPfreq = 35+S(t)*30\n    spawnP = () =>{\n      iPv = S(t*2)/4\n      \n      for(O=3;O--;) B.map((n,i)=>{\n        tx = n[0]\n        ty = n[1]\n        tz = n[2]\n        shp.map(v=>{\n          v.map((q,m) => {\n            l = m\n            X = v[l][0]\n            Y = v[l][1]\n            Z = v[l][2]\n            rfunc(i)\n            X1 = X+tx\n            Y1 = Y+ty\n            Z1 = Z+tz\n\n            l = (m+1)%v.length\n            X = v[l][0]\n            Y = v[l][1]\n            Z = v[l][2]\n            rfunc(i)\n            X2 = X+tx\n            Y2 = Y+ty\n            Z2 = Z+tz\n\n            vx1 = X1-X2\n            vy1 = Y1-Y2\n            vz1 = Z1-Z2\n            d = Math.hypot(vx1,vy1,vz1)\n            vx1/=d\n            vy1/=d\n            vz1/=d\n            vx1*=iPv\n            vy1*=iPv\n            vz1*=iPv\n            vx1+=(Rn()-.5)/50\n            vy1+=(Rn()-.5)/50\n            vz1+=(Rn()-.5)/50\n\n            vx2 = -vx1\n            vy2 = -vy1\n            vz2 = -vz1\n            if(Rn()<.4){\n              col = colFunc(i)\n              P = [...P, [X1, Y1, Z1, vx1, vy1, vz1, 1, col]]\n              P = [...P, [X2, Y2, Z2, vx2, vy2, vz2, 1, col]]\n            }\n          })\n        })\n      })\n    }\n    bg = document.createElement(\'video\')\n    go = false\n    bg.oncanplay= () => {\n      bg.play()\n      go = true\n    }\n\n    bg.loop = true\n    bg.muted = true\n    bg.src = \'https://i.imgur.io/aAlFWzJ.mp4\'\n\n  }\n  x.globalAlpha = .4\n  if(go) x.drawImage(bg,0,0,c.width,c.height)\n  x.globalAlpha = 1\n  x.fillStyle = \'#0002\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin=x.lineCap=\'round\'\n\n  oX=oY=0, oZ=Math.min(30, Math.max(20,(.3+C(t/2))*60))\n  Rl=t/4,Pt=-t/4, Yw=S(t/4)*2\n\n  spawnB()\n\n  B.map((n,i)=>{\n    tx = n[0]\n    ty = n[1]\n    tz = n[2]\n    shp.map(v=>{\n      x.beginPath()\n      v.map(q=>{\n        X = q[0]\n        Y = q[1]\n        Z = q[2]\n        rfunc(i)\n        X+=tx\n        Y+=ty\n        Z+=tz\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n      })\n      col1 = \'#fff4\'\n      col2 = colFunc(i)\n      stroke(col1, col2, 4, 1)\n    })\n  })\n\n  iPfreq = 15+S(t*2)*11|0\n  if(!((t*60|0)%iPfreq)) spawnP()\n\n  P = P.filter(v=>v[6]>.1)\n  P.map(v=>{\n    X = v[0] += v[3]\n    Y = v[1] += v[4]\n    Z = v[2] += v[5]\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      l = Q()\n      s = Math.min(1e3, 2e3/Z*v[6])\n      x.globalAlpha = .1\n      x.fillStyle = v[7]\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      s/=3\n      x.globalAlpha = .2\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      s/=3\n      x.globalAlpha = 1\n      x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n    }\n    v[6] -= .025\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  margin: 0;\n  background: #000;\n  height: 100vh;\n  width: 100vw;\n  border: none;\n  overflow: hidden;\n}\n#c{\n  background: #000;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n  border: 1px solid #4f82;\n}\n', '<canvas id=c></canvas>', 'i don\'t even know', 145, 'whitehot robot', '2023-12-16 23:39:26', '', 49, '', 0, 0),
(600754, '', 'c=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=playing=0\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height = c.clientWidth/1.77777778 + \'px\',0)\n    }\n    c.width=1920\n    c.height=c.width/1.777777778\n  },0)\n}\nrsz()\nDraw=()=>{\n  if(!t){\n    Rn=Math.random\n    R=(Rl,Pt,Yw,m)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(m)X+=oX,Y+=oY,Z+=oZ}\n    Q=()=>[c.width/2+X/Z*600,c.height/2+Y/Z*600]\n    stroke = (scol, fcol, lw = 1, dual=true) => {\n      if(scol){\n        x.strokeStyle = scol\n        x.lineWidth = Math.min(1e3, 400/Z*lw)\n        if(dual){\n          x.globalAlpha = .2\n          x.stroke()\n          x.lineWidth  /= 5\n        }\n        x.globalAlpha = 1\n        x.stroke()\n      }\n      if(fcol){\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n  }\n  x.lineJoin=x.lineCap=\'round\'\n  x.globalAlpha=1\n  x.fillStyle=\'#0002\'\n  x.fillRect(0,0,c.width,c.height)\n  Rl=0;Pt=Math.PI/2+t;Yw=-C(t/2)*5.3333\n  oX=0,oY=0,oZ=30\n\n  w  = 32\n  sd = 300\n  twists = 3\n  ls2 = 6\n  for(i=sd;i--;){\n    let p\n    X = 0\n    Y = -S(p=C(t/2)*16+Math.PI*2/sd*i*twists) * 5-w/2\n    Z = -C(p) * ls2\n    R(Math.PI*2/sd*i,0,0)\n    R(Rl,Pt,Yw,1)\n    x.beginPath()\n    ax1=ay1=ax1=0\n    if(Z>0){\n      ax1 = X\n      ay1 = Y\n      az1 = Z\n      l=Q()\n      x.beginPath()\n      s = Math.min(1e4, 2e3/Z)\n      x.arc(...l,s,0,7)\n      x.fillStyle = \'#00ffff02\'\n      x.fill()\n      x.beginPath()\n      s /= 5\n      x.arc(...l,s,0,7)\n      x.fillStyle = \'#00ffff10\'\n      x.fill()\n    }\n    X = 0\n    Y = S(p) * 5-w/2\n    Z = C(p) * ls2\n    R(Math.PI*2/sd*i,0,0)\n    R(Rl,Pt,Yw,1)\n    ax2=ay2=az2=0\n    if(Z>0){\n      ax2 = X\n      ay2 = Y\n      az2 = Z\n      l=Q()\n      x.beginPath()\n      s = Math.min(1e4, 2e3/Z)\n      x.arc(...l,s,0,7)\n      x.fillStyle = \'#ff008802\'\n      x.fill()\n      x.beginPath()\n      s /= 5\n      x.arc(...l,s,0,7)\n      x.fillStyle = \'#ff008810\'\n      x.fill()\n    }\n    if(!((t*60|0)%(10+S(t)*10|0))){\n      X=ax1\n      Y=ay2\n      Z=az1\n      x.beginPath()\n      x.lineTo(...Q())\n      X=ax2\n      Y=ay2\n      Z=az2\n      x.lineTo(...Q())\n      stroke(`hsla(${t*5000+360/sd*i/2},99%,${200+S(t)*150}%,.3)`,\'\',2)\n    }\n  }\n  \n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()\n', 'body,html{\n  margin: 0;\n  background: #000;\n  height: 100vh;\n  width: 100vw;\n  border: none;\n  overflow: hidden;\n}\n#c{\n  background: #000;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n  border: 1px solid #4f82;\n}\n', '<canvas id=c></canvas>', 'this', 145, 'whitehot robot', '2023-12-19 00:35:00', '[600753]', 48, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600755, '', 'c = document.querySelector(\'#c\')\nc.width = 1920\nc.height = 1080\nx = c.getContext(\'2d\')\nC = Math.cos\nS = Math.sin\nt = 0\nT = Math.tan\n\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height =     c.clientWidth/1.77777778 + \'px\',0)\n    }\n  },0)\n}\nrsz()\n\nasync function Draw(){\n  oX=oY=oZ=0\n  if(!t){\n          HSVFromRGB = (R, G, B) => {\n            let R_=R/256\n            let G_=G/256\n            let B_=B/256\n            let Cmin = Math.min(R_,G_,B_)\n            let Cmax = Math.max(R_,G_,B_)\n            let val = Cmax //(Cmax+Cmin) / 2\n            let delta = Cmax-Cmin\n            let sat = Cmax ? delta / Cmax: 0\n            let min=Math.min(R,G,B)\n            let max=Math.max(R,G,B)\n            let hue = 0\n            if(delta){\n              if(R>=G && R>=B) hue = (G-B)/(max-min)\n              if(G>=R && G>=B) hue = 2+(B-R)/(max-min)\n              if(B>=G && B>=R) hue = 4+(R-G)/(max-min)\n            }\n            hue*=60\n            while(hue<0) hue+=360;\n            while(hue>=360) hue-=360;\n            return [hue, sat, val]\n          }\n\n          RGBFromHSV = (H, S, V) => {\n            while(H<0) H+=360;\n            while(H>=360) H-=360;\n            let C = V*S\n            let X = C * (1-Math.abs((H/60)%2-1))\n            let m = V-C\n            let R_, G_, B_\n            if(H>=0 && H < 60)    R_=C, G_=X, B_=0\n            if(H>=60 && H < 120)  R_=X, G_=C, B_=0\n            if(H>=120 && H < 180) R_=0, G_=C, B_=X\n            if(H>=180 && H < 240) R_=0, G_=X, B_=C\n            if(H>=240 && H < 300) R_=X, G_=0, B_=C\n            if(H>=300 && H < 360) R_=C, G_=0, B_=X\n            let R = (R_+m)*256\n            let G = (G_+m)*256\n            let B = (B_+m)*256\n            return [R,G,B]\n          }\n          \n          R=R2=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    \n    Rn = Math.random\n    async function loadOBJ(url, scale, tx, ty, tz, rl, pt, yw) {\n      let res\n      await fetch(url, res => res).then(data=>data.text()).then(data=>{\n        a=[]\n        data.split(\"\\nv \").map(v=>{\n          a=[...a, v.split(\"\\n\")[0]]\n        })\n        a=a.filter((v,i)=>i).map(v=>[...v.split(\' \').map(n=>(+n.replace(\"\\n\", \'\')))])\n        ax=ay=az=0\n        a.map(v=>{\n          v[1]*=-1\n          ax+=v[0]\n          ay+=v[1]\n          az+=v[2]\n        })\n        ax/=a.length\n        ay/=a.length\n        az/=a.length\n        a.map(v=>{\n          X=(v[0]-ax)*scale\n          Y=(v[1]-ay)*scale\n          Z=(v[2]-az)*scale\n          R2(rl,pt,yw,0)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n        })\n        maxY=-6e6\n        a.map(v=>{\n          if(v[1]>maxY)maxY=v[1]\n        })\n        a.map(v=>{\n          v[1]-=maxY-oY\n          v[0]+=tx\n          v[1]+=ty\n          v[2]+=tz\n        })\n\n        b=[]\n        data.split(\"\\nf \").map(v=>{\n          b=[...b, v.split(\"\\n\")[0]]\n        })\n        b.shift()\n        b=b.map(v=>v.split(\' \'))\n        b=b.map(v=>{\n          v=v.map(q=>{\n            return +q.split(\'/\')[0]\n          })\n          v=v.filter(q=>q)\n          return v\n        })\n        \n        res=[]\n        b.map(v=>{\n          e=[]\n          v.map(q=>{\n            e=[...e, a[q-1]]\n          })\n          e = e.filter(q=>q)\n          res=[...res, e]\n        })\n      })\n      return res\n    }\n\n    geoSphere = (mx, my, mz, iBc, size) => {\n      let collapse=0\n      let B=Array(iBc).fill().map(v=>{\n        X = Rn()-.5\n        Y = Rn()-.5\n        Z = Rn()-.5\n        return  [X,Y,Z]\n      })\n      for(let m=200;m--;){\n        B.map((v,i)=>{\n          X = v[0]\n          Y = v[1]\n          Z = v[2]\n          B.map((q,j)=>{\n            if(j!=i){\n              X2=q[0]\n              Y2=q[1]\n              Z2=q[2]\n              d=1+(Math.hypot(X-X2,Y-Y2,Z-Z2)*(3+iBc/40)*3)**4\n              X+=(X-X2)*99/d\n              Y+=(Y-Y2)*99/d\n              Z+=(Z-Z2)*99/d\n            }\n          })\n          d=Math.hypot(X,Y,Z)\n          v[0]=X/d\n          v[1]=Y/d\n          v[2]=Z/d\n          if(collapse){\n            d=25+Math.hypot(X,Y,Z)\n            v[0]=(X-X/d)/1.1\n            v[1]=(Y-Y/d)/1.1         \n            v[2]=(Z-Z/d)/1.1\n          }\n        })\n      }\n      mind = 6e6\n      B.map((v,i)=>{\n        X1 = v[0]\n        Y1 = v[1]\n        Z1 = v[2]\n        B.map((q,j)=>{\n          X2 = q[0]\n          Y2 = q[1]\n          Z2 = q[2]\n          if(i!=j){\n            d = Math.hypot(a=X1-X2, b=Y1-Y2, e=Z1-Z2)\n            if(d<mind) mind = d\n          }\n        })\n      })\n      a = []\n      B.map((v,i)=>{\n        X1 = v[0]\n        Y1 = v[1]\n        Z1 = v[2]\n        B.map((q,j)=>{\n          X2 = q[0]\n          Y2 = q[1]\n          Z2 = q[2]\n          if(i!=j){\n            d = Math.hypot(X1-X2, Y1-Y2, Z1-Z2)\n            if(d<mind*2){\n              if(!a.filter(q=>q[0]==X2&&q[1]==Y2&&q[2]==Z2&&q[3]==X1&&q[4]==Y1&&q[5]==Z1).length) a = [...a, [X1*size,Y1*size,Z1*size,X2*size,Y2*size,Z2*size]]\n            }\n          }\n        })\n      })\n      B.map(v=>{\n        v[0]*=size\n        v[1]*=size\n        v[2]*=size\n        v[0]+=mx\n        v[1]+=my\n        v[2]+=mz\n      })\n      return [mx, my, mz, size, B, a]\n    }\n\n    lineFaceI = (X1, Y1, Z1, X2, Y2, Z2, facet, autoFlipNormals=false, showNormals=false) => {\n      let X_, Y_, Z_, d, m, l_,K,J,L,p\n      let I_=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n      let Q_=()=>[c.width/2+X_/Z_*600,c.height/2+Y_/Z_*600]\n      let R_ = (Rl,Pt,Yw,m)=>{\n        let M=Math, A=M.atan2, H=M.hypot\n        X_=S(p=A(X_,Y_)+Rl)*(d=H(X_,Y_)),Y_=C(p)*d,X_=S(p=A(X_,Z_)+Yw)*(d=H(X_,Z_)),Z_=C(p)*d,Y_=S(p=A(Y_,Z_)+Pt)*(d=H(Y_,Z_)),Z_=C(p)*d\n        if(m){ X_+=oX,Y_+=oY,Z_+=oZ }\n      }\n      let rotSwitch = m =>{\n        switch(m){\n          case 0: R_(0,0,Math.PI/2); break\n          case 1: R_(0,Math.PI/2,0); break\n          case 2: R_(Math.PI/2,0,Math.PI/2); break\n        }        \n      }\n      let ax = 0, ay = 0, az = 0\n      facet.map(q_=>{ ax += q_[0], ay += q_[1], az += q_[2] })\n      ax /= facet.length, ay /= facet.length, az /= facet.length\n      let b1 = facet[2][0]-facet[1][0], b2 = facet[2][1]-facet[1][1], b3 = facet[2][2]-facet[1][2]\n      let c1 = facet[1][0]-facet[0][0], c2 = facet[1][1]-facet[0][1], c3 = facet[1][2]-facet[0][2]\n      let crs = [b2*c3-b3*c2,b3*c1-b1*c3,b1*c2-b2*c1]\n      d = Math.hypot(...crs)+.001\n      let nls = 1 //normal line length\n      crs = crs.map(q=>q/d*nls)\n      let X1_ = ax, Y1_ = ay, Z1_ = az\n      let flip = 1\n      if(autoFlipNormals){\n        let d1_ = Math.hypot(X1_-X1,Y1_-Y1,Z1_-Z1)\n        let d2_ = Math.hypot(X1-(ax + crs[0]/99),Y1-(ay + crs[1]/99),Z1-(az + crs[2]/99))\n        flip = d2_>d1_?-1:1\n      }\n      let X2_ = ax + (crs[0]*=flip), Y2_ = ay + (crs[1]*=flip), Z2_ = az + (crs[2]*=flip)\n      if(showNormals){\n        x.beginPath()\n        X_ = X1_, Y_ = Y1_, Z_ = Z1_\n        R_(Rl,Pt,Yw,1)\n        if(Z_>0) x.lineTo(...Q_())\n        X_ = X2_, Y_ = Y2_, Z_ = Z2_\n        R_(Rl,Pt,Yw,1)\n        if(Z_>0) x.lineTo(...Q_())\n        x.lineWidth = 5\n        x.strokeStyle=\'#f004\'\n        x.stroke()\n      }\n      \n      let p1_ = Math.atan2(X2_-X1_,Z2_-Z1_)\n      let p2_ = -(Math.acos((Y2_-Y1_)/(Math.hypot(X2_-X1_,Y2_-Y1_,Z2_-Z1_)+.001))+Math.PI/2)\n      let isc = false, iscs = [false,false,false]\n      X_ = X1, Y_ = Y1, Z_ = Z1\n      R_(0,-p2_,-p1_)\n      let rx_ = X_, ry_ = Y_, rz_ = Z_\n      for(let m=3;m--;){\n        if(isc === false){\n          X_ = rx_, Y_ = ry_, Z_ = rz_\n          rotSwitch(m)\n          X1_ = X_, Y1_ = Y_, Z1_ = Z_ = 5, X_ = X2, Y_ = Y2, Z_ = Z2\n          R_(0,-p2_,-p1_)\n          rotSwitch(m)\n          X2_ = X_, Y2_ = Y_, Z2_ = Z_\n          facet.map((q_,j_)=>{\n            if(isc === false){\n              let l = j_\n              X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n              R_(0,-p2_,-p1_)\n              rotSwitch(m)\n              let X3_=X_, Y3_=Y_, Z3_=Z_\n              l = (j_+1)%facet.length\n              X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n              R_(0,-p2_,-p1_)\n              rotSwitch(m)\n              let X4_ = X_, Y4_ = Y_, Z4_ = Z_\n              if(l_=I_(X1_,Y1_,X2_,Y2_,X3_,Y3_,X4_,Y4_)) iscs[m] = l_\n            }\n          })\n        }\n      }\n      if(iscs.filter(v=>v!==false).length==3){\n        let iscx = iscs[1][0], iscy = iscs[0][1], iscz = iscs[0][0]\n        let pointInPoly = true\n        ax=0, ay=0, az=0\n        facet.map((q_, j_)=>{ ax+=q_[0], ay+=q_[1], az+=q_[2] })\n        ax/=facet.length, ay/=facet.length, az/=facet.length\n        X_ = ax, Y_ = ay, Z_ = az\n        R_(0,-p2_,-p1_)\n        X1_ = X_, Y1_ = Y_, Z1_ = Z_\n        X2_ = iscx, Y2_ = iscy, Z2_ = iscz\n        facet.map((q_,j_)=>{\n          if(pointInPoly){\n            let l = j_\n            X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n            R_(0,-p2_,-p1_)\n            let X3_ = X_, Y3_ = Y_, Z3_ = Z_\n            l = (j_+1)%facet.length\n            X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n            R_(0,-p2_,-p1_)\n            let X4_ = X_, Y4_ = Y_, Z4_ = Z_\n            if(I_(X1_,Y1_,X2_,Y2_,X3_,Y3_,X4_,Y4_)) pointInPoly = false\n          }\n        })\n        if(pointInPoly){\n          X_ = iscx, Y_ = iscy, Z_ = iscz\n          R_(0,p2_,0)\n          R_(0,0,p1_)\n          isc = [[X_,Y_,Z_], [crs[0],crs[1],crs[2]]]\n        }\n      }\n      return isc\n    }\n    \n    TruncatedOctahedron = ls => {\n      let shp = [], a = []\n      mind = 6e6\n      for(let i=6;i--;){\n        X = S(p=Math.PI*2/6*i+Math.PI/6)*ls\n        Y = C(p)*ls\n        Z = 0\n        if(Y<mind) mind = Y\n        a = [...a, [X, Y, Z]]\n      }\n      let theta = .6154797086703867\n      a.map(v=>{\n        X = v[0]\n        Y = v[1] - mind\n        Z = v[2]\n        R(0,theta,0)\n        v[0] = X\n        v[1] = Y\n        v[2] = Z+1.5\n      })\n      b = JSON.parse(JSON.stringify(a)).map(v=>{\n        v[1] *= -1\n        return v\n      })\n      shp = [...shp, a, b]\n      e = JSON.parse(JSON.stringify(shp)).map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n        return v\n      })\n      shp = [...shp, ...e]\n      e = JSON.parse(JSON.stringify(shp)).map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n        return v\n      })\n      shp = [...shp, ...e]\n\n      coords = [\n        [[3,1],[4,3],[4,4],[3,2]],\n        [[3,4],[3,3],[2,4],[6,2]],\n        [[1,4],[0,3],[0,4],[4,2]],\n        [[1,1],[1,2],[6,4],[7,3]],\n        [[3,5],[7,5],[1,5],[3,0]],\n        [[2,5],[6,5],[0,5],[4,5]]\n      ]\n      a = []\n      coords.map(v=>{\n        b = []\n        v.map(q=>{\n          X = shp[q[0]][q[1]][0]\n          Y = shp[q[0]][q[1]][1]\n          Z = shp[q[0]][q[1]][2]\n          b = [...b, [X,Y,Z]]\n        })\n        a = [...a, b]\n      })\n      shp = [...shp, ...a]\n      return shp.map(v=>{\n        v.map(q=>{\n          q[0]/=3\n          q[1]/=3\n          q[2]/=3\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n        return v\n      })\n    }\n    \n    Cylinder = (rw,cl,ls1,ls2) => {\n      let a = []\n      for(let i=rw;i--;){\n        let b = []\n        for(let j=cl;j--;){\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n        }\n        //a = [...a, b]\n        for(let j=cl;j--;){\n          b = []\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(j+1)) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(j+1)) * ls1\n          Y = (1/rw*(i+1)-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*(i+1)-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          a = [...a, b]\n        }\n      }\n      b = []\n      for(let j=cl;j--;){\n        X = S(p=Math.PI*2/cl*j) * ls1\n        Y = ls2/2\n        Z = C(p) * ls1\n        b = [...b, [X,Y,Z]]\n      }\n      //a = [...a, b]\n      return a\n    }\n\n    Tetrahedron = size => {\n      ret = []\n      a = []\n      let h = size/1.4142/1.25\n      for(i=3;i--;){\n        X = S(p=Math.PI*2/3*i) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n      }\n      ret = [...ret, a]\n      for(j=3;j--;){\n        a = []\n        X = 0\n        Y = 0\n        Z = -h\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/3*j) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/3*(j+1)) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      ax=ay=az=ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax\n          q[1]-=ay\n          q[2]-=az\n        })\n      })\n      return ret\n    }\n\n    Cube = size => {\n      for(CB=[],j=6;j--;CB=[...CB,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?size/1.5:-size/1.5),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      return CB\n    }\n    \n    Octahedron = size => {\n      ret = []\n      let h = size/1.25\n      for(j=8;j--;){\n        a = []\n        X = 0\n        Y = 0\n        Z = h * (j<4?-1:1)\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*j) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*(j+1)) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      return ret      \n    }\n    \n    Dodecahedron = size => {\n      ret = []\n      a = []\n      mind = -6e6\n      for(i=5;i--;){\n        X=S(p=Math.PI*2/5*i + Math.PI/5)\n        Y=C(p)\n        Z=0\n        if(Y>mind) mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a.map(v=>{\n        X = v[0]\n        Y = v[1]-=mind\n        Z = v[2]\n        R(0, .553573, 0)\n        v[0] = X\n        v[1] = Y\n        v[2] = Z\n      })\n      b = JSON.parse(JSON.stringify(a))\n      b.map(v=>{\n        v[1] *= -1\n      })\n      ret = [...ret, a, b]\n      mind = -6e6\n      ret.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          if(Z>mind)mind = Z\n        })\n      })\n      d1=Math.hypot(ret[0][0][0]-ret[0][1][0],ret[0][0][1]-ret[0][1][1],ret[0][0][2]-ret[0][1][2])\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]-=mind+d1/2\n        })\n      })\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          q[2]*=-1\n        })\n      })\n      ret = [...ret, ...b]\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(0,Math.PI/2,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      e = JSON.parse(JSON.stringify(ret))\n      e.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(Math.PI/2,0,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      ret = [...ret, ...b, ...e]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0] *= size/2\n          q[1] *= size/2\n          q[2] *= size/2\n        })\n      })\n      return ret\n    }\n    \n    Icosahedron = size => {\n      ret = []\n      let B = [\n        [[0,3],[1,0],[2,2]],\n        [[0,3],[1,0],[1,3]],\n        [[0,3],[2,3],[1,3]],\n        [[0,2],[2,1],[1,0]],\n        [[0,2],[1,3],[1,0]],\n        [[0,2],[1,3],[2,0]],\n        [[0,3],[2,2],[0,0]],\n        [[1,0],[2,2],[2,1]],\n        [[1,1],[2,2],[2,1]],\n        [[1,1],[2,2],[0,0]],\n        [[1,1],[2,1],[0,1]],\n        [[0,2],[2,1],[0,1]],\n        [[2,0],[1,2],[2,3]],\n        [[0,0],[0,3],[2,3]],\n        [[1,3],[2,0],[2,3]],\n        [[2,3],[0,0],[1,2]],\n        [[1,2],[2,0],[0,1]],\n        [[0,0],[1,2],[1,1]],\n        [[0,1],[1,2],[1,1]],\n        [[0,2],[2,0],[0,1]],\n      ]\n      for(p=[1,1],i=38;i--;)p=[...p,p[l=p.length-1]+p[l-1]]\n      phi = p[l]/p[l-1]\n      a = [\n        [-phi,-1,0],\n        [phi,-1,0],\n        [phi,1,0],\n        [-phi,1,0],\n      ]\n      for(j=3;j--;ret=[...ret, b])for(b=[],i=4;i--;) b = [...b, [a[i][j],a[i][(j+1)%3],a[i][(j+2)%3]]]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]*=size/2.25\n          q[1]*=size/2.25\n          q[2]*=size/2.25\n        })\n      })\n      cp = JSON.parse(JSON.stringify(ret))\n      out=[]\n      a = []\n      B.map(v=>{\n        idx1a = v[0][0]\n        idx2a = v[1][0]\n        idx3a = v[2][0]\n        idx1b = v[0][1]\n        idx2b = v[1][1]\n        idx3b = v[2][1]\n        a = [...a, [cp[idx1a][idx1b],cp[idx2a][idx2b],cp[idx3a][idx3b]]]\n      })\n      out = [...out, ...a]\n      return out\n    }\n    \n    stroke = (scol, fcol, lwo=1, od=true, oga=1) => {\n      if(scol){\n        //x.closePath()\n        if(od) x.globalAlpha = .2*oga\n        x.strokeStyle = scol\n        x.lineWidth = Math.min(1000,100*lwo/Z)\n        if(od) x.stroke()\n        x.lineWidth /= 4\n        x.globalAlpha = 1*oga\n        x.stroke()\n      }\n      if(fcol){\n        x.globalAlpha = 1*oga\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n    \n    subbed = (subs, size, sphereize, shape) => {\n      for(let m=subs; m--;){\n        base = shape\n        shape = []\n        base.map(v=>{\n          l = 0\n          X1 = v[l][0]\n          Y1 = v[l][1]\n          Z1 = v[l][2]\n          l = 1\n          X2 = v[l][0]\n          Y2 = v[l][1]\n          Z2 = v[l][2]\n          l = 2\n          X3 = v[l][0]\n          Y3 = v[l][1]\n          Z3 = v[l][2]\n          if(v.length > 3){\n            l = 3\n            X4 = v[l][0]\n            Y4 = v[l][1]\n            Z4 = v[l][2]\n            if(v.length > 4){\n              l = 4\n              X5 = v[l][0]\n              Y5 = v[l][1]\n              Z5 = v[l][2]\n            }\n          }\n          mx1 = (X1+X2)/2\n          my1 = (Y1+Y2)/2\n          mz1 = (Z1+Z2)/2\n          mx2 = (X2+X3)/2\n          my2 = (Y2+Y3)/2\n          mz2 = (Z2+Z3)/2\n          a = []\n          switch(v.length){\n            case 3:\n              mx3 = (X3+X1)/2\n              my3 = (Y3+Y1)/2\n              mz3 = (Z3+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 4:\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X1)/2\n              my4 = (Y4+Y1)/2\n              mz4 = (Z4+Z1)/2\n              cx = (X1+X2+X3+X4)/4\n              cy = (Y1+Y2+Y3+Y4)/4\n              cz = (Z1+Z2+Z3+Z4)/4\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 5:\n              cx = (X1+X2+X3+X4+X5)/5\n              cy = (Y1+Y2+Y3+Y4+Y5)/5\n              cz = (Z1+Z2+Z3+Z4+Z5)/5\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X5)/2\n              my4 = (Y4+Y5)/2\n              mz4 = (Z4+Z5)/2\n              mx5 = (X5+X1)/2\n              my5 = (Y5+Y1)/2\n              mz5 = (Z5+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              break\n          }\n        })\n      }\n      if(sphereize){\n        ip1 = sphereize\n        ip2 = 1-sphereize\n        shape = shape.map(v=>{\n          v = v.map(q=>{\n            X = q[0]\n            Y = q[1]\n            Z = q[2]\n            d = Math.hypot(X,Y,Z)\n            X /= d\n            Y /= d\n            Z /= d\n            X *= size*.75*ip1 + d*ip2\n            Y *= size*.75*ip1 + d*ip2\n            Z *= size*.75*ip1 + d*ip2\n            return [X,Y,Z]\n          })\n          return v\n        })\n      }\n      return shape\n    }\n    \n    subDividedIcosahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Icosahedron(size))\n    subDividedTetrahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Tetrahedron(size))\n    subDividedOctahedron   = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Octahedron(size))\n    subDividedCube         = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Cube(size))\n    subDividedDodecahedron = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Dodecahedron(size))\n    \n    Rn = Math.random\n    \n    LsystemRecurse = (size, splits, p1, p2, stem, theta, LsystemReduction, twistFactor) => {\n      if(size < .25) return\n      let X1 = stem[0]\n      let Y1 = stem[1]\n      let Z1 = stem[2]\n      let X2 = stem[3]\n      let Y2 = stem[4]\n      let Z2 = stem[5]\n      let p1a = Math.atan2(X2-X1,Z2-Z1)\n      let p2a = -Math.acos((Y2-Y1)/(Math.hypot(X2-X1,Y2-Y1,Z2-Z1)+.0001))+Math.PI\n      size/=LsystemReduction\n      for(let i=splits;i--;){\n        X = 0\n        Y = -size\n        Z = 0\n        R(0, theta, 0)\n        R(0, 0, Math.PI*2/splits*i+twistFactor)\n        R(0, p2a, 0)\n        R(0, 0, p1a+twistFactor)\n        X+=X2\n        Y+=Y2\n        Z+=Z2\n        let newStem = [X2, Y2, Z2, X, Y, Z]\n        Lshp = [...Lshp, newStem]\n        LsystemRecurse(size, splits, p1+Math.PI*2/splits*i+twistFactor, p2+theta, newStem, theta, LsystemReduction, twistFactor)\n      }\n    }\n    DrawLsystem = shp => {\n      shp.map(v=>{\n        x.beginPath()\n        X = v[0]\n        Y = v[1]\n        Z = v[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        X = v[3]\n        Y = v[4]\n        Z = v[5]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        lwo = Math.hypot(v[0]-v[3],v[1]-v[4],v[2]-v[5])*4\n        stroke(\'#0f82\',\'\',lwo)\n      })\n      \n    }\n    Lsystem = (size, splits, theta, LsystemReduction, twistFactor) => {\n      Lshp = []\n      stem = [0,0,0,0,-size,0]\n      Lshp = [...Lshp, stem]\n      LsystemRecurse(size, splits, 0, 0, stem, theta, LsystemReduction, twistFactor)\n      Lshp.map(v=>{\n        v[1]+=size*1.5\n        v[4]+=size*1.5\n      })\n      return Lshp\n    }\n    \n    Sphere = (ls, rw, cl) => {\n      a = []\n      ls/=1.25\n      for(j = rw; j--;){\n        for(i = cl; i--;){\n          b = []\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          a = [...a, b]\n        }\n      }\n      return a\n    }\n    \n    Torus = (rw, cl, ls1, ls2, parts=1, twists=0, part_spacing=1.5) => {\n      let ret = [], tx=0, ty=0, tz=0, prl1 = 0, p2a = 0\n      let tx1 = 0, ty1 = 0, tz1 = 0, prl2 = 0, p2b = 0, tx2 = 0, ty2 = 0, tz2 = 0\n      for(let m=parts;m--;){\n        avgs = Array(rw).fill().map(v=>[0,0,0])\n        for(j=rw;j--;)for(let i = cl;i--;){\n          if(parts>1){\n            ls3 = ls1*part_spacing\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl1 = Math.PI*2/rw*(j-1)*twists,0,0)\n            tx1 = X\n            ty1 = Y \n            tz1 = Z\n            R(0, 0, Math.PI*2/rw*(j-1))\n            ax1 = X\n            ay1 = Y\n            az1 = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl2 = Math.PI*2/rw*(j)*twists,0,0)\n            tx2 = X\n            ty2 = Y\n            tz2 = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax2 = X\n            ay2 = Y\n            az2 = Z\n            p1a = Math.atan2(ax2-ax1,az2-az1)\n            p2a = Math.PI/2+Math.acos((ay2-ay1)/(Math.hypot(ax2-ax1,ay2-ay1,az2-az1)+.001))\n\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j)*twists,0,0)\n            tx1b = X\n            ty1b = Y\n            tz1b = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax1b = X\n            ay1b = Y\n            az1b = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j+1)*twists,0,0)\n            tx2b = X\n            ty2b = Y\n            tz2b = Z\n            R(0, 0, Math.PI*2/rw*(j+1))\n            ax2b = X\n            ay2b = Y\n            az2b = Z\n            p1b = Math.atan2(ax2b-ax1b,az2b-az1b)\n            p2b = Math.PI/2+Math.acos((ay2b-ay1b)/(Math.hypot(ax2b-ax1b,ay2b-ay1b,az2b-az1b)+.001))\n          }\n          a = []\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          ret = [...ret, a]\n        }\n      }\n      return ret\n    }\n\n    G_ = 8e5, iSTc = 500\n    ST = Array(iSTc).fill().map(v=>{\n      ls = G_*.25 + Rn()**.5 * (G_*.75)\n      X = S(p=Math.PI*2*Rn()) * S(q=Rn()<.5?Rn()**.5*Math.PI/2:Math.PI-Rn()**.5*Math.PI/2) * ls\n      Y = C(q) * ls\n      Z = C(p) * S(q) * ls\n      return [X,Y,Z,[],Rn()<.1, Rn()<.33, Rn()*9|0]\n    })\n    \n    burst = new Image()\n    burst.src = \"https://srmcgann.github.io/temp/burst.png\"\n    \n    starsLoaded = false, starImgs = [{loaded: false}]\n    starImgs = Array(9).fill().map((v,i) => {\n      let a = {img: new Image(), loaded: false}\n      a.img.onload = () => {\n        a.loaded = true\n        setTimeout(()=>{\n          if(starImgs.filter(v=>v.loaded).length == 9) starsLoaded = true\n        }, 0)\n      }\n      a.img.src = `https://srmcgann.github.io/stars/star${i+1}.png`\n      return a\n    })\n    \n    showstars = true\n  }\n  \n  oX=0, oY=0, oZ=40//Math.min(40,Math.max(25, (.3+C(t/2))*200))\n  Rl=S(t/8)/3, Pt=-C(t/2)/1, Yw=C(t/2)\n  \n  x.globalAlpha = 1\n  x.fillStyle=\'#000C\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin = x.lineCap = \'round\'\n  \n  ip1 = Math.min(1,Math.max(0, (.1+C(S(t/8)*Math.PI*120))/(1e5+S(t/2)*2e3)))\n  ip2 = 1-ip1\n  \n  tlen = 26\n  \n  if(showstars) ST.map(v=>{\n    d = Math.hypot(v[0], v[1], v[2])\n    tx = v[0] / d * 20\n    ty = v[1] / d * C(t)*24\n    tz = v[2] / d * 20\n    X = v[0]\n    Y = v[1]\n    Z = v[2]\n    R(C(t/3)/10,C(t)/20,C(t/2)/10)\n    v[0] = X\n    v[1] = Y\n    v[2] = Z\n    X1 = X = v[0] * ip1 + tx * ip2\n    Y1 = Y = v[1] * ip1 + ty * ip2\n    Z1 = Z = v[2] * ip1 + tz * ip2\n    if(v[4] && v[5]){\n      v[3] = v[3].filter((q,j)=>v[3].length<tlen || j)\n      v[3] = [...v[3], [X1, Y1, Z1]]\n    }\n    if(v[4] && v[5]) v[3].map((q, j) => {\n      if(j){\n        x.beginPath()\n        l = j\n        X = v[3][l][0]\n        Y = v[3][l][1]\n        Z = v[3][l][2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        l = j-1\n        X = v[3][l][0]\n        Y = v[3][l][1]\n        Z = v[3][l][2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n        col1 = `hsla(${360/9*v[6]-(150-150/(1+j**4/2e4))},99%,${50+150/(1+j**4/2e4)}%,${alpha=.5-.5/(1+j**4/999)})`\n        col2 = \'\'\n        if(alpha>.1) stroke(col1, col2, Math.min(2000,(l=150+s/4)*(.5-.5/(1+j**2/900))), true)\n      }\n    })\n    X = X1, Y = Y1, Z = Z1\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      s1 = Math.min(5e5, 2e7/Z)\n      s2 = Math.min(1e5, 3e3/Z)\n      s = s1 * ip1 + s2 * ip2\n      l = Q()\n      ls = v[5]&&v[4]?3:.5\n      x.drawImage(starImgs[v[5]&&v[4]?v[6]:0].img,l[0]-s/1.05*ls,l[1]-s/1.05*ls,s*2*ls,s*2*ls)\n    }\n  })\n\n  X = Y = Z = 0 \n  R(Rl,Pt,Yw,1)\n  l = Q()\n  s=Math.min(2e3,3e4/Z)\n  x.drawImage(burst,l[0]-s/2,l[1]-s/2,s,s)\n  \n  x.globalAlpha = 1\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  margin: 0;\n  background: #000;\n  height: 100vh;\n  width: 100vw;\n  border: none;\n  overflow: hidden;\n}\n#c:focus{\n  outline: none;\n}\n#c{\n  background: #000;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}\n', '<canvas id=c></canvas>', 'entity delta', 145, 'whitehot robot', '2023-12-19 00:40:33', '[600754,600753]', 52, '', 0, 0),
(600757, '', 'for(i=10000; i<11000; i++){\n  el = document.createElement(\'span\')\n  el.innerHTML = `&#${(i).toString(16)};`\n  document.body.appendChild(el)\n}', 'body{\ncolor: #fff;\nfont-size: 40px;\nword-break: break-all;\nline-height: .8em\nheight: 100vh\n}', '', 'unicode browser', 145, 'whitehot robot', '2023-12-19 20:59:46', '', 48, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600758, '', 'c = document.querySelector(\'#c\')\nc.width = 1920\nc.height = 1080\nx = c.getContext(\'2d\')\nC = Math.cos\nS = Math.sin\nt = 0\nT = Math.tan\n\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height =     c.clientWidth/1.77777778 + \'px\',0)\n    }\n  },0)\n}\nrsz()\n\nasync function Draw(){\n  oX=oY=oZ=0\n  if(!t){\n    window.onload = () => {\n      c.focus()\n    }\n    HSVFromRGB = (R, G, B) => {\n      let R_=R/256\n      let G_=G/256\n      let B_=B/256\n      let Cmin = Math.min(R_,G_,B_)\n      let Cmax = Math.max(R_,G_,B_)\n      let val = Cmax //(Cmax+Cmin) / 2\n      let delta = Cmax-Cmin\n      let sat = Cmax ? delta / Cmax: 0\n      let min=Math.min(R,G,B)\n      let max=Math.max(R,G,B)\n      let hue = 0\n      if(delta){\n        if(R>=G && R>=B) hue = (G-B)/(max-min)\n        if(G>=R && G>=B) hue = 2+(B-R)/(max-min)\n        if(B>=G && B>=R) hue = 4+(R-G)/(max-min)\n      }\n      hue*=60\n      while(hue<0) hue+=360;\n      while(hue>=360) hue-=360;\n      return [hue, sat, val]\n    }\n\n    RGBFromHSV = (H, S, V) => {\n      while(H<0) H+=360;\n      while(H>=360) H-=360;\n      let C = V*S\n      let X = C * (1-Math.abs((H/60)%2-1))\n      let m = V-C\n      let R_, G_, B_\n      if(H>=0 && H < 60)    R_=C, G_=X, B_=0\n      if(H>=60 && H < 120)  R_=X, G_=C, B_=0\n      if(H>=120 && H < 180) R_=0, G_=C, B_=X\n      if(H>=180 && H < 240) R_=0, G_=X, B_=C\n      if(H>=240 && H < 300) R_=X, G_=0, B_=C\n      if(H>=300 && H < 360) R_=C, G_=0, B_=X\n      let R = (R_+m)*256\n      let G = (G_+m)*256\n      let B = (B_+m)*256\n      return [R,G,B]\n    }\n    \n    R=R2=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n    \n    Rn = Math.random\n    async function loadOBJ(url, scale, tx, ty, tz, rl, pt, yw) {\n      let res\n      await fetch(url, res => res).then(data=>data.text()).then(data=>{\n        a=[]\n        data.split(\"\\nv \").map(v=>{\n          a=[...a, v.split(\"\\n\")[0]]\n        })\n        a=a.filter((v,i)=>i).map(v=>[...v.split(\' \').map(n=>(+n.replace(\"\\n\", \'\')))])\n        ax=ay=az=0\n        a.map(v=>{\n          v[1]*=-1\n          ax+=v[0]\n          ay+=v[1]\n          az+=v[2]\n        })\n        ax/=a.length\n        ay/=a.length\n        az/=a.length\n        a.map(v=>{\n          X=(v[0]-ax)*scale\n          Y=(v[1]-ay)*scale\n          Z=(v[2]-az)*scale\n          R2(rl,pt,yw,0)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n        })\n        maxY=-6e6\n        a.map(v=>{\n          if(v[1]>maxY)maxY=v[1]\n        })\n        a.map(v=>{\n          v[1]-=maxY-oY\n          v[0]+=tx\n          v[1]+=ty\n          v[2]+=tz\n        })\n\n        b=[]\n        data.split(\"\\nf \").map(v=>{\n          b=[...b, v.split(\"\\n\")[0]]\n        })\n        b.shift()\n        b=b.map(v=>v.split(\' \'))\n        b=b.map(v=>{\n          v=v.map(q=>{\n            return +q.split(\'/\')[0]\n          })\n          v=v.filter(q=>q)\n          return v\n        })\n        \n        res=[]\n        b.map(v=>{\n          e=[]\n          v.map(q=>{\n            e=[...e, a[q-1]]\n          })\n          e = e.filter(q=>q)\n          res=[...res, e]\n        })\n      })\n      return res\n    }\n\n    geoSphere = (mx, my, mz, iBc, size) => {\n      let collapse=0\n      let B=Array(iBc).fill().map(v=>{\n        X = Rn()-.5\n        Y = Rn()-.5\n        Z = Rn()-.5\n        return  [X,Y,Z]\n      })\n      for(let m=200;m--;){\n        B.map((v,i)=>{\n          X = v[0]\n          Y = v[1]\n          Z = v[2]\n          B.map((q,j)=>{\n            if(j!=i){\n              X2=q[0]\n              Y2=q[1]\n              Z2=q[2]\n              d=1+(Math.hypot(X-X2,Y-Y2,Z-Z2)*(3+iBc/40)*3)**4\n              X+=(X-X2)*99/d\n              Y+=(Y-Y2)*99/d\n              Z+=(Z-Z2)*99/d\n            }\n          })\n          d=Math.hypot(X,Y,Z)\n          v[0]=X/d\n          v[1]=Y/d\n          v[2]=Z/d\n          if(collapse){\n            d=25+Math.hypot(X,Y,Z)\n            v[0]=(X-X/d)/1.1\n            v[1]=(Y-Y/d)/1.1         \n            v[2]=(Z-Z/d)/1.1\n          }\n        })\n      }\n      mind = 6e6\n      B.map((v,i)=>{\n        X1 = v[0]\n        Y1 = v[1]\n        Z1 = v[2]\n        B.map((q,j)=>{\n          X2 = q[0]\n          Y2 = q[1]\n          Z2 = q[2]\n          if(i!=j){\n            d = Math.hypot(a=X1-X2, b=Y1-Y2, e=Z1-Z2)\n            if(d<mind) mind = d\n          }\n        })\n      })\n      a = []\n      B.map((v,i)=>{\n        X1 = v[0]\n        Y1 = v[1]\n        Z1 = v[2]\n        B.map((q,j)=>{\n          X2 = q[0]\n          Y2 = q[1]\n          Z2 = q[2]\n          if(i!=j){\n            d = Math.hypot(X1-X2, Y1-Y2, Z1-Z2)\n            if(d<mind*2){\n              if(!a.filter(q=>q[0]==X2&&q[1]==Y2&&q[2]==Z2&&q[3]==X1&&q[4]==Y1&&q[5]==Z1).length) a = [...a, [X1*size,Y1*size,Z1*size,X2*size,Y2*size,Z2*size]]\n            }\n          }\n        })\n      })\n      B.map(v=>{\n        v[0]*=size\n        v[1]*=size\n        v[2]*=size\n        v[0]+=mx\n        v[1]+=my\n        v[2]+=mz\n      })\n      return [mx, my, mz, size, B, a]\n    }\n\n    lineFaceI = (X1, Y1, Z1, X2, Y2, Z2, facet, autoFlipNormals=false, showNormals=false) => {\n      let X_, Y_, Z_, d, m, l_,K,J,L,p\n      let I_=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n      let Q_=()=>[c.width/2+X_/Z_*600,c.height/2+Y_/Z_*600]\n      let R_ = (Rl,Pt,Yw,m)=>{\n        let M=Math, A=M.atan2, H=M.hypot\n        X_=S(p=A(X_,Y_)+Rl)*(d=H(X_,Y_)),Y_=C(p)*d,X_=S(p=A(X_,Z_)+Yw)*(d=H(X_,Z_)),Z_=C(p)*d,Y_=S(p=A(Y_,Z_)+Pt)*(d=H(Y_,Z_)),Z_=C(p)*d\n        if(m){ X_+=oX,Y_+=oY,Z_+=oZ }\n      }\n      let rotSwitch = m =>{\n        switch(m){\n          case 0: R_(0,0,Math.PI/2); break\n          case 1: R_(0,Math.PI/2,0); break\n          case 2: R_(Math.PI/2,0,Math.PI/2); break\n        }        \n      }\n      let ax = 0, ay = 0, az = 0\n      facet.map(q_=>{ ax += q_[0], ay += q_[1], az += q_[2] })\n      ax /= facet.length, ay /= facet.length, az /= facet.length\n      let b1 = facet[2][0]-facet[1][0], b2 = facet[2][1]-facet[1][1], b3 = facet[2][2]-facet[1][2]\n      let c1 = facet[1][0]-facet[0][0], c2 = facet[1][1]-facet[0][1], c3 = facet[1][2]-facet[0][2]\n      let crs = [b2*c3-b3*c2,b3*c1-b1*c3,b1*c2-b2*c1]\n      d = Math.hypot(...crs)+.001\n      let nls = 1 //normal line length\n      crs = crs.map(q=>q/d*nls)\n      let X1_ = ax, Y1_ = ay, Z1_ = az\n      let flip = 1\n      if(autoFlipNormals){\n        let d1_ = Math.hypot(X1_-X1,Y1_-Y1,Z1_-Z1)\n        let d2_ = Math.hypot(X1-(ax + crs[0]/99),Y1-(ay + crs[1]/99),Z1-(az + crs[2]/99))\n        flip = d2_>d1_?-1:1\n      }\n      let X2_ = ax + (crs[0]*=flip), Y2_ = ay + (crs[1]*=flip), Z2_ = az + (crs[2]*=flip)\n      if(showNormals){\n        x.beginPath()\n        X_ = X1_, Y_ = Y1_, Z_ = Z1_\n        R_(Rl,Pt,Yw,1)\n        if(Z_>0) x.lineTo(...Q_())\n        X_ = X2_, Y_ = Y2_, Z_ = Z2_\n        R_(Rl,Pt,Yw,1)\n        if(Z_>0) x.lineTo(...Q_())\n        x.lineWidth = 5\n        x.strokeStyle=\'#f004\'\n        x.stroke()\n      }\n      \n      let p1_ = Math.atan2(X2_-X1_,Z2_-Z1_)\n      let p2_ = -(Math.acos((Y2_-Y1_)/(Math.hypot(X2_-X1_,Y2_-Y1_,Z2_-Z1_)+.001))+Math.PI/2)\n      let isc = false, iscs = [false,false,false]\n      X_ = X1, Y_ = Y1, Z_ = Z1\n      R_(0,-p2_,-p1_)\n      let rx_ = X_, ry_ = Y_, rz_ = Z_\n      for(let m=3;m--;){\n        if(isc === false){\n          X_ = rx_, Y_ = ry_, Z_ = rz_\n          rotSwitch(m)\n          X1_ = X_, Y1_ = Y_, Z1_ = Z_ = 5, X_ = X2, Y_ = Y2, Z_ = Z2\n          R_(0,-p2_,-p1_)\n          rotSwitch(m)\n          X2_ = X_, Y2_ = Y_, Z2_ = Z_\n          facet.map((q_,j_)=>{\n            if(isc === false){\n              let l = j_\n              X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n              R_(0,-p2_,-p1_)\n              rotSwitch(m)\n              let X3_=X_, Y3_=Y_, Z3_=Z_\n              l = (j_+1)%facet.length\n              X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n              R_(0,-p2_,-p1_)\n              rotSwitch(m)\n              let X4_ = X_, Y4_ = Y_, Z4_ = Z_\n              if(l_=I_(X1_,Y1_,X2_,Y2_,X3_,Y3_,X4_,Y4_)) iscs[m] = l_\n            }\n          })\n        }\n      }\n      if(iscs.filter(v=>v!==false).length==3){\n        let iscx = iscs[1][0], iscy = iscs[0][1], iscz = iscs[0][0]\n        let pointInPoly = true\n        ax=0, ay=0, az=0\n        facet.map((q_, j_)=>{ ax+=q_[0], ay+=q_[1], az+=q_[2] })\n        ax/=facet.length, ay/=facet.length, az/=facet.length\n        X_ = ax, Y_ = ay, Z_ = az\n        R_(0,-p2_,-p1_)\n        X1_ = X_, Y1_ = Y_, Z1_ = Z_\n        X2_ = iscx, Y2_ = iscy, Z2_ = iscz\n        facet.map((q_,j_)=>{\n          if(pointInPoly){\n            let l = j_\n            X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n            R_(0,-p2_,-p1_)\n            let X3_ = X_, Y3_ = Y_, Z3_ = Z_\n            l = (j_+1)%facet.length\n            X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n            R_(0,-p2_,-p1_)\n            let X4_ = X_, Y4_ = Y_, Z4_ = Z_\n            if(I_(X1_,Y1_,X2_,Y2_,X3_,Y3_,X4_,Y4_)) pointInPoly = false\n          }\n        }