;){\n        a = []\n        X = 0\n        Y = 0\n        Z = -h\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/3*j) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/3*(j+1)) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      ax=ay=az=ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax\n          q[1]-=ay\n          q[2]-=az\n        })\n      })\n      return ret\n    }\n\n    Cube = size => {\n      for(CB=[],j=6;j--;CB=[...CB,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?size/1.5:-size/1.5),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      return CB\n    }\n\n    Octahedron = size => {\n      ret = []\n      let h = size/1.25\n      for(j=8;j--;){\n        a = []\n        X = 0\n        Y = 0\n        Z = h * (j<4?-1:1)\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*j) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*(j+1)) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      return ret      \n    }\n\n    Dodecahedron = size => {\n      ret = []\n      a = []\n      mind = -6e6\n      for(i=5;i--;){\n        X=S(p=Math.PI*2/5*i + Math.PI/5)\n        Y=C(p)\n        Z=0\n        if(Y>mind) mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a.map(v=>{\n        X = v[0]\n        Y = v[1]-=mind\n        Z = v[2]\n        R(0, .553573, 0)\n        v[0] = X\n        v[1] = Y\n        v[2] = Z\n      })\n      b = JSON.parse(JSON.stringify(a))\n      b.map(v=>{\n        v[1] *= -1\n      })\n      ret = [...ret, a, b]\n      mind = -6e6\n      ret.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          if(Z>mind)mind = Z\n        })\n      })\n      d1=Math.hypot(ret[0][0][0]-ret[0][1][0],ret[0][0][1]-ret[0][1][1],ret[0][0][2]-ret[0][1][2])\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]-=mind+d1/2\n        })\n      })\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          q[2]*=-1\n        })\n      })\n      ret = [...ret, ...b]\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(0,Math.PI/2,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      e = JSON.parse(JSON.stringify(ret))\n      e.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(Math.PI/2,0,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      ret = [...ret, ...b, ...e]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0] *= size/2\n          q[1] *= size/2\n          q[2] *= size/2\n        })\n      })\n      return ret\n    }\n\n    Icosahedron = size => {\n      ret = []\n      let B = [\n        [[0,3],[1,0],[2,2]],\n        [[0,3],[1,0],[1,3]],\n        [[0,3],[2,3],[1,3]],\n        [[0,2],[2,1],[1,0]],\n        [[0,2],[1,3],[1,0]],\n        [[0,2],[1,3],[2,0]],\n        [[0,3],[2,2],[0,0]],\n        [[1,0],[2,2],[2,1]],\n        [[1,1],[2,2],[2,1]],\n        [[1,1],[2,2],[0,0]],\n        [[1,1],[2,1],[0,1]],\n        [[0,2],[2,1],[0,1]],\n        [[2,0],[1,2],[2,3]],\n        [[0,0],[0,3],[2,3]],\n        [[1,3],[2,0],[2,3]],\n        [[2,3],[0,0],[1,2]],\n        [[1,2],[2,0],[0,1]],\n        [[0,0],[1,2],[1,1]],\n        [[0,1],[1,2],[1,1]],\n        [[0,2],[2,0],[0,1]],\n      ]\n      for(p=[1,1],i=38;i--;)p=[...p,p[l=p.length-1]+p[l-1]]\n      phi = p[l]/p[l-1]\n      a = [\n        [-phi,-1,0],\n        [phi,-1,0],\n        [phi,1,0],\n        [-phi,1,0],\n      ]\n      for(j=3;j--;ret=[...ret, b])for(b=[],i=4;i--;) b = [...b, [a[i][j],a[i][(j+1)%3],a[i][(j+2)%3]]]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]*=size/2.25\n          q[1]*=size/2.25\n          q[2]*=size/2.25\n        })\n      })\n      cp = JSON.parse(JSON.stringify(ret))\n      out=[]\n      a = []\n      B.map(v=>{\n        idx1a = v[0][0]\n        idx2a = v[1][0]\n        idx3a = v[2][0]\n        idx1b = v[0][1]\n        idx2b = v[1][1]\n        idx3b = v[2][1]\n        a = [...a, [cp[idx1a][idx1b],cp[idx2a][idx2b],cp[idx3a][idx3b]]]\n      })\n      out = [...out, ...a]\n      return out\n    }\n\n    stroke = (scol, fcol, lwo=1, od=true, oga=1) => {\n      if(scol){\n        //x.closePath()\n        if(od) x.globalAlpha = .2*oga\n        x.strokeStyle = scol\n        x.lineWidth = Math.min(1000,100*lwo/Z)\n        if(od) x.stroke()\n        x.lineWidth /= 4\n        x.globalAlpha = 1*oga\n        x.stroke()\n      }\n      if(fcol){\n        x.globalAlpha = 1*oga\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n\n    subbed = (subs, size, sphereize, shape) => {\n      for(let m=subs; m--;){\n        base = shape\n        shape = []\n        base.map(v=>{\n          l = 0\n          X1 = v[l][0]\n          Y1 = v[l][1]\n          Z1 = v[l][2]\n          l = 1\n          X2 = v[l][0]\n          Y2 = v[l][1]\n          Z2 = v[l][2]\n          l = 2\n          X3 = v[l][0]\n          Y3 = v[l][1]\n          Z3 = v[l][2]\n          if(v.length > 3){\n            l = 3\n            X4 = v[l][0]\n            Y4 = v[l][1]\n            Z4 = v[l][2]\n            if(v.length > 4){\n              l = 4\n              X5 = v[l][0]\n              Y5 = v[l][1]\n              Z5 = v[l][2]\n            }\n          }\n          mx1 = (X1+X2)/2\n          my1 = (Y1+Y2)/2\n          mz1 = (Z1+Z2)/2\n          mx2 = (X2+X3)/2\n          my2 = (Y2+Y3)/2\n          mz2 = (Z2+Z3)/2\n          a = []\n          switch(v.length){\n            case 3:\n              mx3 = (X3+X1)/2\n              my3 = (Y3+Y1)/2\n              mz3 = (Z3+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 4:\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X1)/2\n              my4 = (Y4+Y1)/2\n              mz4 = (Z4+Z1)/2\n              cx = (X1+X2+X3+X4)/4\n              cy = (Y1+Y2+Y3+Y4)/4\n              cz = (Z1+Z2+Z3+Z4)/4\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 5:\n              cx = (X1+X2+X3+X4+X5)/5\n              cy = (Y1+Y2+Y3+Y4+Y5)/5\n              cz = (Z1+Z2+Z3+Z4+Z5)/5\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X5)/2\n              my4 = (Y4+Y5)/2\n              mz4 = (Z4+Z5)/2\n              mx5 = (X5+X1)/2\n              my5 = (Y5+Y1)/2\n              mz5 = (Z5+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              break\n          }\n        })\n      }\n      if(sphereize){\n        ip1 = sphereize\n        ip2 = 1-sphereize\n        shape = shape.map(v=>{\n          v = v.map(q=>{\n            X = q[0]\n            Y = q[1]\n            Z = q[2]\n            d = Math.hypot(X,Y,Z)\n            X /= d\n            Y /= d\n            Z /= d\n            X *= size*.75*ip1 + d*ip2\n            Y *= size*.75*ip1 + d*ip2\n            Z *= size*.75*ip1 + d*ip2\n            return [X,Y,Z]\n          })\n          return v\n        })\n      }\n      return shape\n    }\n\n    subDividedIcosahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Icosahedron(size))\n    subDividedTetrahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Tetrahedron(size))\n    subDividedOctahedron   = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Octahedron(size))\n    subDividedCube         = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Cube(size))\n    subDividedDodecahedron = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Dodecahedron(size))\n\n    Rn = Math.random\n\n    LsystemRecurse = (size, splits, p1, p2, stem, theta, LsystemReduction, twistFactor) => {\n      if(size < .25) return\n      let X1 = stem[0]\n      let Y1 = stem[1]\n      let Z1 = stem[2]\n      let X2 = stem[3]\n      let Y2 = stem[4]\n      let Z2 = stem[5]\n      let p1a = Math.atan2(X2-X1,Z2-Z1)\n      let p2a = -Math.acos((Y2-Y1)/(Math.hypot(X2-X1,Y2-Y1,Z2-Z1)+.0001))+Math.PI\n      size/=LsystemReduction\n      for(let i=splits;i--;){\n        X = 0\n        Y = -size\n        Z = 0\n        R(0, theta, 0)\n        R(0, 0, Math.PI*2/splits*i+twistFactor)\n        R(0, p2a, 0)\n        R(0, 0, p1a+twistFactor)\n        X+=X2\n        Y+=Y2\n        Z+=Z2\n        let newStem = [X2, Y2, Z2, X, Y, Z]\n        Lshp = [...Lshp, newStem]\n        LsystemRecurse(size, splits, p1+Math.PI*2/splits*i+twistFactor, p2+theta, newStem, theta, LsystemReduction, twistFactor)\n      }\n    }\n    DrawLsystem = shp => {\n      shp.map(v=>{\n        x.beginPath()\n        X = v[0]\n        Y = v[1]\n        Z = v[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        X = v[3]\n        Y = v[4]\n        Z = v[5]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        lwo = Math.hypot(v[0]-v[3],v[1]-v[4],v[2]-v[5])*4\n        stroke(\'#0f82\',\'\',lwo)\n      })\n\n    }\n    Lsystem = (size, splits, theta, LsystemReduction, twistFactor) => {\n      Lshp = []\n      stem = [0,0,0,0,-size,0]\n      Lshp = [...Lshp, stem]\n      LsystemRecurse(size, splits, 0, 0, stem, theta, LsystemReduction, twistFactor)\n      Lshp.map(v=>{\n        v[1]+=size*1.5\n        v[4]+=size*1.5\n      })\n      return Lshp\n    }\n\n    Sphere = (ls, rw, cl) => {\n      a = []\n      ls/=1.25\n      for(j = rw; j--;){\n        for(i = cl; i--;){\n          b = []\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          a = [...a, b]\n        }\n      }\n      return a\n    }\n\n    Torus = (rw, cl, ls1, ls2, parts=1, twists=0, part_spacing=1.5) => {\n      let ret = [], tx=0, ty=0, tz=0, prl1 = 0, p2a = 0\n      let tx1 = 0, ty1 = 0, tz1 = 0, prl2 = 0, p2b = 0, tx2 = 0, ty2 = 0, tz2 = 0\n      for(let m=parts;m--;){\n        avgs = Array(rw).fill().map(v=>[0,0,0])\n        for(j=rw;j--;)for(let i = cl;i--;){\n          if(parts>1){\n            ls3 = ls1*part_spacing\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl1 = Math.PI*2/rw*(j-1)*twists,0,0)\n            tx1 = X\n            ty1 = Y \n            tz1 = Z\n            R(0, 0, Math.PI*2/rw*(j-1))\n            ax1 = X\n            ay1 = Y\n            az1 = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl2 = Math.PI*2/rw*(j)*twists,0,0)\n            tx2 = X\n            ty2 = Y\n            tz2 = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax2 = X\n            ay2 = Y\n            az2 = Z\n            p1a = Math.atan2(ax2-ax1,az2-az1)\n            p2a = Math.PI/2+Math.acos((ay2-ay1)/(Math.hypot(ax2-ax1,ay2-ay1,az2-az1)+.001))\n\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j)*twists,0,0)\n            tx1b = X\n            ty1b = Y\n            tz1b = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax1b = X\n            ay1b = Y\n            az1b = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j+1)*twists,0,0)\n            tx2b = X\n            ty2b = Y\n            tz2b = Z\n            R(0, 0, Math.PI*2/rw*(j+1))\n            ax2b = X\n            ay2b = Y\n            az2b = Z\n            p1b = Math.atan2(ax2b-ax1b,az2b-az1b)\n            p2b = Math.PI/2+Math.acos((ay2b-ay1b)/(Math.hypot(ax2b-ax1b,ay2b-ay1b,az2b-az1b)+.001))\n          }\n          a = []\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          ret = [...ret, a]\n        }\n      }\n      return ret\n    }\n\n    G_ = 100000, iSTc = 1e4\n    ST = Array(iSTc).fill().map(v=>{\n      X = (Rn()-.5)*G_\n      Y = (Rn()-.5)*G_\n      Z = (Rn()-.5)*G_\n      return [X,Y,Z]\n    })\n\n    burst = new Image()\n    burst.src = \"https://srmcgann.github.io/temp/burst.png\"\n\n    starsLoaded = false, starImgs = [{loaded: false}]\n    starImgs = Array(9).fill().map((v,i) => {\n      let a = {img: new Image(), loaded: false}\n      a.img.onload = () => {\n        a.loaded = true\n        setTimeout(()=>{\n          if(starImgs.filter(v=>v.loaded).length == 9) starsLoaded = true\n        }, 0)\n      }\n      a.img.src = `https://srmcgann.github.io/stars/star${i+1}.png`\n      return a\n    })\n\n    showstars = true\n    sliders = []\n    mbutton = -1\n    c.onmousedown = e => {\n      mbutton = e.button\n      console.log(mbutton)\n      let rect = c.getBoundingClientRect()\n      mx = (e.pageX - rect.left)/c.clientWidth*c.width\n      my = (e.pageY - rect.top)/c.clientHeight*c.height\n      if(sliders.length){\n        sliders.map(slider=>{\n          X = slider.posX - slider.width/2 + slider.width/(slider.max - slider.min) * eval(slider.valVariable)\n          Y = slider.posY\n          s = slider.height/2\n          d = Math.hypot(X-mx,Y-my)\n          if(d<s && e.button == 0){\n            slider.sliding = true\n            slider.tmx = mx\n            slider.tmy = my\n          }\n        })\n      }\n    }\n    \n    c.onmouseup = e => {\n      mbutton = -1\n      sliders.map(slider=>{\n        slider.sliding = false\n      })\n    }\n    \n    c.onmousemove = e => {\n      e.preventDefault()\n      e.stopPropagation()\n      let rect = c.getBoundingClientRect()\n      mx = (e.pageX - rect.left)/c.clientWidth*c.width\n      my = (e.pageY - rect.top)/c.clientHeight*c.height\n      \n      if(sliders.length){\n        c.style.cursor = \'unset\'\n        sliders.map(slider=>{\n          X = slider.posX - slider.width/2 + slider.width/(slider.max - slider.min) * eval(slider.valVariable)\n          Y = slider.posY\n          s = slider.height/2\n          d = Math.hypot(X-mx,Y-my)\n          if(d<s){\n            c.style.cursor = \'pointer\'\n          }\n          if(slider.sliding){\n            if(slider.style == \'horizontal\'){\n              dx = (mx-slider.tmx)/slider.width*(slider.max-slider.min)\n              eval(slider.valVariable + \' += dx\')\n              slider.tmx = mx\n              slider.tmy = my\n              eval(slider.valVariable + \' = Math.min(slider.max,Math.max(slider.min,\'+slider.valVariable+\'))\')\n              slider.captionVar = (Math.round(eval(slider.valVariable)*10)/10)\n            }else{\n            }\n          }\n        })\n      }\n    }\n    \n    \n    sliders = [...sliders,\n      {\n        caption: \'speed\',\n        style: \'horizontal\',   // vertical/horizontal\n        posX: c.width/2,\n        posY: c.height-100,\n        width: 400,\n        height: 40,\n        min: 0,\n        max: 3,\n        majorStep: 1,\n        minorStep: .5,\n        tickColor: \'#0f8a\',\n        backgroundColor: \'#40f4\',\n        selectorColor: \'#fff\',\n        valVariable: \'animations[0].speed\',\n        padding: 75,\n        textColor: \'#f2a\',\n        fontSize: 32,\n        captionVar: 1,\n        sliding: false,\n        tmx: 0,\n        tmy: 0,\n      }\n    ]\n    \n    drawSlider = slider => {\n      if(slider.style == \'horizontal\'){\n        x.fillStyle = slider.backgroundColor\n        X = slider.posX - slider.width/2 - slider.padding/2\n        Y = slider.posY - slider.height/2 - slider.padding/2\n        w = slider.width + slider.padding\n        h = slider.height + slider.padding\n        x.fillRect(X,Y,w,h)\n      }\n      for(let i = slider.min; i<slider.max+1; i+=slider.minorStep){\n        if(slider.style == \'horizontal\'){\n          x.beginPath()\n          X = slider.posX - slider.width/2 + slider.width/(slider.max - slider.min) * i\n          Y = slider.posY - slider.height/4\n          x.lineTo(X,Y)\n          X = slider.posX - slider.width/2 + slider.width/(slider.max - slider.min) * i\n          Y = slider.posY + slider.height/4\n          x.lineTo(X,Y)\n          Z = 1\n          stroke(slider.tickColor,\'\',.1, true)\n        }else{\n        }\n      }\n      for(let i = slider.min; i<slider.max+1; i+=slider.majorStep){\n        if(slider.style == \'horizontal\'){\n          x.beginPath()\n          X = slider.posX - slider.width/2 + slider.width/(slider.max - slider.min) * i\n          Y = slider.posY - slider.height/2\n          x.lineTo(X,Y)\n          X = slider.posX - slider.width/2 + slider.width/(slider.max - slider.min) * i\n          Y = slider.posY + slider.height/2\n          x.lineTo(X,Y)\n          Z = 1\n          stroke(slider.tickColor,\'\',.1, true)\n          x.fillStyle = slider.textColor\n          x.textAlign = \'center\'\n          x.font = (slider.fontSize) + \"px Courier Prime\"\n          x.fillText(i,X,Y+slider.height/2)\n        }else{\n        }\n      }\n      if(slider.style == \'horizontal\'){\n        x.beginPath()\n        X = slider.posX - slider.width/2\n        Y = slider.posY\n        x.lineTo(X,Y)\n        X = slider.posX + slider.width/2\n        Y = slider.posY\n        x.lineTo(X,Y)\n        stroke(slider.tickColor,\'\',.1, true)\n      }\n      x.fillStyle = slider.textColor\n      x.textAlign = \'left\'\n      x.font = (slider.fontSize*1.5) + \"px Courier Prime\"\n      x.fillText(slider.caption + \' \' + slider.captionVar,slider.posX-slider.width/2,Y-slider.height/2-slider.fontSize/3)\n      X = slider.posX - slider.width/2 + slider.width/(slider.max - slider.min) * eval(slider.valVariable)\n      Y = slider.posY\n      s = slider.height*1.5\n      x.drawImage(burst,X-s/2,Y-s/2,s,s)\n    }\n\n    loadAnimation(\'walking_male\', 3, 0,3.5,0, 0,0,Math.PI/2, 1)\n    \n  }\n\n  oX=0, oY=0, oZ=Math.min(50,Math.max(15,(.3+C(t))*100))\n  Rl=0, Pt=-.1 + C(t)/3, Yw=Math.min(Math.PI/1.5, Math.max(-Math.PI, (.3+S(t/1.5))*8)) - Math.PI/2\n\n  x.globalAlpha = 1\n  x.fillStyle=\'#000a\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin = x.lineCap = \'roud\'\n\n  if(showstars) ST.map(v=>{\n    X = v[0]\n    Y = v[1]\n    Z = v[2]\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      if((x.globalAlpha = Math.min(1,(Z/5e3)**2))>.1){\n        s = Math.min(1e3, 4e5/Z)\n        x.fillStyle = \'#ffffff04\'\n        l = Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=5\n        x.fillStyle = \'#fffa\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n    }\n  })\n\n  x.globalAlpha = 1\n\n  animations.map(animation => {\n    drawAnimation(animation, \'#48f4\', \'#40f2\')\n  })\n\n  if(typeof animations != \'undefined\' && animations.length && animations[0].loaded) {\n    shp = Cylinder(1,8,10,20).map(v=>{\n      v.map(q=>{\n        X = q[0]\n        Y = q[1]\n        Z = q[2]\n        R(0,Math.PI/2,t*3.75 * (mbutton == -1 ? animations[0].speed: 0))\n        R(0,0,Math.PI/2)\n        q[0] = X\n        q[1] = Y\n        q[2] = Z\n      })\n      return v\n    })\n\n    shp.map(v=>{\n      x.beginPath()\n      v.map(q=>{\n        X = q[0]\n        Y = q[1] + 13\n        Z = q[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0) x.lineTo(...Q())\n      })\n      stroke(\'#f002\', \'#f002\',8,false)\n    })\n  }\n  \n  sliders.map(slider=>{\n    if(typeof animations != \'undefined\' && animations.length) drawSlider(slider)\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', '/* latin-ext */\n@font-face {\n  font-family: \'Courier Prime\';\n  font-style: normal;\n  font-weight: 400;\n  font-display: swap;\n  src: url(https://fonts.gstatic.com/s/courierprime/v9/u-450q2lgwslOqpF_6gQ8kELaw9pWt_-.woff2) format(\'woff2\');\n  unicode-range: U+0100-02AF, U+0304, U+0308, U+0329, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20CF, U+2113, U+2C60-2C7F, U+A720-A7FF;\n}\n/* latin */\n@font-face {\n  font-family: \'Courier Prime\';\n  font-style: normal;\n  font-weight: 400;\n  font-display: swap;\n  src: url(https://fonts.gstatic.com/s/courierprime/v9/u-450q2lgwslOqpF_6gQ8kELawFpWg.woff2) format(\'woff2\');\n  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+2074, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;\n}\nbody,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  overflow: hidden;\n  font-family: Courier Prime;\n}\n#c:focus{\n  outline: none;\n}\n#c{\n  background:#000;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'swagger animation with speed control', 145, 'whitehot robot', '2024-01-25 18:30:18', '', 46, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600763, '', 'c = document.querySelector(\'#c\')\nc.width = 1920\nc.height = 1080\nx = c.getContext(\'2d\')\nC = Math.cos\nS = Math.sin\nt = 0\nT = Math.tan\n\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height =     c.clientWidth/1.77777778 + \'px\',0)\n    }\n  },0)\n}\nrsz()\n\nasync function Draw(){\n  oX=oY=oZ=0\n  if(!t){\n    HSVFromRGB = (R, G, B) => {\n      let R_=R/256\n      let G_=G/256\n      let B_=B/256\n      let Cmin = Math.min(R_,G_,B_)\n      let Cmax = Math.max(R_,G_,B_)\n      let val = Cmax //(Cmax+Cmin) / 2\n      let delta = Cmax-Cmin\n      let sat = Cmax ? delta / Cmax: 0\n      let min=Math.min(R,G,B)\n      let max=Math.max(R,G,B)\n      let hue = 0\n      if(delta){\n        if(R>=G && R>=B) hue = (G-B)/(max-min)\n        if(G>=R && G>=B) hue = 2+(B-R)/(max-min)\n        if(B>=G && B>=R) hue = 4+(R-G)/(max-min)\n      }\n      hue*=60\n      while(hue<0) hue+=360;\n      while(hue>=360) hue-=360;\n      return [hue, sat, val]\n    }\n\n    RGBFromHSV = (H, S, V) => {\n      while(H<0) H+=360;\n      while(H>=360) H-=360;\n      let C = V*S\n      let X = C * (1-Math.abs((H/60)%2-1))\n      let m = V-C\n      let R_, G_, B_\n      if(H>=0 && H < 60)    R_=C, G_=X, B_=0\n      if(H>=60 && H < 120)  R_=X, G_=C, B_=0\n      if(H>=120 && H < 180) R_=0, G_=C, B_=X\n      if(H>=180 && H < 240) R_=0, G_=X, B_=C\n      if(H>=240 && H < 300) R_=X, G_=0, B_=C\n      if(H>=300 && H < 360) R_=C, G_=0, B_=X\n      let R = (R_+m)*256\n      let G = (G_+m)*256\n      let B = (B_+m)*256\n      return [R,G,B]\n    }\n\n    R=R2=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      if(m){\n        X+=oX\n        Y+=oY\n        Z+=oZ\n      }\n    }\n    Q=()=>[c.width/2+X/Z*700,c.height/2+Y/Z*700]\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    Rn = Math.random\n    async function loadOBJ(url, scale, tx, ty, tz, rl, pt, yw, recenter=true) {\n      let res\n      await fetch(url, res => res).then(data=>data.text()).then(data=>{\n        a=[]\n        data.split(\"\\nv \").map(v=>{\n          a=[...a, v.split(\"\\n\")[0]]\n        })\n        a=a.filter((v,i)=>i).map(v=>[...v.split(\' \').map(n=>(+n.replace(\"\\n\", \'\')))])\n        ax=ay=az=0\n        a.map(v=>{\n          v[1]*=-1\n          if(recenter){\n            ax+=v[0]\n            ay+=v[1]\n            az+=v[2]\n          }\n        })\n        ax/=a.length\n        ay/=a.length\n        az/=a.length\n        a.map(v=>{\n          X=(v[0]-ax)*scale\n          Y=(v[1]-ay)*scale\n          Z=(v[2]-az)*scale\n          R2(rl,pt,yw,0)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n        })\n        maxY=-6e6\n        a.map(v=>{\n          if(v[1]>maxY)maxY=v[1]\n        })\n        a.map(v=>{\n          v[1]-=maxY-oY\n          v[0]+=tx\n          v[1]+=ty\n          v[2]+=tz\n        })\n\n        b=[]\n        data.split(\"\\nf \").map(v=>{\n          b=[...b, v.split(\"\\n\")[0]]\n        })\n        b.shift()\n        b=b.map(v=>v.split(\' \'))\n        b=b.map(v=>{\n          v=v.map(q=>{\n            return +q.split(\'/\')[0]\n          })\n          v=v.filter(q=>q)\n          return v\n        })\n\n        res=[]\n        b.map(v=>{\n          e=[]\n          v.map(q=>{\n            e=[...e, a[q-1]]\n          })\n          e = e.filter(q=>q)\n          res=[...res, e]\n        })\n      })\n      return res\n    }\n\n    function loadAnimation(name, size, X, Y, Z, rl, pt, yw, speed=1) {\n      \n      let rootURL = \'https://srmcgann.github.io/animations\'\n      if(typeof animations == \'undefined\') animations = []\n      \n      let animation = {\n        name             ,\n        speed            ,\n        frameCt:        0,\n        fileList:      \'\',\n        curFrame:       0,\n        loopRangeStart: 0,\n        loopRangeEnd:   0,\n        hasLoop:    false,\n        looping:    false,\n        frameData:     [],\n        loaded:     false,\n        active:      true,\n      }\n      \n      fetch(`${rootURL}/${name}/fileList.json`).then(v => v.json()).then(data => {\n        animation.fileList = data.fileList\n        if(animation.fileList.hasLoop){\n          animation.hasLoop = true\n          animation.looping = true\n          animation.loopRangeStart = animation.fileList.loopRangeStart\n          animation.loopRangeEnd = animation.fileList.loopRangeEnd\n        }\n        for(let i=0; i<+animation.fileList.fileCount; i++){\n          let file = `${rootURL}/${name}/${animation.fileList.fileName}${i}.${animation.fileList.suffix}`\n          loadOBJ(file, size, X,Y,Z, rl,pt,yw, false).then(el=>{\n            animation.frameData[i] = el\n            animation.frameCt++\n            if(animation.frameCt == +animation.fileList.fileCount) {\n              console.log(`loaded animation: ${name}`)\n              animation.loaded = true\n              animations = [...animations, animation]\n            }\n          })\n        }\n      })\n      return name\n    }\n    \n    drawAnimation = (animation, scol=\'\', fcol=\'\', lineWidth=2, glowing=true, overrideGlobalAlpha=1) => {\n      if(animation.loaded && animation.active){\n        animation.curFrame+=animation.speed\n        if(animation.hasLoop && animation.looping){\n          animation.curFrame %= Math.min(animation.loopRangeEnd, animation.frameCt)\n          if(animation.curFrame < 1) animation.curFrame = Math.max(0, animation.loopRangeStart)\n        }else{\n          animation.curFrame %= animation.frameCt\n        }\n        animation.frameData[animation.curFrame|0].map((v, i) => {\n          x.beginPath()\n          v.map(q=>{\n            X = q[0]\n            Y = q[1]\n            Z = q[2]\n            R(Rl,Pt,Yw,1)\n            if(Z>0) x.lineTo(...Q())\n          })\n          stroke(scol, fcol, lineWidth, glowing, overrideGlobalAlpha=1)\n        })\n      }\n    }\n    \n    geoSphere = (mx, my, mz, iBc, size) => {\n      let collapse=0\n      let B=Array(iBc).fill().map(v=>{\n        X = Rn()-.5\n        Y = Rn()-.5\n        Z = Rn()-.5\n        return  [X,Y,Z]\n      })\n      for(let m=200;m--;){\n        B.map((v,i)=>{\n          X = v[0]\n          Y = v[1]\n          Z = v[2]\n          B.map((q,j)=>{\n            if(j!=i){\n              X2=q[0]\n              Y2=q[1]\n              Z2=q[2]\n              d=1+(Math.hypot(X-X2,Y-Y2,Z-Z2)*(3+iBc/40)*3)**4\n              X+=(X-X2)*99/d\n              Y+=(Y-Y2)*99/d\n              Z+=(Z-Z2)*99/d\n            }\n          })\n          d=Math.hypot(X,Y,Z)\n          v[0]=X/d\n          v[1]=Y/d\n          v[2]=Z/d\n          if(collapse){\n            d=25+Math.hypot(X,Y,Z)\n            v[0]=(X-X/d)/1.1\n            v[1]=(Y-Y/d)/1.1         \n            v[2]=(Z-Z/d)/1.1\n          }\n        })\n      }\n      mind = 6e6\n      B.map((v,i)=>{\n        X1 = v[0]\n        Y1 = v[1]\n        Z1 = v[2]\n        B.map((q,j)=>{\n          X2 = q[0]\n          Y2 = q[1]\n          Z2 = q[2]\n          if(i!=j){\n            d = Math.hypot(a=X1-X2, b=Y1-Y2, e=Z1-Z2)\n            if(d<mind) mind = d\n          }\n        })\n      })\n      a = []\n      B.map((v,i)=>{\n        X1 = v[0]\n        Y1 = v[1]\n        Z1 = v[2]\n        B.map((q,j)=>{\n          X2 = q[0]\n          Y2 = q[1]\n          Z2 = q[2]\n          if(i!=j){\n            d = Math.hypot(X1-X2, Y1-Y2, Z1-Z2)\n            if(d<mind*2){\n              if(!a.filter(q=>q[0]==X2&&q[1]==Y2&&q[2]==Z2&&q[3]==X1&&q[4]==Y1&&q[5]==Z1).length) a = [...a, [X1*size,Y1*size,Z1*size,X2*size,Y2*size,Z2*size]]\n            }\n          }\n        })\n      })\n      B.map(v=>{\n        v[0]*=size\n        v[1]*=size\n        v[2]*=size\n        v[0]+=mx\n        v[1]+=my\n        v[2]+=mz\n      })\n      return [mx, my, mz, size, B, a]\n    }\n\n    lineFaceI = (X1, Y1, Z1, X2, Y2, Z2, facet, autoFlipNormals=false, showNormals=false) => {\n      let X_, Y_, Z_, d, m, l_,K,J,L,p\n      let I_=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n      let Q_=()=>[c.width/2+X_/Z_*600,c.height/2+Y_/Z_*600]\n      let R_ = (Rl,Pt,Yw,m)=>{\n        let M=Math, A=M.atan2, H=M.hypot\n        X_=S(p=A(X_,Y_)+Rl)*(d=H(X_,Y_)),Y_=C(p)*d,X_=S(p=A(X_,Z_)+Yw)*(d=H(X_,Z_)),Z_=C(p)*d,Y_=S(p=A(Y_,Z_)+Pt)*(d=H(Y_,Z_)),Z_=C(p)*d\n        if(m){ X_+=oX,Y_+=oY,Z_+=oZ }\n      }\n      let rotSwitch = m =>{\n        switch(m){\n          case 0: R_(0,0,Math.PI/2); break\n          case 1: R_(0,Math.PI/2,0); break\n          case 2: R_(Math.PI/2,0,Math.PI/2); break\n        }        \n      }\n      let ax = 0, ay = 0, az = 0\n      facet.map(q_=>{ ax += q_[0], ay += q_[1], az += q_[2] })\n      ax /= facet.length, ay /= facet.length, az /= facet.length\n      let b1 = facet[2][0]-facet[1][0], b2 = facet[2][1]-facet[1][1], b3 = facet[2][2]-facet[1][2]\n      let c1 = facet[1][0]-facet[0][0], c2 = facet[1][1]-facet[0][1], c3 = facet[1][2]-facet[0][2]\n      let crs = [b2*c3-b3*c2,b3*c1-b1*c3,b1*c2-b2*c1]\n      d = Math.hypot(...crs)+.001\n      let nls = 1 //normal line length\n      crs = crs.map(q=>q/d*nls)\n      let X1_ = ax, Y1_ = ay, Z1_ = az\n      let flip = 1\n      if(autoFlipNormals){\n        let d1_ = Math.hypot(X1_-X1,Y1_-Y1,Z1_-Z1)\n        let d2_ = Math.hypot(X1-(ax + crs[0]/99),Y1-(ay + crs[1]/99),Z1-(az + crs[2]/99))\n        flip = d2_>d1_?-1:1\n      }\n      let X2_ = ax + (crs[0]*=flip), Y2_ = ay + (crs[1]*=flip), Z2_ = az + (crs[2]*=flip)\n      if(showNormals){\n        x.beginPath()\n        X_ = X1_, Y_ = Y1_, Z_ = Z1_\n        R_(Rl,Pt,Yw,1)\n        if(Z_>0) x.lineTo(...Q_())\n        X_ = X2_, Y_ = Y2_, Z_ = Z2_\n        R_(Rl,Pt,Yw,1)\n        if(Z_>0) x.lineTo(...Q_())\n        x.lineWidth = 5\n        x.strokeStyle=\'#f004\'\n        x.stroke()\n      }\n\n      let p1_ = Math.atan2(X2_-X1_,Z2_-Z1_)\n      let p2_ = -(Math.acos((Y2_-Y1_)/(Math.hypot(X2_-X1_,Y2_-Y1_,Z2_-Z1_)+.001))+Math.PI/2)\n      let isc = false, iscs = [false,false,false]\n      X_ = X1, Y_ = Y1, Z_ = Z1\n      R_(0,-p2_,-p1_)\n      let rx_ = X_, ry_ = Y_, rz_ = Z_\n      for(let m=3;m--;){\n        if(isc === false){\n          X_ = rx_, Y_ = ry_, Z_ = rz_\n          rotSwitch(m)\n          X1_ = X_, Y1_ = Y_, Z1_ = Z_ = 5, X_ = X2, Y_ = Y2, Z_ = Z2\n          R_(0,-p2_,-p1_)\n          rotSwitch(m)\n          X2_ = X_, Y2_ = Y_, Z2_ = Z_\n          facet.map((q_,j_)=>{\n            if(isc === false){\n              let l = j_\n              X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n              R_(0,-p2_,-p1_)\n              rotSwitch(m)\n              let X3_=X_, Y3_=Y_, Z3_=Z_\n              l = (j_+1)%facet.length\n              X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n              R_(0,-p2_,-p1_)\n              rotSwitch(m)\n              let X4_ = X_, Y4_ = Y_, Z4_ = Z_\n              if(l_=I_(X1_,Y1_,X2_,Y2_,X3_,Y3_,X4_,Y4_)) iscs[m] = l_\n            }\n          })\n        }\n      }\n      if(iscs.filter(v=>v!==false).length==3){\n        let iscx = iscs[1][0], iscy = iscs[0][1], iscz = iscs[0][0]\n        let pointInPoly = true\n        ax=0, ay=0, az=0\n        facet.map((q_, j_)=>{ ax+=q_[0], ay+=q_[1], az+=q_[2] })\n        ax/=facet.length, ay/=facet.length, az/=facet.length\n        X_ = ax, Y_ = ay, Z_ = az\n        R_(0,-p2_,-p1_)\n        X1_ = X_, Y1_ = Y_, Z1_ = Z_\n        X2_ = iscx, Y2_ = iscy, Z2_ = iscz\n        facet.map((q_,j_)=>{\n          if(pointInPoly){\n            let l = j_\n            X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n            R_(0,-p2_,-p1_)\n            let X3_ = X_, Y3_ = Y_, Z3_ = Z_\n            l = (j_+1)%facet.length\n            X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n            R_(0,-p2_,-p1_)\n            let X4_ = X_, Y4_ = Y_, Z4_ = Z_\n            if(I_(X1_,Y1_,X2_,Y2_,X3_,Y3_,X4_,Y4_)) pointInPoly = false\n          }\n        })\n        if(pointInPoly){\n          X_ = iscx, Y_ = iscy, Z_ = iscz\n          R_(0,p2_,0)\n          R_(0,0,p1_)\n          isc = [[X_,Y_,Z_], [crs[0],crs[1],crs[2]]]\n        }\n      }\n      return isc\n    }\n\n    TruncatedOctahedron = ls => {\n      let shp = [], a = []\n      mind = 6e6\n      for(let i=6;i--;){\n        X = S(p=Math.PI*2/6*i+Math.PI/6)*ls\n        Y = C(p)*ls\n        Z = 0\n        if(Y<mind) mind = Y\n        a = [...a, [X, Y, Z]]\n      }\n      let theta = .6154797086703867\n      a.map(v=>{\n        X = v[0]\n        Y = v[1] - mind\n        Z = v[2]\n        R(0,theta,0)\n        v[0] = X\n        v[1] = Y\n        v[2] = Z+1.5\n      })\n      b = JSON.parse(JSON.stringify(a)).map(v=>{\n        v[1] *= -1\n        return v\n      })\n      shp = [...shp, a, b]\n      e = JSON.parse(JSON.stringify(shp)).map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n        return v\n      })\n      shp = [...shp, ...e]\n      e = JSON.parse(JSON.stringify(shp)).map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n        return v\n      })\n      shp = [...shp, ...e]\n\n      coords = [\n        [[3,1],[4,3],[4,4],[3,2]],\n        [[3,4],[3,3],[2,4],[6,2]],\n        [[1,4],[0,3],[0,4],[4,2]],\n        [[1,1],[1,2],[6,4],[7,3]],\n        [[3,5],[7,5],[1,5],[3,0]],\n        [[2,5],[6,5],[0,5],[4,5]]\n      ]\n      a = []\n      coords.map(v=>{\n        b = []\n        v.map(q=>{\n          X = shp[q[0]][q[1]][0]\n          Y = shp[q[0]][q[1]][1]\n          Z = shp[q[0]][q[1]][2]\n          b = [...b, [X,Y,Z]]\n        })\n        a = [...a, b]\n      })\n      shp = [...shp, ...a]\n      return shp.map(v=>{\n        v.map(q=>{\n          q[0]/=3\n          q[1]/=3\n          q[2]/=3\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n        return v\n      })\n    }\n\n    Cylinder = (rw,cl,ls1,ls2) => {\n      let a = []\n      for(let i=rw;i--;){\n        let b = []\n        for(let j=cl;j--;){\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n        }\n        //a = [...a, b]\n        for(let j=cl;j--;){\n          b = []\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(j+1)) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(j+1)) * ls1\n          Y = (1/rw*(i+1)-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*(i+1)-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          a = [...a, b]\n        }\n      }\n      b = []\n      for(let j=cl;j--;){\n        X = S(p=Math.PI*2/cl*j) * ls1\n        Y = ls2/2\n        Z = C(p) * ls1\n        b = [...b, [X,Y,Z]]\n      }\n      //a = [...a, b]\n      return a\n    }\n\n    Tetrahedron = size => {\n      ret = []\n      a = []\n      let h = size/1.4142/1.25\n      for(i=3;i--;){\n        X = S(p=Math.PI*2/3*i) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n      }\n      ret = [...ret, a]\n      for(j=3;j--;){\n        a = []\n        X = 0\n        Y = 0\n        Z = -h\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/3*j) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/3*(j+1)) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      ax=ay=az=ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax\n          q[1]-=ay\n          q[2]-=az\n        })\n      })\n      return ret\n    }\n\n    Cube = size => {\n      for(CB=[],j=6;j--;CB=[...CB,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?size/1.5:-size/1.5),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      return CB\n    }\n\n    Octahedron = size => {\n      ret = []\n      let h = size/1.25\n      for(j=8;j--;){\n        a = []\n        X = 0\n        Y = 0\n        Z = h * (j<4?-1:1)\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*j) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*(j+1)) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      return ret      \n    }\n\n    Dodecahedron = size => {\n      ret = []\n      a = []\n      mind = -6e6\n      for(i=5;i--;){\n        X=S(p=Math.PI*2/5*i + Math.PI/5)\n        Y=C(p)\n        Z=0\n        if(Y>mind) mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a.map(v=>{\n        X = v[0]\n        Y = v[1]-=mind\n        Z = v[2]\n        R(0, .553573, 0)\n        v[0] = X\n        v[1] = Y\n        v[2] = Z\n      })\n      b = JSON.parse(JSON.stringify(a))\n      b.map(v=>{\n        v[1] *= -1\n      })\n      ret = [...ret, a, b]\n      mind = -6e6\n      ret.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          if(Z>mind)mind = Z\n        })\n      })\n      d1=Math.hypot(ret[0][0][0]-ret[0][1][0],ret[0][0][1]-ret[0][1][1],ret[0][0][2]-ret[0][1][2])\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]-=mind+d1/2\n        })\n      })\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          q[2]*=-1\n        })\n      })\n      ret = [...ret, ...b]\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(0,Math.PI/2,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      e = JSON.parse(JSON.stringify(ret))\n      e.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(Math.PI/2,0,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      ret = [...ret, ...b, ...e]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0] *= size/2\n          q[1] *= size/2\n          q[2] *= size/2\n        })\n      })\n      return ret\n    }\n\n    Icosahedron = size => {\n      ret = []\n      let B = [\n        [[0,3],[1,0],[2,2]],\n        [[0,3],[1,0],[1,3]],\n        [[0,3],[2,3],[1,3]],\n        [[0,2],[2,1],[1,0]],\n        [[0,2],[1,3],[1,0]],\n        [[0,2],[1,3],[2,0]],\n        [[0,3],[2,2],[0,0]],\n        [[1,0],[2,2],[2,1]],\n        [[1,1],[2,2],[2,1]],\n        [[1,1],[2,2],[0,0]],\n        [[1,1],[2,1],[0,1]],\n        [[0,2],[2,1],[0,1]],\n        [[2,0],[1,2],[2,3]],\n        [[0,0],[0,3],[2,3]],\n        [[1,3],[2,0],[2,3]],\n        [[2,3],[0,0],[1,2]],\n        [[1,2],[2,0],[0,1]],\n        [[0,0],[1,2],[1,1]],\n        [[0,1],[1,2],[1,1]],\n        [[0,2],[2,0],[0,1]],\n      ]\n      for(p=[1,1],i=38;i--;)p=[...p,p[l=p.length-1]+p[l-1]]\n      phi = p[l]/p[l-1]\n      a = [\n        [-phi,-1,0],\n        [phi,-1,0],\n        [phi,1,0],\n        [-phi,1,0],\n      ]\n      for(j=3;j--;ret=[...ret, b])for(b=[],i=4;i--;) b = [...b, [a[i][j],a[i][(j+1)%3],a[i][(j+2)%3]]]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]*=size/2.25\n          q[1]*=size/2.25\n          q[2]*=size/2.25\n        })\n      })\n      cp = JSON.parse(JSON.stringify(ret))\n      out=[]\n      a = []\n      B.map(v=>{\n        idx1a = v[0][0]\n        idx2a = v[1][0]\n        idx3a = v[2][0]\n        idx1b = v[0][1]\n        idx2b = v[1][1]\n        idx3b = v[2][1]\n        a = [...a, [cp[idx1a][idx1b],cp[idx2a][idx2b],cp[idx3a][idx3b]]]\n      })\n      out = [...out, ...a]\n      return out\n    }\n\n    stroke = (scol, fcol, lwo=1, od=true, oga=1) => {\n      if(scol){\n        //x.closePath()\n        if(od) x.globalAlpha = .2*oga\n        x.strokeStyle = scol\n        x.lineWidth = Math.min(1000,100*lwo/Z)\n        if(od) x.stroke()\n        x.lineWidth /= 4\n        x.globalAlpha = 1*oga\n        x.stroke()\n      }\n      if(fcol){\n        x.globalAlpha = 1*oga\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n\n    subbed = (subs, size, sphereize, shape) => {\n      for(let m=subs; m--;){\n        base = shape\n        shape = []\n        base.map(v=>{\n          l = 0\n          X1 = v[l][0]\n          Y1 = v[l][1]\n          Z1 = v[l][2]\n          l = 1\n          X2 = v[l][0]\n          Y2 = v[l][1]\n          Z2 = v[l][2]\n          l = 2\n          X3 = v[l][0]\n          Y3 = v[l][1]\n          Z3 = v[l][2]\n          if(v.length > 3){\n            l = 3\n            X4 = v[l][0]\n            Y4 = v[l][1]\n            Z4 = v[l][2]\n            if(v.length > 4){\n              l = 4\n              X5 = v[l][0]\n              Y5 = v[l][1]\n              Z5 = v[l][2]\n            }\n          }\n          mx1 = (X1+X2)/2\n          my1 = (Y1+Y2)/2\n          mz1 = (Z1+Z2)/2\n          mx2 = (X2+X3)/2\n          my2 = (Y2+Y3)/2\n          mz2 = (Z2+Z3)/2\n          a = []\n          switch(v.length){\n            case 3:\n              mx3 = (X3+X1)/2\n              my3 = (Y3+Y1)/2\n              mz3 = (Z3+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 4:\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X1)/2\n              my4 = (Y4+Y1)/2\n              mz4 = (Z4+Z1)/2\n              cx = (X1+X2+X3+X4)/4\n              cy = (Y1+Y2+Y3+Y4)/4\n              cz = (Z1+Z2+Z3+Z4)/4\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 5:\n              cx = (X1+X2+X3+X4+X5)/5\n              cy = (Y1+Y2+Y3+Y4+Y5)/5\n              cz = (Z1+Z2+Z3+Z4+Z5)/5\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X5)/2\n              my4 = (Y4+Y5)/2\n              mz4 = (Z4+Z5)/2\n              mx5 = (X5+X1)/2\n              my5 = (Y5+Y1)/2\n              mz5 = (Z5+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              break\n          }\n        })\n      }\n      if(sphereize){\n        ip1 = sphereize\n        ip2 = 1-sphereize\n        shape = shape.map(v=>{\n          v = v.map(q=>{\n            X = q[0]\n            Y = q[1]\n            Z = q[2]\n            d = Math.hypot(X,Y,Z)\n            X /= d\n            Y /= d\n            Z /= d\n            X *= size*.75*ip1 + d*ip2\n            Y *= size*.75*ip1 + d*ip2\n            Z *= size*.75*ip1 + d*ip2\n            return [X,Y,Z]\n          })\n          return v\n        })\n      }\n      return shape\n    }\n\n    subDividedIcosahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Icosahedron(size))\n    subDividedTetrahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Tetrahedron(size))\n    subDividedOctahedron   = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Octahedron(size))\n    subDividedCube         = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Cube(size))\n    subDividedDodecahedron = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Dodecahedron(size))\n\n    Rn = Math.random\n\n    LsystemRecurse = (size, splits, p1, p2, stem, theta, LsystemReduction, twistFactor) => {\n      if(size < .25) return\n      let X1 = stem[0]\n      let Y1 = stem[1]\n      let Z1 = stem[2]\n      let X2 = stem[3]\n      let Y2 = stem[4]\n      let Z2 = stem[5]\n      let p1a = Math.atan2(X2-X1,Z2-Z1)\n      let p2a = -Math.acos((Y2-Y1)/(Math.hypot(X2-X1,Y2-Y1,Z2-Z1)+.0001))+Math.PI\n      size/=LsystemReduction\n      for(let i=splits;i--;){\n        X = 0\n        Y = -size\n        Z = 0\n        R(0, theta, 0)\n        R(0, 0, Math.PI*2/splits*i+twistFactor)\n        R(0, p2a, 0)\n        R(0, 0, p1a+twistFactor)\n        X+=X2\n        Y+=Y2\n        Z+=Z2\n        let newStem = [X2, Y2, Z2, X, Y, Z]\n        Lshp = [...Lshp, newStem]\n        LsystemRecurse(size, splits, p1+Math.PI*2/splits*i+twistFactor, p2+theta, newStem, theta, LsystemReduction, twistFactor)\n      }\n    }\n    DrawLsystem = shp => {\n      shp.map(v=>{\n        x.beginPath()\n        X = v[0]\n        Y = v[1]\n        Z = v[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        X = v[3]\n        Y = v[4]\n        Z = v[5]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        lwo = Math.hypot(v[0]-v[3],v[1]-v[4],v[2]-v[5])*4\n        stroke(\'#0f82\',\'\',lwo)\n      })\n\n    }\n    Lsystem = (size, splits, theta, LsystemReduction, twistFactor) => {\n      Lshp = []\n      stem = [0,0,0,0,-size,0]\n      Lshp = [...Lshp, stem]\n      LsystemRecurse(size, splits, 0, 0, stem, theta, LsystemReduction, twistFactor)\n      Lshp.map(v=>{\n        v[1]+=size*1.5\n        v[4]+=size*1.5\n      })\n      return Lshp\n    }\n\n    Sphere = (ls, rw, cl) => {\n      a = []\n      ls/=1.25\n      for(j = rw; j--;){\n        for(i = cl; i--;){\n          b = []\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          a = [...a, b]\n        }\n      }\n      return a\n    }\n\n    Torus = (rw, cl, ls1, ls2, parts=1, twists=0, part_spacing=1.5) => {\n      let ret = [], tx=0, ty=0, tz=0, prl1 = 0, p2a = 0\n      let tx1 = 0, ty1 = 0, tz1 = 0, prl2 = 0, p2b = 0, tx2 = 0, ty2 = 0, tz2 = 0\n      for(let m=parts;m--;){\n        avgs = Array(rw).fill().map(v=>[0,0,0])\n        for(j=rw;j--;)for(let i = cl;i--;){\n          if(parts>1){\n            ls3 = ls1*part_spacing\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl1 = Math.PI*2/rw*(j-1)*twists,0,0)\n            tx1 = X\n            ty1 = Y \n            tz1 = Z\n            R(0, 0, Math.PI*2/rw*(j-1))\n            ax1 = X\n            ay1 = Y\n            az1 = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl2 = Math.PI*2/rw*(j)*twists,0,0)\n            tx2 = X\n            ty2 = Y\n            tz2 = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax2 = X\n            ay2 = Y\n            az2 = Z\n            p1a = Math.atan2(ax2-ax1,az2-az1)\n            p2a = Math.PI/2+Math.acos((ay2-ay1)/(Math.hypot(ax2-ax1,ay2-ay1,az2-az1)+.001))\n\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j)*twists,0,0)\n            tx1b = X\n            ty1b = Y\n            tz1b = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax1b = X\n            ay1b = Y\n            az1b = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j+1)*twists,0,0)\n            tx2b = X\n            ty2b = Y\n            tz2b = Z\n            R(0, 0, Math.PI*2/rw*(j+1))\n            ax2b = X\n            ay2b = Y\n            az2b = Z\n            p1b = Math.atan2(ax2b-ax1b,az2b-az1b)\n            p2b = Math.PI/2+Math.acos((ay2b-ay1b)/(Math.hypot(ax2b-ax1b,ay2b-ay1b,az2b-az1b)+.001))\n          }\n          a = []\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          ret = [...ret, a]\n        }\n      }\n      return ret\n    }\n\n    G_ = 100000, iSTc = 1e4\n    ST = Array(iSTc).fill().map(v=>{\n      X = (Rn()-.5)*G_\n      Y = (Rn()-.5)*G_\n      Z = (Rn()-.5)*G_\n      return [X,Y,Z]\n    })\n\n    burst = new Image()\n    burst.src = \"https://srmcgann.github.io/temp/burst.png\"\n\n    starsLoaded = false, starImgs = [{loaded: false}]\n    starImgs = Array(9).fill().map((v,i) => {\n      let a = {img: new Image(), loaded: false}\n      a.img.onload = () => {\n        a.loaded = true\n        setTimeout(()=>{\n          if(starImgs.filter(v=>v.loaded).length == 9) starsLoaded = true\n        }, 0)\n      }\n      a.img.src = `https://srmcgann.github.io/stars/star${i+1}.png`\n      return a\n    })\n\n    showstars = true\n    \n    loadAnimation(\'back_flip_male\', 3, 0,12,0, 0,0,Math.PI/2, 1)\n    \n  }\n\n  oX=0, oY=0, oZ=24\n  Rl=0, Pt=-.2 + C(t)/2, Yw=t/4\n\n  x.globalAlpha = 1\n  x.fillStyle=\'#000a\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin = x.lineCap = \'roud\'\n\n  if(showstars) ST.map(v=>{\n    X = v[0]\n    Y = v[1]\n    Z = v[2]\n    R(Rl,Pt,Yw,1)\n    if(Z>0){\n      if((x.globalAlpha = Math.min(1,(Z/5e3)**2))>.1){\n        s = Math.min(1e3, 4e5/Z)\n        x.fillStyle = \'#ffffff04\'\n        l = Q()\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=5\n        x.fillStyle = \'#fffa\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n    }\n  })\n\n  x.globalAlpha = 1\n\n  animations.map(animation => {\n    drawAnimation(animation, \'#f004\', \'#f002\')\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\nDraw()', 'body,html{\n  background: #000;\n  margin: 0;\n  height: 100vh;\n  overflow: hidden;\n}\n#c{\n  background:#000;\n  position: absolute;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<canvas id=c>', 'loadAnimation Function', 145, 'whitehot robot', '2024-01-26 00:48:24', '[600762]', 39, '', 0, 0);
INSERT INTO `items` (`id`, `videoLink`, `demoJS`, `demoCSS`, `demoHTML`, `title`, `userID`, `author`, `created`, `forkHistory`, `views`, `videoThumb`, `videoViews`, `private`) VALUES
(600764, '', '/*\n// to do\n// âœ” crosshairs\n// âœ” bullets / riccochets\n// âœ” levels\n// âœ” AI players (practice mode)\n// âœ” scoring\n// âœ” HUD / info\n// âœ” level selection (by game creator / round winner)\n// âœ” disallow control of players @ cam view\n// âœ” re-select level / exit (for practice mode)\n// * arena integration (multiplayer mode)\n//   âœ” player death-splosions @ remote screens (vs. lerp-to-respawn)\n//   âœ” topo crosshair -> correct player\n//   âœ” key/mouse action @ other-player-cams does flashMessage\n//   âœ” cameras fixed (alt views have wrong orientation, e.g., also need info)\n//   âœ” sync random-seed level configs\n//   âœ” hotkeys legend\n//   âœ” add hotkeys to practice version\n//   âœ” players proper spawn location @ level change\n//   âœ” game link button\n*/\n\nc = document.querySelector(\'#c\')\nc.width = 1920\nc.height = 1080\nx = c.getContext(\'2d\')\nC = Math.cos\nS = Math.sin\nt = 0\nT = Math.tan\n\nrsz=window.onresize=()=>{\n  setTimeout(()=>{\n    if(document.body.clientWidth > document.body.clientHeight*1.77777778){\n      c.style.height = \'100vh\'\n      setTimeout(()=>c.style.width = c.clientHeight*1.77777778+\'px\',0)\n    }else{\n      c.style.width = \'100vw\'\n      setTimeout(()=>c.style.height =     c.clientWidth/1.77777778 + \'px\',0)\n    }\n  },0)\n}\nrsz()\n\nasync function Draw(){\n  oX=oY=oZ=0\n  Rl=0, Pt=0, Yw=0\n  if(!t){\n    HSVFromRGB = (R, G, B) => {\n      let R_=R/256\n      let G_=G/256\n      let B_=B/256\n      let Cmin = Math.min(R_,G_,B_)\n      let Cmax = Math.max(R_,G_,B_)\n      let val = Cmax //(Cmax+Cmin) / 2\n      let delta = Cmax-Cmin\n      let sat = Cmax ? delta / Cmax: 0\n      let min=Math.min(R,G,B)\n      let max=Math.max(R,G,B)\n      let hue = 0\n      if(delta){\n        if(R>=G && R>=B) hue = (G-B)/(max-min)\n        if(G>=R && G>=B) hue = 2+(B-R)/(max-min)\n        if(B>=G && B>=R) hue = 4+(R-G)/(max-min)\n      }\n      hue*=60\n      while(hue<0) hue+=360;\n      while(hue>=360) hue-=360;\n      return [hue, sat, val]\n    }\n\n    RGBFromHSV = (H, S, V) => {\n      while(H<0) H+=360;\n      while(H>=360) H-=360;\n      let C = V*S\n      let X = C * (1-Math.abs((H/60)%2-1))\n      let m = V-C\n      let R_, G_, B_\n      if(H>=0 && H < 60)    R_=C, G_=X, B_=0\n      if(H>=60 && H < 120)  R_=X, G_=C, B_=0\n      if(H>=120 && H < 180) R_=0, G_=C, B_=X\n      if(H>=180 && H < 240) R_=0, G_=X, B_=C\n      if(H>=240 && H < 300) R_=X, G_=0, B_=C\n      if(H>=300 && H < 360) R_=C, G_=0, B_=X\n      let R = (R_+m)*256\n      let G = (G_+m)*256\n      let B = (B_+m)*256\n      return [R,G,B]\n    }\n\n    R=R2=(Rl,Pt,Yw,m)=>{\n      M=Math\n      X-=oX\n      Y-=oY\n      Z-=oZ\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n    }\n    \n    R3=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n    }\n    \n    R4=(Rl,Pt,Yw,m)=>{\n      M=Math\n      A=M.atan2\n      H=M.hypot\n      X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n      Z=C(p)*d\n      Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n      Z=C(p)*d\n      X=S(p=A(X,Y)+Rl)*(d=H(X,Y))\n      Y=C(p)*d\n      if(m){\n        X+=0\n        Y+=0\n        Z+=m\n      }\n    }\n    Q4=()=>[X/Z*700, Y/Z*700]\n    \n    Q=()=>[c.width/2+X/Z*700, c.height/2+Y/Z*700]\n\n    I=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n\n    Rn = Math.random\n    async function loadOBJ(url, scale, tx, ty, tz, rl, pt, yw, recenter=true) {\n      let res\n      await fetch(url, res => res).then(data=>data.text()).then(data=>{\n        a=[]\n        data.split(\"\\nv \").map(v=>{\n          a=[...a, v.split(\"\\n\")[0]]\n        })\n        a=a.filter((v,i)=>i).map(v=>[...v.split(\' \').map(n=>(+n.replace(\"\\n\", \'\')))])\n        ax=ay=az=0\n        a.map(v=>{\n          v[1]*=-1\n          if(recenter){\n            ax+=v[0]\n            ay+=v[1]\n            az+=v[2]\n          }\n        })\n        ax/=a.length\n        ay/=a.length\n        az/=a.length\n        a.map(v=>{\n          X=(v[0]-ax)*scale\n          Y=(v[1]-ay)*scale\n          Z=(v[2]-az)*scale\n          R2(rl,pt,yw,0)\n          v[0]=X\n          v[1]=Y\n          v[2]=Z\n        })\n        maxY=-6e6\n        a.map(v=>{\n          if(v[1]>maxY)maxY=v[1]\n        })\n        a.map(v=>{\n          v[1]-=maxY-oY\n          v[0]+=tx\n          v[1]+=ty\n          v[2]+=tz\n        })\n\n        b=[]\n        data.split(\"\\nf \").map(v=>{\n          b=[...b, v.split(\"\\n\")[0]]\n        })\n        b.shift()\n        b=b.map(v=>v.split(\' \'))\n        b=b.map(v=>{\n          v=v.map(q=>{\n            return +q.split(\'/\')[0]\n          })\n          v=v.filter(q=>q)\n          return v\n        })\n\n        res=[]\n        b.map(v=>{\n          e=[]\n          v.map(q=>{\n            e=[...e, a[q-1]]\n          })\n          e = e.filter(q=>q)\n          res=[...res, e]\n        })\n      })\n      return res\n    }\n\n    function loadAnimation(name, size, X, Y, Z, rl, pt, yw, speed=1) {\n      \n      let rootURL = \'https://srmcgann.github.io/animations\'\n      if(typeof animations == \'undefined\') animations = []\n      \n      let animation = {\n        name             ,\n        speed            ,\n        frameCt:        0,\n        fileList:      \'\',\n        curFrame:       0,\n        loopRangeStart: 0,\n        loopRangeEnd:   0,\n        hasLoop:    false,\n        looping:    false,\n        frameData:     [],\n        loaded:     false,\n        active:      true,\n      }\n      \n      fetch(`${rootURL}/${name}/fileList.json`).then(v => v.json()).then(data => {\n        animation.fileList = data.fileList\n        if(animation.fileList.hasLoop){\n          animation.hasLoop = true\n          animation.looping = true\n          animation.loopRangeStart = animation.fileList.loopRangeStart\n          animation.loopRangeEnd = animation.fileList.loopRangeEnd\n        }\n        for(let i=0; i<+animation.fileList.fileCount; i++){\n          let file = `${rootURL}/${name}/${animation.fileList.fileName}${i}.${animation.fileList.suffix}`\n          loadOBJ(file, size, X,Y,Z, rl,pt,yw, false).then(el=>{\n            animation.frameData[i] = el\n            animation.frameCt++\n            if(animation.frameCt == +animation.fileList.fileCount) {\n              console.log(`loaded animation: ${name}`)\n              animation.loaded = true\n              animations = [...animations, animation]\n            }\n          })\n        }\n      })\n      return name\n    }\n    \n    drawAnimation = (animation_name, scol=\'\', fcol=\'\', lineWidth=2, glowing=true, overrideGlobalAlpha=1, player) => {\n      //let idx\n      //players.map((v,i) => {\n      //  if(player.id == v.id) idx = i\n      //})\n      //player = players[idx]\n      tx = player.lerpX\n      ty = player.lerpY + playerSize\n      tz = player.lerpZ\n      trl = player.rl\n      tpt = player.pt\n      tyw = player.yw\n      vx = player.vx\n      vy = player.vy\n      vz = player.vz\n      let animation = animations.filter(el => animation_name == el.name)// && el.loaded && el.active)\n      if(animation.length){\n        animation = animation[0]\n        if(animation_name == \'back_flip_male\') {\n          animation.speed = .7\n          animation.looping = false\n        }else if((d=Math.hypot(vx, vz))>.05) {\n          animation.speed =  d/4\n          animation.looping = true\n        }else{\n          player.animation.curFrame = 0\n          animation.looping = false\n        }\n        if(animation_name == \'flip\') animation.speed = 3\n        player.animation.curFrame+=animation.speed\n        if(animation.hasLoop && animation.looping){\n          player.animation.curFrame %= Math.min(animation.loopRangeEnd, animation.frameCt)\n          if(player.animation.curFrame < 1) player.animation.curFrame = Math.max(0, animation.loopRangeStart)\n        }else{\n          player.animation.curFrame %= animation.frameCt\n        }\n        animation.frameData[player.animation.curFrame|0].map((v, i) => {\n          x.beginPath()\n          v.map(q=>{\n            X = q[0]\n            Y = q[1]\n            Z = q[2]\n            R3(0, 0, player.lerpyw)\n            X+=tx\n            Y+=ty\n            Z+=tz\n            R(Rl,Pt,Yw,1)\n            if(Z>0) x.lineTo(...Q())\n          })\n          stroke(scol, fcol, lineWidth, glowing, overrideGlobalAlpha)\n        })\n      }\n    }\n    \n    geoSphere = (mx, my, mz, iBc, size) => {\n      let collapse=0\n      let B=Array(iBc).fill().map(v=>{\n        X = Rn()-.5\n        Y = Rn()-.5\n        Z = Rn()-.5\n        return  [X,Y,Z]\n      })\n      for(let m=200;m--;){\n        B.map((v,i)=>{\n          X = v[0]\n          Y = v[1]\n          Z = v[2]\n          B.map((q,j)=>{\n            if(j!=i){\n              X2=q[0]\n              Y2=q[1]\n              Z2=q[2]\n              d=1+(Math.hypot(X-X2,Y-Y2,Z-Z2)*(3+iBc/40)*3)**4\n              X+=(X-X2)*99/d\n              Y+=(Y-Y2)*99/d\n              Z+=(Z-Z2)*99/d\n            }\n          })\n          d=Math.hypot(X,Y,Z)\n          v[0]=X/d\n          v[1]=Y/d\n          v[2]=Z/d\n          if(collapse){\n            d=25+Math.hypot(X,Y,Z)\n            v[0]=(X-X/d)/1.1\n            v[1]=(Y-Y/d)/1.1         \n            v[2]=(Z-Z/d)/1.1\n          }\n        })\n      }\n      mind = 6e6\n      B.map((v,i)=>{\n        X1 = v[0]\n        Y1 = v[1]\n        Z1 = v[2]\n        B.map((q,j)=>{\n          X2 = q[0]\n          Y2 = q[1]\n          Z2 = q[2]\n          if(i!=j){\n            d = Math.hypot(a=X1-X2, b=Y1-Y2, e=Z1-Z2)\n            if(d<mind) mind = d\n          }\n        })\n      })\n      a = []\n      B.map((v,i)=>{\n        X1 = v[0]\n        Y1 = v[1]\n        Z1 = v[2]\n        B.map((q,j)=>{\n          X2 = q[0]\n          Y2 = q[1]\n          Z2 = q[2]\n          if(i!=j){\n            d = Math.hypot(X1-X2, Y1-Y2, Z1-Z2)\n            if(d<mind*2){\n              if(!a.filter(q=>q[0]==X2&&q[1]==Y2&&q[2]==Z2&&q[3]==X1&&q[4]==Y1&&q[5]==Z1).length) a = [...a, [X1*size,Y1*size,Z1*size,X2*size,Y2*size,Z2*size]]\n            }\n          }\n        })\n      })\n      B.map(v=>{\n        v[0]*=size\n        v[1]*=size\n        v[2]*=size\n        v[0]+=mx\n        v[1]+=my\n        v[2]+=mz\n      })\n      return [mx, my, mz, size, B, a]\n    }\n\n    lineFaceI = (X1, Y1, Z1, X2, Y2, Z2, facet, autoFlipNormals=false, showNormals=false) => {\n      let X_, Y_, Z_, d, m, l_,K,J,L,p\n      let I_=(A,B,M,D,E,F,G,H)=>(K=((G-E)*(B-F)-(H-F)*(A-E))/(J=(H-F)*(M-A)-(G-E)*(D-B)))>=0&&K<=1&&(L=((M-A)*(B-F)-(D-B)*(A-E))/J)>=0&&L<=1?[A+K*(M-A),B+K*(D-B)]:0\n      let M=Math, A=M.atan2, H=M.hypot\n      let R_ = (Rl,Pt,Yw,m)=>{\n        X_=S(p=A(X_,Y_)+Rl)*(d=H(X_,Y_)),Y_=C(p)*d,X_=S(p=A(X_,Z_)+Yw)*(d=H(X_,Z_)),Z_=C(p)*d,Y_=S(p=A(Y_,Z_)+Pt)*(d=H(Y_,Z_)),Z_=C(p)*d\n        if(m){ X_+=oX,Y_+=oY,Z_+=oZ }\n      }\n      let R2_ = (Rl,Pt,Yw,m)=>{\n        X_-=oX\n        Y_-=oY\n        Z_-=oZ\n        A=M.atan2\n        H=M.hypot\n        X_=S(p=A(X_,Z_)+Yw)*(d=H(X_,Z_))\n        Z_=C(p)*d\n        Y_=S(p=A(Y_,Z_)+Pt)*(d=H(Y_,Z_))\n        Z_=C(p)*d\n        X_=S(p=A(X_,Y_)+Rl)*(d=H(X_,Y_))\n        Y_=C(p)*d\n      }\n      Q_=()=>[c.width/2+X_/Z_*600, c.height/2+Y_/Z_*600]\n      let rotSwitch = m =>{\n        switch(m){\n          case 0: R_(0,0,Math.PI/2); break\n          case 1: R_(0,Math.PI/2,0); break\n          case 2: R_(Math.PI/2,0,Math.PI/2); break\n        }        \n      }\n      let ax = 0, ay = 0, az = 0\n      facet.map(q_=>{ ax += q_[0], ay += q_[1], az += q_[2] })\n      ax /= facet.length, ay /= facet.length, az /= facet.length\n      let b1 = facet[2][0]-facet[1][0], b2 = facet[2][1]-facet[1][1], b3 = facet[2][2]-facet[1][2]\n      let c1 = facet[1][0]-facet[0][0], c2 = facet[1][1]-facet[0][1], c3 = facet[1][2]-facet[0][2]\n      let crs = [b2*c3-b3*c2,b3*c1-b1*c3,b1*c2-b2*c1]\n      d = Math.hypot(...crs)+.001\n      let nls = 1 //normal line length\n      crs = crs.map(q=>q/d*nls)\n      let X1_ = ax, Y1_ = ay, Z1_ = az\n      let flip = 1\n      if(autoFlipNormals){\n        let d1_ = Math.hypot(X1_-X1,Y1_-Y1,Z1_-Z1)\n        let d2_ = Math.hypot(X1-(ax + crs[0]/99),Y1-(ay + crs[1]/99),Z1-(az + crs[2]/99))\n        flip = d2_>d1_?-1:1\n      }\n      let X2_ = ax + (crs[0]*=flip), Y2_ = ay + (crs[1]*=flip), Z2_ = az + (crs[2]*=flip)\n      if(showNormals){\n        x.beginPath()\n        X_ = X1_, Y_ = Y1_, Z_ = Z1_\n        R2_(Rl,Pt,Yw,1)\n        if(Z_>0) x.lineTo(...Q_())\n        X_ = ax + crs[0] * 10\n        Y_ = ay + crs[1] * 10\n        Z_ = az + crs[2] * 10\n        R2_(Rl,Pt,Yw,1)\n        if(Z_>0) x.lineTo(...Q_())\n        x.lineWidth = 5\n        x.strokeStyle=\'#f008\'\n        x.stroke()\n      }\n\n      let p1_ = Math.atan2(X2_-X1_,Z2_-Z1_)\n      let p2_ = -(Math.acos((Y2_-Y1_)/(Math.hypot(X2_-X1_,Y2_-Y1_,Z2_-Z1_)+.001))+Math.PI/2)\n      let isc = false, iscs = [false,false,false]\n      X_ = X1, Y_ = Y1, Z_ = Z1\n      R_(0,-p2_,-p1_)\n      let rx_ = X_, ry_ = Y_, rz_ = Z_\n      for(let m=3;m--;){\n        if(isc === false){\n          X_ = rx_, Y_ = ry_, Z_ = rz_\n          rotSwitch(m)\n          X1_ = X_, Y1_ = Y_, Z1_ = Z_ = 5, X_ = X2, Y_ = Y2, Z_ = Z2\n          R_(0,-p2_,-p1_)\n          rotSwitch(m)\n          X2_ = X_, Y2_ = Y_, Z2_ = Z_\n          facet.map((q_,j_)=>{\n            if(isc === false){\n              let l = j_\n              X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n              R_(0,-p2_,-p1_)\n              rotSwitch(m)\n              let X3_=X_, Y3_=Y_, Z3_=Z_\n              l = (j_+1)%facet.length\n              X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n              R_(0,-p2_,-p1_)\n              rotSwitch(m)\n              let X4_ = X_, Y4_ = Y_, Z4_ = Z_\n              if(l_=I_(X1_,Y1_,X2_,Y2_,X3_,Y3_,X4_,Y4_)) iscs[m] = l_\n            }\n          })\n        }\n      }\n      if(iscs.filter(v=>v!==false).length==3){\n        let iscx = iscs[1][0], iscy = iscs[0][1], iscz = iscs[0][0]\n        let pointInPoly = true\n        ax=0, ay=0, az=0\n        facet.map((q_, j_)=>{ ax+=q_[0], ay+=q_[1], az+=q_[2] })\n        ax/=facet.length, ay/=facet.length, az/=facet.length\n        X_ = ax, Y_ = ay, Z_ = az\n        R_(0,-p2_,-p1_)\n        X1_ = X_, Y1_ = Y_, Z1_ = Z_\n        X2_ = iscx, Y2_ = iscy, Z2_ = iscz\n        facet.map((q_,j_)=>{\n          if(pointInPoly){\n            let l = j_\n            X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n            R_(0,-p2_,-p1_)\n            let X3_ = X_, Y3_ = Y_, Z3_ = Z_\n            l = (j_+1)%facet.length\n            X_ = facet[l][0], Y_ = facet[l][1], Z_ = facet[l][2]\n            R_(0,-p2_,-p1_)\n            let X4_ = X_, Y4_ = Y_, Z4_ = Z_\n            if(I_(X1_,Y1_,X2_,Y2_,X3_,Y3_,X4_,Y4_)) pointInPoly = false\n          }\n        })\n        if(pointInPoly){\n          X_ = iscx, Y_ = iscy, Z_ = iscz\n          R_(0,p2_,0)\n          R_(0,0,p1_)\n          isc = [[X_,Y_,Z_], [crs[0],crs[1],crs[2]]]\n        }\n      }\n      return isc\n    }\n\n    TruncatedOctahedron = ls => {\n      let shp = [], a = []\n      mind = 6e6\n      for(let i=6;i--;){\n        X = S(p=Math.PI*2/6*i+Math.PI/6)*ls\n        Y = C(p)*ls\n        Z = 0\n        if(Y<mind) mind = Y\n        a = [...a, [X, Y, Z]]\n      }\n      let theta = .6154797086703867\n      a.map(v=>{\n        X = v[0]\n        Y = v[1] - mind\n        Z = v[2]\n        R(0,theta,0)\n        v[0] = X\n        v[1] = Y\n        v[2] = Z+1.5\n      })\n      b = JSON.parse(JSON.stringify(a)).map(v=>{\n        v[1] *= -1\n        return v\n      })\n      shp = [...shp, a, b]\n      e = JSON.parse(JSON.stringify(shp)).map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n        return v\n      })\n      shp = [...shp, ...e]\n      e = JSON.parse(JSON.stringify(shp)).map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n        return v\n      })\n      shp = [...shp, ...e]\n\n      coords = [\n        [[3,1],[4,3],[4,4],[3,2]],\n        [[3,4],[3,3],[2,4],[6,2]],\n        [[1,4],[0,3],[0,4],[4,2]],\n        [[1,1],[1,2],[6,4],[7,3]],\n        [[3,5],[7,5],[1,5],[3,0]],\n        [[2,5],[6,5],[0,5],[4,5]]\n      ]\n      a = []\n      coords.map(v=>{\n        b = []\n        v.map(q=>{\n          X = shp[q[0]][q[1]][0]\n          Y = shp[q[0]][q[1]][1]\n          Z = shp[q[0]][q[1]][2]\n          b = [...b, [X,Y,Z]]\n        })\n        a = [...a, b]\n      })\n      shp = [...shp, ...a]\n      return shp.map(v=>{\n        v.map(q=>{\n          q[0]/=3\n          q[1]/=3\n          q[2]/=3\n          q[0]*=ls\n          q[1]*=ls\n          q[2]*=ls\n        })\n        return v\n      })\n    }\n\n    Cylinder = (rw,cl,ls1,ls2) => {\n      let a = []\n      for(let i=rw;i--;){\n        let b = []\n        for(let j=cl;j--;){\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n        }\n        //a = [...a, b]\n        for(let j=cl;j--;){\n          b = []\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(j+1)) * ls1\n          Y = (1/rw*i-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(j+1)) * ls1\n          Y = (1/rw*(i+1)-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*j) * ls1\n          Y = (1/rw*(i+1)-.5)*ls2\n          Z = C(p) * ls1\n          b = [...b, [X,Y,Z]]\n          a = [...a, b]\n        }\n      }\n      b = []\n      for(let j=cl;j--;){\n        X = S(p=Math.PI*2/cl*j) * ls1\n        Y = ls2/2\n        Z = C(p) * ls1\n        b = [...b, [X,Y,Z]]\n      }\n      //a = [...a, b]\n      return a\n    }\n\n    Tetrahedron = size => {\n      ret = []\n      a = []\n      let h = size/1.4142/1.25\n      for(i=3;i--;){\n        X = S(p=Math.PI*2/3*i) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n      }\n      ret = [...ret, a]\n      for(j=3;j--;){\n        a = []\n        X = 0\n        Y = 0\n        Z = -h\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/3*j) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/3*(j+1)) * size/1.25\n        Y = C(p) * size/1.25\n        Z = h\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      ax=ay=az=ct=0\n      ret.map(v=>{\n        v.map(q=>{\n          ax+=q[0]\n          ay+=q[1]\n          az+=q[2]\n          ct++\n        })\n      })\n      ax/=ct\n      ay/=ct\n      az/=ct\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]-=ax\n          q[1]-=ay\n          q[2]-=az\n        })\n      })\n      return ret\n    }\n\n    Cube = size => {\n      for(CB=[],j=6;j--;CB=[...CB,b])for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?size/1.5:-size/1.5),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n      return CB\n    }\n\n    Cube2 = size => {\n      for(CB=[],j=6;j--;){\n        for(b=[],i=4;i--;)b=[...b,[(a=[S(p=Math.PI*2/4*i+Math.PI/4),C(p),2**.5/2])[j%3]*(l=j<3?size/1.5:-size/1.5),a[(j+1)%3]*l/1,a[(j+2)%3]*l]]\n        if(j!=4)CB=[...CB,b]\n      }\n      return CB\n    }\n\n    Octahedron = size => {\n      ret = []\n      let h = size/1.25\n      for(j=8;j--;){\n        a = []\n        X = 0\n        Y = 0\n        Z = h * (j<4?-1:1)\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*j) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        X = S(p=Math.PI*2/4*(j+1)) * size/1.25\n        Y = C(p) * size/1.25\n        Z = 0\n        a = [...a, [X,Y,Z]]\n        ret = [...ret, a]\n      }\n      return ret      \n    }\n\n    Dodecahedron = size => {\n      ret = []\n      a = []\n      mind = -6e6\n      for(i=5;i--;){\n        X=S(p=Math.PI*2/5*i + Math.PI/5)\n        Y=C(p)\n        Z=0\n        if(Y>mind) mind=Y\n        a = [...a, [X,Y,Z]]\n      }\n      a.map(v=>{\n        X = v[0]\n        Y = v[1]-=mind\n        Z = v[2]\n        R(0, .553573, 0)\n        v[0] = X\n        v[1] = Y\n        v[2] = Z\n      })\n      b = JSON.parse(JSON.stringify(a))\n      b.map(v=>{\n        v[1] *= -1\n      })\n      ret = [...ret, a, b]\n      mind = -6e6\n      ret.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          if(Z>mind)mind = Z\n        })\n      })\n      d1=Math.hypot(ret[0][0][0]-ret[0][1][0],ret[0][0][1]-ret[0][1][1],ret[0][0][2]-ret[0][1][2])\n      ret.map(v=>{\n        v.map(q=>{\n          q[2]-=mind+d1/2\n        })\n      })\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          q[2]*=-1\n        })\n      })\n      ret = [...ret, ...b]\n      b = JSON.parse(JSON.stringify(ret))\n      b.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(0,Math.PI/2,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      e = JSON.parse(JSON.stringify(ret))\n      e.map(v=>{\n        v.map(q=>{\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R(0,0,Math.PI/2)\n          R(Math.PI/2,0,0)\n          q[0] = X\n          q[1] = Y\n          q[2] = Z\n        })\n      })\n      ret = [...ret, ...b, ...e]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0] *= size/2\n          q[1] *= size/2\n          q[2] *= size/2\n        })\n      })\n      return ret\n    }\n\n    Icosahedron = size => {\n      ret = []\n      let B = [\n        [[0,3],[1,0],[2,2]],\n        [[0,3],[1,0],[1,3]],\n        [[0,3],[2,3],[1,3]],\n        [[0,2],[2,1],[1,0]],\n        [[0,2],[1,3],[1,0]],\n        [[0,2],[1,3],[2,0]],\n        [[0,3],[2,2],[0,0]],\n        [[1,0],[2,2],[2,1]],\n        [[1,1],[2,2],[2,1]],\n        [[1,1],[2,2],[0,0]],\n        [[1,1],[2,1],[0,1]],\n        [[0,2],[2,1],[0,1]],\n        [[2,0],[1,2],[2,3]],\n        [[0,0],[0,3],[2,3]],\n        [[1,3],[2,0],[2,3]],\n        [[2,3],[0,0],[1,2]],\n        [[1,2],[2,0],[0,1]],\n        [[0,0],[1,2],[1,1]],\n        [[0,1],[1,2],[1,1]],\n        [[0,2],[2,0],[0,1]],\n      ]\n      for(p=[1,1],i=38;i--;)p=[...p,p[l=p.length-1]+p[l-1]]\n      phi = p[l]/p[l-1]\n      a = [\n        [-phi,-1,0],\n        [phi,-1,0],\n        [phi,1,0],\n        [-phi,1,0],\n      ]\n      for(j=3;j--;ret=[...ret, b])for(b=[],i=4;i--;) b = [...b, [a[i][j],a[i][(j+1)%3],a[i][(j+2)%3]]]\n      ret.map(v=>{\n        v.map(q=>{\n          q[0]*=size/2.25\n          q[1]*=size/2.25\n          q[2]*=size/2.25\n        })\n      })\n      cp = JSON.parse(JSON.stringify(ret))\n      out=[]\n      a = []\n      B.map(v=>{\n        idx1a = v[0][0]\n        idx2a = v[1][0]\n        idx3a = v[2][0]\n        idx1b = v[0][1]\n        idx2b = v[1][1]\n        idx3b = v[2][1]\n        a = [...a, [cp[idx1a][idx1b],cp[idx2a][idx2b],cp[idx3a][idx3b]]]\n      })\n      out = [...out, ...a]\n      return out\n    }\n\n    stroke = (scol, fcol, lwo=1, od=true, oga=1) => {\n      if(scol){\n        x.closePath()\n        if(od) x.globalAlpha = .2*oga\n        x.strokeStyle = scol\n        x.lineWidth = Math.min(100,100*lwo/Z)\n        if(od) x.stroke()\n        x.lineWidth /= 4\n        x.globalAlpha = 1*oga\n        x.stroke()\n      }\n      if(fcol){\n        x.globalAlpha = 1*oga\n        x.fillStyle = fcol\n        x.fill()\n      }\n    }\n\n    subbed = (subs, size, sphereize, shape) => {\n      for(let m=subs; m--;){\n        base = shape\n        shape = []\n        base.map(v=>{\n          l = 0\n          X1 = v[l][0]\n          Y1 = v[l][1]\n          Z1 = v[l][2]\n          l = 1\n          X2 = v[l][0]\n          Y2 = v[l][1]\n          Z2 = v[l][2]\n          l = 2\n          X3 = v[l][0]\n          Y3 = v[l][1]\n          Z3 = v[l][2]\n          if(v.length > 3){\n            l = 3\n            X4 = v[l][0]\n            Y4 = v[l][1]\n            Z4 = v[l][2]\n            if(v.length > 4){\n              l = 4\n              X5 = v[l][0]\n              Y5 = v[l][1]\n              Z5 = v[l][2]\n            }\n          }\n          mx1 = (X1+X2)/2\n          my1 = (Y1+Y2)/2\n          mz1 = (Z1+Z2)/2\n          mx2 = (X2+X3)/2\n          my2 = (Y2+Y3)/2\n          mz2 = (Z2+Z3)/2\n          a = []\n          switch(v.length){\n            case 3:\n              mx3 = (X3+X1)/2\n              my3 = (Y3+Y1)/2\n              mz3 = (Z3+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 4:\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X1)/2\n              my4 = (Y4+Y1)/2\n              mz4 = (Z4+Z1)/2\n              cx = (X1+X2+X3+X4)/4\n              cy = (Y1+Y2+Y3+Y4)/4\n              cz = (Z1+Z2+Z3+Z4)/4\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx1, Y = my1, Z = mz1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx2, Y = my2, Z = mz2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = mx4, Y = my4, Z = mz4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              X = mx3, Y = my3, Z = mz3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              break\n            case 5:\n              cx = (X1+X2+X3+X4+X5)/5\n              cy = (Y1+Y2+Y3+Y4+Y5)/5\n              cz = (Z1+Z2+Z3+Z4+Z5)/5\n              mx3 = (X3+X4)/2\n              my3 = (Y3+Y4)/2\n              mz3 = (Z3+Z4)/2\n              mx4 = (X4+X5)/2\n              my4 = (Y4+Y5)/2\n              mz4 = (Z4+Z5)/2\n              mx5 = (X5+X1)/2\n              my5 = (Y5+Y1)/2\n              mz5 = (Z5+Z1)/2\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X2, Y = Y2, Z = Z2, a = [...a, [X,Y,Z]]\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X3, Y = Y3, Z = Z3, a = [...a, [X,Y,Z]]\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X4, Y = Y4, Z = Z4, a = [...a, [X,Y,Z]]\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              X = X5, Y = Y5, Z = Z5, a = [...a, [X,Y,Z]]\n              X = X1, Y = Y1, Z = Z1, a = [...a, [X,Y,Z]]\n              X = cx, Y = cy, Z = cz, a = [...a, [X,Y,Z]]\n              shape = [...shape, a]\n              a = []\n              break\n          }\n        })\n      }\n      if(sphereize){\n        ip1 = sphereize\n        ip2 = 1-sphereize\n        shape = shape.map(v=>{\n          v = v.map(q=>{\n            X = q[0]\n            Y = q[1]\n            Z = q[2]\n            d = Math.hypot(X,Y,Z)\n            X /= d\n            Y /= d\n            Z /= d\n            X *= size*.75*ip1 + d*ip2\n            Y *= size*.75*ip1 + d*ip2\n            Z *= size*.75*ip1 + d*ip2\n            return [X,Y,Z]\n          })\n          return v\n        })\n      }\n      return shape\n    }\n\n    subDividedIcosahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Icosahedron(size))\n    subDividedTetrahedron  = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Tetrahedron(size))\n    subDividedOctahedron   = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Octahedron(size))\n    subDividedCube         = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Cube(size))\n    subDividedDodecahedron = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Dodecahedron(size))\n    subDividedPlatform     = (size, subs, sphereize = 0) => subbed(subs, size, sphereize, Cube2(size))\n\n    Rn = Math.random\n\n    LsystemRecurse = (size, splits, p1, p2, stem, theta, LsystemReduction, twistFactor) => {\n      if(size < .25) return\n      let X1 = stem[0]\n      let Y1 = stem[1]\n      let Z1 = stem[2]\n      let X2 = stem[3]\n      let Y2 = stem[4]\n      let Z2 = stem[5]\n      let p1a = Math.atan2(X2-X1,Z2-Z1)\n      let p2a = -Math.acos((Y2-Y1)/(Math.hypot(X2-X1,Y2-Y1,Z2-Z1)+.0001))+Math.PI\n      size/=LsystemReduction\n      for(let i=splits;i--;){\n        X = 0\n        Y = -size\n        Z = 0\n        R(0, theta, 0)\n        R(0, 0, Math.PI*2/splits*i+twistFactor)\n        R(0, p2a, 0)\n        R(0, 0, p1a+twistFactor)\n        X+=X2\n        Y+=Y2\n        Z+=Z2\n        let newStem = [X2, Y2, Z2, X, Y, Z]\n        Lshp = [...Lshp, newStem]\n        LsystemRecurse(size, splits, p1+Math.PI*2/splits*i+twistFactor, p2+theta, newStem, theta, LsystemReduction, twistFactor)\n      }\n    }\n    DrawLsystem = shp => {\n      shp.map(v=>{\n        x.beginPath()\n        X = v[0]\n        Y = v[1]\n        Z = v[2]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        X = v[3]\n        Y = v[4]\n        Z = v[5]\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n        lwo = Math.hypot(v[0]-v[3],v[1]-v[4],v[2]-v[5])*4\n        stroke(\'#0f82\',\'\',lwo)\n      })\n\n    }\n    Lsystem = (size, splits, theta, LsystemReduction, twistFactor) => {\n      Lshp = []\n      stem = [0,0,0,0,-size,0]\n      Lshp = [...Lshp, stem]\n      LsystemRecurse(size, splits, 0, 0, stem, theta, LsystemReduction, twistFactor)\n      Lshp.map(v=>{\n        v[1]+=size*1.5\n        v[4]+=size*1.5\n      })\n      return Lshp\n    }\n\n    Sphere = (ls, rw, cl) => {\n      a = []\n      ls/=1.25\n      for(j = rw; j--;){\n        for(i = cl; i--;){\n          b = []\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*j) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*(i+1)) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          X = S(p = Math.PI*2/cl*i) * S(q = Math.PI/rw*(j+1)) * ls\n          Y = C(q) * ls\n          Z = C(p) * S(q) * ls\n          b = [...b, [X,Y,Z]]\n          a = [...a, b]\n        }\n      }\n      return a\n    }\n\n    Torus = (rw, cl, ls1, ls2, parts=1, twists=0, part_spacing=1.5) => {\n      let ret = [], tx=0, ty=0, tz=0, prl1 = 0, p2a = 0\n      let tx1 = 0, ty1 = 0, tz1 = 0, prl2 = 0, p2b = 0, tx2 = 0, ty2 = 0, tz2 = 0\n      for(let m=parts;m--;){\n        avgs = Array(rw).fill().map(v=>[0,0,0])\n        for(j=rw;j--;)for(let i = cl;i--;){\n          if(parts>1){\n            ls3 = ls1*part_spacing\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl1 = Math.PI*2/rw*(j-1)*twists,0,0)\n            tx1 = X\n            ty1 = Y \n            tz1 = Z\n            R(0, 0, Math.PI*2/rw*(j-1))\n            ax1 = X\n            ay1 = Y\n            az1 = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(prl2 = Math.PI*2/rw*(j)*twists,0,0)\n            tx2 = X\n            ty2 = Y\n            tz2 = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax2 = X\n            ay2 = Y\n            az2 = Z\n            p1a = Math.atan2(ax2-ax1,az2-az1)\n            p2a = Math.PI/2+Math.acos((ay2-ay1)/(Math.hypot(ax2-ax1,ay2-ay1,az2-az1)+.001))\n\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j)*twists,0,0)\n            tx1b = X\n            ty1b = Y\n            tz1b = Z\n            R(0, 0, Math.PI*2/rw*j)\n            ax1b = X\n            ay1b = Y\n            az1b = Z\n            X = S(p=Math.PI*2/parts*m) * ls3\n            Y = C(p) * ls3\n            Z = 0\n            R(Math.PI*2/rw*(j+1)*twists,0,0)\n            tx2b = X\n            ty2b = Y\n            tz2b = Z\n            R(0, 0, Math.PI*2/rw*(j+1))\n            ax2b = X\n            ay2b = Y\n            az2b = Z\n            p1b = Math.atan2(ax2b-ax1b,az2b-az1b)\n            p2b = Math.PI/2+Math.acos((ay2b-ay1b)/(Math.hypot(ax2b-ax1b,ay2b-ay1b,az2b-az1b)+.001))\n          }\n          a = []\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1a)\n          R(prl1,p2a,0)\n          X += ls2 + tx1, Y += ty1, Z += tz1\n          R(0, 0, Math.PI*2/rw*j)\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*(i+1)) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          X = S(p=Math.PI*2/cl*i) * ls1\n          Y = C(p) * ls1\n          Z = 0\n          //R(0,0,-p1b)\n          R(prl2,p2b,0)\n          X += ls2 + tx2, Y += ty2, Z += tz2\n          R(0, 0, Math.PI*2/rw*(j+1))\n          a = [...a, [X,Y,Z]]\n          ret = [...ret, a]\n        }\n      }\n      return ret\n    }\n\n    G_ = 1e5, iSTc = 3e3\n    ST = Array(iSTc).fill().map(v=>{\n      X = (Rn()-.5)*G_\n      Y = (Rn()-.5)*G_\n      Z = (Rn()-.5)*G_\n      return [X,Y,Z]\n    })\n\n    burst = new Image()\n    burst.src = \"https://srmcgann.github.io/temp/burst.png\"\n\n    levels = new Image()\n    levels.src = \"https://srmcgann.github.io/temp7/levels.png\"\n\n    crosshairsLoaded = false, crosshairImgs = [{loaded: false}]\n    crosshairImgs = Array(3).fill().map((v,i) => {\n      let a = {img: new Image(), loaded: false}\n      a.img.onload = () => {\n        a.loaded = true\n        setTimeout(()=>{\n          if(crosshairImgs.filter(v=>v.loaded).length == 3) crosshairsLoaded = true\n        }, 0)\n      }\n      a.img.src = `https://srmcgann.github.io/temp7/crosshair${i+1}.png`\n      return a\n    })\n\n    starsLoaded = false, starImgs = [{loaded: false}]\n    starImgs = Array(9).fill().map((v,i) => {\n      let a = {img: new Image(), loaded: false}\n      a.img.onload = () => {\n        a.loaded = true\n        setTimeout(()=>{\n          if(starImgs.filter(v=>v.loaded).length == 9) starsLoaded = true\n        }, 0)\n      }\n      a.img.src = `https://srmcgann.github.io/stars/star${i+1}.png`\n      return a\n    })\n    \n    rand = () => {\n      return ((randSeed+(randCt++)) ** 3.1/99) % 1\n    }\n\n    spawnShape = (X, Y, Z, shapeType, size, subs, convexity) => {\n      let base_shape = eval(`${shapeType}(shpls = ${size}, ${subs}, ${convexity})`)\n      let maximus = -6e6\n      let minimus = 6e6\n      base_shape.map(v => {\n        v.map(q=>{\n          X2 = q[0]\n          Y2 = q[1]\n          Z2 = q[2]\n          d = Math.hypot(q[1], q[2])\n          p = Math.atan2(Y2,Z2)// - Math.PI*1.5\n          q[1] = S(p) * d\n          q[2] = C(p) * d\n\n          X2 = q[0]\n          Y2 = q[1]\n          Z2 = q[2]\n          d = Math.hypot(q[0], q[2])\n          p = Math.atan2(X2,Z2)// + Math.atan2(X2,Z2) + Math.PI\n          q[0] = S(p) * d\n          q[2] = C(p) * d\n          d = Math.hypot(q[0], q[1], q[2])\n          if(d>maximus) maximus = d\n          if(d<minimus) minimus = d\n        })\n      })\n      shapes = [...shapes, [X, Y, Z, base_shape, shapeType, shpls, maximus*1.1, minimus/1.1, JSON.parse(JSON.stringify(base_shape))]]\n    }\n\n    genTunnels = (cullTunnelsByShapes=false) => {\n\n      originX = originY = originZ = null\n      let skipCapOnPrev = tunnels.length - 1\n      let ls = segLen*(tunLen-2)/2\n      origins = []\n      for(i=tunSections; i--;){\n        p_ = Math.PI/tunSections* i + 0 * (i%2 ? .25 : .25)\n        a = []\n        tx = S(p=p_)*ls\n        ty = 0\n        tz = C(p)*ls\n        tyv=0\n        for(let j = 0; j<tunLen;j++){\n          tyv += (rand()-.5) * vsquirrel\n          if(j==tunLen/2-1|0 && originX == null){\n            originX = tx\n            originY = ty\n            originZ = tz\n          }\n          a = [...a, [tx, ty, tz]]\n          tx -= S(p+=(rand()-.5)*squirreliness) * segLen\n          ty -= S(tyv+0*2)*4\n          tz -= C(p) * segLen\n          tyv /= 1.05\n        }\n        tunnels = [...tunnels, a]\n        p_ += Math.PI/tunSections\n        origins = [...origins, ...JSON.parse(JSON.stringify(tunnels))]\n      }\n\n      let ret = []\n      let caps = []\n      tunnels.map((v, i_) => {\n        v.map((v2, i2) => {\n          if(i2 && i2<v.length-1){\n            tx0 = v[i2+1][0]\n            ty0 = v[i2+1][1]\n            tz0 = v[i2+1][2]\n            tx1 = v2[0]\n            ty1 = v2[1]\n            tz1 = v2[2]\n            tx2 = v[i2-1][0]\n            ty2 = v[i2-1][1]\n            tz2 = v[i2-1][2]\n            \n            /*X = (tx1 + tx2) / 2\n            Y = (ty1 + ty2) / 2\n            Z = (tz1 + tz2) / 2\n            R(Rl,Pt,Yw,1)\n            if(Z>0){\n              x.textAlign = \'center\'\n              x.font = (fs=500/Z)+\'px Courier Prime\'\n              x.fillStyle = \'#fff\'\n              x.fillText(i2-1,...Q())\n            }*/\n\n            p1a = Math.atan2(tx1-tx0, tz1-tz0)\n            p2a = -Math.acos((ty1-ty0)/(Math.hypot(tx1-tx0, ty1-ty0, tz1-tz0)+.001)) + Math.PI/2\n            p1b = Math.atan2(tx2-tx1, tz2-tz1)\n            p2b = -Math.acos((ty2-ty1)/(Math.hypot(tx2-tx1, ty2-ty1, tz2-tz1)+.001)) + Math.PI/2\n\n            /*x.beginPath()\n            X = tx1\n            Y = ty1\n            Z = tz1\n            R(Rl,Pt,Yw,1)\n            if(Z>0) x.lineTo(...Q())\n            X = tx2\n            Y = ty2\n            Z = tz2\n            R(Rl,Pt,Yw,1)\n            if(Z>0) x.lineTo(...Q())\n            stroke(\'#f004\', \'\', 5, false) */\n          \n            if(capTunnels && i_ > skipCapOnPrev && (i2==1 || i2 == v.length-2)) b = []\n            for(i=segSd;i--;){\n              segLs1_ = segLs + (flairTunnelEnds ? (segLs*10 / (1+((v.length-2-i2+10)**5/50000)) + segLs*10 / (1+((8+i2)**5/50000))) : 0)\n              segLs2_ = segLs + (flairTunnelEnds ? (segLs*10 / (1+((v.length-2-i2+9)**5/50000)) + segLs*10 / (1+((9+i2)**5/50000))) : 0)\n              if(capTunnels && i_ > skipCapOnPrev && (i2 == 1 || i2 == v.length-2)){\n                if(i2 ==1){\n                  X = S(p=Math.PI*2/segSd*i+Math.PI/segSd) * segLs1_\n                  Y = C(p)*segLs1_\n                  Z = 0\n                  R3(0,p2b,p1b)\n                  X += tx2\n                  Y += ty2\n                  Z += tz2\n                }else{\n                  X = S(p=Math.PI*2/segSd*i+Math.PI/segSd) * segLs2_\n                  Y = C(p)*segLs2_\n                  Z = 0\n                  R3(0,p2a,p1a)\n                  X += tx1\n                  Y += ty1\n                  Z += tz1\n                }\n                b = [...b, [X,Y,Z,1]]\n              }\n              a = []\n              x.beginPath()\n              X = S(p=Math.PI*2/segSd*i+Math.PI/segSd) * segLs2_\n              Y = C(p)*segLs2_\n              Z = 0\n              R3(0,p2a,p1a)\n              X += tx1\n              Y += ty1\n              Z += tz1\n              cullCt = 0\n              if(!cull(i_,cullTunnelsByShapes)) cullCt++, a = [...a, [X,Y,Z,0]]\n              R(Rl, Pt, Yw, 1)\n              if(Z>0) x.lineTo(...Q())\n              X = S(p=Math.PI*2/segSd*i+Math.PI/segSd) * segLs1_\n              Y = C(p)*segLs1_\n              Z = 0\n              R3(0,p2b,p1b)\n              X += tx2\n              Y += ty2\n              Z += tz2\n              if(!cull(i_,cullTunnelsByShapes)) cullCt++, a = [...a, [X,Y,Z,0]]\n              R(Rl, Pt, Yw, 1)\n              if(Z>0) x.lineTo(...Q())\n              X = S(p=Math.PI*2/segSd*(i+1)+Math.PI/segSd) * segLs1_\n              Y = C(p)*segLs1_\n              Z = 0\n              R3(0,p2b,p1b)\n              X += tx2\n              Y += ty2\n              Z += tz2\n              if(!cull(i_,cullTunnelsByShapes)) cullCt++, a = [...a, [X,Y,Z,0]]\n              R(Rl, Pt, Yw, 1)\n              if(Z>0) x.lineTo(...Q())\n              X = S(p=Math.PI*2/segSd*(i+1)+Math.PI/segSd) * segLs2_\n              Y = C(p)*segLs2_\n              Z = 0\n              R3(0,p2a,p1a)\n              X += tx1\n              Y += ty1\n              Z += tz1\n              if(!cull(i_,cullTunnelsByShapes)) cullCt++, a = [...a, [X,Y,Z,0]]\n              if(cullCt>2){\n                ret = [...ret, [a, i_]]\n              }\n            }\n            if(capTunnels && i_ > skipCapOnPrev && (i2==1 || i2 == v.length-2)){\n              caps = [...caps, [b, i_]]\n            }\n          }\n        })\n      })\n      if(capTunnels) ret = [...ret, ...caps]\n      \n      shapes.map((shp, idx) => {\n        shp[8].map(v=>{\n          v.map(q=>{\n            X = shp[0] + q[0]\n            Y = shp[1] + q[1]\n            Z = shp[2] + q[2]\n            cullShape(X,Y,Z,idx)\n          })\n        })\n      })\n      \n      shapes = shapes.map(shp => {\n        shp[3] = shp[3].map(v=>{\n          return typeof v != \'undefined\' && v.filter(q=>!q[3])\n        })\n        shp[3] = shp[3].filter(v => v.length>2)\n        return shp\n      })\n      \n      return ret\n    }\n\n    genLoopTunnel = (tx, ty, tz, rad, squirreliness=0, vsquirrel=0, capTunnels=false) => {\n      tTunnels = []\n      let tunSections = 1\n      let ls = rad\n      tx_ = tx\n      ty_ = ty\n      tz_ = tz\n      for(i=tunSections; i--;){\n        p_ = 0\n        a = []\n        tx = tx_ + S(p=p_)*ls\n        ty = ty_\n        tz = tz_ + C(p)*ls\n        tyv=0\n        let sd = Math.PI*2*rad/segLen-1|0\n        for(let j = 0; j<sd+3;j++){\n          tyv += (rand()-.5) * vsquirrel\n          if(j) a = [...a, [tx, ty, tz]]\n          tx = S(p=Math.PI*2/sd*j)*ls\n          ty -= S(tyv+0*2)*4\n          tz = C(p)*ls\n          tyv /= 1.05\n        }\n        tTunnels = [...tTunnels, a]\n        p_ += Math.PI/tunSections\n      }\n      \n      return tTunnels\n    }\n    \n    spawnFlashNotice = (text, col)=>{\n      flashNotices = [...flashNotices, [text, col, 1]]\n    }\n\n    spawnCam = player => {\n      X = player.X\n      Z = player.Z - camDist\n      Y = player.Y\n      return {\n        X, Y, Z\n      }\n    }\n    \n    spawnPlayer = (X=0, Y=0, Z=0,uid=0) =>{\n      let p_ = Math.atan2(X,Z)\n      let player = {\n        X,\n        Y,\n        Z,\n        id:                uid,\n        vx:                0,\n        vy:                0,\n        vz:                0,\n        yw:                p_+Math.PI,\n        pt:                0,\n        rl:                0,\n        rlv:               0,\n        ptv:               0,\n        ywv:               0,\n        name:              uid?\'AI player \' + uid:\'human player\',\n        keys:              Array(256).fill(0),\n        lerpX:             X,\n        lerpY:             Y,\n        lerpZ:             Z,\n        lerprl:            0,\n        lerppt:            0,\n        lerpyw:            0,\n        score:             0,\n        speed:             0,\n        health:            1,\n        mbutton:           Array(3).fill(false),\n        buttons:           [],\n        jumping:           false,\n        grounded:          false,\n        shooting:          false,\n        keyTimers:         Array(256).fill(0),\n        animation:         {\n                             curFrame: 0,\n                           },\n        distanceTravelled: 0,\n      }\n      player.cam = spawnCam(player)\n      return player\n    }\n    \n    masterInit = () => {\n      mv                = 1.5\n      rv                = .033\n      hov               = false\n      grav              = .5\n      boost             = .1\n      level             = -1\n      randCt            = 0\n      accelr            = 1\n      sparks            = []\n      camDist           = .01\n      bullets           = []\n      flashes           = []\n      buttons           = []\n      hotkeyX             = 0\n      camMode           = 1\n      players           = []\n      iSparkv           = 5\n      showInfo          = true\n      randSeed          = 1e4 + Math.random()* 1e4 |0\n      maxSpeed          = 24\n      iBulletv          = 32\n      topoZoom          = 5e3\n      showTopo          = true\n      mousedown         = false\n      splosions         = []\n      showstars         = true\n      iSplosionv        = 50\n      lerpFactor        = 3\n      jumpHeight        = 20\n      maxCamDist        = 100\n      iBulletFreq       = 3\n      falloffDist       = 1500\n      camSelected       = 0\n      bulletDamage      = .2\n      bigSplosions      = []\n      crosshairSel      = 2\n      flashNotices      = []\n      showCrosshair     = true\n      buttonsLoaded     = false\n      levelSelected     = false\n      movingTunnels     = false\n      pointerLocked     = false\n      iSparkReflectv    = iSparkv / 6\n      camFollowSpeed    = 10\n      accellr = accelm  = 2\n      flymodeCollisons  = false\n      keyTimerInterval  = 1/60*5 // .25 sec\n      hotkeysModalVisible = false\n      \n      playerSize_ = 50\n      animSize          = 50/4.5\n      animX             = 0\n      animY             = 0//-playerSize_/1.25\n      animZ             = 0//-playerSize/2.5\n      animRl            = 0\n      animPt            = 0//Math.PI/2\n      animYw            = Math.PI/2 + Math.PI\n      player_animations = {\n        walk: loadAnimation(\'walking_male\',   animSize, animX,animY,animZ,animRl,animPt,animYw, 0),\n        flip: loadAnimation(\'back_flip_male\', animSize, animX,animY,animZ,animRl,animPt,animYw, 0),\n      }\n    }\n    masterInit()\n\n    cull = (i_, cullTunnelsByShapes) => {\n      let ret = false\n      tunnels.map((n, j_) => {\n        if(!ret){\n          n.map((q, j) => {\n            if(!ret && j && j_!=i_){\n              tx1_ = q[0]\n              ty1_ = q[1]\n              tz1_ = q[2]\n              tx2_ = n[j-1][0]\n              ty2_ = n[j-1][1]\n              tz2_ = n[j-1][2]\n              d1 = Math.hypot((tx1_+tx2_)/2-X,(ty1_+ty2_)/2-Y,(tz1_+tz2_)/2-Z)\n              if(d1<segLs/(flairTunnelEnds && level>1 ?.75:1.2)) ret = true\n            }\n          })\n        }\n      })\n      shapes.map((shp, idx) => {\n        d = Math.hypot(X-shp[0], Y-shp[1], Z-shp[2])\n        if(d < shp[6] && d > shp[7]){\n          shp[8].map((v, i) => {\n            v.map((q, j)=>{\n              if(!shapes[idx][8][i][j][3]){\n                ax = q[0] + shp[0]\n                ay = q[1] + shp[1]\n                az = q[2] + shp[2]\n                d1 = Math.hypot(ax-X, ay-Y, az-Z)\n                if(cullTunnelsByShapes) {\n                  if(d1<segLs*1.25) ret = true\n                }\n                if(typeof shapes[idx][3][i] != \'undefined\' && d1<segLs*1.25) {\n                  shapes[idx][3][i][j][3] = true\n                }\n              }\n            })\n          })\n        }\n      })\n      return ret\n    }\n    \n    cullShape = (X, Y, Z, idx) => {\n      let ret = false\n      shapes.map((shp, idx2) => {\n        if(idx != idx2){\n          d = Math.hypot(X-shp[0], Y-shp[1], Z-shp[2])\n          if(d < shp[6] && d > shp[7]){\n            shp[8].map((v, i) => {\n              v.map((q, j) => {\n                ax = -q[0] + shp[0] //- q[0]\n                ay = -q[1] + shp[1] //- q[1]\n                az = -q[2] + shp[2] //- q[2]\n                d1 = Math.hypot(ax-X, ay-Y, az-Z)\n                if(d1<segLs/1.5) {\n                  ret = true\n                  shapes[idx][3][i][j][3] = true\n                  //shapes[idx2][3][i][j][3] = true\n                }\n              })\n            })\n          }\n        }\n      })\n      return ret\n    }\n    \n    loadLevel = level => {\n      \n      do{\n        iPlayersc = prompt(\'how many AI players [0-9]?\')\n        if(iPlayersc == null) {\n          tsel = -1\n          mousedown = false\n          return false\n        }else{\n          tsel = -1\n          mousedown = false\n        }\n      }while((+iPlayersc)<0 || (+iPlayersc) > 9);\n      iPlayersc++\n      tunnels       = []\n      switch(level){\n        case 0: \n          shapes        = []\n          spawnShape (0, 0, -800, \'subDividedCube\', 500, 3, .5)\n          spawnShape (-800, 0, 0, \'subDividedCube\', 500, 3, .5)\n          spawnShape (0, 0, 800, \'subDividedCube\', 500, 3, .5)\n          spawnShape (800, 0, 0, \'subDividedCube\', 500, 3, .5)\n          flairTunnelEnds = true\n          capTunnels    = false\n          randCt        = 0\n          colTunMargin  = .66\n          colShapeMargin= 1\n          segLs         = 40\n          segSd         = 6\n          tunSections   = 2\n          segLen        = 20\n          tunLen        = 56\n          topoZoom      = 5e3\n          squirreliness = 0\n          vsquirrel     = 0\n          playerSize    = 50\n          topoZoom      = 4500\n          tunnels = genTunnels()\n          break\n        case 1: \n          shapes        = []\n          spawnShape (0, -200, 0, \'subDividedCube\', 1000, 4, 1)\n          flairTunnelEnds = true\n          capTunnels    = false\n          randCt        = 0\n          topoZoom      = 1e4\n          colTunMargin  = .66\n          colShapeMargin= .75\n          segLs         = 80\n          segSd         = 5\n          tunSections   = 3\n          segLen        = 60\n          tunLen        = 45\n          playerSize    = 50\n          squirreliness = .55\n          vsquirrel     = 5\n          topoZoom      = 7000\n          tunnels = genTunnels(true)\n          originX = originZ = 10\n          break\n        case 2: \n          shapes        = []\n          spawnShape (0, 0, -500, \'subDividedCube\', 500, 3, .5)\n          spawnShape (0, 0, 500, \'subDividedCube\', 500, 3, .5)\n          //spawnShape (0, 0, -800, \'subDividedCube\', 500, 3, .5)\n          //spawnShape (-800, 0, 0, \'subDividedCube\', 500, 3, .5)\n          //spawnShape (0, 0, 800, \'subDividedCube\', 500, 3, .5)\n          //spawnShape (800, 0, 0, \'subDividedCube\', 500, 3, .5)\n          flairTunnelEnds = false\n          capTunnels    = true\n          randCt        = 0\n          colTunMargin  = .66\n          colShapeMargin= .8\n          topoZoom      = 5e3\n          segLs         = 60\n          segSd         = 8\n          tunSections   = 2\n          segLen        = 60\n          tunLen        = 50\n          playerSize    = 40\n          squirreliness = 0\n          vsquirrel     = 0\n          topoZoom      = 6e3\n          tunnels = genLoopTunnel(0,0,0,900,0,0,false) /* pos, rad */\n          tunnels = genTunnels(true)\n          break\n        case 3: \n          shapes        = []\n          spawnShape (0, 0, 0, \'subDividedPlatform\', 1800, 4, .33)\n          shapes = shapes.map(v=>{\n            maxd=-6e6\n            v[3].map(v=>{\n              v.map(q=>{\n                if(q[1]>maxd)maxd=q[1]\n                q[1]-=880\n              })\n            })\n            v[3] = v[3].filter(v=>{\n              return !v.filter(q=>q[1]<maxd-1200).length\n            })\n            return v\n          })\n          flairTunnelEnds = false\n          capTunnels    = false\n          randCt        = 0\n          colTunMargin  = .7\n          colShapeMargin= 1.5\n          segLs         = 60\n          segSd         = 6\n          tunSections   = 3\n          segLen        = 60\n          tunLen        = 20\n          playerSize    = 50\n          squirreliness = 0\n          topoZoom      = 5e3\n          vsquirrel     = 0\n          topoZoom      = 6e3\n          tunnels = genLoopTunnel(0,0,0,350,0,0,false)\n          tunnels = genTunnels(true)\n          originX = originZ = 10\n          break\n        case 4:\n          shapes        = []\n          spawnShape (0, 0, 0, \'subDividedCube\', 1500, 4, -.66)\n          //spawnShape (0, 0, -800, \'subDividedCube\', 500, 3, .5)\n          //spawnShape (-800, 0, 0, \'subDividedCube\', 500, 3, .5)\n          //spawnShape (0, 0, 800, \'subDividedCube\', 500, 3, .5)\n          //spawnShape (800, 0, 0, \'subDividedCube\', 500, 3, .5)\n          flairTunnelEnds = true\n          capTunnels    = false\n          randCt        = 0\n          tunnels       = []\n          colTunMargin  = .9\n          colShapeMargin= 1\n          segLs         = 50\n          segSd         = 6\n          tunSections   = 2\n          playerSize    = 40\n          topoZoom      = 5e3\n          segLen        = 75\n          tunLen        = 50\n          squirreliness = .25\n          vsquirrel     = 2\n          topoZoom      = 7500\n          movingTunnels = false\n          tunnels       = []\n          tunnels = genTunnels(true)\n          break\n        case 5: \n          shapes        = []\n          for(let m=5;m--;) spawnShape (0, 0, -600*2.5+(m+.5)*600, \'subDividedCube\', 550, 3, .5)\n          /*for(let m=3;m--;) spawnShape (0, 0, -600*1.5+(m+.5)*600, \'subDividedCube\', 550, 3, .5)\n          for(let m=3;m--;) {\n            if(m!=1) spawnShape (-600*1.5+(m+.5)*600, 0, 0, \'subDividedCube\', 550, 3, .5)\n          }*/\n          flairTunnelEnds = false\n          capTunnels    = false\n          randCt        = 0\n          colTunMargin  = .66\n          colShapeMargin= .75\n          segLs         = 70\n          segSd         = 6\n          playerSize    = 50\n          tunSections   = 1\n          topoZoom      = 5e3\n          segLen        = 70\n          tunLen        = 20\n          squirreliness = 0\n          vsquirrel     = 0\n          topoZoom      = 6e3\n          tunnels       = []\n          //tunnels = genLoopTunnel(0,0,0,1e3,0,0,false) /* pos, rad */\n          tunnels = genTunnels(true)\n          originX = originZ = 10\n          break\n        default:\n          genTunnels()\n          break\n      }\n      return true\n    }\n\n    document.onpointerlockchange = e => {\n      pointerLocked = document.pointerLockElement == c\n    }\n\n    mx=my=0\n    c.onmousemove = e => {\n      if(players.length){\n        curPlayer = players[camSelected]\n        hov = false\n        if(pointerLocked){\n          if(camSelected == 0){\n            curPlayer.ywv += rv * accelr * e.movementX/9\n            curPlayer.ptv += rv * 3 * e.movementY/9\n          }\n        }else{\n          rect = c.getBoundingClientRect()\n          mx = (e.pageX-rect.x)/c.clientWidth*c.width\n          my = (e.pageY-rect.y)/c.clientHeight*c.height\n          buttons.map(button=>{\n            if(button.hover){\n              hov = true\n            }\n          })\n        }\n      }else{\n        rect = c.getBoundingClientRect()\n        mx = (e.pageX-rect.x)/c.clientWidth*c.width\n        my = (e.pageY-rect.y)/c.clientHeight*c.height\n        buttons.map(button=>{\n          if(button.hover){\n            hov = true\n          }\n        })\n      }\n      if(showInfo){\n        let ofx = hotkeysModalVisible ? 450 : 0\n        X1 = ofx-450\n        Y1 = 5\n        X2 = X1 + 500\n        Y2 = Y1 + 27*14.5\n        if(mx >= X1 && mx <= X2 && my >= Y1 && my <= Y2){\n          c.style.cursor = \'pointer\'\n        }else{\n          c.style.cursor = \'unset\'\n        }\n      }\n    }\n    \n    c.onmouseup = e => {\n      e.preventDefault()\n      e.stopPropagation()\n      if(e.button == 0) mousedown = false\n      if(players.length){\n        curPlayer = players[camSelected]\n        c.focus()\n        curPlayer.mbutton[e.button] = false\n      }\n    }\n   \n    c.onmousedown = e => {\n      e.preventDefault()\n      e.stopPropagation()\n      if(e.button == 0 && !levelSelected) mousedown = true\n      if(players.length){\n        curPlayer = players[camSelected]\n        //c.requestFullscreen()\n        curPlayer.mbutton[e.button] = true\n\n        let hov = false\n        if(!pointerLocked){\n          if(e.button == 0){\n            buttons.map(button=>{\n              if(button.hover){\n                hov = true\n                if(button.visible) eval(button.callback)\n              }\n            })\n          }\n        }\n        if(!hov) {\n          c.requestPointerLock()\n        }\n      }\n      if(showInfo && e.button == 0){\n        let ofx = hotkeysModalVisible ? 450 : 0\n        X1 = ofx-450\n        Y1 = 5\n        X2 = X1 + 500\n        Y2 = Y1 + 27*14.5\n        if(mx >= X1 && mx <= X2 && my >= Y1 && my <= Y2){\n          hotkeysModalVisible = !hotkeysModalVisible\n        }\n      }\n    }\n    c.focus()\n\n    c.onkeydown = e => {\n      e.preventDefault()\n      e.stopPropagation()\n      if(players.length) players[0].keys[e.keyCode] = true\n    }\n\n    c.onkeyup = e => {\n      e.preventDefault()\n      e.stopPropagation()\n      if(players.length) players[0].keys[e.keyCode] = false\n    }\n\n    left = player =>{\n      if(player.keys[18]){\n        if(player.grounded && !player.flymode){\n          vx  = S(-player.yw+Math.PI/2) * C(-player.rl) * mv * accelm\n          vy  = -S(-player.rl) * mv * accelm\n          vz  = C(-player.yw+Math.PI/2) * C(-player.rl) * mv * accelm\n          player.vx -= vx\n          //if(flymode) oYv += vy\n          player.vz -= vz\n        }\n      }else{\n        player.ywv-=rv * accelr\n      }\n    }\n    up = player =>{\n      player.ptv-=rv * accelr\n    }\n    right = player =>{\n      if(player.keys[18]){\n        if(player.grounded || player.flymode){\n          vx  = S(-player.yw+Math.PI/2) * C(-player.rl) * mv * accelm \n          vy  = -S(-player.rl) * mv * accelm\n          vz  = C(-player.yw+Math.PI/2) * C(-player.rl) * mv * accelm\n          player.vx += vx\n          //if(flymode) oYv -= vy\n          player.vz += vz\n        }\n      }else{\n        player.ywv+=rv * accelr\n      }\n    }\n    down = player =>{\n      player.ptv+=rv * accelr\n    }\n    akey = player =>{\n      if(player.flymode){\n        vx  = -S(player.yw+Math.PI/2) * C(player.rl) * mv * accelm\n        vy  = S(player.rl) * mv * accelm\n        vz  = -C(player.yw+Math.PI/2) * C(player.rl) * mv * accelm\n        player.vx += vx\n        player.vy += vy\n        player.vz += vz\n      }else if(player.grounded){\n        vx  = -S(player.yw+Math.PI/2) * mv * accelm\n        vy  = 0\n        vz  = -C(player.yw+Math.PI/2) * mv * accelm\n        player.vx += vx\n        player.vz += vz\n      }\n    }\n    wkey = player =>{\n      if(player.flymode){\n        vx  = -S(player.yw) * C(player.pt) * mv * accelm\n        vy  = -S(player.pt) * mv * accelm\n        vz  = -C(player.yw) * C(player.pt) * mv * accelm\n        player.vx -= vx\n        player.vy -= vy\n        player.vz -= vz\n      }else if(player.grounded){\n        vx  = -S(player.yw) * mv * accelm\n        vy  = 0\n        vz  = -C(player.yw) * mv * accelm\n        player.vx -= vx\n        player.vz -= vz\n      }\n    }\n    dkey = player =>{\n      if(player.flymode){\n        vx  = -S(player.yw+Math.PI/2) * C(player.rl) * mv * accelm\n        vy  = S(player.rl) * mv * accelm\n        vz  = -C(player.yw+Math.PI/2) * C(player.rl) * mv * accelm\n        player.vx -= vx\n        player.vy -= vy\n        player.vz -= vz\n      }else if(player.grounded){\n        vx  = -S(player.yw+Math.PI/2) * mv * accelm\n        vy  = 0\n        vz  = -C(player.yw+Math.PI/2) * mv * accelm\n        player.vx -= vx\n        player.vz -= vz\n      }\n    }\n    skey = player =>{\n      if(player.flymode){\n        vx  = S(player.yw) * C(player.pt) * mv * accelm\n        vy  = S(player.pt) * mv * accelm\n        vz  = C(player.yw) * C(player.pt) * mv * accelm\n        player.vx -= vx\n        player.vy -= vy\n        player.vz -= vz\n      }else if(player.grounded){\n        vx  = S(player.yw) * mv * accelm\n        vy  = 0\n        vz  = C(player.yw) * mv * accelm\n        player.vx -= vx\n        player.vz -= vz\n      }\n    }\n    pgup = player => {\n      if(player.flymode){\n        vx  = -S(player.yw) * C(player.pt+Math.PI/2) * mv * accelm\n        vy  = -S(player.pt+Math.PI/2) * mv * accelm\n        vz  = -C(player.yw) * C(player.pt+Math.PI/2) * mv * accelm\n        player.vx += vx\n        player.vy += vy\n        player.vz += vz\n      }      \n    }\n    pgdn = player => {\n      if(player.flymode){\n        vx  = S(player.yw) * C(player.pt+Math.PI/2) * mv * accelm\n        vy  = S(player.pt+Math.PI/2) * mv * accelm\n        vz  = C(player.yw) * C(player.pt+Math.PI/2) * mv * accelm\n        player.vx += vx\n        player.vy += vy\n        player.vz += vz\n      }      \n    }\n    ctrl = player => {\n      player.shooting = true\n    }\n\n    leftButton = player =>{\n      if(player.flymode){\n        vx  = -S(-Yw) * C(-Pt+Math.PI/2) * mv * accelm\n        vy  = -S(-Pt+Math.PI/2) * mv * accelm\n        vz  = -C(-Yw) * C(-Pt+Math.PI/2) * mv * accelm\n        player.vx -= vx\n        player.vy -= vy\n        player.vz -= vz\n      }else{\n        player.shooting = true\n      }\n    }\n\n    rightButton = spacebar = player =>{\n      if(player.flymode){\n        vx  = -S(-Yw) * C(-Pt+Math.PI/2) * mv * accelm\n        vy  = -S(-Pt+Math.PI/2) * mv * accelm\n        vz  = -C(-Yw) * C(-Pt+Math.PI/2) * mv * accelm\n        player.vx += vx\n        player.vy += vy\n        player.vz += vz\n      }else if(player.grounded && player.keyTimers[32] < t){\n        player.jumping = true\n        player.keyTimers[32] = t+.25\n        //player.vx*=4\n        //player.vz*=4\n        player.vy = -jumpHeight\n      }\n    }\n\n    doKeys = player => {\n      accelr = accelm = 1\n      if(player.keys[16]){\n        accelm = 2.125 * (player.flymode ? 2 : 1)\n        accelr = 1.5\n      }\n      \n      player.shooting = false\n      player.keys.map((v,i) => {\n        if(v){\n          switch(i){\n            case 49: if(players.length)\n              camSelected = 0;\n              camSelHasChanged=true\n            break\n            case  67:\n              if(player.keyTimers[i] < t){\n                player.keyTimers[i] = t+keyTimerInterval*2\n                if(showCrosshair && crosshairSel<crosshairImgs.length-1){\n                  crosshairSel++\n                }else{\n                  crosshairSel=0\n                  showCrosshair = !showCrosshair\n                }\n              }\n              break\n            case 50: if(players.length>1)\n              camSelected = 1;\n              camSelHasChanged=true\n            break\n            case 51: if(players.length>2)\n              camSelected = 2;\n              camSelHasChanged=true\n            break\n            case 52: if(players.length>3)\n              camSelected = 3;\n              camSelHasChanged=true\n            break\n            case 53: if(players.length>4)\n              camSelected = 4;\n              camSelHasChanged=true\n            break\n            case 54: if(players.length>5)\n              camSelected = 5;\n              camSelHasChanged=true\n            break\n            case 55: if(players.length>6)\n              camSelected = 6;\n              camSelHasChanged=true\n            break\n            case 56: if(players.length>7)\n              camSelected = 7;\n              camSelHasChanged=true\n            break\n            case 57: if(players.length>8)\n              camSelected = 8;\n              camSelHasChanged=true\n            break\n            case 72:\n              if(player.keyTimers[i] < t){\n                player.keyTimers[i] = t+keyTimerInterval * 4\n                hotkeysModalVisible = !hotkeysModalVisible\n              }\n            break\n            case 48: if(players.length>9)\n              camSelected = 9;\n              camSelHasChanged=true\n            break\n            case 72:\n              if(player.keyTimers[i] < t){\n                player.keyTimers[i] = t+keyTimerInterval\n                hotkeysModalVisible = !hotkeysModalVisible\n              }\n            break\n            case  84:\n              if(player.keyTimers[i] < t){\n                player.keyTimers[i] = t+keyTimerInterval\n                showDash = !showDash\n              }\n              break\n            case  67:\n              if(player.keyTimers[i] < t){\n                player.keyTimers[i] = t+keyTimerInterval\n                if(showCrosshair && crosshairSel<crosshairImgs.length-1){\n                  crosshairSel++\n                }else{\n                  crosshairSel=0\n                  showCrosshair = !showCrosshair\n                }\n              }\n              break\n            case 77:\n              if(player.keyTimers[i] < t){\n                player.keyTimers[i] = t+keyTimerInterval\n                //camMode++\n                //camMode%=2\n                toggleMenu(false)\n              }\n              break\n            case 16:\n              if(player.grounded){\n                player.vx += S(player.yw) * .25 * boost * (player.forward ? 1 : -1)\n                player.vz += C(player.yw) * .25 * boost * (player.forward ? 1 : -1)\n              }\n              break\n            case 70:\n              if(player.keyTimers[i] < t){\n                player.keyTimers[i] = t+keyTimerInterval*8\n                player.flymode = !player.flymode\n                if(player.flymode){\n                  spawnFlashNotice(\'flymode enabled\', \'#fff8\')\n                }else{\n                  spawnFlashNotice(\'flymode off\', \'#fff8\')\n                }\n              }\n              break\n            case 65: akey(player); break\n            case 87: wkey(player); break\n            case 68: dkey(player); break\n            case 83: skey(player); break\n            case 32: spacebar(player); break\n            case 37: left(player); break\n            case 38: up(player); break\n            case 39: right(player); break\n            case 40: down(player); break\n            case 17: ctrl(player); break\n            case 33: pgup(player); break\n            case 34: pgdn(player); break\n          }\n        }\n      })\n    }\n    window.onload = () => {\n      c.focus()\n    }\n    \n    createLevel = lvl => {\n      level = lvl\n      if(loadLevel(lvl)){\n        levelSelected = true\n        players = Array(iPlayersc).fill().map((v, i) => {\n          l1 = Rn()*origins.length|0\n          l2 = origins[l1].length*Rn()|0\n          X = origins[l1][l2][0]+2.5\n          Y = origins[l1][l2][1]-2\n          Z = origins[l1][l2][2]+2.5\n          newPlayer = spawnPlayer(X,Y,Z,i) \n          newPlayer.flymode = false\n          return newPlayer\n        })\n      }else{\n        tsel = -1\n      }\n    }\n    \n    \n    \n    collisions = (X1,Y1,Z1,X2,Y2,Z2) => {\n      let mind1 = 6e6\n      let mind2 = 6e6\n      let ret = false\n      let l\n      ax = (X1+X2) / 2\n      ay = (Y1+Y2) / 2\n      az = (Z1+Z2) / 2\n      tunnels.map((v, i) => {\n        ax = (v[0][0][0] + v[0][2][0])/2\n        ay = (v[0][0][1] + v[0][2][1])/2\n        az = (v[0][0][2] + v[0][2][2])/2\n        if((d=Math.hypot(X2-ax,Y2-ay,Z2-az))<segLs*1.25 * colTunMargin * (v[0][0][3]?2:1)){\n          if((l = lineFaceI(X1, Y1, Z1, X2, Y2, Z2, v[0], true, false))){\n            if(d<mind1) {\n              mind1 = d\n              ret = l\n            }\n          }\n        }\n      })\n\n      if(!ret) shapes.map((shp, i) => {\n        tx = shp[0]\n        ty = shp[1]\n        tz = shp[2]\n        shp[3].map(v => {\n          ax = tx + (v[0][0] + v[2][0])/2\n          ay = ty + (v[0][1] + v[2][1])/2\n          az = tz + (v[0][2] + v[2][2])/2\n          if((d=Math.hypot(X2-ax,Y2-ay,Z2-az))<segLs*1.35 * colShapeMargin){\n            a = []\n            v.map(q=> a = [...a,[ q[0]+tx, q[1]+ty, q[2]+tz]])\n            if((l = lineFaceI(X1, Y1, Z1, X2, Y2, Z2, a, true, false))){\n              if(d<mind2) {\n                mind2 = d\n                ret = l\n              }\n            }\n          }\n        })\n      })\n      return ret\n    }\n    \n    playerInit = (idx=0) => {\n      X = originX\n      Y = originY-playerSize/2\n      Z = originZ\n      players[idx] = spawnPlayer(X,Y,Z,idx) \n    }\n    \n    spawnFlash = (X, Y, Z) => {\n      flashes = [...flashes, [X,Y,Z,1]]\n    }\n\n    spawnSplosion = (X, Y, Z) => {\n      for(let m = 50; m--;){\n        v = (.1+(Rn()**2*.9))*iSplosionv\n        vx = S(p1=Math.PI*2*Rn())*S(p2=Rn()<.5?Math.PI/2*Rn()**.5:Math.PI-Math.PI/2*Rn()**.5) * v\n        vy = C(p2) * v\n        vz = C(p1) * S(p2) * v\n        splosions = [...splosions, [X,Y,Z,vx,vy,vz,1]]\n      }\n    }\n\n    spawnBigSplosion = (X, Y, Z) => {\n      for(let m = 150; m--;){\n        v = (.1+(Rn()**2*.9))*iSplosionv*2\n        vx = S(p1=Math.PI*2*Rn())*S(p2=Rn()<.5?Math.PI/2*Rn()**.5:Math.PI-Math.PI/2*Rn()**.5) * v\n        vy = C(p2) * v\n        vz = C(p1) * S(p2) * v\n        bigSplosions = [...bigSplosions, [X,Y,Z,vx,vy,vz,1]]\n      }\n    }\n\n    spawnSparks = (X, Y, Z) => {\n      for(let m = 10; m--;){\n        v = Rn()**.5*iSparkv\n        vx = S(p1=Math.PI*2*Rn())*S(p2=Rn()<.5?Math.PI/2*Rn()**.5:Math.PI-Math.PI/2*Rn()**.5) * v\n        vy = C(p2) * v\n        vz = C(p1) * S(p2) * v\n        sparks = [...sparks, [X,Y,Z,vx,vy,vz,1]]\n      }\n    }\n\n    spawnBullet = player => {\n      \n      d = Math.hypot(player.vx, player.vy, player.vz)\n      X = 0\n      Y = 0\n      Z = iBulletv + d\n      R3(player.lerprl, player.lerppt, player.lerpyw)\n      vx = X\n      vy = Y\n      vz = Z\n\n      X = 0\n      Y = 0\n      Z = 1\n      R3(player.rl, player.pt, player.yw)\n      X += player.lerpX\n      Y += player.lerpY\n      Z += player.lerpZ\n      \n      bullets = [...bullets, [X, Y, Z, vx, vy, vz, 1, player.id]]\n    }\n    \n    reflect = (a, n) => {\n      let d1 = Math.hypot(...a)+.0001\n      let d2 = Math.hypot(...n)+.0001\n      a[0]/=d1\n      a[1]/=d1\n      a[2]/=d1\n      n[0]/=d2\n      n[1]/=d2\n      n[2]/=d2\n      let dot = -a[0]*n[0] + -a[1]*n[1] + -a[2]*n[2]\n      let rx = -a[0] - 2 * n[0] * dot\n      let ry = -a[1] - 2 * n[1] * dot\n      let rz = -a[2] - 2 * n[2] * dot\n      return [-rx*d1, -ry*d1, -rz*d1]\n    }\n    \n    drawPlayer = player => {\n      let w, h, fs\n      X = tx = player.lerpX\n      Y = ty = player.lerpY\n      Z = tz = player.lerpZ\n      vx = player.vx\n      vy = player.vy\n      vz = player.vz\n      \n      //player.yw = Math.atan2(player.vx,player.vz)\n      \n      rl = player.lerprl\n      pt = 0//player.lerppt\n      yw = player.lerpyw\n      \n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        s = Math.min(1e4,1e4/Z)\n        l = Q()\n        //x.drawImage(burst, l[0]-s/2,l[1]-s/2,s,s)\n        x.font = (fs=Math.max(1e4/Z,16))+\'px Courier Prime\'\n        x.fillStyle = \'#fff\'\n        x.textAlign = \'center\'\n        x.fillText(player.name, l[0], l[1]-fs*5)\n        x.fillText(`score ${player.score}`, l[0], l[1]-fs*2.5)\n        x.strokeStyle = \'#fa4\'\n        x.lineWidth = Math.min(10, Math.max(2, fs/10))\n        w = 6\n        h = 1\n        x.strokeRect(l[0]-fs*w/2,l[1]-fs*h/2-fs*4,fs*w,fs*h)\n        x.fillStyle = \'#0f4\'\n        x.fillRect(l[0]-fs*w/2,l[1]-fs*h/2-fs*4,fs*w*player.health,fs*h)\n      }\n      \n      ty+=playerSize\n      jumpanim = player.jumping&&!player.grounded\n      drawAnimation(jumpanim ? player_animations.flip:player_animations.walk, scol=\'\', fcol=\'#fff8\', lineWidth=2, glowing=false, overrideGlobalAlpha=1, player)\n    }\n    \n    respawnPlayer = player => {\n      l1 = Rn()*origins.length|0\n      l2 = origins[l1].length*Rn()|0\n      origx = origins[l1][l2][0]+2.5\n      origy = origins[l1][l2][1]-2\n      origz = origins[l1][l2][2]+2.5\n      player.X = player.lerpX = origx //originX\n      player.Y = player.lerpY = origy -playerSize/2 //originY-playerSize/2\n      player.Z = player.lerpZ = origz //originZ\n      player.vx = player.vy = player.vz = 0\n      player.flymode = false\n      player.vx =                 0\n      player.vy =                 0\n      player.vz =                 0\n      player.yw =                 p_+Math.PI\n      player.pt =                 0\n      player.rl =                 0\n      player.rlv =                0\n      player.ptv =                0\n      player.ywv =                0\n      player.lerpX =              player.X\n      player.lerpY =              player.Y\n      player.lerpZ =              player.Z\n      player.health =             1\n      player.shooting =           false\n    }\n    \n    renderButton = (text, X, Y, tooltip = \'\', callback=\'\', typ=\'rectangle\', col1=\'#0ff8\', col2=\'#2088\', fs=36) => {\n      render = ((text == \'EXIT LEVEL\' && showInfo) && (tooltip != \'  hide menu\' && tooltip != \'  show menu\')) || (showInfo && tooltip == \'  hide menu\') || (tooltip == \'  show menu\' && !showInfo)\n      x.globalAlpha = 1\n      if(render) {\n        x.beginPath()\n        x.fillStyle = \'#4f8c\'\n      }\n      let X1, Y1, X2, Y2\n      x.font = fs + \'px Courier Prime\'\n      let margin = 2\n      let w = x.measureText(text).width + margin*2\n      let h = fs + margin*2\n      X1=X-w/2,Y1=Y-h/2\n      if(render || !buttonsLoaded){\n        if(render){\n          c.style.cursor = \'unset\'\n          switch(typ){\n            case \'rectangle\':\n              x.lineTo(X1,Y1)\n              x.lineTo(X+w/2,Y-h/2)\n              x.lineTo(X+w/2,Y+h/2)\n              x.lineTo(X-w/2,Y+h/2)\n            break\n            case \'circle\':\n            break\n          }\n          Z = 30\n          stroke(col1, col2, 5, true)\n        }\n      }\n      \n      X2=X1+w\n      Y2=Y1+h\n      if(mx>X1 && mx<X2 && my>Y1 && my<Y2){\n        if(buttonsLoaded){\n          buttons[bct].hover = true\n        }else{\n          buttons=[...buttons, {callback,X1,Y1,X2,Y2,hover:true,tooltip,visible: false}]\n        }\n        c.style.cursor = \'pointer\'\n      }else{\n        if(buttonsLoaded){\n          buttons[bct].hover = false\n        }else{\n          buttons=[...buttons, {callback,X1,Y1,X2,Y2,hover:false,tooltip,visible: false}]\n        }\n      }\n      if(render){\n        ota = x.textAlign\n        x.textAlign = \'center\'\n        x.fillStyle = \'#fff\'\n        x.fillText(text, X, Y+fs/3.2)\n        x.textAlign = ota\n      }\n      if(render){\n        buttons[bct].visible = true\n      }else{\n        buttons[bct].visible = false\n      }\n      bct++\n    }\n\n    toggleMenu = (releasePointerLock=true) =>{\n      showInfo = !showInfo\n      if(showInfo) {\n        if(releasePointerLock && document.pointerLockElement == c) document.exitPointerLock()\n      } else {\n        if(document.pointerLockElement != c) c.requestPointerLock()\n      }\n    }\n    \n    lineOfSight = (playera, playerb) => {\n      X1_ = playera.X\n      Y1_ = playera.Y\n      Z1_ = playera.Z\n      X2_ = playerb.X\n      Y2_ = playerb.Y\n      Z2_ = playerb.Z\n      d = Math.hypot(X2_-X1_, Y2_-Y1_, Z2_-Z1_)\n      stps = d/20|0\n      let ret = false\n      let l\n      for(let j = stps+1; j--&&!ret;){\n        let mind1 = 6e6\n        let mind2 = 6e6\n        X1 = X1_+(X2_-X1)/stps*j\n        Y1 = Y1_+(Y2_-Y1)/stps*j\n        Z1 = Z1_+(Z2_-Z1)/stps*j\n        X2 = X1_+(X2_-X1)/stps*(j+1)\n        Y2 = Y1_+(Y2_-Y1)/stps*(j+1)\n        Z2 = Z1_+(Z2_-Z1)/stps*(j+1)\n        ax = (X1+X2) / 2\n        ay = (Y1+Y2) / 2\n        az = (Z1+Z2) / 2\n        if(!ret) tunnels.map((v, i) => {\n          ax = (v[0][0][0] + v[0][2][0])/2\n          ay = (v[0][0][1] + v[0][2][1])/2\n          az = (v[0][0][2] + v[0][2][2])/2\n          if((d=Math.hypot(X2-ax,Y2-ay,Z2-az))<segLs*1 * colTunMargin * (v[0][0][3]?2:1)){\n            if((l = lineFaceI(X1, Y1, Z1, X2, Y2, Z2, v[0], true, false))){\n              if(d<mind1) {\n                mind1 = d\n                ret = l\n              }\n            }\n          }\n        })\n\n        if(!ret) shapes.map((shp, i) => {\n          tx = shp[0]\n          ty = shp[1]\n          tz = shp[2]\n          shp[3].map(v => {\n            ax = tx + (v[0][0] + v[2][0])/2\n            ay = ty + (v[0][1] + v[2][1])/2\n            az = tz + (v[0][2] + v[2][2])/2\n            if((d=Math.hypot(X2-ax,Y2-ay,Z2-az))<segLs*1.125 * colShapeMargin){\n              a = []\n              v.map(q=> a = [...a,[ q[0]+tx, q[1]+ty, q[2]+tz]])\n              if((l = lineFaceI(X1, Y1, Z1, X2, Y2, Z2, a, true, false))){\n                if(d<mind2) {\n                  mind2 = d\n                  ret = l\n                }\n              }\n            }\n          })\n        })\n      }\n      return !ret\n    }\n    \n    levelMenu = () => {\n      levelSelected = false\n    }\n  }\n\n  if(movingTunnels) {\n    tunnels       = []\n    tunnels = genTunnels()\n  }\n\n\n  x.globalAlpha = 1\n  x.fillStyle=\'#0006\'\n  x.fillRect(0,0,c.width,c.height)\n  x.lineJoin = x.lineCap = \'roud\'\n\n  if(levelSelected){\n\n    curPlayer = players[camSelected]\n    \n    switch(camMode){\n      case 0:\n        d = Math.hypot(curPlayer.vx, curPlayer.vz)\n        cd = Math.min(maxCamDist, camDist + d/2)\n        dx = curPlayer.cam.X - curPlayer.X\n        dy = curPlayer.cam.Y - curPlayer.Y\n        dz = curPlayer.cam.Z - curPlayer.Z\n        d = Math.hypot(dx,dy,dz)\n        nx = S(t/4)*cd\n        nz = C(t/4)*cd\n        X = dx/d*cd-nx + curPlayer.X\n        Z = dz/d*cd-nz + curPlayer.Z\n        Y = Math.min(100, dy/d*cd-cd/2  + curPlayer.Y)\n        tgtx = X\n        tgty = Y\n        tgtz = Z\n        curPlayer.cam.X -= (curPlayer.cam.X - tgtx)/camFollowSpeed\n        curPlayer.cam.Y -= (curPlayer.cam.Y - tgty)/camFollowSpeed\n        curPlayer.cam.Z -= (curPlayer.cam.Z - tgtz)/camFollowSpeed\n        oX = curPlayer.cam.lerpX\n        oZ = curPlayer.cam.lerpZ\n        oY = curPlayer.cam.lerpY\n        Pt = -Math.acos((oY-curPlayer.Y) / (Math.hypot(oX-curPlayer.X,oY-curPlayer.Y,oZ-curPlayer.Z)+.001))+Math.PI/2\n        Yw = -Math.atan2(curPlayer.X-oX,curPlayer.Z-oZ)\n        Rl = 0\n        break\n      case 1:\n        X = 0\n        Y = 0\n        Z = 25\n        \n        if(camSelected){\n          R3(0,curPlayer.lerppt,curPlayer.lerpyw)\n          X_ = X\n          Y_ = -Y\n          Z_ = Z\n          oX = curPlayer.lerpX// += (curPlayer.X - curPlayer.lerpX) / lerpFactor\n          oY = curPlayer.lerpY// += (curPlayer.Y - curPlayer.lerpY) / lerpFactor\n          oZ = curPlayer.lerpZ// += ((curPlayer.Z-.1) - curPlayer.lerpZ) / lerpFactor\n          Pt = -Math.acos(Y_ / (Math.hypot(X_,Y_,Z_)+.001))+Math.PI/2\n          Yw = -Math.atan2(X_,Z_)\n          Rl = -curPlayer.lerprl\n          vx = curPlayer.vx\n          vy = curPlayer.vy\n          vz = curPlayer.vz\n          \n          curPlayer.yw = Math.atan2(curPlayer.vx,curPlayer.vz)\n        }else{\n          R3(0,curPlayer.pt,curPlayer.yw)\n          X_ = X\n          Y_ = -Y\n          Z_ = Z\n          oX = curPlayer.X// += (curPlayer.X - curPlayer.X) / Factor\n          oY = curPlayer.lerpY// += (curPlayer.Y - curPlayer.Y) / Factor\n          oZ = curPlayer.Z// += ((curPlayer.Z-.1) - curPlayer.Z) / Factor\n          Pt = -Math.acos(Y_ / (Math.hypot(X_,Y_,Z_)+.001))+Math.PI/2\n          Yw = -Math.atan2(X_,Z_)\n          Rl = -curPlayer.rl\n        }\n        break\n    }\n\n    players.map(player => {\n      \n      doKeys(player)\n      \n      //if(player.id) player.vx=S(t)*2\n      \n      player.lerpX += (player.X - player.lerpX) / lerpFactor\n      player.lerpY += (player.Y - player.lerpY) / lerpFactor\n      player.lerpZ += (player.Z - player.lerpZ) / lerpFactor\n      \n      player.lerprl += (player.rl - player.lerprl) / lerpFactor\n      player.lerppt += (player.pt - player.lerppt) / lerpFactor\n      player.lerpyw += (player.yw - player.lerpyw) / lerpFactor\n      \n      if(player.mbutton[0]) leftButton(player)\n      if(player.mbutton[2]) rightButton(player)\n      if(player.shooting && !(((t*60|0)%iBulletFreq))) spawnBullet(player)\n\n      /*while(player.yw > Math.PI*4) player.yw-=Math.PI*8\n      while(player.yw < -Math.PI*4) player.yw+=Math.PI*8\n      while(player.pt > Math.PI*4) player.pt-=Math.PI*8\n      while(player.pt < -Math.PI*4) player.pt+=Math.PI*8\n      while(player.rl > Math.PI*4) player.rl-=Math.PI*8\n      while(player.rl < -Math.PI*4) player.rl+=Math.PI*8\n      */\n      \n      player.rl += player.rlv\n      player.pt += player.ptv\n      player.yw += player.ywv\n      if(player.pt>Math.PI/2){\n        player.pt = Math.PI/2\n        player.ptv = 0\n      }\n      if(player.pt<-Math.PI/2){\n        player.pt = -Math.PI/2\n        player.ptv = 0\n      }\n      player.rlv/=1.5\n      player.ptv/=1.5\n      player.ywv/=1.5\n      \n      if(player.flymode){\n        player.vx /=1.2\n        player.vy /=1.2\n        player.vz /=1.2\n      }\n      \n      coldist = playerSize/2\n      ocg = player.grounded\n      player.grounded = false\n      if(!player.flymode || flymodeCollisons) for(let i=6; i--;){\n        let skip = false\n        switch(i){\n          case 0:\n            if(player.vx<=0) skip = true\n            X = coldist, Y = 0, Z = 0\n            break\n          case 1:\n            if(player.vy<=0) skip = true\n            X = 0, Y = coldist*2, Z = 0\n            break\n          case 2:\n            if(player.vz<=0) skip = true\n            X = 0, Y = 0, Z = coldist\n            break\n          case 3:\n            if(player.vx>=0) skip = true\n            X = -coldist, Y = 0, Z = 0\n            break\n          case 4:\n            if(player.vy>=0) skip = true\n            X = 0, Y = -coldist, Z = 0\n            break\n          case 5:\n            if(player.vz>=0) skip = true\n            X = 0, Y = 0, Z = -coldist\n            break\n        }\n        if(!skip){\n          X1 = player.X  //+ player.vx*4\n          Y1 = player.Y  //+ player.vy*4\n          Z1 = player.Z  //+ player.vz*4\n          X2 = X1+X\n          Y2 = Y1+Y\n          Z2 = Z1+Z\n          if((l = collisions(X1, Y1, Z1, X2, Y2, Z2))){\n            if(!player.flymode) {\n              ref = reflect([player.vx, player.vy, player.vz], l[1])\n              if(i==0 || i==2 || i==3 || i==5){\n                if(!(player.keys[65] || player.keys[87] || player.keys[68] || player.keys[83])){\n                  player.vx/=2.5\n                  player.vz/=2.5\n                  player.vx = ref[0]\n                  player.vz = ref[2]\n                }else{\n                  player.vx = ref[0]\n                  player.vz = ref[2]\n                }\n              }\n              player.vy = ref[1]/2\n            }\n          }\n          if(i==1 && l) {\n            if(player.vy>=0) {\n              if(player.jumping){\n                //player.animation.curFrame = 0\n              }\n            }\n            player.Y = l[0][1]-playerSize/1.1\n            player.vy *= player.vy > 0 ? -.25 : .25\n            player.grounded = true\n            player.jumping = false\n          }\n        }\n      }\n\n      if(player.grounded){\n        player.vy *= player.vy>0 ? -.1 : .1\n      }else{\n        if(!player.flymode) player.vy += grav\n      }\n      \n      if(!player.flymode){\n        d1 = Math.hypot(player.vx,player.vy,player.vz)\n        d2 = Math.min(maxSpeed, d1)\n        player.vx /=d1\n        player.vz /=d1\n        player.vx *=d2\n        player.vz *=d2\n      }\n      \n      player.X += player.vx\n      player.Y += player.vy\n      player.Z += player.vz\n\n      if(player.Y > 1e3) {\n        if(!player.id) spawnFlashNotice(\'falling death!\')\n        spawnFlash(player.X, player.Y, player.Z)\n        spawnBigSplosion(player.X, player.Y, player.Z)\n        respawnPlayer(player)\n      }\n\n      if(player.grounded && !player.flymode){\n        if(!(player.keys[65] || player.keys[87] || player.keys[68] || player.keys[83])){\n          player.vx /= 2\n          player.vz /= 2\n        }else{\n          player.vx /= 1.2\n          player.vz /= 1.2\n        }\n        player.rlv /= 1.5\n        player.ptv /= 1.5\n        player.ywv /= 1.5\n      }else{\n        player.rl += player.rlv/1.4\n        player.pt += player.ptv/1.4\n        player.yw += player.ywv/1.4\n      }\n    })\n    \n    if(showstars) ST.map(v=>{\n      X = v[0]\n      Y = v[1]\n      Z = v[2]\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        if((x.globalAlpha = Math.min(1,(Z/5e3)**2))>.1){\n          s = Math.min(1e3, 4e5/Z)\n          x.fillStyle = \'#ffffff04\'\n          l = Q()\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          s/=5\n          x.fillStyle = \'#fffa\'\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        }\n      }\n    })\n\n    x.globalAlpha = 1\n\n    splosions = splosions.filter(splosion=>splosion[6]>.25)\n    splosions.map(splosion => {\n      X = splosion[0] += splosion[3]\n      Y = splosion[1] += splosion[4] += grav /2\n      Z = splosion[2] += splosion[5]\n      splosion[3] /=1.125\n      splosion[4] /=1.125\n      splosion[5] /=1.125\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        l = Q()\n        s = Math.min(1e4, 2e5/Z*splosion[6]**1.5)\n        x.fillStyle = \'#ff000006\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=3\n        x.fillStyle = \'#ff880010\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=3.5\n        x.fillStyle = \'#ffffffff\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n      splosion[6] -= .02\n    })\n\n    zSortPolygons = []\n    tunnels.map((v, i) => {\n      ax=ay=az=0\n      v[0].map(q => {\n        ax += q[0]\n        ay += q[1]\n        az += q[2]\n      })\n      X = ax /= v[0].length\n      Y = ay /= v[0].length\n      Z = az /= v[0].length\n      R(Rl, Pt, Yw, 1)\n      if(Z>0) {\n        zSortPolygons = [...zSortPolygons, [Math.hypot(X,Y,Z), v[0], v[1]]]\n      }\n    })\n    \n    shapes.map((shp, idx) => {\n      tx = shp[0]\n      ty = shp[1]\n      tz = shp[2]\n      shp[3].map(v => {\n        ax=ay=az=0\n        v.map(q => {\n          ax += q[0]\n          ay += q[1]\n          az += q[2]\n        })\n        X = tx + (ax /= v.length)\n        Y = ty + (ay /= v.length)\n        Z = tz + (az /= v.length)\n        R(Rl, Pt, Yw, 1)\n        if(Z>0) {\n          a = []\n          v.map(q=> a = [...a,[ q[0]+tx, q[1]+ty, q[2]+tz]])\n          zSortPolygons = [...zSortPolygons, [Math.hypot(X,Y,Z), a, tunSections+idx]]\n        }\n      })\n    })\n\n    zSortPolygons.sort((a,b)=>b[0]-a[0])\n    els = tunSections + shapes.length\n    zSortPolygons.map((v_,i) => {\n      v = v_[1]\n      x.beginPath()\n      d1 = 0\n      ax=ay=az=ct = 0\n      v.map(q=>{\n        X = q[0]\n        Y = q[1]\n        Z = q[2]\n        R(Rl, Pt, Yw, 1)\n        if(Z>0) {\n          x.lineTo(...Q())\n          ax += X\n          ay += Y\n          az += Z\n          ct++\n        }\n      })\n      ax /= ct\n      ay /= ct\n      az /= ct\n      d1 = Math.hypot(ax,ay,az)\n      if(d1<falloffDist){\n        alpha1 = .5/(1+d1**4/4e8)\n        alpha2 = .7 /(1+d1**2/1e5)\n        col1 = alpha1 >.05 ? `hsla(${360/els*v_[2]},40%,50%,${alpha1})` : \'\'\n        col2 = `hsla(${360/els*v_[2]},80%,40%,${alpha2})`\n        stroke(col1, col2, 30, true)\n      }\n    })\n\n    players.map((player, idx) => {\n      let mind = 6e6, tgt = -1\n      if(players.length>1){\n        players.map((player2, idx2) => {\n          if(idx != idx2){\n            X1 = player.X\n            Y1 = player.Y\n            Z1 = player.Z\n            X2 = player2.X\n            Y2 = player2.Y\n            Z2 = player2.Z\n            if((d=Math.hypot(X2-X,Y2-Y,Z2-Z))<mind){\n              mind = d\n              tgt = idx2\n            }\n          }\n        })\n      }\n      if(player.id) {\n        player.keys[32] = false\n        if(Rn()<.01) player.keys[32] = true, player.animation.curFrame = 10\n        if(tgt != -1){\n          p1a = player.lerpyw\n          p2a = player.lerppt\n          X1 = player.X\n          Y1 = player.Y\n          Z1 = player.Z\n          X2 = players[tgt].X\n          Y2 = players[tgt].Y\n          Z2 = players[tgt].Z\n          p1b = Math.atan2(X2-X1,Z2-Z1)\n          p2b = -Math.acos((Y2-Y1) / (Math.hypot(X2-X1,Y2-Y1,Z2-Z1)+.001)) + Math.PI/2\n          if(p2b<p2a){\n            player.keys[38]=true\n            player.keys[40]=false\n          }else{\n            player.keys[38]=false\n            player.keys[40]=true\n          }\n          if(Math.abs(p1a-p1b)>Math.PI){\n            if(p1a>p1b){\n              p1b+=Math.PI*2\n            }else{\n              p1a+=Math.PI*2\n            }\n          }\n          if(p1a>p1b){\n            player.keys[37]=true\n            player.keys[39]=false\n          }else{\n            player.keys[37]=false\n            player.keys[39]=true\n          }\n          \n          if(Rn()<.1) player.keys[17] = false\n          if(Rn()<.1 && lineOfSight(player, players[tgt])) player.keys[17] = true\n        }\n        \n        \n        player.keys[87] = false\n        if(Rn()<.85) player.keys[87] = true\n        if(camSelected != player.id) drawPlayer(player)\n      }\n    })\n\n    sparks = sparks.filter(spark=>spark[6]>.25)\n    sparks.map(spark => {\n      X1 = spark[0]\n      Y1 = spark[1]\n      Z1 = spark[2]\n      X2 = X1 + spark[3] * 2\n      Y2 = Y1 + spark[4] * 6\n      Z2 = Z1 + spark[5] * 2\n      if(0&&(l = collisions(X1,Y1,Z1,X2,Y2,Z2))){\n        ref = reflect([spark[3], spark[4], spark[5]], l[1])\n        spark[3] = ref[0]\n        spark[4] = ref[1]\n        spark[5] = ref[2]\n      }\n      X = spark[0] += spark[3]\n      Y = spark[1] += spark[4] += grav /2\n      Z = spark[2] += spark[5]\n      spark[3] /=1.05\n      spark[4] /=1.05\n      spark[5] /=1.05\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        l = Q()\n        s = Math.min(1e4, 1e5/Z*spark[6]**1.5)\n        x.fillStyle = \'#ff000006\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=3\n        x.fillStyle = \'#ff880010\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=3.5\n        x.fillStyle = \'#ffffffff\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n      spark[6] -= .02\n    })\n\n    bigSplosions = bigSplosions.filter(bigSplosion=>bigSplosion[6]>.25)\n    bigSplosions.map(bigSplosion => {\n      X = bigSplosion[0] += bigSplosion[3]\n      Y = bigSplosion[1] += bigSplosion[4] += grav /2\n      Z = bigSplosion[2] += bigSplosion[5]\n      bigSplosion[3] /=1.125\n      bigSplosion[4] /=1.125\n      bigSplosion[5] /=1.125\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        l = Q()\n        s = Math.min(1e4, 2e5/Z*bigSplosion[6]**1.5)\n        x.fillStyle = \'#ff000006\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=3\n        x.fillStyle = \'#ff880010\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        s/=3.5\n        x.fillStyle = \'#ffffffff\'\n        x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n      }\n      bigSplosion[6] -= .02\n    })\n\n    olc = x.lineJoin\n\n    bullets = bullets.filter(bullet=>{\n      if(bullet[6]>.1){\n        return true\n      }else{\n        spawnSplosion(...bullet)\n        spawnFlash(...bullet)\n        return false\n      }\n    })\n    \n    bullets = bullets.map(bullet => {\n      X1 = bullet[0] - bullet[3]*1\n      Y1 = bullet[1] - bullet[4]*1\n      Z1 = bullet[2] - bullet[5]*1\n      X2 = X1 + bullet[3]*2\n      Y2 = Y1 + bullet[4]*2\n      Z2 = Z1 + bullet[5]*2\n      if(l = collisions(X1,Y1,Z1,X2,Y2,Z2)){\n        tx = l[0][0]+l[1][0] * 2\n        ty = l[0][1]+l[1][1] * 2\n        tz = l[0][2]+l[1][2] * 2\n        if(Rn()<.3) spawnSparks(tx,ty,tz)\n\n        ref = reflect([bullet[3], bullet[4], bullet[5]], l[1])\n\n        bullet[3] = ref[0]\n        bullet[4] = ref[1]\n        bullet[5] = ref[2]\n      }\n      X = bullet[0] += bullet[3]\n      Y = bullet[1] += bullet[4]\n      Z = bullet[2] += bullet[5]\n      \n      players.map(player => {\n        if(player.id != bullet[7]){\n          X2 = player.X\n          Y2 = player.Y\n          Z2 = player.Z\n          if((d = Math.hypot(X2-X,Y2-Y,Z2-Z))<playerSize){\n            player.health -= bulletDamage\n            if(player.health <= 0){\n              players.filter(player=>player.id==bullet[7])[0].score++\n              spawnBigSplosion(...bullet)\n              spawnFlash(...bullet)\n              respawnPlayer(player)\n            }else{\n              spawnSplosion(...bullet)\n            }\n            bullet[6] = 0\n          }\n        }      \n      })\n      \n      if(bullet[6]){\n        R(Rl,Pt,Yw,1)\n        if(Z>0){\n          l = Q()\n          s = Math.min(1e4, 1e5/Z)\n          //x.drawImage(burst,l[0]-s/2/1.00,l[1]-s/2/1.00,s,s)\n          x.drawImage(starImgs[0].img,l[0]-s/2/1.00,l[1]-s/2/1.00,s,s)\n          s/=4\n          x.drawImage(starImgs[4].img,l[0]-s/2/1.05,l[1]-s/2/1.05,s,s)\n        }\n        bullet[6] -= .015\n      }\n      return bullet\n    })\n\n    flashes = flashes.filter(flash=>flash[3]>.25)\n    flashes.map(flash => {\n      X = flash[0]\n      Y = flash[1]\n      Z = flash[2]\n      R(Rl,Pt,Yw,1)\n      if(Z>0){\n        l = Q()\n        s = Math.min(1e4, 1e6/Z*flash[3]**1.5)\n        x.fillStyle = \'#ff000006\'\n        x.drawImage(starImgs[0].img,l[0]-s/2,l[1]-s/2,s,s)\n        s/=2\n        x.drawImage(starImgs[1+Rn()*8|0].img,l[0]-s/2/1.05,l[1]-s/2/1.05,s,s)\n      }\n      flash[3] -= .05\n    })\n    \n    if(showCrosshair){\n      x.globalAlpha = .2\n      s=800\n      x.drawImage(crosshairImgs[crosshairSel].img,c.width/2-s/2,c.height/2-s/2,s,s)\n      x.globalAlpha = 1\n      x.lineJoin = x.lineCap = olc\n      //x.lineCap = x.lineJoin = \'round\'\n    }\n\n    if(showTopo){\n      let ls_ = 400\n      let margin = 20\n      x.fillStyle = \'#000e\'\n      x.strokeStyle =\'#208c\'\n      x.lineWidth = 20\n      x.strokeRect(tx_ = c.width-ls_-margin, ty_ = margin,ls_,ls_/1.5)\n      x.fillRect(tx_ = c.width-ls_-margin, ty_ = margin,ls_,ls_/1.5)\n      tx_+=ls_/2\n      ty_+=ls_/2/1.6\n      shapes.map((shp, idx) => {\n        v_ = tunSections+idx\n        tx = shp[0]\n        ty = shp[1]\n        tz = shp[2]\n        shp[3].map(v => {\n          x.beginPath()\n          v.map(q=>{\n            X = q[0] + tx\n            Y = q[1] + ty\n            Z = q[2] + tz\n            R4(0, -.66, t/3, topoZoom)\n            l = Q4()\n            if(Z>0) x.lineTo(l[0]+tx_, l[1]+ty_)\n          })\n          alpha1 = 0\n          alpha2 = .75\n          col1 = \'\'//alpha1 >.05 ? `hsla(${360/els*v_},40%,50%,${alpha1})` : \'\'\n          col2 = `hsla(${360/els*v_},80%,40%,${alpha2})`\n          stroke(col1, col2, 30, true)\n        })\n      })\n      tunnels.map((v, idx) => {\n        ax=ay=az=0\n        x.beginPath()\n        v[0].map(q => {\n          X = q[0]\n          Y = q[1]\n          Z = q[2]\n          R4(0, -.66, t/3, topoZoom)\n          l = Q4()\n          if(Z>0) x.lineTo(l[0]+tx_, l[1]+ty_)\n        })\n        alpha1 = 0\n        alpha2 = .75\n        col1 = \'\'//alpha1 >.05 ? `hsla(${360/els*v[1]},40%,50%,${alpha1})` : \'\'\n        col2 = `hsla(${360/els*v[1]},80%,40%,${alpha2})`\n        stroke(col1, col2, 30, true)\n      })\n      \n      \n      bullets.map(bullet=>{\n        X = bullet[0]\n        Y = bullet[1]\n        Z = bullet[2]\n        R4(0