n      if(Z>.1) x.lineTo(...Q())\n      if(i%4===3){\n        d=H(...v)\n        x.globalAlpha=1/(1+d**5/160000)\n        x.closePath()\n        x.lineWidth=100/Z\n        x.strokeStyle=\'#eeffff18\'\n        x.stroke()\n        x.lineWidth=600/Z\n        x.strokeStyle=\'#66ffcc0b\'\n        x.stroke()\n      }\n    })\n  })\n  x.globalAlpha=1\n\n  B.map((v,m)=>{\n    spin = S(t+m)*32\n    tx=v[0]+=v[3]\n    ty=v[1]+=v[4]\n    tz=v[2]+=v[5]\n    p1=Math.atan2(v[3],v[5])\n    p2=Math.acos(v[4]/Math.hypot(v[3],v[4],v[5]))\n    for(m=3;m--;){\n      X=S(p=Math.PI*2/3*m+spin)*iBr*.9\n      Y=C(p)*iBr*.9\n      Z=-iBr*1.5\n      R(t*2,p2+Math.PI/2,p1+Math.PI)\n      X+=tx,Y+=ty,Z+=tz\n      v[9][m].push([X,Y,Z])\n      v[9][m]=v[9][m].map((q,j)=>{\n        if(j){\n          x.beginPath()\n          X=q[0]\n          Y=q[1]\n          Z=q[2]\n          R(Rl,Pt,Yw,1)\n          if(Z>.1)x.lineTo(...Q())\n          X=v[9][m][j-1][0]\n          Y=v[9][m][j-1][1]\n          Z=v[9][m][j-1][2]\n          R(Rl,Pt,Yw,1)\n          if(Z>.1)x.lineTo(...Q())\n          x.strokeStyle=`hsla(${((trailLength-j)/trailLength)*500-t*250},99%,${(100-(trailLength-j)/trailLength*100)}%,${(1-(trailLength-j)/trailLength)/2}`\n          x.lineWidth=Math.min(30,800/Z**1.5*(1-(trailLength-j)/trailLength))\n          x.stroke()\n        }\n        return q\n      }).filter((q,i)=>v[9][m].length < trailLength || i)\n    }\n    v[6]+=(Rn()-.5)/50\n    v[7]+=(Rn()-.5)/50\n    v[8]+=(Rn()-.5)/50\n    v[6]/=1.02\n    v[7]/=1.02\n    v[8]/=1.02\n    d=8+(4+Math.hypot(v[0],v[1],v[2])*4)**.8*6\n    v[3]-=v[0]/d+v[6]\n    v[4]-=v[1]/d+v[7]\n    v[5]-=v[2]/d+v[8]\n\n    d=Math.hypot(v[3],v[4],v[5])\n    v[3]=v[3]/d*iBv\n    v[4]=v[4]/d*iBv\n    v[5]=v[5]/d*iBv\n    p1=Math.atan2(v[3],v[5])\n    p2=Math.acos(v[4]/Math.hypot(v[3],v[4],v[5]))\n\n    x.beginPath()\n    for(i=3;i--;){\n      X=S(p=Math.PI*2/3*i+spin)*iBr\n      Y=C(p)*iBr\n      Z=-iBr*1.5\n      R(t*2,p2+Math.PI/2,p1+Math.PI)\n      X+=tx,Y+=ty,Z+=tz\n      R(Rl,Pt,Yw,1)\n      if(Z>.5)x.lineTo(...Q())\n    }\n    x.strokeStyle=\'#caf8\'\n    x.lineWidth=Math.min(30,1+350/Z/Z)\n    x.closePath()\n    x.stroke()\n    x.fillStyle=\'#84f3\'\n    x.fill()\n    for(i=3;i--;){\n      x.beginPath()\n      X=0\n      Y=0\n      Z=iBr*1.5\n      R(t*2,p2+Math.PI/2,p1+Math.PI)\n      X+=tx,Y+=ty,Z+=tz\n      R(Rl,Pt,Yw,1)\n      if(Z>.5)x.lineTo(...Q())\n      X=S(p=Math.PI*2/3*i+spin)*iBr\n      Y=C(p)*iBr\n      Z=-iBr*1.5\n      R(t*2,p2+Math.PI/2,p1+Math.PI)\n      X+=tx,Y+=ty,Z+=tz\n      R(Rl,Pt,Yw,1)\n      if(Z>.5)x.lineTo(...Q())\n      X=S(p=Math.PI*2/3*(i+1)+spin)*iBr\n      Y=C(p)*iBr\n      Z=-iBr*1.5\n      R(t*2,p2+Math.PI/2,p1+Math.PI)\n      X+=tx,Y+=ty,Z+=tz\n      R(Rl,Pt,Yw,1)\n      if(Z>.5)x.lineTo(...Q())\n      x.strokeStyle=\'#caf8\'\n      x.lineWidth=Math.min(30,1+350/Z/Z)\n      x.closePath()\n      x.stroke()\n      x.fillStyle=\'#84f3\'\n      x.fill()\n    }\n  })\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  x.lineCap=x.lineJoin=\'round\'\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123);\n  height: 100vh;\n  overflow: hidden;\n}\n#c{\n  width: 100%;\n  min-height: 100vh;\n}', '<canvas id=c>', 'streamers', 1, 'cantelope', '2022-04-09 14:26:49', 15, 0, 'cantelope1', 'https://srmcgann.github.io/assets/1GY3GM.png');
