(600072, 'let c = document.querySelector(\'#anim_canvas\')\nlet x = c.getContext(\'2d\')\nlet S = Math.sin\nlet C = Math.cos\nlet w\nvar anim_t = 0\nc.width = c.clientWidth\nc.height = c.clientHeight\nx.clearRect(0, 0, w=c.width, w)\n\nanim_Draw=()=>{\n\n  let t = anim_t\n\n  if(!t){\n    x.lineJoin=x.lineCap=\'round\'\n    P=Array(5).fill().map(v=>[])\n    pulse = new Image()\n    pulse.src = \'https://srmcgann.github.io/assets/21kQld.png\'\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n  }\n  B=[]\n  oy=9\n  for(j=20;j--;){\n    for(i=4;i--;){\n      Y1 = (j)**4/5000-10\n      ls = (20-(10-Y1))**1.75/50+.3\n      X1 = S(p=Math.PI*2/4*i+Math.PI/4)*ls\n      Z1 = C(p)*ls\n      Y2 = ((j+1))**4/5000-10\n      ls = (20-(10-Y2))**1.75/50+.3\n      X2 = S(p)*ls\n      Z2 = C(p)*ls\n      B = [...B, [X1,Y1-oy,Z1,X2,Y2-oy,Z2]]\n    }\n  }\n  \n  c.width = c.clientWidth\n  c.height = c.clientHeight\n\n\n  if(Math.random()<.15) P[l=Math.random()*5|0]=[...P[l], 3]\n\n  for(k=5; k--;){\n    oX=0, oY=0, oZ=450+S(Math.PI*2/2.5*k+t)*200\n    Rl=C(Math.PI*2/5*k+t/10)*Math.PI*4, Pt=0, Yw=t*2\n    mx = (((c.width+100) / 5 * k) + S(t/6)*1500)\n    while(mx > c.width+50) mx -= c.width+100\n    while(mx < -50) mx += c.width+100\n    Q=q=>[mx+X/Z*800,130+Y/Z*800]\n    P[k] = P[k].map(v=>{\n      v+=.05\n      X = 0\n      Y = -22\n      Z = 0\n      R(Rl,Pt,Yw,1)\n      s = (1+v)**7*2/Z/40\n      l=Q()\n      x.globalAlpha = .3/(1+s**3/20000000)\n      x.drawImage(pulse, l[0]-s/2, l[1]-s/2, s, s)\n      return v\n    }).filter(v=>v<=9)\n      x.globalAlpha=1\n    \n    B.map((v, i)=>{\n      x.beginPath()\n      X = v[0]\n      ty=Y = v[1]\n      Z = v[2]\n      R(Rl,Pt,Yw,1)\n      x.lineTo(...Q())\n      X = v[3]\n      Y = v[4]\n      Z = v[5]\n      R(Rl,Pt,Yw,1)\n      x.lineTo(...Q())\n      x.strokeStyle=\'#3bde21\'\n      x.lineWidth = 1 + Math.min(40, ((ty+18)*20)/Z)\n      x.stroke()\n\n      if(i>3){\n        x.beginPath()\n        X = v[3]\n        Y = v[4]\n        Z = v[5]\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n        l = (i+1)%4?i+1:i-3\n        X = B[l][3]\n        Y = B[l][4]\n        Z = B[l][5]\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n        x.strokeStyle=\'#3bde2188\'\n        x.lineWidth = 1 + Math.min(40, ((ty+18)*12)/Z)\n        x.stroke()\n      }\n\n      if(i<B.length-9){\n        x.beginPath()\n        X = v[3]\n        Y = v[4]\n        Z = v[5]\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n        l = i%4?i+7:i+11\n        X = B[l][3]\n        Y = B[l][4]\n        Z = B[l][5]\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n        x.strokeStyle=\'#3bde2188\'\n        x.lineWidth = 1 + Math.min(40, ((ty+18)*12)/Z)\n        x.stroke()\n      }\n\n      if(i<B.length-9){\n        x.beginPath()\n        X = v[3]\n        Y = v[4]\n        Z = v[5]\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n        l = (i+1)%4?i+9:i+5\n        X = B[l][3]\n        Y = B[l][4]\n        Z = B[l][5]\n        R(Rl,Pt,Yw,1)\n        x.lineTo(...Q())\n        x.strokeStyle=\'#3bde2188\'\n        x.lineWidth = 1 + Math.min(40, ((ty+18)*12)/Z)\n        x.stroke()\n      }\n    })\n\n    X = 0\n    Y = -19\n    Z = 0\n    x.beginPath()\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    X = 0\n    Y = -22\n    Z = 0\n    R(Rl,Pt,Yw,1)\n    x.lineTo(...Q())\n    x.lineWidth = 1 + Math.min(20, 5000/Z/Z)\n    x.strokeStyle=\'#3bde2188\'\n    x.stroke()\n    \n    \n    x.beginPath()\n    X = 0\n    Y = -22\n    Z = 0\n    R(Rl,Pt,Yw,1)\n    x.arc(...Q(),1+500/Z,0,7)\n    x.fillStyle=\'#fff\'\n    x.fill()\n  }\n\n\n\n  anim_t += 1/60\n  requestAnimationFrame(anim_Draw)\n}\n\nanim_Draw()\n', '.anim_main{\n  position: absolute;\n  color: #ff0;\n  top: 0;\n  width: 100%;\n  text-align: center;\n}\n.anim_canvas{\n  width: 100%;\n  height: 500px;\n  vertical-align: top;\n}\n', '<!DOCTYPE html>\n<!-- saved from url=(0021)https://broken.radio/ -->\n<html lang=\"en-GB\" prefix=\"og: http://ogp.me/bens#\" class=\"\"><head><meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\">\n\n<style>#wpadminbar #wp-admin-bar-wsm_free_top_button .ab-icon:before{content:\"\\f239\";color:#FF9800;top:3px;}</style>\n<title>Broken Radio - Where Electronic Music has a place to thrive!</title>\n<meta name=\"description\" content=\"Broken Radio is a not-for-profit project. It has been created to connect audience with amazing DJ’s and sounds from every corner of electronic music genres.\">\n<meta name=\"robots\" content=\"follow, index, max-snippet:-1, max-video-preview:-1, max-image-preview:large\">\n<link rel=\"canonical\" href=\"https://broken.radio/\">\n<meta property=\"og:locale\" content=\"en_GB\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:title\" content=\"Broken Radio - Where Electronic Music has a place to thrive!\">\n<meta property=\"og:description\" content=\"Broken Radio is a not-for-profit project. It has been created to connect audience with amazing DJ’s and sounds from every corner of electronic music genres.\">\n<meta property=\"og:url\" content=\"https://broken.radio\">\n<meta property=\"og:site_name\" content=\"Broken Radio\">\n<meta property=\"og:updated_time\" content=\"2020-12-05T09:32:29+00:00\">\n<meta property=\"og:image\" content=\"https://broken.radio/wp-content/uploads/2020/05/color_logo_transparent-1024x640.png\">\n<meta property=\"og:image:secure_url\" content=\"https://broken.radio/wp-content/uploads/2020/05/color_logo_transparent-1024x640.png\">\n<meta property=\"og:image:width\" content=\"800\">\n<meta property=\"og:image:height\" content=\"500\">\n<meta property=\"og:image:alt\" content=\"broken radio\">\n<meta property=\"og:image:type\" content=\"image/png\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Broken Radio - Where El