INSERT INTO `pages` (`id`, `pageJS`, `pageCSS`, `pageHTML`, `title`, `userID`, `author`, `created`, `views`, `featured`, `escaped_name`, `favicon`) VALUES
(600073, '  song = \'https://twilightparadox.com/sweet spot.mp3\'\n  vid = \'\'\n  recordingStarted=playing=vidplaying=analyzerSetup=0\n\n  fftSize = 64\n\n  c=document.querySelector(\'#c\')\n  x=c.getContext(\'2d\')\n  c.width=c.clientWidth\n  c.height=c.clientHeight\n  canvas2=c.cloneNode()\n  x2=canvas2.getContext(\'2d\')\n  S=Math.sin\n  C=Math.cos\n  t=0\n\n  Draw=()=>{\n\n    if(!t){\n      bg = new Image()\n      go=false\n      bg.addEventListener(\'load\',()=>{\n        go=true\n      })\n      bg.src = \'https://srmcgann.github.io/assets/D8R8C.jpg\'\n    }\n    \n    if(go){\n      x.globalAlpha = .15\n      s=1.2\n      x.drawImage(bg, c.width/2-bg.width/4*s,c.height/2-bg.height/4*s,bg.width/2*s,bg.height/2*s)\n      x.globalAlpha = 1\n      x.fillStyle=\'#0004\',x.fillRect(0,0,w=c.width,w)\n    } else {\n      x.fillStyle=\'#000\', x.fillRect(0,0,w=c.width,w)\n    }\n    \n    iTs=80,iTv=2.5,iTr=8,iTt=100,iTa=1\n    iFc=200,iFs=16,iFv=20\n    \n    Qf=q=>{\n      F=[...F,[Rn()*w,Rn()*c.height,1]]\n    }\n\n    if(!t){\n      F=[]\n      Rn=Math.random\n      P=[[c.width/2,c.height/2,iTs,Math.PI,0,100]]\n      for(i=iFc;i--;)Qf()\n    }\n\n    if(!((t*60|0)%2))Qf()\n    \n    F=F.map(v=>{\n      x.fillStyle=\'#4f4f\'\n      s=iFs\n      x.fillRect(v[0]-s/2,v[1]-s/2,s,s)\n      return v\n    }).filter(v=>v[2])\n\n    Q=q=>{\n      for(m=q[5]/12|0;m--;){\n        P=[...P,[q[0],q[1],10+(q[2]/2-10)*Rn(),q[3],0,100]]\n      }\n    }\n\n    P.map((v, j)=>{\n      v[5]-=iTa\n      mind=6e6\n      F.map(q=>{\n        d=Math.hypot(a=v[0]-q[0],b=v[1]-q[1])\n        if(d<mind)mind=d,p1=Math.atan2(a,b)\n        if(q[2]&&mind<iTs/2){\n          q[2]=0,mind=6e6\n          v[2]+=3\n          v[5]+=iFv\n          v[5]=Math.min(100,v[5])\n        }\n      })\n      p2=v[3]\n      if(Math.abs(p1-p2)>=Math.PI){\n        if(p1<p2){\n          p1+=Math.PI*2\n        }else{\n          p2+=Math.PI*2\n        }\n      }\n      v[4]/=1.15\n      v[3]/=1.03\n      v[4]+=(p1-p2<0?iTr:-iTr)/80\n      v[3]+=v[4]/4\n      v[0]+=S(p=v[3])*(d=v[2]/20*iTv)\n      v[1]+=C(p)*d\n      if(v[0]<0)v[0]+=w\n      if(v[0]>w)v[0]-=w\n      if(v[1]<0)v[1]+=c.height\n      if(v[1]>c.height)v[1]-=c.height\n      x.beginPath()\n      for(i=3;i--;){\n        X=v[0]+S(p=Math.PI*2/3*i+v[3])*(d=v[2]*(i?.5:1))\n        Y=v[1]+C(p)*d\n        x.lineTo(X,Y)\n      }\n      x.closePath()\n      x.lineCap=x.lineJoin=\'round\'\n      x.lineWidth=v[2]/8\n      x.fillStyle=x.strokeStyle=`hsla(${t*50+290-v[5]*.5},99%,${75+S(t*2+v[3])*25}%,.4`\n      x.stroke()\n      x.fill()\n      if(v[2]>=iTt){\n        Q(v)\n        v[5]=0\n      }\n      if(v[5]<=0){\n        for(i=4;i--;){\n          if(i){\n            X1=v[0]+S(p=Math.PI*2/3*i+v[3])*(d=v[2]*(i==3?1:.5))\n            Y1=v[1]+C(p)*d\n            X2=v[0]+S(p=Math.PI*2/3*(i+1)+v[3])*(d=v[2]*((i+1)==3?1:.5))\n            Y2=v[1]+C(p)*d\n            for(j=3;j--;){\n              X=X1+(X2-X1)/3*j\n              Y=Y1+(Y2-Y1)/3*j\n              F=[...F,[X,Y,1]]\n            }\n          }\n        }\n      }\n      return v\n    })\n    P=P.filter((v,i)=>i<500&&v[5]>0)\n  \n    t+=1/60\n    requestAnimationFrame(Draw)\n  }\n\n  setupAnalyzerAndContent = () => {\n    analyzerSetup=1\n    loaded=0\n    mp3 = new Audio()\n    mp3.crossOrigin = \"anonymous\"\n    mp3.src = song\n    mp3.loop = true\n    if(!mp3)loaded=1\n    mp3.addEventListener(\'canplay\',()=>{\n      if(!playing){\n        loaded=playing=1\n        audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n        analyser = audioCtx.createAnalyser()\n        source = audioCtx.createMediaElementSource(mp3)\n        source.connect(analyser)\n        analyser.connect(audioCtx.destination)\n        analyser.fftSize=fftSize\n        trim=analyser.fftSize*.25\n        bufferLength = analyser.frequencyBinCount\n        mp3.loop=true      \n        mp3.play()\n        Draw()\n        if(vid){\n          bgvid = document.createElement(\'video\')\n          bgvid.src = vid\n          bgvid.addEventListener(\'canplay\',()=>{\n            if(!vidplaying){\n              vidplaying=1\n              bgvid.loop=true\n              bgvid.muted=true\n              bgvid.play()\n            }\n          })\n        }\n      }\n    })\n  }\n\n  setupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'cantelope\'s page', 1, 'cantelope', '2022-04-09 14:26:51', 18, 0, 'cantelope1', 'https://srmcgann.github.io/assets/1GY3GM.png'),
(600074, 'song = \'https://twilightparadox.com/tachyon.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w),h=500\n  R=q=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d,X+=oX,Y+=oY,Z+=oZ}\n  Q=q=>[c.width/2+X/Z*500,c.height/2+Y/Z*500]\n  Rn=Math.random\n\n  Rl=0,Pt=-t/2,Yw=t\n  oX=0,oY=0,oZ=11\n  iPc=1900/5,iPbr=5\n  iBv=.1,iBc=3,iBs=1.5\n  G=4\n\n  if(!t){\n    go=false\n    bgimg=new Image()\n    bgimg.addEventListener(\'load\', ()=>{\n      go = true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/2clPtA.jpg\'\n    Rv=q=>[S(p=Math.PI*2*Rn())*S(q=Math.PI*Rn())*iBv,C(q)*iBv,C(p)*S(q)*iBv]\n    x.lineCap=x.lineJoin=\'round\'\n    B=Array(iBc).fill().map(v=>[Rn(),Rn(),Rn(),...Rv()])\n    P=Array(iPbr).fill().map((v,j)=>Array(iPc).fill().map((v,i)=>[a=S(p=Math.PI*2/50*i)/4+(i/iPc-.5)*10,b=C(p/2)*3*S(Math.PI/2+Math.PI*(i/iPc-.5)),f=(j-iPbr/2+.5)*1.5,0,0,0,a,b,f]))\n  }\n  \n  if(go){\n    x.globalAlpha=.4\n    x.drawImage(bgimg, 0, 0, c.width, c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0121\',x.fillRect(0,0,w=c.width,w),h=700\n  } else {\n    x.fillStyle=\'#0008\',x.fillRect(0,0,w=c.width,w),h=700\n  }\n\n  B.map(v=>{\n    v[0]+=v[3]\n    v[1]+=v[4]\n    v[2]+=v[5]\n    if(v[0]<-G||v[0]>G)v[3]*=-1\n    if(v[1]<-G||v[1]>G)v[4]*=-1\n    if(v[2]<-G||v[2]>G)v[5]*=-1\n    x.beginPath()\n    x.fillStyle=\'#4af4\'\n    X=v[0]\n    Y=v[1]\n    Z=v[2]\n    R()\n    x.arc(...Q(),Math.max(1,iBs*600/Z),0,7)\n    x.fill()\n  })\n\n  P.map(v=>{\n    v.map((v,i,ar)=>{\n      v[3]+=(v[6]-v[0])/9\n      v[4]+=(v[7]-v[1])/9\n      v[5]+=(v[8]-v[2])/9\n      v[0]+=v[3]/=1.15\n      v[1]+=v[4]/=1.15\n      v[2]+=v[5]/=1.15\n      B.map(q=>{\n      d=H(a=q[0]-v[0],b=q[1]-v[1],e=q[2]-v[2])\n      if(d<iBs){\n        p1=A(a,e),p2=M.acos(b/d)\n        v[0]=q[0]-S(p1)*S(p2)*iBs\n        v[1]=q[1]-C(p2)*iBs\n        v[2]=q[2]-C(p1)*S(p2)*iBs\n        v[3]-=S(p1)*S(p2)/1000\n        v[4]-=C(p2)/1000\n        v[5]-=C(p1)*S(p2)/1000\n      }\n      })\n      if(i<ar.length-2){\n      x.beginPath()\n      X=ar[i][0]\n      Y=ar[i][1]\n      Z=ar[i][2]\n      R(Rl,Pt,Yw)\n      x.lineTo(...Q())\n      X=ar[i+1][0]\n      Y=ar[i+1][1]\n      Z=ar[i+1][2]\n      R(Rl,Pt,Yw)\n      x.lineTo(...Q())\n      x.strokeStyle=\'#2fa3\'\n      x.lineWidth=iBs*1000/Z/Z\n      x.stroke()\n      }\n    })\n  })\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'cantelope\'s page', 1, 'cantelope', '2022-04-09 14:26:51', 9, 0, 'cantelope1', 'https://srmcgann.github.io/assets/1GY3GM.png'),
(600075, 'song = \'https://twilightparadox.com/Miami Nights.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nwindow.addEventListener(\'resize\',()=>{\n  c.width = c.clientWidth\n  c.height = c.clientHeight\n})\n\nDraw=()=>{\n\n  R=(Rl,Pt,Yw,o)=>{\n    X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n    if(o)X+=oX,Y+=oY,Z+=oZ\n  }\n  Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n  Rn=Math.random\n\n  if(!t){\n    \n    chk=()=>{\n      if(cp1&&cp2&&cp3&&cp4){\n        bgvid1.play()\n        bgvid3.currentTime = bgvid3.duration/2\n        bgvid3.play()\n        mp3.play()\n        go=true\n      }\n    }\n    bgvid1 = document.createElement(\'video\')\n    bgvid2 = document.createElement(\'video\')\n    bgvid3 = document.createElement(\'video\')\n    bgvid4 = document.createElement(\'video\')\n    cp1=cp2=cp3=cp4=false\n    go=false\n    bgvid1.addEventListener(\'canplay\',()=>{\n      cp1=true\n      if(!go)chk()\n    })\n    bgvid2.addEventListener(\'canplay\',()=>{\n      cp2=true\n      if(!go)chk()\n    })\n    bgvid3.addEventListener(\'canplay\',()=>{\n      cp3=true\n      if(!go)chk()\n    })\n    bgvid4.addEventListener(\'canplay\',()=>{\n      cp4=true\n      if(!go)chk()\n    })\n    bgvid1.src = \'https://srmcgann.github.io/assets/20uyb5.mp4\'\n    bgvid2.src = \'https://srmcgann.github.io/assets/20uyb5.mp4\'\n    bgvid3.src = \'https://srmcgann.github.io/assets/20uyb5.mp4\'\n    bgvid4.src = \'https://srmcgann.github.io/assets/20uyb5.mp4\'\n    for(CB=[],j=6;j--;)for(i=4;i--;)CB=[...CB,[(a=[S(p=Math.PI*2/4*i+Math.PI/4)*(d=2**.5),C(p)*d,1])[j%3]*(l=j<3?-1:1),a[(j+1)%3]*l,a[(j+2)%3]*l]]\n  }\n  rw=2, cl=7, br=8, sp = 8+S(t)*6\n  B=Array(rw*cl*br).fill().map((v,i)=>{\n    X=(i%rw-rw/2+.5)*sp\n    Y=(((i/rw|0)%cl)-cl/2+.5)*sp\n    Z=((i/rw/cl|0)-br/2+.5)*(l=(4+S(t))*4)-((t*10)%1)*l\n    return [X, Y, Z]\n  })\n\n  if(go){\n    delay = 5\n    if(bgvid1.ended && bgvid2.currentTime >= bgvid2.duration-bgvid2.duration/delay){\n      bgvid1.play()\n    }\n    if((bgvid2.paused || bgvid2.ended) && bgvid1.currentTime >= bgvid1.duration-bgvid1.duration/delay){\n      bgvid2.play()\n    }\n    x.globalCompositeOperation = \'source-over\'\n    c.width|=0\n    x.lineCap=x.lineJoin=\'butt\'\n    x.fillStyle=`hsla(${t*200},99%,50%,1)`, x.fillRect(0,0,c.width,c.height)\n    alpha1 = Math.min(1, bgvid1.currentTime/bgvid1.duration*delay * Math.min(1, (bgvid1.duration-bgvid1.currentTime)/bgvid1.duration))\n    if(alpha1>.01){\n      x.globalAlpha=alpha1\n      x.drawImage(bgvid1, 0, 0, c.width, c.height)\n    }\n    alpha2 = Math.min(1, bgvid2.currentTime/bgvid2.duration*delay * Math.min(1, (bgvid2.duration-bgvid2.currentTime)/bgvid2.duration))\n    if(alpha2>.01){\n      x.globalAlpha=alpha2\n      x.drawImage(bgvid2, 0, 0, c.width, c.height)\n    }\n    \n    if(bgvid3.ended && bgvid4.currentTime >= bgvid4.duration-bgvid4.duration/delay){\n      bgvid3.play()\n    }\n    if((bgvid4.paused || bgvid4.ended) && bgvid3.currentTime >= bgvid3.duration-bgvid3.duration/delay){\n      bgvid4.play()\n    }\n    x.globalCompositeOperation = \'difference\'\n    alpha3 = Math.min(1, bgvid3.currentTime/bgvid3.duration*delay * Math.min(1, (bgvid3.duration-bgvid3.currentTime)/bgvid3.duration))\n    if(alpha3>.01){\n      x.globalAlpha=alpha3\n      x.drawImage(bgvid3, 0, 0, c.width, c.height)\n    }\n    alpha4 = Math.min(1, bgvid4.currentTime/bgvid4.duration*delay * Math.min(1, (bgvid4.duration-bgvid4.currentTime)/bgvid4.duration))\n    if(alpha4>.01){\n      x.globalAlpha=alpha4\n      x.drawImage(bgvid4, 0, 0, c.width, c.height)\n    }\n  } else {\n    x.fillStyle=\'#0008\',x.fillRect(0,0,c.width,c.height)\n  }\n\n  x.globalCompositeOperation=\'source-over\'\n  x.globalAlpha = 1\n\n  oX=0, oY=0, oZ=20\n  Rl=C(t)*3, Pt=S(t/4)/4, Yw=t/2\n  B.map(v=>{\n    tx=v[0]\n    ty=v[1]\n    tz=v[2]\n    CB.map((q, j)=>{\n      if(!(j%4)) x.beginPath()\n      X = tx + q[0]\n      Y = ty + q[1]\n      Z = tz + q[2]\n      R(Rl,Pt,Yw,1)\n      if(Z>0)x.lineTo(...Q())\n      if(j%4==3){\n        x.closePath()\n        x.lineWidth = Math.min(40, 1+1200/Z/Z)\n        x.strokeStyle=`hsla(${170+t*200},99%,80%,${Math.max(0,.15-Math.abs(tz**2)/19999)})`\n        x.stroke()\n        x.fillStyle=`hsla(${170+t*200},99%,40%,${Math.max(0,.15-Math.abs(tz**2)/19999)})`\n        x.fill()\n      }\n    })\n  })\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true      \n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'cantelope\'s page', 1, 'cantelope', '2022-04-09 14:26:51', 7, 0, 'cantelope1', 'https://srmcgann.github.io/assets/1GY3GM.png'),
(600076, 'song = \'https://twilightparadox.com/breaking formation.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  R=(Rl,Pt,Yw,o)=>{\n    X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n    if(o)X+=oX,Y+=oY,Z+=oZ\n  }\n  Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n  Rn=Math.random\n\n  if(!t){\n    bgimg = new Image()\n    go=false\n    bgimg.addEventListener(\'load\', ()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/uJDKE.jpg\'\n    x.lineCap=x.lineJoin=\'butt\'\n    init=()=>{\n      B=[0,0,0,0,0,0]\n      for(i=6;i--;){\n        p=Math.PI*2/6*i\n        d=1\n        X=S(p)*d\n        Y=C(p)*d\n        Z=0\n        B=[...B,[X,Y,Z,0,0,0]]\n      }\n      for(i=3;i--;){\n        p=Math.PI*2/3*i+Math.PI/6\n        d=.58\n        X=S(p)*d\n        Y=C(p)*d\n        Z=.8\n        B=[...B,[X,Y,Z,0,0,0]]\n      }\n      for(i=3;i--;){\n        p=Math.PI*2/3*i+Math.PI/6\n        d=.58\n        X=S(p)*d\n        Y=C(p)*d\n        Z=-.8\n        B=[...B,[X,Y,Z,0,0,0]]\n      }\n      B=[...B,\n        ...JSON.parse(JSON.stringify(B)).map(v=>{\n          v[2]-=6\n          v[0]+=10\n          return v\n        }),\n        ...JSON.parse(JSON.stringify(B)).map(v=>{\n          v[2]+=6\n          v[0]+=10\n          return v\n        }),\n      /*\n        ...JSON.parse(JSON.stringify(B)).map(v=>{\n          v[0]-=6\n          return v\n        }),\n        ...JSON.parse(JSON.stringify(B)).map(v=>{\n          v[0]+=6\n          return v\n        }),\n        */\n        ...JSON.parse(JSON.stringify(B)).map(v=>{\n          v[1]+=6\n          v[0]+=10\n          return v\n        }),\n        ...JSON.parse(JSON.stringify(B)).map(v=>{\n          v[1]-=6\n          v[0]+=10\n          return v\n        }),\n      ]\n      P=Array(1).fill().map((v,j)=>{\n        return [-50,S(p=Math.PI*2/3*j)*.35,C(p)*.35,2,(Rn()-.5)/20,(Rn()-.5)/20]\n      })\n    }\n  }\n\n  if(!((t*60|0)%120)){\n    init()\n    Rl=0,Pt=t/2,Yw=Math.PI/6+Math.PI/1.5*Rn()\n    Rl=-.25+(Rn()-.5)*.5\n  }\n\n  if(go){\n    x.globalAlpha=.25\n    x.drawImage(bgimg,0,c.height/2-(s=bgimg.height*(c.width/bgimg.width))/2,c.width,s)\n    x.globalAlpha=1\n    x.fillStyle=\'#0003\',x.fillRect(0,0,c.width,c.height)\n  }else{\n    x.fillStyle=\'#000a\',x.fillRect(0,0,c.width,c.height)\n  }\n  iPr=2, iBr=.5\n  Pt-=.02\n  oX=0,oY=0,oZ=28+S(t*2)*12\n  \n  DC=(tx,ty,tz,r,rl,pt,yw)=>{\n    cx=X,cy=Y,cz=Z\n    for(m=18;m--;){\n      x.beginPath()\n      for(let i=10;i--;){\n        X=S(p=Math.PI*2/10*i)*r\n        Y=C(p)*r\n        Z=0\n        if(m<6){\n          R(0,0,Math.PI*2/12*m,0)\n        }else if(m<12){\n          R(0,Math.PI*2/12*m,0,0)\n        }else{\n          R(0,Math.PI*2/12*m,Math.PI/2,0)\n        }\n        R(rl,pt,yw,0)\n        X+=tx\n        Y+=ty\n        Z+=tz\n        R(Rl,Pt,Yw,1)\n        if(Z>.1)x.lineTo(...Q())\n      }\n      x.closePath()\n      x.lineWidth=1+Math.min(60, 100/Z/Z)\n      x.stroke()\n    }\n    X=cx,Y=cy,Z=cz\n  }\n\n\n  P.map(v=>{\n    X=v[0]+=v[3]\n    Y=v[1]+=v[4]\n    Z=v[2]+=v[5]\n    //R(Rl,Pt,Yw,1)\n    x.strokeStyle=\'#2cd8\'\n    DC(X,Y,Z,iPr,0,0,0)\n  })\n  B.map((v,i)=>{\n    P.map(q=>{\n      d=Math.hypot(mx=v[0]-q[0],my=v[1]-q[1],mz=v[2]-q[2])\n      if(d<iBr+iPr){\n        q[3]+=v[3]/4/iPr\n        q[4]+=v[4]/4/iPr\n        q[5]+=v[5]/4/iPr\n        q[3]-=mx/4/iPr\n        q[4]-=my/4/iPr\n        q[5]-=mz/4/iPr\n        v[3]+=q[3]/8/iBr\n        v[4]+=q[4]/8/iBr\n        v[5]+=q[5]/8/iBr\n        v[3]+=mx/8/iBr\n        v[4]+=my/8/iBr\n        v[5]+=mz/8/iBr\n      }\n    })\n    B.map((q,j)=>{\n      if(i!=j){\n        d=Math.hypot(mx=v[0]-q[0],my=v[1]-q[1],mz=v[2]-q[2])\n        if(d<iBr*1.95){\n          q[3]+=v[3]/6/iBr\n          q[4]+=v[4]/6/iBr\n          q[5]+=v[5]/6/iBr\n          q[3]-=mx/8/iBr\n          q[4]-=my/8/iBr\n          q[5]-=mz/8/iBr\n          v[3]+=mx/8/iBr\n          v[4]+=my/8/iBr\n          v[5]+=mz/8/iBr\n        }\n      }\n    })\n    X=v[0]+=v[3]\n    Y=v[1]+=v[4]\n    Z=v[2]+=v[5]\n    x.strokeStyle=\'#1f83\'\n    DC(X,Y,Z,iBr,0,0,0)\n  })\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'cantelope\'s page', 1, 'cantelope', '2022-04-09 14:26:51', 7, 0, 'cantelope1', 'https://srmcgann.github.io/assets/1GY3GM.png'),
(600077, 'song = \'https://twilightparadox.com/rufus.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  R=(Rl,Pt,Yw,o)=>{\n    X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n    if(o)X+=oX,Y+=oY,Z+=oZ\n  }\n  Q=q=>[c.width/2+X/Z*800,c.height/2+Y/Z*800]\n  Rn=Math.random\n\n  if(!t){\n    window.addEventListener(\'resize\', ()=>{\n      c.width = c.clientWidth\n      c.height = c.clientHeight\n    })\n    w=1920\n    rufus = new Image()\n    loaded=false\n    rufus.addEventListener(\'load\',()=>{\n      loaded=true\n    })\n    rufus.src = \'https://srmcgann.github.io/assets/e5Jhv.png\'\n    bgimg = new Image()\n    bgloaded=false\n    bgimg.addEventListener(\'load\',()=>{\n      bgloaded=true\n    })\n    bgimg.src = \'https://srmcgann.github.io/assets/1Hyqt6.jpg\'\n    drawRotatedImage=(img,X,Y,w,h,a)=>{\n      x.save()\n      x.translate(X,Y)\n      x.rotate(a)\n      x.drawImage(img,-w/2,-h/2,w,h)\n      x.restore()\n    }\n    G=30\n    B=Array(w).fill().map((v,j)=>{\n      X = (Rn()-.5)*G\n      Y = (Rn()-.5)*G/1.77777778\n      Z = Rn()*G/1.5\n      return [X,Y,Z,j]\n    })\n  }\n  \n  Rl=0,Pt=0,Yw=0\n  oX=0,oY=0,oZ=.01\n  \n  if(bgloaded){\n    x.globalAlpha=.4\n    x.drawImage(bgimg,0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#0002\',x.fillRect(0,0,c.width,c.height)\n  }else{\n    x.fillStyle=\'#0008\',x.fillRect(0,0,c.width,c.height)\n  }\n  if(loaded){\n    B=B.map(v=>{\n      Z=v[2]-=.04\n      if(v[2]<0)v[2]+=G/1.5\n      return v\n    })\n    let tmp = JSON.parse(JSON.stringify(B)).sort((a,b)=>b[2]-a[2])\n    tmp.map(v=>{\n      X=v[0]\n      Y=v[1]\n      Z=v[2]\n      R(Rl,Pt,Yw,1)\n      s=.5/Z\n      x.globalAlpha = 1/(1+Z**4/2000)\n      drawRotatedImage(rufus,...Q(),rufus.width*s,rufus.height*s,(t*2+v[3])*S(v[3])*(v[3]%2?-1:1))\n    })\n  }\n  x.globalAlpha=1\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'rufus inception', 1, 'cantelope', '2022-04-09 14:26:51', 29, 0, 'cantelope1', 'https://srmcgann.github.io/assets/1GY3GM.png'),
(600080, 'song = \'https://twilightparadox.com/epiphany.mp3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\ncanvas2=c.cloneNode()\nx2=canvas2.getContext(\'2d\')\nS=Math.sin\nC=Math.cos\nt=0\n\nDraw=()=>{\n\n  if(!t){\n    c.width=c.clientWidth/2,c.height=c.clientHeight/2\n    R=(Rl,Pt,Yw,o)=>{\n      X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d\n      if(o)X+=oX,Y+=oY,Z+=oZ\n    }\n    Rn=Math.random\n    Q=q=>[c.width/2+X/Z*400,c.height/2+Y/Z*400]\n  }\n\n  oX=0,oY=0,oZ=12+C(t)*4\n  Rl=-C(t/2)/4,Pt=-C(t/1.5)/3-1,Yw=S(t/1.5)*1.05\n\n  if(!t){\n    go=false\n    bgimg=new Image()\n    bgimg.addEventListener(\'load\',()=>{\n      go=true\n    })\n    bgimg.src=\'https://srmcgann.github.io/assets/MlBFm.jpg\'\n  }\n\n  if(go){\n    x.globalAlpha=.075\n    x.drawImage(bgimg, 0,0,c.width,c.height)\n    x.globalAlpha=1\n    x.fillStyle=\'#1013\', x.fillRect(0,0,w=c.width,w)\n  }else{\n    x.fillStyle=\'#1026\', x.fillRect(0,0,w=c.width,w)\n  }\n  \n  if(playing){\n    B = new Uint8Array(bufferLength)\n    analyser.getByteFrequencyData(B)\n    amp=0\n    B.map((v,i)=>amp+=v*5**4)\n    amp/=550000\n  } else {\n    trim=0\n    B=Array(128).fill(1)\n  }\n\n  rw=50, col=50, sp=9\n  for(m=2;m--;){\n    for(i=rw*col;i--;){\n      x.beginPath()\n      j=i+1\n      if(m){\n        X=((j%rw)/rw-.5)*sp\n        Z=((j/rw|0)/col-.5)*sp\n      }else{\n        Z=((j%rw)/rw-.5)*sp\n        X=((j/rw|0)/col-.5)*sp\n      }\n      l=Math.hypot(X,Z)/(Math.hypot(rw,col))*1024|0\n      d1=-(.75+S(Math.hypot(X,Z)*(3+S(t)*2)-t*10)/4)-B[l]/256*(1+l**.5)/2+.75+(l<2?-.6:0)\n      ty=Y=d1*2\n      X*=2\n      Z*=2\n      R(Rl,Pt,Yw,1)\n      if(Z>0)x.lineTo(...Q())\n      j=i+rw+1\n      if(i<rw*col-rw){\n        if(m){\n          X=((j%rw)/rw-.5)*sp\n          Z=((j/rw|0)/col-.5)*sp\n        }else{\n          Z=((j%rw)/rw-.5)*sp\n          X=((j/rw|0)/col-.5)*sp\n        }\n        l=Math.hypot(X,Z)/(Math.hypot(rw,col))*1024|0\n        d=-(.75+S(Math.hypot(X,Z)*(3+S(t)*2)-t*10)/4)-B[l]/256*(1+l**.5)/2+.75+(l<2?-.6:0)\n        Y=d*2\n        X*=2\n        Z*=2\n        R(Rl,Pt,Yw,1)\n        if(Z>0)x.lineTo(...Q())\n      }\n      x.lineWidth=1\n      x.strokeStyle=`hsla(${d1*200-t*300},99%,${70-Math.min(40,Math.abs(d1*25))+(1-ty)**4/3.5}%,${.1-d1/1.5})`\n      x.stroke()\n    }\n  }\n\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      mp3.play()\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', 'body,html{\n  height: 100vh;\n  margin: 0;\n  background: linear-gradient(45deg, #000, #123)\n}\ncanvas{\n  width:100%;\n  height: 100%;\n}', '<canvas id=c>', 'cantelope\'s page', 1, 'cantelope', '2022-04-09 14:26:51', 5, 0, 'cantelope1', 'https://srmcgann.github.io/assets/1GY3GM.png'),
(600081, 'el = document.querySelector(\'#sel\')\nresult = document.querySelector(\'#result\')\n\nel.addEventListener(\'change\', e => {\n  result.innerHTML=e.srcElement.value\n})', 'html,body{\n  background: linear-gradient(-45deg, #024, #000);\n  margin: 0;\n  font-family: arial, tahoma;\n  font-size: 24px;\n  color: #ff0;\n  min-height: 100%;\n  overflow: hidden;\n}\n#main{\n  padding-top: 100px;\n  padding-bottom: 100px;\n  text-align: center;\n}\n#sel{\n  display: block;\n  position: relative;\n  margin-left: auto;\n  margin-right: auto;\n}', '<div id=\"main\">\n  <select id=\"sel\">\n    <option value=\"one\">1</option>\n    <option value=\"two\">2</option>\n  </select>\n  <div id=\"result\">\n    select a value\n  </div>\n</div>', 'onchange', 145, 'whitehot robot', '2022-04-09 14:26:51', 9, 0, 'whitehotrobot2l', 'https://srmcgann.github.io/assets/1GY3GM.png'),
(600082, 'var c = document.querySelector(\'#c\')\nc.width = 1e3\nc.height = 1e3\nvar x = c.getContext(\'2d\')\nvar S = Math.sin\nvar C = Math.cos\nvar t=0, oX=0, oY=0, oZ=12\n\nvar R=(Rl,Pt,Yw,o)=>{\n  X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=(H=M.hypot)(X,Y))\n  Y=C(p)*d\n  Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z))\n  Z=C(p)*d\n  X=S(p=A(X,Z)+Yw)*(d=H(X,Z))\n  Z=C(p)*d\n  if(o)X+=oX,Y+=oY,Z+=oZ\n}\n\nvar Q=()=>[c.width/2+X/Z*600,c.height/2+Y/Z*600]\n\n\nDraw = () => {\n\n  x.globalAlpha=.5\n  x.clearRect(0,0,w=c.width,w)\n\n  Rl=-t*1.5\n  Pt=0\n  Yw=S(t/2)*4\n\n  let P=Array(6).fill().map((v,i)=>{\n    X=S(p=Math.PI*2/6*i+Math.PI/6)\n    Y=C(p)\n    Z=0\n    return [X,Y,Z]\n  })\n  let ls=1.6\n  let B=Array(6).fill().map((v,i)=>{\n    let q=Math.PI*2/6*i-t*8\n    s=ls*(1+(1+S(q)/2)*(1+S(t*1.5))/3)\n    X=S(p=Math.PI*2/6*i)*s\n    Y=C(p)*s\n    Z=0\n    return [X,Y,Z,[...P]]\n  })\n  B=[...B,[0,0,0,[...P]]]\n\n  x.lineJoin=x.lineCap=\'round\'\n\n  B.map(v=>{\n    tx=v[0]\n    ty=v[1]\n    tz=v[2]\n    x.beginPath()\n    v[3].map(q=>{\n      X=tx+q[0]\n      Y=ty+q[1]\n      Z=tz+q[2]\n      R(Rl,Pt,Yw,1)\n      x.lineTo(...Q())\n    })\n\n    x.closePath()\n    x.lineWidth=140/Z\n    x.strokeStyle=\'#4bc8\'\n    x.fillStyle=\'#2cf8\'\n    x.fill()\n    x.stroke()\n  })\n\n  this.t += 1/60\n  requestAnimationFrame(Draw)\n}\n\nDraw()', 'html,body{\n  background: linear-gradient(-45deg, #024, #000);\n  margin: 0;\n  font-family: arial, tahoma;\n  font-size: 24px;\n  color: #ff0;\n  min-height: 100%;\n  overflow: hidden;\n}\n#c{\n  width: 800px;\n  height: 800px;\n}\n.demoPageText{\n  text-align: center;\n  position: absolute;\n  top: 50%;\n  transform: translatey(-50%);\n  text-shadow: 2px 2px 2px #000;\n}\n.mainInner{\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: space-evenly;\n}\n.main{\n  position: absolute;\n  width: 700px;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n}', '<div class=\"main\">\n  <div class=\"mainInner\">\n    <div class=\"demoPageText\">\n      <span style=\"font-size: 1.5em;\">\n        cantelope42\'s page\n      </span><br><hr>\n      this is a sample page<br>\n      edit the code to customize it!<br><br>\n      the changes you make<br>\n      are effective immediately!<br>\n      ...so use care!\n    </div>\n    <canvas id=c></canvas>\n  </div>\n</div>', 'cantelope42\'s page', 148, 'cantelope42', '2022-04-09 14:26:51', 3, 0, 'cantelope422o', 'https://srmcgann.github.io/assets/1GY3GM.png'),
(600084, 'song = \'https://audiocloud.whitehotrobot.com/audio/9f1b261a1a6530b71e70b03c09c3d013.MP3\'\nvid = \'\'\nrecordingStarted=playing=vidplaying=analyzerSetup=0\n\nfftSize = 64\n\nc=document.querySelector(\'#c\')\nx=c.getContext(\'2d\')\nc.width=c.clientWidth\nc.height=c.clientHeight\nS=Math.sin\nC=Math.cos\nt=0\n\ndocument.querySelector(\'#launchButton\').addEventListener(\'click\',()=>{\n  document.querySelector(\'#launchButton\').style.display=\'none\'\n  launch=1\n})\n\nwindow.onresize=()=>{\n  c.width=c.clientWidth\n  c.height=c.clientHeight\n  t=0\n}\nbgimg = new Image()\nbgimg.addEventListener(\'load\',()=>{\n  go=true\n})\nbgimg.src=\'https://srmcgann.github.io/assets/12ddK3.jpg\'\ngo=playing=launch=false\n\nDraw=()=>{\n\n  isd=4\n  if(!t){\n    Rn=Math.random\n    R=(Rl,Pt,Yw,o)=>{X=S(p=(A=(M=Math).atan2)(X,Y)+Rl)*(d=H(X,Y)),Y=C(p)*d,Y=S(p=A(Y,Z)+Pt)*(d=H(Y,Z)),Z=C(p)*d,X=S(p=A(X,Z)+Yw)*(d=H(X,Z)),Z=C(p)*d;if(o)X+=oX,Y+=oY,Z+=oZ}\n    Q=q=>[c.width/2+X/Z*1e3,c.height/2+Y/Z*1e3]\n    iPc=10,G=Math.max(20, 32/(1+1920/c.width)),iPTv=8,iPs=800\n    PT=[]\n    P=Array(iPc).fill().map(v=>{\n      switch(Rn()*4|0){\n        case 0: sd = 4; break\n        case 1: sd = 6; break\n        case 2: sd = 12; break\n        case 3: sd = 14; break\n      }\n      B=Array(sd).fill().map(v=>[(O=Math.random)(),O(),O()])\n      L=q=>q*99**3/d,n=0\n      for(m=500/(1+sd/9)|0;m--;){\n        B.map((v,i)=>{\n          f=g=h=0,B.map(q=>{d=(1+(H=Math.hypot)(a=v[0]-q[0],b=v[1]-q[1],e=v[2]-q[2])*9)**3,f+=L(a),g+=L(b),h+=L(e)}),d=H(v[0]+=f,v[1]+=g,v[2]+=h),v[0]*=1/d,v[1]*=1/d,v[2]*=1/d\n        })\n      }\n      n=6e6\n      B.map(v=>{\n        B.map(q=>{\n          if((d=H(q[0]-v[0],q[1]-v[1],q[2]-v[2]))&&d<n) n=d\n        })\n      })\n      X=(Rn()-.5)*G\n      Y=(Rn()-.5)*G\n      Z=(Rn()-.5)*G\n      return [ X, Y, Z, B, 0, n, sd]\n    })\n  }\n  if(go){\n    x.globalAlpha=.3\n    if(c.width/bgimg.width>c.height/bgimg.height){\n      s=c.width/bgimg.width\n    }else{\n      s=c.height/bgimg.height\n    }\n    x.drawImage(bgimg,c.width/2-bgimg.width/2*s,c.height/2-bgimg.height/2*s,bgimg.width*s,bgimg.height*s)\n    x.globalAlpha=1\n    x.fillStyle=\'#0011\',x.fillRect(0,0,c.width,c.height)\n    if(launch){\n      if(!playing)mp3.play(),playing=true\n      Rl=t/8,Pt=-t/6,Yw=S(t/10)*2\n      oX=0,oY=0,oZ=G\n      x.lineCap=\'round\'\n      P.map((e,o)=>{\n        Rl1=t/2.5,Pt1=-C(t/2+o/3)*2.5,Yw1=S(t+o)*2.5\n        tx=e[0]\n        ty=e[1]\n        tz=e[2]\n        B=e[3]\n        B.map((v,i)=>{\n          X=v[0]\n          Y=v[1]\n          Z=v[2]\n          R(Rl1,Pt1,Yw1)\n          X+=tx\n          Y+=ty\n          Z+=tz\n          PT=[...PT, [X,Y,Z,(X-tx)/99*iPTv,(Y-ty)/99*iPTv,(Z-tz)/99*iPTv,1,o,0]]\n          B.map((q,j)=>{\n            if(j>i){\n              d=H(q[0]-v[0],q[1]-v[1],q[2]-v[2])\n              if(d<e[5]*1.22+e[6]**2/2e5){\n                x.beginPath()\n                X=v[0]\n                Y=v[1]\n                Z=v[2]\n                R(Rl1,Pt1,Yw1)\n                X+=tx\n                Y+=ty\n                Z+=tz\n                R(Rl,Pt,Yw,1)\n                if(Z>0) x.lineTo(...Q())\n                k=Z+4\n                X=q[0]\n                Y=q[1]\n                Z=q[2]\n                R(Rl1,Pt1,Yw1)\n                X+=tx\n                Y+=ty\n                Z+=tz\n                R(Rl,Pt,Yw,1)\n                if(Z>0) x.lineTo(...Q())\n                x.globalAlpha=99/Z\n                x.strokeStyle=\'#fffa\'\n                x.lineWidth=1+Math.min(30,40/Z)\n                x.stroke()\n                x.strokeStyle=`hsla(${t*199+360/P.length*o},99%,50%,.1)`\n                x.lineWidth=Math.min(30,500/Z)\n                x.stroke()\n              }\n            }\n          })\n        })\n      })\n\n      PT=PT.map(v=>{\n        X=v[0]+=v[3]\n        Y=v[1]+=v[4]\n        Z=v[2]+=v[5]\n        R(Rl,Pt,Yw,1)\n        v[6]/=1.1\n        v[8]++\n        if(Z>0){\n          l=Q()\n          s=iPs*v[6]/Z/1\n          x.fillStyle=`hsla(${t*199+360/P.length*v[7]-v[8]*10},99%,${Math.max(50,100-v[8]*6)}%,.1)`\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n          s=iPs*v[6]/Z/3\n          x.fillStyle=`#fff8`\n          x.fillRect(l[0]-s/2,l[1]-s/2,s,s)\n        }\n        return v\n      }).filter(v=>v[6]>.15)\n    }\n  }else{\n    x.fillStyle=\'1031\',x.fillRect(0,0,c.width,c.height)\n  }\n  t+=1/60\n  requestAnimationFrame(Draw)\n}\n\nsetupAnalyzerAndContent = () => {\n  analyzerSetup=1\n  loaded=0\n  mp3 = new Audio()\n  mp3.crossOrigin = \"anonymous\"\n  mp3.src = song\n  mp3.loop = true\n  if(!mp3)loaded=1\n  mp3.addEventListener(\'canplay\',()=>{\n    if(!playing){\n      loaded=1//playing=1\n      audioCtx = new (window.AudioContext || window.webkitAudioContext)()\n      analyser = audioCtx.createAnalyser()\n      source = audioCtx.createMediaElementSource(mp3)\n      source.connect(analyser)\n      analyser.connect(audioCtx.destination)\n      analyser.fftSize=fftSize\n      trim=analyser.fftSize*.25\n      bufferLength = analyser.frequencyBinCount\n      mp3.loop=true\n      Draw()\n      if(vid){\n        bgvid = document.createElement(\'video\')\n        bgvid.src = vid\n        bgvid.addEventListener(\'canplay\',()=>{\n          if(!vidplaying){\n            vidplaying=1\n            bgvid.loop=true\n            bgvid.muted=true\n            bgvid.play()\n          }\n        })\n      }\n    }\n  })\n}\n\nsetupAnalyzerAndContent()', '@import url(\'https://fonts.googleapis.com/css2?family=Play&display=swap\');\nhtml,body{\n  background: linear-gradient(-45deg, #024, #000);\n  margin: 0;\n  font-family: arial, tahoma;\n  font-size: 24px;\n  color: #0f4;\n  min-height: 100%;\n  overflow: hidden;\n}\n.hidden{\n  display: none;\n}\nbutton:focus{\n  outline: none;\n}\n.sized{\n  display: inline-block;\n  transform: scale(1.2,.5);\n  color: #0f8;\n  font-style: normal;\n}\n\n#launchButton{\n  box-shadow: 0px 0px 40px 50px #104;\n  cursor: pointer;\n  position: absolute;\n  padding: 5px;\n  font-style: oblique;\n  padding-top: 0px;\n  left: 50%;\n  text-shadow: 1px 1px 3px #48f;\n  top: 50%;\n  transform: translate(-50%,-50%) scale(1.5,1.25);\n  width: 175px;\n  background: #104;\n  border: none;\n  border-radius: 10px;\n  font-family: \'Play\';\n  color: #f06;\n  font-weight: 900;\n  line-height: .65em;\n  font-size: 36px;\n}\n#c{\n  width: 100vw;\n  height: 100vh;\n}', '<button id=\"launchButton\">\n  <div class=\"sized\">\n    visit the\n  </div>\n  cherubim\n</button>\n<canvas id=\"c\">', 'visit the cherubim', 145, 'whitehot robot', '2022-04-09 14:26:51', 24, 0, 'whitehotrobot2l', 'https://srmcgann.github.io/assets/1CzsSA.png'),
